\bigg|\int_{0}^{\infty}\frac{r^{\frac{7\alpha}{4}-1}}{i^{\alpha} r^{2\alpha}
- 2r^\alpha \cos(\alpha \pi) + {(-i)}^{\alpha}}dr\bigg|\\
&\lesssim T^{\frac{3\alpha-2}{4}}\left\|f\right\|_{L^{2}_{T,x}},
\end{align*}
where we use $\sup_{x\in\mathbb{R}^{+}}|x|^{\eta}e^{-|x|^{\delta}}<\infty$ for any $\eta>0$. The proof is completed now.
\end{proof}
