To use the embedding properties of non-homogeneous Sobolev spaces, we must prove the following estimates:
\begin{lemma}
Let $\delta>1$, $\beta<2$, $2\beta>\delta+1$, d=1, $\gamma=\frac{\delta-1}{2}$, $\nu=\beta-\frac{\delta+1}{2}$, the following estimates hold:
\begin{align}
\label{smoothing 12}\left\|e^{-itD^{\delta}}f\right\|_{L^{\infty}_{x}L^{2}_{T}}&\lesssim\left(T^{\frac{1}{2}}+1\right) \|f\|_{L^{2}_{x}},\\\label{smoothing 13}
\left\|\int_{0}^{\infty}
\frac{e^{-rtD^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}} \, drf(\cdot)\right\|_{L^{\infty}_{x}L^{2}_{T}}&\lesssim\left(T^{\frac{\gamma-\gamma'}{\delta}}+T^{\frac{1}{2}}\right) \|f\|_{L^{2}_{x}}, 0<\gamma'<\gamma,\\\label{smoothing 14}
\left\|\int_{0}^{t} D^{\delta-\beta} e^{-i(t-s)D^\delta} f(s,\cdot) \, ds\right\|_{L^\infty_x L^2_t} &\lesssim\left(T^{\frac{1}{2}}+1\right)T^{\frac{1}{2}} \|f\|_{L^{2}_{x,T}},\\\label{smoothing 15}
\left\|\int_{0}^{t}\int_{0}^{\infty} \frac{D^{\delta-\beta} e^{-r(t-s)D^{\delta}} r^\alpha}{i^{\alpha} r^{2\alpha}
- 2r^\alpha \cos(\alpha \pi) + {(-i)}^{\alpha}} \, drf(s,\cdot)ds\right\|_{L^{\infty}_{x}L^{2}_{T}}&\lesssim\left(T^{\frac{\nu}{\delta}}+T^{\frac{\nu-\nu'}{\delta}}\right)T^{\frac{1}{2}}
\left\|f\right\|_{L^{2}_{x,T}}.
