\end{lemma}

\begin{proof}
We choose $\widehat{\chi}\in C^{\infty}_{c}(\mathbb{R})$, hence we have $f=\chi f+\left(1-\chi\right)f$. We derive that
\begin{align*}
\left\|e^{-itD^{\delta}}f\right\|_{L^{\infty}_{x}L^{2}_{T}}&\lesssim\left\|e^{-itD^{\delta}}\left(\chi f+\left(1-\chi\right)f\right)\right\|_{L^{\infty}_{x}L^{2}_{T}}\\
&\lesssim\left\|e^{-itD^{\delta}}\chi f\right\|_{L^{\infty}_{x}L^{2}_{T}}+\left\|e^{-itD^{\delta}}(1-\chi)f\right\|_{L^{\infty}_{x}L^{2}_{T}}\\
&\lesssim\left\|e^{-it|\xi|^{\delta}}\widehat{\chi} \widehat{f}\right\|_{L^{2}_{T}L^{1}_{\xi}}+ \left\|D^{\frac{\delta-1}{2}}e^{-itD^{\delta}}D^{-\frac{\delta-1}{2}}\left(1-\chi\right)f\right\|_{L^{\infty}_{x}L^{2}_{T}}\\
&\lesssim T^{\frac{1}{2}}\left\|f\right\|_{L^{2}_{x}}+\left\|D^{-\frac{\delta-1}{2}}\left(1-\chi\right)f\right\|_{L^{2}_{x}}\\
&\lesssim\left(T^{\frac{1}{2}}+1\right) \|f\|_{L^{2}_{x}},
\end{align*}
where we use the Hausdorff-Young inequality, H\"{o}lder inequality, Plancherel identity the smoothing effect \eqref{smoothing 1}, and the symbol $|\xi|^{-\delta+1}\widehat{\chi}^{c}$ is a $L^{2}$ H\"{o}rmander multiplier, can refer to \cite{Triebel}. The estimate \eqref{smoothing 14} is identical and we omit the details.

Moreover, we have that
\begin{align*}
&\left\|\int_{0}^{\infty}
\frac{e^{-rtD^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}} \, drf(x)\right\|_{L^{\infty}_{x}L^{2}_{T}}\\
&\lesssim\left\|\int_{0}^{\infty}
\frac{e^{-rt|\xi|^{\delta}}\widehat{\chi}(\xi) \widehat{f}(\xi)r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}} \, dr\right\|_{L^{2}_{T}L^{1}_{\xi}}\\
&\qquad+\left\|D^{\gamma'}\int_{0}^{\infty}
\frac{e^{-rtD^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}} \, drD^{-\gamma'}(1-\chi)f(x)\right\|_{L^{\infty}_{x}L^{2}_{T}}\\
&\lesssim \left(T^{\frac{\gamma-\gamma'}{\delta}}+T^{\frac{1}{2}}\right) \|f\|_{L^{2}_{x}},
\end{align*}
and
\begin{align*}
&\left\|\int_{0}^{t}\int_{0}^{\infty} \frac{D^{\delta-\beta} e^{-r(t-s)D^{\delta}} r^\alpha}{i^{\alpha} r^{2\alpha}
- 2r^\alpha \cos(\alpha \pi) + {(-i)}^{\alpha}} \, drf(s,\cdot)ds\right\|_{L^{\infty}_{x}L^{2}_{T}}\\
&\lesssim\left\|\int_{0}^{t}\int_{0}^{\infty} \frac{D^{\delta-\beta} e^{-r(t-s)D^{\delta}}\chi f(s,\cdot) r^\alpha}{i^{\alpha} r^{2\alpha}
- 2r^\alpha \cos(\alpha \pi) + {(-i)}^{\alpha}} \, drds\right\|_{L^{2}_{T}L^{\infty}_{x}}\\
&\quad +\left\|D^{\nu}\int_{0}^{t}\int_{0}^{\infty} \frac{D^{\delta-\beta} e^{-r(t-s)D^{\delta}} r^\alpha}{i^{\alpha} r^{2\alpha}
- 2r^\alpha \cos(\alpha \pi) + {(-i)}^{\alpha}} \, drD^{-\nu}\left(1-\chi\right) f(s,\cdot)ds\right\|_{L^{\infty}_{x}L^{2}_{T}}\\
&\lesssim\left\|\int_{0}^{t}\int_{0}^{\infty}\frac{r^{\alpha-\frac{\delta-\beta}{\delta}-\frac{1}{2\delta}}
(t-s)^{-\frac{\delta-\beta}{\delta}-\frac{1}{2\delta}}
\left\|f(s,\cdot)\right\|_{L^{2}_{x}}}{i^{\alpha} r^{2\alpha}
- 2r^\alpha \cos(\alpha \pi) + {(-i)}^{\alpha}}drds\right\|_{L^{2}_{T}}+T^{\frac{\nu-\nu'}{\delta}}\left\|D^{-\nu'}\left(1-\chi\right) f(s,\cdot)\right\|_{L^{1}_{T}L^{2}_{x}}\\
&\lesssim \left(T^{\frac{\nu}{\delta}}+T^{\frac{\nu-\nu'}{\delta}}\right)\left\|f\right\|_{L^{1}_{T}L^{2}_{x}}
\end{align*}
where we use the smoothing estimate \eqref{smoothing 10}, \eqref{smoothing 11}, the H\"{o}rmander multiplier theory, and the integral
$$
