Next, we need the following $L^{p}_{x}L^{\infty}_{T}$ estimates.
\begin{lemma}\label{maximum function estimate}
Let $d=1$, $\delta>1$, $\frac{1}{2}<\alpha<1$, $\beta<2$, $\frac{1}{4}\leq s<\frac{1}{2}$, $\frac{1}{p_{s}}=\frac{1}{2}-s$, then we have the following estimates:
\begin{align}
\label{smoothing 16}
\left\|e^{-itD^{\delta}}f\right\|_{L^{p_{s}}_{x}L^{\infty}_{t}}&\lesssim\left\|D^{s}f\right\|_{L^{2}_{x}},\\\label{smoothing 17}
\left\|\int_{0}^{\infty}
\frac{e^{-rtD^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}} \, drf(\cdot)\right\|_{L^{p_{s}}_{x}L^{\infty}_{t}}&\lesssim\left\|D^{s}f\right\|_{L^{2}_{x}},\\\label{smoothing 18}
\left\|\int_{0}^{t} D^{\delta-\beta} e^{-i(t-s)D^\delta} f(s,\cdot) \, ds\right\|_{L^{p_{s}}_{x}L^{\infty}_{T}}&\lesssim T^{\frac{1}{2}}\left\|D^{\delta-\beta+s}f\right\|_{L^{2}_{T,x}},\\\label{smoothing 19}
\left\|\int_{0}^{t}\int_{0}^{\infty} \frac{D^{\delta-\beta} e^{-r(t-\tau)D^{\delta}} r^\alpha}{i^{\alpha} r^{2\alpha}
- 2r^\alpha \cos(\alpha \pi) + {(-i)}^{\alpha}} \, drf(\tau,\cdot)d\tau\right\|_{L^{p_{s}}_{x}L^{\infty}_{T}}&\lesssim T^{\alpha-\frac{1}{2}}\left\|D^{s}f\right\|_{L^{2}_{T,x}}
\end{align}
\end{lemma}
\begin{proof}

The proof of \eqref{smoothing 16} follows Kenig \cite{Kenig}. We define the following integral
\begin{align}\label{Kenig integral}
I^{t}_{\vartheta}=\int_{\mathbb{R}}e^{i\left(t|\xi|^{\delta}+x\xi\right)}\frac{d\xi}{|\xi|^{\vartheta}},\quad
\frac{1}{2}\leq\vartheta<1.
\end{align}
Kenig \cite{Kenig} proved that for $\delta=3$, $\left|I^{t}_{\vartheta}\right|\lesssim \left|x\right|^{\vartheta-1}$. Indeed, we can claim for any $\delta>1$, $\left|I^{t}_{\vartheta}\right|\lesssim \left|x\right|^{\vartheta-1}$.

Indeed, for $t=0$, the conclusion is obvious, see \cite{Grafakos}. For $t\neq 0$, by the scaling transform, we only need to verify the case $t=1$. Let us denote the following regions:
\begin{align*}
\Omega_{1}&=\left\{\xi\in\mathbb{R}:|\xi|\lesssim\max\{2,|x|^{-1}\}\right\},\\
\Omega_{2}&=\left\{\xi\in\Omega_{1}^{c}:\left|\delta|\xi|^{\delta-1}+x\right|\leq\frac{1}{\delta-1}|x|\right\},\\
\Omega_{3}&=\mathbb{R}\setminus\left(\Omega_{1}\cup\Omega_{2}\right).
\end{align*}
Thus, we can write $I^{1}_{\vartheta}$ as
$$
I^{1}_{\vartheta}=\sum_{j=1}^{3}\int_{\Omega_{j}}e^{i\left(|\xi|^{\delta}+x\xi\right)}\frac{d\xi}{|\xi|^{\vartheta}}
=\sum_{j=1}^{3}I_{\vartheta,j}^{1}.
$$
First, $\left|I_{\vartheta,1}^{1}\right|\lesssim \left|x\right|^{\vartheta-1}$ is obvious. If $\xi\in\Omega_{2}$, there exist constants $c_{1}, c_{2}$ such that $c_{1}\left|x\right|\leq \left|\xi\right|^{\delta-1}\leq c_{2} \left|x\right|$, hence by the
Lemma \ref{Van der Corput lemma}, we have that
\begin{align*}
\left|\int_{\Omega_{2}}e^{i\left(|\xi|^{\delta}+x\xi\right)}\frac{d\xi}{|\xi|^{\vartheta}}\right|&\lesssim \left(\left|\xi\right|^{\delta-2}\right)^{-\frac{1}{2}}
\left(\left\||\xi|^{-\vartheta}\chi_{|\xi|^{\delta-1}\sim|x|}(\cdot)\right\|_{\infty}
+\left\||\xi|^{-\vartheta-1}\chi_{|\xi|^{\delta-1}\sim|x|}(\cdot)\right\|_{1}\right)\\
&\lesssim \left|x\right|^{\vartheta-1}.
\end{align*}
If $\xi\in\Omega_{3}$, then we get $\left||\xi|^{\delta-1}+x\right|\gtrsim \left||\xi|^{\delta-1}+|x|\right|$, hence by integration by parts, we estimate that
\begin{align*}
\left|\int_{\Omega_{3}}e^{i\left(|\xi|^{\delta}+x\xi\right)}\frac{d\xi}{|\xi|^{\vartheta}}\right|&=
\left|\int_{\Omega_{3}}e^{i\left(|\xi|^{\delta}+x\xi\right)}\frac{d}{d\xi}
\left(\frac{1}{\delta|\xi|^{\delta-1}+x}\frac{1}{|\xi|^{\vartheta}}\right)d\xi\right|\\
&\lesssim\left|\int_{\Omega_{3}}e^{i\left(|\xi|^{\delta}+x\xi\right)}
\left(\frac{|\xi|^{\delta-1}}{\left(\delta|\xi|^{\delta-1}+x\right)^{2}}\frac{1}{|\xi|^{\vartheta+1}}
+\frac{1}{\delta|\xi|^{\delta-1}+x}\frac{1}{|\xi|^{\vartheta+1}}\right)d\xi\right|\\
&\lesssim\left|x\right|^{\vartheta-1}.
\end{align*}
Moreover, by the standard dual method, \eqref{smoothing 16} is equivalent to the following estimate
\begin{align}\label{dual integral}
A = \left\| \int_{\mathbb{R}} D^{-s} e^{itD^{\delta}} f(t, \cdot) dt \right\|_{L^2_x} \lesssim \left\| f \right\|_{L^{p_{s}'}_x L^1_t}.
\end{align}
In fact,
\begin{align*}
A^2 &= \int_{\mathbb{R}} \left( \int_{\mathbb{R}} D^{-s} e^{itD^{\delta}} f(t,x) dt \right) \overline{\left( \int_{\mathbb{R}} D^{-s} e^{it'D^{\delta}} f(t',x) dt' \right)} dx \\
&= \int_{\mathbb{R}} \int_{\mathbb{R}} \left( \int_{\mathbb{R}} D^{-2s} e^{i(t-t')D^{\delta}} \overline{f(t',x)} dt' \right) f(t,x) dt dx \\
&\lesssim \left\| \int_{\mathbb{R}} D^{-2s} e^{i(t-t')D^{\delta}} f(t',x) dt' \right\|_{L^{p_{s}}_x L^\infty_t} \left\| f \right\|_{L^{p_{s}'}_x L^1_t} \\
&\lesssim \left\| \frac{1}{|x|^{1-2s}} \star \int_{\mathbb{R}} f(t', \cdot) dt' \right\|_{L^{p_{s}}_x} \left\| f \right\|_{L^{p_{s}'}_x L^1_t} \\
&\lesssim \left\| f \right\|_{L^{p_{s}'}_x L^1_t}^2,
\end{align*}
where we use the Hardy-Littlewood inequality, hence implying \eqref{smoothing 16}. Additionally, noting that $e^{itD^{\delta}}$ is an unity operator and by Minkowski inequality, we get
\begin{align*}
\left\| \int_{0}^{t} D^{\delta-\beta} e^{-i(t-s)D^\delta} f(s, \cdot) ds \right\|_{L^{p_{s}}_x L^\infty_T} &\lesssim \int_{0}^{T} \left\| D^{\delta-\beta+s} e^{isD^{\delta}} \chi_{(0,t)}(s) f(s, \cdot) \right\|_{L^2_x} ds \\
&\lesssim T^{\frac{1}{2}} \left\| D^{\delta-\beta+s} f \right\|_{L^2_{T,x}},
\end{align*}
hence, this implies that \eqref{smoothing 18}.

Next we prove the estimate \eqref{smoothing 17}. By Hardy-Littlewood inequality, \eqref{smoothing 17} is equivalent to verify
\begin{align}\label{heat estimate 1}
\left|\int_{\mathbb{R}}\int_{0}^{\infty}
\frac{|\xi|^{-s}e^{-rt|\xi|^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}\, drd\xi\right|\lesssim \left|x\right|^{s-1}.
\end{align}
By scailing transform, we only prove \eqref{heat estimate 1} for $t=1$.

For $x$ is small ($|x|< 1$), we estimate
\begin{align*}
&\left|\int_{\mathbb{R}}\int_{0}^{\infty}
\frac{|\xi|^{-s}e^{-r|\xi|^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}\, drd\xi\right|\\
&\leq\left|\int_{\left|\xi\right|\leq 1}\int_{0}^{\infty}
\frac{|\xi|^{-s}e^{-r|\xi|^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}\, drd\xi\right| +\left|\int_{\left|\xi\right|\geq 1}\int_{0}^{\infty}
\frac{|\xi|^{-s}e^{-r|\xi|^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}\, drd\xi\right|\\
&\lesssim\left|\int_{|\xi|\leq 1}|\xi|^{-s}d\xi\right|+\left|\int_{|\xi|\geq 1}\int_{0}^{\infty}\frac{r^{\alpha-\frac{3}{4\delta}-1}}{i^{\alpha}r^{2\alpha}-2r^{\alpha}\cos(\alpha\pi)+(-i)^{\alpha}}dr|\xi|^{-s-\frac{3}{4}}
\sup_{(r,\xi)\in\mathbb{R}^{+}\times\mathbb{R}}\big(|r^{\frac{1}{\delta}}
\xi|^{\frac{3}{4}}e^{-|r^{\frac{1}{\delta}}\xi|^{\delta}}\big)d\xi\right|\\
&\lesssim\left|\int_{|\xi|\leq 1}|\xi|^{-s}d\xi\right|+\left|\int_{|\xi|\geq 1}|\xi|^{-s-\frac{3}{4}}d\xi\right|\\
&\lesssim 1\lesssim \left|x\right|^{s-1}.
\end{align*}
Furthermore, for $|x|>1$, note that $\sup_{x\in\mathbb{R}^{+}}x^{\eta}e^{-x}<\infty$ for any $\eta>0$,  using partial integration we have
\begin{align*}
&\left|\int_{\left|\xi\right|\geq 1}\int_{0}^{\infty}
\frac{|\xi|^{-s}e^{-r|\xi|^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}\, drd\xi\right|\\
&=\left|\frac{1}{x}\int_{\left|\xi\right|\geq 1}e^{ix\xi}\frac{d}{d\xi}\int_{0}^{\infty}\frac{|\xi|^{-s}e^{-r|\xi|^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}\, drd\xi\right|\\
&\lesssim\left|\frac{1}{x}\int_{\left|\xi\right|\geq 1}e^{ix\xi}\int_{0}^{\infty}\left(\frac{|\xi|^{\delta-1-s}e^{-r|\xi|^{\delta}}r^{\alpha}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}+\frac{|\xi|^{-1-s}e^{-r|\xi|^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}\right)\, drd\xi\right|\\
&\lesssim\left|\frac{1}{x}\int_{\left|\xi\right|\geq 1}e^{ix\xi}\left|\xi\right|^{-s-1}d\xi\cdot\int_{0}^{\infty}\frac{r^{\alpha-1}}{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}dr\right|\lesssim \frac{1}{|x|}\lesssim \left|x\right|^{s-1},
\end{align*}
and
\begin{align*}
&\left|\int_{\left|\xi\right|\leq 1}\int_{0}^{\infty}
\frac{|\xi|^{-s}e^{-r|\xi|^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}\, drd\xi\right|\\
&\lesssim\left|\int_{\left|\xi\right|\leq \left|x\right|^{-1}}\int_{0}^{\infty}
\frac{|\xi|^{-s}e^{-r|\xi|^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}\, drd\xi\right|\\
&\quad +
\left|\int_{\left|x\right|^{-1}\leq\left|\xi\right|\leq 1}\int_{0}^{\infty}
\frac{|\xi|^{-s}e^{-r|\xi|^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}\, drd\xi\right|\\
&\lesssim \left|\int_{|\xi|\leq |x|^{-1}}\left|\xi\right|^{-s}d\xi\right|\\
&\quad+\left|\frac{1}{x}\int_{\left|x\right|^{-1}\leq\left|\xi\right|\leq 1}\int_{0}^{\infty}
\left(\frac{|\xi|^{\delta-s-1}e^{-r|\xi|^{\delta}}r^{\alpha}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}+\frac{|\xi|^{-s-1}e^{-r|\xi|^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}\right)e^{ix\xi}\, drd\xi\right|\\
&\lesssim \left|\int_{|\xi|\leq |x|^{-1}}\left|\xi\right|^{-s}d\xi\right|+\left|\frac{1}{x}\int_{|x|^{-1}\leq|\xi|\leq 1}\left|\xi\right|^{-s-1}d\xi\right|\lesssim \left|x\right|^{s-1}.
\end{align*}
from above, we have the estimate \eqref{smoothing 17}.

The proof of \eqref{smoothing 19} is similar to that of \eqref{smoothing 17}, hence, we present a brief calculation.

First, we prove that
\begin{align}\label{heat estimate 2}
\left|\int_{\mathbb{R}}\int_{0}^{\infty}\frac{\left|\xi\right|^{\delta-\beta-s}e^{-rt\left|\xi\right|^{\delta}}r^{\alpha}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}drd\xi\right|\lesssim t^{\alpha-1}\left|x\right|^{s-1}.
\end{align}
By the scailing transform, the estimate \eqref{heat estimate 2} is only to verify for $t=1$. The process is similar to the estimate \eqref{heat estimate 1}.

For $x$ is small ($|x|<1$), note that $\frac{\beta}{4}+s<1$, the integral
$$
\int_{0}^{\infty}\frac{r^{\frac{7\alpha}{4}-1}}{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}dr
$$
is convengent,
we have that
\begin{align*}
&\left|\int_{\mathbb{R}}\int_{0}^{\infty}\frac{\left|\xi\right|^{\delta-\beta-s}e^{-r\left|\xi\right|^{\delta}}r^{\alpha}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}drd\xi\right|\\
&\lesssim \left|\int_{\mathbb{R}}\int_{0}^{\infty}\frac{\left|\xi\right|^{-\frac{\beta}{4}-s}
\left(\left|r^{\frac{1}{\delta}}\xi\right|^{\delta-\frac{3\beta}{4}}e^{-r\left|\xi\right|^{\delta}}\right)
r^{\frac{7\alpha}{4}-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}drd\xi\right|\\
&\lesssim\left|\int_{\mathbb{R}}e^{ix\cdot\xi}|\xi|^{-\frac{\beta}{4}-s}d\xi\right|\cdot
\left|\sup_{(r,\xi)\in\mathbb{R}^{+}\times\mathbb{R}}
\bigg(|r^{\frac{1}{\delta}}\xi|^{\delta-\frac{3\beta}{4}}e^{-r\left|\xi\right|^{\delta}}\bigg)\right|\\
&\lesssim \left|x\right|^{\frac{\beta}{4}+s-1}\lesssim\left|x\right|^{s-1}.
\end{align*}
Moreover, for $|x|>1$, we also have that
\begin{align*}
&\left|\int_{\mathbb{R}}\int_{0}^{\infty}\frac{\left|\xi\right|^{\delta-\beta-s}e^{-r\left|\xi\right|^{\delta}}r^{\alpha}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}drd\xi\right|\\
&\lesssim\left|\int_{\left|\xi\right|\leq \left|x\right|^{-1}}\int_{0}^{\infty}\frac{\left|\xi\right|^{\delta-\beta-s}e^{-r\left|\xi\right|^{\delta}}r^{\alpha}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}drd\xi\right|\\
&\quad+\left|\int_{\left|x\right|^{-1}\leq\left|\xi\right|\leq 1}\int_{0}^{\infty}\frac{\left|\xi\right|^{\delta-\beta-s}e^{-r\left|\xi\right|^{\delta}}r^{\alpha}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}drd\xi\right|\\
&\quad +\left|\int_{\left|\xi\right|\geq 1}\int_{0}^{\infty}\frac{\left|\xi\right|^{\delta-\beta-s}e^{-r\left|\xi\right|^{\delta}}r^{\alpha}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}drd\xi\right|.
\end{align*}
Similar to the estimate in \eqref{smoothing 17}, we derive the estimate
\begin{align*}
&\left|\int_{\left|\xi\right|\geq 1}\int_{0}^{\infty}\frac{\left|\xi\right|^{\delta-\beta-s}e^{-r\left|\xi\right|^{\delta}}r^{\alpha}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}drd\xi\right|\\
&\lesssim\left|\frac{1}{x}\int_{|\xi|\geq 1}e^{ix\cdot\xi}\int_{0}^{\infty}e^{-r|\xi|^{\delta}}\bigg(\frac{|\xi|^{2\delta-\beta-s-1}r^{\alpha+1}
+|\xi|^{\delta-\beta-s-1}r^{\alpha}}{i^{\alpha}r^{2\alpha}-2r^{\alpha}\cos(\alpha\pi)+(-i)^{\alpha}}\bigg)drd\xi\right|\\
&\lesssim\frac{1}{\left|x\right|}\int_{\left|\xi\right|\geq 1}\frac{d\xi}{\left|\xi\right|^{\beta+s+1}}\int_{0}^{\infty}\frac{r^{\alpha-1}}{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}dr\cdot\sup_{(r,\xi)\in\mathbb{R}^{+}\times[-1,1]^{c}}\big(r^{2}|\xi|^{2\delta}e^{-r|\xi|^{\delta}}
+r|\xi|^{\delta}e^{-r|\xi|^{\delta}}\big)\\
&\lesssim \frac{1}{\left|x\right|}\lesssim\left|x\right|^{s-1},
\end{align*}
and by using Remark \ref{change variable equaton of Mittag-Leffer function}, we get
\begin{align*}
&\left|\int_{\left|\xi\right|\leq \left|x\right|^{-1}}\int_{0}^{\infty}\frac{\left|\xi\right|^{\delta-\beta-s}e^{-r\left|\xi\right|^{\delta}}r^{\alpha}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}drd\xi\right|\\
&\sim\left|\int_{\left|\xi\right|\leq \left|x\right|^{-1}}|\xi|^{-s}
\left(E_{\alpha,\alpha}((-i)^{\alpha}|\xi|^{\beta})-|\xi|^{\delta-\beta}e^{-i|\xi|^{\delta}}\right)e^{ix\xi}d\xi\right|\\
&\lesssim\left|\int_{|\xi|\leq|x|^{-1}}|\xi|^{-s}d\xi\right|
\lesssim\left|x\right|^{s-1},
\end{align*}
and
\begin{align*}
&\left|\int_{\left|x\right|^{-1}\leq|\xi|\leq1}
\int_{0}^{\infty}\frac{\left|\xi\right|^{\delta-\beta-s}e^{-r\left|\xi\right|^{\delta}}r^{\alpha}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}e^{ix\xi}drd\xi\right|\\
&\sim\left|\int_{\left|x\right|^{-1}\leq|\xi|\leq1}|\xi|^{-s}
\left(E_{\alpha,\alpha}((-i)^{\alpha}|\xi|^{\beta})-|\xi|^{\delta-\beta}e^{-i|\xi|^{\delta}}\right)e^{ix\xi}d\xi\right|\\
&\lesssim\left|\frac{1}{x}\int_{|x|^{-1}\leq|\xi|\leq 1}\frac{d}{d\xi}\bigg[|\xi|^{-s}\bigg(\sum_{j=0}\frac{i^{-\alpha j}|\xi|^{\beta j}}{\Gamma(\alpha j+\alpha)}-|\xi|^{\delta-\beta}e^{-i|\xi|^{\delta}}\bigg)\bigg]e^{ix\xi}d\xi\right|\\
&\lesssim\frac{1}{|x|}\left|\int_{|x|^{-1}\leq|\xi|}|\xi|^{-s-1}d\xi\right|\lesssim |x|^{s-1},
\end{align*}
hence we get the estimate \eqref{heat estimate 2}.

Next, by using the Minkovski inequality, the Hardy-Littlewood inequality, we have that
\begin{align*}
&\left\|\int_{0}^{t}\int_{0}^{\infty} \frac{D^{\delta-\beta} e^{-r(t-\tau)D^{\delta}} r^\alpha}{i^{\alpha} r^{2\alpha}
- 2r^\alpha \cos(\alpha \pi) + {(-i)}^{\alpha}} \, drf(\tau,\cdot)d\tau\right\|_{L^{p_{s}}_{x}L^{\infty}_{T}}\\
&\lesssim\int_{0}^{T}\left\|\int_{0}^{\infty} \frac{D^{\delta-\beta} e^{-r(t-\tau)D^{\delta}} r^\alpha}{i^{\alpha} r^{2\alpha}
- 2r^\alpha \cos(\alpha \pi) + {(-i)}^{\alpha}} \, dr\chi_{(0,t)}(\tau)f(\tau,\cdot)\right\|_{L^{p_{s}}_{x}L^{\infty}_{T}}d\tau\\
&\lesssim \int_{0}^{T}(t-\tau)^{\alpha-1}\left\|\left|x\right|^{s-1}\star D^{s}f(\tau,\cdot)\right\|_{L^{p_{s}}_{x}}d\tau\\
&\lesssim T^{\alpha-\frac{1}{2}}\left\|D^{s}f\right\|_{L^{2}_{T,x}},
\end{align*}
hence we get the estimate \eqref{smoothing 19}. The proof is completed.
\end{proof}
Moreover, we can construct the following interpolation estimate.

\begin{lemma}\label{interpolation estimate}
Under the conditions \rm{Lemma \ref{smoothing effects 1}-Lemma \ref{maximum function estimate}} are satisfied, for any $\theta\in\left(0,1\right)$, the following estimates hold:
 \begin{align}
 \label{smoothing 20}
 \left\|e^{-itD^{\delta}}f\right\|_{L^{\frac{p_{s}}{\theta}}_{x}L^{\frac{2}{1-\theta}}_{t}}&\lesssim \left\|D^{\theta s-\left(1-\theta\right)\gamma}f\right\|_{L^{2}_{x}},\\ \label{smoothing 21}
 \left\|\int_{0}^{\infty}
\frac{e^{-rtD^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}} \, drf(x)\right\|_{L^{\frac{p_{s}}{\theta}}_{x}L^{\frac{2}{1-\theta}}_{T}}&\lesssim T^{\frac{(\gamma-\gamma')(1-\theta)}{\delta}}
\left\|D^{\theta s-\left(1-\theta\right)\gamma'}f\right\|_{L^{2}_{x}},\\\label{smoothing 22}
\left\|\int_{0}^{t} D^{\delta-\beta} e^{-i(t-\tau)D^\delta} f(\tau,\cdot) \, d\tau\right\|_{L^{\frac{p_{s}}{\theta}}_{x}L^{\frac{2}{1-\theta}}_{T}}
&\lesssim \left\|D^{\theta\left(\delta-\beta+s\right)-\left(1-\theta\right)\nu}f\right\|_{L^{1}_{T}L^{2}_{x}},\\\label{smoothing 23}\left\|\int_{0}^{t}\int_{0}^{\infty} \frac{D^{\delta-\beta} e^{-r(t-\tau)D^{\delta}} r^\alpha}{i^{\alpha} r^{2\alpha}
- 2r^\alpha \cos(\alpha \pi) + {(-i)}^{\alpha}} \, drf(\tau,\cdot)d\tau\right\|_{L^{\frac{p_{s}}{\theta}}_{x}L^{\frac{2}{1-\theta}}_{T}}&\lesssim T^{\frac{1-2(1-\alpha)\theta}{2}+\frac{(\nu-\nu')(1-\theta)}{\delta}}\left\|D^{\theta s-\left(1-\theta\right)\nu'}f\right\|_{L^{2}_{T,x}}.
\end{align}
\end{lemma}
\begin{proof}
The proof follows the Stein's theorem of analytic interpolation, can refer to \cite{Grafakos}.

Define the operator
\begin{align*}
T_{z}f=D^{-sz+\left(1-z\right)\gamma}e^{-itD^{\delta}}f, \text{ for }z\in\mathbb{C}, 0\leq\Re{z}\leq 1.
\end{align*}
We can get
\begin{align*}
T_{i\omega}f&=D^{\gamma}D^{-i\omega\left(s+\gamma\right)}e^{-itD^{\delta}}f,\\
T_{1+i\omega}f&=D^{-s}D^{-i\omega\left(s+\gamma\right)}e^{-itD^{\delta}}f.
\end{align*}
Note that the interpolation
$$
\left( BMO_{x}L_{t}^{2}, L^{p_{s}}_{x}L^{\infty}_{t} \right)_{\theta} = L^{\frac{p_{s}}{\theta}}_{x}L^{\frac{2}{1-\theta}}_{t},
$$
Combine with the estimate \eqref{BMO estimate}, \eqref{smoothing 1}, \eqref{smoothing 16}, we respectively estimate that
\begin{align*}
\left\|T_{i\omega}f\right\|_{BMO_{x}L^{2}_{t}}&\leq C_{\omega,s,\gamma}\left\|D^{\gamma}e^{-itD^{\delta}}f\right\|_{L^{\infty}_{x}L^{2}_{t}}\lesssim\left\|f\right\|_{L^{2}_{x}},\\
\left\|T_{1+i\omega}f\right\|_{L^{p_{s}}_{x}L^{\infty}_{t}}&\lesssim \left\|D^{-s}e^{-itD^{\delta}}D^{-i\omega\left(s+\gamma\right)}f\right\|_{L^{p_{s}}_{x}L^{\infty}_{t}}\lesssim
\left\|D^{-i\omega\left(s+\gamma\right)}f\right\|_{L^{2}_{x}}\lesssim\left\|f\right\|_{L^{2}_{x}},
\end{align*}
By the Stein's theorem of analytic interpolation and \eqref{Kenig interpolation},
we get that
$$
\left\|e^{-itD^{\delta}}f\right\|_{L^{\frac{p_{s}}{\theta}}_{x}L^{\frac{2}{1-\theta}}_{t}}\lesssim \left\|D^{\theta s-\left(1-\theta\right)\gamma}f\right\|_{L^{2}_{x}},
$$
this implies that \eqref{smoothing 20}.

Define the operator
\begin{align*}
T_{z}f=D^{-sz+\left(1-z\right)\gamma'}\int_{0}^{\infty}\frac{e^{-rtD^{\delta}}r^{\alpha-1}}{i^{\alpha}r^{2\alpha}-2r^{\alpha}
\cos(\alpha\pi)+(-i)^{\alpha}}drf, \text{ for }z\in\mathbb{C}, 0\leq\Re{z}\leq 1, 0<\gamma'<\gamma,
\end{align*}
and by using the estimate \eqref{Kenig interpolation}, \eqref{smoothing 10}, \eqref{smoothing 17} and follows the process of \eqref{smoothing 20}, we obtain
\begin{align*}
\left\|T_{i\omega}f\right\|_{BMO_{x}L^{2}_{T}}\leq C_{\omega,s,\gamma}\bigg\|D^{\gamma'}\int_{0}^{\infty}\frac{e^{-rtD^{\delta}}r^{\alpha-1}}{i^{\alpha}r^{2\alpha}-2r^{\alpha}
\cos(\alpha\pi)+(-i)^{\alpha}}drf\bigg\|_{L^{\infty}_{x}L^{2}_{T}}\lesssim T^{\frac{\gamma-\gamma'}{\delta}}\big\|f\big\|_{L^{2}_{x}},\\
\left\|T_{1+i\omega}f\right\|_{L^{p_{s}}_{x}L^{\infty}_{T}}\lesssim\bigg\|D^{-s}\int_{0}^{\infty}
\frac{e^{-rtD^{\delta}}r^{\alpha-1}}{i^{\alpha}r^{2\alpha}-2r^{\alpha}
\cos(\alpha\pi)+(-i)^{\alpha}}drD^{-i\omega(s+\gamma)}f\bigg\|_{L^{p_{s}}_{x}L^{\infty}_{T}}\lesssim\big\|f\big\|_{L^{2}_{x}},
\end{align*}
combine the interpolation $\left( BMO_{x}L_{T}^{2}, L^{p_{s}}_{x}L^{\infty}_{T} \right)_{\theta} = L^{\frac{p_{s}}{\theta}}_{x}L^{\frac{2}{1-\theta}}_{T}$, we can get \eqref{smoothing 21}.

Moreover, define the operator
\begin{align*}
T_{z}f&=D^{-sz+\left(1-z\right)\nu}_{x}\int_{0}^{t} D^{\delta-\beta} e^{-i(t-\tau)D^\delta} f(\tau,\cdot) \, d\tau, \text{ for }z\in\mathbb{C}, 0\leq\Re{z}\leq 1,\\
T_{z}f&=D^{-sz+\left(1-z\right)\nu'}_{x}\int_{0}^{t}\int_{0}^{\infty} \frac{D^{\delta-\beta} e^{-r(t-\tau)D^{\delta}} r^\alpha}{i^{\alpha} r^{2\alpha}
- 2r^\alpha \cos(\alpha \pi) + {(-i)}^{\alpha}} \, drf(\tau,\cdot)d\tau, \text{ for }z\in\mathbb{C}, 0\leq\Re{z}\leq 1.
\end{align*}
combine with \eqref{BMO estimate}, \eqref{smoothing 9}, \eqref{smoothing 11},\eqref{smoothing 18},\eqref{smoothing 19} and the Stein's theorem of analytic interpolation, similar the process \eqref{smoothing 20} and \eqref{smoothing 21},we can get the estimates \eqref{smoothing 22}, \eqref{smoothing 23}.
\end{proof}
At the end of this section, we generalize the dispersive estimates proven by Ponce \cite{Ponce}, which play a crucial role in the proof of well-posedness for the case $\beta > 2$ in Section 4.
\begin{lemma}\label{diepersive estimate}
Let $d\geq1$ and define for any $\varpi\geq 2$
\begin{align*}
S^{\varpi}(x)=\int_{\mathbb{R}^{d}}e^{i\left(\left|\xi\right|^{\varpi}+x\xi\right)}d\xi.
\end{align*}
Then for any $0\leq\frac{\eta}{d}\leq\frac{\varpi}{2}-1$,
\begin{align}\label{dispersive bounded}
\left\|I^{\eta}S^{\varpi}(x)\right\|_{\infty}\leq C_{\varpi,\eta},
\end{align}
where
\begin{align*}
I^{\eta}S^{\varpi}(x)=\int_{\mathbb{R}^{d}}e^{i\left(\left|\xi\right|^{\varpi}+x\xi\right)}\left|\xi\right|^{\eta}d\xi,
\end{align*}
and $C_{\varpi}$ is only depending on $\varpi$.
\end{lemma}
\begin{remark}
If $\varpi=3$, $d=1$, $S^{\varpi}(x)$ agrees with the Airy function $Ai(x)$.
\end{remark}
\begin{proof}
For $d=1$, the proof can be founded in Ponce \cite{Ponce}, hence we only verify for $d\geq 2$.

The proof depends the Van der Corput Lemma, the properties of the Bessel function and the Fa\'{a} di Bruno's formula.

We choose a $C^{\infty}(\mathbb{R}^{d})$ radial function $\chi_{0}$ such that
$\chi_{0}(\xi)=
\begin{cases}
0,\quad \left|\xi\right|<1,\\
1,\quad \left|\xi\right|\geq 2,
\end{cases}$
hence we only need to verify that
\begin{align*}
H^{\varpi}(x)=\left|\int_{\mathbb{R}^{d}}e^{i\left(\left|\xi\right|^{\varpi}+x\xi\right)}
\chi_{0}(\xi)\left|\xi\right|^{\eta}d\xi\right|\leq C.
\end{align*}
By using the Littlewood-Paley decomposition and using the changes variable, we get that
\begin{align*}
\left\|H^{\varpi}\left(\cdot\right)\right\|_{\infty}&\lesssim\sup_{x\in\mathbb{R}^{d}}\sum_{j\in\mathbb{Z}}
\left|\int_{\mathbb{R}^{d}}e^{i\left(\left|\xi\right|^{\varpi}+x\xi\right)}
\chi_{0}(\xi)\left|\xi\right|^{\eta}\Phi\left(2^{-j}\xi\right)d\xi\right|\\
&\lesssim\sup_{x\in\mathbb{R}^{d}}\sum_{j\in\mathbb{Z}}2^{j\left(\eta+d\right)}
\left|\int_{\mathbb{R}^{d}}e^{i\left(2^{j\varpi}\left|\xi\right|^{\varpi}+x\cdot2^{j}\xi\right)}
\chi_{0}(2^{j}\xi)\left|\xi\right|^{\eta}\Phi\left(\xi\right)d\xi\right|\\
&=\sup_{x\in\mathbb{R}^{d}}\sum_{j=0}2^{j\left(\eta+d\right)}
\left|\int_{\mathbb{R}^{d}}e^{i\left(2^{j\varpi}\left|\xi\right|^{\varpi}+x\cdot2^{j}\xi\right)}
\chi_{0}(2^{j}\xi)\left|\xi\right|^{\eta}\Phi\left(\xi\right)d\xi\right|\\
&=\sup_{x\in\mathbb{R}^{d}}\sum_{j=0}2^{j\left(\eta+d\right)}
\int_{S^{d-1}}\int_{0}^{\infty}e^{i\left(2^{j\varpi}r^{\varpi}+2^{j}r\left(x,\xi'\right)\right)}
\chi_{0}(2^{j}r)r^{\eta+d-1}\Phi\left(r\right)drd\mu(\xi'),
\end{align*}
where $\mu(\cdot)$ is the measure of the surface $S^{d-1}$.

We need to estimate
\begin{align}\label{need estimate 1 }
\sum_{j=0}2^{j\left(\eta+d\right)}
\int_{0}^{\infty}e^{i\left(2^{j\varpi}r^{\varpi}+2^{j}r\left(x,\xi'\right)\right)}
\chi_{0}(2^{j}r)r^{\eta+d-1}\Phi\left(r\right)dr
\end{align}
Note that $r\in\left(\frac{1}{2},2\right)$, and for the function $g(r)=2^{j\varpi}r^{\varpi}+2^{j}r\left(x,\xi'\right)$,
$g'(r)\sim 2^{j\varpi}r^{\varpi-1}+2^{j}\left(x,\xi'\right)$. We can choose constant $c_{1}$, $c_{2}$, and get that
\begin{align*}
&\sum_{j=0}2^{j\left(\eta+d\right)}
\int_{0}^{\infty}e^{i\left(2^{j\varpi}r^{\varpi}+2^{j}r\left(x,\xi'\right)\right)}
\chi_{0}(2^{j}r)r^{\eta+d-1}\Phi\left(r\right)dr\\
&=\sum_{k=1}^{3}\sum_{j\in A_{k}}2^{j\left(\eta+d\right)}
\int_{0}^{\infty}e^{i\left(2^{j\varpi}r^{\varpi}+2^{j}r\left(x,\xi'\right)\right)}
\chi_{0}(2^{j}r)r^{\eta+d-1}\Phi\left(r\right)dr,
\end{align*}
where
\begin{align*}
A_{1}&=\left\{j\geq 0,  c_{1}2^{j\left(\varpi-1\right)}\geq \left|x\right|\right\},\\
A_{2}&=\left\{j\geq 0,  c_{2}2^{j\left(\varpi+1\right)}\leq \left|x\right|\right\},\\
A_{3}&=\left\{j\geq 0,  c_{1}2^{j\left(\varpi-1\right)}\leq \left|x\right|\leq c_{2}2^{j\left(\varpi+1\right)} \right\}.
\end{align*}

We make sequential estimates for $j \in A_i$ ($i=1,2,3$).

For $j\in A_{1}$, denote the operator $L$:
$$
L=\frac{1}{ig'(r)}\frac{d}{dr},\text{ then we have }L\left(e^{ig(r)}\right)=e^{ig(r)},
$$

We denote that $S_{j}(r)=\chi_{0}(2^{j}r)r^{\eta+d-1}\Phi\left(r\right)$, obviously, $S_{j}(r)=0$ for $j\geq 2$. We derive that
$$
\left|\partial_{r}^{k}S_{j}(r)\right|\lesssim 1, \text{ for any }k\in\mathbb{Z}^{+}.
$$
Moreover, note that $\left|x\right|\lesssim 2^{j\left(\varpi-1\right)}$, we derive that
$$
\left|g'(r)\right|\gtrsim 2^{j\varpi}\text{ and }\left|g^{(k)}(r)\right|\lesssim 2^{j\varpi}\text{ for any }k\in\mathbb{Z}^{+}\text{ and }k\geq 2.
$$
By using the Fa\'{a} di Bruno's formula, we get that
\begin{align*}
\left|D^{k}\frac{1}{g'(r)}\right|\lesssim \left|\sum_{\substack {b_{1}+b_{2}+\cdot\cdot\cdot+b_{l}=k\\ b_{j}\geq 0,1\leq l\leq k}}
\prod_{j=1}^{l}\left(\partial^{b_{j}}g'(r)\right)\frac{1}{\left(g'(r)\right)^{l+1}}\right|\lesssim 2^{-j\varpi},
\end{align*}
hence we get that for any $N\in\mathbb{Z}^{+}$,
\begin{align*}
\left|\int_{0}^{\infty}e^{i\left(2^{j\varpi}r^{\varpi}+2^{j}r\left(x,\xi'\right)\right)}
\chi_{0}(2^{j}r)r^{\eta+d-1}\Phi\left(r\right)dr\right|&=\left|\int_{0}^{\infty}L^{N}\left(e^{ig(r)}\right)S_{j}(r)dr\right|\\
&=\left|\int_{0}^{\infty}e^{ig(r)}\left(L^{*}\right)^{N}S_{j}(r)dr\right|,
\end{align*}
where
\begin{align*}
\left(L^{*}\right)^{N}S_{j}(r)&=\frac{1}{-i}\left(L^{*}\right)^{N-1}\left\{\frac{d}{dr}\left(\frac{1}{g'(r)}S_{j}(r)\right)\right\}\\
&=\left(\frac{1}{-i}\right)^{2}\left(L^{*}\right)^{N-2}\left\{\frac{d}{dr}\left(\frac{1}{g'(r)}\frac{d}{dr}
\left(\frac{1}{g'(r)}S_{j}(r)\right)\right)\right\}\\
&=\cdot\cdot\cdot\\
&\sim\sum_{_{\alpha+\beta=N}}\sum_{\substack{b_{1}+b_{2}+\cdot\cdot\cdot+b_{l}=\alpha\\b_{j}\geq0,1\leq l\leq N}}\prod_{j=1}^{N}
\left(\frac{d^{b_{j}}}{dr^{b_{j}}}\left(\frac{1}{g'(r)}\right)\right)\frac{d^{\beta}}{dr^{\beta}}S_{j}(r),
\end{align*}
hence we get
\begin{align*}
\left|\int_{0}^{\infty}e^{ig(r)}\left(L^{*}\right)^{N}S_{j}(r)dr\right|\lesssim 2^{-j\varpi N}, \text{ for any }N\in\mathbb{Z}^{+}.
\end{align*}

For $j\in A_{2}$, similar to the $j\in A_{1}$, we can get the same estiamtes, hence we omit the details.

For $ j \in A_{3} $, the above method of integration by parts is no longer applicable, because there exists $ x_{0} \in \left( c_{1} 2^{j (\varpi - 1)}, c_{2} 2^{j (\varpi + 1)} \right) $ such that $ g'(r) = 0 $. Therefore, we need to employ Van der Corput Lemma.

By the Fourier transform formula on $ S^{d-1} $, as referenced in \cite{Grafakos}, and by using the properties of the Bessel function \eqref{Bessel function transform}, \eqref{h function property}, we obtain that
\begin{align*}
&\int_{S^{d-1}}\int_{0}^{\infty}e^{i\left(2^{j\varpi}r^{\varpi}+2^{j}r\left(x,\xi'\right)\right)}
\chi_{0}(2^{j}r)r^{\eta+d-1}\Phi\left(r\right)drd\mu(\xi')\\
&=\int_{S^{d-1}}\int_{0}^{\infty}e^{ig(r)}
\chi_{0}(2^{j}r)r^{\eta+d-1}\Phi\left(r\right)drd\mu(\xi')\\
&=c_{d}\int_{0}^{\infty}\chi_{0}(2^{j}r)r^{\eta+d-1}\Phi\left(r\right)e^{i2^{j\varpi}r^{\varpi}}\left(2^{j}rs\right)^{-\frac{d-2}{2}}
J_{\frac{d-2}{2}}\left(2^{j}rs\right)dr\quad \left(s=\left|x\right|\right)\\
&=c_{d}\int_{0}^{\infty}\chi_{0}(2^{j}r)r^{\eta+d-1}\Phi\left(r\right)e^{i2^{j\varpi}r^{\varpi}}\Re \left(e^{i2^{j}rs}h\left(2^{j}rs\right)\right)dr\\
&\sim c_{d}\int_{0}^{\infty}\chi_{0}(2^{j}r)r^{\eta+d-1}\Phi\left(r\right)e^{i2^{j\varpi}r^{\varpi}+i2^{j}rs}h\left(2^{j}rs\right)dr\\
&\qquad+c_{d}\int_{0}^{\infty}\chi_{0}(2^{j}r)r^{\eta+d-1}\Phi
\left(r\right)e^{i2^{j\varpi}r^{\varpi}-i2^{j}rs}\overline{h}\left(2^{j}rs\right)dr.
\end{align*}
Note $r\in\left(\frac{1}{2},2\right)$, $s\in\left(c_{1}2^{j\left(\varpi-1\right)},c_{2}2^{j\left(\varpi+1\right)}\right)$ and using the lemma \ref{Van der Corput lemma} and equation \eqref{h function property}, we get
\begin{align*}
&\int_{S^{d-1}}\int_{0}^{\infty}e^{i\left(2^{j\varpi}r^{\varpi}+2^{j}r\left(x,\xi'\right)\right)}
\chi_{0}(2^{j}r)r^{\eta+d-1}\Phi\left(r\right)drd\mu(\xi')\\
&\lesssim \left(2^{j\varpi}\right)^{-\frac{1}{2}}\left\{\left\|S_{j}(r)h\left(2^{j}rs\right)\right\|_{\infty}+
\left\|\partial\left(S_{j}(r)h\left(2^{j}rs\right)\right)\right\|_{L^{1}}\right\}\\
&\lesssim  \left(2^{j\varpi}\right)^{-\frac{1}{2}}\left(2^{j}\right)^{-\frac{d-1}{2}}\left(2^{j(\varpi-1)}\right)^{-\frac{d-1}{2}}\\
&\lesssim 2^{\frac{-j\varpi d}{2}}.
\end{align*}
If $j\in A_{3}$, we can get
$$
\frac{1}{\varpi+1}\log_{2}\left(\frac{\left|x\right|}{c_{2}}\right)\leq j\leq\frac{1}{\varpi-1}\log_{2}\left(\frac{\left|x\right|}{c_{1}}\right),
$$
hence we can choose the constant $M$ which is only dependent of $\varpi$, $c_{1}$ and $c_{2}$ such that $\left|A_{3}\right|\leq M$.
From above discuss, we can choose the constan $N\in\mathbb{Z}^{+}$ large enough and for $0\leq\frac{\eta}{d}\leq\frac{\varpi}{2}-1$,
we get
\begin{align*}
&\sum_{j=0}2^{j\left(\eta+d\right)}
\int_{S^{d-1}}\int_{0}^{\infty}e^{i\left(2^{j\varpi}r^{\varpi}+2^{j}r\left(x,\xi'\right)\right)}
\chi_{0}(2^{j}r)r^{\eta+d-1}\Phi\left(r\right)drd\mu(\xi')\\
&\lesssim \sum_{j\in A_{1}}2^{j\left(\eta+d-\varpi N\right)}+\sum_{j\in A_{2}}2^{j\left(\eta+d-\varpi N\right)}+\sum_{j\in A_{3}}2^{j\left(\eta+d-\frac{\varpi d}{2}\right)}\\
&\lesssim 1, \text{ for }0\leq\frac{\eta}{d}\leq\frac{\varpi}{2}-1.
\end{align*}
The proof is completed.
\end{proof}
\begin{remark}\label{scaling disoersive estimates}
When the condition of Lemma \ref{diepersive estimate} is satisfied, by the scaling transform, we have
\begin{align}\label{dispersive estimate with t}
\left|\int_{\mathbb{R}^{d}}e^{i\left(t\left|\xi\right|^{\varpi}+x\xi\right)}\left|\xi\right|^{\eta}d\xi\right|\lesssim
t^{-\frac{d+\eta}{\varpi}}\left\|I^{\eta}S\left(t^{-\frac{1}{\varpi}}x\right)\right\|_{\infty}\lesssim t^{-\frac{d+\eta}{\varpi}}.
\end{align}
\end{remark}
\begin{remark}\label{operator holder estimate}
From Lemma {\rm\ref{diepersive estimate}} and Remark {\rm\ref{scaling disoersive estimates}}, it is easy to see
\begin{align}\label{holder estimate}
\big\|I^{\eta}S^{\varpi}(x)\big\|_{\dot{C}^{\varrho}(\mathbb{R}^{d})}\leq C_{\varpi},\quad \text{when } 0\leq \frac{\eta+\varrho}{d}\leq \frac{\varpi}{2}-1.
\end{align}
\begin{align}\label{holder estimate scailing}
\bigg\|\int_{\mathbb{R}^{d}}e^{i(t|\xi|^{\varpi}+x\xi)}|\xi|^{\eta}\,d\xi\bigg\|_{\dot{C}^{\varrho}}\lesssim t^{-\frac{d+\eta+\varpi}{\varpi}},\quad \text{when } 0\leq \frac{\eta+\varrho}{d}\leq \frac{\varpi}{2}-1.
\end{align}
Indeed, note that $\dot{C}^{\varrho}\sim \dot{B}^{\varrho}_{\infty,\infty}$ and $l^{1}\subset l^{\infty}$, hence
\begin{align*}
\big\|I^{\eta}S^{\varpi}(x)\big\|_{\dot{C}^{\varrho}}&\sim\sup_{j\in\mathbb{Z}}2^{j\varrho}
\big\|\triangle_{j}I^{\eta}S^{\varpi}\big\|_{L^{\infty}}\\
&\lesssim\sup_{x\in\mathbb{R}^{d}}\sum_{j\in\mathbb{Z}}
\left|\int_{\mathbb{R}^{d}}e^{i\left(|\xi|^{\varpi}+x\xi\right)}
|\xi|^{\eta+\varrho}\Phi\left(2^{-j}\xi\right)d\xi\right|,
\end{align*}
which implies \eqref{holder estimate} holds. By scaling, \eqref{holder estimate scailing} also holds.
\end{remark}
By using the dispersive estimate Lemma \ref{diepersive estimate}, we can get the following lemma.
\begin{lemma}\label{estimate operator}
Let $d\geq 1$, and the condition $0\leq\frac{\delta-\beta}{d}<\frac{\delta}{2}-1$ is satisfied, the following estimates hold:
\begin{align}
\label{dispersive estimates 1}\left\|e^{-itD^{\delta}}f\right\|_{L^{p}}&\lesssim t^{-\frac{\alpha d}{\beta}\left(1-\frac{2}{p}\right)}\left\|f\right\|_{L^{p'}},\text{ }2\leq p\leq\infty,\\\label{dispersive estimates 2}
\left\|D^{\delta-\beta}e^{-itD^{\delta}}f\right\|_{L^{p}}&\lesssim t^{\alpha-1-\frac{\alpha d}{\beta}\left(1-\frac{2}{p}\right)}\left\|f\right\|_{L^{p'}},\text{ }\frac{1}{p}=\frac{1}{2}-\frac{\delta-\beta}{d\left(\delta-2\right)},\\\label{dispersive estimates 3}
\left\|\int_{0}^{\infty}
\frac{e^{-rtD^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}} \, drf(\cdot)\right\|_{L^{r}}&\lesssim t^{-\frac{\alpha d}{\beta}\left(\frac{1}{p}-\frac{1}{r}\right)}\left\|f\right\|_{L^{p}},\text{ }\frac{d}{\beta}\big(\frac{1}{p}-\frac{1}{r}\big)<1,\\\label{dispersive estimates 4}
\left\|\int_{0}^{\infty} \frac{D^{\delta-\beta} e^{-rtD^{\delta}} r^\alpha}{i^{\alpha} r^{2\alpha}
- 2r^\alpha \cos(\alpha \pi) + {(-i)}^{\alpha}} \, drf(\cdot)\right\|_{L^{r}}&\lesssim t^{\alpha-1-\frac{\alpha d}{\beta}\left(\frac{1}{p}-\frac{1}{r}\right)}\left\|f\right\|_{L^{p}},\text{ }\frac{d}{\beta}\big(\frac{1}{p}-\frac{1}{r}\big)<2.
\end{align}
\end{lemma}
\begin{proof}
From Lemma \ref{diepersive estimate} and Plancherel identity, we obtain
\begin{align*}
\left\|e^{-itD^{\delta}}f\right\|_{L^{\infty}}&\lesssim t^{-\frac{\alpha d}{\beta}}\left\|f\right\|_{L^{1}},\\
\left\|e^{-itD^{\delta}}f\right\|_{L^{2}}&\lesssim \left\|f\right\|_{L^{2}},
\end{align*}
by using the Riesz interpolation, we get \eqref{dispersive estimates 1}.

We choose $\sigma=\left(\frac{\delta}{2}-1\right)d-\left(\delta-\beta\right)>0$, and note that
$
\frac{\delta-\beta+\sigma+d}{\delta}=\frac{d}{2}
$.
By using Lemma \ref{diepersive estimate} and Plancherel identity,
we have that
\begin{align*}
\left\|D^{\delta-\beta}e^{-itD^{\delta}}f\right\|_{L^{\infty}}
=\left\|D^{\delta-\beta}D^{\sigma}e^{-itD^{\delta}}D^{-\sigma}f\right\|_{L^{\infty}}&\lesssim t^{-\frac{d}{2}}\left\|f\right\|_{\dot{H}^{-\sigma}_{1}},\\
\left\|D^{\delta-\beta}e^{-itD^{\delta}}f\right\|_{L^{2}}=\left\|e^{-itD^{\delta}}D^{\delta-\beta}f\right\|_{L^{2}}
&\lesssim\left\|f\right\|_{\dot{H}^{\delta-\beta}_{2}},
\end{align*}
for
\begin{align*}
\theta=\frac{2\left(\delta-\beta\right)}{d\left(\delta-2\right)},\text{ }
\frac{1}{p}=\frac{1}{2}-\frac{\delta-\beta}{d\left(\delta-2\right)},\text{ }
\frac{1}{p'}=\frac{1}{2}+\frac{\delta-\beta}{d\left(\delta-2\right)},
\end{align*}
and note that
\begin{align*}
\theta\left(-\sigma\right)+\left(1-\theta\right)\left(\delta-\beta\right)&=0,\\
-\frac{d}{2}\theta=\alpha-1-\frac{\alpha d}{\beta}\left(1-\frac{2}{p}\right)&=-\frac{d}{\delta}\big(\frac{1}{p'}-\frac{1}{p}+\frac{\delta-\beta}{d}\big),
\end{align*}
by using the real interpolation and Besov embedeeding \cite{Bergh,B.X. Wang}, we have
\begin{align*}
\left(L^{\infty}(\mathbb{R}^{d}),L^{2}(\mathbb{R}^{d})\right)_{\theta,p}=L^{p,p}(\mathbb{R}^{d})
&=L^{p}(\mathbb{R}^{d}),\\
\left(\dot{H}^{-\sigma}_{1}(\mathbb{R}^{d}),
\dot{H}^{\delta-\beta}_{2}(\mathbb{R}^{d})\right)_{\theta,p}&=\dot{B}^{0}_{p',p}(\mathbb{R}^{d}),\\
L^{p'}(\mathbb{R}^{d})\approx\dot{F}^{0}_{p',2}(\mathbb{R}^{d})\hookrightarrow \dot{B}^{0}_{p',2}(\mathbb{R}^{d})&\hookrightarrow\dot{B}^{0}_{p',p}(\mathbb{R}^{d}),
\end{align*}
hence we obtain that
\begin{align*}
\left\|D^{\delta-\beta}e^{-itD^{\delta}}f\right\|_{L^{p}}&\lesssim t^{\alpha-1-\frac{\alpha d}{\beta}\left(1-\frac{2}{p}\right)}\left\|f\right\|_{L^{p'}},
\end{align*}
hence we obtain \eqref{dispersive estimates 2}.

Moreover, $\frac{d}{\beta}\big(\frac{1}{p}-\frac{1}{r}\big)<1$ and $\frac{d}{\beta}\big(\frac{1}{p}-\frac{1}{r}\big)<2$ can ensure that integral
\begin{align*}
\int_{0}^{\infty}\frac{r^{\alpha-1-\frac{\alpha d}{\beta}\left(\frac{1}{p}-\frac{1}{r}\right)}}{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}dr,\int_{0}^{\infty}\frac{r^{2\alpha-1-\frac{\alpha d}{\beta}\left(\frac{1}{p}-\frac{1}{r}\right)}}{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}}dr
\end{align*}
are respectively both convergent. Therefore, basic the estimates of fractional heat kernel, we obtain \eqref{dispersive estimates 3},\eqref{dispersive estimates 4}.
The proof is completed.
\end{proof}
\begin{remark}\label{condition claim}
From the above process, it is obvious that the condition $0\leq \frac{\delta-\beta}{d}<\frac{\delta}{2}-1$ is not necessary for \eqref{dispersive estimates 1}, \eqref{dispersive estimates 3} and \eqref{dispersive estimates 4}.
\end{remark}
\begin{remark}
Indeed, let $r\in(0,1)$. If $0\leq (\delta-\beta)/d\leq\delta/2-1/r$, then for the operator $D^{\delta-\beta}e^{-itD^{\delta}}$, we obtain the following dispersive estimates:
\begin{enumerate}[\rm(i)]
\item
\begin{align}\label{Hardy estimate1}
\big\|D^{\delta-\beta}e^{-itD^{\delta}}f\big\|_{L^{\infty}}&\lesssim t^{\alpha-1-\frac{\alpha d}{\beta r}}\big\|f\big\|_{\mathcal{H}^{r}},
\end{align}
\item
Consider the line segment $\overline{AB}$ determined by points $A:(\frac{1}{p'},\frac{1}{p})$ and $B:(\frac{1}{r},0)$, where $p$ takes values from \eqref{dispersive estimates 2}. Then we have
\begin{align}\label{Hardy estimate2}
\big\|D^{\delta-\beta}e^{-itD^{\delta}}f\big\|_{\mathcal{H}^{a}}&\lesssim t^{\alpha-1-\frac{\alpha d}{\beta}(\frac{1}{b}-\frac{1}{a})}\big\|f\big\|_{\mathcal{H}^{b}},\ \text{where } \left(\frac{1}{b},\frac{1}{a}\right)\in \overline{AB}.
\end{align}
\item
\begin{align}\label{Hardy estimate3}
\big\|D^{\delta-\beta}e^{-itD^{\delta}}f\big\|_{BMO}\lesssim t^{\alpha-1-\frac{\alpha d}{\beta c}}\big\|f\big\|_{\mathcal{H}^{c}},\ \text{where } c=\frac{p+r-pr}{p-pr+2r-1}.
\end{align}
\end{enumerate}

For $r\in(0,1)$, note that $\big(\mathcal{H}^{r}(\mathbb{R}^{d})\big)^{\star}=\dot{C}^{d(\frac{1}{r}-1)}(\mathbb{R}^{d})$, and
$$
0\leq \frac{\delta-\beta}{d}<\frac{\delta}{2}-\frac{1}{r}\Rightarrow \frac{\delta-\beta+d(\frac{1}{r}-1)}{d}\leq\frac{\delta}{2}-1.
$$
Applying Lemma \ref{diepersive estimate} and Remark \ref{operator holder estimate}, we have
\begin{align*}
\big\|D^{\delta-\beta}e^{-itD^{\delta}}f\big\|_{L^{\infty}}&=\big\|S_{t,\delta-\beta}\star f\big\|_{L^{\infty}}\\
&\lesssim\big\|\mathcal{F}^{-1}\big(|\xi|^{\delta-\beta}e^{-it|\xi|^{\delta}}\big)\big\|_{\dot{C}^{d(\frac{1}{r}-1)}}\big\|f\big\|_{\mathcal{H}^{r}}\\
&\lesssim t^{-\frac{d}{\delta}\left(\frac{1}{r}+\frac{\delta-\beta}{d}\right)}\big\|f\big\|_{\mathcal{H}^{r}}.
\end{align*}
Combining \eqref{dispersive estimates 2} and \eqref{Hardy estimate1}, interpolation yields \eqref{Hardy estimate2}. Furthermore, since $(1,\frac{1-r}{p+r-pr})\in \overline{AB}$, we obtain
$$
\big\|D^{\delta-\beta}e^{-itD^{\delta}}f\big\|_{\mathcal{H}^{\frac{p+r-pr}{1-r}}}\lesssim t^{-\frac{\alpha d}{\beta}\left(\frac{p-pr+2r-1}{p+r-pr}+\frac{\delta-\beta}{d}\right)}\big\|f\big\|_{\mathcal{H}^{1}}.
$$
Noting that $\big(\mathcal{H}^{1}(\mathbb{R}^{d})\big)^{\star}=BMO$, we derive \eqref{Hardy estimate3} through duality estimates.
\end{remark}
Basic the above Lemma \ref{estimate operator}, we can construct the following estimates for the solution operator $E_{\alpha,1}\left((-it)^{\alpha}D^{\beta}\right)$ and $E_{\alpha,\alpha}\left((-it)^{\alpha}D^{\beta}\right)$. Under the conditions of Lemma \ref{estimate operator}, for convenience, we denote
$p_{0}=\frac{2d(\delta-2)}{d(\delta-2)-2(\delta-\beta)}$.
\begin{lemma}\label{Mittag-Leffer operator estimate}
Let $d\geq 1$, $\beta>2$, under the conditions of Lemma {\rm\ref{estimate operator}},
the following estimate hold:
\begin{align}
\label{Mittag-Leffer estimates 1}
\left\|E_{\alpha,1}\left((-it)^{\alpha}D^{\beta}\right)f(\cdot)\right\|_{L^{p_{0}}}
\lesssim t^{-\frac{\alpha d}{\beta}\left(1-\frac{2}{p}\right)}\left\|f\right\|_{L^{p_{0}'}},\\\label{Mittag-Leffer estimates 2}
\left\|E_{\alpha,\alpha}\left((-it)^{\alpha}D^{\beta}\right)f(\cdot)\right\|_{L^{p_{0}}}
\lesssim t^{-\frac{\alpha d}{\beta}\left(1-\frac{2}{p}\right)}\left\|f\right\|_{L^{p_{0}'}}.
\end{align}
\end{lemma}
\begin{proof}
From Remark \ref{change variable equaton of Mittag-Leffer function}, we obtain that
\begin{align*}
E_{\alpha,1}\left((-it)^{\alpha}D^{\beta}\right)&\sim e^{-it D^{\delta}}
    -\int_{0}^{\infty}
    \frac{e^{-rtD^{\delta}} r^{\alpha-1}}
    {i^{\alpha} r^{2\alpha} - 2 r^{\alpha} \cos(\alpha \pi) + (-i)^{\alpha}} \, dr,\\
E_{\alpha,\alpha}\left((-it)^{\alpha}D^{\beta}\right)&\sim t^{1-\alpha} D^{\delta-\beta} e^{-itD^{\delta}}
    - t^{1-\alpha} \int_{0}^{\infty}
    \frac{D^{\delta-\beta}e^{-rtD^{\delta}}r^{\alpha}}
    {i^{\alpha} r^{2\alpha} - 2 r^{\alpha} \cos(\alpha \pi) + (-i)^{\alpha}} \, dr.
\end{align*}
The condition $\beta>2$ can ensure that
$$
\frac{1}{p_{0}}=\frac{1}{2}-\frac{\delta-\beta}{d\left(\delta-2\right)}>\frac{d-\beta}{2d},
$$
by using Lemma \ref{estimate operator}, the estimates \eqref{Mittag-Leffer estimates 1} and \eqref{Mittag-Leffer estimates 2}
are obvious. The proof is now completed.
\end{proof}
\begin{remark}
From Lemma \ref{estimate operator}, it is obvious that \eqref{Mittag-Leffer estimates 1} hold for any $\frac{d-\beta}{2d}<\frac{1}{p}\leq\frac{1}{2}$.
\end{remark}

\section{Main results}
In this section, we establish our main results, which include global/local well-posedness, the asymptotic behavior of solutions, and self-similarity. For convenience, we choose the nonlinearity $g(w) = |w|^{p-2}w$.
\subsection{The well-posedness}

\subsubsection{The case $2<\beta<\infty$}
First, we construct the global/local well-posedness of E.q. \eqref{Eq:F-T-S-E} for case $2<\beta<\infty$.

For $2\leq p<\infty$, we consider the following Banach space
$$
X^{\kappa}_{p}=\left\{w:\left(0,\infty\right)\rightarrow L^{p}(\mathbb{R}^{d})/\quad \sup_{0<t<\infty}t^{\kappa}\left\|w(t)\right\|_{p}<\infty\right\}\text{ with }\kappa=\frac{\alpha}{\beta}\left(\frac{\beta}{p-2}-\frac{d}{p}\right),
$$
and define the initial value space $X_{0}$ as the set of $u_{0}\in\mathcal{S}'$ such that
$$
\left\|w_{0}\right\|_{X_{0}}=\sup_{0<t<\infty}t^{\kappa}\left\|E_{\alpha,1}((-it)^{\alpha}
D^{\beta})w_{0}\right\|_{L^{p}}<\infty,
$$
then we can construct the following result.
\begin{theorem}\label{global existence}
Let $\beta>2$, $d\geq 1$ and for $\frac{\delta-\beta}{d}<\frac{\delta}{2}-1$, assume that $g(w)=|w|^{p_{0}-2}w$ and the condition $\kappa\left(p_{0}-1\right)<1$ is satisfied. For the constant $\varepsilon>0$ is small enough, the E.q. \eqref{Eq:F-T-S-E} has a unique global mild solution in $X_{p_{0}}^{\kappa}$ when the initial $\left\|w_{0}\right\|_{X_{0}}\lesssim \varepsilon$. If $u,w$ are respectively the two mild solutions of E.q. \eqref{Eq:F-T-S-E} with the initial data $w_{0}$ and $u_{0}$, we have that $\left\|w-u\right\|_{X_{p_{0}}^{\kappa}}\lesssim \left\|w_{0}-u_{0}\right\|_{X_{0}}$.
\end{theorem}
\begin{remark}
The assumption condition in Theorem \ref{global existence}, $\kappa(p_{0}-1) < 1$, is reasonable. For example, let $p^{*}$ be the positive real root of the equation
\[
dx^2 - (3d + \beta)x + 2d = 0.
\]
For $d = 3$, $\beta \in \left(2, \frac{9}{2}\right)$, and $\alpha \in \left(0, \frac{3}{8}\right)$, by calculation, we have
\[
\frac{d-\beta}{2d}<\frac{1}{p_{0}}<\frac{1}{p^{*}},
\]
which ensures that the condition $\kappa(p_{0}-1) < 1$ is satisfied.
\end{remark}
\begin{proof}
Consider the Banach space
\[
\Xi_{\varepsilon} = \left\{ w \in X_{p_{0}}^{\kappa} : \quad \left\| w \right\|_{X_{p_{0}}^{\kappa}} \lesssim \varepsilon \right\},
\]
equipped with the norm metric
\[
\left\| w - v \right\|_{X_{p_{0}}^{\kappa}} = \sup_{0 < t < \infty} t^{\kappa} \left\| w(t) - v(t) \right\|_{p_{0}}.
\]
Define the operator
$$
\Psi(w)=E_{\alpha,1}((-it)^{\alpha}D^{\beta})w_{0}(x) + i^{-\alpha}
\int_{0}^{t}(t-s)^{\alpha-1}E_{\alpha,\alpha}((-i(t-s))^{\alpha}D^{\beta})g(w(s,x)) \, ds,
$$
where $g\left(w\right)=\left|w\right|^{p_{0}-2}w$.
From the Lemma \ref{Mittag-Leffer operator estimate}, we obtain that
\begin{align*}
\left\|\Psi(w)\right\|_{p_{0}}&\lesssim \left\|E_{\alpha,1}((-it)^{\alpha}D^{\beta})w_{0}\right\|_{p_{0}}
+\int_{0}^{t}(t-s)^{\alpha-1}\left\|E_{\alpha,\alpha}((-i(t-s))^{\alpha}D^{\beta})g(w(s,\cdot))\right\|_{p_{0}}ds\\
&\lesssim \left\|E_{\alpha,1}((-it)^{\alpha}D^{\beta})w_{0}\right\|_{p_{0}}+\int_{0}^{t}\left(t-s\right)^{\alpha-1-\frac{\alpha d}{\beta}\left(\frac{1}{p_{0}'}-\frac{1}{p_{0}}\right)}\left\|g(w(s,\cdot))\right\|_{p_{0}'}ds\\
&\lesssim \left\|E_{\alpha,1}((-it)^{\alpha}D^{\beta})w_{0}\right\|_{p_{0}}+\int_{0}^{t}\left(t-s\right)^{\alpha-1-\frac{\alpha d}{\beta}\left(\frac{1}{p_{0}'}-\frac{1}{p_{0}}\right)}\left\|w\left(s,\cdot\right)\right\|^{p_{0}-1}_{p_{0}}ds\\
&\lesssim \left\|E_{\alpha,1}((-it)^{\alpha}D^{\beta})w_{0}\right\|_{p_{0}}+\int_{0}^{t}\left(t-s\right)^{\alpha-1-\frac{\alpha d}{\beta}\left(\frac{1}{p_{0}'}-\frac{1}{p_{0}}\right)}s^{-\kappa\left(p_{0}-1\right)}ds\left\|w\right\|_{X_{p_{0}}^{\kappa}}^{p_{0}-1}\\
&\lesssim \left\|E_{\alpha,1}((-it)^{\alpha}D^{\beta})w_{0}\right\|_{p_{0}}+t^{-\kappa}B_{\kappa}\left\|w\right\|_{X_{p_{0}}^{\kappa}}^{p_{0}-1},
\end{align*}
where the constant
$$
B_{\kappa}=B\left(\alpha-\frac{\alpha d}{\beta}(\frac{1}{p_{0}'}-\frac{1}{p_{0}}),1-\kappa(p_{0}-1)\right).
$$
Therefore, we obtain that $\left\|\Psi(w)\right\|_{X_{p_{0}}^{\kappa}}\lesssim \varepsilon$ when the initial $\left\|w_{0}\right\|_{X_{0}}\lesssim \varepsilon$ is small enough, and the operator $\Psi$ maps $\Xi_{\varepsilon}$ to $\Xi_{\varepsilon}$.

Moreover, for any $w,v\in\Xi_{\varepsilon}$ and small $\varepsilon>0$, we obtain that
\begin{align*}
&t^{\kappa}\left\|\Psi(w)-\Psi(v)\right\|_{p_{0}}\\
&\lesssim t^{\kappa}\int_{0}^{t}\left(t-s\right)^{\alpha-1-\frac{\alpha d}{\beta}(\frac{1}{p_{0}'}-\frac{1}{p_{0}})}\left\|g(w(s))-g(v(s))\right\|_{p_{0}'}ds\\
&\lesssim t^{\kappa}\int_{0}^{t}\left(t-s\right)^{\alpha-1-\frac{\alpha d}{\beta}(\frac{1}{p_{0}'}-\frac{1}{p_{0}})}\left(\left\|w(s)\right\|^{p_{0}-2}_{p_{0}}+\left\|v(s)\right\|^{p_{0}-2}_{p_{0}}\right)
\left\|w(s)-v(s)\right\|_{p}ds\\
&\lesssim t^{\kappa}\int_{0}^{t}\left(t-s\right)^{\alpha-1-\frac{\alpha d}{\beta}(\frac{1}{p_{0}'}-\frac{1}{p_{0}})}s^{-\kappa(p_{0}-1)}
\left((s^{\kappa}\left\|w(s)\right\|_{p_{0}})^{p_{0}-2}+(s^{\kappa}\left\|v(s)\right\|_{p_{0}})^{p_{0}-2}\right)
(s^{\kappa}\left\|w(s)-v(s)\right\|_{p_{0}})ds\\
&\lesssim 2^{p_{0}-2}B_{\kappa}\varepsilon^{p_{0}-2}\left\|w-v\right\|_{X_{p_{0}}^{\kappa}}<\frac{1}{2}\left\|w-v\right\|_{X_{p_{0}}^{\kappa}}.
\end{align*}
We get that
$$
\left\|\Psi(w)-\Psi(v)\right\|_{X_{p_{0}}^{\kappa}}<\frac{1}{2}\left\|w-v\right\|_{X_{p_{0}}^{\kappa}}.
$$
The operator $\Psi$ exist the unique fixed point on $\Xi_{\kappa}$ by Banach contraction mapping theorem, which is the mild solution of E.q. \eqref{Eq:F-T-S-E}.

Therefore, for two solutions $w,v$ with the initial data $w_{0}$ and $v_{0}$, respectively, similar the above process, we obtain that
\begin{align*}
\left\|w-v\right\|_{X_{p_{0}}^{\kappa}}&\lesssim \left\|w_{0}-v_{0}\right\|_{X_{0}}+2^{p_{0}-2}B_{\kappa}\varepsilon^{p_{0}-2}\left\|w-v\right\|_{X_{p_{0}}^{\kappa}}\\
&\lesssim\left\|w_{0}-v_{0}\right\|_{X_{0}}+\frac{1}{2}\left\|w-v\right\|_{X_{p_{0}}^{\kappa}},
\end{align*}
this implies that $\left\|w-v\right\|_{X_{0}^{\kappa}}\lesssim \left\|w_{0}-v_{0}\right\|_{X_{0}}$.
The proof is now completed.
\end{proof}
Next we construct the local existence of E.q. \eqref{Eq:F-T-S-E} for case $2<\beta<\infty$.

For $2\leq p<\infty$, $T>0$, we consider the following Banach space
$$
Y^{\nu}_{p}=\left\{w:\left(0,T\right)\rightarrow L^{p}(\mathbb{R}^{d})/\quad \sup_{0<t<T}t^{\nu}\left\|w(t)\right\|_{p}<\infty\right\}\text{ with }\nu=\frac{\alpha d}{\beta}\left(\frac{1}{p'}-\frac{1}{p}\right),
$$
then we have the following result.
\begin{theorem}\label{local existence}
Let $\beta>2$, $d\geq 1$ and for $\frac{\delta-\beta}{d}<\frac{\delta}{2}-1$, assume that $g(w)=|w|^{p_{0}-2}w$ and the condition $\nu\left(p_{0}-1\right)<\alpha$ is satisfied. For any $w_{0}\in L^{p_{0}'}(\mathbb{R}^{d})$, there exist $T>0$ such that E.q. \eqref{Eq:F-T-S-E} has a unique local mild solution in $Y_{p_{0}}^{\nu}$. If $w,v$ are respectively the two local mild solutions of E.q. \eqref{Eq:F-T-S-E} with the initial data $w_{0}$ and $v_{0}$, we have that $\left\|w-v\right\|_{Y_{p_{0}}^{\nu}}\lesssim \left\|w_{0}-v_{0}\right\|_{p_{0}'}$.
\end{theorem}
\begin{remark}
The assumption condition in Theorem \ref{local existence}, $\nu(p_{0}-1) < \alpha$, is reasonable. For example, let $p^{*}$ be the positive real root of the equation
\[
dx^2 - (3d + \beta)x + 2d = 0.
\]
For $d = 3$, $\beta>\frac{9}{2}$, and $\alpha\in\left(\frac{3}{8},1\right)$, by calculation, we have
\[
\frac{d-\beta}{2d}<\frac{1}{p^{*}}<\frac{1}{p_{0}},
\]
which ensures that the condition $\nu(p_{0}-1) < \alpha$ is satisfied.
\end{remark}
\begin{proof}
For $T>0$, we consider the operator $\Psi$, that is
$$
\Psi(w)=E_{\alpha,1}((-it)^{\alpha}D^{\beta})w_{0}(x) + i^{-\alpha}
\int_{0}^{t}(t-s)^{\alpha-1}E_{\alpha,\alpha}((-i(t-s))^{\alpha}D^{\beta})g(w(s,x)) \, ds, \text{ }t\in[0,T].
$$
By using Lemma \ref{Mittag-Leffer operator estimate}, we obtain that
\begin{align*}
\left\|E_{\alpha,1}((-it)^{\alpha}D^{\beta})w_{0}(\cdot)\right\|_{Y_{p_{0}}^{\nu}}=\sup_{t\in(0,T)}t^{\nu}
\left\|E_{\alpha,1}((-it)^{\alpha}D^{\beta})w_{0}(\cdot)\right\|_{L^{p_{0}}}\lesssim \left\|w_{0}\right\|_{L^{p_{0}'}},
\end{align*}
and
\begin{align*}
&\left\|\int_{0}^{t}(t-s)^{\alpha-1}E_{\alpha,\alpha}((-i(t-s))^{\alpha}D^{\beta})g(w(s,x)) \, ds\right\|_{Y_{p_{0}}^{\nu}}\\
&\lesssim \sup_{t\in(0,T)}t^{\nu}\int_{0}^{t}(t-s)^{\alpha-1-\frac{\alpha d}{\beta}(1-\frac{2}{p_{0}})}\left\|w(s)\right\|_{L^{p_{0}}}^{p_{0}-1}ds\\
&\leq CT^{\alpha-\nu(p_{0}-1)}B(\alpha-\nu,\nu(p_{0}-1))\left\|w\right\|_{Y_{p_{0}}^{\nu}}^{p_{0}-1}.
\end{align*}
Since $w_{0}\in L^{p_{0}'}(\mathbb{R}^{d})$, we can choose constant $M>0$ such that $\left\|w_{0}\right\|_{p_{0}'}\leq \frac{M}{2C}$. Let us consider the closed ball $B_{M}$ in $Y_{p_{0}}^{\nu}$, that is
$$
B_{M}=\left\{w\in Y_{p_{0}}^{\nu}:\quad \left\|w\right\|_{Y_{p_{0}}^{\nu}}\leq M\right\}.
$$
we choose the constant $T>0$ such that
$$
2CT^{\alpha-\nu(p_{0}-1)}B(\alpha-\nu,\nu(p_{0}-1))M^{p_{0}-2}<1,
$$
hence we can get that for $w\in B_{M}$,
\begin{align*}
\left\|\Psi(w)\right\|_{Y_{p_{0}}^{\nu}}\leq C\frac{M}{2C}+CT^{\alpha-\nu(p_{0}-1)}B(\alpha-\nu,\nu(p_{0}-1))M^{p_{0}-1}\leq \frac{M}{2}+\frac{M}{2}=M,
\end{align*}
and for any $w,v\in Y_{p_{0}}^{\nu}$,
\begin{align*}
\left\|\Psi(w)-\Psi(v)\right\|_{Y_{p_{0}}^{\nu}}&\leq 2CT^{\alpha-\nu(p_{0}-1)}B(\alpha-\nu,\nu(p_{0}-1))M^{p-2}\left\|w-v\right\|_{Y_{p_{0}}^{\nu}}\\
&<\left\|w-v\right\|_{Y_{p_{0}}^{\nu}},
\end{align*}
The Theorem \ref{local existence} is now completed by the Banach fixed point theorem.
\end{proof}
\subsubsection{The case $\beta<2$}
When $\beta <2$, Lemma \ref{Mittag-Leffer operator estimate} is no longer applicable, and we cannot establish the well-posedness using the methods in Theorem \ref{global existence} and Theorem \ref{local existence}. Inspired by \cite{Kenig,Grande}, we establish the following local well-posedness result.

\begin{theorem}\label{local-well-posedness}
Let $d=1$, $\beta > \frac{\delta+1}{2}$, $1<\delta < \frac{3}{2}$, $\varsigma=\frac{1}{2} - \frac{1}{2(p-2)}$, and $s\geq\varsigma$, where $p \geq 4$ is an even integer. If the initial value $w_{0} \in H^{s}(\mathbb{R})$, then there exists $T = T(\left\|w_{0}\right\|_{H^{s}(\mathbb{R})})$ such that the E.q.\eqref{Eq:F-T-S-E} has a unique mild solution $w \in C(0, T; H^{s}(\mathbb{R}))$ satisfying
\begin{align}
\label{regularity1} \left\|\langle D \rangle^{\sigma} w\right\|_{L^{\infty}_{x}L^{2}_{T}} &< \infty,\\
\label{regularity2} \left\|\langle D \rangle^{s} w\right\|_{L^{\infty}_{T}L^{2}_{x}} &< \infty, \\
\label{regularity3} \left\|w\right\|_{L^{2(p-2)}_{x}L^{\infty}_{T}} &< \infty, \\
\label{regularity4} \left\|\langle D \rangle^{\theta(s + \delta - \beta)} w\right\|_{L^{\frac{2(p-2)}{1-\theta}}_{x}L^{\frac{2}{\theta}}_{T}} &< \infty,\\
\label{regularity5} \left\|\langle D \rangle^{(1-\theta)(s + \delta - \beta)} w\right\|_{L^{\frac{2(p-2)}{\theta}}_{x}L^{\frac{2}{1-\theta}}_{T}} &< \infty,
\end{align}
where $\sigma=s + (3\delta - 1)/4- \beta/2$, $\theta\in\big(\gamma/(\varsigma+\gamma),\varsigma/(\varsigma+\gamma)\big)$.
\end{theorem}
\begin{remark}
We can choose $\frac{1+\sqrt{1+12\beta}}{6} < \alpha < 1$ such that
$\delta + 1 <2\beta<3\alpha$.
Therefore, the condition $\frac{\delta + 1}{2} < \beta$ and $\delta < \frac{3}{2}$ is reasonable.
\end{remark}
\begin{proof}
Define the operator $\Psi(w)$ as in \eqref{mild solution}. Similar to Kenig \cite[\emph{Commun. Pure Appl. Math.}]{Kenig}, without loss of generality, we only consider the case $s \in [\varsigma, \frac{3}{4})$. Once this result is established, the proof for $s \geq \frac{3}{4}$ becomes simpler, as in our estimates, the highest derivatives always appear linearly. The verification that $\Psi(w) \in C(0, T; H^{s}(\mathbb{R}))$ can be found in \cite{Grande}. Furthermore, based on Lemma \ref{find Mild solution}, up to a constant, we have that
\begin{align*}
\Psi(w)&\sim \left(e^{-itD^{\delta}} + \int_{0}^{\infty}
\frac{e^{-rtD^{\delta}}r^{\alpha-1}}
{i^{\alpha}r^{2\alpha} - 2r^{\alpha}\cos(\alpha\pi) + (-i)^{\alpha}} \, dr\right) w_{0}(x)\\\notag
&\quad + i^{-\alpha} \int_{0}^{t} \left(D^{\delta-\beta}
e^{-i(t-s)D^{\delta}} + \int_{0}^{\infty} \frac{D^{\delta-\beta}
e^{-r(t-s)D^{\delta}} r^\alpha}{i^{\alpha}r^{2\alpha} - 2r^\alpha \cos(\alpha\pi) + (-i)^{\alpha}} \, dr \right) g(w(s,x)) \, ds.
\end{align*}
Consider the following Banach space:
\[
\Theta_{T} = \left\{ w \in C\left(0, T; H^{s}(\mathbb{R})\right) : \lambda(w) = \max_{j=1,2,3,4,5} \lambda_{j}(w) < \infty \right\},
\]
where $\lambda_{1}(w)$, $\lambda_{2}(w)$, $\lambda_{3}(w)$, $\lambda_{4}(w)$, and $\lambda_{5}(w)$ are defined as in \eqref{regularity1}-\eqref{regularity5}.

Next, we sequentially estimate $\lambda_{j}(\Psi(w))$ for $j = 1, 2, 3, 4, 5$.

We choose $\gamma' = (5\delta - 2\beta - 3)/8$. Noting that $\gamma' - \delta + \beta < (\delta - 1)/2$ and setting $\nu' = \gamma' - \delta + \beta$, we have $0<\sigma-\gamma<\sigma-\gamma'<s$ and $0<\sigma-\nu<\sigma-\nu'<s+\delta-\beta$.

By \eqref{smoothing 1}, \eqref{smoothing 9}, \eqref{smoothing 10}, \eqref{smoothing 11}, \eqref{smoothing 12}, \eqref{smoothing 13}, \eqref{smoothing 14}, and \eqref{smoothing 15}, we obtain
\begin{align*}
\lambda_{1}\left(\Psi(w)\right) &\lesssim \left(1 + T^{\frac{1}{2}} + T^{\frac{\gamma - \gamma'}{\delta}}\right)\left\|w_{0}\right\|_{L^{2}_{x}}+\left\|D^{\sigma-\gamma}w_{0}\right\|_{L^{2}_{x}}+T^{\frac{\gamma-\gamma'}{\delta}}
\left\|D^{\sigma-\gamma'}w_{0}\right\|_{L^{2}_{x}}\\
&\quad+ \left(T^{\frac{1}{2}} + T + T^{\frac{\nu}{\delta} + \frac{1}{2}}+T^{\frac{\nu-\nu'}{\delta} + \frac{1}{2}}\right) \left\|(|w|^{p-2} w)\right\|_{L^{2}_{T,x}}+T^{\frac{1}{2}}\big\|D^{\sigma-\nu}(|w|^{p-2}w)\big\|_{L^{2}_{T,x}}\\
&\quad+T^{\frac{\nu-\nu'}{\delta} + \frac{1}{2}}\big\|D^{\sigma-\nu}(|w|^{p-2}w)\big\|_{L^{2}_{T,x}}\\
&\lesssim \left(1 + T^{\frac{1}{2}} + T^{\frac{\gamma - \gamma'}{\delta}}\right) \left\|\langle D \rangle^{s} w_{0}\right\|_{L^{2}_{x}} + \left(T^{\frac{1}{2}} + T + T^{\frac{\nu}{\delta} + \frac{1}{2}}+T^{\frac{\nu-\nu'}{\delta}
+ \frac{1}{2}}\right) \left\|\langle D \rangle^{s + \delta - \beta} (|w|^{p-2} w)\right\|_{L^{2}_{T,x}}.
\end{align*}

By \eqref{smooth 1}, \eqref{smooth 2}, \eqref{smooth 3}, and \eqref{smooth 4}, similar the estimate of $\lambda_{1}\left(\Psi(w)\right)$, we have
\begin{align*}
\lambda_{2}\left(\Psi(w)\right) &\lesssim \left\|\langle D \rangle^{s} w_{0}\right\|_{L^{2}_{x}} + \left(T^{\frac{1}{2}} + T^{\frac{3\alpha-2}{4}}\right) \left\|\langle D \rangle^{s + \delta - \beta} (|w|^{p-2} w)\right\|_{L^{2}_{T,x}}.
\end{align*}

By \eqref{smoothing 16}, \eqref{smoothing 17}, \eqref{smoothing 18}, and \eqref{smoothing 19}, we obtain
\begin{align*}
\lambda_{3}\left(\Psi(w)\right) &\lesssim \left\|\langle D \rangle^{s} w_{0}\right\|_{L^{2}_{x}} + \left(T^{\frac{1}{2}} + T^{\alpha - \frac{1}{2}}\right) \left\|\langle D \rangle^{s + \delta - \beta} (|w|^{p-2} w)\right\|_{L^{2}_{T,x}}.
\end{align*}

By \eqref{smoothing 20}, \eqref{smoothing 21}, \eqref{smoothing 22}, and \eqref{smoothing 23}, we have
\begin{align*}
&\lambda_{4}\left(\Psi(w)\right)\\&\lesssim \left(1 + T^{\frac{(\gamma - \gamma')\theta}{\delta}}\right) \left\|\langle D \rangle^{s - \theta \nu'} w_{0}\right\|_{L^{2}_{x}} + \left(T^{\frac{1}{2}} + T^{\frac{1-2(1-\alpha)(1-\theta)}{2}+\frac{(\nu-\nu')\theta}{\delta}}\right) \left\|\langle D \rangle^{s + \delta - \beta - \theta \nu'} (|w|^{p-2} w)\right\|_{L^{2}_{T,x}} \\
&\lesssim \left(1 + T^{\frac{(\gamma - \gamma')\theta}{\delta}}\right) \left\|\langle D \rangle^{s} w_{0}\right\|_{L^{2}_{x}} + \left(T^{\frac{1}{2}} + T^{\frac{1-2(1-\alpha)(1-\theta)}{2}+\frac{(\nu-\nu')\theta}{\delta}}\right) \left\|\langle D \rangle^{s + \delta - \beta} (|w|^{p-2} w)\right\|_{L^{2}_{T,x}}.
\end{align*}

Similarly,
\begin{align*}
&\lambda_{5}\left(\Psi(w)\right)\\
 &\lesssim\left(1 + T^{\frac{(\gamma - \gamma')(1-\theta)}{\delta}}\right) \left\|\langle D \rangle^{s} w_{0}\right\|_{L^{2}_{x}} + \left(T^{\frac{1}{2}} + T^{\frac{1-2(1-\alpha)\theta}{2}+\frac{(\nu-\nu')(1-\theta)}{\delta}}\right) \left\|\langle D \rangle^{s + \delta - \beta} (|w|^{p-2} w)\right\|_{L^{2}_{T,x}}.
\end{align*}

Noting that $s + \delta - \beta \in (0, 1)$ and $s + \delta - \beta<\sigma$, by Proposition \ref{Leibnitz rule}, we obtain
\begin{align*}
\left\|\langle D \rangle^{s + \delta - \beta} (|w|^{p-2} w)\right\|_{L^{2}_{T,x}} &\lesssim \left\|(\langle D \rangle^{s + \delta - \beta} (|w|^{p-2})) w\right\|_{L^{2}_{T,x}} + \left\|(\langle D \rangle^{s + \delta - \beta} w) |w|^{p-2}\right\|_{L^{2}_{T,x}} \\
&\quad + \left\|\langle D \rangle^{\theta (s + \delta - \beta)} w\right\|_{L^{\frac{2(p-2)}{1-\theta}}_{x} L^{\frac{2}{\theta}}_{T}} \left\|\langle D \rangle^{(1 - \theta) (s + \delta - \beta)} |w|^{p-2}\right\|_{L^{\eta}_{x} L^{\frac{2}{1-\theta}}_{T}},
\end{align*}
where $\eta = \frac{p + \theta - 3}{2(p - 2)}$. Thus, we have
\begin{align*}
\left\|\langle D \rangle^{(1 - \theta) (s + \delta - \beta)} |w|^{p-2}\right\|_{L^{\eta}_{x} L^{\frac{2}{1-\theta}}_{T}} &\lesssim \left\||w|^{p-3}\right\|_{L^{\frac{2(p-2)}{p-3}}_{x} L^{\infty}_{T}} \left\|\langle D \rangle^{(1 - \theta) (s + \delta - \beta)} w\right\|_{L^{\frac{2(p-2)}{\theta}}_{x} L^{\frac{2}{1-\theta}}_{T}} \\
&\lesssim \lambda_{3}(w)^{p-3} \lambda_{5}(w),
\end{align*}
\begin{align*}
\left\|(\langle D \rangle^{s + \delta - \beta} w) |w|^{p-2}\right\|_{L^{2}_{T,x}} &\lesssim \left\|\langle D \rangle^{s + \delta - \beta} w\right\|_{L^{\infty}_{x} L^{2}_{T}} \left\|w\right\|_{L^{2(p-2)}_{x} L^{\infty}_{T}}^{p-2} \\
&\lesssim \lambda_{1}(w) \lambda_{3}(w)^{p-2},
\end{align*}
and
\begin{align*}
\left\|(\langle D \rangle^{s + \delta - \beta} (|w|^{p-2})) w\right\|_{L^{2}_{T,x}} &\lesssim \left\|w\right\|_{L^{2(p-2)}_{x} L^{\infty}_{T}} \left\|\langle D \rangle^{s + \delta - \beta} |w|^{p-2}\right\|_{L^{\frac{2(p-2)}{p-3}}_{x} L^{2}_{T}} \\
&\lesssim \left\|w\right\|_{L^{2(p-2)}_{x} L^{\infty}_{T}}^{p-3} \left\|\langle D \rangle^{\theta (s + \delta - \beta)} w\right\|_{L^{\frac{2(p-2)}{1-\theta}}_{x} L^{\frac{2}{\theta}}_{T}} \left\|\langle D \rangle^{(1 - \theta) (s + \delta - \beta)} w\right\|_{L^{\frac{2(p-2)}{\theta}}_{x} L^{\frac{2}{1-\theta}}_{T}} \\
&\quad + \left\|w\right\|_{L^{2(p-2)}_{x} L^{\infty}_{T}}^{p-2} \left\|\langle D \rangle^{s + \delta - \beta} w\right\|_{L^{\infty}_{x} L^{2}_{T}} \\
&\lesssim \lambda_{3}(w)^{p-3} \lambda_{4}(w) \lambda_{5}(w) + \lambda_{3}(w)^{p-2} \lambda_{1}(w),
\end{align*}
where we have used Remark \ref{A.S.I.E}. Therefore, summarizing the above estimates, we have
\begin{align*}
\left\|\langle D \rangle^{s + \delta - \beta} (|w|^{p-2} w)\right\|_{L^{2}_{T,x}} &\lesssim \lambda_{3}(w)^{p-3} \lambda_{4}(w) \lambda_{5}(w) + \lambda_{3}(w)^{p-2} \lambda_{1}(w) + \lambda_{1}(w) \lambda_{3}(w)^{p-2} \\
&\quad + \lambda_{3}(w)^{p-3} \lambda_{4}(w) \lambda_{5}(w) \\
&\lesssim \lambda(w)^{p-1}.
\end{align*}

Noting that $w_{0} \in H^{s}(\mathbb{R})$, there exists $R > 0$ such that $\left\|w_{0}\right\|_{H^{s}(\mathbb{R})} \leq R/(2C)$. We can choose $0 < T < 1$ such that
\[
2C \big(T + T^{\frac{1}{2}} + T^{\frac{3\alpha-2}{4}}+ T^{\alpha - \frac{1}{2}} + T^{\frac{1}{2} + \frac{\nu}{\delta}} + T^{\frac{1}{2} + \frac{\nu-\nu'}{\delta}}+ T^{\frac{1-2(1-\alpha)(1-\theta)}{2}+\frac{(\nu-\nu')\theta}{\delta}} + T^{\frac{1-2(1-\alpha)\theta}{2}+\frac{(\nu-\nu')(1-\theta)}{\delta}}\big) R^{p-2} < 1.
\]

Considering the closed ball $B(R) \subset \Theta_{T}$, we have
\begin{align*}
&\lambda\left(\Psi(w)\right)\\ &\leq C \frac{R}{2C}+\\
&\quad +  C \left(T + T^{\frac{1}{2}}
+ T^{\frac{3\alpha-2}{4}}+ T^{\alpha - \frac{1}{2}} + T^{\frac{1}{2} + \frac{\nu-\nu'}{\delta}} + T^{\frac{1-2(1-\alpha)(1-\theta)}{2}+\frac{(\nu-\nu')\theta}{\delta}} + T^{\frac{1-2(1-\alpha)\theta}{2}+\frac{(\nu-\nu')(1-\theta)}{\delta}}\right) R^{p-2} \cdot R \\
&\leq \frac{R}{2} + \frac{R}{2} = R.
\end{align*}

Furthermore, for any $v, w \in B(R)$, similar the above process, we obtain
\begin{align*}
&\lambda\left(\Psi(v) - \Psi(w)\right) \\&\leq 2C \left(T + T^{\frac{1}{2}}
+ T^{\frac{3\alpha-2}{4}}+ T^{\alpha - \frac{1}{2}} + T^{\frac{1}{2} + \frac{\nu-\nu'}{\delta}} + T^{\frac{1-2(1-\alpha)(1-\theta)}{2}+\frac{(\nu-\nu')\theta}{\delta}} + T^{\frac{1-2(1-\alpha)\theta}{2}+\frac{(\nu-\nu')(1-\theta)}{\delta}}\right)\\
&\quad\cdot \left(\lambda(v)^{p-2} + \lambda(w)^{p-2}\right) \lambda(v - w) \\
&< \lambda(v - w).
\end{align*}

Therefore, by the Banach fixed-point theorem, equation \eqref{Eq:F-T-S-E} has a unique mild solution $w \in C(0, T; H^{s}(\mathbb{R}))$ that satisfies \eqref{regularity1}-\eqref{regularity5}. The proof is completed now.
\end{proof}


\subsection{Asymptotic behavior and Self-similar solutions}
In this section, we construct the asymptotic behavior and self-similar solutions about E.q. \eqref{Eq:F-T-S-E}.
\begin{theorem}\label{asymptotic behavior}
Let $v$ and $w$ be the global solutions of Equation \eqref{Eq:F-T-S-E} as determined by Theorem \ref{global existence}, with corresponding initial values $v_{0}$ and $w_{0}$, respectively. Then,
\begin{align*}
\lim_{t\rightarrow\infty}t^{\kappa}\left\|w(t)-v(t)\right\|_{L^{p_{0}}}=0 \quad \text{if and only if} \quad \lim_{t\rightarrow\infty}t^{\kappa}\left\|E_{\alpha,1}((-it)^{\alpha}D^{\beta})(w_{0}-v_{0})\right\|_{L^{p_{0}}}=0.
\end{align*}
\end{theorem}
\begin{proof}
On the hand, if $\lim_{t\rightarrow\infty}t^{\kappa}\left\|E_{\alpha,1}((-it)^{\alpha}D^{\beta})(w_{0}-v_{0})\right\|_{L^{p_{0}}}=0$, for any $0<\varrho<1$, we can get that
\begin{align*}
&t^{\kappa}\left\|w(t)-v(t)\right\|_{L^{p_{0}}}\\
&\lesssim t^{\kappa}\left\|E_{\alpha,1}((-it)^{\alpha}D^{\beta})(w_{0}-v_{0})\right\|_{L^{p_{0}}}\\
&\quad +
t^{\kappa}\int_{0}^{t}(t-s)^{\alpha-1}\left\|E_{\alpha,\alpha}((-it)^{\alpha}D^{\beta})
\left(\left(|w(s)|^{p_{0}-2}+|v(s)|^{p_{0}-2}\right)(w(s)-v(s))\right)\right\|_{L^{p_{0}}}ds\\
&\lesssim t^{\kappa}\left\|E_{\alpha,1}((-it)^{\alpha}D^{\beta})(w_{0}-v_{0})\right\|_{L^{p_{0}}}\\
&\quad +t^{\kappa}\left(\int_{0}^{\varrho t}+\int_{\varrho t}^{t}\right)(t-s)^{\alpha-1-\frac{\alpha d}{\beta}(1-\frac{2}{p_{0}})}\left\|
\left(|w(s)|^{p_{0}-2}+|v(s)|^{p_{0}-2}\right)(w(s)-v(s))\right\|_{L^{p_{0}'}}ds\\
&\lesssim t^{\kappa}\left\|E_{\alpha,1}((-it)^{\alpha}D^{\beta})(w_{0}-v_{0})\right\|_{L^{p_{0}}}\\
&\quad +t^{\kappa}\varepsilon^{p_{0}-2}\left(\int_{0}^{\varrho t}+\int_{\varrho t}^{t}\right)(t-s)^{\alpha-1-\frac{\alpha d}{\beta}(1-\frac{2}{p_{0}})}s^{-\kappa(p_{0}-1)}\left(s^{\kappa}\left\|w(s)-v(s)\right\|_{L^{p_{0}}}\right)ds\\
&\lesssim t^{\kappa}\left\|E_{\alpha,1}((-it)^{\alpha}D^{\beta})(w_{0}-v_{0})\right\|_{L^{p_{0}}}\\
&\quad +t^{\kappa}\varepsilon^{p_{0}-2}\left(\int_{0}^{\varrho}+\int_{\varrho}^{1}\right)(1-s)^{\alpha-1-\frac{\alpha d}{\beta}(1-\frac{2}{p_{0}})}s^{-\kappa(p_{0}-1)}\left((ts)^{\kappa}\left\|w(ts)-v(ts)\right\|_{L^{p_{0}}}\right)ds,
\end{align*}
hence we have that
\begin{align*}
\overline{\lim_{t\rightarrow\infty}}t^{\kappa}\left\|w(t)-v(t)\right\|_{L^{p_{0}}}\leq C\varepsilon^{p_{0}-2}\left(1+H(\varrho)\right)\overline{\lim_{t\rightarrow\infty}}t^{\kappa}\left\|w(t)-v(t)\right\|_{L^{p_{0}}},
\end{align*}
note that the constant $\varepsilon$ is small and $\lim_{\varrho\rightarrow 0^{+}}H(\varrho)=0$, we get that
$$
\lim_{t\rightarrow\infty}t^{\kappa}\left\|w(t)-v(t)\right\|_{L^{p_{0}}}=0.
$$
On the other hand, if $\lim_{t\rightarrow\infty}t^{\kappa}\left\|w(t)-v(t)\right\|_{L^{p_{0}}}=0$, note that
\begin{align*}
&t^{\kappa}\left\|E_{\alpha,1}((-it)^{\alpha}D^{\beta})(w_{0}-v_{0})\right\|_{L^{p_{0}}}\\
&\lesssim t^{\kappa}\left\|w(t)-v(t)\right\|_{L^{p_{0}}}+t^{\kappa}\int_{0}^{t}(t-s)^{\alpha-1}\left\|E_{\alpha,\alpha}((-it)^{\alpha}D^{\beta})
\left(\left(|w(s)|^{p_{0}-2}+|v(s)|^{p_{0}-2}\right)(w(s)-v(s))\right)\right\|_{L^{p_{0}}}ds\\
&\leq C\varepsilon^{p_{0}-2}\left(1+H(\varrho)\right)\overline{\lim_{t\rightarrow \infty}}t^{\kappa}\left\|w(t)-v(t)\right\|_{L^{p_{0}}},
\end{align*}
hence we obtain that
$$
\overline{\lim_{t\rightarrow\infty}}t^{\kappa}\left\|E_{\alpha,1}((-it)^{\alpha}D^{\beta})(w_{0}-v_{0})\right\|_{L^{p_{0}}}=0.
$$
The proof is now completed.
\end{proof}
\begin{theorem}\label{self-similar solution}
 Assume the condition Theorem {\rm\ref{global existence}} is satisfied and the initial value $w_{0}$ is a homogeneous function with homogeneity degree $-\frac{\beta}{p_{0}-2}$ and satisfies $\left\|E_{\alpha,1}((-i)^{\alpha}D^{\beta})w_{0}\right\|_{L^{p_{0}}}$ being sufficiently small. Then, the equation \eqref{Eq:F-T-S-E} admits a self-similar solution in $X_{p_{0}}^{\kappa}$, i.e., for all $\lambda > 0$,
\[
w(x,t) = \lambda^{\frac{\beta}{p-2}} w(\lambda x, \lambda^{\delta} t) \quad \text{a.e. } x \in \mathbb{R}^{d}, t > 0.
\]
\end{theorem}
\begin{proof}
Notice that $w_{0}(\lambda x) = \lambda^{-\frac{\beta}{p_{0}-2}} w_{0}(x)$. We can derive
\[
\widehat{w}_{0}(\lambda \xi) = \lambda^{-d + \frac{\beta}{p_{0}-2}} \widehat{w}_{0}(\xi),
\]
and consequently,
\begin{align}\label{Mitleffer self similar}
E_{\alpha,1}((-it)^{\alpha}D^{\beta})w_{0}(x) &= \int_{\mathbb{R}^{d}} E_{\alpha,1}((-it)^{\alpha} |\xi|^{\beta}) \widehat{w}_{0}(\xi) e^{ix \xi} d\xi \quad (\lambda \zeta = \xi) \notag \\
&= \lambda^{d} \int_{\mathbb{R}^{d}} E_{\alpha,1}((-i)^{\alpha} (\lambda^{\delta} t)^{\alpha} |\zeta|^{\beta}) \widehat{w}_{0}(\lambda \zeta) e^{i \lambda x \cdot \zeta} d\zeta \notag \\
&= \lambda^{\frac{\beta}{p_{0}-2}} E_{\alpha,1}((-i)^{\alpha} (\lambda^{\delta} t)^{\alpha} D^{\beta}) w_{0}(\lambda x).
\end{align}
Thus, for any $t > 0$,
\begin{align*}
t^{\kappa} \left\|E_{\alpha,1}((-it)^{\alpha} D^{\beta}) w_{0}(\cdot)\right\|_{L^{p_{0}}} &= \lambda^{\frac{\beta}{p_{0}-2}} t^{\kappa} \left\|E_{\alpha,1}((-i)^{\alpha} (\lambda^{\delta} t)^{\alpha} D^{\beta}) w_{0}(\lambda \cdot)\right\|_{L^{p_{0}}} \\
&= t^{\kappa} t^{-\frac{\alpha}{p_{0}-2} + \frac{\alpha d}{p \beta}} \left\|E_{\alpha,1}((-i)^{\alpha} D^{\beta}) w_{0}(\cdot)\right\|_{L^{p_{0}}} \\
&= \left\|E_{\alpha,1}((-i)^{\alpha} D^{\beta}) w_{0}(\cdot)\right\|_{L^{p_{0}}}.
\end{align*}
Therefore, when $\left\|E_{\alpha,1}((-i)^{\alpha}D^{\beta})w_{0}(\cdot)\right\|_{L^{p_{0}}}$ is sufficiently small, by Theorem \ref{global existence} and the Banach fixed-point theorem, the equation \eqref{Eq:F-T-S-E} has a unique global solution $w \in X_{p_{0}}^{\kappa}$. On the other hand, the fixed point $w \in X_{p_{0}}^{\kappa}$ must be the limit of the following Picard iteration sequence:
\begin{align*}
\overline{w}_{0}(t,x) &= E_{\alpha,1}((-it)^{\alpha} D^{\beta}) w_{0}(x), \\
\overline{w}_{1}(t,x) &= \overline{w}_{0}(t,x) + \int_{0}^{t} (t-s)^{\alpha-1} E_{\alpha,\alpha}((-i(t-s))^{\alpha} D^{\beta}) |\overline{w}_{0}(s,x)|^{p_{0}-2} \overline{w}_{0}(s,x) ds, \\
\overline{w}_{2}(t,x) &= \overline{w}_{0}(t,x) + \int_{0}^{t} (t-s)^{\alpha-1} E_{\alpha,\alpha}((-i(t-s))^{\alpha} D^{\beta}) |\overline{w}_{1}(s,x)|^{p_{0}-2} \overline{w}_{1}(s,x) ds, \\
&\vdots \\
\overline{w}_{n}(t,x) &= \overline{w}_{0}(t,x) + \int_{0}^{t} (t-s)^{\alpha-1} E_{\alpha,\alpha}((-i(t-s))^{\alpha} D^{\beta}) |\overline{w}_{n-1}(s,x)|^{p_{0}-2} \overline{w}_{n-1}(s,x) ds.
\end{align*}
Clearly, by \eqref{Mitleffer self similar}, $\overline{v}_{0}(t,x)$ satisfies the self-similar property, i.e.,
\[
\overline{w}_{0}(t,x) = \lambda^{\frac{\beta}{p_{0}-2}} \overline{w}_{0}(\lambda^{\delta} t, \lambda x).
\]
Furthermore, we can similarly obtain
\begin{align*}
&\overline{w}_{1}(t,x) \\
&= \overline{w}_{0}(t,x) + \int_{0}^{t} (t-s)^{\alpha-1} E_{\alpha,\alpha}((-i(t-s))^{\alpha} D^{\beta}) |\overline{w}_{0}(s,x)|^{p_{0}-2} \overline{w}_{0}(s,x) ds \\
&= \lambda^{\frac{\beta}{p_{0}-2}} \overline{w}_{0}(\lambda^{\delta} t, \lambda x) + \lambda^{\frac{\beta(p_{0}-1)}{p_{0}-2}} \int_{0}^{t} (t-s)^{\alpha-1} E_{\alpha,\alpha}((-i(t-s))^{\alpha} D^{\beta}) |\overline{w}_{0}(\lambda^{\delta} s, \lambda x)|^{p_{0}-2} \overline{w}_{0}(\lambda^{\delta} s, \lambda x) ds \\
&= \lambda^{\frac{\beta}{p_{0}-2}} \overline{w}_{0}(\lambda^{\delta} t, \lambda x) \\
&\quad + \lambda^{\frac{\beta(p_{0}-1)}{p_{0}-2} - \beta} \int_{0}^{t} (\lambda^{\delta} (t-s))^{\alpha-1} E_{\alpha,\alpha}((-i \lambda^{\beta} (t-s))^{\alpha} D^{\beta}) |\overline{w}_{0}(\lambda^{\delta} s, \lambda x)|^{p_{0}-2} \overline{w}_{0}(\lambda^{\delta} s, \lambda x) d(\lambda^{\delta} s) \\
&= \lambda^{\frac{\beta}{p_{0}-2}} \overline{w}_{0}(\lambda^{\delta} t, \lambda x) + \lambda^{\frac{\beta}{p_{0}-2}} \int_{0}^{\lambda^{\delta} t} (\lambda^{\delta} t - s)^{\alpha-1} E_{\alpha,\alpha}((-i (\lambda^{\delta} t - s))^{\alpha} D^{\beta}) |\overline{w}_{0}(s, \lambda x)|^{p_{0}-2} \overline{w}_{0}(s, \lambda x) ds \\
&= \lambda^{\frac{\beta}{p_{0}-2}} \overline{w}_{1}(\lambda^{\delta} t, \lambda x).
\end{align*}
This shows that $\overline{w}_{1}(t,x)$ also satisfies the self-similar property. Similarly, for any $n \in \mathbb{N}$,
\[
\overline{w}_{n}(t,x) = \lambda^{\frac{\beta}{p_{0}-2}} \overline{w}_{n}(\lambda^{\delta} t, \lambda x).
\]
Consequently, in the topology of $X_{p_{0}}^{\kappa}$,
\[
w(t,x) = \lim_{n \to \infty} \overline{w}_{n}(t,x) = \lim_{n \to \infty} \lambda^{\frac{\beta}{p_{0}-2}} \overline{w}_{n}(\lambda^{\delta} t, \lambda x) = \lambda^{\frac{\beta}{p_{0}-2}} w(\lambda^{\delta} t, \lambda x).
\]
The proof is completed now.
\end{proof}
\section{Conclusion}
In this paper, we consider the local and global well-posedness of the \(\mu=\alpha\) type space-time fractional Schr\"{o}dinger equation with power-type nonlinearity, where the linear part is consistent with the equation proposed by Naber. Due to the derivative loss in the solution operator, this equation is fundamentally different from the \(\mu=1\) type space-time fractional Schr\"{o}dinger equation studied in \cite{Su2}. We adopt a strategy similar to the smoothing effects used by Kenig et al. in their study of the Korteweg-de Vries equation, combined with the fractional Leibniz rule established by Kenig and other harmonic analysis methods, to establish the local well-posedness of E.q.\eqref{Eq:F-T-S-E} in $C(0,T;H^{s})$ when \(\beta < 2\) and \(d = 1\). It is worth noting that this method is only effective for \(d = 1\), and due to the limitations imposed by the fractional heat kernel, the global well-posedness for \(\beta < 2\) remains unclear, which is worthy of further discussion. Furthermore, because the H\"{o}rmander multiplier theorem is not applicable due to the derivative loss in the solution operator, we generalize a regularity result for oscillatory integrals established by Ponce in the study of the Korteweg-de Vries equation equation to higher dimensions. By combining real interpolation techniques, we establish $\mathcal{H}^{b}-\mathcal{H}^{a}$ estimates for the operator $D^{\delta-\beta}\exp(-it^{\alpha}D^{\delta})$. Subsequently, combined with harmonic analysis methods such as time-space estimates for the fractional heat kernel, we prove the global and local well-posedness of mild solutions in the space $X_{p_{0}}^{\kappa}$ for space dimensions $d \geq 1$ and $\beta > 2$. On the other hand, adjusting the value of $\alpha$ to $\alpha\in (1,2)$ allows establishing a connection or transition between the Schr\"{o}dinger equation and the classical wave equation, while ensuring that the resulting equation remains within the class of dispersive equations. These equations are characterized by the distinctive phenomenon where different frequency components of waves propagate at distinct speeds. Consequently, in subsequent research, we will investigate the existence of solutions for Equation \eqref{Eq:F-T-S-E} with $\alpha\in(1,2)$.


