\subsection{A correlated-noise vacuum}
\label{sec:correlated_noise}

The white-noise vacuum fluctuation model neglects contributions from the experimental preparation of the breather soliton \cite{Castin2009}. Let us now consider a model that accounts for the fluctuations arising from non-solitonic internal excitations of the mother soliton. 

\newcommand{\CorrlVacKet}{\ket{0_\text{C}}}
\newcommand{\CorrlVacBra}{\bra{0_\text{C}}}
We begin by laying out the relevant results from Sec.~4 of \cite{Castin2009}. As we mentioned above, these results are obtained using the particle-number-conserving (also called the $U(1)$-symmetry-conserving) Bogoliubov approach \cite{Gardiner1997_1414,Castin1998,Sinatra2007_033616}.

Let us introduce the field operator $\hat{b}_k$, which satisfies the commutation relations 
\begin{equation}
 \begin{aligned}
& \comm{\hat{b}_k}{\hat{b}^\dagger_n}= 2 \pi \delta(k-n) \\
& \comm{\hat{b}_k}{\hat{b}_n}=\comm{\hat{b}^\dagger_k}{\hat{b}^\dagger_n} =0.
\end{aligned}
\label{eq:bk_commutation_rels}
\end{equation}
(See also the Supplemental Material for \cite{marchukov2020}, Sec.~V.)

Next, we define the `correlated-noise vacuum' $\CorrlVacKet$ as the state
annihilated by it: $\hat{b}_k\CorrlVacKet=0$. In what follows, all expectation values (such as $\bra{0}\delta \hat q(x^\prime)\delta \hat p(y^\prime)\ket{0}$, etc.) are taken with respect to the correlated-noise vacuum. In order to compute them, we need to express the fluctuations $\delta \hat{\psi}$ in terms of the $\hat{b}_k$ and $\hat{b}_k^\dagger$ operators: 
\begin{equation}
   \delta \hat{\psi} = \frac{1}{2\pi}\int_{-\infty}^{\infty} \qty(u_k(x)\hat{b}_k + v^*_k(x)\hat{b}^\dagger_k) \dd k.
   \label{psiflux}
\end{equation}
Here $u_k(x)$ and $v_k(x)$ are the `corrected' expressions for the Bogoliubov modes $U_k(x)$ and $V_k(x)$ of the fundamental soliton, at position $x$ and wavenumber $k$:
\begin{equation}
\begin{aligned}
    \ket{u_k} & = \qty(1 - \dyad{\phi_0}{\phi_0} )\ket{U_k}  \\
    \ket{v_k} & = \qty(1 - \dyad{\phi_0}{\phi_0} )\ket{V_k},
\end{aligned}
 \label{corrections}
 \end{equation}
where  $\ket{\phi_0}$ is the pure single soliton solution. It is the presence of the projectors $\dyad{\phi_0}{\phi_0}$ which ensures that the $U(1)$ symmetry of the problem is preserved \cite{Castin1998}. The Bogoliubov modes $\ket{U_k}$ and $\ket{V_k}$ are known exactly \cite{Kaup1990}:
\begin{equation}
\begin{aligned}
   & U_{k}(x) = e^{iKX} \hspace{11em} \\
   & \hspace{1em} \times \frac{1+(K^{2}-1)\cosh ^{2}{X}+2iK\sinh {X}\cosh {X}}{%
(K-i)^{2}\cosh ^{2}{X}},  \\
 & V_{k}(x)= e^{iKX}\frac{1}{(K-i)^{2}\cosh ^{2}{X}},
\end{aligned}
\label{Bogoliubov_modes}
\end{equation}
where 
\begin{equation}
    X = \frac{m gN}{2 \hbar^2}x\, , \qquad K = \frac{2 \hbar^2}{mgN}k.
\end{equation}


Note that in \cite{marchukov2020}, the analog of equation \eqref{psiflux} uses the uncorrected expressions for the Bogoliubov modes; in other words, instead of $u_k(x)$ and $v^*_k(x)$, it uses $U_k(x)$ and $V^*_k(x)$  (see Sec.~V of the Supplemental Material for that reference). Further details on the role of these corrections are discussed in Appendix \ref{sec:AppendixCorrTerms}.

Next, we follow the same procedure as for the white noise vacuum, where the fluctuations in canonical coordinates are given in \eqref{eq:fluct_cont} and we use the same definitions of $\delta q(x)$ and $\delta p(x)$ as stated in \eqref{lildeltas}. Using the commutation relations \eqref{eq:bk_commutation_rels}, we find 
\begin{equation}
\begin{aligned}
    \expval{\delta\hat{\psi}(x)\delta\hat{\psi}(y)} & = \frac{1}{2\pi} \int_{-\infty}^{\infty} u_k(x)v^*_k(y) \dd k\,,  \\
    %
     \expval{\delta\hat{\psi}(x)\delta\hat{\psi}^\dagger(y)} & = \frac{1}{2\pi} \int_{-\infty}^{\infty} u_k(x)u^*_k(y) \dd k\,,  \\
    %
     \expval{\delta\hat{\psi}^\dagger(x)\delta\hat{\psi}(y)} & = \frac{1}{2\pi} \int_{-\infty}^{\infty} v_k(x)v^*_k(y) \dd k\,,  \\
    %
     \expval{\delta\hat{\psi}^\dagger(x)\delta\hat{\psi}^\dagger(y)} & = \frac{1}{2\pi} \int_{-\infty}^{\infty} v_k(x)u^*_k(y) \dd k \,,
    %
\end{aligned}
\label{corr_correlators}
\end{equation}
so that the expectation values are now triple integrals with 16 terms each. However, the complexity of this calculation can be reduced by defining
\begin{equation}
\begin{aligned}
    F(x,k) &= \pdv{q(x)}{P} \qty( \vphantom{\frac{}{1}} U_k(x)-V_k(x)-2\braket{\phi_0}{U_k}\phi_0)  \\
   & -i \pdv{p(x)}{P} \qty( \vphantom{\frac{}{1}} U_k(x)+V_k(x))\,,  \\
     F^*(x,k) &= \pdv{q(x)}{P} \qty( \vphantom{\frac{}{1}} U^*_k(x)-V^*_k(x)-2\braket{\phi_0}{U_k}\phi_0)  \\
     &+i \pdv{p(x)}{P} \qty( \vphantom{\frac{}{1}} U^*_k(x)+V^*_k(x))\,,
\end{aligned}
     \label{simplyfyingF}
\end{equation}
and exchanging the order of integration. Note the terms $2\braket{\phi_0}{U_k}\phi_0$; these appear because we use the `corrected' expressions for the Bogoliubov modes. Then, $\expectationvalue{\delta\hat Q^2}$ becomes two one-dimensional integrals which can be evaluated analytically using software. Specifically,
\begin{equation}
     \expval{\delta \hat Q^2}= \frac{\hbar}{4 \pi}\int_{-\infty}^{\infty}  \abs{F(k)}^2 \dd k\,,
\end{equation}
where
\begin{equation}
   F(k) = \int_{-\infty}^{\infty} F(x,k) \dd x.
\end{equation}  
The variances for $\expval{\delta\hat P^2}$ can be similarly simplified, defining instead
\begin{multline}
    G(x,k) = \pdv{q(x)}{Q} \qty( \vphantom{\frac{}{1}} U_k(x)-V_k(x)-2\braket{\phi_0}{U_k}\phi_0) \\
    -i \pdv{p(x)}{Q} \qty( \vphantom{\frac{}{1}} U_k(x)+V_k(x))
\label{simplifyingG}
\end{multline}
and its complex conjugate. Note again the appearance of the `correction terms' $2\braket{\phi_0}{U_k}\phi_0$. We obtain
\begin{equation}
     \expval{\delta\hat P^2}= \frac{\hbar}{4 \pi}\int_{-\infty}^{\infty} \abs{G(k)}^2 \dd k\,.
\end{equation}
Finally, for the relevant covariances, we have
\begin{equation}
     \expval{\delta Q\delta P}= \frac{\hbar}{4 \pi}\int_{-\infty}^{\infty} F(k)G^*(k) \dd k \,.
\end{equation}



