\section{MODEL OF HIGHER SYMMETRY}\label{sec:appa}
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The exact analysis of the jammed macrostates for the model with emphasis on symmetry (Sec.~\ref{sec:scen1}) is outlined here.
The partition function (\ref{eq:18}) can be simplified into
\begin{align}\label{eq:a16}
  \bar{Z}^{-1}= \zeta = \prod_{m}x_{m}^{\bar{A}_{m}}=\prod_{m<15}x_m,
\end{align}
with the $x_m$ defined in (\ref{eq:17}) and for the $\bar{A}_m$, $\hat{g}_{mn}$ in Table~\ref{tab:t5}.
A corresponding simplification occurs in Eqs.~(\ref{eq:19}) for the variable $x_1$:
\begin{equation}\label{eq:a17}
  x_{1} = 1 -e_{1}\prod_nx_{n}^{\hat{g}_{n1}}
  = 1 -\bar{e}_{1}\prod_{n<15}x_{n}.
\end{equation}
In consequence, the partition function reduces to a function of $x_1$ alone:
\begin{equation}\label{eq:a9}
\bar{Z}=\frac{\bar{e}_1}{1-x_1}.
\end{equation}
For the following we introduce the fugacity $z$ and the modified energy parameters $\bar{e}_m$:
\begin{equation}\label{eq:a5}
z\doteq e^{\beta\mu},\quad
\bar{e}_m\doteq e^{-\beta p_m}=e_mz^{-s_m}.
\end{equation}
For the purpose of compact expressions and computational efficiency it is useful to introduce
\begin{align}\label{eq:a61}
y_m\doteq 1-x_m.
\end{align}

By judiciously sequencing the remaining Eqs.~(\ref{eq:19}) we can relate all $x_m$ to $\zeta$ directly or recursively:
\begin{equation}\label{eq:a3}
x_{1} = 1 -\bar{e}_{1}\zeta,
\end{equation}
\begin{equation}\label{eq:a18}
 \frac{y_{15}}{y_{1}} =\frac{e_{15}}{e_{1}}
 \quad \Rightarrow~ 
 x_{15} = 1-\bar{e}_{15}z\zeta,
\end{equation}
\begin{equation} \label{eq:a19}
  \frac{y_{17}}{y_{15}^{2}}=\frac{e_{17}}{e_{15}^{2}}x_{15}^{-2}
   \quad \Rightarrow~
  x_{17} = 1 - \frac{\bar{e}_{17}z^2\zeta^{2}}{(1-\bar{e}_{15}z\zeta)^{2}},
\end{equation}
\begin{equation}\label{eq:a20}
  \frac{y_{8}}{y_{15}}=\frac{e_{8}}{e_{15}}\frac{x_{8}}{x_{15}x_{17}}
   \quad \Rightarrow~ 
  x_{8} =  \left[1+\frac{\bar{e}_{8}z\zeta}{x_{15}x_{17}}\right]^{-1},
\end{equation}
\begin{equation}\label{eq:a21}
  \frac{y_{7}}{y_{8}}=x_{7}
   \quad \Rightarrow~   
  x_{7} = \frac{1}{2-x_{8}},
\end{equation}
\begin{equation}\label{eq:a22}
  \frac{y_{5}}{y_{17}}=\frac{e_{5}}{e_{17}}\frac{x_{15}}{x_{1}x_{17}}
  \quad \Rightarrow~   
  x_{5} =1 - \frac{\bar{e}_{5}}{\bar{e}_{17}}\frac{x_{15}y_{17}}{z\,x_{1}x_{17}},
\end{equation}
\begin{equation}\label{eq:a23}
\frac{y_{3}}{y_{5}}=\frac{e_{3}}{e_{5}}\frac{1}{x_{5}}
  \quad \Rightarrow~   
  x_{3} =1- \frac{\bar{e}_{3}}{\bar{e}_{5}}\frac{y_{5}}{x_{5}},
\end{equation}
\begin{align}\label{eq:a24}
\frac{y_{9}}{y_{3}y_{8}}=\frac{e_{9}}{e_{3}e_{8}}\frac{x_{17}}{x_{3}x_{8}} 
\quad \Rightarrow~   
  x_{9} =1- \frac{\bar{e}_{9}}{\bar{e}_{3}\bar{e}_{8}}\frac{x_{17}y_{3}y_{8}}{x_{3}x_{8}},
\end{align}
\begin{equation}\label{eq:a25}
  \frac{y_{11}}{y_{9}}=\frac{1}{x_{9}}
 \quad \Rightarrow~    
  x_{11} = 2 - \frac{1}{x_{9}},
\end{equation}
\begin{equation}\label{eq:a26}
\frac{y_{13}}{y_{11}}=\frac{e_{13}}{e_{11}}\frac{1}{x_{11}}
 \quad \Rightarrow~    
  x_{13} = 1 - \frac{\bar{e}_{13}}{\bar{e}_{11}}\frac{y_{11}}{x_{11}},
\end{equation}
\begin{equation}\label{eq:a27}
  \frac{y_{14}}{y_{13}}=\frac{e_{14}}{e_{13}}\frac{1}{x_{9}x_{13}}
 \quad \Rightarrow~      
  x_{14} = 1 - \frac{\bar{e}_{14}}{\bar{e}_{13}}\frac{y_{13}}{x_{13}}.
\end{equation}
Substitution of the $x_m$ and $y_m$ from \eqref{eq:a17}-\eqref{eq:a27} into \eqref{eq:a16}
 yields the cubic equation,
\begin{equation}\label{eq:a1}
  1 - a_{1}\zeta -a_{2}\zeta^{2} + a_{3}\zeta^{3}=0,
\end{equation}
with coefficients,
\begin{align}\label{eq:a2}
  a_{1} & = 1+\bar{e}_{1}+2z\bar{e}_{15}, \nonumber \\
  a_{2} & = z^2[\bar{e}_{17}-\bar{e}_{15}^2] 
  +z[\bar{e}_{3}+2\bar{e}_{8}+\bar{e}_{5}-2(1+\bar{e}_{1})\bar{e}_{15} ],
  \nonumber \\ 
  a_{3} & = z^2[(1+\bar{e}_{1})(\bar{e}_{17}-\bar{e}_{15}^2) + (\bar{e}_{3}+2\bar{e}_{8}+\bar{e}_{5})e_{15} \nonumber \\ &\hspace{25mm} -\bar{e}_{14}-2\bar{e}_{9} -\bar{e}_{13}]. 
\end{align}
A unique physical solution is guaranteed if the modified energy parameters satisfy the inequalities,
\begin{equation}\label{eq:a6}
\sqrt{\bar{e}_{17}}>\bar{e}_{15},\quad
(\bar{e}_3+2\bar{e}_8+\bar{e}_5)\bar{e}_{15}
>\bar{e}_{14}+2\bar{e}_9+\bar{e}_{13},
\end{equation}
which are not restrictive from a physical perspective for the intended applications.
If the $\bar{e}_m$ satisfy the relation,
\begin{equation}\label{eq:a7}
(\bar{e}_3+2\bar{e}_8+\bar{e}_5)\sqrt{\bar{e}_{17}}
=\bar{e}_{14}+2\bar{e}_9+\bar{e}_{13},
\end{equation}
which is consistent with (\ref{eq:a6}), then the cubic equation (\ref{eq:a1}) factorizes with one particular root of the quadratic factor identifiable as the physically relevant solution.
The partition function in closed form for this case reads,
  \begin{align}\label{eq:a8}
    \bar{Z} &= \frac{1}{2}\Big[
    1+\bar{e}_{1}+(\bar{e}_{15}+\sqrt{\bar{e}_{17}})z \\ \nonumber  
    &+
    \sqrt{\big(1+\bar{e}_{1}-(\bar{e}_{15}+\sqrt{\bar{e}_{17}})z\big)^{2}
      -4z(\bar{e}_{3}+2\bar{e}_{8}+\bar{e}_{5})}\,\Big].
  \end{align}

From this result we infer explicit expressions for the variables $x_m$ via the Eqs.~(\ref{eq:a3})-(\ref{eq:a27}) and for the particle population densities $\bar{N}_m$ via the solution of the linear equations (\ref{eq:15}) with the $w_m$ from (\ref{eq:17}).
The excess volume of the jammed macrostate then follows from (\ref{eq:7})
and its entropy from (\ref{eq:20}).

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Default energy parameters}\label{sec:appa-1}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
We continue with the default choice (\ref{eq:39}) for the $p_m$ that go into the energy parameters $\bar{e}_m$ as stated in (\ref{eq:a5}).
For the implementation of this choice, we introduce the non-negative quantities,
\begin{equation}\label{eq:a10}
 f_i\doteq e^{-\beta(\tilde{V}_i-\tilde{V}_\mathrm{b})}\quad i=\mathrm{a}, \mathrm{c}, \mathrm{d}, \mathrm{e}, \mathrm{f},
\end{equation}
associated with the volumes of two-disk tiles listed in Table ~\ref{tab:t2}. 
We can thus write,
\begin{align}\label{eq:a51}
& \bar{e}_1=f_\mathrm{d}/f_\mathrm{a},\quad
\bar{e}_3=f_\mathrm{c}^2/f_\mathrm{a}^2,\quad
\bar{e}_5=f_\mathrm{f}^2/f_\mathrm{a}^2, 
\nonumber \\
& \bar{e}_7=\bar{e}_8=f_\mathrm{c}f_\mathrm{f}/f_\mathrm{a}^2,\quad
\bar{e}_9=\bar{e}_{11}=f_\mathrm{c}f_\mathrm{f}/f_\mathrm{a}^3,
\nonumber \\
& \bar{e}_{13}=f_\mathrm{f}^2/f_\mathrm{a}^3,\quad
\bar{e}_{14}=f_\mathrm{c}^2/f_\mathrm{a}^3,
\nonumber \\
& \bar{e}_{15}=\bar{e}_{16}=f_\mathrm{e}/f_\mathrm{a},\quad
\bar{e}_{17}=1/f_\mathrm{a}^2.
\end{align}
The partition function (\ref{eq:a8}) turns into an explicit, parameterless  function of $\beta$ and $z$:
\begin{align}\label{eq:a11}
    \bar{Z}(\beta,z) &= \frac{1}{2f_\mathrm{a}}\Bigg[(1+f_\mathrm{e})z+f_\mathrm{a}+f_\mathrm{d} \\
    &-\sqrt{\Big((1+f_\mathrm{e})z-f_\mathrm{a}-f_\mathrm{d}\Big)^{2}
      +4z(f_\mathrm{c}+f_\mathrm{f})^{2}}\;\;\Bigg]. \nonumber
  \end{align}

Next we aim to establish the relation (\ref{eq:8}) between the chemical potential $\mu$, which enters $\bar{Z}$ via the fugacity $z$, and the (experimentally controllable) fraction $\bar{N}_\mathrm{S}$ of small disks.  
Toward this goal, a more compact rendering of the result (\ref{eq:a11}) is useful. 
We can write, 
\begin{equation}\label{eq:a12}
  \bar{Z}(\beta,z)
  = \frac{Z_{0}}{2}\left[1+
  \frac{z}{z_\mathrm{h}} +\sqrt{\left(1-\frac{z}{z_\mathrm{h}}\right)^{2}\!\!+4 \delta^2\,\frac{z}{z_\mathrm{h}}}\;\right].
\end{equation}
The significance of the three parameters, 
\begin{align}\label{eq:a13}
Z_{0} &\doteq \frac{f_\mathrm{a}+f_\mathrm{d}}{f_\mathrm{a}},\quad 
\delta(\beta) \doteq \frac{f_\mathrm{c}+f_\mathrm{f}}{\sqrt{(1+f_\mathrm{e})(f_\mathrm{a}+f_\mathrm{d})}}, \nonumber \\
z_\mathrm{h} &\doteq \frac{f_\mathrm{a}+f_\mathrm{d}}{1+f_\mathrm{e}} \quad :~
0<z_\mathrm{h}<\delta<1<Z_0<2,
\end{align}
will become clear shortly.
$\bar{N}_\mathrm{S}$ can be extracted from the partition function via derivatives,
\begin{equation}\label{eq:a14}
  \bar{N}_\mathrm{S} = \frac{1}{\beta \bar{Z}} \frac{\partial \bar{Z}}{\partial \mu}
  = \frac{z}{\bar{Z}} \frac{\partial \bar{Z}}{\partial z},
\end{equation}
to be carried out on expression (\ref{eq:a12}):
\begin{equation}\label{eq:a15}
  \bar{N}_\mathrm{S}(\beta,z) = \frac{1}{2}
  \left[1 +  \frac{z/z_\mathrm{h}-1}{\sqrt{(z/z_\mathrm{h}-1)^{2}+4\delta^2 z/z_\mathrm{h}}}\right].
\end{equation}
For given $\beta$ (contained in $\delta$ and $z_\mathrm{h}$), $\bar{N}_\mathrm{S}$ is a rather simple, monotonically increasing, function of $z$.
The limit ${\bar{N}_\mathrm{S}=0}$ ($\bar{N}_\mathrm{S}=1$) is realized for $z\to0$ ($z\to\infty$).
The case $\bar{N}_\mathrm{S}=\frac{1}{2}$ is realized for $z=z_\mathrm{h}$ (half and half).
For what follows we need the inverse relation $z(\beta,\bar{N}_\mathrm{S})$: 
\begin{align}\label{eq:a28}
\frac{z}{z_\mathrm{h}}
=\exp\Big(2\mathrm{Arsinh}(\eta_\mathrm{S}\delta)\Big),\quad
\eta_\mathrm{S}= \frac{\bar{N}_\mathrm{S}-\frac{1}{2}}{\sqrt{\bar{N}_\mathrm{S}\big(1-\bar{N}_\mathrm{S}\big)}}.
\end{align}
The antisymmetry of $\eta_\mathrm{S}$ about $\bar{N}_\mathrm{S}=\frac{1}{2}$ is another manifestation of symmetry. 
Expressions (\ref{eq:a3})-(\ref{eq:a27}) can now be simplified.
The solution of the linear Eqs.~(\ref{eq:15}) for the particle population densities then yield the compact expressions,
\begin{equation}\label{eq:a39}
\bar{N}_{1} = \bar{N}_{2} 
=\frac{y_{1}x_{15}x_{17}}{2D},\quad
\bar{N}_{3} = \bar{N}_{4} 
=\bar{N}_{1}\frac{y_{3}x_{1}x_{5}}{y_{1}},
 \end{equation}
\begin{equation}\label{eq:a40}
\bar{N}_{5} = \bar{N}_{6} 
=\bar{N}_{1}\frac{y_{5}x_{1}}{y_{1}},\quad
 \bar{N}_{7} = \frac{y_{7}\zeta x_{15}x_{17}}{x_{7}x_{8}D},
\end{equation}
\begin{equation}\label{eq:a41}
 \bar{N}_{8} = \bar{N}_{7}\frac{y_{8}x_{7}}{y_{7}},\quad
\bar{N}_{9} = \frac{y_{9}x_{1}x_{3}x_{5}x_{15}x_{17}}{2D}, 
\end{equation}
\begin{equation}\label{eq:a42}
\bar{N}_{11} = \bar{N}_{12}  
=\bar{N}_{9}\frac{y_{11}x_{9}}{y_{9}},\quad
\bar{N}_{13} = \bar{N}_{11}\frac{2y_{13}x_{11}}{y_{11}}, 
\end{equation}
\begin{equation}\label{eq:a43}
 \bar{N}_{14}  = \bar{N}_{13}\frac{y_{14}x_{13}}{y_{13}},\quad
 \bar{N}_{17} = \frac{y_{17}(x_{1}-\zeta)x_{15}}{D},
\end{equation}
\begin{align}\label{eq:a44}
 \bar{N}_{15} = \bar{N}_{16} 
  =\frac{y_{15}}{D}\Bigg[x_{1} &-\zeta\left(1+\frac{x_{17}y_{8}}{x_{8}}\right) \nonumber \\
 &  -\frac{x_{1}x_{17}(1-x_{3}x_{5})}{2}\Bigg], 
\end{align}
with $\zeta=1/\bar{Z}$ from (\ref{eq:a12}) and 
\begin{align}\label{eq:a45}
D &\doteq  (2-x_{17})(x_{1}-\zeta) \nonumber \\
&\hspace{10mm}+x_{17}\left(x_{15}+x_{1}x_{3}x_{5}
-\frac{\zeta}{x_{7}x_{8}}\right).
\end{align}
Excess volume (\ref{eq:7}) and entropy (\ref{eq:20}), which are functions of the $\bar{N}_m$ follow directly.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Modified energy parameters}\label{sec:appa-2}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The results presented in Secs.~\ref{sec:ssm-b} and \ref{sec:ssm-c} require specific modifications in the energy parameters $\bar{e}_m$ as explained in Secs.~\ref{sec:jam-prot} and \ref{sec:ssm}.
All possible modifications are combinations of changes in the $\bar{e}_m$.
We noted that the criterion for distinct ordering tendencies hinges on whether the quantity $\Delta\mathcal{V}$ with default value (\ref{eq:31}) remains positive or goes negative.
The inequality $\Delta\mathcal{V}>0$ implies the inequality,
\begin{equation}\label{eq:a52}
\frac{f_\mathrm{c}^2}{f_\mathrm{a}}=e^{-\beta\Delta\mathcal{V}}<1,
\quad \Delta\mathcal{V}=0.19748\ldots,
\end{equation}
to be satisfied for the default energy parameters.
The numerical value for $\Delta\mathcal{V}$ stated in (\ref{eq:a52}) pertains to the disk diameters used throughout this study.
For the case described in Sec.~\ref{sec:ssm-b} we replace $\Delta\mathcal{V}$ by $-\Delta\mathcal{V}$ in (\ref{eq:a52}), which changes the ordering tendency.
The borderline case described in Sec.~\ref{sec:ssm-c} pertains to setting $\Delta\mathcal{V}=0$ in 
(\ref{eq:a52}).
In practice, we keep the default value of $f_\mathrm{a}$ and modify $f_\mathrm{c}$ in two out of three cases:
\begin{equation}\label{eq:a53}
f_\mathrm{c}=\left\{ \begin{array}{ll} \displaystyle
\sqrt{f_\mathrm{a}}e^{-\beta\Delta\mathcal{V}/2} & 
:~ \mathrm{Sec.~\ref{sec:ssm-a}},  \\ \rule[-2mm]{0mm}{7mm}
\displaystyle \sqrt{f_\mathrm{a}}e^{\beta\Delta\mathcal{V}/2} & 
:~ \mathrm{Sec.~\ref{sec:ssm-b}},  \\ \rule[-2mm]{0mm}{6mm}
\displaystyle \sqrt{f_\mathrm{a}} & 
:~ \mathrm{Sec.~\ref{sec:ssm-c}}. \end{array} \right.
\end{equation}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Small-disk reference state}\label{sec:appa-3}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
We stated in Sec.~\ref{sec:geom} that starting from reference state (\ref{eq:36}), representing the most compact configuration of small disks, instead of the large-disk configuration (\ref{eq:2}), makes no difference mathematically and produces the same physics.
The switch amounts to interchanging two pairs of the six tile volumes listed in Table~\ref{tab:t2}:
\begin{equation}\label{eq:a54}
\tilde{V}_\mathrm{a} \longleftrightarrow \tilde{V}_\mathrm{b},\quad 
\tilde{V}_\mathrm{d} \longleftrightarrow \tilde{V}_\mathrm{c}.
\end{equation}
In the statistical mechanical analysis carried out above (Sec~\ref{sec:appa-1}), the switch entails the following substitutions:
\begin{equation}\label{eq:a55}
\bar{N}_\mathrm{L} \longleftrightarrow \bar{N}_\mathrm{S},\quad 
z_\mathrm{h} \longleftrightarrow z_\mathrm{h}^{-1},\quad
z \longleftrightarrow z^{-1}.
\end{equation}
The mathematical simplicity associated with the switch of reference state is owed to the symmetry of the model.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Entropy and excess volume}\label{sec:appa-4}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
For the graphical representations in Sec.~\ref{sec:scen1} of excess volume $\bar{V}$ we use (\ref{eq:7}) with the $\bar{N}_m$ as determined analytically in the preceding parts of this appendix. We could proceed likewise for the configurational entropy $\bar{S}$ by using the same $\bar{N}_m$ in (\ref{eq:20}).
However, it is possible derive a closed-form expression for $\bar{S}$ as a function of $\bar{N}_\mathrm{S}$, $\bar{N}_\mathrm{L}$, and $\beta$ from the partition function (\ref{eq:a12}) via 
\begin{align}\label{eq:a60}
\bar{S}=\beta^2\frac{\partial\bar{\Omega}}{\partial\beta},\quad
\bar{\Omega}=-\frac{1}{\beta}\ln\bar{Z},
\end{align}
with use of (\ref{eq:a15}):
\begin{align}\label{eq:a56}
\bar{S} &=\bar{N}_\mathrm{L}\bar{S}_\mathrm{S}^{(0)}
+\bar{N}_\mathrm{S}\bar{S}_\mathrm{L}^{(0)}
+\frac{1}{2}\ln\big(1-\delta^2\big) \\
&+\mathrm{Arsinh}\left(\frac{\eta_\mathrm{S}\delta}{(\bar{N}_\mathrm{S}-\bar{N}_\mathrm{L})\sqrt{1-\delta^2}}\right) \nonumber \\
&-(\bar{N}_\mathrm{S}-\bar{N}_\mathrm{L})\mathrm{Arsinh}(\eta_\mathrm{S}\delta)
  \nonumber \\
&+\frac{\beta\nu\delta\sqrt{\bar{N}_\mathrm{S}\bar{N}_\mathrm{L}}}
{\sqrt{1-\delta^2}}\,\exp\left(-\mathrm{Arsinh}\left(\frac{\eta_\mathrm{S}\delta}{(\bar{N}_\mathrm{S}-\bar{N}_\mathrm{L})\sqrt{1-\delta^2}}\right)\right).
\nonumber
\end{align}
where
\begin{align}\label{eq:a57}
\bar{S}_\mathrm{S}^{(0)}=\ln\left(1+\frac{f_\mathrm{d}}{f_\mathrm{a}}\right)
+\frac{\ln(f_\mathrm{a}/f_\mathrm{d})}{1+f_\mathrm{a}/f_\mathrm{d}},
\end{align}
\begin{align}\label{eq:a58}
\bar{S}_\mathrm{L}^{(0)}=\ln\left(1+f_\mathrm{e}\right)
+\frac{\ln(1/f_\mathrm{e})}{1+1/f_\mathrm{e}},
\end{align}
\begin{align}\label{eq:a59}
\beta\nu(\beta) &=\frac{f_\mathrm{a}\ln f_\mathrm{a}+f_\mathrm{d}\ln f_\mathrm{d}}
{f_\mathrm{a}+f_\mathrm{d}}
+\frac{f_\mathrm{e}\ln f_\mathrm{e}}{1+f_\mathrm{e}} \nonumber \\
&-2\frac{f_\mathrm{c}\ln f_\mathrm{c}+f_\mathrm{f}\ln f_\mathrm{f}}
{f_\mathrm{c}+f_\mathrm{f}},
\end{align}
$\delta(\beta)$ from (\ref{eq:a13}) and $\eta_\mathrm{S}$ from (\ref{eq:a28}).

