Eliminating the $x_m$ and $y_m$ from \eqref{eq:B1}-\eqref{eq:B11} leads to a polynomial equation of order 6 for $\zeta$:
\begin{subequations}\label{eq:B12}
  \begin{align}\label{eq:B12a}
    p_{z}(\zeta)
    & = \big(1-(1+z\zeta f_\mathrm{e}/f_\mathrm{a})^{2}z^{2}
    \zeta^{2}/f_\mathrm{a}^{2}\big)p_{0}(\zeta)
    \\ \nonumber 
    & -(1+\zeta f_\mathrm{d}/f_\mathrm{a})\big(
      (f_\mathrm{c}+2f_\mathrm{f})f_\mathrm{c}f_\mathrm{a}\\  \nonumber
      &+(f_\mathrm{c}
      +f_\mathrm{f})^{2}(1+z\zeta f_\mathrm{e}/f_\mathrm{a})z\zeta
      +z\zeta f_\mathrm{c}^{2}f_\mathrm{e}\big)z\zeta^{2}/f_\mathrm{a}^{3}
  \end{align}
  \begin{equation}\label{eq:B12b}
   p_{0}(\zeta): = 1-\zeta-f_\mathrm{d}/f_\mathrm{a}\zeta^{2},
  \end{equation}
\end{subequations}
In expanded form, this polynomial reads
\begin{align}\label{eq:B13}
  p(\zeta) & = \sum_{\ell=0}^{6}a_{\ell}\zeta^{\ell},
  \end{align}
  with coefficients
  \begin{subequations}\label{eq:B14}
    \begin{align}\label{eq:B14a}
      a_{0} & = 1 > 0,
      \\ \label{eq:B14b}
      a_{1} &= -1 < 0,\\ \label{eq:B14c}
      a_{2} &= -\big(f_\mathrm{d}f_\mathrm{a}+(f_\mathrm{c}+2 f_\mathrm{f})f_\mathrm{c}z +z^{2}\big)/f_{a}^{2} < 0, \\ \label{eq:B14d}
      a_{3} &= -\big((f_\mathrm{c}+2 f_\mathrm{f})f_\mathrm{c}f_\mathrm{d}z \\\nonumber 
              &+\big((f_\mathrm{c}+f_\mathrm{f})^{2} -f_\mathrm{a} +f_\mathrm{c}^{2} f_\mathrm{e}\big) z^{2}
              +2f_\mathrm{e}z^{3}\big)/f_\mathrm{a}^{3} \leq 0,
      \\ \label{eq:B14e}
      a_{4} &= -\Big(\big((f_\mathrm{c}+f_\mathrm{f})^{2}-f_\mathrm{a}+f_\mathrm{c}^{2}f_\mathrm{e}\big)f_\mathrm{d}z^{2}
      \nonumber \\
              &+\big((f_\mathrm{c}+f_\mathrm{f})^{2}-2f_\mathrm{a}\big)f_\mathrm{e} z^{3}
              +f_\mathrm{e}^{2}z^{4}\Big)/f_\mathrm{a}^{4}  \leq 0,
      \\ \label{eq:B14f}
      a_{5} &= -\Big(\big((f_\mathrm{c}+f_\mathrm{f})^{2}-2f_\mathrm{a}\big)f_\mathrm{d}f_\mathrm{e} z^{3}-f_\mathrm{e}^{2}z^{4}\Big)/f_\mathrm{a}^{4}, 
      \\ \label{eq:B14g}
      a_{6} &= f_\mathrm{e}^{2}f_\mathrm{d}z^{4}/f_\mathrm{a}^{5} \geq 0.
    \end{align}
\end{subequations}
It can be shown that a unique positive physical root exists and has the range,
\begin{align}\label{eq:B15}
0 < \zeta <  \min\Big\{1,\frac{f_\mathrm{a}}{z}
\frac{2}{\sqrt{1+4f_\mathrm{e}}+1}\Big\}.
\end{align}

To derive the asymptotic expansion for large $\beta$ (implying small $f_\mathrm{a}/z$ with $z>0$), we consider the polynomial equation $p(\zeta_{*})=0$ with ingredients in (\ref{eq:B13}) and (\ref{eq:B14}). 
%For large $\beta$ (i.e. small $f_{a}/z$) and assuming $z>1$, the solution $\zeta_{*}$ satisfies $\zeta_{*}<\zeta_{\max}=\mathcal{O}(f_{a}/z)$. 
Analyzing the terms for each power of $\zeta_*$ individually, we find that $a_0\zeta_*$ and $a_2\zeta_*^2$ are of $\mathcal{O}(1)$ and $a_i\zeta_*^i$ for $i=1,3,4,5,6$ are of $\mathcal{O}(f_\mathrm{a}/z)$.
The solution to leading order becomes
\begin{align}\label{eq:B16}
  \zeta_{*} =  \frac{1}{\sqrt{a_{2}}} \leadsto \frac{f_\mathrm{a}}{z}.
\end{align}
A Newton iteration,
\begin{align}\label{eq:B17}
  \zeta_{*}^{(i+1)} = \zeta_{*}^{(i)} - \frac{p_{z}(\zeta_{*}^{(i)})}{p_{z}'(\zeta_{*}^{(i)})},\quad \zeta^{(0)}=\frac{f_\mathrm{a}}{z},
\end{align}
leads to a consistent expansion after just two iterations:
\begin{align}\label{eq:B18}
  \zeta_{*} =\frac{f_\mathrm{a}}{z}(1-f_\mathrm{e}+ ...).
\end{align}
In the mapping from the segregation to the alternation regime as distinguished in  (\ref{eq:a53}), which implies the substitution, $f_\mathrm{c} \mapsto f_\mathrm{a}/f_\mathrm{c}$, we again find (\ref{eq:B18}).
The exact solution worked out in Appendix~\ref{sec:appa} produces the exact same first two terms in the corresponding expansion.
Thus, the asymptotic behavior of $\zeta_{*}$ is consistent across both models -- the more symmetric one and the more stable one -- up to second order.

