\subsection{Numerical Scheme}\label{app:numeric}
For numerical simulations of model \eqref{eq:coupled_elast}-\eqref{eq:coupled_reactions}  we use FEM for discretization in space and backward Euler for discretization in time,  implemented in FEniCS~\cite{logg_automated_2012}. 
Consider the space
\begin{equation}\label{eq:W_def}
    \mathcal{W}(Y) = \lbrace u\in H^1(Y): \int_Y u_i \dd{x}=0, \; \int_Y \left(\partial_{x_j}u_i-\partial_{x_i} u_j \right)\dd{x} = 0 \; \;  \mbox{ for } \; i,j=1,2,3 \rbrace,
\end{equation}
such that $\mathcal{W}(Y)\cap \mathcal{R}(Y)=0$ with $\mathcal{R}(Y)$ the space of rigid motions. Then, the weak solution of the model \eqref{eq:coupled_elast}-\eqref{eq:coupled_reactions} is given  by  $(\phi_d,\phi_a) \in L^2(0,T;H^1(Y))$, $\rho_a\in L^2(0,T;H^1(\Gamma))$, with $(\partial_t\phi_d,\partial_t\phi_a)\in L^2(0,T;H^1(Y)')$ and $\partial_t \rho_a\in L^2(0,T;H^1(\Gamma)')$, and $u \in L^2(0,T;\mathcal{W}(Y))$ satisfying  %{\bl what is the space $W(Y)$?}
\begin{equation} \label{eq:weak_formul}
\begin{aligned}
   & \langle\partial_t \phi_d, \psi \rangle_{(H^1)^\prime,T} + \langle D_1 \nabla \phi_d, \nabla \psi \rangle_{Y_T} + \langle C_1\tr(\sigma(u))_+\phi_d, \psi \rangle_{Y_T} + \langle n_r\tilde{k}_3\phi_d, \psi\rangle_{\Gamma_T} = \langle k_1\phi_a,\psi \rangle_{Y_T}, \\
   & \langle \partial_t \phi_a, \varphi \rangle_{(H^1)^\prime,T} + \langle D_2 \nabla \phi_a, \nabla \varphi \rangle_{Y_T} + \langle k_1\phi_a,\varphi \rangle_{Y_T} =  \langle C_1\tr(\sigma(u))_+\phi_d, \varphi \rangle_{Y_T} + \langle n_r\tilde{k}_3\phi_d, \psi\rangle_{\Gamma_T} ,\\
  &  \langle\partial_t \rho_a, w \rangle_{(H^1)^\prime,T}+ \langle D_3 \nabla_\Gamma \rho_a, \nabla_\Gamma w \rangle_{\Gamma_T} + \langle \tilde{k}_4(\phi_a)\rho_a,w \rangle_{\Gamma_T}= \langle n_r\tilde{k}_5(\phi_a),w \rangle_{\Gamma_T},   \\
  &  \langle E(\phi_a)\epsilon(u),\epsilon(v) \rangle_{Y_T} = \langle k_6\mathbb{P}(\rho_a\nu),v \rangle_{\Gamma_T}, 
\end{aligned}
\end{equation}
for all $\psi,\varphi \in L^2\left(0,T;H^1(Y)\right)$, $w \in L^2\left(0,T;H^1(\Gamma)\right)$, and $v\in L^2(0,T;H^1(Y))$,  with initial conditions satisfied in the $L^2$-sense, and where $\tilde{k}_3=k_2+k_3\frac{E}{C+E}$, $\tilde{k}_4(\phi_a)=k_4+k_5((\gamma \phi_a)^n+1)$ and  $\tilde{k}_5(\phi_a)=k_5((\gamma \phi_a)^n+1)\frac{M_\rho}{|Y|}$.
Here $\langle\phi, \psi \rangle_{(H^1)^\prime,T}$ denotes the dual product between $\phi \in L^2(0,T; H^1(Y))$ and $\psi \in L^2(0,T; H^1(Y)^\prime)$ or between  $\phi \in L^2(0,T; H^1(\Gamma))$ and $\psi \in L^2(0,T; H^1(\Gamma)^\prime)$ and 
$$
\langle \phi, \psi\rangle_{Y_T} = \int_0^T \int_Y \phi \psi dx dt, \quad \langle \phi_1, \psi_1 \rangle_{\Gamma_T} = \int_0^T \int_\Gamma \phi_1 \psi_1 dx dt, \quad \text{ where } 1/p_1 + 1/p_2 =1, \; \; 1/q_1+ 1/q_2 =1, 
$$
for  $\phi \in L^{p_1}(0,T; L^{q_1}(Y))$, $\psi \in L^{p_2}(0,T; L^{q_2}(Y))$, $\phi_1 \in L^{p_1}(0,T; L^{q_1}(\Gamma))$, and  $\psi_1 \in L^{p_2}(0,T; L^{q_2}(\Gamma))
$. 
%\subsubsection*{Spatial discretization}
The discretization of the domain is given  by the polyhedral approximation of $Y$ such that $Y_h$ is the union of finitely many tetrahedrons in $\mathbb{R}^3$, and $S_h$ is  the set of these tetrahedrons $K$, such that
$$
Y_h = \bigcup_{K \in S_h} K.
$$
Then  the surface $\Gamma$ is approximated by $\Gamma_h$ such that $\Gamma_h=\partial Y_h$. The mesh size is defined by the maximum diameter of a simplex $h=\max\lbrace h_Y,h_\Gamma\rbrace$, where $ h_Y = \max_{K\in S_h}h_Y(K)$ and  $h_\Gamma = \max_{R=K\cap \Gamma_h\neq 0, K \in S_h}h_\Gamma(R)$ with $h_Y(K)$ being the diameter of a tetrahedron and $h_\Gamma(R)$  the diameter of a triangle on the surface.
