\noindent The bulk and surface finite element spaces are given by 
\begin{align*}
    \mathbb{V}_{h,Y} &= \left\lbrace \Psi \in C(Y_h):\left.\Psi\right|_K \mbox{ is linear affine for each } K \in S_h \right\rbrace,\\
    \mathbb{V}_{h,\Gamma} &= \left\lbrace \Psi \in C(\Gamma_h):\left.\Psi\right|_R \mbox{ is linear affine for each } K \in S_h \mbox{ with } R=K\cap \Gamma_h\neq 0 \right\rbrace,\\
    \mathbb{W}_{h,Y} &= \left\lbrace V\in\mathcal{W}(Y_h) \mbox{ and } V_i \in C(Y_h):\left.V_i\right|_K \mbox{ is linear affine for each } K \in S_h \mbox{ for }i=1,2,3 \right\rbrace,
\end{align*}
where we recall the definition of $\mathcal{W}$ in Eq~(\ref{eq:W_def}). 
The bulk space is spanned by nodal basis functions defined by
$$
\chi_j\in\mathbb{V}_{h,Y}, \quad \chi_j(X_k)=\delta_{jk} \quad \text{ for } \; j,k=1,...,J,
$$
where $\delta_{jk}$ is the Kronecker delta and  $J$ is the number of nodes (vertices)  $X_j\in Y$ of the tetrahedrons $S_h$. Then  function $\Phi(t)\in \mathbb{V}_{h,Y}$ has the form
$$
\Phi(t, x)=\sum_{j=1}^J a_j(t)\chi_j(x) \quad  \text{ for } \; x\in Y_h, \; t \in (0,T),
$$
with real measurable functions $a_j$. Similarly  the surface finite element space is spanned by nodal basis functions 
$$
\mu_j\in\mathbb{V}_{h,\Gamma}, \quad \mu_j(Z_k)=\delta_{jk} \quad \text{ for } \; j,k=1,...,M,
$$
where $Z_j\in\Gamma$, with $j,k=1,...,M$,  are nodes of the triangulated surface such that $Z_k=X_k\bigcap \Gamma_h\neq 0$. Then  function $P(t)\in \mathbb{V}_{h,\Gamma}$ has the form
$$
P(t,x)=\sum_{j=1}^M b_j(t)\mu_j(x) \quad \text{ for } \; x\in \Gamma_h, \; t \in (0,T),
$$
with real measurable functions $b_j$. Thus, the semi-discretized problem corresponding to \eqref{eq:coupled_elast}-\eqref{eq:coupled_reactions} reads
\begin{equation} \label{eq:space_discr}
\begin{aligned}
    &\left<\partial_t \Phi_d, \Psi \right>_{Y_h} + \left< D_1 \nabla \Phi_d, \nabla \Psi \right>_{Y_h} + \left<C_1\tr(\sigma(U))_+\Phi_d, \Psi \right>_{Y_h} + \left<n_r\tilde{k}_3\Phi_d, \Psi\right>_{\Gamma_h} = \left<k_1\Phi_a,\Psi \right>_{Y_h}, \\
   & \left<\partial_t \Phi_a, \Psi \right>_{Y_h} + \left< D_2 \nabla \Phi_a, \nabla \Psi \right>_{Y_h} + \left<k_1\Phi_a,\Psi \right>_{Y_h} =  \left<C_1\tr(\sigma(U))_+\Phi_d, \Psi \right>_{Y_h} + \left<n_r\tilde{k}_3\Phi_d, \Psi\right>_{\Gamma_h} , \\
   & \left<\partial_t P_a, W \right>_{\Gamma_h} + \left< D_3 \nabla_{\Gamma_h} P_a, \nabla_{\Gamma_h} W \right>_{\Gamma_h} + \left<\tilde{k}_4(\Phi_a)P_a,W \right>_{\Gamma_h} = \left<n_r\tilde{k}_5(\Phi_a),W \right>_{\Gamma_h},\\
  &  \left<E(\Phi_a)\epsilon(U),\epsilon(V) \right>_{Y_h} = \left<k_6\mathbb{P}(P_a\hat{\nu}),V \right>_{\Gamma_h},
\end{aligned}
\end{equation}
for every test function $\Psi\in \mathbb{V}_{h,Y}$, $W\in \mathbb{V}_{h,\Gamma}$ and $V\in \mathbb{W}_{h,Y}$.

%\subsubsection*{Temporal discretization}
To obtain the fully discrete problem we discretize \eqref{eq:space_discr} in time  using the  backwards Euler  method with 
$$
\partial_t \Phi \approx \frac{\Phi^n-\Phi^{n-1}}{\Delta t},
$$
where $\Delta t = T/N$, and  an IMEX time-stepping method, in which the diffusion terms are treated implicitly and the nonlinear reaction terms are treated explicitly \cite{lakkis2013implicit}. The discrete system, with the notation $\Phi^n(x)=\Phi(t_n,x)$, reads
\begin{eqnarray} \label{eq:full_discrete}
%\begin{aligned}
    \left<\mathbb{E}(\Phi_a^{n-1})\epsilon(U^n),\epsilon(V) \right>_{Y_h} &=& \left<k_6\mathbb{P}(P_a^{n-1}\hat{\nu}),V \right>_{\Gamma_h},  \nonumber\\
     \Delta t^{-1}\left<\Phi_d^n, \Psi \right>_{Y_h} + \left< D_1 \nabla \Phi_d^n, \nabla \Psi \right>_{Y_h} &+ &\left<C_1\tr(\sigma(U^n))_+\Phi_d^n, \Psi \right>_{Y_h} + \left<n_r\tilde{k}_3\Phi_d^n, \Psi\right>_{\Gamma_h} \nonumber \\
     &=&\Delta t^{-1}\left<\Phi_d^{n-1}, \Psi \right>_{Y_h} + \left<k_1\Phi_a^{n-1},\Psi \right>_{Y_h},  \nonumber\\
    \Delta t^{-1}\left<\Phi_a^n, \Psi \right>_{Y_h} + \left< D_2 \nabla \Phi_a^n, \nabla \Psi \right>_{Y_h} &+& \left<k_1\Phi_a^n,\Psi \right>_{Y_h} \\
    &= & \Delta t^{-1}\left<\Phi_a^{n-1}, \Psi \right>_{Y_h} + \left<C_1\tr(\sigma(U^n))_+\Phi_d^{n}, \Psi \right>_{Y_h} + \left<n_r\tilde{k}_3\Phi_d^{n}, \Psi\right>_{\Gamma_h} , \nonumber\\
   \Delta t^{-1}\left< P_a^n, W \right>_{\Gamma_h} + \left< D_3 \nabla_{\Gamma_h} P_a^n, \nabla_{\Gamma_h} W \right>_{\Gamma_h} &+& \left<\tilde{k}_4(\Phi_a^n)P_a^n,W \right>_{\Gamma_h}\nonumber \\
    &=& \Delta t^{-1}\left< P_a^{n-1}, W \right>_{\Gamma_h} + \left<n_r\tilde{k}_5(\Phi_a^n),W \right>_{\Gamma_h}. \nonumber
%\end{aligned}
\end{eqnarray}
%\subsection*{Benchmarking}\label{app:benchmark}
To benchmark the numerical scheme and implementation in FEniCS, we consider $Y$ to be a unit ball and a simplified model  
\begin{equation}\label{eq:benchmark}
\begin{aligned}
    -\nabla \cdot \sigma(u) &= f &&\text{in } \; Y, \\
    \sigma(u)\cdot \nu &= \mathbb{P}(g\rho) &&\text{on }\Gamma,\\
  %  \sigma(u) &= \lambda(\nabla \cdot u)I +  \mu \left( \nabla u + (\nabla u)^T\right), \\
    \partial_t  \phi - \Delta  \phi &= q_1 + \tr(\sigma(u))_{+} \quad &&\text{in } \; Y, \; t>0, \\
    \nabla \phi\cdot \nu &= \rho-\phi &&\text{on }\Gamma, \; t>0, \\
    \partial_t \rho - \Delta_{\Gamma} \rho  &= q_2-\rho+\phi &&\text{on } \Gamma, \; t>0, \\
    u (0, x) = u_{ex}(0,x), &\quad \phi (0, x) = \phi_{ex}(0,x)  \quad &&\mbox{in } Y, \\
    \rho (0, x)& = \rho_{ex}(0,x)  && \mbox{on } \Gamma.
\end{aligned}
\end{equation}
The functions $f$, $g$, $q_1$, and $q_2$ are such that 
$$
\begin{aligned}
    u_{ex}(t,x) &= \left(2x_1^2x_2x_3e^{-4t}, -x_1x_2^2x_3e^{-4t}, -2x_1x_2x_3^2e^{-4t} \right),\\
    \phi_{ex}(t,x) &= \cos(x_1x_2x_3) e^{-4t},\\
    \rho_{ex}(t,x) &= \cos(x_1x_2x_3) e^{-4t} - 3\sin(x_1x_2x_3)e^{-4t}
