\subsection{Simulations with linear viscoelasticity} \label{app:viscoelas}
To model a linear viscoelastic material, we consider the model equations \eqref{eq:coupled_elast} and  \eqref{eq:coupled_reactions} with the stress defined as
\begin{equation}\label{eq:sigma_visco} 
    \sigma(u) = \lambda(\phi_a)(\nabla \cdot u + \theta_\lambda \nabla \cdot \partial_t u)I +  2\mu(\phi_a)\left( \big( \nabla u + (\nabla u)^T\big) + \theta_\mu \big( \nabla \partial_t u + (\nabla \partial_t u)^T\big)\right),
\end{equation}
with the initial condition $u(0,x)=0$ for $x \in Y$, where  $\theta_\lambda$ and $\theta_\mu$ are the characteristic retardation times. We use a backward Euler discretization such that
\begin{align*}
    \left<\lambda(\Phi_a^{n-1})\right.&(1+\Delta t^{-1}\theta_\lambda)(\nabla \cdot U^n)I +\left.  2\mu(\Phi_a^{n-1})(1+\Delta t^{-1}\theta_\mu) \epsilon(U^n),\epsilon(V) \right>_{Y_h}\\
    &= \Delta t^{-1} \left<\lambda(\Phi_a^{n-1})\theta_\lambda (\nabla \cdot U^{n-1})I +  2\mu(\Phi_a^{n-1})\theta_\mu \epsilon(U^{n-1}),\epsilon(V) \right>_{Y_h} + \left<k_6\mathbb{P}(P_a^{n-1}\hat{\nu}),V \right>_{\Gamma_h}.
\end{align*}
The numerical simulation results are presented in Fig~\ref{fig:sim_visc}.

