\section{Nehari's theorem and its proof}

In this section we present Nehari's theorem, and a novel proof based on the duality result given in the previous section. Before stating the theorem, we need to introduce Hankel operators.

Let $g \in L_\infty(\mathbb{T})$. The \emph{Hankel operator with symbol $g$} is the linear operator on $\mathcal{H}_2$ given by
%
\begin{align*}
\Gamma_g := P_{\mathcal{H}_2} M_g R,
\end{align*}
%
where $P_{\mathcal{H}_2}$ is the projection of $L_2(\mathbb{T})$ onto $\mathcal{H}_2$, defined as $P_{\mathcal{H}_2}(\cdots + a_{-2} z^2 + a_{-1} z + a_0 + a_1 z^{-1} + a_2 z^{-2} + \cdots) := a_0 + a_1 z^{-1} + a_2 z^{-2} + \cdots$; $M_g$ is the \emph{multiplication operator} on $L_2(\mathbb{T})$, given by $M_g f := g f$; and $R$ is the \emph{reversion operator} on $L_2(\mathbb{T})$, defined as $R(\cdots + a_{-2} z^2 + a_{-1} z + a_0 + a_1 z^{-1} + a_2 z^{-2} + \cdots) := \cdots + a_2 z^2 + a_1 z + a_0 + a_{-1} z^{-1} + a_{-2} z^{-2} + \cdots$.

Note that, if $f_1, f_2 \in \mathcal{H}_2$ and $g \in L_\infty(\mathbb{T})$,
%
\begin{align*}
(\Gamma_g f_1, f_2)
&= (P_{\mathcal{H}_2} M_g R f_1, f_2) \\
&= (g [R f_1], f_2) \\
&=\frac{1}{2 \pi} \int_{-\pi}^\pi f_1(e^{-i \omega})\, g(e^{i \omega})\, \overline{f_2(e^{i \omega})}\, d\omega,
\end{align*}
%
where the second line follows since $M_g R f_1 = P_{\mathcal{H}_2} M_g R f_1 + (I - P_{\mathcal{H}_2}) M_g R f_1$, and $(I - P_{\mathcal{H}_2}) M_g R f_1 \in \mathcal{H}_2^\perp$, so $([I - P_{\mathcal{H}_2}] M_g R f_1, f_2) = 0$, thus $(P_{\mathcal{H}_2} M_g R f_1, f_2) = (M_g R f_1, f_2)$.

For our derivations, it will be useful to appeal to the \emph{forward shift operator} $q\colon L_1(\mathbb{T}) \to L_1(\mathbb{T})$, defined as $(q f)(z) := z f(z)$. If $f \in L_1(\mathbb{T})$, let $f^{\sim}(z) := \overline{f(z^{-1}})$; note that, for every $p \geq 1$, $f \in \mathcal{H}_p$ if and only if $f^\sim \in \mathcal{H}_p$, and $\| f^\sim \|_p = \| f \|_p$.

\medskip
We can now present our main contribution.

\begin{thm}[Nehari's Theorem] \label{thm:Nehari_theorem}
Let $g \in L_\infty(\mathbb{T})$. Then,
%
\begin{align*}
\inf_{f \in \mathcal{H}_\infty^\perp} \| g - f \|_\infty = \| \Gamma_g \|.
\end{align*}
%
Also, the infimum is attained at an $f_\text{opt} \in \mathcal{H}_\infty^\perp$. If there is a non-zero $y \in \mathcal{H}_2$ such that $\| \Gamma_g y\|_2 = \| \Gamma_g \| \, \| y \|_2$, then $g - f_\text{opt}$ is an inner function, \ie, $|g(e^{i \omega}) - f_\text{opt}(e^{i \omega})|$ is constant with respect to $\omega \in [-\pi, \pi)$.
\end{thm}

\begin{proof}
Note that $f \in \mathcal{H}_\infty^\perp$ iff $q R f \in \mathcal{H}_\infty$, because if $f(z) = a_1 z + a_2 z^2 + \cdots$ then $(q R f)(z) = a_1 + a_2 z^{-1} + a_3 z^{-2} + \cdots$, and $\esssup_{\omega \in [-\pi, \pi)} |f(e^{i \omega})| = \esssup_{\omega \in [-\pi, \pi)} |(q R f)(e^{i \omega})|$. Then,
%
\begin{align*}
\| g - f \|_\infty
&= \underset{\omega \in [-\pi, \pi)}{\esssup}\; |g(e^{i \omega}) - f(e^{i \omega})| \\
&= \underset{\omega \in [-\pi, \pi)}{\esssup}\; |e^{i \omega} g(e^{-i \omega}) - e^{i \omega} f(e^{-i \omega})| \\
&= \| q R g - q R f \|_\infty.
\end{align*}
%
Therefore, we can transform the norm minimization problem $\inf_{f \in \mathcal{H}_\infty^\perp} \| g - f \|_\infty$ into $\inf_{\hat{f} \in \mathcal{H}_\infty} \| q R g - \hat{f} \|_\infty$, where $\hat{f} = q R f$. This problem can now be put into the form of Theorem~\ref{thm:norm_min}. Indeed, by letting $X = L_1(\mathbb{T})$ (so $X^\ast = L_\infty(\mathbb{T})$), $x^\ast = q R g$, and $M = \mathcal{H}_1^0$ (so that $M^\perp = \mathcal{H}_\infty$), Theorem~\ref{thm:norm_min} establishes that the infimum is achieved by some $\hat{f}_\text{opt} \in \mathcal{H}_\infty$, and that
%
\begin{align*}
&\min_{\hat{f} \in \mathcal{H}_\infty} \| q R g - \hat{f} \|_\infty \\
&\qquad = \sup_{\substack{x \in M \\ \| x \| \leq 1}} \left| \langle x, q R g \rangle \right| \\
&\qquad = \sup_{\substack{x \in \mathcal{H}_1^0 \\ \| x \|_1 = 1}} \left| \frac{1}{2 \pi} \int_{-\pi}^\pi e^{i \omega}\, g(e^{-i \omega})\, x(e^{i \omega})\, d\omega \right|.
\end{align*}
%
In the last equality, we have replaced the inequality constraint $\| x \| \leq 1$ by the equality $\| x \|_1 = 1$, since at optimality the norm of $x$ can be shown to be as large as possible.

Note that $x \in \mathcal{H}_1^0$ iff $q x \in \mathcal{H}_1$.
Using the Riesz factorization theorem (Theorem~\ref{thm:Riesz_fact}), we can then write $q x$ as $q x = z\, w^\sim$, where $z, w^\sim \in \mathcal{H}_2$ and $\| x \|_1 = \| z \|_2\, \| w \|_2$.
Then, we have that
%
\begin{align} \label{eq:equalities}
&\frac{1}{2 \pi} \int_{-\pi}^\pi e^{i \omega}\, g(e^{-i \omega})\, x(e^{i \omega})\, d\omega \nonumber \\
&\qquad = \frac{1}{2 \pi} \int_{-\pi}^\pi g(e^{-i \omega})\, z(e^{i \omega})\, w^\sim (e^{i \omega})\, d\omega \nonumber \\
&\qquad = \frac{1}{2 \pi} \int_{-\pi}^\pi g(e^{i \omega})\, z(e^{-i \omega})\, \overline{w(e^{i \omega})}\, d\omega \\
&\qquad = (M_g R z, w) \nonumber \\
&\qquad = (P_{\mathcal{H}_2} M_g R z, w) \nonumber \\
&\qquad = (\Gamma_g z, w), \nonumber
\end{align}
%
where in the third line we performed the change of variable $\omega \leftrightarrow -\omega$, and %in the fourth line we introduce $x_2 \in \mathcal{H}_2$, defined such that $x^\sim_2(e^{i \omega}) = \overline{x_2(e^{-i \omega})}$; note that $\| \tilde{x}_2 \|_2 = \| x_2 \|_2$.
the fifth line follows from the fact that $w \in \mathcal{H}_2$, so the inner product does not change its value if one projects its first argument onto $\mathcal{H}_2$. Therefore, we have that
%
\begin{align*}
\min_{\hat{f} \in \mathcal{H}_\infty} \| q R g - \hat{f} \|_\infty
&= \sup_{\substack{z, w \in \mathcal{H}_2 \\ \| z \|_2 = \| w \|_2 = 1}} \left| (\Gamma_g z, w) \right| \\
&= \| \Gamma_g \|.
\end{align*}
%
Finally, assume that there is a non-zero $y \in \mathcal{H}_2$ such that $\| \Gamma_g y \|_2 = \| \Gamma_g \| \, \| y \|_2$.
Then, letting $z = z_\text{opt} := (1/\|y\|_2)\, y$ and $w = w_\text{opt} := (1 / \| \Gamma_g y\|_2)\, \Gamma_g y$, which are both in $\mathcal{H}_2$ and have unit norm, we obtain
%
\begin{align} \label{eq:inner_product}
(\Gamma_g z_\text{opt}, w_\text{opt})
&= \frac{1}{\| \Gamma_g y \|_2\, \| y \|_2} (\Gamma_g y, \Gamma_g y) \nonumber \\
&= \frac{1}{\| \Gamma_g \|\, \| y \|_2^2} \| \Gamma_g y \|_2^2 \nonumber \\
&= \frac{1}{\| \Gamma_g \|\, \| y \|_2^2} \| \Gamma_g \|^2\, \|y\|_2^2 \\
&= \|\Gamma_g\|. \nonumber
\end{align}
%
Therefore, $(\Gamma_g z_\text{opt}, w_\text{opt}) = \sup_{z,w \in \mathcal{H}_2,\; \| z \|_2 = \| w \|_2 = 1} \left| (\Gamma_g z, w) \right|$, so $x_\text{opt}(e^{i \omega}) = e^{-i \omega} z_\text{opt}(e^{i \omega})\, \overline{w_\text{opt}(e^{-i \omega})}$ belongs to $\mathcal{H}_1^0$, has norm $1$ (as $\| x^\text{opt} \|_1 = \| z_\text{opt} \|_2 \| w_\text{opt} \|_2 = 1$), and $\langle x_\text{opt}, q R g \rangle = \sup_{x \in \mathcal{H}_1^0,\; \| x \|_1 \leq 1} \left| \langle x, q R g \rangle \right|$.
%; by the last equality, we have that, in fact, $\| x_\text{opt} \|_1 = 1$.
Furthermore, since $x_\text{opt}$ is the product of non-zero functions in $\mathcal{H}_2$, $x_\text{opt}(e^{i \omega}) \neq 0$ for almost all $\omega \in [-\pi, \pi)$. Then, by the last statement in Theorem~\ref{thm:norm_min}, $\langle x_\text{opt}, q R g - \hat{f}_\text{opt} \rangle = \| x_\text{opt} \|_1\, \| q R g - \hat{f}_\text{opt} \|_\infty$, or
%
\begin{align*}
\frac{1}{2 \pi} \int_{-\pi}^\pi x_\text{opt}(e^{i \omega})\, h(e^{i \omega})\, d\omega = \frac{1}{2 \pi} \int_{-\pi}^\pi |x_\text{opt}(e^{i \omega})|\, d\omega,
\end{align*}
%
where $h = (1/\| q R g - \hat{f}_\text{opt} \|_\infty) (q R g - \hat{f}_\text{opt}) \in L_\infty(\mathbb{T})$ is such that $|h(e^{i \omega})| \leq 1$ for almost all $\omega \in [-\pi, \pi)$. By the previous equation, we infer that $|h(e^{i \omega})| = 1$ for almost all $\omega \in [-\pi, \pi)$, \ie, $|e^{i \omega} g(e^{-i \omega}) - \hat{f}_\text{opt}(e^{i \omega})|$ is constant almost everywhere, which is equivalent to stating that $|g(e^{i \omega}) - f_\text{opt}(e^{i \omega})|$ is constant with respect to $\omega$ for almost all $\omega \in [-\pi, \pi)$.
This concludes the proof.
\end{proof}

The solution of the $\mathcal{H}_\infty$ norm minimization problem can be further characterized, thanks to the following corollary due to D. Sarason~\cite[Proposition~5.1]{Sarason-67} (see also \cite[Theorem~3.10]{Partington-88}):

\begin{cor}[Sarason's theorem]
Under the conditions of Theorem~\ref{thm:Nehari_theorem}, if there is a non-zero $y \in \mathcal{H}_2$ such that $\| \Gamma_g y\|_2 = \| \Gamma_g \| \, \| y \|_2$, then the minimizer $f_\text{opt}$ is unique and $g - f_\text{opt} = \Gamma_g y\, /\, R y$.
\end{cor}

\begin{proof}
Let $f_\text{opt}$ be a minimizer of $\| g - f \|_\infty$ over all $f \in \mathcal{H}_\infty^\perp$, and let $z_\text{opt}$ and $w_\text{opt}$ as in the proof of Theorem~\ref{thm:Nehari_theorem}.
Since $f_\text{opt} \in \mathcal{H}_\infty^\perp$, we have that $P_{\mathcal{H}_2} M_{g - f_\text{opt}} = P_{\mathcal{H}_2} M_g$, thus $\Gamma_{g - f_\text{opt}} = \Gamma_g$. Therefore, from \eqref{eq:inner_product}, \eqref{eq:equalities}, and the Cauchy-Schwarz inequality,
%
\begin{align*}
\| \Gamma_g \|
&= \| \Gamma_{g - f_\text{opt}} \| \\
&= (\Gamma_{g - f_\text{opt}} z_\text{opt}, w_\text{opt}) \\
&\leq \| P_{\mathcal{H}_2} M_{g - f_\text{opt}}\, R z_\text{opt} \|_2\, \| w_\text{opt} \|_2 \\
&\leq \| M_{g - f_\text{opt}} \|\, \| R z_\text{opt} \|_2\, \| w_\text{opt} \|_2 \\
&= \| g - f_\text{opt} \|_\infty \| z_\text{opt} \|_2\, \| w_\text{opt} \|_2 \\
&= \| \Gamma_g \|.
\end{align*}
%
Since the lower and upper bounds coincide, we have equality throughout, thus $M_{g - f_\text{opt}}\, R z_\text{opt} = P_{\mathcal{H}_2} M_{g - f_\text{opt}}\, R z_\text{opt} \in \mathcal{H}_2$, \ie, $\Gamma_{g - f_\text{opt}}\, z_\text{opt} =  M_{g - f_\text{opt}}\, R z_\text{opt}$, hence $g - f_\text{opt} = \Gamma_{g - f_\text{opt}}\, z_\text{opt}\, /\, R z_\text{opt} = \Gamma_g\, y\, /\, R y$ (which, in turn, implies that $f_\text{opt}$ is unique).
\end{proof}


