			\par
			\noindent Here $M>1$ and $\mathrm{C}_N(\xi)$ is rapidly decreasing as $\xi\to\infty$ for each $N\in \Z_+$. Moreover,
			$$
			\begin{aligned}
				&\tilde{A}_1(\xi):=-\frac{\sqrt{\tilde{\nu}_1}}{3^{\frac{1}{4}} 2 \sqrt{5 } k_0^{\frac{3}{2}}},\  \tilde{A}_2(\xi):=-\frac{\sqrt{\tilde{\nu}_4}}{3^{\frac{1}{4}} 2 \sqrt{5 } k_0^{\frac{3}{2}}},\\
				&\tilde{\alpha}_1(\xi, t):=\frac{19 \pi}{12}-\left(\arg \tilde{r}_1(k_0)+\arg \Gamma\left(i \tilde{\nu}_1\right)\right)-\left(36 \sqrt{3} t k_0^5\right)+\tilde{\nu}_1 \ln \left(3^{\frac{7}{2}} 20 t k_0^5\right)+\tilde{s}_1,\\
				&\tilde{\alpha}_2(\xi, t):=\frac{11 \pi}{12}-\left(\arg \tilde{r}_2(-k_0)+\arg \Gamma\left(i \nu_4\right)\right)-\left(36 \sqrt{3} t k_0^5\right)+\tilde{\nu}_4 \ln \left(3^{\frac{7}{2}} 20 t k_0^5\right)+\tilde{s}_2,
			\end{aligned}
			$$
			with $k_0=\sqrt[4]{\xi/45}$, $\Gamma(k)$ denotes the Gamma function, and
			$$
			\begin{aligned}
