		\subsection{The Sawada-Kotera equation}
		The scattering matrices \( s(k) \) and \( s^A(k) \) of the SK equation \eqref{SK} exhibit different properties compared to that of the mSK equation (\ref{msk-equation}). Notably, \( s(k) \) and \( s^A(k) \) have a simple pole at \( k=0 \). The details regarding these properties are provided in (\ref{sprop}). Moreover, in order to apply the Deift-Zhou steepest-descent method to the RH problem for the SK equation \eqref{SK},  the following assumption should be imposed.
		\begin{assumption}\label{r less 1}$($Generic behavior at $k=0$$)$. Generically, assume that
			$$
			\lim_{k\to0}k(s_{11}(k))\neq0,\ \lim_{k\to0}k(s^A_{11}(k))\neq0.
			$$
		\end{assumption}
		\noindent When \(u_0(x)=u(x,0) \in \mathcal{S}(\mathbb{R}) \) satisfies the Assumption \ref{solitonless} and Assumption \ref{r less 1}, the reflection coefficients \( r_j(k) \) for \( j=1,2 \) satisfy the properties stated in Theorem \ref{prop for r} below, with \( |r_j(k)| < 1~(j=1,2) \) except at \( k = 0 \).
		\begin{theorem}\label{prop for r}
			Suppose $u_{0}(x) \in \mathcal{S}(\mathbb{R})$, then  $r_{1}(k): (0, \infty) \rightarrow \mathbb{C}$ and $r_{2}(k): (-\infty, 0) \rightarrow \mathbb{C}$ have the following properties:
			$r_1(k)$ and $r_2(k)$ are smooth functions, rapidly decay as $|k|\to\infty $ in their domains and can be extended to $k=0$ in the way below
			$$
			r_{1}(k)=r_{1}(0)+r_{1}^{\prime}(0) k+\frac{1}{2} r_{1}^{\prime \prime}(0) k^{2}+\cdots, \quad k \rightarrow 0,\quad k>0,
			$$
			and
			$$
			r_{2}(k)=r_{2}(0)+r_{2}^{\prime}(0) k+\frac{1}{2} r_{2}^{\prime \prime}(0) k^{2}+\cdots, \quad k \rightarrow 0,\quad k<0,
			$$
			where $r_1(0)=\omega^2$ and $r_2(0)=1$.
		\end{theorem}
		\begin{remark}
			Notice that after gauge transformation (\ref{gauge-matrix}), the isospectral problem of the KK equation (\ref{KK}) has a double pole. In this case, the functions $J_{\pm}(x;k)$, $s(k)$, $J^{A}_{\pm}(x;k)$, $s^{A}(k)$ also have a double pole at $k=0$. Consequently, the behaviors of reflection coefficients $\breve{r}_1(k)$ and $\breve{r}_2(k)$ associated with the KK equation (\ref{KK})
			have different values with that of the SK equation (\ref{SK}), which are $\breve{r}_1(0)=\omega$ and $\breve{r}_2(0)=1$.
		\end{remark}
		\begin{RHproblem}\label{rhp SK}
			Given the reflection coefficients $r_{1}(k)$ and $r_{2}(k)$ associated with the SK equation (\ref{SK}), find a $3 \times 3$ matrix-valued function $M(x, t; k)=M_n(x, t; k)$ for $k\in\Omega_n,~n=1,\cdots,6$ with the following properties:

			(a) $M_n(x, t; k):~ \mathbb{C} \backslash \Sigma \rightarrow \mathbb{C}^{3 \times 3}$ is analytic for $k\in \mathbb{C} \backslash \Sigma$.

			(b) As $k$ approaches $\Sigma $ from the left (+) and right (-), the limits of $ M(x, t; k)$  exist, are continuous on $\Sigma  $ and are related by
			$$
			M_{+}(x, t; k)=M_{-}(x, t; k) v(x, t; k), \quad k \in \Sigma,
			$$
			where $v(x, t; k)=v_n(x, t; k)~(n=1,2,\cdots,6)$ are defined in terms of $r_{1}(k)$ and $r_{2}(k)$ by $(\ref{vn-jump-matrix})$.

			(c)The matrix-valued functions $M_{n}(x;k)$ follow  the symmetries
			\begin{equation}\label{M symmeties}
				M_n(x;k)=\mathcal{A} M_n(x; \omega k) \mathcal{A}^{-1}={\mathcal{B} M_n^*(x;k^*)} \mathcal{B}.
			\end{equation}

			(d) $M(x, t; k)=I+\frac{M_{\infty}^{(1)}(x,t)}{k}+\mathcal{O}\left(k^{-2}\right)$ as $k \rightarrow \infty,~ k \notin \Sigma $, with
			$$
			M_{\infty}^{(1)}(x,t)=\int_x^{\infty}2u(y,t)\mathrm{d}y\left(\begin{array}{ccc}
				\omega^2  & 0 & 0\\
				0 & \omega& 0\\
				0 & 0 & 1\\
			\end{array}
			\right).
			$$

			(e) $M(x, t; k)=\sum_{l=-1}^{p} {M_{0}}^{(l)}(x,t) k^{l}+\mathcal{O}(k^{p+1})$ as $k \rightarrow 0$ with
			$$
			M_0^{(-1)}(x,t)={a_+(x,t)}\begin{pmatrix}
				\omega^2 & 0 & 0\\
				\omega^2 & 0 &0\\
				\omega^2 & 0 &0
			\end{pmatrix},
			$$
			where $a_+(x,t)$ is a real valued function and rapidly decreases as $x\to\infty$.
		\end{RHproblem}
		\begin{theorem}\label{thm for sk}
			Suppose the initial data \(u_0(x) \in \mathcal{S}(\mathbb{R})\) and the scattering data satisfy Assumption \ref{solitonless} and Assumption \ref{r less 1}. Define the reflection coefficients \(r_1(k)\) and \(r_2(k)\) with respect to \(u_0(x)\) as per (\ref{r1r2def}). Then it is established that the RH problem \ref{rhp SK} admits a unique solution \(M(x, t; k)\) whenever it exists, for each point in the domain \((x, t) \in \mathbb{R} \times [0, T)\). Furthermore, the solution \(u(x, t)\) of the SK equation (\ref{SK}) for all \((x, t) \in \mathbb{R} \times [0, T)\) can be expressed by
			\begin{equation}\label{recover-formula SK}
				u(x, t)=-\frac{1}{2} \frac{\partial}{\partial x} \lim _{k \rightarrow \infty} k\left(M_{33}(x, t; k)-1\right).
			\end{equation}
		\end{theorem}
		\begin{proof}
			The proof follows a standard approach. Please refer to \cite{Charlier-Lenells-2021} or \cite{procA} for details.
		\end{proof}
		The Miura transformation \cite{Fordy-Gibbons-1980} establishes a connection between the SK equation (\ref{SK}) and its modified version. In fact, this transformation can be derived directly from their corresponding RH problems.
		\begin{theorem}\label{Miura theorem}
			Assume the reflection coefficients $r_1(k)$ and $r_2(k)$ satisfy the Theorem \ref{prop for r}. Suppose that the $3\times3$ jump matrices $v_n(x, t; k)$ are formulated in (\ref{vn-jump-matrix})
			in terms of $r_1(k)$ and $r_2(k)$. For $x\in\R$ and $t\in[0,\infty)$, the solutions $M(x, t; k)$ and $m(x, t; k)$ for RH problems of the SK equation (\ref{SK}) and the modified SK equation (\ref{msk-equation}) satisfy the following correspondence. Moreover, the Miura transformation between the SK equation (\ref{SK}) and the modified SK equation (\ref{msk-equation}) is reconstructed. They are
			\par		


			\begin{enumerate}[(a)]
				\item Define $A(x,t)$ as
				\begin{equation}\label{miura-A}
					A(x,t)=-\frac{w(x,t)}{3}\begin{pmatrix}
						\omega^2 & \omega  & 1\\
						\omega^2 & \omega  & 1\\
						\omega^2 & \omega  & 1\\
					\end{pmatrix},
				\end{equation}	
				then the $3\times3$ matrix-valued function $M(x,t;k)$  defined by
				\begin{equation}\label{miura-relation}
					M(x,t;k)=\left(I+\frac{A(x,t)}{k}\right)m(x,t;k),
				\end{equation}
				solves the RH problem \ref{rhp SK} for the SK equation (\ref{SK}).

				\item The solutions $u(x,t)$ and $w(x,t)$ of the SK equation (\ref{SK}) and the mSK equation (\ref{msk-equation}) are related by the Miura transformation for $x\in \mathbb{R},0\le t<\infty$, that is
				$$
				u(x,t)=\frac{1}{6}(w_x(x,t)-w(x,t)^2).
				$$	
			\end{enumerate}
		\end{theorem}
		\begin{proof}
			See Section \ref{Miura rhp}.
		\end{proof}
		\begin{theorem}\label{main-theorem-SK}
			Let \(u_0(x) \in \mathcal{S}(\mathbb{R})\) satisfy the assumptions in Theorem \ref{thm for sk}. Then, the solution \(u(x,t)\) of the initial value problem for the SK equation \eqref{SK} exhibits the following asymptotic behaviors as \((x,t) \to \infty\) in the $(x,t)$-half plane (see Figure \ref{categoryforsk}):
			\par
			\noindent {\bf Sector \rm I:}
			$
			u(x, t)=\frac{A_1(\xi)}{\sqrt{t}} \sin \alpha_1(\xi, t)+\frac{A_2(\xi)}{\sqrt{t}} \sin \alpha_2(\xi, t)+
			$
			{$
				\mathcal{O}\left(\frac{1}{x^N}+\frac{\mathrm{C}_N(\xi)}{x}\right)$}
			$,\quad M\le\xi<\infty;
			$
			\par
			\noindent {\bf Sector \rm II:}
			$
			u(x, t)=\frac{A_1(\xi)}{\sqrt{t}} \sin \alpha_1(\xi, t)+\frac{A_2(\xi)}{\sqrt{t}} \sin \alpha_2(\xi, t)+\mathcal{O}\left(\frac{\log t}{t}\right),\quad \frac{1}{M}\le\xi\le M;
			$
			\par
			\noindent {\bf Sector \rm III:}
			This is a transition region that arises due to $|r_j(0)|=1$ for $j=1,2$.
			\par
			\noindent {\bf Sector \rm IV:} This is Painlev\'{e} region and the leading-order term is
			$u(x,t)\sim \frac{1}{6}(5t)^{-\frac{2}{5}}\left(p'(s)-p^2(s)\right)$ with $s=\frac{x}{(5t)^{\frac{1}{5}}}$ and $p(s)$ solves the fourth-order analogues of the Painlev\'{e} transcendent (\ref{Painleve_equation_first}), $\quad|\xi|\le {M}{t^{-\frac{4}{5}}};$
			\par
			\noindent {\bf Sector \rm V:}
			{$
				u(x,t)=\mathcal{O}((|x|+t)^{-j})~j\geq 1,\quad \frac{1}{M}\le|\xi|,x<0.
				$}
			\par
			\noindent Here $\xi=\frac{x}{t}$,  $M>1$, and $\mathrm{C}_N(\xi)$ is rapidly decreasing as $\xi\to\infty$ for each $N\in \Z_+$. Moreover,
			\[
			\begin{aligned}
				&A_1(\xi):=-\frac{\sqrt{\nu_1}}{3^{\frac{3}{4}} 2 \sqrt{5k_0 } },\  A_2(\xi):=-\frac{\sqrt{\nu_4}}{3^{\frac{3}{4}} 2 \sqrt{5k_0 } },\\
				&\alpha_1(\xi, t):=\frac{19 \pi}{12}-\left(\arg r_1(k_0)+\arg \Gamma\left(i \nu_1\right)\right)-\left(36 \sqrt{3} t k_0^5\right)+\nu_1 \ln \left(3^{\frac{7}{2}} 20 t k_0^5\right)+s_1,\\
				&\alpha_2(\xi, t):=\frac{11 \pi}{12}-\left(\arg r_2(-k_0)+\arg \Gamma\left(i \nu_4\right)\right)-\left(36 \sqrt{3} t k_0^5\right)+\nu_4 \ln \left(3^{\frac{7}{2}} 20 t k_0^5\right)+s_2,
			\end{aligned}
			\]
			with $k_0=\sqrt[4]{\xi/45}$, $\Gamma(k)$ denotes the Gamma function, and	
			\[
			\begin{aligned}
				&\nu_1:=-\frac{1}{2 \pi} \ln \left(1-\left|r_1\left(k_0\right)\right|^2\right),\ \nu_4=-\frac{1}{2 \pi} \ln \left(1-\left|r_2\left(-k_0\right)\right|^2\right),\\
				&s_1=\nu_4 \ln (4)+\frac{1}{\pi} \int_{-k_0}^{-\infty} \log _\pi \frac{\left|s-\omega k_0\right|}{\left|s-k_0\right|} \mathrm{d}\ln \left(1-\left|r_2(s)\right|^2\right)+\frac{1}{\pi} \int_{k_0}^{\infty} \log _0 \frac{\left|s-k_0\right|}{\left|s-\omega k_0\right|} \mathrm{d}\ln \left(1-\left|r_1(s)\right|^2\right),\\
				&s_2=\nu_1 \ln (4)+\frac{1}{\pi} \int_{k_0}^{\infty} \log _0 \frac{\left|s+\omega k_0\right|}{\left|s+k_0\right|} \mathrm{d}\ln \left(1-\left|r_1(s)\right|^2\right)+\frac{1}{\pi} \int_{-k_0}^{-\infty} \log _\pi \frac{\left|s+k_0\right|}{\left|s+\omega k_0\right|} \mathrm{d}\ln \left(1-\left|r_2(s)\right|^2\right).
			\end{aligned}
			\]
			{Furthermore, the formula in Sector II holds uniformly with respect to $\xi=x / t$ in compact subset of the stated interval.}
		\end{theorem}
