\section{\bf The Riemman-Hilbert problem and Miura transformation}\label{RHPandmiura}
This section performs the direct and inverse scattering transforms \cite{GGKM-1967} to formulate the RH problems associated with the SK equation (\ref{SK}) and the modified SK equation (\ref{msk-equation}), and reconstructs the Miura transformation between the two equations based on the relationship of the RH problems.
	\par	
	Introduce the gauge transformation
	\begin{equation}\label{gauge-matrix}
		\Phi(x,t;k)=G(k)\Psi(x,t;k) \quad {\rm with}\quad G(k)=\left(
		\begin{array}{ccc}
			{\omega} & {\omega^2} & {1} \\
			{\omega^2}{ k} & {\omega}{ k} & {k} \\
			k^2 & k^2 & k^2 \\
		\end{array}
		\right),\quad \omega=\mathrm{e}^{\frac{2\pi i}{3}},
	\end{equation}
	then the space part of spectral problem (\ref{SK-lax-pair}) with (\ref{SKlaxspace}) is converted into
	\begin{equation}\label{lax-pair-new-x-part}
		\Psi_x=\mathcal{L} \Psi,
	\end{equation}
	where $\mathcal{L}=G^{-1}LG=k\Lambda+Q(x,t;k)$ with
	$$
	\Lambda=\left(\begin{array}{ccc}
		\omega & 0 & 0\\
		0 & \omega^2 & 0\\
		0 & 0 & 1\\
	\end{array}
	\right),\quad
	Q(x,t;k)=-\frac{2u(x,t)}{k}\left(\begin{array}{ccc}
		\omega^2 & \omega & 1\\
		\omega^2 & \omega & 1\\
		\omega^2 & \omega & 1\\
	\end{array}
	\right):=\frac{Q_1}{k}.
	$$
	\begin{remark}
		Similarly, one can take the same gauge transformation on the Lax pair of the KK equation (\ref{KK}). However, in the new spectral problem, which is denoted as $\widetilde{\Psi}_x=\widetilde{\mathcal{L}} \widetilde{\Psi}$, a second-order pole emerges at $k=0$, i.e., $\widetilde{\mathcal L}=k\Lambda+\frac{\widetilde{Q}_1}{k}+\frac{\widetilde{Q}_2}{k^2}$ with $\mathop{{\rm lim}}\limits_{|x|\to \infty}\widetilde{Q}_1=\mathop{{\rm lim}}\limits_{|x|\to \infty}\widetilde{Q}_2=0$, in contrast to the simple pole in the case of the SK equation. This difference arises from the discrepancy between $q_0=0$ (for the SK equation (\ref{SK})) and $q_0=q_x+p$ (for the KK equation (\ref{KK})) in the third-order operator $\mathscr{L}=d^3/dx^3+q_1d/dx+q_0$.
	\end{remark}

	\par
	The gauge transformation (\ref{gauge-matrix}) can map the temporal part of spectral problem (\ref{SK-lax-pair}) with (\ref{SKlaxtime}) into
	\begin{equation}\label{lax-pair-new-t-part}
		\Psi_t=\mathcal{Z} \Psi,
	\end{equation}
	where $\mathcal{Z}=G^{-1}ZG:=9k^5\Lambda^2+P(x,t;k)$     
    with $P(x,t;k)\to0$ as $|x|\to \infty$.
	\par
	Thus the gauge transformation (\ref{gauge-matrix}) transforms the Lax pairs (\ref{SK-lax-pair}) into
	\begin{equation}\label{New-Lax-SK-KK}
		\left\{\begin{array}{l}
			\Psi_x=(k\Lambda+Q) \Psi, \\
			\Psi_t=(9k^5\Lambda^2+P)\Psi.
		\end{array}\right.
	\end{equation}
	Furthermore, the transformation $\Psi=J \mathrm{e}^{(k\Lambda x+9k^5\Lambda^2 t)}$ indicates that
	\begin{equation}\label{Lax-equation}
		\left\{\begin{array}{l}
			J_x-[k\Lambda,J]=Q J, \\
			J_t-[9k^5\Lambda^2,J]=P J. \\
		\end{array}\right.
	\end{equation}
	\par
	In what follows, we only focus on the $x$-variable and take $t$-variable as a dump variable. According to the equation $J_x-[k\Lambda,J]=Q J$, the Volterra integral equations of the Jost functions $J_{+}(x; k)$ and $J_{-}(x; k)$ are written as
	\begin{equation}\label{Jost-functions}
		\begin{aligned}
			& J_{+}(x;k)=I-\int_x^{\infty} \mathrm{e}^{(x-y) \widehat{k\Lambda}}\left(Q(y;k) J_{+}(y;k)\right) d y, \\
			& J_{-}(x;k)=I+\int_{-\infty}^x \mathrm{e}^{(x-y) \widehat{k\Lambda}}\left(Q(y;k) J_{-}(y;k)\right) d y,
		\end{aligned}
	\end{equation}
	which show that the singular set is
	$$
	\Sigma:=\{k\in\mathbb{C}|{\rm Re}(\omega^nk)={\rm Re}(\omega^m k),\quad 0\le n<m<3\},
	$$
	which divides the complex plane into six parts (see Figure \ref{sigma0}), i.e.,
	$$
	\Omega_n:=\left\{k\in\mathbb{C}\bigg|\frac{(n-1)\pi}{3}<{\rm arg}(k)<\frac{n\pi}{3},n=1,2,\cdots,6\right\}.
	$$
