	The following way to construct the RH problem \cite{Boutet-de-Monvel-1,Beals-Coifman-1984}\cite{Lenells-2018}
	is standard, so the proofs of the propositions below are omitted, see \cite{Lin-Wang-Zhu} for details.




	\subsection{Basic properties of the Jost functions}

	\begin{proposition} Let $\mathcal{S}(\R)$ be the Schwartz space.
		Suppose that the SK equation (\ref{SK}) has initial value $u_0(x)\in\mathcal{S}(\R)$ and denote $S=\Omega_3\cup\Omega_4$, then the matrix-valued Jost functions $J_+(x;k)$ and $J_-(x;k)$ possess the following properties:

		(1). $J_+(x;k)$ is well defined in the closure of  $(\omega^2S,\omega S,S)\setminus\{0\}$, and $J_-(x;k)$ is well defined in the closure of  $(-\omega^2S,-\omega S,-S)\setminus\{0\}$. Moreover, the determinants of $J_{\pm}(x;k)$ are always equal to $1$.

		(2). $J_+(\cdot;k)$ and $J_-(\cdot;k)$ are smooth and rapidly decay in the closure of their domains $($except for $\{0\}$$)$.

		(3). $J_+(x;\cdot)$ and $J_-(x;\cdot)$ are analytic in the interior of  their domains, but any order partial derivative of $k$ can be continuous to the closure of their domains $($except for $\{0\}$$)$.

		(4). The functions $J_+(x;k)$ and $J_-(x;k)$ satisfy the following symmetries:
		$$
		\begin{aligned}
			& J_+(x;k)=\mathcal{A} J_+(x; \omega k) \mathcal{A}^{-1}=\mathcal{B} {J_+^*(x; {k}^*)} \mathcal{B},\\
			& J_-(x;k)=\mathcal{A} J_-(x; \omega k) \mathcal{A}^{-1}=\mathcal{B} {J_-^*(x; {k}^*)} \mathcal{B},
		\end{aligned}
		$$
		where $k$ is located in their domains and the matrices $\mathcal{A}$ and $\mathcal{B}$ are given in (\ref{AB-Matrices}).

		(5). When $u_0(x)$ is compact support, $J_+(x;k)$ and $J_-(x;k)$ are well defined and analytic for $k\in\C\setminus\{0\}$. 	
	\end{proposition}

	\noindent{\bf The behavior of Jost functions for $k\to\infty$.}
	Let the WKB expansions of the Jost functions $J_{\pm}(x;k)$ be
	$$
	J_{\pm}(x;k)=I+\frac{J_{\pm}^{(1)}}{k}+\frac{J_{\pm}^{(2)}}{k^2}+\cdots.
	$$
	Taking into account of the equation ({\ref{Lax-equation}}), one has
	\begin{equation}\label{WkB-infty}
		\left\{\begin{array}{l}
			{\left[\Lambda, J_{\pm}^{(n+1)}\right]=(\partial_x J_{\pm}^{(n)})^{(o)}-\left(\mathrm{Q}_1 J_{\pm}^{(n-1)}\right)^{(o)}}, \\
			(\partial_x J_{\pm}^{(n+1)})^{(d)}=\left(\mathrm{Q}_1 J_{\pm}^{(n)}\right)^{(d)},
		\end{array}\right.
	\end{equation}
	with $Q_1(x,t;k)={-2u}\left(\begin{array}{ccc}
		\omega^2 & \omega & 1\\
		\omega^2 & \omega & 1\\
		\omega^2 & \omega & 1\\
	\end{array}
	\right)$, in which the notation $(o)$ means the off-diagonal part of the matrix and $(d)$ denotes the diagonal part. 
	Furthermore, the other expansion coefficients are
	$$
	J_+^{(1)}=\int_x^{\infty}2u(y)dy\left(\begin{array}{ccc}
		\omega^2  & 0 & 0\\
		0 & \omega& 0\\
		0 & 0 & 1\\
	\end{array}
	\right),
	$$
	\begin{equation}\label{J1-infty}
		J_+^{(2)}=\int_x^{\infty}{2u(y)(J_{1+})_{33}}dy\left(\begin{array}{ccc}
			\omega  & 0 & 0\\
			0 & \omega^2 & 0\\
			0 & 0 & 1\\
		\end{array}
		\right)+\frac{2u(x)}{1-\omega}\left(\begin{array}{ccc}
			0  & 1 & -1\\
			-\omega & 0 & \omega\\
			\omega^2 & -\omega^2 & 0\\
		\end{array}
		\right).
	\end{equation}

	\begin{proposition}
		Suppose $u_0(x)\in\mathcal{S}(\R)$, there exist bounded smooth functions $f_{\pm}(x)$, which rapidly decay as $x\to\infty$ and $x\to-\infty$, respectively. Letting $m\ge 0$ be an integer and for each integer $n\ge 0$, it follows
		$$
		\left|\frac{\partial^n}{\partial{k^n}}\left[ J_{\pm}-\left(I+\frac{J_{\pm}^{(1)}}{k}+\cdots+\frac{J_{\pm}^{(m)}}{k^m}\right)\right]\right|\le \frac{f_{\pm}(x)}{k^{m+1}},
		$$
		where $k$ is located in the domains of $J_{+}(x;k)$ and $J_{-}(x;k)$, respectively and is large enough.
	\end{proposition}


	\noindent{\bf The behavior of Jost functions for  $k\to0$.}

	Since the kernel matrix function $Q(x;k)$ has a simple pole at $k=0$, it is necessary to illustrate the asymptotics of $J_{\pm}(x;k)$ as $k\to 0$.

	\begin{proposition}
		Suppose $u_0(x)\in\mathcal{S}(\R)$, there exist bounded smooth functions $g_{\pm}(x)$, which rapidly decay as $x\to\infty$ and $x\to-\infty$, respectively. Let $m\ge 0$ be an integer and for each integer $n\ge 0$, then the Jost function $J_{\pm}(x;k)$ have the asymptotic expansions of the forms:
		$$
		\left|\frac{\partial^n}{\partial{k^n}}\left[ J_{\pm}(x;k)-\left(\frac{\mathcal{J}_{\pm}^{(-1)}}{k}+I+{\mathcal{J}_{\pm}^{(1)}}{k}+\cdots+{\mathcal{J}_{\pm}^{(m)}}{k^m}\right)\right]\right|\le {g_{\pm}(x)}{k^{m+1}},
		$$
		where $k$ is small enough.
		Furthermore, the terms $\mathcal{J}_{\pm}^{(-1)}$ are
		$$
		\mathcal{J}_{\pm}^{(-1)}(x)=a_{\pm}(x)\left(\begin{array}{ccc}
			\omega^2 & \omega & 1 \\
			\omega^2 & \omega & 1 \\
			\omega^2 & \omega & 1
		\end{array}\right),
		$$
		where $a_{\pm}(x)$ are real valued functions and are dominated by $g_{\pm}(x)$ with rapidly decay as $x\to \infty$ and $x\to-\infty$, respectively.
	\end{proposition}

	\subsection{The scattering matrix}

	Define the scattering matrix as
	\begin{equation}\label{Scattering-Ma}
		s(k)=I-\int_{\mathbb{R}} \mathrm{e}^{-xk \widehat{\Lambda}}(Q J)(x;k) d x.
	\end{equation}
	\par
	When the initial potential function $u_0(x)$ is compact support, the scattering matrix $s(k)$ satisfies
	$$
	J_+(x;k)=J_-(x;k) \mathrm{e}^{x k \widehat{\Lambda}} s(k), \quad k \in \mathbb{C}\setminus\{0\}.
	$$
	\begin{proposition}\label{sprop}
		Suppose $u_0(x)\in\mathcal{S}(\R)$, then the scattering function $s(k)$ defined in (\ref{Scattering-Ma}) has the following properties:

		(a) The domain of scattering matrix $s(k)$ is
		$$
		s(k) \in \left(\begin{array}{ccc}
			\omega^{2}\overline{S} & \mathbb{R}_{+} & \omega \mathbb{R}_{+} \\
			\mathbb{R}_{+} & \omega \overline{S} & \omega^{2} \mathbb{R}_{+} \\
			\omega \mathbb{R}_{+} & \omega^{2} \mathbb{R}_{+} & \overline{S}
		\end{array}\right)\setminus\{0\},
		$$
		where $\overline{S}$ means the closure of set $S$ and $s(k)$ is continuous to the boundary of domain but is analytic in the interior of its domain.

		(b) The matrix-valued function $s(k)$ has the following expansions as $k\to\infty$ and $k\to 0$, respectively, that are
		$$
		s(k)=I-\sum_{j=1}^{N} \frac{s_{j}}{k^{j}}+\mathcal{O}\left(\frac{1}{k^{N+1}}\right),\quad k \rightarrow \infty,
		$$
		and
		$$
		s(k)=\frac{s^{(-1)}}{k}+s^{(0)}+s^{(1)} k+\cdots, \quad k \rightarrow 0,
		$$
		with
		$$
		s^{(-1)}=\mathbf{s}^{(-1)}\begin{pmatrix}
			\omega^2 &\omega &1\\
			\omega^2 &\omega &1\\
			\omega^2 &\omega &1\\
		\end{pmatrix},
		$$
		where $\mathbf{s}^{(-1)}$ is a constant in form of integral about the potential function $u_0(x)$.

		(c) The matrix-valued function $s(k)$ satisfies the symmetries:
		$$
		s(k)=\mathcal{A} s(\omega k) \mathcal{A}^{-1}=\mathcal{B} s^*({k}^*) \mathcal{B}.
		$$
	\end{proposition}

	\noindent{
    \bf The cofactor Jost functions}
	Define $M^{A}=(M^{-1})^T$, then the adjoint equation associated with the equation $J_x-[k\Lambda,J]=Q J$ is
	\begin{equation}\label{cofactor-equation}
		\left(J^{A}\right)_{x}+\left[k\Lambda, J^{A}\right]=-Q^{T}J^{A}.
	\end{equation}	
	By the same procedure, one can also get the cofactor Jost functions $J_{\pm}^A(x;k)$ and cofactor scattering matrix $s^A(k)$. Furthermore, the properties of $J_{\pm}^A(x;k)$ and $s^A(k)$ can also be given similarly. Moreover, we have
	\begin{equation}\label{Scattering-Ma-A}
		s^A(k)=I+\int_{\mathbb{R}} \mathrm{e}^{-xk \widehat{\Lambda}}(Q^T J^A)(x;k) d x.
	\end{equation}

	\subsection{The eigenfunctions $M_n$ }

	Define the eigenfunctions for the equation (\ref{Lax-equation}) in each $k\in \Omega_n\setminus\{0\}~(n=1,2,\cdots,6)$ by the following Fredholm integral

	\begin{equation}\label{M_n-eigenfunction}
		\left(M_{n}\right)_{i j}(x;k)=\delta_{i j}+\int_{\gamma_{i j}^{n}}\left(\mathrm{e}^{\left(x-y\right) k\widehat{\Lambda}}\left(Q M_{n}\right)\left(y;k\right)\right)_{i j} d y, \quad i, j=1,2,3,
	\end{equation}
	where $\gamma_{ij}^n=(x,\infty)\ \text{or}\ (-\infty,x)$, which is determined by the exponential part and $\delta_{ij}$ is the Kronecker delta. Notice that there are zeros in Fredholm determinants on the complex plane that is denoted by $\mathcal{Z}$, which is a finite set. However, the solution of (\ref{M_n-eigenfunction}) can be analytic continuation to $\mathcal{Z}$.

	\begin{proposition}
		Suppose $u_0(x)\in\mathcal{S}(\R)$, then the integral equation (\ref{M_n-eigenfunction}) uniquely defines six $3 \times 3$ matrix-valued solutions $\left\{M_{n}\right\}_{n=1}^{6}$ of (\ref{Lax-equation}) with the following properties:

		(a) The eigenfunctions $M_{n}(x;k)$ are defined for $x \in \mathbb{R}$ and $k \in \bar{\Omega}_{n} \backslash{(\mathcal{Z}\cup\{0\})}$. Moreover, the functions $M_{n}(x;k)$ are smooth for $x\in\R$, continuous to $k \in \bar{\Omega}_{n} \backslash{(\mathcal{Z}\cup\{0\})}$ and analytic in the interior of its domain. Except for $k\in\mathcal{Z}\cup\{0\}$, the functions $M_n(x;k)$ are bounded.

		(b) The eigenfunctions $M_{n}(x;k)$ follow  the symmetries
		\begin{equation}\label{Mnsymmeties}
			M_n(x;k)=\mathcal{A} M_n(x; \omega k) \mathcal{A}^{-1}={\mathcal{B} M_n^*(x;k^*)} \mathcal{B},
		\end{equation}
		where $k\in\bar\Omega_k\setminus{(\mathcal{Z}\cup\{0\})}$.

		(c) The determinants of  eigenfunctions $M_{n}(x;k)$ identically equal to one for each $k\in\bar\Omega_k\setminus{(\mathcal{Z}\cup\{0\})}$.
	\end{proposition}



	\noindent{\bf The properties of eigenfunctions $M_n(x;k)$ as $k\to\infty$.}
	\begin{proposition}
		Suppose $u_0(x)\in\mathcal{S}(\R)$ and $u_0(x)$ is not identically equal to zero. Given an integer $m\ge 1$ and for $k$ large enough in its domain, the eigenfunction $M_n(x;k)$ can be approached by the expansion of $J_{+}(x;k)$ as
		\begin{equation}\label{M_n-infty}
			\left| M_{n}(x;k)-\left(I+\frac{J_{+}^{(1)}}{k}+\cdots+\frac{J_{+}^{(m)}}{k^m}\right)\right|\le \frac{C}{k^{m+1}},\quad C\in \R_{+}.
		\end{equation}
	\end{proposition}
	Now, assuming  $u_0(x)\in\mathcal{S}(\R)$ is compact support, then one can get the relationship between $M_n(x;k)$ and $J_{\pm}(x;k)$ for $k \in \bar{\Omega}_{n} \backslash \mathcal{Z}$ and $ x \in \mathbb{R}$ by
	\begin{equation}\label{Sn-Tn}
		\begin{aligned}
			M_{n}(x;k) &=J_-(x;k) \mathrm{e}^{x \widehat{\mathcal{L}(k})} S_{n}(k) \\
			&=J_+(x;k) \mathrm{e}^{x \widehat{\mathcal{L}(k})} T_{n}(k), \quad n=1, 2, \ldots, 6.
		\end{aligned}
	\end{equation}
	Combining the relationship between $J_+(x;k)$ and $J_-(x;k)$, the $S_n(k)$ and $T_n(k)$ can be linked by
	$$
	s(k)=S_{n}(k) T_{n}^{-1}(k), \quad k \in \bar{\Omega}_{n} \backslash (\mathcal{Z}\cup\{0\}) .
	$$
	Since the Schwartz functions with compact support are dense in $\mathcal{S}(\R)$ with respect to the $L^{\infty}$ norm, one can asymptotically express the functions $M_n(x;k)$, $J_{\pm}(x;k)$ and $s(k)$ under generically Schwartz initial potentials by the ones generated from potentials with compact support.

    \noindent{\bf The jump matrices $v_n(x;k)$}\begin{lemma}
		Suppose $u_0(x)\in\mathcal{S}(\R)$, then the matrix-valued functions $M_n(x;k)$ satisfies the boundary condition
		$$
		M_{+}(x;k)=M_{-}(x;k) v(x;  k), \quad k \in \Sigma \backslash(\mathcal{Z}\cup\{0\}),
		$$
		where $v(x;  k)$ is the jump matrix to be determined below.
		\par		
		In particular, when $u_0(x)\in\mathcal{S}(\R)$ is compact support, there exists a matrix $v_1(k)$ such that
		$$
		M_1(x;k)=M_6(x;k) \mathrm{e}^{k x \widehat{\Lambda}} v_1(k).
		$$
		One has $M_n(x;k)=\mathrm{e}^{x \widehat{\mathcal{L}(k)}} S_n(k)$ when $x$ is out of the support of $u_0(x)$ and $x\to-\infty$. Hence, the jump matrix $v_1(k)$ can be calculated by
		$$
		v_1(k)=S_6(k)^{-1} S_1(k).
		$$
	\end{lemma}
	By the same procedure, all the jump functions $v_n(k)~(n=1,2,\cdots,6)$ can be gotten.

	\begin{lemma}
		Let $u_{0}(x) \in \mathcal{S}(\mathbb{R})$, the eigenfunctions $M_{1}(x;k)$ can be expressed in terms of the entries of $J_{\pm}(x;k), J_{\pm}^{A}(x;k), s(k)$, and $s^{A}(k)$ as follows:
		$$
		M_{1}=\left(\begin{array}{clc}
			J^{+}_{11} & \frac{(J^{-}_{31})^{A} (J^{+}_{23})^{A}-(J^{-}_{21})^{A} (J^{+}_{33})^{A}}{s_{11}} & \frac{J^{-}_{13}}{s_{33}^{A}} \\
			J^{+}_{21} & \frac{(J^{-}_{11})^{A} (J^{+}_{33})^{A}-(J^{-}_{31})^{A} (J^{+}_{13})^{A}}{s_{11}} & \frac{J^{-}_{23}}{s_{33}^{A}} \\
			J^{+}_{31} & \frac{(J^{-}_{21})^{A} (J^{+}_{13})^{A}-(J^{-}_{11})^{A} (J^{+}_{23})^{A}}{s_{11}} & \frac{J^{-}_{33}}{s_{33}^{A}}
		\end{array}\right).
		$$
		Furthermore, for $|k|$ small enough, the following property holds
		$$
		\left|M_{n}(x;k)-\sum_{l=-1}^{p} {M}_{n}^{(l)}(x) k^{l}\right| \leq C|k|^{p+1}, \quad k \in \bar{\Omega}_{n}.
		$$

	\end{lemma}
	\par


	Define the jump matrices $v_n(x,t;k)~(n=1,2,\cdots,6)$ for $k\in\Sigma$ (see Figure \ref{sigma0}) as
	\begin{equation}\label{vn-jump-matrix}
		\begin{aligned}
			&\small v_1=\left(\begin{array}{ccc}
				1 & -r_1(k) \mathrm{e}^{-\theta_{21}} & 0 \\
				r_1^*(k) \mathrm{e}^{\theta_{21}} & 1-\left|r_1(k)\right|^2 & 0 \\
				0 & 0 & 1
			\end{array}\right),
			v_2=\left(\begin{array}{ccc}
				1 & 0 & 0 \\
				0 & 1-r_2(\omega k) r_2^*(\omega k) & -r_2^*(\omega k) \mathrm{e}^{-\theta_{32}} \\
				0 & r_2(\omega k) \mathrm{e}^{\theta_{32}} & 1
			\end{array}\right), \\
			&\small v_3=\left(\begin{array}{ccc}
				1-r_1\left(\omega^2 k\right) r_1^*\left(\omega^2 k\right) & 0 & r_1^*\left(\omega^2 k\right) \mathrm{e}^{-\theta_{31}} \\
				0 & 1 & 0 \\
				-r_1\left(\omega^2 k\right) \mathrm{e}^{\theta_{31}} & 0 & 1
			\end{array}\right),
			v_4=\left(\begin{array}{ccc}
				1-\left|r_2(k)\right|^2 & -r_2^*(k) \mathrm{e}^{-\theta_{21}} & 0 \\
				r_2(k) \mathrm{e}^{\theta_{21}} & 1 & 0 \\
				0 & 0 & 1
			\end{array}\right) \text {, } \\
			&\small v_5=\left(\begin{array}{ccc}
				1 & 0 & 0 \\
				0 & 1 & -r_1(\omega k) \mathrm{e}^{-\theta_{32}} \\
				0 & r_1^*(\omega k) \mathrm{e}^{\theta_{32}} & 1-r_1(\omega k) r_1^*(\omega k)
			\end{array}\right),
			v_6=\begin{pmatrix}
				1 & 0 & r_2\left(\omega^2 k\right) \mathrm{e}^{-\theta_{31}} \\
				0 & 1 & 0 \\
				-r_2^*\left(\omega^2 k\right) \mathrm{e}^{\theta_{31}} & 0 & 1-r_2\left(\omega^2 k\right) r_2^*\left(\omega^2 k\right)
			\end{pmatrix},
		\end{aligned}
	\end{equation}
	where the terms $\theta_{i j}=\left(l_i-l_j\right) x+$ $\left(z_i-z_j\right) t$~$(1 \leq j<i \leq 3)$ with $l_1(k)= \omega k,l_2=\omega^2k,l_3=k$ and $z_1(k)=9 \omega^2 k^5,z_2(k)=9 \omega k^5,z_3(k)=9  k^5$.

	Consequently, we can construct the RH problem \ref{rhp SK} for the SK equation (\ref{SK}), which has a singularity at \( k = 0 \). Redeemingly, we can rewrite the RH problem \( M(x,t;k) \) as \( N(x,t;k) := \begin{pmatrix} \omega & \omega^2 & 1 \end{pmatrix} M(x,t;k) \) which is a regular RH problem at $k=0$. In particular, the RH problem for \( N(x,t;k) \) obeys the following properties.

	\begin{RHproblem}
		Given the reflection coefficients $r_{1}(k)$ and $r_{2}(k)$, find a $1 \times 3$ vector-valued function $N(x, t; k)=N_n(x, t; k)$ for $k\in\Omega_n$ with the following properties:

		(a) $N_n(x, t; k):~ \mathbb{C} \backslash \Sigma \rightarrow \mathbb{C}^{3 \times 3}$ is analytic for $k\in \mathbb{C} \backslash \Sigma$.

		(b) The limits of $ N(x, t; k)$ as $k$ approaches $\Sigma $ from the left (+) and right (-) exist, are continuous on $\Sigma  $, and are related by
		$$
		N_{+}(x, t; k)=N_{-}(x, t; k) v(x, t; k), \quad k \in \Sigma,
		$$
		where $v(x, t; k)=v_n(x, t; k)$ for $n=1,2,\cdots,6$ are defined in terms of $r_{1}(k)$ and $r_{2}(k)$ by $(\ref{vn-jump-matrix})$.

		(c) $N(x, t; k)=\begin{pmatrix} \omega & \omega^2 & 1 \end{pmatrix}+\mathcal{O}\left(k^{-1}\right)$ as $k \rightarrow \infty,~ k \notin \Sigma $ and $N(x, t; k)=\mathcal{O}(1)$ as $k \rightarrow 0$.
		The reconstruction formula for the potential function of the SK equation (\ref{SK}) is
		\begin{equation}\label{recover-formula SK RHP N}
			u(x, t)= -\frac{1}{2}\frac{\partial}{\partial x}\lim _{k \rightarrow \infty}k (N(x, t; k)_{3}-1).
		\end{equation}
	\end{RHproblem}

    \begin{remark}
    By the similar way, the RH problem for matrix-valued $m(x,t;k)$ and reconstruction formula of the mSK equation (\ref{msk-equation}) can also be obtained, which are given in RH problem \ref{msk RHP} and Theorem \ref{thm for msk}, see also Ref. \cite{procA}.
    \end{remark}

	\subsection{Miura transformation between the SK equation and mSK equation}\label{Miura rhp}


	At first glance, the relationship between RH problems for $M(x,t;k)$ and $m(x,t;k)$ seems profound. Indeed, one can establish the Miura transformation between the SK equation (\ref{SK}) and the mSK equation (\ref{msk-equation}), as shown in (\ref{miura-SK}), akin to the relationship between the KdV and mKdV equations \cite{Charlier-Lenells-miura}. The proof of Theorem \ref{Miura theorem} is proposed below.
	\begin{proof}
		Suppose
		$$
		M(x,t;k)=\left(I+\frac{A_1(x,t)}{k}\right)m(x,t;k),
		$$
        where the matrix-valued function $A_1(x,t)$ is to be determined. By the symmetries in (\ref{Mnsymmeties}), we have
		$$
A_1(x,t)=\omega^2\mathcal{A}A_1(x,t)\mathcal{A}^{-1},
		$$
		which indicates that
		$$
		A_1(x)=\begin{pmatrix}
			\omega^2c_3 & \omega^2 c_1 & \omega^2 c_2\\
			\omega c_2 & \omega c_3 &\omega c_1\\
			c_1 & c_2 & c_3\\
		\end{pmatrix}.
		$$
		Here the functions $c_1, c_2$ and $c_3$ are determined by considering the limit of $k\to0$. Recall that $r_1(0)=\omega^2$ and $r_2(0)=1$ and thus
		$$
		v_1(0)=\begin{pmatrix}
			1 & -\omega^2 & 0\\
			\omega & 0 & 0\\
			0 & 0 & 1
		\end{pmatrix},\quad
		v_6(0)v_1(0)=\begin{pmatrix}
			1 & -\omega^2 & 1\\
			\omega & 0 & 0\\
			-1 & \omega^2 & 0\\
		\end{pmatrix}.
		$$
		For the RH problem associated with the mSK equation, one has
		$$
		m_{1}(x, t; k)=\mathcal{A}m_1(x,t;\omega k)\mathcal{A}^{-1}(v_6v_1)(x, t; k),
		$$
		thus taking $k=0$ yields
		$$
		m^{(1)}_0=\mathcal{A}m_0^{(1)}\mathcal{A}^{-1}(v_6v_1)(0)
		=\left(\begin{array}{ccc}
			\mathfrak{m}_{11}^{(0)} & \mathfrak{m}_{12}^{(0)} & \mathfrak{m}_{33}^{(0)} \\
			\omega \mathfrak{m}_{11}^{(0)}+\mathfrak{m}_{33}^{(0)}-\mathfrak{m}_{12}^{(0)} & \omega^2\left(\mathfrak{m}_{12}^{(0)}-\mathfrak{m}_{33}^{(0)}\right) & \mathfrak{m}_{33}^{(0)} \\
			\omega^2 \mathfrak{m}_{11}^{(0)}+\mathfrak{m}_{12}^{(0)} & \omega \mathfrak{m}_{12}^{(0)}+\mathfrak{m}_{33}^{(0)} & \mathfrak{m}_{33}^{(0)}
		\end{array}\right).
		$$
		Comparing with the asymptotic expansion of the RH problem for $M(x,t;k)$ of the SK equation (\ref{SK}) at $k=0$, we have
		$$
		M_0^{(-1)}={a_+(x)}\begin{pmatrix}
			\omega^2 & 0 & 0\\
			\omega^2 & 0 &0\\
			\omega^2 & 0 &0
		\end{pmatrix},
		$$
		and
		$$
		M_0^{(-1)}=A_1m^{(1)}_0,
		$$
		thus it follows
		$$
		c_3=-\omega^2c_1-\omega c_2.
		$$
        \par
		Moreover, taking the asymptotics  (\ref{J1-infty}) and (\ref{expansion of m}) as $k\to\infty$ into account, one can deduce that
		$$
		c_1=-\frac{\omega^2}{3}w(x,t),c_2=-\frac{\omega}{3}w(x,t),c_3=-\frac{w(x,t)}{3}.
		$$
		Finally, combining the reconstruction formula (\ref{recover-formula SK}) and (\ref{recover-formula mSK}), it follows that
		$$
		u(x, t)=-\frac{1}{2} \frac{\partial}{\partial x} \lim _{k \rightarrow \infty} k\left(M(x, t; k)_{33}-1\right)\\
		=-\frac{1}{2}\frac{\partial}{\partial x}\left(\frac{1}{3} \int_{\infty}^xw^2-\frac{w(x,t)}{3}\right)=\frac{1}{6}(w_x-w^2).
		$$
	\end{proof}


