	The Deift-Zhou steepest-descent method is adopted through a series of transformations. We would like to denote $M^{(j)}$ as the RH problem after the $j$-th transformations (denote $M^{(0)}=M$), and let $\Sigma^{(j)}$ and $v^{(j)}$ represent the corresponding jump contours and jump matrices of the RH problem for $M^{(j)}$. The contributions to the leading-order term in asymptotic formular due to the local parametrix near the six saddle points $\pm\omega^jk_0~(j=0,1,2)$ and the global parametrix $\Delta(k)$ defined in (\ref{Delta}) below. Thanks to the symmetries outlined in (\ref{m symmeties}) and (\ref{M symmeties}), it is enough to focus on demonstrating the transformations restricted to $\mathbb{R}$ and the analysis in the vicinity of the point $k_0$. Indeed, transformations maintain the symmetries of the RH problems, i.e.,
	\begin{equation}\label{symmetry}
		\begin{aligned}
			& v^{(j)}(x, t; k)=\mathcal{A} v^{(j)}(x, t; \omega k) \mathcal{A}^{-1}=\mathcal{B} \overline{v^{(j)}\left(x, t; \bar k\right)} \mathcal{B}, \quad k \in \Sigma^{(j)} , \\
			& M^{(j)}(x, t; k)=\mathcal{A}M^{(j)}(x, t; \omega k) \mathcal{A}^{-1}=\mathcal{B}\overline{M^{(j)}\left(x, t;\bar  k\right)} \mathcal{B}, \quad k \in \mathbb{C} \backslash \Sigma^{(j)}. \\
		\end{aligned}
	\end{equation}



	\subsection{Global parametrix $\bf \Delta$ and  the first deformation}
	To implement the transformations of the RH problem for $M(x,t;k)$, introduce the global parametrix $\Delta(k)$. For each $\zeta\in [0, \zeta_{\rm{max}}]$ and $\xi$ in some compact subset of $(0,\infty)$, let $\delta_1(\xi;k)$ or $\delta_1(\zeta;k)$: $\C\setminus[k_0,\infty)$ be a solution of the following scalar RH problem
	$$
	\begin{aligned}
		\delta_{1+}(k)  =\delta_{1-}(k)\left(1-|r_1(k)|^2\right), & & k\in[k_0,\infty),
	\end{aligned}
	$$
	while $\delta_4(\xi;k)$ or $\delta_4(\zeta;k)$: $\C\setminus(-\infty,-k_0]$ obeys the jump condition
	$$
	\begin{aligned}
		\delta_{4+}(k) & =\delta_{4-}(k)\left(1-|r_2(k)|^2\right), & & k\in(-\infty,-k_0],
	\end{aligned}
	$$
	where both $\delta_1(k)$ and $\delta_4(k)$ satisfy the normalization condition $\delta_j(k)=1+\mathcal{O}\left(\frac{1}{k}\right)$, as $k\to\infty$ for $j=1,4$. Thanks to Assumptions $\ref{solitonless}$ and $\ref{r less 1}$, it is concluded that $1-|r_j(k)|^2>0$ for $j=1,2$, respectively, when $|k|\geq k_0$. Thus the $\delta_j(k)$ are well-defined and by using the Plemelj's formula, it is derived that
	\begin{equation}\label{delta1}
		\delta_1(k)=\exp \left\{\frac{1}{2 \pi i} \int_{\left[k_0, \infty\right)} \frac{\ln \left(1-\left|r_1(s)\right|^2\right)}{s-k} d s\right\}, \quad k \in \mathbb{C} \backslash [k_0,\infty),
	\end{equation}
	and
	\begin{equation}\label{delta4}
		\delta_4(k)=\exp \left\{\frac{1}{2 \pi i} \int_{[-k_0,-\infty)} \frac{\ln \left(1-\left|r_2(s)\right|^2\right)}{s-k} d s\right\}, \quad k \in \mathbb{C} \backslash (-\infty,-k_0].	
	\end{equation}

	Let $\log_{\theta}(k)$ represents the logarithm of $k$ with the branch cut along $\arg k = \theta$, that is,
	$
	\log_0(k) = \ln|k| + \arg_0(k)$ for $\arg_0(k) \in (0,2\pi)$, and
	$\log_{\pi}(k) = \ln|k| + \arg_{\pi}(k)$ for $\arg_{\pi}(k) \in (-\pi,\pi).$

	\begin{proposition}\label{properties of delta}
		The basic properties of functions $\delta_j(k)$ for $j=1,4$ are given below:
		\par	
		\begin{enumerate}
			\item On the one hand, $\delta_1(k)$ can be rewritten as
			$$
			\delta_1( k)=\mathrm{e}^{-i \nu_1 \log_0\left(k-k_0\right)} \mathrm{e}^{-\chi_1( k)}
			$$
			where
			$
			\nu_1=-\frac{1}{2 \pi} \ln \left(1-\left|r_1\left(k_0\right)\right|^2\right),\ \chi_1(\xi;k)=\frac{1}{2 \pi i} \int_{k_0}^{\infty} \log_0(k-s) \mathrm{d}\ln \left(1-\left|r_1(s)\right|^2\right).
			$

			\noindent One the other hand, one has
			$$
			\delta_4( k)=\mathrm{e}^{-i \nu_4 \log_{\pi}\left(k+k_0\right)} \mathrm{e}^{-\chi_4( k)}
			$$
			where
			$
			\nu_4=-\frac{1}{2 \pi} \ln \left(1-\left|r_2\left(-k_0\right)\right|^2\right),\ \chi_4( \xi;k)=\frac{1}{2 \pi i} \int_{-k_0}^{-\infty} \log_{\pi}(k-s) \mathrm{d}\ln \left(1-\left|r_2(s)\right|^2\right).
			$
			\item  The $\delta_{1\pm}(k)$ and $\delta_{4\pm}(k)$ satisfy the conjugate symmetries and are bounded, for $k>k_0$ and $k<-k_0$, respectively, such that
			$$
			\delta_1( k)={(\overline{\delta_1( \bar{k})})^{-1}}, \  k \in \mathbb{C} \backslash [k_0,\infty),\quad
			\delta_4( k)={(\overline{\delta_4( \bar{k})})^{-1}}, \  k \in \mathbb{C} \backslash (-\infty,-k_0];
			$$
			and
			$
			|\delta_{1}^{\pm 1}(k)|<\infty\ {\rm for}~ k \in \mathbb{C} \backslash [k_0,\infty);\
			|\delta_{4}^{\pm 1}(k)|<\infty\  {\rm for}~~ \mathbb{C} \backslash (-\infty,-k_0].
			$

			\item  As $k\to \pm k_0$ along a path non-tangential to $|k|\ge k_0$, it follows
			$$
			\begin{aligned}
				& \left|\chi_1(\xi;k)-\chi_1\left(\xi;k_0\right)\right| \leq C\left|k-k_0\right|\left(1+|\ln | k-k_0||\right), \\
				& \left|\chi_4(\xi;k)-\chi_4\left(\xi; -k_0\right)\right| \leq C\left|k+k_0\right|\left(1+|\ln | k+k_0||\right), \\
			\end{aligned}
			$$
			where $C$ is a constant independent of $\xi$ and $\zeta$. Especially, for $\xi$ in some subset of $\R_+$, one has
			$$
			\begin{aligned}
				& \left|\partial_x\left(\chi_1(\xi;k)-\chi_1\left(\xi;k_0\right)\right)\right| \leq \frac{C}{t}\left(1+|\ln | k-k_0||\right),\\
				& \left|\partial_x\left(\chi_4(\xi;k)-\chi_4\left(\xi; -k_0\right)\right)\right| \leq \frac{C}{t}\left(1+|\ln | k+k_0||\right),
			\end{aligned}
			$$
			where
			$
			\left|\partial_x \chi_j\left(\xi;k_0\right)\right|\leq \frac{C}{t} 
		$, and
        $	\partial_x\left(\delta_j(\xi;k)^{\pm 1}\right)=\frac{\pm i \nu_j}{180 tk_0^3\left(k-k^*\right)} \delta_j(\xi;k)^{\pm 1}
			$, for $k^*=k_0,j=1$, $k^*=-k_0,j=4$.
		\end{enumerate}
	\end{proposition}
	\begin{proof}
		We focus on proving the properties of $\delta_1(k)$, with the properties of $\delta_4(k)$ being analogous. Using the technique of integration by parts, it is immediate to derive (1) from the expression in (\ref{delta1}). Note that we choose $\log_0$ for $\delta_1(k)$ and $\log_{\pi}$ for $\delta_4(k)$ based on their respective jump conditions. By leveraging the uniqueness of the RH problem associated with $\delta_1(k)$, it can be inferred that $\delta_1(k) = \overline {\delta_1( \bar k)}^{-1}$, which states the second property of $\delta_1(k)$. Based on the representation of $\chi_1$ and the properties of $r_1(k)$, the inequalities in item (3) directly follow from some standard estimates, see \cite{Charlier-Lenells-Wang-2021} and \cite{Charlier-Lenells-2022}.
	\end{proof}
	\par
	Reminding the symmetries in (\ref{symmetry}), define $\delta_j(\xi;k)\ \text{or}\ \delta_j(\zeta;k)$ for $j=2,3,5,6$ as follows:
	$$
	\begin{aligned}
		&\delta_3( k)=\delta_1\left( \omega^2 k\right),\ k \in \mathbb{C} \backslash [\omega k_0,\omega \infty),
		&&\delta_5( k)=\delta_1( \omega k),\ k \in \mathbb{C} \backslash [\omega^2k_0,\omega^2\infty),\\
		&\delta_2( k)=\delta_4\left( \omega k\right),\ k \in \mathbb{C} \backslash (-\omega^2 \infty,-\omega^2 k_0],
		&&\delta_6( k)=\delta_4( \omega^2 k),\ k \in \mathbb{C} \backslash (-\omega \infty,-\omega k_0],
	\end{aligned}
	$$
	which satisfy the jump conditions
	$$
	\begin{aligned}
		&\delta_{3+}( k)=\delta_{3-}( k)\left(1-\left|r_1\left(\omega^2 k\right)\right|^2\right),\ \omega^2 k>k_0 ,
		&&\delta_{5+}( k)=\delta_{5-}( k)\left(1-\left|r_1(\omega k)\right|^2\right), \ \omega k>k_0 ,\\
		&\delta_{2+}( k)=\delta_{2-}( k)\left(1-\left|r_2\left(\omega k\right)\right|^2\right), \ \omega k<-k_0 ,
		&&\delta_{6+}( k)=\delta_{6-}( k)\left(1-\left|r_2(\omega^2 k)\right|^2\right), \ \omega^2 k<-k_0.
	\end{aligned}
	$$


	\begin{remark}
		The expressions for the functions $\delta_n(k)$  include $\log_{\frac{(n-1)\pi}{3}}(k)$ and are respectively defined in the intervals $\frac{(n-1)\pi}{3} < \arg(k) < 2\pi + \frac{(n-1)\pi}{3}$ for $n=1,2,3$. For $n=4,5,6$, the functions $\delta_n(k)$ also involve $\log_{\frac{(n-1)\pi}{3}}(k)$ but are defined in the intervals $-\frac{(7-n)\pi}{3} < \arg(k) < 2\pi - \frac{(7-n)\pi}{3}$.
	\end{remark}

	Now it is ready to define the global parametrix $\Delta(k)$ as 
	\begin{equation}\label{Delta}
		\Delta(k)=\left(\begin{array}{ccc}
			\frac{\delta_1( k)\delta_6( k)}{\delta_3( k)\delta_4( k)} & 0 & 0 \\
			0 & \frac{\delta_5( k)\delta_4( k)}{\delta_1( k)\delta_2( k)} & 0 \\
			0 & 0 & \frac{\delta_3( k)\delta_2( k)}{\delta_5( k)\delta_6( k)}
		\end{array}\right).
	\end{equation}
    \par
	Furthermore, take the first transformation by
	$$
	M^{(1)}(x, t; k)=M(x, t; k) \Delta(k),
	$$
	then the jump matrix is $v^{(1)}(x,t;k)=\Delta^{-1}_-v(x,t;k)\Delta_+$, and the corresponding contour $\Sigma^{(1)}$ is decipited in Figure \ref{Sigma1}. More explicitly, for $|k|>k_0$  the jump matrices $v_1^{(1)}$ and $v_4^{(1)}$ are

	\begin{equation}\label{firstv14}
		\begin{aligned}
			&v_1^{(1)}=
			\begin{pmatrix}
				1-|r_1(k)|^2 & -\frac{\tilde\delta_{v_1}}{\delta_{1-}^2}\frac{r_1(k)}{1-|r_1(k)|^2} \mathrm{e}^{-t \Phi_{21}} & 0 \\
				\frac{\delta_{1+}^2 }{\tilde\delta_{v_1}} \frac{r_1^*(k)}{1-|r_1(k)|^2} \mathrm{e}^{t \Phi_{21}} & 1 & 0 \\
				0 & 0 & 1
			\end{pmatrix},&&k\in\Sigma_{1}^{(1)},\\
			&v_{4}^{(1)}=
			\begin{pmatrix}
				1 & -\frac{\delta_{4+}^2}{\tilde\delta_{v_4}}\frac{r_{2}^{*}(k)}{1-|r_2(k)|^2} \mathrm{e}^{-t\Phi_{21}} & 0 \\
				\frac{\tilde\delta_{v_4}}{\delta_{4-}^2}\frac{r_{2}(k)}{1-|r_2(k)|^2} \mathrm{e}^{t\Phi_{21}} & 1-\left|r_{2}(k)\right|^{2} & 0 \\
				0 & 0 & 1
			\end{pmatrix},&&k\in\Sigma_{4}^{(1)},
		\end{aligned}
	\end{equation}
where $\tilde\delta_{v_1}=\frac{\delta_3\delta^2_4\delta_5}{\delta_6\delta_2}$ and $\tilde\delta_{v_4}=\frac{\delta_1^2\delta_2\delta_6}{\delta_5\delta_3}$.
	On the other hand, the functions $\delta_j(k)$ for $j=1,4$ have no jumps between $-k_0<k<k_0$, thus the jump matrices $v_{7}^{(1)}$ and $v_{10}^{(1)}$ are written as
	\begin{equation}\label{firstv710}
		\begin{aligned}
			&v_7^{(1)}=
			\begin{pmatrix}
				1 & -\frac{\tilde\delta_{v1} }{\delta_{1}^2} r_1(k) \mathrm{e}^{-t \Phi_{21}} & 0 \\
				\frac{\delta_{1}^2 }{\tilde\delta_{v1}} r_1^*(k) \mathrm{e}^{t \Phi_{21}} & 1-r_1(k) r_1^*(k)& 0 \\
				0 & 0 & 1
			\end{pmatrix},&&k\in\Sigma_7^{(1)},\\
			&v_{10}^{(1)}=\begin{pmatrix}
				1-\left|r_{2}(k)\right|^{2} & -\frac{\delta_{4}^2}{\tilde\delta_{v_4}}{r_{2}^{*}(k)} \mathrm{e}^{-t\Phi_{21}} & 0 \\
				\frac{\tilde\delta_{v_4}}{\delta_{4}^2}{r_{2}(k)} \mathrm{e}^{t\Phi_{21}} & 1 & 0 \\
				0 & 0 & 1
			\end{pmatrix},&&k\in\Sigma_{10}^{(1)}.
		\end{aligned}
	\end{equation}
	Furthermore, based on the symmetries in (\ref{symmetry}), the other jump matrices can be derived from (\ref{firstv14}) and (\ref{firstv710}), and they are omitted for brevity.

