	Note that the non-diagonal parts in $v^{(1)}_{1,4}$ involve $\frac{r_j(k)}{1-r_j(k)r_j^{*}(k)}$ for $j=1,2$, and we also need to decompose them. Suppose that
	$$
	\rho_1(k)=\frac{r_1(k)}{1-r_1(k)r_1^{*}(k)},\quad \rho_2(k)=\frac{r_2(k)}{1-r_2(k)r_2^{*}(k)}.
	$$
	\begin{lemma}\label{Lemma-analytic-extension}	
		For any integer $N\ge1$, the functions $r_j(k)$ and $\rho_j(k)~(j=1,2)$ have the following decompositions
		$$
		\begin{array}{ll}
			r_1(k)=r_{1, a}(x, t; k)+r_{1, r}(x, t; k), & k \in\left[0, k_0\right), \\
			r_2(k)=r_{2, a}(x, t; k)+r_{2, r}(x, t; k), & k \in(-k_0,0], \\
			\rho_1(k)=\rho_{1, a}(x, t; k)+\rho_{1, r}(x, t; k), & k \in\left[k_0, \infty\right),\\
			\rho_2(k)=\rho_{2, a}(x, t; k)+\rho_{2, r}(x, t; k), & k \in\left( -\infty,-k_0\right].
		\end{array}
		$$
		Furthermore, the decomposition functions have the properties as follow:

		\begin{enumerate}
