	\begin{proof}
		The proof follows standard techniques outlined in \cite{Deift-Zhou-1993}. Therefore, we only provide a proof of the third property about $\rho_1(k)$ for brevity. Suppose that $M\ge N+1$ is an positive integer, then there exists a rational function $h_0(k)$ which has no poles in $U_6$ and such that $h_0(k)$ is coincided with $\rho_1(k)$ at $k_0$ for $4M$-order, and $h_0(k)=\mathcal{O}(k^{-4M})$, as $k\to\infty$ for $k\in[k_0,\infty)$. Denote $h(k):=\rho_1(k)-h_0(k)$, and notice that $-i\tilde{\Phi}_{21}(\zeta;k):={9\sqrt{3}k^5\zeta-\sqrt{3}k}:=\phi(k)$ is a monotonic increasing function from $[k_0,\infty)\rightarrow[0,\infty)$, and thus define
		$$
		H(\phi):=\begin{cases}
			\begin{aligned}
				&\frac{k^{2M}h(k)}{(k-k_0)^M},&&\phi\ge0,\\
				&0,&&\phi<0.
			\end{aligned}
		\end{cases}
		$$
		It is seen that $H(\phi)$ is a smooth function for $k\in\R\setminus\{k_0\}$, and for $n\ge1$, we have
		$$
		F^{(n)}(\phi)=\left(\frac{1}{(k^4-k_0^4)}\frac{d}{\mathrm{d}k}\right)^n\frac{k^{2M}h(k)}{(k-k_0)^M},\ \phi\ge0.
		$$
		Consequently, for $M$ large enough, it is immediate that $H\in H^{N+1}(\R)$. Introduce
		$$
		\hat H(s)=\frac{1}{\sqrt{2\pi}}\int_{\R}H(\phi)\mathrm{e}^{-i\phi s} d\phi, \quad H(\phi)=\frac{1}{\sqrt{2\pi}}\int_{\R}\hat H(s)\mathrm{e}^{i\phi s} \mathrm{ds},
		$$
		and by the Plancherel's Theorem, $\|s^{N+1}\hat H(s)\|_{L^2(\R)}=\| H^{N+1}(\phi)\|_{L^2(\R)}$, it follows that
		$$
		h(k)=\frac{(k-k_0)^M}{k^{2M}}\frac{1}{\sqrt{2\pi}}\int_{\R}\hat H(s)\mathrm{e}^{\tilde{\Phi}_{21}(\zeta;k)s } \mathrm{ds}.
		$$
		For $x\ge1$, decompose $h(k)$ as $h(k):=h_1(x;k)+h_2(x;k)$ with
		$$
		h_1(x;k)=\frac{(k-k_0)^M}{k^{2M}}\frac{1}{\sqrt{2\pi}}\int_{-\infty}^{\frac{x}{4}}\hat H(s)\mathrm{e}^{\tilde{\Phi}_{21}(\zeta;k)s } \mathrm{ds},
		$$
		and
		$$
		h_2(x;k)=\frac{(k-k_0)^M}{k^{2M}}\frac{1}{\sqrt{2\pi}}\int^{\infty}_{\frac{x}{4}}\hat H(s)\mathrm{e}^{\tilde{\Phi}_{21}(\zeta;k)s } \mathrm{ds}.
		$$
		Since $\Re \tilde{\Phi}_{21}=0$ for $k>k_0$, it states that
		$$
		|h_2(x;k)|\le\frac{C}{1+|k|^N}\|s^{N+1}\hat H(s)\|_{L^2(\R)}x^{-N-\frac{1}{2}},
		$$
		and
		$$
		|h_1(x;k)|\le\frac{(k-k_0)^M}{k^{2M}}\|\hat H(s)\|_{L^1(\R)}\mathrm{e}^{\frac{x}{4}|\Re\tilde{\Phi}_{21}(\zeta;k)|}.
		$$
		Let $\rho_{1,a}(x, t; k):=h_0(x, t; k)+h_1(x, t; k)$ for $k\in\bar U_6$ and $\rho_{1,r}(x, t; k):=h_2(x, t; k)$ for $k\ge k_0$, then the properties in item (3) of $\rho_{1,a}$ and $\rho_{1,r}$ hold. Moreover, since $r_1(k)$ tends to $0$, rapidly as $k\to\infty$, it follows that $k_0=\infty$ as $\zeta=0$, and $r_1(k_0)$ and $\rho_1(k_0)$ vanish.
	\end{proof}
