	\begin{lemma}
		The functions $G^{(1)}(x,t;k)$ and $(G^{(1)}(x,t;k))^{-1}$ are uniformly bounded for $k\in\C\setminus\Sigma^{(2)}$, and $G^{(1)}(x,t;k)=I+\mathcal{O}(\frac{1}{k})$ as $k\to\infty$.
	\end{lemma}
	\begin{proof}
		We focus only on \(G_1^{(1)}(x,t;k)\), the treatment of $(G^{(1)}(x,t;k))^{-1}$ is analogous. Indeed, it suffices to show that  $\frac{\delta_{1+}^2 }{\tilde\delta_{v_1}} \rho^*_{1,a} \mathrm{e}^{t \Phi_{21}}$ and $\frac{\tilde\delta_{v1} }{\delta_{1}^2}r_{1,a} \mathrm{e}^{-t \Phi_{21}}$ are bounded on their corresponding regions. Recall that \(\delta_j(k)\) is bounded in \(\mathbb{C} \setminus \Sigma^{(1)}\), and \(\rho_{1,a}\) and \(r_{j,a}\) satisfy the Lemma \ref{Lemma-analytic-extension}. Hence, it follows that \( \left| \frac{\delta_{1+}^2}{\tilde{\delta}_{v_1}} \rho^*_{1,a} \mathrm{e}^{t \Phi_{21}} \right| \leq \frac{C}{1+|k|^N} \mathrm{e}^{-\frac{3t}{4}|\Re {\Phi}_{21}(\xi;k)|} \) and \( \left| \frac{\tilde{\delta}_{v_1}}{\delta_{1}^2} r_{1,a} \mathrm{e}^{-t \Phi_{21}} \right| \)
		is uniformly bounded due to the compactness in its domain.
	\end{proof}

	\begin{lemma}
		For $\frac{1}{M}\le\xi \le M$ or $\zeta\in[0,\zeta_{\rm{max}}]$, the jump matrix $v^{(2)}$ converges uniformly to identity matrix
 $I$ as $t\to\infty$ or $x\to\infty$ and $\partial_xv^{(2)}$ uniformly converges to the zero matrix except for the points near the saddle points, i.e., $\left\{\pm k_0,\pm \omega k_0,\pm \omega^2k_0\right\}$. In particular, the jump matrix $v^{(2)}$ on $\Sigma_{5,6}$ has the following estimates:
		$$
		\begin{aligned}
			\|(1+|\cdot|)\partial_x^l(v^{(2)}-I)\|_{(L^1\cap L^{\infty})(\Sigma_{5,6}^{(2)})}&\le Ct^{-N},\ \text{for}\ M^{-1}\le\xi\le M,\\
			\|(1+|\cdot|)\partial_x^l(v^{(2)}-I)\|_{(L^1\cap L^{\infty})(\Sigma_{5,6}^{(2)})}&\le Cx^{-N},\ \text{for}\ \zeta\in[0,\zeta_{\rm{max}}].
		\end{aligned}
		$$
		Moreover, reminding the  symmetries of the jump matrices, the similar estimates on the other cuts of $\Sigma_j^{(2)}$  can be gotten immediately. 
	\end{lemma}
	\begin{proof}
		We focus on the jump matrices on $\Sigma_{1,2,\cdots,6}^{(2)}$ and since for $k\in\Sigma_{1,2,3,4}^{(2)}$ the exponential part $\Re{(t\Phi_{21})}$ or $\Re{(x\tilde{\Phi}_{21})}$ is strictly less than zero for $k\in\Sigma_{1,3}^{(2)}$ and strictly larger than zero for $k\in\Sigma_{2,4}^{(2)}$, except for the points near the saddle point $k_0$. Using the Lemma \ref{Lemma-analytic-extension} on the properties of $r_{1,a},\rho_{1,a}$ and the boundedness of the functions $\delta_j(k)$, it is concluded that $v^{(2)}_{1,2,3,4}$ ($\partial_x v_{1,2,3,4}^{(2)}$) converges to $I$ (resp. to the zero matrix) as $t\to\infty$ or $x\to\infty$.
		For \(\frac{1}{M}\le  \xi \le M\), one has
		\[
		(v_5^{(2)} - I)_{12} = -\frac{\tilde{\delta}_{v1}}{\delta_{1}^2} r_{1,r}(k) \mathrm{e}^{-t \Phi_{21}}, \quad
		(v_6^{(2)} - I)_{12} = -\frac{\tilde{\delta}_{v_1}}{\delta_{1-}^2} \rho_{1,r} \mathrm{e}^{-t \Phi_{21}}.
		\]
		Moreover, the properties of \(\delta_j(k)\) for \(j=1,2,\cdots,6\) in Lemma \ref{properties of delta}, along with those of \(r_{j,r}\) and \(\rho_{j,r}\) for \(j=1,2\), imply that
		\[
		|(v_5^{(2)} - I)_{12}| \le Ct^{-N}, \quad |(v_6^{(2)} - I)_{12}| \le Ct^{-N}.
		\]
        \par
		The analysis for \(\zeta \in [0, \zeta_{\rm{max}}]\) is similar and this completes the proof of this lemma.
	\end{proof}


	\subsection{The third deformation }\label{local parmetrices}
	In order to factorize the RH problem for $M^{(2)}(x, t; k)$ into a model problem, focus on the contours $\Sigma_A$ and $\Sigma_B$ of the forms
	$$
	\Sigma_A=\Sigma_{\{1,2,3,4\}}^{(2)}\cap B_{\epsilon}(k_0),\ \Sigma_B=\Sigma_{\{7,8,9,10\}}^{(2)}\cap B_{\epsilon}(-k_0),
	$$
	with the disk $B_{\epsilon}(\pm k_0):=\{k\in\C||k\mp k_0|<\epsilon\}$. Observing that the exponential parts in the jump matrices on the contours $\Sigma_A$ and $\Sigma_B$ are $\pm t\Phi_{21}(\xi;k)$ or $\pm x\tilde{\Phi}_{21}(\zeta;k)$, expand $t\Phi_{21}(\xi;k)$ at $k_0$ into
	$$
	\begin{aligned}
		t\Phi_{21}(k)&=t[(\omega^2-\omega)k\xi+(\omega-\omega^2)9k^5]
		=9t(\omega-\omega^2)(k^5-5kk_0^4)\\
		&=9\sqrt{3}it[(k-k_0)^5+5k_0(k-k_0)^4+10k_0^2(k-k_0)^3+10k_0^3(k-k_0)^2-4k_0^5],
	\end{aligned}
	$$
	and set $t=\frac{x}{45k_0^4}$ to expand $x\tilde{\Phi}_{21}(\zeta;k)$ into 
	$$
	\begin{aligned}
		x\tilde{\Phi}_{21}(k)&=x[(\omega^2-\omega)k+(\omega-\omega^2)9k^5\zeta]
		=\frac{x}{5k_0^4}(\omega-\omega^2)(k^5-5kk_0^4)\\
		&=\frac{\sqrt{3}i x}{5k_0^4}[(k-k_0)^5+5k_0(k-k_0)^4+10k_0^2(k-k_0)^3+10k_0^3(k-k_0)^2-4k_0^5].
	\end{aligned}
	$$

	Suppose  $z_1={3^{\frac{5}{4}}2\sqrt{5t}k_0^{\frac{3}{2}}}(k-k_0)={3^{\frac{1}{4}}2\sqrt{x}k_0^{-\frac{1}{2}}}(k-k_0)$, then rewrite $t\Phi_{21}(\xi;k)$ and $x\tilde{\Phi}_{21}(\zeta;k)$ as
	$$
	\begin{aligned}
		t\Phi_{21}(k)
		&=9\sqrt{3}ita^3[a^2z_1^5+5ak_0z_1^4+10k_0^2z_1^3]+\frac{iz_1^2}{2}+t\Phi_{21}(k_0)\\
		&:=t\Phi_{21}^{0}(k_0;z_1)+\frac{iz_1^2}{2}+t\Phi_{21}(k_0),
	\end{aligned}
	$$
	and
	$$
	\begin{aligned}
		x\tilde{\Phi}_{21}(k)
		&=\frac{\sqrt{3}i x}{5k_0^4}a^3[a^2z_1^5+5ak_0z_1^4+10k_0^2z_1^3]+\frac{iz_1^2}{2}+x\tilde{\Phi}_{21}(k_0)\\
		&:=x\tilde{\Phi}_{21}^{0}(k_0;z_1)+\frac{iz_1^2}{2}+x\tilde{\Phi}_{21}(k_0),
	\end{aligned}
	$$
	where $a=\frac{1}{{3^{\frac{5}{4}}2\sqrt{5t}k_0^{\frac{3}{2}}}}=\frac{k_0^{\frac{1}{2}}}{3^{\frac{1}{4}}2\sqrt{x}}$.
	\par
	The other parts of the jump matrices on contour $\Sigma_A$ involve the function $\delta_1(k)$, i.e.,
	$$
	\delta_1( k)=\mathrm{e}^{-i \nu_1 \log_0\left(k-k_0\right)} \mathrm{e}^{-\chi_1( k)},\quad k\in\C\setminus[k_0,\infty),
	$$
	where
	$$
	\nu_1=-\frac{1}{2 \pi} \ln \left(1-\left|r_1\left(k_0\right)\right|^2\right),
	$$
	and
	$$
	\chi_1( k)=\frac{1}{2 \pi i} \int_{k_0}^{\infty} \log_0(k-s) \mathrm{d}\ln \left(1-\left|r_1(s)\right|^2\right) .
	$$
	Again, rewrite the following fraction as
	$$
	\begin{aligned}
		\frac{\delta_{1+}^{2}(k)}{\delta_{\tilde v_1}(k)}	
		&=\mathrm{e}^{-2i \nu_1 \log_0\left(z\right)}\frac{a^{-2i\nu_1}\mathrm{e}^{-2\chi_1(k_0)}}{\tilde\delta_{ v_1}(k_0)}
		\frac{\mathrm{e}^{2\chi_1(k_0)-2\chi_1(k)}\tilde\delta_{v_1}(k_0)}{\tilde\delta_{ v_1}(k)}\\
		&:=\mathrm{e}^{-2i \nu_1 \log_0\left(z\right)}\delta_A^0\delta_A^1,
	\end{aligned}
	$$
	where $\delta_A^0=\frac{a^{-2i\nu}\mathrm{e}^{-2\chi_1(k_0)}}{\delta_{\tilde v_1}(k_0)}$ and $\delta_A^1=\frac{\mathrm{e}^{2\chi_1(k_0)-2\chi_1(k)}\delta_{\tilde v_1}(k_0)}{\delta_{\tilde v_1}(k)}$.
    \par
	On the other hand, on the contour $\Sigma_B$, expand $t\Phi_{21}(\xi;k)$ and $x\tilde{\Phi}_{21}(\zeta;k)$ at $-k_0$ as
	$$
	\begin{aligned}
		&t\Phi_{21}(k)
		=9\sqrt{3}it[(k+k_0)^5-5k_0(k+k_0)^4+10k_0^2(k+k_0)^3-10k_0^3(k+k_0)^2+4k_0^5],\\
		&x\tilde{\Phi}_{21}(k)
		=\frac{\sqrt{3}i x}{5k_0^4}[(k+k_0)^5-5k_0(k+k_0)^4+10k_0^2(k+k_0)^3-10k_0^3(k+k_0)^2+4k_0^5].
	\end{aligned}
	$$
    \par
	Suppose $z_2={3^{\frac{5}{4}}2\sqrt{5t}k_0^{\frac{3}{2}}}(k+k_0)={3^{\frac{1}{4}}2\sqrt{x}k_0^{-\frac{1}{2}}}(k+k_0)$, and rewrite $t\Phi_{21}$ and $x\tilde{\Phi}_{21}$ as
	$$
	\begin{aligned}
		t\Phi_{21}(k)
		&=9\sqrt{3}ita^3[a^2z^5_2-5ak_0z^4_2+10k_0^2z^3_2]-\frac{iz^2_2}{2}+t\Phi_{21}(-k_0)\\
		&=t\Phi_{21}^{0}(-k_0;z_2)-\frac{iz_2^2}{2}+t\Phi_{21}(-k_0),
	\end{aligned}
	$$
	and
	$$
	\begin{aligned}
		x\tilde{\Phi}_{21}(k)
		&=\frac{\sqrt{3}i x}{5k_0^4}a^3[a^2z^5_2-5ak_0z^4_2+10k_0^2z^3_2]-\frac{iz^2_2}{2}+x\tilde{\Phi}_{21}(-k_0)\\
		&=x\tilde{\Phi}_{21}^{0}(-k_0;z_2)-\frac{iz_2^2}{2}+x\tilde{\Phi}_{21}(-k_0).
	\end{aligned}
	$$
    \par
	Moreover, recall the function $\delta_4$ on the contour $\Sigma_B$ as
	$$
	\delta_4( k)=\mathrm{e}^{-i \nu_4 \log_{\pi}\left(k+k_0\right)} \mathrm{e}^{-\chi_4( k)},\quad k\in\C\setminus(-\infty,-k_0],
	$$
	with
	$$
	\nu_4=-\frac{1}{2 \pi} \ln \left(1-\left|r_2\left(-k_0\right)\right|^2\right),
	$$
	and
	$$
	\chi_4( k)=\frac{1}{2 \pi i} \int_{-k_0}^{-\infty} \log_{\pi}(k-s) \mathrm{d}\ln \left(1-\left|r_2(s)\right|^2\right).
	$$
    \par
	In addition, one has
	$$
	\begin{aligned}
		\frac{\tilde\delta_{v_4}}{\delta_{4}^2}&=\mathrm{e}^{2i \nu_4 \log_{\pi}\left(z_2\right)} \frac{\tilde\delta_{v_4}(-k_0)}{a^{-2i\nu_4}\mathrm{e}^{-2\chi_4( -k_0)}}\frac{\tilde\delta_{ v_4}(k)}{\mathrm{e}^{2\chi_4(-k_0)-2\chi_4(k)}\tilde\delta_{ v_4}(-k_0)}\\
		&:=\mathrm{e}^{2i \nu_4 \log_{\pi}\left(z_2\right)}\left(\delta_B^0\right)^{-1}\left(\delta_B^1\right)^{-1},
	\end{aligned}
	$$
	where $\delta_B^0=\frac{a^{-2i\nu_4}\mathrm{e}^{-2\chi_4(-k_0)}}{\delta_{\tilde v_4}(-k_0)}$ and $\delta_B^1=\frac{\mathrm{e}^{2\chi_4(-k_0)-2\chi_4(k)}\delta_{ v_4}(-k_0)}{\delta_{ \tilde v_4}(k)}$.




	Now, define the matrix-valued function $H(\pm k_0,t)$ and deform the RH problem for $M^{(2)}(x,t;k)$ by the transformation
	$$
	M^{(3,\epsilon)}(x,t;k)=M^{(2)}(x,t;k)H(\pm k_0,t),\quad k\in B_{\epsilon}(\pm k_0),
	$$
	where
	$$
	H(k_0,t)=\left(\begin{array}{ccc}
		\left(\delta_A^{0}\right)^{-\frac{1}{2}} \mathrm{e}^{-\frac{t}{2} \Phi_{21}\left( k_0\right)} & 0 & 0 \\
		0 & \left(\delta_A^{0}\right)^{\frac{1}{2}} \mathrm{e}^{\frac{t}{2} \Phi_{21}\left( k_0\right)} & 0 \\
		0 & 0 & 1
	\end{array}\right),
	$$
	and
	$$
	H(-k_0,t)=\left(\begin{array}{ccc}
		\left(\delta_B^{0}\right)^{\frac{1}{2}} \mathrm{e}^{-\frac{t}{2} \Phi_{21}\left( -k_0\right)} & 0 & 0 \\
		0 & \left(\delta_B^{0}\right)^{-\frac{1}{2}} \mathrm{e}^{\frac{t}{2} \Phi_{21}\left( -k_0\right)} & 0 \\
		0 & 0 & 1
	\end{array}\right).
	$$
	For the case \(\zeta \in [0, \zeta_{\rm{max}}]\), introduce the matrix
    \(\tilde{H}(\pm k_0, x) = H(\pm k_0, t)\). Thus we adopt the convention notation \(H(\pm k_0, t)\) to denote the transformation for both \(M^{-1} \le \xi \le M\) and \(\zeta \in [0, \zeta_{\rm{max}}]\). In order to keep the symbol with the Appendix \ref{appendix}, we let $z$ denote $z_1$ and $z_2$. Consequently, the jump matrices on the contours $\Sigma_A$ and $\Sigma_B$ are
	$$
	\begin{aligned}
		v^{(3,\epsilon)}_1&=\begin{pmatrix}
			1 & 0 & 0 \\
			\mathrm{e}^{-2i \nu_1 \log_0\left(z\right)}\delta_A^1 \rho^*_{1,a} \mathrm{e}^{t \Phi_{21}^0(k_0;z)+\frac{iz^2}{2}} & 1 & 0 \\
			0 & 0 & 1
		\end{pmatrix},\\
		v^{(3,\epsilon)}_2&=\begin{pmatrix}
			1 & \mathrm{e}^{2i \nu_1 \log_0\left(z\right)}(\delta_A^1)^{-1} r_{1,a} \mathrm{e}^{-t \Phi_{21}^0(k_0;z)-\frac{iz^2}{2}} & 0 \\
			0 & 1 & 0 \\
			0 & 0 & 1
		\end{pmatrix},\\
		v^{(3,\epsilon)}_3&=\begin{pmatrix}
			1 & 0 & 0 \\
			-\mathrm{e}^{-2i \nu_1 \log_0\left(z\right)}\delta_A^1r^*_{1,a} \mathrm{e}^{t \Phi_{21}^0(k_0;z)+\frac{iz^2}{2}} & 1 & 0 \\
			0 & 0 & 1
		\end{pmatrix},\\
		v^{(3,\epsilon)}_4&=\begin{pmatrix}
			1 & -\mathrm{e}^{2i \nu_1 \log_0\left(z\right)}(\delta_A^1)^{-1}\rho_{1,a} \mathrm{e}^{-t \Phi_{21}^0(k_0;z)-\frac{iz^2}{2}} & 0 \\
			0 & 1 & 0 \\
			0 & 0 & 1
		\end{pmatrix}.\\
	\end{aligned}
	$$
	Moreover, one also has
	$$
	\begin{aligned}
		v^{(3,\epsilon)}_7&=\begin{pmatrix}
			1 & 0 & 0 \\
			\mathrm{e}^{2i \nu_4 \log_{\pi}\left(z\right)}\left(\delta_B^1\right)^{-1}\rho_{2,a} \mathrm{e}^{t\Phi_{21}^0(-k_0;z_2)-\frac{iz^2}{2}} & 1 & 0 \\
			0 & 0 & 1
		\end{pmatrix},\\
		v^{(3,\epsilon)}_8&=\begin{pmatrix}
			1 & -\mathrm{e}^{-2i \nu_4 \log_{\pi}\left(z\right)}\delta_B^1\rho_{2,a}^{*} \mathrm{e}^{-t\Phi_{21}^0(-k_0;z_2)+\frac{iz^2}{2}} & 0 \\
			0 & 1 & 0 \\
			0 & 0 & 1
		\end{pmatrix},\\
		v^{(3,\epsilon)}_9&=\begin{pmatrix}
			1 & 0 & 0 \\
			-\mathrm{e}^{2i \nu_4 \log_{\pi}\left(z\right)}\left(\delta_B^1\right)^{-1} r_{2,a} \mathrm{e}^{t\Phi_{21}^0(-k_0;z_2)-\frac{iz^2}{2}} & 1 & 0 \\
			0 & 0 & 1
		\end{pmatrix},\\
		v^{(3,\epsilon)}_{10}&=\begin{pmatrix}
			1 & \mathrm{e}^{-2i \nu_4 \log_{\pi}\left(z\right)}\delta_B^1r_{2,a}^* \mathrm{e}^{-t\Phi_{21}^0(-k_0;z_2)+\frac{iz^2}{2}} & 0 \\
			0 & 1 & 0 \\
			0 & 0 & 1
		\end{pmatrix}.\\
	\end{aligned}
	$$

	When $z$ is fixed, it is observed that $r_{j,a} \to r_j(k_0)$, $\rho_{j,a} \to \frac{r_j(k_0)}{1-|r_j(k_0)|^2}$, $\delta_A^1\to 1,$ $\delta_B^1\to 1$ and $\mathrm{e}^{\pm t\Phi_{21}^0(\pm k_0;z)}\to1$ (or $\mathrm{e}^{\pm x\tilde{\Phi}_{21}^0(\pm k_0;z)}\to1$) as $t\to\infty$ for $M^{-1}\le\xi\le M$ (resp. $x\to\infty$ for $0\le\zeta\le\zeta_{\rm{max}}$), so that the jump matrix $v^{3,\epsilon} \to v^X_{A,B}$ as $t\to\infty \ \text{or}\ x\to\infty$, in which $v^{X}_{A,B}$ are the jump matrices of the model problems for $M^{X}_{A}$ and $M^{X}_{B}$ in the Appendix \ref{appendix}. 

	\begin{lemma}
		The matrix-valued function $H(\pm k_0,t)$ is uniformly bounded in sense of
		$$
		\sup_{t\ge 1}|\partial_x^lH(\pm k_0,t)|\le C, \quad M^{-1}\le\xi\le M,
		$$
		and
		$$
		\sup_{x\ge 1}|\partial_x^l\tilde{H}(\pm k_0,x)|\le C, \quad 0\le\zeta\le\zeta_{\rm{max}},
		$$
		for $l=0,1$. Moreover, for $(x,t)$ belong to the Sectors $\rm I$ and $\rm II$, the functions $\delta_{A,B}^0,\delta_{A,B}^1$ satisfy
		$
		|\delta_A^0|=\mathrm{e}^{2\pi\nu},\  |\delta_B^0|=1\
		$, and one has
		$$
		|\delta_{A}^1(k)-1|\le C|k-k_0|(1+|\ln|k- k_0||),\quad
		|\delta_{B}^1(k)-1|\le C|k+k_0|(1+|\ln|k+ k_0||).
		$$
		Especially, for
		$M^{-1}\le\xi\le M$ and $t\ge 1$, it follows that
		$$
		|\partial_x\delta_A^0|\le \frac{C\ln t}{t},\  |\partial_x\delta_B^0|\le \frac{C\ln t}{t},\
		|\partial_x\delta_{A}^1(k)|\le\frac{C}{t}|\ln|k-k_0||,\
		|\partial_x\delta_{B}^1(k)|\le\frac{C}{t}|\ln|k+k_0||.
		$$
		For $0\le\zeta\le \zeta_{\rm{max}}$ and $x\ge1$, it follows that
		$$
		|\partial_x\delta_A^0|\le \frac{Ck_0^4\ln x}{x},\  |\partial_x\delta_B^0|\le \frac{Ck_0^4\ln x}{x},\
		|\partial_x\delta_{A}^1(k)|\le\frac{Ck_0^4}{x}|\ln|k-k_0||,\
		|\partial_x\delta_{B}^1(k)|\le\frac{Ck_0^4}{x}|\ln|k+k_0||.
		$$

	\end{lemma}
	\begin{proof}
		Recalling that $\delta_A^0=\frac{a^{-2i\nu_1}\mathrm{e}^{-2\chi_1(k_0)}}{\tilde \delta_{v_1}(k_0)}$, direct calculation shows that
		$$
		|a^{-2i\nu_1}|=|({3^{\frac{5}{4}}2\sqrt{5t}k_0^{\frac{3}{2}}})^{2i\nu_1}|=|\mathrm{e}^{2i\nu_1 ln(a)}|=1,
		$$
		since the coefficients $\nu_1$ and $a$ are real, and
		$$
		|\tilde \delta_{v_1}(k_0)|=\left|\frac{\delta_3(k_0)\delta^2_4(k_0)\delta_5(k_0)}{\delta_6(k_0)\delta_2(k_0)}\right|=\left|\frac{\delta_1(\omega^2k_0)\delta^2_4(k_0)\delta_1(\omega k_0)}{\delta_4(\omega k_0)\delta_4(\omega^2 k_0)}\right|=1,
		$$
		where the fact that $\delta_{1,4}(k)={(\overline{\delta_{1,4}( \bar{k})})^{-1}}$ and the symmetries between $\delta_{1}(k)$ (resp. $\delta_{4}(k)$) and $\delta_{3,5}(k)$ (resp. $\delta_{2,6}(k)$) have been used.
		\par
		Furthermore, the real part of $\chi_1$ is written as
		$$
		\Re\chi_1(k_0)=\frac{1}{2 \pi} \int_{k_0}^{\infty} \pi \mathrm{d}\ln \left(1-\left|r_1(s)\right|^2\right)=-\frac{1}{2} \ln \left(1-\left|r_1\left(k_0\right)\right|^2\right)=\pi \nu_1,
		$$
		since the branch cut from $0$ to $2\pi$ is chosen.

		Thus we have
		$$
|\delta_A^0|=\left|\frac{a^{-2i\nu_1}\mathrm{e}^{-2\chi_1(k_0)}}{\delta_{\tilde v_1}(k_0)}\right|=\mathrm{e}^{-2\pi\nu_1}.
		$$
		Similarly, it is observed that
		$$
		\Re\chi_4(-k_0)=\frac{1}{2 \pi} \int_{-k_0}^{-\infty} 0 \mathrm{d}\ln \left(1-\left|r_2(s)\right|^2\right)=0,
		$$
		and
		$$
|\delta_B^0|=\left|\frac{a^{-2i\nu_4}\mathrm{e}^{-2\chi_4(-k_0)}}{\tilde\delta_{ v_4}(-k_0)}\right|=1.
		$$

		Moreover, the formulas indicate that
		$$
		\begin{aligned}
			\left|\partial_x \delta_A^0(\zeta, t)\right| & =\left|\delta_A^0(\zeta, t) \partial_x \ln \delta_A^0(\zeta, t)\right|=\mathrm{e}^{-2 \pi \nu_1}\left|\partial_x \ln \delta_A^0(\zeta, t)\right| \\
			& \leq C\left(\left|\ln t \partial_x \nu_1\right|+\left|\partial_x \chi_1\left(k_0\right)\right|+\left|\partial_x \ln \tilde\delta_{v_1}\left( k_0\right) \right|\right).
		\end{aligned}
		$$
        \par
		Since $k_0=\sqrt[4]{\frac{x}{45t}}$, it can be gotten that $\partial_x=\frac{1}{4k_0^3t}\partial_{k_0}$, thus it follows
		$$
		|\partial_x\nu_1| \le C \frac{1}{t} \frac{[\partial_k|r_1(k)|^2]|_{k=k_0}}{1-|r_1(k_0)|^2}\le C\frac{1}{t},\\
		\left|\partial_x \chi_1\left(k_0\right)\right|\le \frac{C}{t},\ \left|\partial_x \ln \tilde\delta_{v_1}\left( k_0\right) \right|\le \frac{C}{t} \left|\partial_{k_0} \ln \tilde\delta_{v_1}\left( k_0\right) \right|,
		$$
		since the function $\tilde\delta_{v_1}(k)$ is analytic near $k_0$.

		Recalling that $\delta_A^1=\frac{\mathrm{e}^{2\chi_1(k_0)-2\chi_1(k)}\delta_{\tilde v_1}(k_0)}{\delta_{\tilde v_1}(k)}$, we have
		$$
		|\mathrm{e}^{2\chi_1(k_0)-2\chi_1(k)}-1|\le C|\chi_1(k_0)-\chi_1(k)|\le C|k-k_0|(1+|\ln|k-k_0||),
		$$
		and direct calculation shows that
		$$
		\partial_x \delta_A^1(k)=\delta_A^1( k) \partial_x \log \delta_A^1( k).
		$$
        \par
		Using the fact that the function $\tilde \delta_{v_1}(k)$ is analytic near $k_0$ again and combining all the estimates above, it can be obtained that
		$$
		\left|\partial_x \delta_{A}^1(\zeta; k)\right| \leq C\left(\left|\partial_x\left(\chi_1( k)-\chi_1\left(k_0\right)\right)\right|+\frac{1}{t}\left|\partial_{k_0} \log \tilde\delta_{v_1}\right|\right)\le \frac{C |\ln|k-k_0||}{t}.
		$$
		Notice that the above estimates still hold for the case \(\zeta \in [0, \zeta_{\rm{max}}]\). Under the equality \(t = \frac{x}{45k_0^4}\), the estimate for \(\tilde{H}(\pm k_0, x)\) can be given similarly.
	\end{proof}
	In conclusion, for $k\in\Sigma_{A,B}$, we have $$M^{(2)}(x,t;k)=M^{(3,\epsilon)}(x,t;k)H(\pm k_0,t)^{-1} \to M^{X_{A,B}}(y;z)H(\pm k_0,t)^{-1}$$ as $t\to\infty$ or $x\to\infty$. But on the boundary of $\partial B_{\epsilon}(\pm k_0)$, the RH problem for $M^{X}_{A,B}H(\pm k_0,t)^{-1}$ does not converge to the identity matrix $I$ as $t\to\infty$, which suggests that a new RH problem should be introduced. To do so, define
	$$
	M^{(\pm k_0)}(x,t;k)=H(\pm k_0,t)M^{X_{A,B}}(y;z)H(\pm k_0,t)^{-1},\quad k\in B_{\epsilon}(\pm k_0),
	$$
	then the following lemma holds.
	\begin{lemma}
		The function $M^{(\pm k_0)}(x,t;k)$ is analytic for $k\in B_{\epsilon}(\pm k_0)\setminus\Sigma_{A,B}$ and satisfies the jump condition $M^{(\pm k_0)}_+=M^{(\pm k_0)}_-V^{(\pm k_0)}$ on the contours $\Sigma_{A,B}$, respectively. Moreover, for $t$ large enough and $M^{-1}\le\xi\le M$, the following estimates hold
		$$
		\|\partial_x^l(v^{(2)}-V^{(\pm k_0)})\|_{L^1(\Sigma_{A,B})}\le C\frac{\ln t}{t},\quad \|\partial_x^l(v^{(2)}-V^{(\pm k_0)})\|_{L^{\infty}(\Sigma_{A,B})}\le C\frac{\ln t}{t^{\frac{1}{2}}}.
		$$
		Furthermore, one has
		$$
		\left\|\partial_x^l\left(M^{(\pm k_0)}(x, t; \cdot)^{-1}-I\right)\right\|_{L^{\infty}\left(\partial B_{\epsilon}(\pm k_0)\right)}  =\mathcal{O}\left(t^{-1 / 2}\right), \\
		$$
		$$
		\frac{1}{2 \pi i} \int_{\partial B_{\left(\pm k_0,\epsilon\right)}}\left(M^{(\pm k_0)}(x, t; k)^{-1}-I\right) d k  =-\frac{H(\pm k_0, t) \left(M^{X_{A,B}}(y)\right)^{(1)} H(\pm k_0, t)^{-1}}{a(t)}+\mathcal{O}\left(t^{-1}\right).
		$$
		On the other hand, for $\zeta\in[0,\zeta_{\rm{max}}]$ and $x\ge1$, it follows that
		$$
		\|\partial_x^l(v^{(2)}-V^{(\pm k_0)})\|_{L^1(\Sigma_{A,B})}\le \frac{\mathrm{C}_N(\zeta)\ln x}{x},\quad \|\partial_x^l(v^{(2)}-V^{(\pm k_0)})\|_{L^{\infty}(\Sigma_{A,B})}\le \frac{\mathrm{C}_N(\zeta)\ln x}{x^{\frac{1}{2}}},
		$$
		and
		$$
		\left\|\partial_x^l\left(M^{(\pm k_0)}(x, t; \cdot)^{-1}-I\right)\right\|_{L^{\infty}\left(\partial B_{\epsilon}(\pm k_0)\right)}  =\mathcal{O}\left(\mathrm{C}_N(\zeta)x^{-1 / 2}\right), \\
		$$
		$$
		\begin{aligned}
			\frac{1}{2 \pi i} \int_{\partial B_{\left(\pm k_0,\epsilon\right)}}\left(M^{(\pm k_0)}(x, t; k)^{-1}-I\right) d k =-\frac{H(\pm k_0, t) \left(M^{X_{A,B}}(y)\right)_{1} H(\pm k_0, t)^{-1}}{a(x)}\\+\mathcal{O}\left(\mathrm{C}_N(\zeta)x^{-1}\right),
		\end{aligned}
		$$
		where $\mathrm{C}_N(\zeta)\ge0$ is a smooth function which vanishes in any order derivative at $\zeta=0$.
	\end{lemma}
	\begin{proof}
		Recall that
		$$
		M^{(k_0)}(x,t;k)=H(k_0,t)M^{X_A}(y;z)H(k_0,t)^{-1},\quad k\in B_{\epsilon}(k_0),
		$$
		where
		$$
		V^{(k_0)}(x,t;k)=H(k_0,t)v^{X_A}(y;z)H(k_0,t)^{-1},
		$$
		and
		$$
		v^{(2)}(x,t;k)=H(k_0,t)v^{(3,\epsilon)}(x,t;k)H(k_0,t)^{-1},
		$$
		thus we get that
		$$
		v^{(2)}-V^{(k_0)}=H(k_0,t)\left(v^{(3,\epsilon)}-v^{X_A}\right)H(k_0,t).
		$$
		Since $H(k_0,t)^{\pm1}$ is bounded and it is sufficient to show that
		$$
		\begin{aligned}
			& \left\|\partial_x^l\left[v^{(3,\epsilon)}(x, t; \cdot)-v^{X_A}(x, t; z(k_0, \cdot))\right]\right\|_{L^1\left(\mathcal{X}_j^\epsilon\right)} \leq C t^{-1} \ln t\ \text{or}\ \mathrm{C}_N(\zeta) x^{-1} \ln x, \\
			& \left\|\partial_x^l\left[v^{(3,\epsilon)}(x, t; \cdot)-v^{X_A}(x, t; z(k_0, \cdot))\right]\right\|_{L^{\infty}\left(\mathcal{X}_j^\epsilon\right)} \leq C t^{-1 / 2} \ln t\ \text{or}\ \mathrm{C}_N(\zeta) x^{-1/2} \ln x.
		\end{aligned}
		$$
		Indeed, the Lemma \ref{Lemma-analytic-extension} shows that for $t$ large enough and $M^{-1}\le\xi\le M$, it follows that
		$$
		\begin{aligned}
			&\left|\mathrm{e}^{-2i \nu_1 \log_0\left(z\right)}\delta_A^1 \rho^*_{1,a} \mathrm{e}^{t \Phi_{21}^0(k_0;z)+\frac{iz^2}{2}} -{\frac{\bar{y}}{1-|y|^2}} z^{-2 i \nu_1(y)} \mathrm{e}^{\frac{i z^2}{2}}\right|\\
			&=|\mathrm{e}^{-2i \nu_1 \log_0\left(z\right)}|\left|\delta_A^1 \rho^*_{1,a} \mathrm{e}^{t \Phi_{21}^0(k_0;z)}-{\frac{\bar{y}}{1-|y|^2}}\right||\mathrm{e}^{\frac{iz^2}{2}}|\\
			&\le C\left|(\delta_A^1-1)\rho^*_{1,a} \mathrm{e}^{t \Phi_{21}^0(k_0;z)}+(\mathrm{e}^{t \Phi_{21}^0(k_0;z)}-1) \rho^*_{1,a}+(\rho^*_{1,a}(k)-\rho^*_{1,a}(k_0))\right||\mathrm{e}^{\frac{iz^2}{2}}|\\
			%		&\le C\left(|k-k_0|ln(|k-k_0|)+|k-k_0| \right)\mathrm{e}^{t\Re\Phi_{21}}|\mathrm{e}^{\frac{iz_1^2}{2}}|\\
			%		&(\le \mathrm{C}_N(\zeta)\left(|k-k_0|ln(|k-k_0|)+|k-k_0| \right)\mathrm{e}^{x\Re\tilde{\Phi}_{21}}|\mathrm{e}^{\frac{iz_1^2}{2}}|)\\
			&\le C |k-k_0|(1+|\ln|k-k_0||)\mathrm{e}^{-ct|k-k_0|^2},
		\end{aligned}
		$$
and for $\zeta\in[0,\zeta_{\rm{max}}]$ and $x\ge1$, it can also be gotten that
$$
\begin{aligned}
			&\left|\mathrm{e}^{-2i \nu_1 \log_0\left(z_1\right)}\delta_A^1 \rho^*_{1,a} \mathrm{e}^{t \Phi_{21}^0(k_0;z)+\frac{iz^2}{2}} -{\frac{\bar{y}}{1-|y|^2}} z^{-2 i \nu_1(y)} \mathrm{e}^{\frac{i z^2}{2}}\right|\\
			&\le \mathrm{C}_N(\zeta)|k-k_0|(1+|\ln|k-k_0||)\mathrm{e}^{-cx|k-k_0|^2},
\end{aligned}
$$
which imply that for $t$ large enough and $M^{-1}\le\xi\le M$, one has
		$$
		\begin{aligned}
			\left\|\left(v^{(3,\epsilon)}-v^{X_A}\right)_{21}\right\|_{L^1\left(\Sigma_A\right)} &\leq C \int_0^{\infty} s(1+|\ln s|) \mathrm{e}^{-c t s^2} d s \leq C t^{-1} \ln t,\\
		\left\|\left(v^{(3,\epsilon)}-v^{X_A}\right)_{21}\right\|_{L^{\infty}\left(\Sigma_A\right)} &\leq C \sup _{s \geq 0} s(1+|\ln s|) \mathrm{e}^{-c t s^2} \leq C t^{-1 / 2} \ln t,	
		\end{aligned}
		$$
		and for $\zeta\in[0,\zeta_{\rm{max}}]$ and $x\ge1$, one has
		$$
		\begin{aligned}
        \left\|\left(v^{(3,\epsilon)}-v^{X_A}\right)_{21}\right\|_{L^1\left(\Sigma_A\right)}&\leq \mathrm{C}_N(\zeta) \int_0^{\infty} s(1+|\ln s|) \mathrm{e}^{-c x s^2} d s \leq \mathrm{C}_N(\zeta) x^{-1} \ln x,\\
			\left\|\left(v^{(3,\epsilon)}-v^{X_A}\right)_{21}\right\|_{L^{\infty}\left(\Sigma_A\right)}&\leq \mathrm{C}_N(\zeta) \sup _{s \geq 0} s(1+|\ln s|) \mathrm{e}^{-c x s^2} \leq \mathrm{C}_N(\zeta) x^{-1 / 2} \ln x.
		\end{aligned}
		$$
		\par
        Furthermore, it is derived that
		$$
		\begin{aligned}
			&\partial_x\left(v^{(3,\epsilon)}-v^{X_A}\right)_{21}\\&=\partial_x(\mathrm{e}^{-2i\nu_1\log_0(z)})\left((\delta_A^1-1)\rho^*_{1,a} \mathrm{e}^{t \Phi_{21}^0(k_0;z)}+(\mathrm{e}^{t \Phi_{21}^0(k_0;z)}-1) \rho^*_{1,a}+(\rho^*_{1,a}(k)-\rho^*_{1,a}(k_0)\right)\mathrm{e}^{\frac{iz^2}{2}}\\
			&+\mathrm{e}^{-2i\nu_1\log_0(z)}\partial_x\left((\delta_A^1-1)\rho^*_{1,a} \mathrm{e}^{t \Phi_{21}^0(k_0;z)}+(\mathrm{e}^{t \Phi_{21}^0(k_0;z)}-1) \rho^*_{1,a}+(\rho^*_{1,a}(k)-\rho^*_{1,a}(k_0)\right)\mathrm{e}^{\frac{iz^2}{2}}\\
			&+\mathrm{e}^{-2i\nu_1\log_0(z)}\left((\delta_A^1-1)\rho^*_{1,a} \mathrm{e}^{t \Phi_{21}^0(k_0;z)}+(\mathrm{e}^{t \Phi_{21}^0(k_0;z)}-1) \rho^*_{1,a}+(\rho^*_{1,a}(k)-\rho^*_{1,a}(k_0)\right)\partial_x\mathrm{e}^{\frac{iz^2}{2}}\\
			&:={\rm I} +{\rm II}+{\rm III}.
		\end{aligned}
		$$
        \par
		For the first part ${\rm I}$, the fact that $|\partial_x\mathrm{e}^{-2i\nu_1\log_0(z)}|\le \frac{C}{t(k-k_0)}(\le\frac{\mathrm{C}_N(\zeta)}{x(k-k_0)})$ indicates that
		$$
		\begin{aligned}
		\|{\rm I}\|_{L^1(\Sigma_A)}&\le C t^{-1} \int_0^{\infty}(1+\ln s) \mathrm{e}^{-c t s^2} d s \leq C t^{-3 / 2} \ln t,\quad {\rm for}~M^{-1}\le\xi\le M,\\
			\|{\rm I}\|_{L^1(\Sigma_A)}&\le \mathrm{C}_N(\zeta) x^{-1} \int_0^{\infty}(1+\ln s) \mathrm{e}^{-c x s^2} d s \leq \mathrm{C}_N(\zeta) x^{-3 / 2} \ln x,\quad {\rm for}~ \zeta\in[0,\zeta_{\rm{max}}],\\
			\|{\rm I}\|_{L^{\infty}(\Sigma_A)} &\leq C t^{-1} \sup _{u \geq 0}(1+\ln s) \mathrm{e}^{-c t s^2} \leq C t^{-1} \ln t,\quad {\rm for}~M^{-1}\le\xi\le M,\\
			\|{\rm I}\|_{L^{\infty}(\Sigma_A)} &\leq \mathrm{C}_N(\zeta) x^{-1} \sup _{u \geq 0}(1+\ln s) \mathrm{e}^{-c x s^2} \leq \mathrm{C}_N(\zeta) x^{-1} \ln x, \quad {\rm for}~ \zeta\in[0,\zeta_{\rm{max}}].
		\end{aligned}
		$$
        \par
		For the parts ${\rm II}$ and ${\rm III}$, the same estimates can also be obtained correspondingly.
		\par
		Since
		$$
		z_1={3^{\frac{5}{4}}2\sqrt{5t}k_0^{\frac{3}{2}}}(k-k_0)={3^{\frac{1}{4}}2\sqrt{x}k_0^{-\frac{1}{2}}}(k-k_0),
		$$
		for the $k\in\partial B_{\epsilon}(k_0)$, it is obvious that $z_1\to\infty$ as $t\to\infty$ and $z_1\to\infty$ as $x\to\infty$. Combining this with the WKB expansion of $M^{X_A}$, it is found that
		$$
		\begin{aligned}
			M^{X_A}(y;z)&=I+\frac{M^{X_A}_1(y)}{{3^{\frac{5}{4}}2\sqrt{5t}k_0^{\frac{3}{2}}}(k-k_0)}+\mathcal{O}\left(\frac{1}{t}\right),\quad {\rm as}~t\to\infty,\\
			M^{X_A}(y;z)&=I+\frac{M^{X_A}_1(y)}{{3^{\frac{1}{4}}2\sqrt{x}k_0^{-\frac{1}{2}}}(k-k_0)}+\mathcal{O}\left(\frac{ \mathrm{C}_N(\zeta)}{x}\right),\quad {\rm as}~x\to\infty,
		\end{aligned}
		$$
		and further 
		$$
		\begin{aligned}
			\left(M^{(k_0)}\right)^{-1}-I&=-\frac{H(k_0, t) M_1^{X_A}(y) H(k_0, t)^{-1}}{{3^{\frac{5}{4}}2\sqrt{5t}k_0^{\frac{3}{2}}}(k-k_0)}+\mathcal{O}\left(t^{-1}\right), \quad t \rightarrow \infty\\
			\left(M^{(k_0)}\right)^{-1}-I&=-\frac{H(k_0, t) M_1^{X_A}(y) H(k_0, t)^{-1}}{{3^{\frac{1}{4}}2\sqrt{x}k_0^{-\frac{1}{2}}}(k-k_0)}+\mathcal{O}\left( \mathrm{C}_N(\zeta)x^{-1}\right), \quad x \rightarrow \infty.
		\end{aligned}
		$$
	\end{proof}
	\subsection{Local parametrix near the saddle points}
	By means of the symmetry properties of the RH problems, deform the RH problem for $M^{(\pm k_0)}$ in the way
	$$
	\tilde M^{(\pm k_0)}(x,t;k)=\mathcal{A}M^{(\pm k_0)}(x,t;\omega k)\mathcal{A}^{-1}.
	$$
	Denote $\tilde B^{(\pm k_0)}_{\epsilon}=B_{\epsilon}(\pm k_0)\cup B_{\epsilon}(\pm \omega k_0)\cup B_{\epsilon}(\pm \omega^2 k_0)$ and introduce a new RH problem with solution $\tilde M(x,t;k)$ as follows:
	$$
	\tilde M(x,t;k):=\begin{cases}\begin{aligned}
			&M^{(2)}\left(\tilde M^{(k_0)}\right)^{-1}, &&k\in \tilde B^{(k_0)}_{\epsilon},\\
			&M^{(2)}\left(\tilde M^{(-k_0)}\right)^{-1},&&k\in \tilde B^{(-k_0)}_{\epsilon},\\
			&M^{(2)}, && \text{otherelse}.
		\end{aligned}
	\end{cases}
	$$
	Moreover, the jump contour is denoted as $\tilde{\Sigma}:=\Sigma^{(2)}\cup\partial \tilde B^{(k_0)}_{\epsilon}\cup \partial \tilde B^{(-k_0)}_{\epsilon}$ (see Figure \ref{Sigmatilde})
	and the jump matrices are defined by
	$$
	\tilde{V}:=\begin{cases}\begin{aligned}
			&v^{(2)}, && k \in \tilde{\Sigma}\setminus \overline {\left(\tilde B^{(\pm k_0)}_{\epsilon}\right)},\\
			&(\tilde M^{(k_0)})^{-1}, && k \in \partial \tilde B^{(k_0)}_{\epsilon},\\
			&(\tilde M^{(-k_0)})^{-1}, && k \in \partial \tilde B^{(-k_0)}_{\epsilon},\\
			&\tilde M^{(k_0)}_{-}v^{(2)}(\tilde M^{(k_0)}_+)^{-1}, && k \in \tilde B^{(k_0)}_{\epsilon}\cap \tilde{\Sigma},\\
			&\tilde M^{(-k_0)}_{-}v^{(2)}(\tilde M^{(-k_0)}_+)^{-1}, && k \in \tilde B^{(-k_0)}_{\epsilon}\cap \tilde{\Sigma}.

	\end{aligned}\end{cases}
	$$
    \par
	Thus we have constructed a new RH problem for $\tilde M(x,t;k)$ that satisfies $\tilde M_+(x,t;k)=\tilde M_-(x,t;k)\tilde V$ for $k\in\tilde \Sigma$ and is analytic in $\C\setminus \tilde\Sigma$.

	Suppose $\tilde\Sigma_{A,B}:=\Sigma_{A,B}\cup\omega\Sigma_{A,B}\cup\omega^2\Sigma_{A,B}$ and denote
	$$
\Sigma':=\tilde{\Sigma}\setminus\left(\Sigma\cup\tilde\Sigma_{A,B}\cup\partial \tilde{B}^{(\pm k_0)}_{\epsilon}\right).
	$$


