	\begin{lemma}
		Let $W=\tilde V-I$. The following estimates hold uniformly for $t$ large enough and $M^{-1}\le\xi\le M$
		$$
		\begin{aligned}
			& \left\|(1+|\cdot|) \partial_x^l {W}\right\|_{\left(L^1 \cap L^{\infty}\right)(\Sigma)} \leq \frac{C}{k_0^3 t}, \\
			& \left\|(1+|\cdot|) \partial_x^l W\right\|_{\left(L^1 \cap L^{\infty}\right)\left(\Sigma^{\prime}\right)} \leq C \mathrm{e}^{-c t}, \\
			& \left\|\partial_x^l W\right\|_{\left(L^1 \cap L^{\infty}\right)(\partial \tilde{B}^{(\pm k_0)})} \leq C t^{-1 / 2}, \\
			& \left\|\partial_x^l W\right\|_{L^1\left(\tilde{\Sigma}_{A,B}\right)} \leq C t^{-1} \ln t, \\
			& \left\|\partial_x^l W\right\|_{L^{\infty}\left(\tilde{\Sigma}_{A,B}\right)} \leq C t^{-1 / 2} \ln t,
		\end{aligned}
		$$
and for $\zeta\in[0,\zeta_{\rm{max}}]$ and $x$ large enough, similar estimates also hold
        $$
		\begin{aligned}
			& \left\|(1+|\cdot|) \partial_x^l {W}\right\|_{\left(L^1 \cap L^{\infty}\right)(\Sigma)} \leq \frac{\mathrm{C}_N(\zeta)}{ x}, \\
			& \left\|(1+|\cdot|) \partial_x^l W\right\|_{\left(L^1 \cap L^{\infty}\right)\left(\Sigma^{\prime}\right)} \leq Cx^{-N}, \\
			& \left\|\partial_x^l W\right\|_{\left(L^1 \cap L^{\infty}\right)(\partial \tilde{B}^{(\pm k_0)})} \leq \mathrm{C}_N(\zeta) x^{-1 / 2}, \\
			& \left\|\partial_x^l W\right\|_{L^1\left(\tilde{\Sigma}_{A,B}\right)} \leq \mathrm{C}_N(\zeta) x^{-1} \ln x, \\
			& \left\|\partial_x^l W\right\|_{L^{\infty}\left(\tilde{\Sigma}_{A,B}\right)} \leq \mathrm{C}_N(\zeta) x^{-1/2} \ln x.
		\end{aligned}
		$$
	\end{lemma}


	\begin{proof} We first prove the case that $t$ is large enough and $M^{-1}\le\xi\le M$.
    \par
		For the first inequality, notice that the jump matrix on $\Sigma$ involves the terms $r_{j,r}$ and $\rho_{j,r},~j=1,2$, and the function $(\tilde M^{(\pm k_0)})^{\pm1}$ is bounded, then we have
		$$
		\|(1+|\cdot|)\partial_x^l(v^{(2)}-I)\|_{(L^1\cap L^{\infty})(\Sigma_{5,6}^{(2)})}\le Ct^{-1}.
		$$
		So that on the cuts $\Sigma^{(2)}_{5,6}\cap B_{\epsilon}(k_0)$, it follows that
		$$
		W=\tilde V-I=M^{(k_0)}_-v^{(2)}\left(M^{(k_0)}_+\right)^{-1}-I=M^{(k_0)}_-\left(v^{(2)}-I\right)\left(M^{(k_0)}_+\right)^{-1}.
		$$
		Since the jump of the RH problem for $\tilde M^{(\pm k_0)}$ is on contours $\tilde\Sigma_{A,B}$, the function $\tilde M^{(k_0)}$ is analytic on $\Sigma^{(2)}_{5,6}\cap B_{\epsilon}(k_0)$ and is bounded. Then we have
		$$
		\left\|(1+|\cdot|) \partial_x^l {W}\right\|_{\left(L^1 \cap L^{\infty}\right)(\Sigma)} \leq \frac{C}{k_0^3 t}. \\
		$$
        \par
		For the second inequality, notice the contour $\Sigma'=\Sigma^{(2)}\setminus\overline{\tilde{B}^{(\pm k_0)}_\epsilon}$. We would like to focus on the contour $\Sigma^{(2)}\setminus B_{\epsilon}(k_0)$ and the matrix $W$ involving the entry $(v^{(2)}_1)_{21}=\frac{\delta_{1+}^2 }{\tilde\delta_{v_1}} \rho^*_{1,a} \mathrm{e}^{t \Phi_{21}}\neq 0$.
		Because the functions $\partial_x^l\delta_j~(j=1,2,\cdots,6)$ are bounded, the estimate of $\rho^*_{1,a}$ is
		$$
		\left|\partial_x \rho_{1, a}^*(x, t; k)\right| \leq \frac{C\mathrm{e}^{t\Re \Phi_{21}( k)}}{1+|k|}.
		$$
		Moreover, it is seen that $\Re\Phi_{21}<-c$ for $|k-k_0|>\epsilon$, so that the following inequality holds
		$$
		\left\|(1+|\cdot|) \partial_x^l W\right\|_{\left(L^1 \cap L^{\infty}\right)\left(\Sigma^{\prime}\right)} \leq C \mathrm{e}^{-c t}. \\
		$$
        \par
		The third inequality is reached by direct outcome of the above lemmas.
        \par
		For the last inequality, noticing that
		$$
		W=\tilde M^{(k_0)}_{-}(v^{(2)}-V^{(k_0)})(\tilde M^{(k_0)}_+)^{-1},\quad k\in\tilde \Sigma_{A},
		$$
 it is found that the function $M^{(k_0)}$ is bounded uniformly for $M^{-1}\le\xi\le M$. For \(\zeta \in [0, \zeta_{\rm{max}}]\), the proof of the inequalities in this lemma follows a similar approach.
	\end{proof}




	Now, introduce the Cauchy operator
	$$
	\left({C} f\right)(z)=\int_{\tilde\Sigma} \frac{f(\zeta)}{\zeta-z} \frac{\mathrm{d} \zeta}{2 \pi i}, \quad z \in \C\setminus \tilde \Sigma.
	$$
	If $(1+|z|)^{\frac{1}{3}}f(z)\in L^3(\tilde\Sigma)$, then $(Cf)(z)$ is analytic from $\C\setminus\tilde\Sigma$ to $\C$ with property that for any component $D$ in $\C\setminus \tilde \Sigma$, there are curves $\{\mathrm{C}_n \}_{n=1}^\infty$ which surround each compact subset of $D$ satisfying
	$$
	\sup_{n\ge1}\int_{\mathrm{C}_n}(1+|z|)|f(z)|^3|dz|<\infty.
	$$
	Moreover, $C_{\pm}f$ exist a.e. for $z\in\tilde\Sigma$ and $(1+|z|)^{\frac{1}{3}}C_{\pm}f(z)\in L^3(\tilde\Sigma)$.

	On one hand, the $C_{\pm}$ are bounded operators from weighted space $L^3(\tilde\Sigma)$ to itself (thus denote it as $\dot L^{3}(\tilde\Sigma)$), which satisfy $C_+-C_-=I$.

	On the other hand, recall the estimates for $l=0,1$
	$$
	\begin{cases}\begin{aligned}
			&\|(1+|\cdot|)\partial_x^lW\|_{L^1(\tilde\Sigma)}\le C t^{-\frac{1}{2}},\\
			&\|(1+|\cdot|)\partial_x^lW\|_{L^{\infty}(\tilde\Sigma)}\le C t^{-\frac{1}{2}}\ln t.\\
	\end{aligned}\end{cases}
	$$
    \par
	Then the Riesz interpolation inequality yields that
	$$
	\|(1+|\cdot|)\partial_x^lW\|_{L^p(\tilde\Sigma)}\le C t^{-\frac{1}{2}}(\ln t)^{\frac{1}{p}},
	$$
	so that $W$ belongs to the weighted space $L^3(\tilde\Sigma)$ and $L^{\infty}(\tilde\Sigma)$.



	Define the map $C_W:\dot L^3(\tilde\Sigma)+ L^{\infty}(\tilde\Sigma)\to \dot L^3(\tilde\Sigma)$ by
	$$
	C_{W} f=C_{+}\left(fW_{-}\right)+C_{-}\left(fW_{+}\right),
	$$
    then the following lemma holds.


	\begin{lemma}\label{invertible}
		For $t$ large enough and $M^{-1}<\xi<M$, the operator $I-C_W$ is invertible and $(I-C_W)^{-1}$is a bounded linear operator from $\dot L^3(\tilde\Sigma)$ to itself.
	\end{lemma}

	\begin{proof}
		Since $C_{\pm}$ are bounded operators from weighted space $L^3(\tilde\Sigma)$ to itself, then for any $f\in\dot L^3(\tilde\Sigma)$, we have
		$$
		\begin{aligned}	C_Wf&={C}_{+}\left(fW_{-}\right)+{C}_{-}\left(fW_{+}\right)\\
			%		&\le \|C_+\|_{\dot L^3(\tilde\Sigma)\to\dot L^3(\tilde\Sigma)}\|W\|_{L^\infty(\tilde\Sigma)}\|f\|_{\dot L^3(\tilde\Sigma)}+\|C_-\|_{\dot L^3(\tilde\Sigma)\to\dot L^3(\tilde\Sigma)}\|W\|_{L^\infty(\tilde\Sigma)}\|f\|_{\dot L^3(\tilde\Sigma)}\\
			&\le \left(\|C_+\|_{\dot L^3(\tilde\Sigma)\to\dot L^3(\tilde\Sigma)}+\|C_-\|_{\dot L^3(\tilde\Sigma)\to\dot L^3(\tilde\Sigma)}\right)\|W\|_{L^\infty(\tilde\Sigma)}\|f\|_{\dot L^3(\tilde\Sigma)}.\\
		\end{aligned}
		$$
		Then $\|C_W\|_{\dot L^3(\tilde\Sigma)\to\dot L^3(\tilde\Sigma)}\le \left(\|C_+\|_{\dot L^3(\tilde\Sigma)\to\dot L^3(\tilde\Sigma)}+\|C_-\|_{\dot L^3(\tilde\Sigma)\to\dot L^3(\tilde\Sigma)}\right)\|W\|_{L^\infty(\tilde\Sigma)}$, and by the estimate above, it follows that for $l=0,1$
		$$
		\|(1+|\cdot|)\partial_x^lW\|_{L^{\infty}(\tilde\Sigma)}\le C t^{-\frac{1}{2}}(\ln t),\quad t\to \infty.\\
		$$
		Thus $\|W\|_{L^\infty(\tilde\Sigma)}<\frac{1}{\left(\|C_+\|_{\dot L^3(\tilde\Sigma)\to\dot L^3(\tilde\Sigma)}+\|C_-\|_{\dot L^3(\tilde\Sigma)\to\dot L^3(\tilde\Sigma)}\right)}$ holds, then the operator $I-C_W$ is invertible.
	\end{proof}
	\begin{remark}
		For $\zeta\in[0,\zeta_{\rm{max}}]$ and $x$ large enough, the Lemma \ref{invertible} still holds and the proof is similar, just replacing 
        $\|(1+|\cdot|)\partial_x^lW\|_{L^{\infty}(\tilde\Sigma)}\le C t^{-\frac{1}{2}}(\ln t)$ with $\|(1+|\cdot|)\partial_x^lW\|_{L^{\infty}(\tilde\Sigma)}\le \mathrm{C}_N(\zeta) x^{-\frac{1}{2}}(\ln x)$.
	\end{remark}
	Let $\mu\in I+\dot L^3(\tilde \Sigma)$ satisfy the integral equation $\mu=I+C_W\mu,$ then one has $\mu=I+(I-C_W)^{-1}C_WI$.



	\begin{lemma}
		For $t$ large enough and $M^{-1}<\xi<M$ or $\zeta\in[0,\zeta_{\rm{max}}]$ and $x$ large enough, the RH problem for the function $\tilde M(x,t;k)$ has a unique solution of the form
		$$
		\tilde M(x,t;k)=I+C(\mu W)=I+\int_{\tilde\Sigma} \frac{\mu(x,t;\zeta)W(x,t;\zeta)}{\zeta-k} \frac{\mathrm{d} \zeta}{2 \pi i}, \quad k \in \C\setminus \tilde \Sigma.
		$$
	\end{lemma}



	\begin{lemma}
		For $t$ large enough, $M^{-1}<\xi<M$ and for $1\le p\le\infty$, it is found that
		$$
		\|\partial_x^l(\mu-I)\|_{L^p(\tilde \Sigma)}\le  {\frac{C(\ln t)^{\frac{1}{p}}}{t^{\frac{1}{2}}}},\quad l=0,1.
		$$
        Moreover, for $x$ large enough and $\zeta\in[0,\zeta_{\rm{max}}]$, it follows that
        $$
		\|\partial_x^l(\mu-I)\|_{L^p(\tilde \Sigma)}\le  {\frac{\mathrm{C}_N(\zeta)(\ln x)^{\frac{1}{p}}}{x^{\frac{1}{2}}}},\quad l=0,1.
		$$

	\end{lemma}

	\begin{proof}
		Denote $\|C_{\pm}\|_p:=\left(\|C_+\|_{L^p(\tilde\Sigma)\to L^p(\tilde\Sigma)}+\|C_-\|_{ L^p(\tilde\Sigma)\to L^p(\tilde\Sigma)}\right)$ and assume $t$ large enough to satisfy $\|W\|_{L^{\infty}(\tilde\Sigma)}<\|C_{\pm}\|_p^{-1}$. When $l=0$, we have
		$$
		\begin{aligned}
			\|\mu-I\|_{L^p(\tilde\Sigma)}&\le \sum_{j=1}^\infty\|C_{\pm}\|^{j}_{p}\|W\|^{j-1}_{L^\infty(\tilde \Sigma)}\|W\|_{L^p(\tilde\Sigma)}=\frac{\|C_{\pm}\|_p \|W\|_{L^p(\tilde\Sigma)}}{1-\|C_{\pm}\|_p\|W\|_{L^{\infty}(\tilde\Sigma)}}.
		\end{aligned}
		$$
		So combining the estimate of $\|W\|_{L^p(\tilde\Sigma)}$, the estimate for $l=0$ holds immediately. 

		When $l=1$, it can be gotten that
		$
		\partial_x(\mu-I)=\partial_x\sum_{j=1}^\infty(C_W)^jI.
		$
		Since the series on the right hand side is uniformly bounded and the order of sum and derivative can be changed, then we have
		$$
		\begin{aligned}
			\|\partial_x(\mu-I)\|_{L^p(\tilde\Sigma)}&\leq \sum_{j=2}^{\infty}(j-1)\left\|{{C}}_W\right\|_{L^p(\tilde{\Sigma})\to L^p(\tilde{\Sigma})}^{j-2}\left\|\partial_x C_W\right\|_{L^p(\tilde{\Sigma})\to L^p(\tilde{\Sigma})}\left\|C_W I\right\|_{L^p(\tilde{\Sigma})}\\
&+\sum_{j=1}^{\infty}\left\|C_W\right\|_{L^p(\tilde{\Sigma})\to L^p(\tilde{\Sigma})}^{j-1}\left\|\partial_x {C_W} I\right\|_{L^p(\tilde{\Sigma})}\\
			&\le C\frac{\|\partial_xW\|_{L^\infty(\tilde\Sigma)}\|W\|_{L^p(\tilde\Sigma)}+ \|\partial_xW\|_{L^p(\tilde\Sigma)}}{1-\|C_{\pm}\|_p\|W\|_{L^\infty(\tilde\Sigma)}}.
		\end{aligned}
		$$
	\end{proof}


	Now, the following non-tangential limit holds for $k\to\infty$
	$$
	Q(x,t):=\lim_{k\to\infty}k(\tilde M(x,t;k)-I)=-\frac{1}{2\pi i}\int_{\tilde\Sigma}\mu (x,t;k)W(x,t;k)\mathrm{d}k.
	$$


	\begin{lemma}
		For $M^{-1}\le\xi\le M$ and $t\to\infty$, the asymptotics for $Q(x,t)$ is formulated as
		$$
		Q(x,t)=-\frac{1}{2\pi i}\int_{\partial\tilde B^{(k_0)}_\epsilon\cup\partial\tilde B^{(-k_0)}_\epsilon}W(x,t;k)\mathrm{d}k+\mathcal{O}\left(\frac{\ln t}{t}\right).
		$$
		Furthermore, for $\zeta\in[0,\zeta_{\rm{max}}]$ and $x\to\infty$, it becomes 
        $$
		Q(x,t)=-\frac{1}{2\pi i}\int_{\partial\tilde B^{(k_0)}_\epsilon\cup\partial\tilde B^{(-k_0)}_\epsilon}W(x,t;k)\mathrm{d}k+\mathcal{O}\left(x^{-N}+\frac{C_{N}(\zeta)\ln x}{x}\right).
		$$

	\end{lemma}


	\begin{proof}
		Decompose $Q(x,t)$ as  
		$$
		Q(x,t)=-\frac{1}{2\pi i}\int_{\partial\tilde B^{(k_0)}_\epsilon\cup\partial\tilde B^{(-k_0)}_\epsilon}W(x,t;k)\mathrm{d}k+Q_1(x,t)+Q_2(x,t),
		$$
		where
		$$
		Q_1(x,t):=-\frac{1}{2\pi i}\int_{\tilde\Sigma}(\mu (x,t;k)-I)W(x,t;k)\mathrm{d}k,\
		Q_2(x,t):=-\frac{1}{2\pi i}\int_{\tilde\Sigma\setminus{(\partial\tilde B^{(k_0)}_\epsilon}\cup \partial\tilde B^{(k_0)}_\epsilon)}W(x,t;k)\mathrm{d}k.
		$$
		For the function $Q_1(x,t)$, the H\"{o}lder inequality indicates that
		$$
		|Q_1(x,t)|\le C \|\mu (x,t;\cdot)-I\|_{L^p(\tilde\Sigma)}\|W(x,t;\cdot)\|_{L^q(\tilde\Sigma)}\le\frac{C\ln t}{t},\quad {\rm for}~M^{-1}\le\xi\le M,~t\to\infty,
		$$
        $$
		|Q_1(x,t)|\le C \|\mu (x,t;\cdot)-I\|_{L^p(\tilde\Sigma)}\|W(x,t;\cdot)\|_{L^q(\tilde\Sigma)}\le\frac{\mathrm{C}_N(\zeta)\ln x}{x},\quad {\rm for}~\zeta\in[0,\zeta_{\rm{max}}],~x\to\infty,
		$$
		where $\frac{1}{p}+\frac{1}{q}=1$. For the function $Q_2(x,t)$, the estimates below hold
		$$
		|Q_2(x,t)|\le C\|W(x,t;\cdot)\|_{L^1(\tilde \Sigma \setminus(\partial\tilde B^{(k_0)}_\epsilon\cup\partial\tilde B^{(-k_0)}_\epsilon))}\le\frac{C\ln t}{t},\quad {\rm for}~M^{-1}\le\xi\le M,~t\to\infty,
		$$
        $$
		|Q_2(x,t)|\le C\|W(x,t;\cdot)\|_{L^1(\tilde \Sigma \setminus(\partial\tilde B^{(k_0)}_\epsilon\cup\partial\tilde B^{(-k_0)}_\epsilon))}\le x^{-N},\quad {\rm for}~\zeta\in[0,\zeta_{\rm{max}}],~x\to\infty.
		$$
        \par
		Now, suppose
		$$
		R(x,t;\pm k_0):=-\frac{1}{2\pi i}\int_{\partial B_{\epsilon}(\pm k_0)}W(x,t;k)\mathrm{d}k=-\frac{1}{2\pi i}\int_{\partial B_{\epsilon}(\pm k_0)}((M^{(k_0)})^{-1}-I) \mathrm{d}k,
		$$
		and then it yields that
		$$
		R(x,t; k_0)=\frac{H( k_0, t) M_1^{X_{A}}(y(k_0) H( k_0, t)^{-1}}{{3^{\frac{5}{4}}2\sqrt{5t}k_0^{\frac{3}{2}}}}+\mathcal{O}\left(t^{-1}\right), \quad {\rm as}~t\to\infty,
		$$
        $$
		R(x,t; k_0)=\frac{H( k_0, t) M_1^{X_A}(y(k_0) H( k_0, t)^{-1}}{{3^{\frac{5}{4}}2\sqrt{5t}k_0^{\frac{3}{2}}}}+\mathcal{O}\left(\frac{ \mathrm{C}_N(\zeta)}{x}\right),\quad {\rm as}~x\to\infty,
		$$
        and for the case $R(x,t;-k_0)$, just replacing $M_1^{X_A}(y)$ into $M_1^{X_B}(y)$ and $H(k_0,t)$ int0 $H(-k_0,t)$.
        \par
		Reminding the symmetry of the function $\tilde M(x,t;k)$, one has
		$$
		\tilde M(x,t;k)=\mathcal{A}\tilde M(x,t;\omega k)\mathcal{A}^{-1}, \quad k\in\C\setminus\tilde \Sigma.
		$$
		Notice that $\mu$ and $W$ also satisfy this symmetry, then it can be found that
		$$
		\begin{aligned}
			-\frac{1}{2\pi i}\int_{\partial\tilde B^{(k_0)}_\epsilon\cup\partial\tilde B^{(-k_0)}_\epsilon}W(x,t;k)\mathrm{d}k&=-\frac{1}{2\pi i}
			\int_{\cup_{j=0}^{2}\partial B_{\epsilon}(\pm \omega^jk_0)}
			W(x,t;k)\mathrm{d}k\\
			&=R(x,t;\pm k_0)+\omega \mathcal{A}^{-1}R(x,t;\pm k_0)\mathcal{A}+\omega^2 \mathcal{A}^{-2}R(x,t;\pm k_0)\mathcal{A}^2,
		\end{aligned}
		$$	
        which immediately gives the asymptotic formulas in this lemma.
	\end{proof}

	\par
	\noindent{\bf Asymptotic behaviors of the SK and mSK equations in Sectors ${\rm I}$ and ${\rm II}$}. The reconstruction formula of the SK equation (\ref{SK}) is given in (\ref{recover-formula SK}), i.e.,
	$$
	u(x,t)=-\frac{1}{2}\partial_x\left(\lim_{k\to\infty}k(N_3(x,t;k)-1) \right),
	$$
	where $N(x,t;k)=\left(N_1,N_2,N_3\right)=(\omega,\omega^2,1)M(x,t;k)$. Recall that for $k\in\C\setminus{(\tilde B^{(k_0)}_{\epsilon}\cup\tilde B^{(-k_0)}_{\epsilon})}$, the function $M(x,t;k)$ is related with the function $\tilde M(x,t;k)$ by
	$$
	M=\tilde MG^{-1}\Delta^{-1}.
	$$
	Then it follows that
	$$
	\begin{aligned}
		u(x,t)&=-\frac{1}{2}\partial_x\left(\lim_{k\to\infty}k[((\omega,\omega^2,1)\tilde MG^{-1}\Delta^{-1})_3-1] \right)\\
		&=-\frac{1}{2}\partial_x\left(\lim_{k\to\infty}k[((\omega,\omega^2,1)\tilde M)_3-1] \right)+\mathcal{O}\left(\frac{\ln t}{t}\right),\ \text{as}\  t\to \infty,
	\end{aligned}
	$$
    and 
       $$
		u(x,t)=-\frac{1}{2}\partial_x\left(\lim_{k\to\infty}k[((\omega,\omega^2,1)\tilde M)_3-1] \right)+\mathcal{O}\left(\frac{\mathrm{C}_N(\zeta)\ln x}{x}+x^{-N}\right), \ {\rm as}~ x\to \infty.
	$$
    \par
	For the second equality, since the $G^{-1}\Delta^{-1}$ tends to $I$ as $k\to\infty$ and their derivatives are dominated by $\frac{\ln t}{t}$ or $\frac{\mathrm{C}_N(\zeta)\ln x}{x}+x^{-N}$ for $t\to \infty$ and $x\to \infty$, respectively, it is concluded that for $t\to \infty$
	\begin{align*}
		u(x,t)=&-\frac{1}{2}\partial_x\left(\begin{pmatrix}
			\omega & \omega^2 & 1
		\end{pmatrix} \frac{\sum_{j=0}^2 \omega^j \mathcal{A}^{-j} H(k_0, t) M_1^{X_A}(y(k_0)) H(k_0, t)^{-1} \mathcal{A}^j}{{3^{\frac{5}{4}}2\sqrt{5t}k_0^{\frac{3}{2}}}}\right)\\
		&-\frac{1}{2}\partial_x\left(\begin{pmatrix}
			\omega & \omega^2 & 1
		\end{pmatrix}
		\frac{\sum_{j=0}^2 \omega^j \mathcal{A}^{-j} H(-k_0, t) M_1^{X_B}(y(-k_0)) H(-k_0, t)^{-1} \mathcal{A}^j}{{3^{\frac{5}{4}}2\sqrt{5t}k_0^{\frac{3}{2}}}}\right)+\mathcal{O}\left(\frac{\ln t}{t}\right)\\
		=&-\frac{1}{3^{\frac{5}{4}}2\sqrt{5t}k_0^{\frac{3}{2}}}\left(\partial_x\Re\left(\omega^2\beta^A_{21}\delta^0_A\mathrm{e}^{t\Phi_{21}(k_0)}\right)+\partial_x\Re\left(\omega\beta^B_{12}\delta^0_B\mathrm{e}^{-t\Phi_{21}(-k_0)}\right)\right)+\mathcal{O}\left(\frac{\ln t}{t}\right),\\
	\end{align*}
    while for $x\to \infty$
    $$
    u(x,t)=-\frac{\left(\partial_x\Re\left(\omega^2\beta^A_{21}\delta^0_A\mathrm{e}^{t\Phi_{21}(k_0)}\right)+\partial_x\Re\left(\omega\beta^B_{12}\delta^0_B\mathrm{e}^{-t\Phi_{21}(-k_0)}\right)\right)}{3^{\frac{5}{4}}2\sqrt{5t}k_0^{\frac{3}{2}}}
    \\+\mathcal{O}\left(\frac{\mathrm{C}_N(\zeta)\ln x}{x}+x^{-N}\right).
    $$
	\begin{theorem}
		Suppose $u(x,t)$ is the solution of the SK equation (\ref{SK}) with initial data $u(x,0)=u_0(x)$ in Schwartz space and the Assumption \ref{solitonless} and \ref{r less 1} hold, then in the generic case, for $1/M\le \xi \le M$ with $x>0$, the solution $u(x,t)$ in Sector ${\rm II}$ of Theorem \ref{main-theorem-SK} has the following asymptotics as $t\to\infty$
		\begin{equation}\label{longtime-solution}
			\begin{split}
				\begin{aligned}
					u(x,t)=&-\frac{1}{3^{\frac{3}{4}}2\sqrt{5t}k_0^{\frac{1}{2}}}\left[\sqrt{\nu_1}\sin \left(\frac{19\pi }{12}-\left(\arg y_1+\arg\Gamma(i\nu_1)\right)-(36\sqrt{3}tk_0^5)+\nu_1\ln({{3^{\frac{7}{2}}20tk_0^{5}}})+s_1\right)\right.\\
					&\left.+\sqrt{\nu_4}\sin \left(\frac{11\pi }{12}-\left(\arg y_4+\arg\Gamma(i\nu_4)\right)-(36\sqrt{3}tk_0^5)+\nu_4\ln({{3^{\frac{7}{2}}20tk_0^{5}}})+s_2\right)\right]+\mathcal{O}\left(\frac{\ln t}{t}\right),\\
				\end{aligned}
			\end{split}
		\end{equation}
		with $s_1=\nu_4\ln(4)+\frac{1}{\pi }\int_{-k_0}^{-\infty}\log_{\pi}\frac{|s-\omega k_0|}{|s- k_0|}d\ln(1-|r_2(s)|^2)+\frac{1}{\pi }\int_{k_0}^\infty\log_0\frac{|s-k_0|}{|s-\omega k_0|}d\ln(1-|r_1(s)|^2)$, and $s_2=\nu_1\ln(4)+\frac{1}{\pi }\int_{k_0}^{\infty}\log_{0}\frac{|s+\omega k_0|}{|s+ k_0|}d\ln(1-|r_1(s)|^2)+\frac{1}{\pi }\int_{-k_0}^{-\infty}\log_{\pi}\frac{|s+ k_0|}{|s+\omega k_0|}d\ln(1-|r_2(s)|^2)$.
        \par
        Moreover, for $\zeta\in[0,\zeta_{\rm{max}}]$ and $x\to\infty$, the leading-order term of $u(x,t)$ in Sector ${\rm I}$ of Theorem \ref{main-theorem-SK} is the same as that in (\ref{longtime-solution}), but the error term should be replaced with $\mathcal{O}\left(\frac{\mathrm{C}_N(\zeta)\ln x}{x}+x^{-N}\right)$.
	\end{theorem}

	\begin{proof}
		To be specific, denote
		$$
		y_1=r_1(k_0),\ \nu_1=-\frac{1}{2 \pi} \ln \left(1-\left|r_1\left(k_0\right)\right|^2\right),\ \nu_4=-\frac{1}{2 \pi} \ln \left(1-\left|r_2\left(-k_0\right)\right|^2\right),
		$$
		$$
		 y_4=r_2(-k_0),\ \beta^A_{21}=\sqrt{\nu_1}\mathrm{e}^{ i\left(\frac{\pi}{4}-\arg y-\arg\Gamma(i\nu_1)\right)},\quad \mathrm{e}^{t\Phi_{21}(k_0)}=\mathrm{e}^{-i(36\sqrt{3}tk_0^5)}.
		$$

		Recall
		$
		\delta^0_A=\frac{a^{-2i\nu_1}\mathrm{e}^{-2\chi_1(k_0)}}{\tilde\delta_{v_1}(k_0)}
		$
		and notice that
		$$
		a^{-2i\nu_1}=\exp\left(i\nu_1\ln({{3^{\frac{5}{2}}20tk_0^{3}}})\right),\quad
		\mathrm{e}^{-2\chi_1(k_0)}=\exp\left(-\frac{1}{\pi i}\int_{k_0}^\infty\log_0|s-k_0|d\ln(1-|r_1(s)|^2)\right).
		$$
		On the other hand, it can be calculated that
		\begin{align*}	&\delta_3(k_0)\delta_5(k_0)=\delta_1(\omega^2k_0)\delta_1(\omega k_0)=\exp\left(-i\nu_1\ln(3k_0^2)-\frac{1}{\pi i}\int_{k_0}^\infty\log_0|s-\omega k_0|d\ln(1-|r_1(s)|^2)\right),\\
			&\delta_2(k_0)\delta_6(k_0)=\delta_4(\omega^2k_0)\delta_4(\omega k_0)=\exp\left(-i\nu_4\ln(k_0^2)-\frac{1}{\pi i}\int_{-k_0}^{-\infty}\log_{\pi}|s-\omega k_0|d\ln(1-|r_2(s)|^2)\right),\\
			&\delta_4^2(k_0)=\exp\left(-i\nu_4\ln(4k_0^2)-\frac{1}{\pi i}\int_{-k_0}^{-\infty}\log_{\pi}|s- k_0|d\ln(1-|r_2(s)|^2)\right).
		\end{align*}
		The computation near the saddle point \(-k_0\) is similar and quite tedious. Finally, by incorporating the aforementioned computations into the formulas and performing the complex calculations, the desired results can be obtained.
	\end{proof}
	Regarding to the asymptotic solution $w(x,t)$ of the mSK equation (\ref{msk-equation}) in Sectors $\rm I$ and $\rm II$, following the similar way of Deift-Zhou steepest-descent analysis, together with the reconstruction formula (\ref{recover-formula mSK}), it is immediate that
	$$
	w(x,t)=3\lim_{k\to\infty}k(\tilde mG^{-1}\Delta^{-1})_{13} =3\lim_{k\to\infty}k\tilde m_{13}+\mathcal{O}\left(\frac{\ln t}{t}\right),\ \text{for}\  t\to \infty,
	$$
    and
    $$
	w(x,t)=3\lim_{k\to\infty}k(\tilde mG^{-1}\Delta^{-1})_{13} =3\lim_{k\to\infty}k\tilde m_{13}+  \mathcal{O}\left(\frac{\mathrm{C}_N(\zeta)\ln x}{x}+x^{-N}\right), \ \text{for}\  x\to \infty.
	$$
    \par
    Consequently, the long-time asymptotics of the solution to the mSK equation (\ref{msk-equation}) is formulated below
	\begin{equation}\label{longtime-solution-msk}
		\begin{split}
			\begin{aligned}
				w(x,t)=&\frac{-1}{3^{\frac{1}{4}}2\sqrt{5t}k_0^{\frac{3}{2}}}\left[\sqrt{\tilde{\nu}_1}\cos \left(\frac{19\pi }{12}-\left(\arg \tilde{y}_1+\arg\Gamma(i\tilde{\nu}_1)\right)-(36\sqrt{3}tk_0^5)+\tilde{\nu}_1\ln({{3^{\frac{7}{2}}20tk_0^{5}}})+\tilde{s}_1\right)\right.\\	
				&+\left.\sqrt{\tilde{\nu}_4}\cos \left(\frac{11\pi }{12}-\left(\arg \tilde{y}_4+\arg\Gamma(i\tilde{\nu}_4)\right)-(36\sqrt{3}tk_0^5)+\tilde{\nu}_4\ln({{3^{\frac{7}{2}}20tk_0^{5}}})+\tilde{s}_2\right)\right]\\
                &+\mathcal{O}\left(\frac{\ln t}{t}\right).\\
			\end{aligned}
		\end{split}
	\end{equation}
 Moreover, the leading-order term of the large space solution $w(x,t)$ is the same as that in (\ref{longtime-solution-msk}), but the error term should be replaced with $\mathcal{O}\left(\frac{\mathrm{C}_N(\zeta)\ln x}{x}+x^{-N}\right)$.
    \par
	In fact, the RH problem for $M(x,t;k)$ and $m(x,t;k)$ can be factorized into the same model problem for $M^{X_{A,B}}$. However, the reconstruction formulas and the reflection coefficients are different in general.

\section{\bf The Painlev\'{e} region}\label{painleve region}
\par	
It is observed from Figures \ref{msk-comparisons} and \ref{SK-comparisons} that the long-time asymptotic solutions (\ref{longtime-solution})-(\ref{longtime-solution-msk}) in Sector ${\rm II}$ of the SK equation (\ref{SK}) and mSK equation (\ref{msk-equation}) are invalid near $x=0$. As the case of KdV equation \cite{Deift-Zhou-1994} and mKdV equation \cite{Deift-Zhou-1993} and motivated by the self-similar transformation from the mSK equation (\ref{msk-equation}) to the Painlev\'{e} transcendent equation (\ref{4th-Painleve}), it is conjectured that a region that can be described by Painlev\'{e} type equations may appear in the region around $x=0$. 
Since the reflection coefficients of the SK equation (\ref{SK}) satisfy $|r_j(0)|=1$ for $j=1,2$, the analysis of this region is very complicated. Fortunately, there is a Miura transformation between the SK equation  (\ref{SK}) and the mSK equation (\ref{msk-equation}), and 
in generic case, the absolute value of the reflection coefficients for the mSK equation (\ref{msk-equation}) are strictly less than 1. Thus in this section, we focus on the long-time asymptotic analysis of the mSK equation (\ref{msk-equation}) in Painlev\'{e} region. 
\par
For convenience, rewrite the mSK equation (\ref{msk-equation}) by taking $t\to-t$, which becomes
\begin{equation}\label{rewrite-msk}
	w_t=w_{x x x x x}-\left(5 w_x w_{x x}+5 w w_x^2+5 w^2 w_{x x}-w^5\right)_x.
\end{equation}
The jump matrices of the RH problem associated with the mSK equation (\ref{rewrite-msk}) are similar to that in (\ref{vn-jump-matrix}) except for the phase functions $\theta_{ij}~(1\le j<i\le 3)$. More precisely, the phase functions corresponding to (\ref{rewrite-msk}) are
$$
\theta_{i j}(x,t;k)=-t\left[\left(l_i-l_j\right) \xi+ \left(z_i-z_j\right) \right]:=t\Phi_{ij}(\xi;k)
$$
with $\xi:=-{x}/{t}$, $l_j(k)= \omega^j k$ and $z_j(k)=9 \omega^{2j} k^5$ for $j=1,2,3$. Notice that the transformation $t\to-t$ only changes the sign of the phase functions (see Figure \ref{regionU painleve} for the sign signature of $\Re \Phi_{21}$), thus we still adopt the same symbols of $\theta_{ij}, \xi$ and $\Phi_{ij}$ as that in Section ${\rm II}$. According to the self-similar transformation $w(x,t)=(5t)^{-\frac{1}{5}}p(s)$ with $s=\frac{x}{(5t)^{\frac{1}{5}}}$ from the mSK equation to the fourth-order analogues of Painlev\'{e} transcendent (\ref{4th-Painleve}), in what follows, we constrain ourself on the region $|\frac{x}{t^{1/5}}|<M$. Because of the transformation $t\to-t$, it is known that the case of $x<0$ for equation (\ref{rewrite-msk})  corresponds to the case of $x>0$ for equation (\ref{msk-equation}), and vice versa.  

\subsection{Painlev\'{e} region for $x<0$}

Firstly, consider the case of $x<0$, which implies that the critical points lie on the real line.  To be specific, the saddle points of phase function $\theta_{21}$ are $\pm k_0=\pm\sqrt[4]{\frac{-x}{45t}}$, and it is immediate that $k_0\sim t^{-\frac{1}{5}}$ as $t\to\infty$. Consequently, it is reasonable to adopt the new variable $\lambda:=k(5t)^{\frac{1}{5}}$ as the parameter of the model problem in the analysis of long-time asymptotics. Initially, decompose the reflection coefficients $\tilde{r}_{j}(k)~(j=1,2)$ into $\tilde{r}_{j,a}(k)+\tilde{r}_{j,r}(k)$ likewise the case in Sector $\rm II$, see Lemma \ref{Lemma-analytic-extension}.
