	\begin{lemma}\label{Lemma-analytic-extension painleve}
		For any integer $N\ge1$, letting $A>0$ be a constant, the functions $\tilde{r}_j(k)$ for $j=1,2$ have the following decompositions:
		$$
		\begin{array}{ll}
			\tilde{r}_1(x,t;k)=\tilde{r}_{1, a}(x, t; k)+\tilde{r}_{1, r}(x, t; k), & k \in\left(k_0, \infty\right), \\
			\tilde{r}_2(x,t;k)=\tilde{r}_{2, a}(x, t; k)+\tilde{r}_{2, r}(x, t; k), & k \in(-\infty,-k_0).
		\end{array}
		$$
		Furthermore, the decomposition functions $\tilde{r}_{j,a}(x,t;k)$ and $\tilde{r}_{j,r}(x,t;k)~(j=1,2)$ have the properties as follow:
		\begin{enumerate}
			\item For each $\xi\in[0,A]$ and $t\ge1$, $\tilde{r}_{1,a}(x,t;k)$ and $\tilde{r}_{2,a}(x,t;k)$ are well-defined and continuous for $\bar{U}_1$ and $\bar{U}_4$, respectively, and are analytic in the interior of their respective domains. The open subsets $U_j~(j=1,2,3,4)$ are depicted in Figure \ref{regionU painleve}.

			\item For each $\xi\in[0,A]$ and $t\ge1$, the functions $\tilde{r}_{j,a}(x,t;k)$ for $j=1,2$  satisfy the following estimates:
			$$
			\left|\tilde{r}_{j, a}(x, t; k)-\sum_{i=0}^N\frac{\tilde{r}_j^{(i)}(k_*)(k-k_*)^i}{i!}\right| \leq C|k-k_*|^{N+1}{\mathrm{e}^{t|\Re \Phi_{21}(\xi;k)|/4}},
			$$
			and
			$$
			\left|\tilde{r}_{j, a}(x, t; k)\right| \leq \frac{C}{1+|k|^{N+1}}{\mathrm{e}^{t|\Re \Phi_{21}(\xi;k)|/4}},
			$$
where the first inequality holds for \( j=1 \) when \( k_* = k_0 \) and \( k\in {U}_1 \), and for \( j=2 \) when \( k_* = -k_0 \) and \( k\in  {U}_4 \).
			\item For each $p$ satisfying \(1 \leq p \leq \infty\) and \(\xi\in[0,A]\), the \(L^p\)-norms of the functions \(\tilde{r}_{j,r}(x,t;k)\) \((j=1,2)\) are \(\mathcal{O}(t^{-N})\) on their respective domains as \(t \to \infty\).
		\end{enumerate}
	\end{lemma}
	\begin{proof}
		The proof parallels that in Lemma \ref{Lemma-analytic-extension}, thus it is omitted for brevity. For more information, refer to Ref. \cite{Lenells-mkdv}.
	\end{proof}
	Now, according to the decompositions of the functions $r_{j}(k)~(j=1,2)$ above, transform the RH problem for $m(x,t;k)$ of the mSK equation (\ref{rewrite-msk}) into the RH problem for $m^{(1)}(x,t;k)$ by
	$$
	m^{(1)}(x,t;k)=m(x,t;k)G(x,t;k),\ k\in\C\setminus\Sigma^{1},
	$$
	where the jump contour $\Sigma^{1}$ is depicted in Figure \ref{Sigma1 Painleve} and the transformation matrices are $G(x,t;k):=G_n(x,t;k)$ for $n=1,2,\cdots,6$. In particular, the matrix $G^{(1)}_1(x,t;k)$ is defined near $k_0$ by
	$$
	G_1(x, t; k):= \begin{cases}
		\small\left(\begin{array}{ccc}
			1 & \tilde{r}_{1,a}(k) \mathrm{e}^{-\theta_{21}(x,t;k)} & 0 \\
			0 & 1& 0 \\
			0 & 0 & 1
		\end{array}\right), & k\ \text{on the right}  \text{side of } \Sigma_{1}^{1},\\
		\small\left(\begin{array}{ccc}
			1 & 0 & 0 \\
			\tilde{r}_{1,a}^{*}(k) \mathrm{e}^{\theta_{21}(x,t;k)} & 1& 0 \\
			0 & 0 & 1
		\end{array}\right), & k\ \text{on the left} \text{side of } \Sigma_{3}^{1}, \\
		I, & \text{otherwise},
	\end{cases}
	$$
	and
	$G_4(x,t;k)$ is defined near $-k_0$ by
	$$
	G_4(x, t; k):= \begin{cases}
		\small\left(\begin{array}{ccc}
			1 & -\tilde{r}_{2,a}^{*}(k) \mathrm{e}^{-\theta_{21}(x,t;k)} & 0 \\
			0 & 1& 0 \\
			0 & 0 & 1
		\end{array}\right), & k\ \text{on the right}  \text{side of } \Sigma_{6}^{1}, \\
		\small\left(\begin{array}{ccc}
			1 & 0 & 0 \\
			-\tilde{r}_{2,a}(k) \mathrm{e}^{\theta_{21}(x,t;k)} & 1& 0 \\
			0 & 0 & 1
		\end{array}\right), & k\ \text{on the left}  \text{side of } \Sigma_{8}^{1}, \\
		I, & \text{otherwise}.
	\end{cases}
	$$
	 One can obtain the other functions $G_n(x,t;k)~(n=2,3,5,6)$ by the symmetry properties in (\ref{symmetry}).

