	For $\xi\in[0,A]$, the jump matrix $v^{(1)}$ converges uniformly to identity matrix $I$ as $t\to\infty$ except for the cuts near the saddle points, i.e., $\left\{\pm k_0,\pm \omega k_0,\pm \omega^2k_0\right\}$. Consequently, we only need to carry out the long-time asymptotic analysis near the saddle points. For $\xi\in[0,A]$, take the self-similar transformation
\begin{equation}\label{self-similar-transformation0}
    \lambda:={k}{(5t)^{1/5}},\quad y:=\frac{x}{(5t)^{\frac{1}{5}}},
\end{equation}
then the phase functions $\theta_{ij}(x,t;k)$ for $1\le j<i\le 3$ are transformed into
	$$
	\theta_{i j}(y;\lambda)=\left[\left(\omega^i-\omega^j\right)y\lambda-\frac{9\lambda^5}{5}\left(\omega^{2i}-\omega^{2j}\right) \right].
	$$
    \par
	As that in Section \ref{local parmetrices}, suppose $\Sigma_{\le}^{\epsilon}=\Sigma^{1}\cap B_{\epsilon}(0) \setminus \left(\cup_{j=0}^2(-\omega^j\infty,-\omega^jk_0)\cup(\omega^jk_0,\omega^j\infty)\right)$, where $B_{\epsilon}(0):=\{\lambda\in \C||\lambda|<\epsilon\}=\{k\in \C||k|<\epsilon(5t)^{1/5}\}$. Indeed, the local model problem with contour $\Sigma_{\le}^{\epsilon}$ is related to the Painlev\'e model problem for $m^{p}(y;\lambda)$ defined in Appendix \ref{appendix painleve}.

	\begin{lemma}\label{error for painleve}
		For $\xi\in[0,A]$, the function $m^{p}(x,t;k)=m^{p}(y;\lambda)$ is a bounded analytic function for $k\in B_{\epsilon}(0)\setminus\Sigma_{\le}^{\epsilon}$, such that for any $1\le p\le\infty$, one has
		\begin{equation}
			\|v^{(1)}-v^{p}\|_{L^p}\le t^{-\frac{1}{5}}.
		\end{equation}
		Furthermore, it can be obtained that
		$$
		m^{p}(x,t;k)^{-1}=I-\frac{m^{p}_{1}(y)}{kt^{\frac{1}{5}}}+\mathcal{O}\left(\frac{1}{t^{\frac{2}{5}}}\right).
		$$
	\end{lemma}
	\begin{proof}
		The analyticity of $m^p(y;\lambda)$ follows from its definition, while the boundedness is a consequence of the sign signature of the jump matrices. In particular, it can be derived that
		$$
		v^{(1)}-v^{p}=\begin{cases}
			\begin{aligned}
				&\small\left(\begin{array}{ccc}
					0 & 0 & 0 \\
					(\tilde{r}_{1,a}^{*}(k)-\tilde{r}_1^{*}(0)) \mathrm{e}^{\theta_{21}(x,t;k)} & 0& 0 \\
					0 & 0 & 0
				\end{array}\right), && k\in \Sigma_{1,\le}^{(\epsilon)},\\
				&\small\left(\begin{array}{ccc}
					0 & \tilde{r}_{1,r}(k) \mathrm{e}^{-\theta_{21}(x,t;k)} & 0 \\
					\tilde{r}_{1,r}^{*}(k) \mathrm{e}^{\theta_{21}(x,t;k)} & -\tilde{r}_{1,r}(k)\tilde{r}_{1,r}^*(k) & 0 \\
					0 & 0 & 0
				\end{array}\right), && k\in \Sigma_{2,\le}^{(\epsilon)},\\
				&\small\left(\begin{array}{ccc}
					0 & -(\tilde{r}_{1,a}(k)-\tilde{r}_1(0)) \mathrm{e}^{-\theta_{21}(x,t;k)} & 0 \\
					0 & 0& 0 \\
					0 & 0 & 0
				\end{array}\right), && k\in \Sigma_{3,\le}^{(\epsilon)},\\
				&\small \left(\begin{array}{ccc}
					0 & -(\tilde{r}_1(k)-\tilde{r}_1(0)) \mathrm{e}^{-\theta_{21}(x,t;k)} & 0 \\
					(\tilde{r}_1^*(k)-\tilde{r}_1^*(0)) \mathrm{e}^{\theta_{21}(x,t;k)} & \left|\tilde{r}_1(k)\right|^2-\left|\tilde{r}_1(0)\right|^2 & 0 \\
					0 & 0 & 0
				\end{array}\right), && k\in \Sigma_{4,\le}^{(\epsilon)}.\\
			\end{aligned}
		\end{cases}
		$$
		More precisely, we have
		$$
		\begin{aligned}
			\Re(-\theta_{21}(x,t;k))&=9\sqrt{3}t[(k-k_0)^5+5k_0(k-k_0)^4+10k_0^2(k-k_0)^3+10k_0^3(k-k_0)^2-4k_0^5]\\
			&\le -C t |k|^5,\quad k\in\Sigma^{\epsilon}_{3,\le},
		\end{aligned}
		$$
		where $C$ is a positive constant.
		On the other hand, it is seen that
		$$
		\tilde{r}_1(k_0)-\tilde{r}_1(0)=\tilde{r}^{(1)}(0)k_0+\mathcal{O}\left(k_0^2\right).
		$$
		Recalling the inequalities in Lemma \ref{Lemma-analytic-extension painleve}, for $\xi\in[0,A]$ and $k\in\Sigma^{(\epsilon)}_{3,\le}$, it follows that
		$$
		\begin{aligned}
			|v^{(1)}-v^{p}|&\le  |\tilde{r}_{1,a}(k)-\tilde{r}_{1}(k_0)|\mathrm{e}^{-t\Re \Phi_{21}}+|\tilde{r}_{1}(0)-\tilde{r}_{1}(k_0)|\mathrm{e}^{-t\Re \Phi_{21}}\\
			&\le C |k-k_0|\mathrm{e}^{-ct|k|^5}+C |k|\mathrm{e}^{-ct|k|^5}\le C|\lambda t^{-\frac{1}{5}}|\mathrm{e}^{-c|\lambda|^5}.
		\end{aligned}
		$$
		Consequently, for each $1\le p\le \infty$, it is immediate that
		$$
		\|v^{(1)}-v^{p}\|_{L^{\infty}(\Sigma^{(\epsilon)}_{3,\le})}\le C t^{-\frac{1}{5}},\
		\|v^{(1)}-v^{p}\|_{L^{1}(\Sigma^{(\epsilon)}_{3,\le})}\le C t^{-\frac{2}{5}}.
		$$
		Furthermore, by the Lemma \ref{Lemma-analytic-extension painleve}, for $k\in \Sigma_{2,\le}^{(\epsilon)}$,  we have
		$$
		|v^{(1)}-v^{p}|\le C t^{-1}.
		$$
	The estimates of the other jump matrices can also be gotten in a similar way.		Noting the expansion $m^{p}(y;\lambda)=I+\frac{m_{1}^p(y)}{\lambda}+\mathcal{O}\left(\frac{1}{\lambda^2}\right)$ in Appendix \ref{appendix painleve} and recalling  the self-similar variable $\lambda=kt^{\frac{1}{5}}$, it follows that
		$$
		m^{p}(x,t;k)^{-1}=I-\frac{m^{p}_{1}(y)}{kt^{\frac{1}{5}}}+\mathcal{O}\left(\frac{1}{t^{\frac{2}{5}}}\right).
		$$
	\end{proof}
