	Finally, denote the new contour $\hat \Sigma:=\Sigma^{1}\cup\partial B_{\epsilon}(0) $, which can be seen in Figure \ref{Sigma hat}, and define the function $\hat{m}(x,t;k)$ by
	\begin{equation}\label{hat m}
		\hat{m}(x,t;k)=\begin{cases}
			\begin{aligned}
				&m^{(1)}(x,t;k)(m^p)^{-1}(x,t;k),&&k\in B_{\epsilon}(0),\\
				&m^{(1)}(x,t;k),&&k\in \C\setminus B_{\epsilon}(0),\\
			\end{aligned}
		\end{cases}
	\end{equation}
	which is the solution of a RH problem with jump contour $\hat \Sigma$ and jump matrices 
	\begin{equation}\label{hat m jumps}
		\hat{v}(x,t;k)=\begin{cases}
			\begin{aligned}
				&m^{p}_{-}(x,t;k)v^{(1)}(m^{p}_{+})^{-1}(x,t;k),&&k\in B_{\epsilon}(0)\cap \hat \Sigma,\\
				&(m^p(x,t;k))^{-1},&&k\in \partial B_{\epsilon}(0),\\
				&v^{(1)},&&k\in\hat \Sigma\setminus \bar{B}_{\epsilon}(0).
			\end{aligned}
		\end{cases}
	\end{equation}
	\begin{lemma}
		Let $\hat w =\hat v -I$ and $p\ge 1$, then for $\xi\in[0,A]$, the following inequalities hold uniformly
		\begin{equation}
			\begin{aligned}
				&\|\hat w\|_{L^p(\partial B_{\epsilon}(0))}\le Ct^{-\frac{1}{5}},\ \|\hat w\|_{L^p(\hat \Sigma \setminus B_{\epsilon}(0))}\le Ct^{-N},\
				\|\hat w\|_{L^p( B_{\epsilon}(0)\cap \Sigma_{1})}\le Ct^{-\frac{1}{5}-\frac{1}{5p}}.
			\end{aligned}
		\end{equation}
	\end{lemma}
	\begin{proof}
		The first and last inequalities follow from Lemma \ref{error for painleve}, while the second inequality is the consequence of Lemma \ref{Lemma-analytic-extension painleve}.
	\end{proof}
	Since $\|\hat w\|_{L^{\infty}}\to0$ as $t\to\infty$, it follows that the operator $I-C_{\hat w}$ is invertible for $t$ large enough. Therefore, the solution $\hat m(x,t;k)$ of the RH problem  exists and is unique, that is
	\begin{equation}\label{m recover Cauchy}
		\hat m(x,t;k)=I+C(\hat\mu \hat w)=I+\int_{\hat\Sigma} \frac{\hat\mu(x,t;\zeta)\hat w(x,t;\zeta)}{\zeta-k} \frac{\mathrm{d} \zeta}{2 \pi i}, \quad k \in \C\setminus \hat \Sigma,
	\end{equation}
	with $\hat \mu=I+(I-C_{\hat w})^{-1}C_{\hat w}I$.

	\begin{lemma}\label{H-asymptotic-54}
		When $\xi\in[0,A]$ and $t\to\infty$, we have
		$$
		\lim_{k\to\infty}k(\hat{m}(x,t;k)-I)=-\frac{1}{2\pi i}\int_{\partial B_{\epsilon}(0)}\hat w(x,t;k)\mathrm{d}k+\mathcal{O}\left(t^{-\frac{2}{5}}\right).
		$$
	\end{lemma}


	\begin{proof}
		It follows from the equation (\ref{m recover Cauchy}) that
		$$
		\lim_{k\to\infty}k(\hat{m}(x,t;k)-I)=-\frac{1}{2\pi i}\int_{\hat \Sigma}\hat{\mu}(x,t;\zeta)\hat{w}(x,t;\zeta)\mathrm{d}\zeta.
		$$
		Decomposing the right integration into three parts, yields
		$$
		-\frac{1}{2\pi i}\int_{\partial B_\epsilon{(0)}}\hat{w}(x,t;k)\mathrm{d}k+Q_1(x,t)+Q_2(x,t),
		$$
		where
		$$
		Q_1(x,t):=-\frac{1}{2\pi i}\int_{\hat\Sigma}(\hat{\mu} (x,t;k)-I)\hat{w}(x,t;k)\mathrm{d}k,\
		Q_2(x,t):=-\frac{1}{2\pi i}\int_{\hat\Sigma\setminus{\partial B_\epsilon{(0)}}}\hat{w}(x,t;k)\mathrm{d}k.
		$$
		For the function $Q_1(x,t)$, the H\"{o}lder inequality indicates that
		$$
		|Q_1(x,t)|\le C \|\hat{\mu} (x,t;\cdot)-I\|_{L^p(\hat\Sigma)}\|\hat{w}(x,t;\cdot)\|_{L^q(\hat\Sigma)}\le\frac{1}{t^{\frac{2}{5}}},
		$$
		where $\frac{1}{p}+\frac{1}{q}=1$. For the function $Q_2(x,t)$, it is seen that
		$$
		|Q_2(x,t)|\le C\|\hat{w}(x,t;\cdot)\|_{L^1(\hat \Sigma \setminus\partial B_\epsilon{(0)})}\le t^{-\frac{2}{5}}.
		$$
	\end{proof}
    \par
	In summary, the lemmas above shows that, for $\xi\in[0,A]$ and $t\to\infty$, the long-time asymptotic behavior of the solution to the mSK equation (\ref{msk-equation}) is
	$$
	\begin{aligned}
		w(x,t)&=3\lim_{k\to\infty}k(m(x,t;k)-I)_{13}=-\frac{3}{2\pi i}\int_{\partial B_{\epsilon}(0)}\hat w(x,t;k)\mathrm{d}k+\mathcal{O}\left(t^{-\frac{2}{5}}\right)\\
		&=-\frac{3}{2\pi i}\int_{\partial B_{\epsilon}(0)}((m^p)^{-1}-I)\mathrm{d}k+\mathcal{O}\left(t^{-\frac{2}{5}}\right)=\frac{3(m^p_{1}(y))_{13}}{t^{\frac{1}{5}}}+\mathcal{O}\left(\frac{1}{t^{\frac{2}{5}}}\right),
	\end{aligned}
	$$
where $3(m^p_{1}(y))_{13}$ satisfies the fourth-order analogues of the Painlev\'{e} transcendent in (\ref{4th-Painleve}), see also Appendix \ref{appendix painleve}. Thus this completes the proof of Sector $\rm III$ for $x\ge0$ in Theorem \ref{msk Thm}.

\subsection{Painlev\'{e} region for $x>0$}
	Recall that the saddle point $k_0$ satisfies  $k_0^4=\frac{-x}{45t}$, which indicates that
   it no longer lies on the real line. However, the $k_0$ still behaviors like $t^{-\frac{1}{5}}$ as $t\to\infty$, thus the local self-similar parameters $\lambda$ and $y$ remain unchanged. Similar to the case of $x<0$, decompose the reflection coefficients $\tilde{r}_j(k)~(j=1,2)$ into two parts as shown in the lemma below.
	\begin{lemma} \label{decomposation-x-positive}
		For any integer $N\ge1$, let $A$ be a positive constant, then the functions $\tilde{r}_j(k)~(j=1,2)$ have the following decompositions:
		$$
		\begin{array}{ll}
			\tilde{r}_1(k)=\tilde{r}_{1, a}(x, t; k)+\tilde{r}_{1, r}(x, t; k), & k \in\left(0, \infty\right), \\
			\tilde{r}_2(k)=\tilde{r}_{2, a}(x, t; k)+\tilde{r}_{2, r}(x, t; k), & k \in(-\infty,0),
		\end{array}
		$$
		where the decomposition functions $\tilde{r}_{j,a}(x,t;k)$ and $\tilde{r}_{j,r}(x,t;k)~(j=1,2)$ have the properties as follow:
		\begin{enumerate}
			\item For each $\xi\in[-A,0]$ and $t\ge1$, $\tilde{r}_{1,a}(x,t;k)$ and $\tilde{r}_{2,a}(x,t;k)$ are well-defined and continuous on the regions $\bar{U}_1$ and $\bar{U}_4$, respectively, and are analytic in the interior of their respective domains. The open subsets $U_j$ for $j=1,2,3,4$ are depicted in Figure \ref{regionU painlevege0}.

			\item For $\xi\in[-A,0]$ and $t\ge1$, the functions $\tilde{r}_{j,a}(x,t;k)~(j=1,2)$ satisfy the following estimates:
			$$
			\left|\tilde{r}_{j, a}(x, t; k)-\sum_{i=0}^N\frac{\tilde{r}_j^{(i)}(0)k^i}{i!}\right| \leq C|k|^{N+1}{\mathrm{e}^{t|\Re \Phi_{21}(\xi;k)|/4}},
			$$
			and
			$$
			\left|\tilde{r}_{j, a}(x, t; k)\right| \leq \frac{C}{1+|k|^{N+1}}{\mathrm{e}^{t|\Re \Phi_{21}(\xi;k)|/4}}.
			$$
			\item For each \(1 \leq p \leq \infty\) and \(\xi\in[-A,0]\), the \(L^p\)-norms of \(\tilde{r}_{j,r}(x,t;k)\) \((j=1,2)\) on their respective domains are \(\mathcal{O}(t^{-N})\) as \(t \to \infty\).
		\end{enumerate}
	\end{lemma}
	\begin{proof}
		The proof of this lemma follows the techniques outlined in \cite{Charlier-Lenells-2021}. As these techniques are quite standard, we omit the details for the sake of brevity.
	\end{proof}
