				0 & 1 & \tilde{r}_1(0)\\
				0 & 0 & 1\\
			\end{matrix}
			\right),\\	
			&v_{10}^P=\mathrm{e}^{ad(y\lambda\Lambda-\frac{9\lambda^5}{5}\Lambda^2)}
			\left(\begin{matrix}
				1 & 0 & 0\\
				0 & 1 & 0\\
				-\tilde{r}_2^*(0) & 0 & 1\\
			\end{matrix}
			\right), \quad
			&&v_{11}^P=\mathrm{e}^{ad(y\lambda\Lambda-\frac{9\lambda^5}{5}\Lambda^2)}
			\left(\begin{matrix}
				1 & 0 & -\tilde{r}_2(0)\\
				0 & 1 & 0\\
				0 & 0 & 1\\
			\end{matrix}
			\right),\\
		\end{aligned}
	\end{equation}
	where $\Lambda:=\begin{pmatrix}
		\omega & 0 & 0\\
		0 &\omega^2 & 0\\
		0 & 0 &1
	\end{pmatrix}$ and $\mathrm{e}^{ad(A)}Y=\mathrm{e}^{A}Y\mathrm{e}^{-A}$. Notice that for $n=1,2,\cdots,8$, we have
    $$
    v_{n+4}^{P}=\mathcal{A}^{-1}v_{n}^{P}\mathcal{A},
	$$
    and for $n$ being integer odd with $ 1\le n\le12$, it follows that
	 $$
	v_{n-1}^{P}=\mathcal{B}\bar v_{n}^{P}\mathcal{B}.
      $$


