	\begin{proposition}
		The $3\times3$ matrix-valued function $M^P(y;\lambda)$ has the following properties:	

		(1). $M^P(y;\cdot\ ): \C\setminus \Sigma^P\to\C^{3\times3}$ is analytic for $\lambda \in\C\setminus \Sigma^P$.

		(2). $M^P(y;\lambda)$ is continuous for $\lambda\in \Sigma^P\setminus\{0\}$ and satisfies the jump condition:
		$$
\left(M^P(y;\lambda)\right)_+=\left(M^P(y;\lambda)\right)_-V^{P}(y;\lambda),\quad \lambda\in\C\setminus \{0\},
		$$
		where the jump matrix $V^P=\{v^{P}_j(y;\lambda)\}_{j=1}^{12}$ is defined in (\ref{vp}).

		(3). $M^P(y;\lambda)\to I$  as $\lambda\to\infty$, and more precisely, we have
		$$
		M^P(y;\lambda)=I+\frac{M^P_{1}(y)}{\lambda}+\mathcal{O}\left(\frac{1}{\lambda^2}\right),
		$$
		where 3$(M^P_{1}(y))_{13}$ satisfies the fourth-order analogues of the Painlev\'{e} transcendent in (\ref{4th-Painleve}).
	\end{proposition} 

	\begin{proof}
		By using the jump condition, multiply the jump matrices recursively to arrive at
		$$
		v_1^Pv_2^P\cdots v_{12}^P=I,
		$$
		and then one has
		$$
		\tilde{r}_2(0)=\frac{\tilde{r}_2^*(0)^2-\tilde{r}_1^*(0)}{\tilde{r}_2^*(0)\tilde{r}_1^*(0)-1},\quad
		\tilde{r}_1(0)=\frac{\tilde{r}_1^*(0)^2-\tilde{r}_2^*(0)}{\tilde{r}_2^*(0)\tilde{r}_1^*(0)-1},
		$$
		which is coincided with the Assumption \ref{Painelve assumption}.
		It is immediate  that as $\lambda \to \infty$, the function $M^P(y;\lambda)$ has expansion $M^P(y;\lambda)=\sum_{j=0}^{\infty}\frac{M_j^P(y)}{\lambda^j}$ with $M_0^P=I$. 
        \par
        In particular, by the symmetry $M^P(y;\lambda)=\mathcal{A} M^P( y,\omega\lambda)\mathcal{A}^{-1}$, it follows that the coefficients $M_j^P(y)~(j=1,2,3,4)$ of the asymptotic expansion obey
		$$
		\begin{aligned}
			&M_{1}^P(y)=\omega^2\mathcal{A}M_{1}^P(y)\mathcal{A}^{-1},\ M_2^{P}(y)=\omega\mathcal{A}M_2^{P}(y)\mathcal{A}^{-1},\\
		&M_3^{P}(y)=\mathcal{A}M_3^{P}(y)\mathcal{A}^{-1},\ M_4^{P}(y)=\omega^2\mathcal{A}M_4^{P}(y)\mathcal{A}^{-1},
		\end{aligned}
		$$
		thus is is reasonable to assume that
		\begin{align*}
			&M_1^P(y)=\left(
			\begin{array}{ccc}
				a_1 & a_2 & a_3 \\
				a_3 \omega^2 & a_1 \omega^2 & a_2 \omega^2 \\
				a_2 \omega & a_3 \omega & a_1 \omega \\
			\end{array}
			\right),\
			M_2^P(y)=\left(
			\begin{array}{ccc}
				b_1 & b_2 & b_3 \\
				b_3 \omega & b_1 \omega & b_2 \omega \\
				b_2 \omega^2 & b_3 \omega^2 & b_1 \omega^2 \\
			\end{array}
			\right),\\
			&M_3^{P}(y)=\left(
			\begin{array}{ccc}
				c_1 & c_2 & c_3 \\
				c_3 & c_1 & c_2 \\
				c_2 & c_3 & c_1 \\
			\end{array}
			\right),\
			M_4^P(y)=\left(
			\begin{array}{ccc}
				d_1 & d_2 & d_3 \\
				d_3 \omega^2 & d_1 \omega^2 & d_2 \omega^2 \\
				d_2 \omega & d_3 \omega & d_1 \omega \\
			\end{array}
			\right).
		\end{align*}
        \par
		Furthermore, the conjugate symmetry $M^P(y;\lambda)=\mathcal{B}\overline{M^P(y,\bar\lambda)}\mathcal{B}$ indicates that

		\begin{align*}
		&a_1=\omega\bar a_1,~a_2=\omega \bar a_3,~a_3=\omega \bar a_2,~
			b_1=\omega^2\bar b_1,~b_2=\omega^2 \bar b_3,~b_3=\omega^2 \bar b_2,\\
		&c_1=\bar c_1,~c_2=\bar c_3,~c_3=\bar c_2,~
			d_1=\omega\bar d_1,~d_2=\omega \bar d_3,~d_3=\omega \bar d_2,
		\end{align*}
        which denotes that $\bar a_3=a_3$. This guarantees that the solution of the fourth-order analogues of the Painlev\'{e} transcendent in (\ref{4th-Painleve}) is real-valued, which is associated the real-valued solution of the mSK equation (\ref{msk-equation}).
        \par
		Define the $\mathcal{U}=\Psi_y\Psi^{-1}$ by
		$$
		\mathcal{U}=\Psi_y\Psi^{-1}=(M^P_y+\lambda M^P\Lambda)(M^P)^{-1},
		$$
		where $(M^P)^{-1}=I+\sum_{j=1}\frac{N_j^P}{\lambda^j}$, and since $\mathcal{U}$ is an entire function on $\lambda$, which means that
		$$
		\mathcal{U}(y;\lambda)=\mathcal{U}_0(y;\lambda)+\lambda\mathcal{U}_1(y;\lambda)\\
		=M_1^P(y)\Lambda+\Lambda N_1^P(y)+\lambda \Lambda.
		$$

		Define $\mathcal{A}=\Psi_{\lambda}\Psi^{-1}$ as
		$$
		\mathcal{A}=\Psi_{\lambda}\Psi^{-1}=(M^P_{\lambda}+M^P(y\Lambda-9\lambda^4\Lambda^2))(M^P)^{-1}.
		$$
		As the jump matrices are not concerned to $\lambda$ for $\Psi$, it implies that $\mathcal{A}$ is an entire function and can be expressed by
		$$
		\mathcal{A}=A_0+\lambda A_1+\lambda^2 A_2+\lambda^3 A_3+\lambda^4 A_4,
		$$
		where
		$$
		\begin{aligned}
			&A_0=y\Lambda-9(M_4^P\Lambda^2+M_3^P\Lambda^2N_1^P+M_2^P\Lambda^2N_2^P+M_1^P\Lambda^2N_3^P+\Lambda^2N_4^P),\\
			&A_1=-9(M_3^P\Lambda^2+M_2^P\Lambda^2N_1^P+M_1^P\Lambda^2N_2^P+\Lambda^2N_3^P),\\
			&A_2=-9(M_2^P\Lambda^2+M_1^P\Lambda^2N_1^P+\Lambda^2N_2^P),\\
			&A_3=-9(M_1^P\Lambda^2+\Lambda^2N_1^P),\\
			&A_4=-9\Lambda^2.
		\end{aligned}
		$$
		Furthermore, one has		
		\begin{align*}
		&N_1^P=-M_1^P,\ N_2^P=(M_1^P)^2-M_2^P,\ N_3^P=M_1^PM_2^P+M^P_2M^P_1-(M^P_1)^3-M^P_3,\\
		&N_4^P=(M^P_1)^4+M^P_1M^P_3+M^P_3M^P_1-(M^P_1)^2M^P_2-M^P_1M^P_2M^P_1-M^P_2(M^P_1)^2+(M^P_2)^2-M^P_4.
		\end{align*}

		Notice that
		$$
		\mathcal{U}=(M^P_y+\lambda M^P\Lambda)(M^P)^{-1},
		$$
		which implies that
		$$
		M_y^P=\mathcal{U}M^P-\lambda M^P\Lambda=\lambda[\Lambda,M^P]+[M_1^P,\Lambda]M^P.
		$$
		Moreover, it is seen that
		\begin{equation}
			\begin{aligned}
				(M_1^P)_y=[\Lambda,M_2^P]+[M_1^P,\Lambda]M_1^P,\\
				(M_2^P)_y=[\Lambda,M_3^P]+[M_1^P,\Lambda]M_2^P,\\
				(M_3^P)_y=[\Lambda,M_4^P]+[M_1^P,\Lambda]M_3^P,\\
			\end{aligned}
		\end{equation}
		which reduces that

		\begin{equation}\label{MP_y_equation}
			\begin{aligned}
				&a_1'(y)=3\omega^2a_3(y),\\
				&b_3(y)= \omega a_1(y) a_3(y)+\frac{a_3'(y)}{\omega-1}+\frac{\omega a_3(y)^2}{\omega+1},\\
				&b_2(y)=  a_1(y) a_3(y)-\frac{a_3'(y)}{\omega-1}-a_3(y)^2,\\
				&b_1'(y)=(1-\omega) \omega^2 a_3(y) (b_2(y)-\omega b_3(y)),\\
				&c_3(y)= \frac{\omega^2 \left((\omega-1) a_3(y) ((\omega+1) b_1(y)+b_2(y))-b_3'(y)\right)}{\omega^2-1},\\
				&c_2(y)= \omega a_3(y) (\omega b_1(y)-b_3(y))+\frac{b_2'(y)}{\omega-\omega^2},\\
				&c_1'(y)=(1-\omega) a_3(y) \left(c_2(y)-\omega^2 c_3(y)\right),\\
				&d_2(y)= \frac{a_3(y) \left(\omega^2 c_1(y)-c_3(y)\right)-\frac{c_2'(y)}{\omega-1}}{\omega},\\
				&d_3(y)= \frac{(\omega-1) \omega a_3(y) ((\omega+1) c_1(y)+\omega c_2(y))-c_3'(y)}{\omega \left(\omega^2-1\right)}.
			\end{aligned}
		\end{equation}
		\par
		On the other hand, it is obvious that
		$$
		\begin{cases}
			\begin{aligned}
				&\Psi_y=\mathcal{U}\Psi,\\
				&\Psi_{\lambda}=\mathcal{A}\Psi,
			\end{aligned}
		\end{cases}
		$$
		yields the comparable condition $\mathcal{A}_y-\mathcal{U}_{\lambda}+[\mathcal{A},\mathcal{U}]=0$, and it follows that

		\begin{equation}\label{MP_comparable}
			\begin{aligned}
				&\lambda^0:(A_0)_y-\mathcal{U}_1+[A_0,\mathcal{U}_0]=0,\\
				&\lambda^1:(A_1)_y+[A_1,\mathcal{U}_0]+[A_0,\mathcal{U}_1]=0,\\
				&\lambda^2:(A_2)_y+[A_2,\mathcal{U}_0]+[A_1,\mathcal{U}_1]=0,\\
				&\lambda^3:(A_3)_y+[A_3,\mathcal{U}_0]+[A_2,\mathcal{U}_1]=0,\\
				&\lambda^4:(A_4)_y+[A_4,\mathcal{U}_0]+[A_3,\mathcal{U}_1]=0,\\
				&\lambda^5:[A_4,\mathcal{U}_1]=0.
			\end{aligned}
		\end{equation}
        \par
	By using the ordinary differential equations in (\ref{MP_y_equation}), it is found that the equations in (\ref{MP_comparable}) can be reduced into
		\begin{equation}
			a_3^{(4)}(y)-45 a_3(y)^2 a_3''(y)+a_3(y) \left(y-45 a_3'(y)^2\right)-15 a_3'(y) a_3''(y)+81 a_3(y)^5=0,
		\end{equation}
		and it is immediate that $p(y):=\frac{a_3(y)}{3}$ satisfies 
        the fourth-order analogues of the Painlev\'{e} transcendent (\ref{4th-Painleve}) for $y=s$.
	\end{proof}
	\begin{proposition}
		The $3 \times 3$ matrix-valued function $m^p$ satisfies the following properties:	

		(1). $m^p(y;\lambda):\C\setminus \Sigma^p\to\C^{3\times3}$  is analytic for $\lambda \in\C\setminus \Sigma^p$, where the contour $\Sigma^p$ is depicted in Figure \ref{MPge0}.

		(2). $m^p(y;\lambda)$ is continuous for $\lambda\in\Sigma^p\setminus\{0\}$ and satisfies the jump condition below:
		$$
		\left(m^p(y;\lambda)\right)_+=\left(m^p(y;\lambda)\right)_-v^{p}(y;\lambda),\quad \lambda\in\C\setminus \{0\},
		$$
		where the jump matrix $v^p=v^{p}_j(y;\lambda)$. In particular, they are
		$$
		v_1^p(y;\lambda)=\mathrm{e}^{ad(y\lambda\Lambda-\frac{9\lambda^5}{5}\Lambda^2)}
		\left(\begin{matrix}
			1 & 0 & 0\\
			\tilde{r}_1^*(0) & 1 & 0\\
			0 & 0 & 1\\
		\end{matrix}
		\right),\  v_2^p(y;\lambda)=\mathrm{e}^{ad(y\lambda\Lambda-\frac{9\lambda^5}{5}\Lambda^2)}
		\left(\begin{matrix}
			1 & \tilde{r}_1(0) & 0\\
			0 & 1 & 0\\
			0 & 0 & 1\\
		\end{matrix}
		\right),
		$$
		and
		$$
		v_3^p(y;\lambda)=\mathrm{e}^{ad(y\lambda\Lambda-\frac{9\lambda^5}{5}\Lambda^2)}
		\left(\begin{matrix}
			1 & \tilde{r}_1(0) & 0\\
			\tilde{r}_1^*(0) & 1-|\tilde{r}_1(0)|^2 & 0\\
			0 & 0 & 1\\
		\end{matrix}
		\right).
		$$
		(3). $m^p(y;\lambda)\to I$  as $\lambda\to\infty$, in particular, it follows that
		$$
		m^p(y;\lambda)=I+\frac{m^p_{1}(y)}{\lambda}+\mathcal{O}\left(\frac{1}{\lambda^2}\right),
		$$
		where 3$(m^p_{1}(y))_{13}$ satisfies the fourth-order analogues of the Painlev\'{e} transcendent (\ref{4th-Painleve}) for $y=s$.
	\end{proposition}
