\section{Additional preliminaries}
\paragraph{Discounted MDPs.}
A discounted Markov Decision Process (MDP; \cite{puterman1994markov}) $\cM$ is defined by a tuple
	$\cM = (\cS, \cA, \P, r, \gamma, \rho_0)$.
For notational convenience, for $s,a\in \cS\times\cA$ we let $\P_{s, a} \eqq \P(\cdot \mid s, a) \in \Delta(\cS)$ denote the next state probability measure.
We denote the \emph{value} of $\pi$ when starting from a state $s\in \cS$ by $V_s(\pi)$:
\begin{align*}
    V_s(\pi) \eqq \E\sbr{\sum_{t=0}^\infty \gamma^t r(s_t, a_t) \mid s_0 = s, \pi},
\end{align*}
and more generally for any $\rho\in \Delta(\cS)$,
$V_\rho(\pi) \eqq \E_{s \sim \rho}V_{s}(\pi)$. When the subscript is omitted, $V(\pi)$ denotes value of $\pi$ when starting from the initial state distribution $\rho_0$:
\begin{align*}
    V(\pi) \eqq V_{\rho_0}(\pi) =  \E\sbr{\sum_{t=0}^\infty \gamma^t r(s_t, a_t) \mid s_0 \sim \rho_0, \pi}.
\end{align*}
For any state action pair $s,a\in \cS\times \cA$, the action-value function of $\pi$, or $Q$-function, measures the value of $\pi$ when starting from $s$, taking action $a$, and then following $\pi$ for the reset of the interaction:
\begin{align*}
    Q^\pi_{s, a} \eqq \E\sbr{\sum_{t=0}^\infty \gamma^t r(s_t, a_t) \mid s_0 = s, a_0=a, \pi}
\end{align*}
We further denote the discounted state-occupancy measure of $\pi$ induced by any start state distribution $\rho\in \Delta(\cS)$ by $\mu^\pi_\rho$:
\begin{align*}
    \mu^\pi_{\rho}(s) \eqq 
    \br{1-\gamma}\sum_{t=0}^\infty \gamma^t \Pr(s_t = s \mid s_0 \sim \rho, \pi).
\end{align*}
It is easily verified that $\mu^\pi\in \Delta(\cS)$ is indeed a state probability measure.
In the sake of brevity, we take the MDP true start state distribution $\rho_0$ as the default in case one is not specified:
\begin{align}\label{def:occmeas_rho0}
    \mu^\pi \eqq \mu^\pi_{\rho_0}.
\end{align}

\paragraph{Problem setup.}
We consider an infinite horizon environment interaction model (see Protocol \ref{prot:infinite_horizon_rollout}) similar to that of, e.g., \citet{agarwal2021theory}.

\begin{protocol}[!ht]
    \caption{Infinite horizon environment rollout}
    \label{prot:infinite_horizon_rollout}
	\begin{algorithmic}
            \STATE Environment resets $s_0 \sim \rho_0$
            \FOR{$t = 0, \ldots:$}
                \STATE Agent observes $s_t$,
                chooses $a_t$, incurs $r(s_t, a_t)$ 

                \STATE Environment transitions $s_{t+1} \sim \P(\cdot|s_t, a_t)$
                \STATE Agent decides whether to terminate episode
            \ENDFOR
	\end{algorithmic}
\end{protocol}

\paragraph{Additional notation.}
For a given set $\cX$, we let $\cN(\epsilon, \cX, \norm{\cdot})$ denote the $\epsilon$-\emph{covering number} of $\cX$ w.r.t.~the norm $\norm{\cdot}$. The convex closure of $\cX$ is denoted by ${\rm conv}(\cX)$. We recall our definition for an $\epsexpl$-greedy exploratory version of a policy class $\Pi$ (see \cref{def:Pi_expl}):
\begin{align*}
    \Pi^\epsexpl \eqq \cbr{(1-\epsexpl)\pi + \epsexpl u \mid 
    \pi \in \Pi, u_{s,a} \equiv 1/A\;\forall s, a}
\end{align*}
We conclude by recalling the following notations used throughout:
\begin{align*}
    \mu^k \eqq \mu^{\pi^k}, \quad 
    Q^k \eqq Q^{\pi^k}, \quad 
    S \eqq |\cS|, \quad
    A \eqq |\cA|, \quad
    H \eqq \frac{1}{1-\gamma}.
\end{align*}

\section{First Order Methods for non-Euclidean Optimization}
\label{sec:opt}
In this section, we consider the smooth non-convex optimization problem:
\begin{align}\label{def:opt_main}
    \min_{x\in \cX} f(x),
\end{align}
where $f\colon \cX \to \R$ and 
$\cX \subset \R^d$ is a compact convex set. Our reduction detailed in \cref{sec:framework_reduction} leads to the optimization setup described next. All algorithms presented in \cref{sec:algs} are instances of the algorithms we analyze in this section.
Before introducing the problem setup, we give the following definitions.
\begin{definition}[Variational Gradient Dominance]\label{def:vgd}
    We say $f\colon \cX \to \R$ satisfies the variational gradient dominance condition with parameters $(\cvgd, \epsvgd)$, or that $f$ is $(\cvgd, \epsvgd)$-VGD, if
    here exist constants $\cvgd, \epsvgd>0$, such that for any $x \in \cX$, it holds that:
    \begin{align*}
        f(x) - \argmin_{x^\star\in \cX}f(x^\star)
        \leq 
        \cvgd \max_{\tilde x \in \cX}\abr{\nabla f(x), x - \tilde x} + \epsvgd.
    \end{align*}
\end{definition}

% \begin{definition}[Smoothness]\label{def:smoothness}
%     We say $f\colon \cX \to \R$ is
%     $\beta$-smooth w.r.t.~$\norm{\cdot}$ if for all $x, y\in \dom f$:
%     \begin{align*}
%     \av{f(y) - f(x) - \abr{\nabla f(x), y - x}} \leq 
%     \frac\beta2\norm{y-x}^2 .
%     \end{align*}
% \end{definition}


\begin{definition}[Local Norm]\label{def:local_norm}
    We define a \emph{local} norm over a set $\cX\subseteq \R^d$ by a mapping $x \mapsto \norm{\cdot}_x$ such that $\norm{\cdot}_x$ is a norm for all $x\in \cX$.
    We may denote a local norm by $\norm{\cdot}_{(\cdot)}$ or by $x \mapsto \norm{\cdot}_x$.
\end{definition}

\begin{definition}[Local Smoothness]\label{def:local_smoothness}
    We say $f\colon \cX \to \R$ is
    $\beta$-\emph{locally} smooth w.r.t.~a local norm $x \mapsto \norm{\cdot}_x$ if for all $x, y\in \cX$:
    \begin{align*}
    \av{f(y) - f(x) - \abr{\nabla f(x), y - x}} \leq 
    \frac\beta2\norm{y-x}_x^2 .
    \end{align*}
\end{definition}

\begin{definition}[Local Lipschitz continuity]\label{def:local_Lipschitz}
    We say $f\colon \cX \to \R$ is
    $M$-\emph{locally} Lipschitz w.r.t.~a local norm $x\mapsto \norm{\cdot}_x$ if for all $x\in \cX$:
    \begin{align*}
    \norm{\nabla f(x)}_x^* \leq M.
    \end{align*}
\end{definition}


\paragraph{Problem Setup.}
We consider the problem of computing an approximate global minimum of the objective \cref{def:opt_main},
under the following conditions.
\begin{assumption}\label{assm:opt_setup}
    The local norm $x \mapsto \norm{\cdot}_x$, decision set $\cX$, and objective $f$ satisfy:
    \begin{itemize}
    \item $f$ is $\beta$-locally smooth and $M$-locally Lipschitz w.r.t.~$x \mapsto \norm{\cdot}_{x}$ for $M\geq 1$,
    \item $f$ is $(\cvgd, \epsvgd)$-VGD over $\cX$ with $\nu \geq 1$,
    \item $f$ is bounded from below; $f^\star=\min_{x} f(x) > -\infty$,
    \item $\cX$ has a bounded diameter w.r.t.~$x\mapsto \norm{\cdot}$; $D \geq \max\{1, \max_{x,y,z\in \cX}\norm{z - y}_x\}$.
\end{itemize}
The assumption that $D, M, \nu \geq 1$ is solely for simplicity of presentation; if for example the objective $f$ is $M$-Lipschitz for $M<1$, our results still hold with $M \to \max\{1, M\}$.
\subsection{Constrained steepest descent method}
In this section, we consider the constrained steepest descent method; given an initialization $x_1\in \cX$, step size $\eta>0$, and step error $\epserr>0$:
    \begin{align}\label{def:csd}
        \forall k=1, \ldots, K,\;
        x_{k+1} \in \argmineps_{x\in \cX}
        \cbr{\abr{\nabla f(x_k), x} + \frac1{2\eta}\norm{x - x_k}^2_{x_k}}.
    \end{align}
For this method, we prove the following theorem.
\begin{theorem}\label{thm:csd}
Under \cref{assm:opt_setup},
    the constrained steepest descent method \cref{def:csd} guarantees, as long as $\eta\leq 1/\beta$:
    \begin{align*}
        f(x_{K+1}) - f^\star
        \leq
        \frac{8\br{ \cvgd M D }^{2}}{\eta K}
        + \frac{4  \cvgd M D }{\sqrt \eta}\sqrt{\epserr}
        + \epsvgd
    \end{align*}
\end{theorem}
\end{assumption}
To prove \cref{thm:csd}, we will first establish an analysis framework that connects the algorithm with a notion of constrained steepest descent magnitude.
As a general note, the fact that the norm used in \cref{def:csd} to compute the steepest descent direction is local makes only a syntactic difference in the analysis. Wherever it is convenient we make a claim about a general norm (which may be local and depend on some point), like in \cref{lem:csd_gt_step} below.

Let $\eta > 0$ be a fixed step size.
Given $x\in \cX$, we define the set of potential gradient mappings from $x$ by:
\begin{align}\label{def:csd_gm_set}
	\cG_x \eqq \cbr{\frac1\eta(x - y) \mid y \in \cX},
\end{align}
and the steepest descent magnitude by:
\begin{align}\label{def:csd_dm}
\Des_x \eqq \max_{g \in \cG_x} \cbr{ \abr{\nabla f(x), g} 
    - \frac{1}{2}\norm{g}_x^2}.
\end{align}

\begin{lemma}\label{lem:csd_gt_step}
     For any norm $\norm{\cdot}$, It holds that
    \begin{align*}
    x^+ \in \argmineps_{y\in \cX} \cbr{ \abr{\nabla f(x),y} 
		+ \frac{1}{2\eta}\norm{x - y}^2}&
       \\ \iff
\frac1\eta(x - x^+) \in &\argmaxeps[(\epserr/\eta)]_{g \in \cG_x} \cbr{ \abr{\nabla f(x), g} 
		- \frac{1}{2}\norm{g}^2}.
\end{align*}
\end{lemma}
\begin{proof}
    Observe:
\begin{align*}
\argmineps_{y\in \cX} \cbr{ \abr{\nabla f(x),y} 
		+ \frac{1}{2\eta}\norm{x - y}^2}
&=
\argmineps_{y\in \cX} \cbr{ \abr{\nabla f(x),y - x} 
		+ \frac{1}{2\eta}\norm{y - x}^2}
\\ &=
\argmineps[(\epserr/\eta)]_{y\in \cX} \cbr{ 
    \abr{\nabla f(x),\frac1\eta\br{y - x}} 
		+ \frac{1}{2}\norm{\frac1\eta(y - x)}^2}.
\end{align*}
Further, for any $y \in \cX$, letting $g =\frac1\eta(x - y)$, we have
\begin{align*}
\abr{\nabla f(x),\frac1\eta\br{x - y}} 
		+ \frac{1}{2}\norm{\frac1\eta(x - y)}^2
&=
\abr{\nabla f(x), - g} 
		+ \frac{1}{2}\norm{g}^2
.
\end{align*}
Hence, the gradient mapping $y \mapsto \frac1\eta(x - y)$ is a bijection between $\cX$ and $\cG_x$ that 
gives the same value for the LHS and RHS objectives in the above display. Thus, 
\begin{align*}
x^+ \in \argmineps_{y\in \cX} \cbr{ \abr{\nabla f(x), y} 
		+ \frac{1}{2\eta}\norm{x - y}^2}&
\\
\iff
\frac1\eta(x - x^+) \in &\argmineps[(\epserr/\eta)]_{g \in \cG_x} \cbr{ \abr{\nabla f(x), -g} 
		+ \frac{1}{2}\norm{g}^2}
.
\end{align*}
Finally, 
\begin{align*}
    \argmineps_{g \in \cG_x} \cbr{ \abr{\nabla f(x), -g} 
		+ \frac{1}{2}\norm{g}^2}
    =
    \argmaxeps[(\epserr/\eta)]_{g \in \cG_x} \cbr{ \abr{\nabla f(x), g} 
		- \frac{1}{2}\norm{g}^2},
\end{align*}
which completes the proof.
\end{proof}

\begin{lemma}\label{lem:csd_to_stationarity}
    For all $x\in \cX, \eta > 0$, we have:
$$
	\max_{y\in \cX}\abr{\nabla f(x), x - y}
	\leq 2\max\cbr{D, 1}\max\cbr{\Des_x, \sqrt \Des_x}.
$$
\end{lemma}
\begin{proof}
    Let $y\in\cX$, and note that
\begin{align*}
	\abr{\nabla f(x), x - y}
	=
	\eta  \abr{\nabla f(x), \frac1\eta(x - y)},
\end{align*}
hence
\begin{align}\label{eq:csd_stationarity_to_Dx}
	\max_{y\in \cX}\abr{\nabla f(x), x - y}
	= \eta \max_{g \in \cG_x}\abr{\nabla f(x), g}.
\end{align}
In what follows, we consider the set of gradient mappings restricted to direction $u$ and the corresponding descent quantity in direction $u$:
\begin{align*}
    \cG_x(u) \eqq \cG_x \cap \{\alpha u: \alpha\geq0\};
    \quad
    \Des_x(u) \eqq \max_{g\in \cG_x(u)}
    \abr{\nabla f(x), g} - \frac12\norm{g}_x^2.
\end{align*}
By \cref{lem:sd_to_grad}, we have:
\begin{align*}
    \begin{cases}
    \Des_x(u) = \frac12 \abr{\nabla f(x), u}^2
    & \abr{\nabla f(x), u} u\in \cG_x,
    \\
        \Des_x(u) \geq \frac12\max_{g \in \cG_x(u)}
  \abr{\nabla f(x), g}
    & \abr{\nabla f(x),  u} u\notin \cG_x.
    \end{cases}
\end{align*}
Now, since
\begin{align*}
    \Des_x
    = 
    \max_{g\in \cG_x}\cbr{\abr{\nabla f(x), g} - \frac12\norm{g}_x^2}
    =
    \max_{\norm{u}_x=1}\Des_x(u)
    ,
\end{align*}
it follows that:
\begin{align*}
    \max_{g \in \cG_x}\abr{\nabla f(x), g}
    &=
    \max_{u: \norm{u}_x=1}\max_{g \in \cG_x(u)}\abr{\nabla f(x), g}
    \\
    &\leq 
    \max_{u: \norm{u}_x=1}
    \max\cbr{2 \Des_x(u), \frac D\eta\sqrt{2 \Des_x(u)}}
    \\
    &=
    \max\cbr{2 \Des_x, \frac D\eta\sqrt{2 \Des_x}}
    \\
    &\leq
    \frac{2}{\eta}\max\{D, 1\}\max\cbr{\Des_x, \sqrt{\Des_x}}
    .
\end{align*}
Combining the above with \cref{eq:csd_stationarity_to_Dx}, the result follows.
\end{proof}


\begin{lemma}\label{lem:sd_to_grad}
    Let $x\in \cX$,  $u\in \R^d, \norm{u}_x=1$, and define:
\begin{align*}
    \cG_x(u) \eqq \cG_x \cap \{\alpha u: \alpha\geq0\};
    \quad
    \Des_x(u) \eqq \max_{g\in \cG_x(u)}
    \abr{\nabla f(x), g} - \frac12\norm{g}_x^2.
\end{align*}
Then,
\begin{align*}
    \begin{cases}
    \Des_x(u) = \frac12 \abr{\nabla f(x), u}^2
    & \abr{\nabla f(x), u} u\in \cG_x,
    \\
        \Des_x(u) \geq \frac12\max_{g \in \cG_x(u)}
  \abr{\nabla f(x), g}
    & \abr{\nabla f(x),  u} u\notin \cG_x.
    \end{cases}
\end{align*}

\end{lemma}
\begin{proof}
We have, by definition of $\Des_x(u)$:
\begin{align*}
  \Des_x(u) =
  \max_{\alpha\geq0:\alpha u\in \cG_x}
  \cbr{\abr{\nabla f(x), \alpha u}
  - \frac12\norm{\alpha u}_x^2},
\end{align*}
and we note that without constraining $\alpha u\in \cG_x$, we have
\begin{align*}
    \argmax_{\alpha\geq0}
  \cbr{\abr{\nabla f(x), \alpha u}
  - \frac12\norm{\alpha u}_x^2}
  =
  \argmax_{\alpha\geq0}
  \cbr{ \alpha \abr{\nabla f(x), u}
  - \frac{\alpha^2}{2}}
  = 
  \abr{\nabla f(x), u}.
\end{align*}
Now, set 
$A \eqq \{\alpha : \alpha u \in \cG_x\}$, and 
$\alpha_0 \eqq \sup\{\alpha : \alpha u \in \cG_x\}$.
Observe that since $\cG_x$ is closed and convex, we have $\alpha_0=\infty \implies A=[0, \infty)$, and $\alpha_0 < \infty \implies A=[0, \alpha_0]$.
%
Proceeding, we now consider the two cases from the lemma statement. 
\paragraph{Assume first that $\abr{\nabla f(x), u} u\in \cG_x$.} Then $\alpha_0 \geq \abr{\nabla f(x), u}$, and by since $\alpha = \abr{\nabla f(x), u} \in A$ minimizes the unconstrained problem, it also minimizes the constrained one, hence
\begin{align*}
  \Des_x(u) =
  \frac12\abr{\nabla f(x),  u}^2,
\end{align*}
as required.
\paragraph{Assume now that $\abr{\nabla f(x), u} u\notin \cG_x$.}Then $\alpha_0 < \abr{\nabla f(x), u}$, and since
\begin{align*}
  \alpha \mapsto \cbr{\abr{\nabla f(x), \alpha u}
  - \frac12\norm{\alpha u}_x^2
  =
  \alpha \abr{\nabla f(x), u}
  - \frac{\alpha^2}{2}}
\end{align*}
is monotonically increasing for $\alpha\in[0, \abr{\nabla f(x), \alpha u}]$, we obtain
\begin{align*}
  \Des_x(u) =
  \abr{\nabla f(x), \alpha_0 u}
  - \frac12\norm{\alpha_0 u}_x^2
  &=
  \alpha_0 \br{\abr{\nabla f(x), u}
  - \frac{\alpha_0}2}
  \\
  &\geq
  \alpha_0 \br{\abr{\nabla f(x), u}
  - \frac{\abr{\nabla f(x), u}}2}
  \\
  &=
  \frac12 \abr{\nabla f(x), \alpha_0 u}
  \\
  &=
  \frac12 \max_{0\leq \alpha \in \cG_x}\abr{\nabla f(x), \alpha u}
  \\
  &=
  \frac12 \max_{g \in \cG_x(u)}\abr{\nabla f(x), g}
  .
\end{align*}
This completes the proof.
\end{proof}
We are now ready for the proof of our main theorem.

\begin{proof}[Proof of \cref{thm:csd}]
	For ease of presentation, we prove for the case that $\epsvgd=0$; the general case follows immediately by replacing $f^\star$ with the error floor $f^\star + \epsvgd$ everywhere in the proof.
    Throughout the proof we 
    denote $\cG_k \eqq \cG_{x_k}$ and $\Des_k \eqq \Des_{x_k}$. We recall these are the set of potential gradient mappings and steepest descent magnitude \cref{def:csd_gm_set,def:csd_dm}. For convenience:
\begin{align*}
	\cG_t = \cbr{\frac1\eta(x_k - y) \mid y \in \cX};\quad 
    \Des_{k} = \max_{g \in \cG_t} \cbr{ \abr{\nabla f(x_k), g} 
    - \frac{1}{2}\norm{g}_{x_k}^2}.
\end{align*}
    By \cref{lem:csd_gt_step}, we have that for all $k$, $g_k \eqq \frac1\eta(x_k - x_{k+1})$ satisfies
    \begin{align*}
        g_k \in \argmaxeps[(\epserr/\eta)]_{g \in \cG_k} \cbr{ \abr{\nabla f(x_k), g} 
		- \frac{1}{2}\norm{g}_{x_k}^2}.
    \end{align*}
    Hence, by smoothness of $f$:
\begin{align*}
	f(x_{k+1})
	&\leq f(x_k) + \abr{\nabla f(x_k), x_{t=k+1} - x_k} + \frac \beta2\norm{x_{k+1} - x_k}_{x_k}^2
	\\
	&= f(x_k) - \eta \abr{\nabla f(x_k), g_k} + \frac {\eta^2\beta}2\norm{g_k}_{x_k}^2
	\\
	&\leq f(x_k) - \eta \abr{\nabla f(x_k), g_k} + \frac {\eta}2\norm{g_k}_{x_k}^2
	\tag{$\eta\leq1/\beta$}
	\\
	&= f(x_k) - \eta \br{\abr{\nabla f(x_k), g_k} - \frac {1}2\norm{g_k}_{x_k}^2}
	\\
	&\leq f(x_k) - \eta \br{\Des_k - \epserr/\eta},
\end{align*}
which implies
\begin{align}\label{eq:csd_vgd_descent}
    \eta \Des_k \leq f(x_k) - f(x_{k+1}) + \epserr.
\end{align}
Further, by the VGD assumption and \cref{lem:csd_to_stationarity}:
\begin{align*}
    \frac{1}{\cvgd}\br{f(x_k) - f^\star}
    \leq 
    \max_{y\in \cX}\abr{\nabla f(x_k), x_k - y}
    \leq 2 D \max\cbr{\Des_k, \sqrt \Des_k},
\end{align*}
hence, with $E_k \eqq f(x_k) - f^\star$ the above implies
\begin{align}\label{eq:csd_vgd_1}
    \frac{1}{(2 D \cvgd)^2} E_k^2
    \leq\max\cbr{\Des_k^2, \Des_k}
    .
\end{align}
In addition, we have
\begin{align*}
    \Des_k &= \max_{g\in \cG_k} \cbr{
        \abr{\nabla f(x_k), g} - \frac12\norm{g}_{x_k}^2
    }
    \\
    &\leq 
    \max_{g\in \R^d} \cbr{
        \abr{\nabla f(x_k), g} - \frac12\norm{g}_{x_k}^2
    }
    = \max_{\norm{u}_{x_k}=1}\abr{\nabla f(x_k), u}^2
    = \br{\norm{\nabla f(x_k)}_{x_k}^*}^2
    \leq M^2
    ,
    \\
    \implies
    \max\cbr{\Des_k^2, \Des_k}
    &\leq \max\cbr{M^2 \Des_k, \Des_k}
    =
    M^2 \Des_k.
    \tag{$M\geq 1$}
\end{align*}
Combining with \cref{eq:csd_vgd_1} we obtain
\begin{align*}
    \frac{1}{(2 D \cvgd)^2} E_k^2
    \leq M^2 \Des_k
    \implies 
    \br{2 M \cvgd D}^{-2} E_k^2
    \leq \Des_k.
\end{align*}
Further combining the above display with \cref{eq:csd_vgd_descent}, we obtain:
\begin{align*}
    \omega_0 E_k^2
    &\leq \eta \Des_k
    \leq f(x_k) - f(x_{k+1}) + \epserr
    = E_k - E_{k+1} + \epserr
    \\
    \iff
    \omega_0 \br{E_k^2 - \epserr/\omega_0}
    &\leq E_k - E_{k+1}
    .
\end{align*}
for $\omega_0 \eqq \eta \br{2 \cvgd M D}^{-2}$.
We now consider two cases. In the first, the algorithm converges to the error floor determined by $\epserr$, in the second, $E_k^2 \geq 2\epserr/\omega_0$ for all $k$.
\paragraph{Case 1 (Convergence to error floor).} Suppose that
$E_{k_0}^2 \leq 2\epserr/\omega_0$ for some $k_0\in [K]$. By our previous display, it holds that for all $k$,
\begin{align*}
    E_{k+1}
    &\leq E_k - \omega_0 \br{E_k^2 - \epserr/\omega_0} 
    ,
\end{align*}
which implies that whenever $E_k^2 \geq 2\epserr/\omega_0$, $E_{k+1}\leq E_k$.
Further, since $E_k\geq 0$, we also have that in any case, $E_{k+1}\leq E_k + \epserr$.
Now suppose by contradiction that $E_{K+1} > \sqrt{2\epserr/\omega_0} + \epserr$.
This implies that the last iteration was a descent iteration, hence $E_K > \sqrt{2\epserr/\omega_0} + \epserr$. Proceeding with this argument inductively contradicts our assumption that $E_{k_0}^2 \leq 2\epserr/\omega_0$. Thus, we obtain
\begin{align*}
E_{K+1} \leq \sqrt{2\epserr/\omega_0} + \epserr \leq \frac{4  \cvgd M D }{\sqrt \eta}\sqrt{\epsilon}.	
\end{align*}
%
\paragraph{Case 2 (Descent throughout).} Suppose that ``Case 1'' does not occur, then
$E_k^2 \geq 2\epserr/\omega_0$ for all $k$, which implies $\eta\Des_k - \epsilon \geq \eta\Des_k/2$, and for $\omega\eqq\omega_0/2$:
\begin{align*}
    \omega E_k^2
    \leq E_t - E_{t+1}
    .
\end{align*}
Now, divide both sides of the previous display by $E_k E_{k+1}$ and use that $E_k\geq E_{k+1}$,
\begin{align*}
    \omega \leq \frac{\omega E_k}{E_{k+1}}
    \leq \frac1{E_{k+1}} - \frac1{E_{k}} 
    ,
\end{align*}
and sum over $k$, telescoping the RHS to obtain
\begin{align*}
    \omega K 
    \leq \frac1{E_{K +1}} - \frac1{E_{1}}
    &\implies
    \omega K (E_{K+1} E_1) 
    \leq E_1 - E_{K+1}
    \\
    &\implies
    E_{K+1} 
    \leq E_1 - \omega (E_{K+1} E_1)K.
\end{align*}
Finally,
\begin{align*}
    0\leq E_{K+1} 
    \leq E_1\br{1 - \omega E_{K+1}K},
\end{align*}
and dividing by $E_1$ (if $E_1=0$, there is nothing to prove), we obtain
\begin{align*}
    0\leq  1 - \omega E_{K+1}K
    \implies
    E_{K+1} \leq \frac{1}{\omega K}
    =
    \frac{2\br{2 \cvgd M D}^{2}}{\eta K},
\end{align*}
and which completes the proof.
\end{proof}

Next, we additionally provide a proof for convergence to an approximate stationary point without the VGD assumption. Here we prove for the error free case
\begin{theorem}
    Assume that $f\colon \cX \to \R$ is $\beta$-smooth w.r.t.~a norm $\norm{\cdot}$ over $\cX$ and attains a minimum $f^\star=\min_{x\in \cX} f(x)$.
    Then the constrained steepest descent method \cref{def:csd} with step size $\eta\leq 1/\beta$ guarantees that after $K \geq 1$ iterations, we have that for some $k\in [K]$, $x_k$ is an approximate stationary point:
    \begin{align*}
        \min_{y \in \cX} \abr{\nabla f(x_k), y - x_k}
        \geq - 2D
        \max\cbr{\frac{E_1}{\eta K} + \epserr/\eta, \sqrt {\frac{E_1}{\eta  K}+\epserr/\eta}},
    \end{align*}
    where $E_1\eqq f(x_1) - f^\star$.
\end{theorem}
\begin{proof}
	Similar to the proof of \cref{thm:csd}, we obtain for all $k$:
	\begin{align}
	    \eta \Des_k \leq f(x_k) - f(x_{k+1}) + \epserr.
	\end{align}
Summing over $k$ and rearranging,
\begin{align*}
	\sum_{t=1}^T \Des_k
	\leq \frac{f(x_1) - f(x_{T+1})}{\eta}
	+ \frac{K \epserr}{\eta},
\end{align*}
which implies that for some $k$,
$$
	\Des_k \leq \frac{f(x_1) - f(x_\star)}{\eta K} + \frac{\epserr}{\eta}.
$$
By \cref{lem:csd_to_stationarity}, we have
$$
	\max_{y\in \cX}\abr{\nabla f(x_k), x_k - y}
	\leq 2 D \max\cbr{\Des_k, \sqrt \Des_k}
	\leq 2 D \max\cbr{\frac{E_1}{\eta K} + \epserr/\eta, \sqrt {\frac{E_1}{\eta  K}+\epserr/\eta}},
$$
which proves our claim.
\end{proof}


\subsection{Frank-Wolfe method}
We first present the guarantee of the standard FW \citep{frank1956algorithm} method subject to the VGD condition, without local norms and without a second approximation step. The analysis is fairly standard, but uses the VGD condition where convexity is normally used.
\begin{algorithm}[ht!]
    \caption{Approximate Frank-Wolfe} 
    \label{alg:fw}
	\begin{algorithmic}
	    \STATE \textbf{input:} $
	    	\eta_1, \ldots, \eta_K
	    $; error tolerance $\epsilon>0$.
            \FOR{$k=1, \ldots, K$}
                \STATE Compute
                $\tilde x_{k+1} \in \argmineps[\epsilon]_{x \in \cX} \abr{x, \nabla f(x_k)}$
                \STATE Set
                $x_{k+1} = (1-\eta_k) x_k + \eta_k \tilde x_{k+1}$.
            \ENDFOR
	\end{algorithmic}
\end{algorithm}

\begin{theorem}\label{thm:fw}
Let $\norm{\cdot}$ be a norm, and 
$\cX\subset \R^d$ be a set of bounded diameter $D\geq \max_{x, y\in \cX}\norm{x - y}$.
Assume that $f\colon \cX \to \R$ is $\beta$-smooth w.r.t.~$\norm{\cdot}$ over ${\rm conv} (\cX)$ and attains a minimum $f^\star=\min_{x\in \cX} f(x)$.
Assume further that $\cX, f$ satisfy a $(\cvgd, \epsvgd)$-VGD condition.
    Then the FW method (\cref{alg:fw}) guarantees for all $k$:
    \begin{align*}
	f(x_{k+1}) - f^\star
	&\leq \prod_{s=1}^k(1 - \eta_s/\cvgd)\br{f(x_1) - f^\star} 
+ \frac12\sum_{s=1}^k \prod_{s'=s+1}^k(1 - \eta_{s'}/\cvgd) \br{\eta_s^2 \beta D^2 
     + 2\eta_s \epsilon  
     }     +\epsvgd.
    \end{align*}
    Furthermore, with $\eta_k=\frac{2\cvgd}{k+2}$, we obtain after $K$ iterations:
    \begin{align*}
	f(x_{{K+1}}) - f^\star
	&\leq \frac{ f(x_1) - f^\star + 2 \cvgd^2\beta D^2}{K+2} 
      + 2\cvgd \epsilon 
     +\epsvgd   .
    \end{align*}
\end{theorem}
\begin{proof}
For ease of presentation, we prove for the case that $\epsvgd=0$; the general case follows immediately by replacing $f^\star$ with the error floor $f^\star + \epsvgd$ everywhere in the proof.
    Observe,
	\begin{align*}
		f(x_{k+1}) - f(x_k) 
		&\leq \nabla f(x_k)\T (x_{k+1} - x_k) 
		+ \frac{\beta}{2}\norm{x_{k+1} - x_k}^2
		\tag{$\beta$-smoothness}
		\\
		&= \eta_k \nabla f(x_k)\T (\tilde x_{k+1} - x_k) 
		+ \frac{\beta\eta_k^2}{2}\norm{\tilde x_{k+1} - x_k}^2
		\tag{$x_{k+1} - x_k = \eta_k(\tilde x_{k+1} - x_k)$}
		\\
		&\leq \eta_k \nabla f(x_k)\T (\tilde x_{k+1} - x_k) 
		+ \frac{\eta_k^2\beta D^2}{2}
		.
	\end{align*}
	Further by definition of the algorithm,
	\begin{align*}
		\eta_k \nabla f(x_k)\T (\tilde x_{k+1} - x_k)
		&\leq 
		\eta_k \min_{\tilde x\in \cX}
		\nabla f(x_k)\T (\tilde x - x_k)
		+ \epsilon \eta_k
		\\
		&=
		\frac{\eta_k}{\cvgd} \cvgd\min_{\tilde x\in \cX}
		\nabla f(x_k)\T (\tilde x - x_k)
		+ \epsilon \eta_k
		\\
		&\leq 
		\frac{\eta_k}{\cvgd} \br{f^\star - f(x_k)}
		+ \epsilon \eta_k,
	\end{align*}
	where the last inequality follows by the VGD assumption. Combining this with our previous display now yields,
	\begin{align*}
		f(x_{k+1}) - f(x_k) 
		&\leq \frac{\eta_k}{\cvgd} 
		\br{f^\star - f(x_k)}
		+ \eta_k \epsilon
		+ \beta \eta_k^2 D^2/2,
	\end{align*}
	hence, letting $E_k\eqq f(x_k) - f^\star$ we have,
	\begin{align*}
		E_{k+1}
		&\leq \br{1-\frac{\eta_k}{\cvgd}}E_k
		+ \eta_k^2 \beta D^2/2 
		+ \eta_k \epsilon.
	\end{align*}
    Now, apply the above inequality recursively to obtain
    \begin{align*}
    	E_{k+1} 
    	\leq \prod_{s=1}^k(1 - \eta_s/\cvgd)E_1 
        &+ \frac12\sum_{s=1}^k 
            \prod_{s'=s+1}^k(1 - \eta_{s'}/\cvgd)\br{\eta_s^2 \beta D^2}
        \\
        &\quad   + \sum_{s=1}^k 
            \prod_{s'=s+1}^k(1 - \eta_{s'}/\cvgd)\eta_s
            \epsilon
        ,
    \end{align*}
    which proves the first part.
    For the second part, note that
    choosing $\eta_t = \frac{2\cvgd}{t+2}$ gives
\begin{align*}
	\prod_{s=1}^k (1-\eta_s/\cvgd)=\prod_{s=1}^k \frac{s}{s+2}=\frac{1}{(k+1)(k+2)},    
\end{align*}
and,
\begin{align*}
    \prod_{s'=s+1}^k(1 - \eta_{s'}/\cvgd)\eta_s 
	&= \frac{(s+1)(s+2)}{(k+1)(k+2)}\frac{2\cvgd}{(s+2)}
	\leq \frac{2\cvgd}{k+1}
    \\
    \prod_{s'=s+1}^k(1 - \eta_{s'}/\cvgd)\eta_s^2 
	&= \frac{(s+1)(s+2)}{(k+1)(k+2)}\frac{4\cvgd^2}{(s+2)^2}
	\leq \frac{4\cvgd^2}{(k+1)(k+2)}
    .
\end{align*}
Plugging this back into our bound on $E_{k+1} = f(x_{k+1}) - f^\star$, we obtain:
\begin{align*}
    f(x_{k+1}) - f(x^\star) 
    &\leq
    \frac{f(x_1) - f^\star}{(k+1)(k+2)} 
    + \frac12\sum_{s=1}^k \frac{4\cvgd^2 \beta D^2}{(k+1)(k+2)}
    + \sum_{s=1}^k \frac{2\cvgd \epsilon}{k+1}
    \\
    &\leq
    \frac{f(x_1) - f^\star}{(k+1)(k+2)} 
      + \frac{2 \cvgd^2 \beta D^2}{k+2}
      + 2\cvgd \epsilon
    \\ 
    &\leq 
      \frac{f(x_1) - f^\star + 2 \cvgd^2 \beta D^2}{k+2}
      + 2\cvgd \epsilon,
\end{align*}
as claimed.
\end{proof}

Next, we present the guarantee for the doubly approximate version of FW with local norms.
\begin{algorithm}[ht!]
    \caption{Doubly Approximate Frank-Wolfe} 
    \label{alg:da_fw}
	\begin{algorithmic}
	    \STATE \textbf{input:} $
	    	\eta_1, \ldots, \eta_K
	    $; error tolerances $\epsilon, \tilde \epsilon>0$.
            \FOR{$k=1, \ldots, K$}
                \STATE Compute
                $\tilde x_{k+1} \in \argmineps[\epsilon]_{x \in \cX} \abr{x, \nabla f(x_k)}$
                \STATE Compute
                $x_{k+1} \in 
                \argmineps[\tilde \epsilon]_{x \in \cX} \cbr{\norm{x - ((1-\eta_k) x_k + \eta_k \tilde x_{k+1}))}_{x_k}^2}$.
            \ENDFOR
	\end{algorithmic}
\end{algorithm}

\begin{theorem}\label{thm:da_fw}
    Under \cref{assm:opt_setup}, the Doubly Approximate FW
    \cref{alg:da_fw} guarantees, for all $k$:
    \begin{align*}
	f(x_{k+1}) - f^\star
	&\leq \prod_{s=1}^k(1 - \eta_s/\cvgd)\br{f(x_1) - f^\star} 
	\\ 
     &\quad+ \frac12\sum_{s=1}^k \prod_{s'=s+1}^k(1 - \eta_{s'}/\cvgd) \br{\eta_s^2 \beta D^2 
     + 2\eta_s\br{\epsilon + \beta \sqrt {\tilde \epsilon}} 
     + \tilde \epsilon (2M + \beta)}
     + \epsvgd.
    \end{align*}
    Furthermore, with $\eta_k=\frac{2\cvgd}{k+2}$, we obtain after $K$ iterations:
    \begin{align*}
	f(x_{{K+1}}) - f^\star
	&\leq \frac{(2 \cvgd^2 +1)\beta D^2}{K+2} 
      + 2\cvgd \br{\epsilon + \beta \sqrt{\tilde \epsilon}}
      + \tilde \epsilon \br{M +\beta}K
      + \epsvgd .
    \end{align*}
\end{theorem}
\begin{proof}
For ease of presentation, we prove for the case that $\epsvgd=0$; the general case follows immediately by replacing $f^\star$ with the error floor $f^\star + \epsvgd$ everywhere in the proof.
    For all $k$, let
    \begin{align*}
        x_{k+1}^\star = (1-\eta_k) x_k + \eta_t \tilde x_{k+1}.
    \end{align*}
    We have,
    \begin{align*}
		\frac{\beta}{2}\norm{x_{k+1} - x_k}^2_{x_k}
		&= \frac{\beta}{2}\norm{x_{k+1}^\star - x_k + \br{x_{k+1} - x_{k+1}^\star}}_{x_k}^2
		\\
		&\leq \frac{\beta}{2}\norm{x_{k+1}^\star - x_k}_{x_k}^2 
		+ \beta\norm{x_{k+1}^\star - x_k}\norm{x_{k+1} - x_{k+1}^\star}_{x_k}
		+ \frac\beta2\norm{x_{k+1} - x_{k+1}^\star}^2_{x_k}
		\\
		&= \frac{\beta \eta_k^2}{2}
		\norm{\tilde x_{k+1} - x_k}^2_{x_k} 
		+ \beta\eta_k\norm{\tilde x_{k+1} - x_k}_{x_k}
		\norm{x_{k+1} - x_{k+1}^\star}_{x_k}
		+ \frac\beta2\norm{x_{k+1} - x_{k+1}^\star}^2_{x_k}
		\\
		&\leq \frac{\beta \eta_k^2}{2}D^2 
		+ \beta\eta_k\sqrt {\tilde\epsilon}
		+ \frac\beta2\tilde \epsilon.
	\end{align*}
	Hence,
	\begin{align*}
		f(x_{k+1}) - f(x_k) 
		&\leq \nabla f(x_k)\T (x_{k+1} - x_k) 
		+ \frac{\beta}{2}\norm{x_{k+1} - x_k}^2_{x_k}
		\\
		&\leq \nabla f(x_k)\T (x_{k+1}^\star - x_k) 
		+ \tilde \epsilon M 
		+ \frac{\beta}{2}\norm{x_{k+1} - x_k}^2_{x_k}
		\\
		&= \eta_k \nabla f(x_k)\T (\tilde x_{k+1} - x_k) 
		+ \tilde \epsilon M 
		+ \frac{\beta}{2}\norm{x_{k+1} - x_k}^2_{x_k}
		\\
		&\leq \eta_k \nabla f(x_k)\T (\tilde x_{k+1} - x_k) 
		+ \tilde \epsilon M 
		+ \beta \eta_k^2 D^2/2 
		+ \beta\eta_k\sqrt {\tilde \epsilon}
		+ \beta\tilde \epsilon/2
	\end{align*}
	Now, note that by definition of the algorithm,
	\begin{align*}
		\eta_k \nabla f(x_k)\T (\tilde x_{k+1} - x_k)
		&\leq 
		\eta_k \min_{\tilde x\in \cX}
		\nabla f(x_k)\T (\tilde x - x_k)
		+ \epsilon \eta_k
		\\
		&=
		\frac{\eta_k}{\cvgd} \cvgd\min_{\tilde x\in \cX}
		\nabla f(x_k)\T (\tilde x - x_k)
		+ \epsilon \eta_k
		\\
		&\leq 
		\frac{\eta_k}{\cvgd} \br{f^\star - f(x_k)}
		+ \epsilon \eta_k,
	\end{align*}
	where the last inequality follows by the VGD assumption. Combining this with our previous display now yields,
	\begin{align*}
		f(x_{k+1}) - f(x_k) 
		&\leq \frac{\eta_k}{\cvgd} 
		\br{f^\star - f(x_k)}
		+ \eta_k \epsilon
		+ \tilde \epsilon M 
		+ \beta \eta_k^2 D^2/2 
		+ \beta\eta_k\sqrt {\tilde \epsilon}
		+ \beta\tilde \epsilon/2
		\\
		&= \frac{\eta_k}{\cvgd} 
		\br{f^\star - f(x_k)}
		+ \eta_k^2 \beta D^2/2 
		+ \eta_k \br{\epsilon+ \beta\sqrt {\tilde \epsilon}}
		+ \tilde \epsilon \br{M 
		+ \beta/2},
	\end{align*}
	hence, letting $E_k\eqq f(x_k) - f^\star$ we have,
	\begin{align*}
		E_{k+1}
		&\leq \br{1-\frac{\eta_k}{\cvgd}}E_k
		+ \eta_k^2 \beta D^2/2 
		+ \eta_k \br{\epsilon+ \beta\sqrt {\tilde \epsilon}}
		+ \tilde \epsilon \br{M 
		+ \beta/2}.
	\end{align*}
    Now, apply the above inequality recursively to obtain
    \begin{align*}
    	E_{k+1} 
    	\leq \prod_{s=1}^k(1 - \eta_s/\cvgd)E_1 
        &+ \frac12\sum_{s=1}^k 
            \prod_{s'=s+1}^k(1 - \eta_{s'}/\cvgd)\br{\eta_s^2 \beta D^2}
        \\
        &\quad   + \sum_{s=1}^k 
            \prod_{s'=s+1}^k(1 - \eta_{s'}/\cvgd)\eta_s
            \br{\epsilon  + \beta \sqrt{\tilde\epsilon}}
        \\
        &\quad   + \sum_{s=1}^k 
            \prod_{s'=s+1}^k(1 - \eta_{s'}/\cvgd)\tilde \epsilon
            \br{M + \beta/2}
        ,
    \end{align*}
    which proves the first part.
    For the second part, note that
    choosing $\eta_t = \frac{2\cvgd}{t+2}$ gives
\begin{align*}
	\prod_{s=1}^k (1-\eta_s/\cvgd)=\prod_{s=1}^k \frac{s}{s+2}=\frac{1}{(k+1)(k+2)},    
\end{align*}
and,
\begin{align*}
    \prod_{s'=s+1}^k(1 - \eta_{s'}/\cvgd)
	&= \frac{(s+1)(s+2)}{(k+1)(k+2)},
    \\
    \prod_{s'=s+1}^k(1 - \eta_{s'}/\cvgd)\eta_s 
	&= \frac{(s+1)(s+2)}{(k+1)(k+2)}\frac{2\cvgd}{(s+2)}
	\leq \frac{2\cvgd}{k+1}
    \\
    \prod_{s'=s+1}^k(1 - \eta_{s'}/\cvgd)\eta_s^2 
	&= \frac{(s+1)(s+2)}{(k+1)(k+2)}\frac{4\cvgd^2}{(s+2)^2}
	\leq \frac{4\cvgd^2}{(k+1)(k+2)}
    .
\end{align*}
Plugging this back into our bound on $E_{k+1} = f(x_{k+1}) - f^\star$, we obtain, for any $x^\star\in \argmin_{x\in \cX} f(x)$,
\begin{align*}
    f(x_{k+1}) - f(x^\star) 
    &\leq
    \frac{f(x_1) - f(x^\star)}{(k+1)(k+2)} 
    + \frac12\sum_{s=1}^k \frac{4\cvgd^2 \beta D^2}{(k+1)(k+2)}
    + \sum_{s=1}^k \frac{2\cvgd\br{\epsilon + \beta\sqrt{\tilde \epsilon}}}{k+1}
    + \tilde \epsilon \br{M +\beta}k
    \\
    &\leq
    \frac{f(x_1) - f(x^\star)}{(k+1)(k+2)} 
      + \frac{2 \cvgd^2 \beta D^2}{k+2}
      + 2\cvgd \br{\epsilon + \beta \sqrt{\tilde \epsilon}}
    + \tilde \epsilon \br{M +\beta}k
    \\ &\leq 
    \frac{\beta\norm{x_1 - x^\star}_{x^\star}^2}{2(k+1)(k+2)} 
      + \frac{2 \cvgd^2 \beta D^2}{k+2}
      + 2\cvgd \br{\epsilon + \beta \sqrt{\tilde \epsilon}}
      + \tilde \epsilon \br{M +\beta}k
     \tag{$\abr{\nabla f(x^\star), x_1 - x_\star} \geq 0$}
     \\
      &\leq \frac{(2 \cvgd^2 +1)\beta D^2}{k+2} 
      + 2\cvgd \br{\epsilon + \beta \sqrt{\tilde \epsilon}}
      + \tilde \epsilon \br{M +\beta}k,
\end{align*}
as claimed.
\end{proof}






\subsection{Bregman proximal point method}
We first recall the algorithm as presented in \citet{sherman2025convergence}.
Given any convex regularizer $h\colon \R^d \to \R$, we define the set of $\epsilon$-approximate Bregman proximal point update solutions with step-size $\eta > 0$ by:
\begin{align}\label{def:bregman_prox_approx}
	\cT_{\eta}^{\epsilon}(x; h) 
        \eqq 
	\cbr{x^+ \in \cX \mid \forall z\in \cX: 
		\abr{\grad{f}{x} + \frac1\eta\nabla B_h(x^+, x), z - x^+} \geq -\epsilon}.
\end{align}
The approximate Bregman proximal point update of \citet{sherman2025convergence} is defined by:
\begin{align}\label{alg:opt_omd_0}
    k=1, \ldots, K: \quad 
    		x_{k+1} &\in \cT_{\eta}^{\epsilon}(x_k; R_{x_k}).
\end{align}
\begin{theorem}[\cite{sherman2025convergence}]\label{thm:opt_omd_0}
	Consider \cref{assm:opt_setup}, and suppose further that
	the local regularizer $R_x$ is $1$-strongly convex and has an $L$-Lipschitz gradient w.r.t.~$\norm{\cdot}_x$ for all $x\in \cX$.
    Then, for the Bregman proximal point update \cref{alg:opt_omd_0} we have following guarantee, for $\eta\leq 1/(2\beta)$:
	\begin{align*}
		f(x_{K+1}) - f^\star 
		&= O\br{\frac{\cvgd^2 L^2 c_1^2}{\eta K}
        + \cvgd \epsilon 
        + c_1 L \eta^{-\frac12}\sqrt{\epsilon}
            + \epsvgd
            }
        \end{align*}
	where $c_1 \eqq D + \eta M$.
\end{theorem}
We now consider the Bregman proximal point algorithm that operates with iterates that are approximate minimizers in terms of \emph{function values}:
\begin{align}\label{alg:opt_omd}
    k=1, \ldots, K: \quad 
    		x_{k+1} &\gets \argmineps_{x\in \cX}\cbr{
    		\abr{\nabla f(x_k), x} + \frac1\eta B_{R_{x_k}}(x, x_k)
    		}
\end{align}
We will use the following lemma to translate objective sub-optimality to approximate optimality conditions.
\begin{lemma}\label{lem:subopt_to_optcond}
    Let $\norm{\cdot}$ be a norm, and suppose $D\geq \max\cbr{1, \max_{x,y\in \cX}\norm{x - y}}$.
    Let $\phi\colon \cX \to \R$ be $1$-strongly convex and $L$-smooth w.r.t.$\norm{\cdot}$. Then, for any $\epsilon \leq 1$ if $\hat x\in \argmineps[\epsilon]_{x\in \cX}\phi(x)$, we have:
    \begin{align*}
        \abr{\phi(\hat x), y - \hat x}
        \geq - 2L D\sqrt{2\epsilon}.
    \end{align*}
\end{lemma}
\begin{proof}
    Let $x^\star=\argmin_{x\in \cX}\phi(x)$.
    By $1$-strong convexity and our assumption,
    \begin{align*}
        \frac12\norm{\hat x - x^\star}^2
        \leq \phi(\hat x) - \phi(x^\star)
        \leq \epsilon
        \implies
        \norm{\hat x - x^\star}
        \leq \sqrt{2\epsilon}.
    \end{align*}
    Hence, for any $y\in \cX$, by $L$-smoothness:
    \begin{align*}
        \abr{\phi(\hat x), \hat x - y}
        &=
        \abr{\phi(x^\star), \hat x - y}
        + \abr{\phi(\hat x) - \phi(x^\star), \hat x - y}
        \\
        &\leq
        \abr{\phi(x^\star), \hat x - y}
        + L D \sqrt{2\epsilon}
    \end{align*}
    Further by our assumption and optimality conditions at $x^\star$, 
    \begin{align*}
        \abr{\phi(x^\star), \hat x - y}
        &=
        \abr{\phi(x^\star), x^\star - y}
        + \abr{\phi(x^\star), \hat x - x^\star}
        \\
        &\leq \abr{\phi(x^\star), x^\star - y}
        + \phi(\hat x) - \phi(x^\star)
        \\
        &\leq \abr{\phi(x^\star), x^\star - y}
        + \epsilon
        \\
        &\leq
        + \epsilon
        .
    \end{align*}
    Hence, we have for all $y\in \cX$:
    \begin{align*}
        \abr{\phi(\hat x), \hat x - y}
        \leq L D\sqrt{2\epsilon}
        + \epsilon
        \leq 2 L D\sqrt{2\epsilon},
    \end{align*}
    which completes the proof.
\end{proof}
We are now in position to tprove the following.
\begin{theorem}\label{thm:breg_prox}
	In the same setting of \cref{thm:opt_omd_0}, we have that the Bregman proximal method \cref{alg:opt_omd} with $\epsilon\leq 1$ guarantees, for $\eta\leq 1/(2\beta)$:
	\begin{align*}
		f(x_{K+1}) - f^\star 
		&= O\br{\frac{\cvgd^2 L^2 c_1^2}{\eta K}
        + \cvgd L D \sqrt{ \epsilon }
        + \frac{c_1 \sqrt{L^{3}D}}{\sqrt \eta } \epsilon^{1/4}
            + \epsvgd
            }
        \end{align*}
	where $c_1 \eqq D + \eta M$.
\end{theorem}
\begin{proof}
    By \cref{lem:subopt_to_optcond} applied with the norm $\norm{\cdot}_{x_k}$ and $\phi(x)=\abr{\nabla f(x_k), x} + \frac1\eta B_{R_{x_k}}(x, x_k)$, we have that
    $x_{k+1}$ from \cref{alg:opt_omd} satisfies:
\begin{align*}
	\forall z\in \cX: 
		\abr{\grad{f}{x_k} + \frac1\eta\nabla B_{R_{x_k}}(x_{k+1}, x_k), z - x_{k+1}} \geq -2 L D\sqrt{2\epsilon}.
\end{align*}
This implies that $x_{k+1} \in \cT_{\eta}^{\tilde \epsilon}(x_k; R_{x_k})$ for $\tilde \epsilon = 2 L D\sqrt{2\epsilon}$.
This proves the claimed result be substituting $\epsilon \to 2 L D\sqrt{2\epsilon}$ in the bound of \cref{thm:opt_omd_0}.
\end{proof}

\section{Proofs for Section 4}
In this section, we provide the proofs of convergence for our algorithms in their idealized versions. 
All proofs build on casting our algorithms as instances of those presented in the pure optimization setup, in \cref{sec:opt}.
We note that we did not make particular effort in optimizing dependence on problem parameters other than $K$, and in some cases intentionally opted for slightly worse dependence in favor of cleaner bounds.
\subsection{Analysis preliminaries}
Given a state probability measure $\mu\in \Delta(\cS)$, and an action space norm $\norm{\cdot}_\circ\colon \R^A \to \R$, we define the induced state-action weighted $L^p$ norm $\norm{\cdot}_{L^p(\mu), \circ}\colon \R^{SA}\to \R$:
\begin{align}
	\norm{u}_{L^p(\mu), \circ}
	&\eqq \br{\E_{s \sim \mu}\norm{u_s}_\circ^p}^{1/p}.
\end{align}
For any norm $\norm{\cdot}$, we let $\norm{\cdot}^*$ denote its dual. When discussing a generic norm and there is no risk of confusion, we may use $\norm{\cdot}_*$ to refer to its dual.
%
In addition, for $\mu\in \R^S, Q\in \R^{SA}$, we define the state to state-action element-wise product $\mu \circ Q \in \R^{SA}$:
\begin{align}
	\br{\mu \circ Q}_{s, a} \eqq \mu(s)Q_{s, a}.
\end{align}
Below, we collect a number of results that will be used repeatedly in the analyses.
\begin{lemma}[Value difference; \citealp{kakade2002approximately}]\label{lem:value_diff}
    For any $\rho\in \Delta(\cS)$,
    \begin{align*}
        V_\rho\br{\tilde \pi} -  V_\rho\br{ \pi}
        = \frac{1}{1-\gamma}
        \E_{s\sim \mu_\rho^\pi}\abr{Q^{\tilde \pi}_s, \tilde \pi_s - \pi_s}.
    \end{align*}
\end{lemma}

\begin{lemma}[Policy gradient theorem; \citealp{sutton1999policy}]\label{lem:value_pg}
    For any $\rho\in \Delta(\cS)$,
    \begin{align*}
        \br{\nabla V_\rho(\pi)}_{s, a}
        &= \frac{1}{1-\gamma} \mu^\pi_\rho(s) Q^\pi_{s, a},
        \\
        \abr{\nabla V_\rho(\pi), \tilde \pi - \pi}
        &= \frac{1}{1-\gamma} \E_{s\sim \mu^\pi_\rho} 
        \abr{Q^\pi_s, \tilde \pi_s - \pi_s}.
    \end{align*}
\end{lemma}

\begin{lemma}[\citealp{sherman2025convergence}]\label{lem:value_local_smoothness}
    Let $\pi\colon \cS \to \Delta(\cA)$ be any policy such that $\epsexpl\eqq \min_{s, a}\cbr{\pi_{sa}} > 0$.
    Then, for any $\tilde \pi \in \cS \to \Delta(\cA)$, we have:
    \begin{align*}
        &\av{V(\tilde \pi) - V(\pi) - \abr{\nabla V(\pi), \tilde \pi - \pi}}
        % \\ &\leq %icml_edit
        \leq 
        \min\cbr{
        \frac{  H^3}{\sqrt \epsilon}
            \norm{\tilde \pi - \pi}_{L^2(\mu^\pi), 1}^2,
        \frac{ A H^3}{\sqrt \epsilon}
            \norm{\tilde \pi - \pi}_{L^2(\mu^\pi), 2}^2
        }.
    \end{align*}
\end{lemma}

\begin{lemma}[\citealp{sherman2025convergence}]\label{lem:epsgreedy_vgd}
	Assume $\Pi$ is $(\cvgd, \epsvgd)$-VGD w.r.t.~$\cM$, and consider the $\epsexpl$-greedy exploratory version of $\Pi$, $\Pi^\epsexpl \eqq \cbr{(1-\epsexpl)\pi + \epsexpl u \mid \pi \in \Pi}$, where $u_{s,a} \equiv 1/A$. Then $\Pi^\epsexpl$ is $(\cvgd, \tildepsvgd)$-VGD with $\tildepsvgd \eqq \epsvgd + 12 \cvgd H^2 A \epsexpl $. 
\end{lemma}
The next lemmas follow from standard arguments, for proofs refer to \cite{sherman2025convergence}.
\begin{lemma}\label{lem:weighted_norm_dual}
	For any strictly positive measure $\mu\in \R_{++}^S$,
	the dual norm of $\norm{\cdot}_{L^2(\mu),\circ}$ is given by
	\begin{align}
		\norm{z}_{L^2(\mu), \circ}^*
		&= \sqrt{\int \mu(s)^{-1}\br{\norm{z_s}_\circ^*}^2 {\rm d}s}
	\end{align}
\end{lemma}

\begin{lemma}\label{lem:wnorm_dual_mu}
	Let $\mu\in \Delta(\cS)$, and consider the state-action norm $\norm{\cdot}_{L^2(\mu), \circ}$. For any $W\in \R^{SA}$, we have
	\begin{align*}
		\norm{\mu \circ W}_{L^2(\mu), \circ}^*
		= \sqrt{\E_{s\sim \mu} \br{\norm{W_s}_\circ^*}^2}
	\end{align*}
\end{lemma}
\begin{lemma}\label{lem:value_local_lip}
	For any policy $\pi\in \Delta(\cA)^\cS$ and action norm $\norm{\cdot}_\circ\colon \R^\cA \to \R$, if $\max_{s\in \cS}\norm{Q^\pi_s}_\circ^*\leq G$, then it holds that:
	\begin{aligni*}
            \norm{\nabla V(\pi)}_{L^2(\mu^\pi), \circ}^*
            \leq H G.
        \end{aligni*}
\end{lemma}
\begin{proof}
Observe, by \cref{lem:wnorm_dual_mu}:
	\begin{align*}
            \norm{\nabla V(\pi)}_{L^2(\mu^\pi), \circ}^*
            =
            H\norm{\mu^\pi \circ Q^\pi}_{L^2(\mu^\pi), \circ}^*
            =
            H\sqrt{\E_{s \sim \mu^\pi} \br{\norm{Q^\pi_s}_\circ^*}^2}
            \leq H G.
        \end{align*}
\end{proof}






\subsection{SDPO}
\begin{theorem*}[Restatement of \cref{thm:sdpo}]
    Let $\Pi$ be a convex policy class that satisfies $(\cvgd, \epsvgd)$-VGD w.r.t.~$\cM$.
    Suppose that SDPO (\cref{alg:sdpo}) is executed with the $L^1$ action norm $\norm{\cdot}_1$.
    Then, after $K$ iterations, with appropriately tuned $\eta$ and $\epsexpl$, the output of SDPO satisfies:
    \begin{align*}
        V(\hat \pi) - V^\star(\Pi)
        &= O\br{
        \frac{ \cvgd^2 A H^{4}}{ K^{2/3}}
        + \cvgd H^3 \sqrt A K^{1/6}\sqrt{\varepsilon}
        + \epsvgd}.
    \end{align*}
\end{theorem*}
\begin{proof}[Proof of \cref{thm:sdpo}]
	By the policy gradient theorem (\cref{lem:value_pg}), the update step in \cref{alg:sdpo} may be equivalently written as:
	\begin{align}\label{eq:sdpo_ideal}
        \pi^{k+1}
        \in  
        \argmineps_{\pi\in \Pi^\epsexpl}
            \abr{\nabla V(\pi^k), \pi} 
            + \frac1{2\eta} \norm{\pi - \pi^k}_{L^2(\mu^k),1}^2
   \end{align}
   We now verify a number of conditions that place us in the setup of \cref{assm:opt_setup}.
   \begin{itemize}
   	\item 	\textbf{Local smoothness.}
	By \cref{lem:value_local_smoothness} and the definition of $\Pi^\epsexpl$, the value function is $(2\sqrt A H^3/\sqrt{\epsexpl})$ locally smooth w.r.t.~the 
	local norm $\pi \mapsto \norm{\cdot}_{L^2(\mu^\pi),1}$. 
	\item 	\textbf{VGD condition for $\Pi^\epsexpl$.}
	By \cref{lem:epsgreedy_vgd}, we have that $\Pi^\epsexpl$ satisfies $(\cvgd, \tildepsvgd)$ with $\tildepsvgd \eqq \epsvgd + 12 \cvgd H^2 A \epsexpl$.
	\item \textbf{Local Lipschitz property.} By \cref{lem:value_local_lip}, the value function is $H^2$-local Lipschitz w.r.t.~the 
	local norm $\pi \mapsto \norm{\cdot}_{L^2(\mu^\pi),1}$. 
	\item \textbf{Diameter bound.} We have that $\norm{\pi' - \tilde \pi}_{L^2(\mu^\pi),1} \leq \max_{p, q\in \Delta(\cA)}\norm{p-q}_1\leq 2$, for all $\pi, \pi', \tilde\pi\in \Delta(\cA)^\cS$.
   \end{itemize}
   The above imply we are in the setting of \cref{thm:csd} 
   with $\beta=2\sqrt A H^3/\sqrt{\epsexpl}$, $M=H^2, D=2$.
   Thus, setting $\eta=\sqrt{\epsexpl}/(2H^3 \sqrt A)$, 
	ensures that after $K$ iterations of \cref{eq:sdpo_ideal}, it is guaranteed that:
	\begin{align*}
        V(\pi^{K+1}) - V^\star(\Pi)
        &\lesssim
        \frac{\br{ \cvgd H^2 }^{2}}{\eta K}
        + \frac{  \cvgd H^2 }{\sqrt \eta}\sqrt{\epserr}
        + \tildepsvgd
        \\
        &\lesssim
        \frac{ \cvgd^2 \sqrt A H^{7}}{\sqrt{\epsexpl} K}
        + \frac{\cvgd H^5 A^{1/4}}{\epsexpl^{1/4}}\sqrt{\epserr}
        + \nu A H^2 \epsexpl
        +\epsvgd,
    \end{align*}
	where $\lesssim$ hides only universal constant factors.
	Now set $\epsexpl = \frac{ H^{2}}{ K^{2/3}}$, then
	\begin{align*}
	        V(\pi^{K+1}) - V^\star(\Pi)
	        &\lesssim
	        \frac{ \cvgd^2 A H^{6}}{ K^{2/3}}
	        + \frac{\cvgd H^5 A^{1/4}}{\epsexpl^{1/4}}\sqrt{\epserr}
	        +\epsvgd
	        \\
	        &\leq
	        \frac{ \cvgd^2 A H^{6}}{ K^{2/3}}
	        + \cvgd H^5 \sqrt A K^{1/6}\sqrt{\epserr}
	        +\epsvgd,
	\end{align*}
	as required.
\end{proof}

\subsection{CPI and DA-CPI}
\label{sec:proofs_cpi_dacpi}
In this section, we provide the analysis for CPI and DA-CPI. For CPI, we can make an argument using a non-local norm owed to the usage of the exact convex combination policy obtained in the second step if each iteration in \cref{alg:cpi}. Our first lemma below establishes smoothnes of the value function w.r.t.~the global $\norm{\cdot}_{\infty, 1}$ norm.

\begin{lemma}\label{lem:value_smoothness_infty_1}
    The value function is $(2 H^3)$-smooth w.r.t. the $\norm{\cdot}_{\infty, 1}$ norm; for any $\pi, \tilde \pi \in \cS \to \Delta(\cA)$, we have:
    \begin{align*}
	\av{V(\tilde \pi) - V(\pi) - \abr{\nabla V(\pi), \tilde \pi - \pi}}
	&\leq 
        \frac{2H^3}{2} \norm{\tilde \pi - \pi}_{\infty, 1}^2.
    \end{align*}
\end{lemma}

\begin{proof}
    We have by value difference \cref{lem:value_diff} and the policy gradient theorem \cref{lem:value_pg}:
    \begin{align}
	\av{V(\tilde \pi) - V(\pi) - \abr{\nabla V(\pi), \tilde \pi - \pi}}
	&= \av{H\E_{s \sim \mu^\pi}\abr{Q^{\tilde \pi}_s, \tilde \pi_s - \pi_s}
	- H\E_{s \sim \mu^\pi}\abr{Q^{\pi}_s, \tilde \pi_s - \pi_s}}
	\nonumber \\
        &= \av{H\E_{s \sim \mu^\pi}\abr{Q^{\tilde \pi}_s - Q^\pi_s, \tilde \pi_s - \pi_s}}
	\nonumber \\
	&\leq
		H\E_{s \sim \mu^\pi}\sbr{\av{\abr{{Q^{\tilde \pi}_s - Q^\pi_s}, 
		\tilde \pi_s - \pi_s}}}
	\nonumber \\
	&\leq
		H\E_{s \sim \mu^\pi}\sbr{
			\norm{Q^{\tilde \pi}_s - Q^\pi_s}_\infty
		\norm{\tilde \pi_s - \pi_s}_1}
        \label{eq:lem_smooth_1}.
    \end{align}
    Further, again by value difference \cref{lem:value_diff}, for any $s, a \in \cS \times \cA$:
    \begin{align*}
	Q_{s, a}^{\tilde \pi} - Q_{s, a}^\pi
	&= \gamma \E_{s' \sim \P_{s, a}}\sbr{V_{s'}(\tilde \pi) - V_{s'}(\pi)}
	\\
	&= \gamma H\E_{s' \sim \P_{s, a}}
            \sbr{\E_{s''\sim \mu^\pi_{s'}}\abr{Q^{\tilde\pi}_{s''}, \tilde \pi_{s''} - \pi_{s''}}}
	\\
	&= \gamma H\sum_{s'} \P(s' |s, a)
		\sum_{s''} \mu^\pi_{s'}(s'')
	\abr{Q^{\tilde\pi}_{s''}, \tilde \pi_{s''} - \pi_{s''}}
	\\
	&= \gamma H\sum_{s''} \sum_{s'} \P(s' |s, a)
            \mu^\pi_{s'}(s'')
	\abr{Q^{\tilde\pi}_{s''}, \tilde \pi_{s''} - \pi_{s''}}
	\\
	&= \gamma H\sum_{s''} \mu^\pi_{\P_{s, a}}(s'')
	\abr{Q^{\tilde\pi}_{s''}, \tilde \pi_{s''} - \pi_{s''}}
        \\
	&= \gamma H\E_{s'' \sim \mu^\pi_{\P_{s, a}}} 
	\abr{Q^{\tilde\pi}_{s''}, \tilde \pi_{s''} - \pi_{s''}}.
    \end{align*}
    This implies that for any $s$,
    \begin{align*}
        \norm{Q^{\tilde \pi}_s - Q^\pi_s}_\infty
        &=
        \gamma H\max_a\av{
            \E_{s' \sim \mu^\pi_{\P_{s, a}}} 
    	\abr{Q^{\tilde\pi}_{s'}, \tilde \pi_{s'} - \pi_{s'}}
        }
        \\
        &\leq
        \gamma H^2 \max_a
            \E_{s' \sim \mu^\pi_{\P_{s, a}}} 
    	\norm{\tilde \pi_{s'} - \pi_{s'}}_1
        \\
        &\leq
        \gamma H^2 \norm{\tilde \pi - \pi}_{\infty,1}
    \end{align*}
    Plugging the above back into \cref{eq:lem_smooth_1}, we obtain
    \begin{align*}
	\av{V^{\tilde \pi} - V^{\pi} - \abr{\nabla V^\pi, \tilde \pi - \pi}}
	&\leq
		\gamma H^3 \norm{\tilde \pi - \pi}_{\infty,1} \E_{s \sim \mu^\pi}
		\norm{\tilde \pi_s - \pi_s}_1
        \\
        &\leq 
        \gamma H^3 \norm{\tilde \pi - \pi}_{\infty, 1}^2,
    \end{align*}
    which completes the proof up to a trivial computation.
\end{proof}
We are now ready to prove the guarantee for CPI (\cref{alg:cpi}), by means of reducing it to a non-Euclidean instance of FW \cref{alg:fw}.
\begin{theorem*}[Restatement of \cref{thm:cpi}]
	Let $\Pi$ be a policy class that satisfies $(\cvgd, \epsvgd)$-VGD w.r.t.~$\cM$.
    Suppose that CPI (\cref{alg:cpi}) is executed with the step size choices $\eta_k=\frac{2\cvgd}{k+2}$ for $k=1, \ldots, K$. Then, we have the guarantee that:
    \begin{align*}
    	V(\pi^K) - V^\star(\Pi)
    	\leq \frac{8(2\cvgd^2 + 1)H^3}{K} + 2\cvgd\varepsilon
        + \epsvgd
    \end{align*}
\end{theorem*}
\begin{proof}[Proof of \cref{thm:cpi}]
	By the policy gradient theorem (\cref{lem:value_pg}), the update step in CPI (\cref{alg:cpi}) may be equivalently written as:
	\begin{align*}
        \pi^{k+1}
        \in  
        \argmineps_{\pi\in \Pi}
            \abr{\nabla V(\pi^k), \pi - \pi^k}.
   \end{align*}
   We now verify conditions that place us in the setting of \cref{thm:fw}.
   \begin{itemize}
   	\item 	\textbf{Global smoothness.}
	By \cref{lem:value_smoothness_infty_1}, the value function is $(2H^3)$-smooth w.r.t.~the 
	$\norm{\cdot}_{\infty,1}$ norm. 
	\item 	\textbf{VGD condition.} By assumption, 
		$\Pi$ satisfies $(\cvgd,\epsvgd)$ -VGD.
	\item \textbf{Diameter bound.} We have that $\norm{\pi - \tilde \pi}_{\infty,1} \leq \max_{p, q\in \Delta(\cA)}\norm{p-q}_1\leq 2$ for all $\pi, \tilde \pi\in \Delta(\cA)^\cS$.
   \end{itemize}
   The above imply we are in the setting of \cref{thm:fw} 
   with $\beta=2 H^3$ and $D=2$.
   Thus, our step size choice ensures that after $K$ iterations, it is guaranteed that:
   \begin{align*}
        V(\pi^{K+1}) - V^\star(\Pi)
        &\leq
        \frac{H + 16 \cvgd^2 H^3}{ K}
        + 2\cvgd\epserr
        +\epsvgd
        \leq
        \frac{(16 \cvgd^2 + 1) H^3}{ K}
        + 2\cvgd\epserr
        +\epsvgd,
    \end{align*}
	as required.
\end{proof}


Next, we provide the proof for the guarantees of DA-CPI, which relies on the use of local norms and is actor-oracle efficient.
\begin{theorem*}[Restatement of \cref{thm:da_cpi}]
    Let $\Pi$ be a convex policy class that satisfies $(\cvgd, \epsvgd)$-VGD w.r.t.~$\cM$.
    Suppose that DA-CPI (\cref{alg:da_cpi}) is executed with the $L^1$ action norm $\norm{\cdot}_1$.
    Then, for an appropriate setting of $\eta_1, \ldots, \eta_K$ and $\epsexpl$, we have that the DA-CPI output satisfies:
    \begin{align*}
        V(\hat \pi) - V^\star(\Pi)
        &= O\br{\cvgd^2 AH^3\br{
	   \frac{1}{K^{2/3}} 
            + \varepsilon^{1/3}
    	+ \varepsilon^{2/3}  K^{2/3}}
        }
    .
    \end{align*}
\end{theorem*}
\begin{proof}[Proof of \cref{thm:da_cpi}]
	By the policy gradient theorem (\cref{lem:value_pg}), the first update step in \cref{alg:da_cpi} may be equivalently written as:
	\begin{align*}
        \pi^{k+1}
        \in  
        \argmineps_{\pi\in \Pi^\epsexpl}
            \abr{\nabla V(\pi^k), \pi - \pi^k}.
   \end{align*}
   We now verify a number of conditions that place us in the setup of \cref{assm:opt_setup}.
   \begin{itemize}
   	\item 	\textbf{Local smoothness.}
	By \cref{lem:value_local_smoothness} and the definition of $\Pi^\epsexpl$, the value function is $(2\sqrt A H^3/\sqrt{\epsexpl})$ locally smooth w.r.t.~the 
	local norm $\pi \mapsto \norm{\cdot}_{L^2(\mu^\pi),1}$. 
	\item 	\textbf{VGD condition for $\Pi^\epsexpl$.}
	By \cref{lem:epsgreedy_vgd}, we have that $\Pi^\epsexpl$ satisfies $(\cvgd, \tildepsvgd)$ with $\tildepsvgd \eqq \epsvgd + 12 \cvgd H^2 A \epsexpl$.
	\item \textbf{Local Lipschitz property.} By \cref{lem:value_local_lip}, the value function is $H^2$-local Lipschitz w.r.t.~the 
	local norm $\pi \mapsto \norm{\cdot}_{L^2(\mu^\pi),1}$. 
	\item \textbf{Diameter bound.} We have that $\norm{\pi' - \tilde \pi}_{L^2(\mu^\pi),1} \leq \max_{p, q\in \Delta(\cA)}\norm{p-q}_1\leq 2$, for all $\pi, \pi', \tilde\pi\in \Delta(\cA)^\cS$.
   \end{itemize}
   The above imply we are in the setting of \cref{thm:da_fw} 
   with $\beta=2\sqrt A H^3/\sqrt{\epsexpl}$, $M=H^2, D=2$, and $\epsilon=\tilde \epsilon=\epserr$.
   Thus, with step sizes set according to the statement of \cref{thm:da_fw},
	we have that after $K$ iterations:
	\begin{align*}
        V(\pi^{K+1}) - V^\star(\Pi)
        &\lesssim
        \frac{\cvgd^2 \sqrt A H^3 }{\sqrt{\epsexpl}K}
        + \frac{\cvgd\sqrt A H^3}{\sqrt{\epsexpl}}
        \sqrt{\epserr} 
        + \frac{\sqrt A H^3}{\sqrt{\epsexpl}}\epserr K 
        + \cvgd A H^2 \epsexpl
        + \epsvgd
        \\
        &\leq
        \frac{\cvgd^2 \sqrt A H^3 }{\sqrt{\epsexpl}}
        \br{\frac1K + \sqrt{\epserr} + \epserr K}
        + \cvgd A H^2 \epsexpl
        + \epsvgd
    \end{align*}
	where $\lesssim$ hides only universal constant factors.
	Now, set $\epsexpl=\br{\frac{1}{K} + \sqrt{\epserr}+ \epserr  K}^{2/3}$, and use the fact that $(a + b)^{2/3} \leq a^{2/3} + b^{2/3}$
to immediately obtain the stated bound.
\end{proof}


\subsection{PMD}
\label{sec:proofs_pmd}
The PMD method \citep{tomar2020mirror,xiao2022convergence,lan2023policy} make use of an action regularizer, and more specifically the Bregman divergence w.r.t.~the chosen regularizer, which we define below.
\begin{definition}[Bregman divergence]\label{def:bregman_divergenvce}
    Given a convex differentiable regularizer $R \colon \R^\cA \to \R$, the Bregman divergence w.r.t.~$R$ is:
    \begin{align*}
        B_R(u, v) \eqq R(u) - R(v) - \abr{\nabla R(v), u -v}.
    \end{align*}
\end{definition}
We will make use of the following elementary lemma, which follows from standard arguments; for proof see \citet{sherman2025convergence}.
\begin{lemma}\label{lem:reg_transform}
	Assume $h\colon \R^A \to \R$ is $1$-strongly convex and has $L$-Lipschitz gradient w.r.t.~$\norm{\cdot}$.
	Let  $\mu\in \Delta(\cS)$, and define $R_\mu(\pi) \eqq \E_{s\sim \mu}[h(\pi_s)]$.
	Then
	\begin{enumerate}
		\item $B_{R_\mu}(\pi, \tilde \pi) = \E_{s \sim \mu} B_R(\pi_s, \tilde \pi_s)$.
		\item $R_\mu$ is $1$-strongly convex and has an $L$-Lipschitz gradient w.r.t. $\norm{\cdot}_{L^2(\mu), \circ}$. 
	\end{enumerate}

\end{lemma}
Below we restate and prove the guarantee for the PMD method detailed in \cref{alg:pmd}.

\begin{algorithm}[tb]
   \caption{Policy Mirror Descent (PMD)}
   \label{alg:pmd}
\begin{algorithmic}
   \STATE {\bfseries Input:} 
   $K\geq 1, \eta > 0, \varepsilon > 0, \epsexpl >0, \Pi\in \Delta(\cA)^\cS$, and action regularizer $R\colon\R^\cA \to \R$.
   \STATE Initialize $\pi^1 \in \Pi^\epsexpl$
   \FOR{$k=1$ {\bfseries to} $K$}
   \STATE Update
   \begin{aligni*}
        \pi^{k+1}
        \gets 
        \argmineps_{\pi\in \Pi^\epsexpl}
        \E_{s\sim \mu^k} \sbr{
            H\abr{Q^{k}_{s}, \pi_s} 
            + \frac1{\eta} B_R\br{\pi_s, \pi_s^k}
        }
   \end{aligni*}
   \ENDFOR
   \RETURN $\hat \pi \eqq \pi^{K+1}$
\end{algorithmic}
\end{algorithm}

\begin{theorem*}[Restatement of \cref{thm:pmd}]
    Let $\Pi$ be a convex policy class that satisfies $(\cvgd, \epsvgd)$-VGD w.r.t.~$\cM$.
    Suppose that PMD (see \cref{alg:pmd}) is 
    executed with the $L^2$ action regularizer.
    Then, with an appropriate tuning of  $\eta, \epsexpl$, we have that the output of PMD satisfies:
    \begin{align*}
        V(\hat \pi) - V^\star(\Pi)
        &= O\br{
            \frac{\cvgd^2 A^{3/2} H^3 }{ K^{2/3}}
            + \br{\cvgd + H^2 A K^{1/6}}\varepsilon^{1/4}
            }.
    \end{align*}
\end{theorem*}
\begin{proof}[Proof of \cref{thm:pmd}]
	We now verify a number of conditions that place us in the setup of \cref{assm:opt_setup}.
   \begin{itemize}
   	\item 	\textbf{Local smoothness.}
	By \cref{lem:value_local_smoothness} and the definition of $\Pi^\epsexpl$, the value function is $(2 A^{3/2} H^3/\sqrt{\epsexpl})$ locally smooth w.r.t.~the 
	local norm $\pi \mapsto \norm{\cdot}_{L^2(\mu^\pi),2}$. 
	\item 	\textbf{VGD condition for $\Pi^\epsexpl$.}
	By \cref{lem:epsgreedy_vgd}, we have that $\Pi^\epsexpl$ satisfies $(\cvgd, \tildepsvgd)$ with $\tildepsvgd \eqq \epsvgd + 12 \cvgd H^2 A \epsexpl$.
	\item \textbf{Local Lipschitz property.} By \cref{lem:value_local_lip} and the fact that $\norm{Q^\pi_s}_2\leq \sqrt A H$ for all $\pi, s$, the value function is $(\sqrt A H^2)$-local Lipschitz w.r.t.~the 
	local norm $\pi \mapsto \norm{\cdot}_{L^2(\mu^\pi),2}$. 
	\item \textbf{Diameter bound.} We have that $\norm{\pi' - \tilde \pi}_{L^2(\mu^\pi),2} \leq \max_{p, q\in \Delta(\cA)}\norm{p-q}_2\leq 2$, for all $\pi, \pi', \tilde\pi\in \Delta(\cA)^\cS$.
	\item \textbf{Regularizer smoothness.} The euclidean action norm $R(p)=\frac12\norm{p}_2^2$ is $1$-smooth.
   \end{itemize}
   The above imply we are in the setting of \cref{thm:breg_prox} 
   with $\beta=2A^{3/2} H^3/\sqrt{\epsexpl}$, $M=\sqrt A H^2, D=2, L=1$. 
   Thus, setting $\eta=\sqrt{\epsexpl}/(2H^3 A^{3/2})$, we have $c_1=D + \eta M=O(1)$, and the guarantee that ($\lesssim$ suppresses constant numerical factors):
	\begin{align*}
		V(\pi^{K+1}) - V^\star(\Pi)
		&\lesssim  
		\frac{\cvgd^2 }{\eta K}
        + \cvgd \sqrt{ \epserr }
        + \frac{ \epserr^{1/4}}{\sqrt \eta }
            + \epsvgd
        \\
        &\lesssim 
        \frac{\cvgd^2 A^{3/2} H^3 }{\sqrt\epsexpl K}
            + \cvgd \sqrt{ \epserr }
            + \frac{\sqrt {H^3 A^{3/2}}}{\epsexpl^{1/4}}\epserr^{1/4}
            + \nu A H^2 \epsexpl
            + \epsvgd
        \\
        &\lesssim 
        \frac{\cvgd^2 A^{3/2} H^3 }{\sqrt\epsexpl K}
            + \epserr^{1/4}\br{\cvgd
            + \frac{H^2 A}{\epsexpl^{1/4}}}
            + \nu A H^2 \epsexpl
            + \epsvgd.
	\end{align*}
	Choosing $\epsexpl = K^{-2/3}$, we immediately obtain the stated bound.
\end{proof}

\section{Sample complexity upper bounds}
\label{sec:sc}
In this section, we demonstrate how our iteration complexity upper bounds may be translated to sample complexity upper bounds.
The sampling scheme \cref{alg:sampler} we employ to estimate the full gradient step is based on importance sampling and in itself is fairly standard. A similar algorithm can be found in e.g., \cite{agarwal2021theory}. Throughout this section we adopt the assumption that $\gamma\leq 1/2$ in sake of simplified presentation. In terms of the effective horizon this implies $H\geq 2$, which is the interesting regime.
\begin{algorithm}[tb]
   \caption{Action-value estimation}
   \label{alg:sampler}
\begin{algorithmic}
   \STATE {\bfseries Input: $\pi$} 
   \STATE Begin rollout at $s_0 \sim \rho_0$
   \STATE For each timestep $t=0,\ldots$, act $a_t \sim \pi_{s_t}$, and
   $\begin{cases}
       \text{continue }
       \quad &\text{w.p.~}\gamma
       \\
       \text{accept } s_t
       \quad &\text{w.p.~}1-\gamma
   \end{cases}$
   \STATE After accepting $s_t$, sample $a_t\sim \Unif(\cA)$ and continue the rollout, terminating at each step w.p.~$1-\gamma$.
   \STATE Assume the rollout terminated at iteration $T$. Define $\widehat Q^\pi_{s_t}\in \R^\cA$ by
   \begin{align*}
    \forall a\in \cA: \;
    \widehat Q^\pi_{s_t, a} = 
    \I\cbr{a=a_t}A\sum_{t'=t}^T r(s_{t'}, a_{t'}).
    \end{align*}
   \RETURN $s_t, \widehat Q^\pi_{s_t}$
\end{algorithmic}
\end{algorithm}
The first lemma given below, provides the connection between optimizing the empirical and population objectives. 
\begin{lemma}\label{lem:update_steps_ge}
    Let $\widetilde \Pi$ be a policy class and suppose $\gamma\leq 1/2$.
    Assume $\Div\colon \R^\cA \times \R^\cA \to \R_+$ is a non-negative function that satisfies:
    \begin{itemize}
    	\item Boundedness: $D \geq \Div(p, q)$ for all $p,q\in \Delta(\cA)$.
    	\item Lipschitz continuity w.r.t.~the $1$-norm:
    $\av{\Div(p, p_0) - \Div(q, p_0)}\leq L\norm{p-q}_1$ for all $p, q, p_0\in \Delta(\cA)$.
    \end{itemize}
    Let $\pi^1\in \widetilde \Pi$, suppose $\pi^{k+1}\in \widetilde \Pi$ satisfy for all $k\in [K]$, for a given learning rate $0<\eta\leq 1$,
    \begin{align}\label{eq:concentration_hat_phi_k}
        \pi^{k+1}
        \in 
        \argmineps[\epserm]_{\pi\in \widetilde \Pi}\cbr{
        \widehat \Phi_k(\pi) \eqq
        \frac1N \sum_{s \in \cD_k} {
            \abr{H \widehat Q^{k}_{s}, \pi_s} 
            + \frac1{\eta} \Div\br{\pi_s, \pi_s^k}
        }},
    \end{align}
    where $\cD_k$ are a (state, action-value) datasets of size $N$ obtained by invoking \cref{alg:sampler}.
    Then,
    for any $\delta>0$, 
    w.p.~$\geq 1-\delta$, it holds that for all $k\in [K]$,
    \begin{align}\label{eq:concentration_phi_k}
        \pi^{k+1}
        \in 
        \argmineps_{\pi\in \widetilde \Pi}\cbr{
        \Phi_k(\pi) \eqq
        \E_{s\sim \mu^k}\sbr{
        \abr{H Q^k_s, \pi_s}+ \frac1{\eta} \Div\br{\pi_s, \pi_s^k}
        }
        },
    \end{align}
    where $\epserr = \epserm + \epsgen$,
    \begin{aligni*}
        \epsgen \eqq \frac{\cgen A H^2 D}{\eta}\sqrt{
            \frac{\log\frac{KN\cN(\epsnet, \widetilde \Pi, \norm{\cdot}_{\infty, 1})}{\delta}}{ N}
        },
    \end{aligni*}
    $\cgen>0$ is an absolute numerical constant, 
    and 
    $\epsnet \geq 
    \frac{\cgen AH^2D}{6 \sqrt{ N} (A H^2\log(2 KN/\delta)  + L)}$. Furthermore, the number of time steps of each episode rolled out by \cref{alg:sampler} is $\leq 2 H \log\br{2 K N/\delta} $.
\end{lemma}
We defer the proof of \cref{lem:update_steps_ge} to \cref{sec:update_steps_ge_proof}.
We now turn
to apply the lemma in conjunction with the iteration complexity guarantee of SDPO (\cref{thm:sdpo}) to obtain a sample complexity upper bound for SDPO in the learning setup (\cref{alg:sc_sdpo}).
Afterwards, we present sample complexity upper bounds for the other algorithms in \cref{sec:sc_cpi_da_cpi,sec:sc_pmd}.
We note that there are a number of places where we expect the analysis can be tightened subject to future work; primarily, the greedy exploration required by the current local-smoothness analysis.
Hence, the actual rate obtained is not the primary focus of our work. Furthermore, we did not make a notable effort in obtaining optimal dependence on all problem parameters, and expect these can be easily tightened by a more careful choice analysis and choice of algorithm input-parameters.

\begin{algorithm}[tb]
   \caption{SDPO in the learning letup}
   \label{alg:sc_sdpo}
\begin{algorithmic}
   \STATE {\bfseries Input:} 
   $K\geq 1, N\geq 1, \eta > 0, \epsexpl >0, \epserm>0, \Pi\in \Delta(\cA)^\cS$, and action norm $\norm{\cdot}_\circ\colon\R^\cA \to \R$.
   \STATE Initialize $\pi^1 \in \Pi^\epsexpl$
   \FOR{$k=1$ {\bfseries to} $K$}
   \STATE Rollout $\pi^k$ for $N$ episodes via \cref{alg:sampler}, obtain $\cD_k = \cbr{s_i^k, \widehat Q_{s_i^k}^k}_{i=1}^N$.
   \STATE Update
   \begin{aligni*}
        \pi^{k+1}
        \gets 
        \argmineps[\epserm]_{\pi\in \Pi^\epsexpl}\cbr{
        \widehat \Phi_k(\pi) \eqq
        \frac1N \sum_{s \in \cD_k} {
            \abr{H \widehat Q^{k}_{s}, \pi_s} 
            + \frac1{2\eta} \norm{\pi_s - \pi_s^k}_\circ^2
        }}
   \end{aligni*}
   \ENDFOR
   \RETURN $\hat \pi \eqq \pi^{K+1}$
\end{algorithmic}
\end{algorithm}
\begin{theorem}\label{thm:sc_sdpo}
	Let $\Pi$ be a convex policy class that satisfies $(\cvgd, \epsvgd)$-VGD w.r.t.~$\cM$, and assume $\gamma \leq 1/2$.
	Then for any $n\geq 1$, 
	there exists a choice of parameters $K, N, \eta, \epsexpl$ such that
 \cref{alg:sc_sdpo} executed with the $L^1$ action norm guarantees for any $\delta>0$, that w.p.~$\geq 1-\delta$ the total number of environment time steps $\leq n$, and the output policy satisfies 
	\begin{align*}
        V(\hat \pi) - V^\star(\Pi)
        &= O\br{
        \frac{\cvgd^2 A^2 H^{7} \sqrt{\log\frac{ n \cC(\Pi)}{\delta}}}{ n^{2/15}}
        + \cvgd H^3 \sqrt A n^{1/30}\sqrt{\epserm}
        + \epsvgd},
    \end{align*}
    where  $\cC(\Pi) \eqq \cN(\epsnet, \Pi, \norm{\cdot}_{\infty, 1})$ is the $\epsnet$-covering number of $\Pi$
    and 
   	\begin{aligni*}
    	\epsnet 
    	= \Omega\br{\tfrac{ 1}{ \log(n/\delta) n }}
    	.
    \end{aligni*}
\end{theorem}
\begin{proof}
	Note that for any $p,q\in \Delta(\cA)$, $\frac12\norm{p-q}_1^2\leq 2$, and
	\begin{align*}
		\frac12\norm{p-p_0}_1^2
		- \frac12\norm{q-p_0}_1^2
		&=
		\frac12\br{\norm{p-p_0}_1 + \norm{q-p_0}_1}
		\br{\norm{p-p_0}_1 - \norm{q-p_0}_1}
		\\
		&\leq2\br{\norm{p-p_0}_1 - \norm{q-p_0}_1}
		\\
		&\leq2\norm{p-q}_1.
	\end{align*}
	Thus, when executing \cref{alg:sc_sdpo} over $K$ iterations, we are in the setting of \cref{lem:update_steps_ge} with $D=2, L=2$.
	Suppose we run the algorithm for $K$ iterations with $\eta=\sqrt{\epsexpl}/(2H^3 \sqrt A)$, $\epsexpl=H^2/K^{2/3}$, and $N$ (and $K$) to be chosen later on.
	For any $\delta>0$, we have by \cref{lem:update_steps_ge} that w.p.~$\geq 1-\delta$, for all $k\in [K]$ it holds that:
	\begin{align}\label{eq:sdpo_sc_proof_1}
        \pi^{k+1}
        \in 
        \argmineps_{\pi\in \Pi^\epsexpl}\cbr{
        \Phi_k(\pi) \eqq
        \E_{s\sim \mu^k}\sbr{
        \abr{H Q^k_s, \pi_s}+ \frac1{2\eta} \norm{\pi_s - \pi_s^k}_1^2
        }
        },
    \end{align}
    with $\epserr = \epserm + \epsgen$, where
    \begin{align*}
        \epsgen =O\br{ \frac{A H^2}{\eta}\sqrt{
            \frac{\log\frac{ K N \cC(\Pi)}{\delta}}{ N}
        }},
    \end{align*}
	$\cC(\Pi) \eqq \cN(\epsnet, \Pi, \norm{\cdot}_{\infty, 1})$,
    and 
    \begin{aligni*}
    	\epsnet 
    	= \Omega\br{\tfrac{ 1}{ \log(KN/\delta) \sqrt{ N} }}.
    \end{aligni*}
    Now, \cref{eq:sdpo_sc_proof_1} implies \cref{alg:sc_sdpo} is an instance of the idealized SDPO \cref{alg:sdpo} with the error $\epserr$ defined above.
    Hence, by \cref{thm:sdpo}, we have that
    \begin{align}\label{eq:sc_sdop_1}
        V(\hat \pi) - V^\star(\Pi)
        &= O\br{
        \frac{ \cvgd^2 A H^{4}}{ K^{2/3}}
        + \cvgd H^3 \sqrt A K^{1/6}\sqrt{\epserr}
        + \epsvgd}
        \nonumber
        \\
        &= O\br{
        \frac{ \cvgd^2 A H^{4}}{ K^{2/3}}
        + \cvgd H^3 \sqrt A K^{1/6}\sqrt{\epsgen}
        + \cvgd H^3 \sqrt A K^{1/6}\sqrt{\epserm}
        + \epsvgd}.
    \end{align}
    We focus on the first two terms to choose $K,N$ as a function of $n$.
    Observe:
    \begin{align*}
        \frac{\cvgd^2 A H^{4}}{ K^{2/3}}
        + \cvgd H^3 \sqrt A K^{1/6}\sqrt{\epsgen}
        &\approx 
        \frac{\cvgd^2 A H^{4}}{ K^{2/3}}
        + \cvgd H^3 \sqrt A K^{1/6}
        	\frac{\sqrt A H}{\sqrt{\eta}}
            \frac{\log^{1/4}\frac{ K N \cC(\Pi)}{\delta}}{ N^{1/4}}
       \\
       &=
       \frac{\cvgd^2 A H^{4}}{ K^{2/3}}
        + \frac{\cvgd A H^4 K^{1/6} \iota}{\sqrt{\eta} N^{1/4}}
    \end{align*}
    with $\iota \eqq \log^{1/4}\frac{ K N \cC(\Pi)}{\delta}$.
    Further, by our choice of $\eta, \epsexpl$, $\eta=H/(2H^3 \sqrt A K^{1/3})$, hence
    \begin{align*}
    	\frac{\cvgd^2 A H^{4}}{ K^{2/3}}
        + \frac{\cvgd A H^4 K^{1/6} \iota}{\sqrt{\eta} N^{1/4}}
        &\approx
            	\frac{\cvgd^2 A H^{4}}{ K^{2/3}}
        + \frac{\cvgd A H^4 K^{1/6} \iota \sqrt{H^3 \sqrt A K^{1/3}}}{\sqrt{H} N^{1/4}}
        \\
        &\leq
         \frac{\cvgd^2 A H^{6}}{ K^{2/3}}
        + \frac{\cvgd A^2 H^5 \iota }{N^{1/4}}K^{1/3}.
    \end{align*}
    Choosing $N=K^{4}$ gives
    \begin{align*}
    	\frac{\cvgd^2 A H^{6}}{ K^{2/3}}
        + \frac{\cvgd A^2 H^5 \iota }{N^{1/4}}K^{1/3}
        &\lesssim
        \frac{\cvgd^2 A^2 H^{6} \iota}{ K^{2/3}},
    \end{align*}
    with $n \leq KN \widetilde H = K^5 \widetilde H$ with $\widetilde H= H \log(2KN/\delta)$ by \cref{lem:update_steps_ge}.
    Hence $K\geq n^{1/5}/\widetilde H^{1/5}$, and
    \begin{align*}
    	\frac{\cvgd^2 A^2 H^{6} \iota}{ K^{2/3}}
    	&\leq 
    	\frac{\cvgd^2 A^2 H^{6} \widetilde H^{2/15}\iota}{ n^{2/15}}.
    \end{align*}
	Now substitute $\widetilde H^{2/15} \lesssim H^{1/2} \log^{1/4} (n/\delta)$,
	and $\iota=\log^{1/4}\frac{ K N \cC(\Pi)}{\delta} 
	\lesssim \log^{1/4}\frac{ n \cC(\Pi)}{\delta}$
	to obtain 
	\begin{align*}
    	\frac{\cvgd^2 A^2 H^{6} \widetilde H^{2/15}\iota}{ n^{2/15}}
    	\lesssim
    	\frac{\cvgd^2 A^2 H^{7} \sqrt{\log\frac{ n \cC(\Pi)}{\delta}}}{ n^{2/15}}.
    \end{align*}
    Finally, using that and plugging our upper bound back into \cref{eq:sc_sdop_1} and using that $K \leq n^{1/5}$:
    \begin{align*}
        V(\hat \pi) - V^\star(\Pi)
        &= O\br{
        \frac{\cvgd^2 A^2 H^{7} \sqrt{\log\frac{ n \cC(\Pi)}{\delta}}}{ n^{2/15}}
        + \cvgd H^3 \sqrt A K^{1/6}\sqrt{\epserm}
        + \epsvgd}
        \\
        &= O\br{
        \frac{\cvgd^2 A^2 H^{7} \sqrt{\log\frac{ n \cC(\Pi)}{\delta}}}{ n^{2/15}}
        + \cvgd H^3 \sqrt A n^{1/30}\sqrt{\epserm}
        + \epsvgd},
    \end{align*}
    with 
   	\begin{aligni*}
    	\epsnet 
    	= \Omega\br{\tfrac{1}{ \log(KN/\delta) \sqrt{ N} }}
    	= \Omega\br{\tfrac{ 1}{ \log(n/\delta) \sqrt{ N}}}
    	= \Omega\br{\tfrac{ 1}{ \log(n/\delta) n^{2/5} }}
    	.
    \end{aligni*}
\end{proof}

\subsection{CPI and DA-CPI}
\label{sec:sc_cpi_da_cpi}
In this section we present the learning versions of CPI (\cref{alg:sc_cpi}) and DA-CPI (\cref{alg:sc_da_cpi}) and their sample complexity guarantees.
We first state two lemmas which play the same role of \cref{lem:update_steps_ge}. The proofs follow from identical arguments as those of \cref{lem:update_steps_ge}, and are thus omitted.
\begin{algorithm}[ht!]
    \caption{CPI in the learning setup} 
    \label{alg:sc_cpi}
	\begin{algorithmic}
	    \STATE \textbf{input:} Initial policy $\pi^1\in\Pi$, 
	    $\cbr{\eta_k}_{k=1}^K, N\geq 1, \epserm>0$
           \FOR{$k=1,2, \ldots,K$}
           \STATE Rollout $\pi^k$ for $N$ episodes via \cref{alg:sampler}, obtain $\cD_k = \cbr{s_i^k, \widehat Q_{s_i^k}^k}_{i=1}^N$.
           \STATE Update
           \begin{aligni*}
                \tilde \pi^{k+1}
                \gets 
                \argmineps[\epserm]_{\pi\in \Pi}
                \cbr{
                	\widehat \Phi_k(\pi)
                	\eqq \frac1N \sum_{s\in \cD_k}
                	\abr{H \widehat Q^{k}_{s}, \pi_s - \pi^k_s} 
                }
           \end{aligni*}
			\STATE Set
                $\pi^{k+1}  = (1-\eta_k) \pi^k + \eta_k \tilde \pi^{k+1}$
            \ENDFOR
            \RETURN $\hat \pi = \pi^{K+1}$
	\end{algorithmic}
\end{algorithm}

\begin{algorithm}[ht!]
    \caption{DA-CPI in the learning setup} 
    \label{alg:sc_da_cpi}
	\begin{algorithmic}
	    \STATE \textbf{input:} $
	    	\eta_1, \ldots, \eta_K > 0
	    $; $N \geq 1, \epsexpl>0$, $\epserm>0$, action norm $\norm{\cdot}_\circ$.
            \FOR{$k=1, \ldots, K$}
            \STATE Rollout $\pi^k$ for $N$ episodes via \cref{alg:sampler}, obtain $\cD_k = \cbr{s_i^k, \widehat Q_{s_i^k}^k}_{i=1}^N$.
           \STATE Update
           \begin{aligni*}
                \tilde \pi^{k+1}
                \gets 
                \argmineps[\epserm]_{\pi\in \Pi^\epsexpl}\cbr{
                \widehat \Phi_k(\pi) \eqq
                \frac1N \sum_{s \in \cD_k} {
                    \abr{\widehat Q^{k}_{s}, \pi_s} 
                }}
           \end{aligni*}
           \STATE Rollout $\pi^k$ for another $N$ episodes via \cref{alg:sampler}, obtain $\widetilde \cD_k$.
                \STATE Update
                $\pi^{k+1} \gets 
                \argmineps[\epserm]_{\pi\in \Pi^\epsexpl} \cbr{
                    \widehat \psi_k(\pi) \eqq \frac1N \sum_{s \in \widetilde \cD_k}
                    \norm{\pi_s - ((1-\eta_k) \pi^k_s + \eta_k \tilde \pi^{k+1}_s)}_\circ^2)
                }
                $
            \ENDFOR
            \RETURN $\hat \pi = \pi^{K+1}$
	\end{algorithmic}
\end{algorithm}

\begin{lemma}\label{lem:update_steps_ge_cpi}
    For $\gamma\leq 1/2$, upon execution of \cref{alg:sc_cpi}, 
    for any $\delta>0$, 
    w.p.~$\geq 1-\delta$, it holds that for all $k\in [K]$,
    \begin{align*}
        \tilde \pi^{k+1}
        &\in 
        \argmineps_{\pi\in \Pi}{
        \E_{s\sim \mu^k}\sbr{
        \abr{H Q^k_s, \pi_s - \pi^k_s}
        }},
    \end{align*}
    where $\epserr = \epserm + \epsgen$,
    \begin{aligni*}
        \epsgen \eqq \cgen A H^2 D\sqrt{
            \frac{\log\frac{KN\cN(\epsnet, \widetilde \Pi, \norm{\cdot}_{\infty, 1})}{\delta}}{ N}
        },
    \end{aligni*}
    $\cgen>0$ is an absolute numerical constant, 
    and 
    $\epsnet \geq 
    \frac{\cgen }{6 \sqrt{ N} (\log(2 KN/\delta)}$. Furthermore, the number of time steps of each episode rolled out by \cref{alg:sampler} is $\leq 2 H \log\br{2 K N/\delta} $.
\end{lemma}


\begin{lemma}\label{lem:update_steps_ge_da_cpi}
	For $\gamma\leq 1/2$, 
    upon execution of \cref{alg:sc_da_cpi}, 
    for any $\delta>0$, 
    w.p.~$\geq 1-\delta$, it holds that for all $k\in [K]$,
    \begin{align*}
        \tilde \pi^{k+1}
        &\in 
        \argmineps_{\pi\in  \Pi^\epsexpl}{
        \E_{s\sim \mu^k}\sbr{
        \abr{H Q^k_s, \pi_s - \pi^k_s}
        }}
        \\
        \pi^{k+1} &\in  
                \argmineps_{\pi\in \Pi^\epsexpl} 
                    \E_{s \sim \mu^k} 
                    \norm{\pi_s - ((1-\eta_k) \pi^k_s + \eta_k \tilde \pi^{k+1}_s)}_1^2
       ,
    \end{align*}
    where $\epserr = \epserm + \epsgen$,
    \begin{aligni*}
        \epsgen \eqq \cgen A H^2 D\sqrt{
            \frac{\log\frac{KN\cN(\epsnet, \widetilde \Pi, \norm{\cdot}_{\infty, 1})}{\delta}}{ N}
        },
    \end{aligni*}
    $\cgen>0$ is an absolute numerical constant, 
    and 
    $\epsnet \geq 
    \frac{\cgen }{6 \sqrt{ N} (\log(2 KN/\delta)}$. Furthermore, the number of time steps of each episode rolled out by \cref{alg:sampler} is $\leq 2 H \log\br{2 K N/\delta} $.
\end{lemma}

We now give the sample complexity guarantees of CPI and DA-CPI; for simplicity, we present the bounds assuming $\epserm=0$.
\begin{theorem}
	Let $\Pi$ be a policy class that satisfies $(\cvgd, \epsvgd)$-VGD w.r.t.~$\cM$, and assume $\gamma \leq 1/2$.
	Then for any $n\geq 1$, 
	there exists a choice of parameters $K, N, \cbr{\eta_k}$ such that
 \cref{alg:sc_cpi} executed with $\epserm=0$ and the $L^1$ action norm, guarantees for any $\delta>0$, that w.p.~$\geq 1-\delta$ the total number of environment time steps $\leq n$, and the output policy satisfies 
	\begin{align*}
        V(\hat \pi) - V^\star(\Pi)
        &= O\br{\frac{\cvgd^2 A H^4 \log(n\cC(\Pi)/\delta)}{n^{1/3}}
        + \epsvgd},
    \end{align*}
    where  $\cC(\Pi) \eqq \cN(\epsnet, \Pi, \norm{\cdot}_{\infty, 1})$ is the $\epsnet$-covering number of $\Pi$
    and $\epsnet = \Omega\br{\tfrac{ 1}{ \log(n/\delta) n}}$
    	.
\end{theorem}
\begin{proof}
	By \cref{lem:update_steps_ge_cpi},
	we have that w.p.~$\geq 1-\delta$, for all $k\in [K]$ it holds that:
	\begin{align*}
        \pi^{k+1}
        \in 
        \argmineps_{\pi\in \Pi}\cbr{
        \Phi_k(\pi) \eqq
        \E_{s\sim \mu^k}\sbr{
        \abr{H Q^k_s, \pi_s - \pi^k_s}
        }
        },
    \end{align*}
    with $\epserr = \epserm + \epsgen$, where
    \begin{align*}
        \epsgen =O\br{ A H^2\sqrt{
            \frac{\log\frac{ K N \cC(\Pi)}{\delta}}{ N}
        }},
    \end{align*}
	$\cC(\Pi) \eqq \cN(\epsnet, \Pi, \norm{\cdot}_{\infty, 1})$,
    and 
    \begin{aligni*}
    	\epsnet 
    	= \Omega(\tfrac{ 1}{ \log(KN/\delta) \sqrt{ N} }).
    \end{aligni*}
    Hence, \cref{alg:sc_cpi} is an instance of the idealized CPI \cref{alg:cpi} with the error $\epserr$ defined above.
    Now, by \cref{thm:cpi}, we have that
    \begin{align*}
    	V(\hat \pi) - V^\star(\Pi)
    	&= O\br{
    	\frac{\cvgd^2 H^3}{K} + \cvgd\varepsilon
        + \epsvgd
    	}
    	\\
    	&= O\br{
    	\frac{\cvgd^2 H^3}{K} + \cvgd A H^2\sqrt{
            \frac{\log\frac{ K N \cC(\Pi)}{\delta}}{ N}
        }
        + \epsvgd
    	}.
    \end{align*}
	Choosing $N = K^2$, and noting that $n\lesssim N^{3/2} H \log(n/\delta)$, we obtain
	\begin{align*}
    	V(\hat \pi) - V^\star(\Pi)
    	&= O\br{
    	\frac{\cvgd^2 A H^4 \log(n\cC(\Pi)/\delta)}{n^{1/3}}
        + \epsvgd
    	},
    \end{align*}
	which completes the proof.
\end{proof}




\begin{theorem}
	Let $\Pi$ be a policy class that satisfies $(\cvgd, \epsvgd)$-VGD w.r.t.~$\cM$, and assume $\gamma \leq 1/2$.
	Then for any $n\geq 1$, 
	there exists a choice of parameters $K, N, \epsexpl, \cbr{\eta_k}$ such that
 \cref{alg:sc_da_cpi} executed with with $\epserm=0$ and the $L^1$ action norm, guarantees for any $\delta>0$, that w.p.~$\geq 1-\delta$ the total number of environment time steps $\leq n$, and the output policy satisfies 
	\begin{align*}
        V(\hat \pi) - V^\star(\Pi)
        &= O\br{
			\frac{ \cvgd^2 A^2H^5 \sqrt{\log(n\cC(\Pi)/\delta)}}{n^{2/15} } 
        +\epsvgd
        },
    \end{align*}
    where  $\cC(\Pi) \eqq \cN(\epsnet, \Pi, \norm{\cdot}_{\infty, 1})$ is the $\epsnet$-covering number of $\Pi$
    and $\epsnet = \Omega\br{\tfrac{ 1}{ \log(n/\delta) n}}$
    	.
\end{theorem}
\begin{proof}
	By \cref{lem:update_steps_ge_da_cpi},
	we have that w.p.~$\geq 1-\delta$, sub-optimality $\epserr$ holds for all $k\in [K]$ and for both update steps
	with $\epserr = \epserm + \epsgen$, where
    \begin{align*}
        \epsgen =O\br{ A H^2\sqrt{
            \frac{\log\frac{ K N \cC(\Pi)}{\delta}}{ N}
        }},
    \end{align*}
	$\cC(\Pi) \eqq \cN(\epsnet, \Pi, \norm{\cdot}_{\infty, 1})$,
    and 
    \begin{aligni*}
    	\epsnet 
    	= \Omega(\tfrac{ 1}{ \log(KN/\delta) \sqrt{ N} }).
    \end{aligni*}
    Hence, \cref{alg:sc_da_cpi} is an instance of the idealized DA-CPI \cref{alg:cpi} with the error $\epserr$ defined above.
    Now, by \cref{thm:cpi}, we have that
    \begin{align*}
        V(\hat \pi) - V^\star(\Pi)
        &= O\br{\cvgd^2 AH^3\br{
	   \frac{1}{K^{2/3}} 
            + \varepsilon^{1/3}
    	+ \varepsilon^{2/3}  K^{2/3}}
    	+\epsvgd
        }
    .
    \end{align*}
    We focus on the first two terms; when balancing them, the third will be of the same order.
    Let $\iota\eqq\sqrt{\log(KN\cC(\Pi)/\delta)}$, and we have:
    \begin{align*}
	   \frac{1}{K^{2/3}} 
            + \varepsilon^{1/3}
       &\lesssim 
       \frac{1}{K^{2/3}} 
            + \frac{(AH^2\iota)^{1/3}}{N^{1/6}}
       \\
       &\lesssim 
       \frac{(AH^2\iota)^{1/3}}{K^{2/3}} \tag{$N=K^4$}
       \\
       &\lesssim 
       \frac{AH^2 \iota}{n^{2/15}} \tag{$n\lesssim K^5 H \log(KN/\delta)$}.
    \end{align*}
    This implies
    \begin{align*}
        V(\hat \pi) - V^\star(\Pi)
        &= O\br{\frac{ \cvgd^2 A^2H^5 \iota}{n^{2/15} } 
        +\epsvgd
        }
    ,
    \end{align*}
	which completes the proof.
\end{proof}


\subsection{PMD}
\label{sec:sc_pmd}
PMD in the learning setup is given in \cref{alg:sc_pmd}.
Since $L^2$-PMD and $L^2$-SDPO coincide (they are the exact same algorithm),
the sample complexity of PMD with the Euclidean action regularizer follows form arguments identical to those given for SDPO in the proof of \cref{thm:sc_sdpo}, but with the $L^2$-action norm instead of the $L^1$-norm. This leads to slightly worse dependence on the action set cardinality $A$, but otherwise to the same guarantee.
\begin{theorem}\label{thm:sc_pmd}
	Let $\Pi$ be a convex policy class that satisfies $(\cvgd, \epsvgd)$-VGD w.r.t.~$\cM$, and assume $\gamma \leq 1/2$.
	Then for any $n\geq 1$, 
	there exists a choice of parameters $K, N, \eta, \epsexpl$ such that
 \cref{alg:sc_pmd} executed with $\epserm=0$ and the $L^2$ action regularizer guarantees for any $\delta>0$, that w.p.~$\geq 1-\delta$ the total number of environment time steps $\leq n$, and the output policy satisfies 
	\begin{align*}
        V(\hat \pi) - V^\star(\Pi)
        &= O\br{
        \frac{\cvgd^2 A^3 H^{7} \sqrt{\log\frac{ n \cC(\Pi)}{\delta}}}{ n^{2/15}}
        + \epsvgd},
    \end{align*}
    where  $\cC(\Pi) \eqq \cN(\epsnet, \Pi, \norm{\cdot}_{\infty, 1})$ is the $\epsnet$-covering number of $\Pi$
    and 
   	\begin{aligni*}
    	\epsnet 
    	= \Omega\br{\tfrac{ 1}{ \log(n/\delta) n }}
    	.
    \end{aligni*}
\end{theorem}
Notably, the analysis of $L^2$-PMD through the SDPO perspective gives better sample complexity than we would have obtained through the Bregman-proximal method analysis \cref{thm:breg_prox}; roughly speaking this is the case because analysis based on the Bregman divergence hinges on approximate optimality conditions rather than sub-optimality in function values. This leads to dependence of $\epsgen^{1/4}$ rather than $\sqrt \epsgen$, which further leads to inferior sample complexity.
For action regularizers other than $L^2$, sample complexity of PMD may be derived again using similar arguments to those of \cref{thm:sc_sdpo} but now combined with \cref{thm:breg_prox}. A little more care is needed in the choice of parameters, as smoothness of the action regularizer (needed both in \cref{thm:breg_prox} and in \cref{lem:update_steps_ge}) is commonly inversely related to $\epsexpl$. As a result, with the currently known techniques for the iteration complexity upper bound, the sample complexity upper bounds for essentially any action regularizer other than $L^2$, will be worse than those of the $L^2$ case w.r.t.~dependence on both $n$ and $A$.

\begin{algorithm}[tb]
   \caption{PMD in the learning setup}
   \label{alg:sc_pmd}
\begin{algorithmic}
   \STATE {\bfseries Input:} 
   $K\geq 1, N\geq 1, \eta > 0, \epsexpl >0, \epserm>0, \Pi\in \Delta(\cA)^\cS$, and action regularizer $R \colon\R^\cA \to \R$.
   \STATE Initialize $\pi^1 \in \Pi^\epsexpl$
   \FOR{$k=1$ {\bfseries to} $K$}
   \STATE Rollout $\pi^k$ for $N$ episodes via \cref{alg:sampler}, obtain $\cD_k = \cbr{s_i^k, \widehat Q_{s_i^k}^k}_{i=1}^N$.
   \STATE Update
   \begin{aligni*}
        \pi^{k+1}
        \gets 
        \argmineps[\epserm]_{\pi\in \Pi^\epsexpl}\cbr{
        \widehat \Phi_k(\pi) \eqq
        \frac1N \sum_{s \in \cD_k} {
            \abr{H \widehat Q^{k}_{s}, \pi_s} 
            + \frac1{\eta} B_R{\pi_s, \pi_s^k}
        }}
   \end{aligni*}
   \ENDFOR
   \RETURN $\hat \pi \eqq \pi^{K+1}$
\end{algorithmic}
\end{algorithm}




