\subsection[Proof of good event lemma]{Proof of \cref{lem:update_steps_ge}}
\label{sec:update_steps_ge_proof}
\begin{lemma}\label{lem:sampler}
    \cref{alg:sampler}
    returns $s_t, \widehat Q^\pi_{s_t}$ that satisfy
    (i) $s_t\sim \mu^\pi$; 
    (ii) $\E \sbr[b]{ \widehat Q^\pi_{s_t} \mid s_t} = Q^\pi_{s_t}$.
    Furthermore, for any $\delta>0$, w.p.~$\geq 1-\delta$, 
    the algorithm terminates after no more than $\frac{2}{1-\gamma}\log \frac2{\delta}$ time steps and it holds that
    \begin{aligni*}
    \av{\widehat Q^\pi_{s_t, a_t}} \leq HA\log(2/\delta).
    \end{aligni*}
    % \begin{aligni*}
    % \E_{a \sim \pi_{s_t}}\norm[b]{\widehat Q^\pi_{s_t}}^2_1 \leq \fraci{\br{H\log(1/\delta)}^2}{\pi_{s_t, a_t}}
    % \end{aligni*}
\end{lemma}
\begin{proof}[Proof of \cref{lem:sampler}]
	First, note that (i) follows directly from the definition of the discounted occupancy measure \cref{def:occmeas_rho0}. 
    Indeed, by definition of \cref{alg:sampler}, for any $s\in \cS$:
    \begin{align*}
        \Pr(s \text{ is accepted by \cref{alg:sampler} on step } t)
        &= \gamma^{t}(1-\gamma)\Pr(s_t = s \mid \pi, s_0\sim \rho_0)
        \\
        \implies
        \Pr(s \text{ is accepted by \cref{alg:sampler}})
        &= (1-\gamma)\sum_{t=0}^\infty\gamma^{t}
        \Pr(s_t = s \mid \pi, s_0\sim \rho_0)
        =\mu^\pi(s).
    \end{align*}
    Further, let $\mathbf {alg}$ denote \cref{alg:sampler}, and then 
    \begin{align*}
    \E_{\mathbf {alg}}\sbr{\widehat Q^\pi_{s_t, a_t} \mid s_t, a_t}
    &= 
    A\E_{\mathbf {alg}}\sbr{\sum_{t'=t}^T r(s_{t'}, a_{t'}) \mid s_t, a_t}
    \\
    &= A\sum_{t'=t}^\infty\gamma^{t-t'} 
    \E_\pi \sbr{r(s_{t'}, a_{t'}) \mid s_t, a_t}
    \\
    &= A\sum_{t'=t}^\infty\gamma^{t-t'} 
    \E_\pi \sbr{r(x_h, u_h) \mid x_0=s_t, u_0=a_t},
    \end{align*}
    where in the last expression, expectation is w.r.t.~$x_{h+1}\sim \P(\cdot|x_h, u_h)$ for $h\geq1$, and $u_h \sim \pi(\cdot|x_h)$ for $h\geq 2$.
    Now,
    \begin{align*}
        \sum_{t'=t}^\infty\gamma^{t-t'} 
    \E_\pi \sbr{r(x_h, u_h) \mid x_0=s_t, u_0=a_t}
    &=\sum_{h=0}^\infty\gamma^{h} 
    \E_\pi \sbr{r(x_h, u_h) \mid x_0=s_t, u_0=a_t}
    \\
    &=\E_\pi \sbr{\sum_{h=0}^\infty\gamma^{h} 
        r(x_h, u_h) \mid x_0=s_t, u_0=a_t}
    \\
    &= Q_{s_t, a_t}^\pi,
    \end{align*}
    hence for all $a\in \cA$,
    \begin{align*}
    \E_{\mathbf {alg}}\sbr{\widehat Q^\pi_{s_t, a} \mid s_t}
    =
    \Pr(a_t = a)\E_{\mathbf {alg}}\sbr{\widehat Q^\pi_{s_t, a_t} \mid s_t, a_t=a}
    = \Pr(a_t = a) A Q_{s_t, a}^\pi
    =
    Q_{s_t, a}^\pi,
    \end{align*}
    which proves (ii).

	For the second part, observe that the
    acceptance event occurs w.p.$1-\gamma$ at each time step, therefore the probability for acceptance to not occur in the first $t$ times steps is $\gamma^t$, and hence probability of acceptance by time $t$ is $1-\gamma^t$. 
    We have $\gamma^t \leq e^{-(1-\gamma)t}\leq \delta$
    for $t\geq \frac{1}{1-\gamma}\log \frac1\delta$,
    hence, w.p.~$\geq 1-\delta/2$ acceptance occurs before time step $t_\delta \eqq \frac{1}{1-\gamma}\log \frac2{\delta}$.
    Same goes for the termination event, hence, the episode terminates after $2t_\delta$ time steps w.p. $\geq 1-\delta$.

	Finally, the bound on $\av[b]{\widehat Q^\pi_{s_t, a_t}}$ follows from the termination event and definition of $\widehat Q^\pi_{s_t, a_t}$ in the algorithm.
\end{proof}
Our proof makes use of the notion of sub-exponential norm \citep{vershynin2018high} of a random variable $X$:
\begin{align}
	\norm{X}_{\psi_1} \eqq \inf\cbr{\alpha > 0 : \E e^{|X|/\alpha}\leq 2}.
\end{align}

\begin{lemma}\label{lem:geom_subexp}
Assume $T$ is a geometric random variable, $T \sim {\rm Geom(p})$, i.e., $\Pr(T = t) = (1-p)^{t-1}p$ for $1\leq t\in \N$.
Then, for $q\eqq\max\cbr{p, 1-p}$:
$$
\norm{T}_{\psi_1}\leq 1/\ln\br{1+\tfrac{1-q}{4q}}.
$$	
\end{lemma}
\begin{proof}
	We have:
\begin{align*}
	\E e^{T/\alpha}
	&= \sum_{t=1}^\infty (1-p)^{t-1}p e^{t/\alpha}
	\\
	&= pe^{1/\alpha}\sum_{t=1}^\infty (1-p)^{t-1} e^{(t-1)/\alpha}
	\\
	&= pe^{1/\alpha}\sum_{t=0}^\infty \br{(1-p)e^{1/\alpha}}^t
\end{align*}
Let $q\eqq\max\cbr{p, 1-p}$, and set
$\alpha=1/\ln\br{1+\tfrac{1-q}{4q}}$, then,
\begin{align*}
	e^{1/\alpha} = 1+\frac{1-q}{4q}.
\end{align*}
Now,
\begin{align*}
	(1-p)e^{1/\alpha}
	= 1-p+(1-p)\frac{1-q}{4q}
	\leq 1-p+\frac{1-q}{4}
	\leq 1-p+\frac{p}{4},
\end{align*}
hence
\begin{align*}
	\sum_{t=0}^\infty \br{(1-p)e^{1/\alpha}}^t
	\leq \frac{1}{1-\br{1-p+\frac{p}{4}}}
	= \frac{4}{3 p}.
\end{align*}
Combining with our previous derivation, we obtain
\begin{align*}
	\E e^{T/\alpha}
	&\leq pe^{1/\alpha}\frac{4}{3 p}
	=\frac43\br{1+\frac{1-q}{4q}}
	\leq \frac43\br{1+\frac{1}{4}}
	=\frac53 \leq 2.
\end{align*}
\end{proof}

\begin{lemma}\label{lem:subexp_concentration}
	Assume $X$ is a random variable that satisfies $\norm{X}_{\psi_1}\leq R$. Then for $N$ independent samples of $X_1, \ldots, X_N$, we have for any $\epsilon\leq R$:
\begin{align*}
	\Pr\br{\av{\frac{1}{N}\sum_{i=1}^N T_i - \E T }\geq \epsilon}
	&\leq2e^{-c \frac{N \epsilon^2}{R^2} },
\end{align*}
where $c>0$ is an absolute numerical constant.
\end{lemma}
Centering only costs an absolute constant factor \citep{vershynin2018high}, thus
$\norm{X-\E x}_{\psi_1} \leq \tilde R$
for $\tilde R= c_0 R$. Now, the Bernstein inequality for sums of independent sub-exponential random variables (Theorem 2.8.1 of \citealp{vershynin2018high}) yields:
\begin{align*}
	\Pr\br{\av{\frac{1}{N}\sum_{i=1}^N X_i - \E X }\geq \epsilon}
	&\leq 
	2\exp\sbr{-c_1\min\br{
		\frac{N^2\epsilon^2}{N \tilde R^2}, \frac{N \epsilon}{\tilde R}}
	}
	\\
	&=2\exp\sbr{-c_1 N \min\br{
		\frac{\epsilon^2}{ \tilde R^2}, \frac{ \epsilon}{\tilde R}}
	}
	\\
	&=2\exp\sbr{-(c_1/c_0) \frac{\epsilon^2 N }{ R^2}}
\end{align*}
where we use the assumption that $\epsilon\leq R \leq \tilde R$.


\begin{lemma}[Empirical objective concentration]
\label{lem:phi_k_conc}
	For a given fixed $k$ and a given fixed policy $\pi$, 
	we have that for any $\delta'>0$, w.p.~$\geq1-\delta'$ it holds that:
    \begin{align*}
        \av{\Phi_k(\pi) - \widehat \Phi_k(\pi)}
        \leq \frac{C A H^2 D}{\eta}\sqrt{
        \frac{ \log\frac{2}{\delta'}}{N}
        }
        ,
    \end{align*}
    where $C>0$ is a universal numerical constant and $\Phi_k, \widehat \Phi_k$ are defined in \cref{eq:concentration_hat_phi_k,eq:concentration_phi_k} of \cref{lem:sampler}.
\end{lemma}
\begin{proof}
    Denote:
    \begin{align*}
        \hat \ell^k(\pi; s) \eqq 
            H\abr[b]{\widehat Q^k_s, \pi_s} + \frac1{\eta}\Div\br{\pi_s, \pi^k_s},
    \end{align*}
    and note that by \cref{lem:sampler}, we have
    \begin{align*}
        \Phi_k(\pi) = 
        \E_{(s, \widehat Q_s^k) \sim {\rm sampler}(\pi^k)}
        \sbr{
            \hat \ell^k(\pi; s)
        },
    \end{align*}
    where ``${\rm sampler}$'' denotes \cref{alg:sampler}.
    Now, for $(s, \widehat Q_s^k) \sim {\rm sampler}(\pi^k)$, we consider the RV
    $$
    X = \abr{\widehat Q^k_s, \pi_s} + \frac1\eta \Div(\pi_s, \pi^k_s).
    $$
    The divergence term is bounded by $D/\eta$, hence $\norm{\frac1\eta \Div(\pi_s, \pi^k_s)}_{\psi_1}\leq D/\eta$ follows immediately.
    Further, the RV $\frac1A\widehat Q_{s, a}^k$ for the action $a$ accepted in \cref{alg:sampler} is dominated by a geometric RV $T\sim {\rm Geom(p=1-\gamma)}$, therefore $\norm{H \widehat Q_{s, a}^k}_{\psi_1}
    	\leq H A \norm{T}_{\psi_1}$.
    By \cref{lem:geom_subexp} and our assumption that $\gamma \leq 1/2$,
    \begin{align*}
    	\norm{T}_{\psi_1} \leq \frac1{\ln\br{1+\tfrac{1-\gamma}{4\gamma}}}
    	\leq \frac1{\tfrac{1-\gamma}{8\gamma}}
    	\leq \frac{8}{1-\gamma} = 8 H.
    \end{align*}
	Now, again using that $\norm{\cdot}_{\psi_1}$ is a norm, we obtain:
	\begin{align*}
			\norm{H\abr{\widehat Q^k_s, \pi_s } + \frac1\eta\Div(\pi_s, \pi^k_s)}_{\psi_1}
			\leq D/\eta + 8H^2A.
	\end{align*}
	Now, by \cref{lem:subexp_concentration}, we have
	\begin{align*}
        \Pr\br{\av{\widehat \Phi_k(\pi)
        - \Phi_k(\pi)}\geq \epsilon}
        \leq 
        2 e^{- c' \frac{N \epsilon^2}{A^2 H^4 + D^2/\eta^2}}
        \leq
        2 e^{- c' \frac{N \epsilon^2 \eta^2}{ A^2 H^4 D^2}}.
    \end{align*}
    for an appropriate universal constant $c'$.
    Letting $\delta=2 e^{- c' \frac{N \epsilon^2 \eta^2}{ A^2 H^4 D^2}}$, the result follows.
