\end{proof}
We are now ready for the proof of \cref{lem:update_steps_ge}.
\begin{proof}[Proof of \cref{lem:update_steps_ge}]
    Consider the ``good event'' described next.
    Let $\delta > 0$ and denote
    \begin{align*}
        \widetilde H &\eqq  H\log(2 K N/\delta),
        \\
        \epsnet &\eqq \frac{C AH^2D}{\sqrt{ N} (A \widetilde H H  + L/\eta)},
    \end{align*}
    where $C$ is specified by \cref{lem:phi_k_conc}.
    Further, let ${\rm Net}(\epsnet, \widetilde \Pi) \eqq {\rm Net}(\epsnet, \widetilde \Pi, \norm{\cdot}_{\infty, 1})$ be an $\epsnet$-cover of $\widetilde \Pi$ w.r.t.~$\norm{\cdot}_{\infty, 1}$ of size $\cN(\epsnet, \widetilde \Pi) \eqq \cN(\epsnet, \widetilde \Pi, \norm{\cdot}_{\infty, 1})$.
    Consider the following events:
    \begin{enumerate}
        \item For all $k\in [K], i\in [N]:$ $\widehat Q^k_{s_i^k, a_i^k} 
        \leq \widetilde H A
        $, and the corresponding  episode length $\leq \widetilde H$
        \item For all $k\in [K]$:
        \begin{align*}
            \forall \pi\in {\rm Net}(\epsnet, \widetilde \Pi):
    	\quad 
        |\widehat \Phi_k(\pi) - \Phi_k(\pi)| 
        \leq \frac{C A H^2 D}{\eta} \sqrt{
            \frac{\log\frac{2KN\cN(\epsnet, \widetilde \Pi)}{\delta}}{ N}
        }
        \end{align*}
    \end{enumerate}
    By \cref{lem:sampler} and the union bound, event (1) holds w.p.~$\geq1-\delta/2$, and by \cref{lem:phi_k_conc} and the union bound, event (2) holds w.p.~$\geq 1-\delta/2$.
    Hence, the good event holds w.p.~$\geq 1-\delta$.
	%
    Proceeding, we assume the good event holds.
    We have that for any $\pi, \pi'$,
    \begin{align*}
        \av{\Phi_k(\pi) - \Phi_k(\pi')}
        &= \av{
        \E_{s\sim \mu^{\pi^k}}\sbr{
            H\abr[b]{Q^k_s, \pi_s - \pi_s'} 
            + \frac1{\eta}\br{
                \Div(\pi_s, \pi^k_s) - \Div(\pi_s', \pi^k_s)
            }
        }}
        \\
        &\leq \E_{s\sim \mu^k}\sbr{\br{H^2
        + L/\eta}\norm{\pi_s - \pi_s'}_1}
        \\
        &=
        \br{H^2 + L/\eta}\norm{\pi - \pi'}_{L^1(\mu^k),1}.
    \end{align*}
    By a similar argument, using the good event (1):
    \begin{align*}
        \av{\widehat \Phi_k(\pi) - \widehat \Phi_k(\pi')}
        &\leq 
        \br{A \widetilde H H  + L/\eta}\norm{\pi - \pi'}_{L^1(\mu^k),1}.
    \end{align*}
    Further,
    \begin{align*}
        \norm{\pi - \pi'}_{L^1(\mu^k),1}
        \leq 
        \norm{\pi - \pi'}_{\infty,1},
    \end{align*}
    hence, we have that for any $\pi\in \widetilde \Pi$, there exists $\pi'\in {\rm Net}(\epsgen, \widetilde \Pi)$ such that:
    \begin{align*}
        \av{\Phi_k(\pi) - \widehat \Phi_k(\pi)}
        &\leq 
        \av{\Phi_k(\pi) - \Phi_k(\pi')}
        +
        \av{\Phi_k(\pi') - \widehat \Phi_k(\pi')}
        +
        \av{\widehat \Phi_k(\pi') - \widehat \Phi_k(\pi)}
        \\
        &\leq 
        \frac{C A H^2 D}{ \sqrt{ N}}
        +
        \av{\Phi_k(\pi') - \widehat \Phi_k(\pi')}
        +
        \frac{C A H^2 D}{ \sqrt{ N}}
        \\
        &\leq 
        \frac{3 C A H^2 D}{\eta} \sqrt{
            \frac{\log\frac{2KN\cN(\epsilon, \widetilde \Pi)}{\delta}}{ N}
        }=:
        \epsgen/2.
    \end{align*}
    Now, let 
    $\hat \pi_\star^{k+1}=\argmin_{\pi\in \widetilde \Pi}\widehat \Phi_k(\pi)$ and 
    $\pi_\star^{k+1}=\argmin_{\pi\in \widetilde \Pi}\Phi_k(\pi)$, then we have:
    \begin{align*}
        \Phi_k(\pi^{k+1})
        &\leq \widehat \Phi_k(\pi^{k+1}) + \epsgen/2
        \\
        &\leq \widehat \Phi_k(\hat \pi^{k+1}_\star) + \epsgen/2
        + \epserm
        \\
        &\leq \widehat \Phi_k(\pi^{k+1}_\star) + \epsgen/2
        + \epserm
        \\
        &\leq \Phi_k(\pi^{k+1}_\star) + \epsgen
        + \epserm
        \\
        &= \min_{\pi\in \widetilde \Pi}\Phi_k(\pi) + \epsgen
        + \epserm
        .
    \end{align*}
    This completes the proof.
\end{proof}




\section{Experiments implementation details}
\label{sec:vgd_experiments_details}
In this section, we provide further details on the experimental setup where we evaluate the VGD condition parameters. The pseudocode used for the experiments is give in \cref{alg:vgd_eval}.
The environments we tested on consider rewards and not cost functions, therefore the code and discussion below should be understood as having the negative reward as the cost function (we opt to maintain the cost formulation here to better align with our original setup). Additionally, the environments considered are finite-horizon and the objective is undiscounted.
\begin{algorithm}[t]
   \caption{Pseudocode for VGD parameter evaluation}
   \label{alg:vgd_eval}
\begin{algorithmic}
   \STATE Initialize two actor neural networks $\Pi_{\rm actor}, \Pi_{\rm vgd}$
   \STATE Initialize $\pi^1 \in \Pi_{\rm actor}$
   \FOR{$k=1$ {\bfseries to} $K$}
   \STATE {\color{gray} // Gradient estimation phase:}
   \STATE Rollout $\pi^k$ to collect $N$ environment timesteps $\cD^k=\cbr{s^k_i}_{i=1}^N$

   \FOR{$s\in \cD^k, a\in \cA$}
   \STATE Rollout $n_{\rm rep}$ episodes of $\pi^k$ starting from $s, a$.
   \STATE Set $\widehat Q_{s, a}^k \gets $ average of returns from the previous step.
   \ENDFOR
   \STATE {\color{gray} // (Note: we treat each state as if it were an independent sample from $\mu^k$, even though it is not.)}
   \STATE
   \STATE {\color{gray} // Update actor:}

   \STATE Train $\pi^{k+1}$ for $n_{\rm epochs}$ epochs, with $n_{\rm mbs}$ mini-batches in each epoch:
   \begin{align*}
        \pi^{k+1}
        \approx 
        \argmin_{\pi\in \Pi_{\rm actor}}
        \frac1N \sum_{s\in \cD^k}
            \abr{\widehat Q^{k}_{s}, \pi_s - \pi^k_s} 
            + \frac1{2\eta} \norm{\pi_s - \pi_s^k}_2^2
   \end{align*}

    \STATE {\color{gray} // Evaluate VGD:}

   \STATE Initialize $\tilde \pi^{k+1} \gets \pi^{k+1}$ 
   \STATE for $n_{\rm epochs}^{\rm vgd}$ epochs, with $n_{\rm mbs}^{\rm vgd}$ mini-batches in each epoch:
   \begin{align*}
        \tilde \pi^{k+1}
        \approx 
        \argmax_{\pi\in \Pi_{\rm vgd}}
        \frac1N \sum_{s\in \cD^k}
            \abr{\widehat Q^{k}_{s}, \pi^k_s - \pi_s} 
   \end{align*}
   \STATE Estimate $\widehat H^k$ the average episode length of $\pi^k$
   \STATE Report ${\rm Grad VGD}^k$ $= \frac1N \sum_{s\in \cD^k}
            \abr{\widehat H^k\widehat Q^{k}_{s}, 
                \pi^k_s  -\tilde \pi_s^{k+1}} 
                \eqqcolon \abr{\widehat \nabla V(\pi^k), 
                \pi^k  -\tilde \pi^{k+1}}$
   \ENDFOR
   \RETURN $\hat \pi \eqq \pi^{K+1}$
\end{algorithmic}
\end{algorithm}
\paragraph{Evaluating ``Sub Optimality'' at iteration $k$.}
For each (seed, environment) combination,
after the execution was concluded, we take the maximum value attained by the actor iterates, $\widehat V^\star = \min_{k\in K} \widehat V(\pi^k)$, where $\widehat V(\pi^k)$ is estimated using rollouts during experiment execution. We made sure to run the experiments for long enough (i.e., for large enough $K$) so that the algorithm converges.
Sub optimality of iteration $k$ is then given by $\widehat V(k) - \widehat V^\star$.


\paragraph{Evaluating ``VGD Ratio'' at iteration $k$; $\cvgd_k$.}
Given the sub-optimality evaluated as described in the previous paragraph, we report $\cvgd_k$ by computing the following:
\begin{align*}
    \cvgd_k \eqq
    \frac{\widehat V(\pi^k) - \widehat V^\star}
    {\abr{\widehat \nabla V(\pi^k), \pi^k - \tilde \pi^{k+1}}}
    .
\end{align*}


\paragraph{Local optima.}
As mentioned in \cref{sec:vgd_experiments}, local optima was only an issue (i.e., the case that $\widehat V^\star \neq V^\star(\Pi_{\rm actor})$) in the MinAtar environments. We note that our analysis holds just the same under the assumption the VGD condition is satisfied for $(\cvgd, 0)$ w.r.t.~a given target value $\widehat V^\star$ which is not necessarily the in-class optimal one. This may be interpreted as an execution specific value of $\epsvgd= \widehat V^\star -V^\star(\Pi_{\rm actor})$.
Thus, while the environments in question may not satisfy VGD globally, it seems convergence behavior may nonetheless be governed by the effective VGD parameters encountered during execution.

\paragraph{Hyperparameters.}
For the VGD actor, we used the AdamW optimizer with stepsize $5e-4$, $n_{\rm epochs}^{\rm vgd}=100, n_{\rm mbs}^{\rm vgd}=4$ accross all experiments.
Below, $N=N_{\rm envs}\times N_{\rm steps}$ means $N_{\rm steps}$ where executed in $N_{\rm envs}$ in parallel.
For the actor optimizer we used the Adam optimizer with step size $\eta_{\rm opt}$ (this is the step size of the ``inner'' optimization).
\begin{itemize}
    \item \textbf{Cartpole:}
    $K=40, N=4\times500, n_{\rm epochs}=100, n_{\rm mbs}=4, n_{\rm rep}=5, \eta_{\rm opt}=2e-4, \eta=0.01$.

    \item \textbf{Acrobot:}
    $K=100, N=8\times500, n_{\rm epochs}=100, n_{\rm mbs}=4, n_{\rm rep}=20, \eta_{\rm opt}=4e-4$ with linear annealing, $\eta=0.1$.

    \item \textbf{SpaceInvaders-MinAtar:}
    $K=600, N=16\times1000, n_{\rm epochs}=4, n_{\rm mbs}=8, n_{\rm rep}=5, \eta_{\rm opt}=5e-3$ with linear annealing, $\eta=0.1$.

    \item \textbf{Breakout-MinAtar:}
    $K=200, N=16\times1000, n_{\rm epochs}=100, n_{\rm mbs}=8, n_{\rm rep}=5, \eta_{\rm opt}=5e-3$ with linear annealing, $\eta=0.1$.

\end{itemize}
\paragraph{Additional comments.}
\begin{itemize}
    \item The architecture of both actor models is identical to that of the purejaxrl implementation \citep{lu2022discovered}.
    \item For Breakout-MinAtar and SpaceInvaders-MinAtar, execution took approximately 90-120 minutes per seed, on an NVIDIA-RTX-A5000 GPU.
    The experiments for Cartpole and Acrobot were run on similar hardware and took under 20 minutes for all 10 seeds.
\end{itemize}


