\subsection{Analysis of  the frozen characteristics}
%-
Next, we examine the behaviour close to the 
frozen characteristics~${
	\lambda_1 \big(\rho,v,\HAR(\rho)\big)
}$. To this end, the relaxation is stated with respect to the non-conservative form~\eqref{PiuS1}, which yields the following results in terms of viscosity solutions~\cite{Crandall1983,Caselles1992}. 

\medskip

\begin{theorem}\label{TheoremAwRascle2}
	Let an equilibrium~$
	\HAR(\rho)
	$ 
	be given and assume the function~$q$ is three-times differentiable in a small neighbourhood around~$\HAR(\rho)$. 
	Then, the first-order correction to the local equilibrium approximation of the relaxation
	\begin{equation}\label{RelaxationHyperbolic}
		\begin{cases}
			\begin{aligned}
				\partial_t \rho + \partial_x(\rho v)&=0,\\
				\partial_t v+ \Big(v-q'(h)\h'(\rho)\rho\Big)\partial_x v
				&= 0, \\
				\partial_t
				\Big( h-\h(\rho) \Big) 
				+
				v
				\partial_x
				\Big( h-\h(\rho) \Big)
				&=-
				\frac{\HAR(\rho)-h}{\varepsilon}
			\end{aligned}
		\end{cases}
	\end{equation}
	reads as
	\begin{equation*}
		\begin{cases}
			\begin{aligned}
				\partial_t \rho + \partial_x(\rho v)&=0,\\
				%-
				\partial_t v +
				\Big(
				v-q'\big(\HAR(\rho)\big)\h'(\rho)\rho
				\Big)	\partial_x v
				&=
-				\varepsilon
\rho \gamma(\rho)
(\partial_x v)^2
				+\mathcal{O}\big(\varepsilon^2\big)	\end{aligned}
		\end{cases}
	\end{equation*}
for 
$
	\gamma(\rho)\coloneqq
	q''\big(
	\HAR(\rho)
	\big)
	\h'(\rho)
	\rho
	\big(\HAR'(\rho)-\h'(\rho) \big).
$  
	In terms of viscosity solutions, it is equivalent to an hyperbolic system with eigenvalues
	\begin{align*}	
	\lambda_1^{\textup{HC}} (\rho,v) &= \Big(
	v-q'\big(\HAR(\rho)\big)\h'(\rho)\rho
	\Big)-\varepsilon 
    \gamma(\rho)
	\dot{\rho}, \\
	\lambda_2^{\textup{HC}}(\rho,v)
	&=v.
	\end{align*}




	%-
	%\begin{align*}
	%	0 &= \partial_t v + (v-h) \partial_x v
	%	=  
	%	\partial_t v +  \partial_x \left(
	%	\frac{v^2}{2}
	%	\right)
	%	-
	%	\partial_x(hv)
	%	+
	%	v\partial_x h 
	%	=
	%	\partial_t v +  \partial_x \left(
