	%	\right)
	%	- \frac{h-\HAR(\rho)}{\varepsilon}. 
	%\end{align*}		

\end{theorem}


\begin{proof}	
	We apply the Chapman-Enskog expansion~$h=\HAR(\rho)+\varepsilon h^{(1)}+\mathcal{O}\big(\varepsilon^2\big)$	to the third equation of system~\eqref{RelaxationHyperbolic}, which yields
	\begin{alignat*}{8}
		&	h^{(1)}
		&&=
		\partial_t
		&&\Big( \HAR(\rho)&&-\h(\rho) &&\Big) 
		+
		v
		\partial_x
		\Big( \HAR(\rho)-\h(\rho) \Big)
		&&+\mathcal{O}(\varepsilon) \\
		%-
		& &&=
		&&\Big(\HAR'(\rho)&&-\h'(\rho) &&\Big)
		\Big(
		\partial_t \rho + v \partial_x \rho
		\Big)	
		&&+\mathcal{O}(\varepsilon) \\
		%-
		& &&=-
		&&\Big(\HAR'(\rho)&&-\h'(\rho) &&\Big)
		\rho\, \partial_x v
		&&+\mathcal{O}(\varepsilon).
	\end{alignat*}
	Hence, we have the expansion~$h=\HAR(\rho)
	-
	\varepsilon \rho\big(\HAR'(\rho)-\h'(\rho) \big)
	\partial_x v+\mathcal{O}\big(\varepsilon^2\big)$.  Taylor's theorem states for some~$\xi\in\big(h,\HAR(\rho) \big)$ or~$\xi\in\big(\HAR(\rho), h\big)$, respectively, which implies the bound~$ (h-\xi)=\mathcal{O}(\varepsilon)
	$, 
	the approximation
	\begin{align*}
		q'(h)
		&=
		q'\big(\HAR(\rho))
		+
		\big(
		h-\HAR(\rho)
		\big)
		\Big[
		q''\big(
		\HAR(\rho)
		\big)
		+
		q^{(3)}(\xi) (h-\xi)
		\Big] \\
		&=
		q'\big(\HAR(\rho))
		-
		\varepsilon
		q''\big(\HAR(\rho)\big)
		\rho\big(\HAR'(\rho)-\h'(\rho) \big)
		\partial_x v
		+
		\mathcal{O}\big(\varepsilon^2\big).
	\end{align*}
	Then, the second equation of  system~\eqref{RelaxationHyperbolic} reads as
	\begin{align}
		0&=	\partial_t v + \Big(v-q'(h)\h'(\rho)\rho\Big)\partial_x v \label{HJ}\\
		&	=
		\partial_t v +
		\Big(
		v-
		q'\big(\HAR(\rho)\big)\h'(\rho)\rho
		\Big)	\partial_x v
		+
		\varepsilon
        \rho
        \gamma(\rho)(\partial_x v)^2
		+\mathcal{O}\big(\varepsilon^2\big).\nonumber
	\end{align}
	We introduce the auxiliary variables 
	$\alpha\coloneqq \partial_x v
    $ and
    $
	\beta(\rho)
	\coloneqq
	q'\big(
	\HAR(\rho)
    \big)
	\h'(\rho)\rho
	$. 
	Differentiating equation~\eqref{HJ} with respect to space~${x\in\mathbb{R}}$ yields
	\begin{equation}\label{HJ1}
\begin{aligned}
0&=		\partial_t \alpha +
		\Big(
		v-\beta(\rho)
		\Big)	\partial_x \alpha \\
& \quad		+
		\alpha\partial_x v- \alpha
		\beta'(\rho)\partial_x\rho
		+\varepsilon\Big(
		\alpha^2 \partial_\rho \big( \rho\gamma(\rho) \big)\partial_x \rho 
		+2\rho \gamma(\rho)\alpha \partial_x \alpha \Big)
        +
        \mathcal{O}\big(\varepsilon^2\big).
\end{aligned}
	\end{equation}
	Negleting terms of order $\mathcal{O}\big(\varepsilon^2\big)$, the continuity equation~$\partial_t \rho + \partial_x(\rho v) =0$, equation~\eqref{HJ} and~\eqref{HJ1} 
	form altogether the hyperbolic quasilinear form 
    $
    \partial_t \u + Q(\u) \partial_x \u=0 
    $ 
    with unknowns~$
    \u= (\rho,v,\alpha)^\T
    $ and matrix function
	$$
Q(\u)=
    	\begin{pmatrix}
		v & \rho & 0 \\
		0	& v-\beta(\rho) + \varepsilon \rho \alpha \gamma(\rho) & 0 \\
		-\alpha \beta'(\rho) 
		+
		\varepsilon
		\alpha^2 \partial_\rho \big( \rho\gamma(\rho) \big)
		& \alpha
		& v-\beta(\rho)+\varepsilon 2\rho \alpha \gamma(\rho)
	\end{pmatrix}.
	$$
	Its characteristic speeds read as
	$$
	\lambda_1^{\textup{HC}}(\rho,v) = \big(
	v-\beta(\rho)
	\big)+
	\varepsilon \rho \alpha \gamma(\rho), \ \
	\lambda_2^{\textup{HC}}(\rho,v)
	=v    
	\ \ \text{and}\ \  
	\widetilde{\lambda_3^{\textup{HC}}}(\rho,v) = \big(
	v-\beta(\rho)
	\big)+
	\varepsilon 2\rho \alpha \gamma(\rho).
	$$
	The claim follows from the relation~$\dot{\rho} = -\rho \alpha$. 

        \hfill	
\end{proof}

\medskip

\noindent
Theorem~\ref{TheoremAwRascle2} allows to properly choose functions~$\HAR(\rho)$, $\h(\rho)$ and $q(h)$ that account for different driver's  attitudes depending on de- and acceleration. Namely, the frozen characteristic~$\lambda_1\big(\rho,v,\HAR(\rho) \big) $ 
states how fast information travels backward as a function of the density. This speed depends in the TOM model also on acceleration and deacceleration as the relation
\begin{equation*}
	\lambda_1^{\textup{HC}}(\rho,v) = \lambda_1\big(\rho,v,\HAR(\rho) \big)
	-
	\varepsilon \gamma(\rho) \dot{\rho} 
\end{equation*} 
for 	$\gamma(\rho)
	= 
	q''\big(
	\HAR(\rho)
	\big)
	\h'(\rho)\rho
	\big(\HAR'(\rho)-\h'(\rho) \big)
$
shows. This allows to model the in the real world observable features
\begin{alignat*}{8}
	&\lambda_1^{\textup{HC}}(\rho,v)
	&&   \leq
	\lambda_1\big(\rho,v,\HAR(\rho) \big) 
	&&\quad \text{if drivers accelerate,}\\
	%-
	&\lambda_1^{\textup{HC}}(\rho,v)
	&&   \geq
	\lambda_1\big(\rho,v,\HAR(\rho) \big) 
	&&\quad \text{if drivers deaccelerate.}
\end{alignat*}
%-





\begin{remark}
	We note the similarity and the main difference between the proofs of Theorem~\ref{TheoremAwRascle1}
	and Theorem~\ref{TheoremAwRascle2}. 
	Starting from the relaxation to the third equation, we obtain expressions for the first-order Chapman-Enskog expansion in terms of
	\begin{alignat*}{8}
		&    h&&=\HAR(\rho)
		&&	-
		\varepsilon \rho\big(\HAR'(\rho)-\h'(\rho) \big)
		&&	\partial_x v
		&&+
		\mathcal{O}\big(\varepsilon^2\big),\\
		%-
		&	w&&=
		\WAR(\rho)
		&&	-
		\varepsilon
		\big[
		\WAR'(\rho)\rho-\WAR(\rho)
		\big]
		&&	\partial_x v\big(\rho,z,\WAR(\rho)\big)
		&&	+
		\mathcal{O}\big(\varepsilon^2\big).
	\end{alignat*}
	In fact, both expressions are equivalent up to second order although they are stated with respect to different variables. 
	Then, the Chapman-Enskog-type expansions are inserted into the second equation for the velocity. 
	Theorem~\ref{TheoremAwRascle2} is based on a non-conservative form of the second equation. This leads to a relaxation term that is of Hamilton-Jacobi-type. 
	In contrast, Theorem~\ref{TheoremAwRascle1} makes use of a conservative form which leads to an advection-diffusion equation. In this case, we obtain a similar result as in Section~\ref{sec:ARZ}, where the relaxation of the Aw-Rascle-Zhang model to the first-order LWR model is also related to an advection-diffusion equation. An explanation is given in~\cite{Herty:2020}, 
	where a Chapman-Enskog-type expansion is  inserted into  a conservative form, namely the continuity equation. 



\end{remark}





\subsection{Relaxation to a prescribed velocity of a multiclass system}
%-
We examine in this section the relation to traffic flow models of the type
\begin{equation}\label{FixedVelocity}
