	\begin{pmatrix}
		\rho \\ \rho \omegaTilde
	\end{pmatrix}
	+\partial_x
	\begin{pmatrix}
		\Vtilde(\rho,\omegaTilde)	\rho \\ \Vtilde(\rho,\omegaTilde) \rho \omegaTilde
	\end{pmatrix}
	=0
	\quad
	\text{or equivalently}
	\quad
	\begin{cases}
		\begin{aligned}
			\partial_t \rho + \partial_x\big(\rho \Vtilde(\rho,\omegaTilde) \big)&=0, \\
			\partial_t \omegaTilde + \Vtilde(\rho,\omegaTilde) \partial_x \omegaTilde&= 0,
		\end{aligned}
	\end{cases}
\end{equation}
where~$\omegaTilde$ is a driver-dependent quantity. Such systems generate a  
family of velocity curves~$\Vtilde(\cdot,\omegaTilde)$. 
%-
As explained in~\cite[Sec.~2.3]{fan2013comparative}, 
the ARZ model is of this form. Furthermore, the  generalization of the LWR model can be explained by the choice~$\omegaTilde=\omega=v+P(\rho)$, where this driver-dependent quantity  moves with the vehicles and 
influences the family of velocity curves~$
\Vtilde(\rho,\omega)
=
\omega
-P(\rho) 
$. \\

\noindent
Another traffic flow model of the form~\eqref{FixedVelocity} has been recently introduced to account for hysteresis~\cite{Corli:2019}. 
Since the speed-density relations corresponding to acceleration and deceleration 
are usually different, the function
$$
\h(\rho) \coloneqq
\chi_{A}(\rho) \hA(\rho)
+
\chi_{D}(\rho) \hD(\rho)
$$ 
is made dependent on the regions
$$
A(\rho) \coloneqq
\Big\{
(t,x) \in \mathbb{R}\times \mathbb{R}^+
\ \Big| \
\dot{\rho}(t,x)<0
\Big\}
\quad\text{and}\quad
D(\rho) \coloneqq
\Big\{
(t,x) \in \mathbb{R}\times \mathbb{R}^+
\ \Big| \
\dot{\rho}(t,x)>0
\Big\},
$$
where cars accelerate or slow down. 
Then, a specific~velocity~$\vCorli(\rho,h)$ is derived that depends on hysteresis~$h$ to account for the multi-valued speed-density relations. By defining the term
\begin{equation*}
	\HCorli(\rho,v)
	\coloneqq
	\chi_{A}(\rho) \Big(
	\partial_t\hA(\rho)
	+
	v \partial_x\hA(\rho)
	\Big)
	+
	\chi_{D}(\rho) \Big(
	\partial_t\hD(\rho)
	+
	v \partial_x\hD(\rho)
	\Big),
\end{equation*}
the model in~\cite{Corli:2019} can be written as
\begin{equation}\label{CorliLWR}
	\begin{cases}
		\begin{aligned}
			\partial_t \rho + \partial_x\big(\rho \vCorli(\rho,h) \big)&=0, \\
			\partial_t h + \vCorli(\rho,h) \partial_xh&= \HCorli\big(\rho,\vCorli(\rho,h)\big).
		\end{aligned}
	\end{cases}
\end{equation}
Therefore, the system~\eqref{CorliLWR} is of the form  given in equation~\eqref{FixedVelocity}. 
Here, we have
\begin{alignat*}{8}
&	\HCorli\big(\rho,\vCorli(\rho,h)\big)
	&&= &&
	\hCorli'(\rho) \Big[ -
	\partial_x \big( \rho \vCorli(\rho,h) \big) 
	+ 
	\vCorli(\rho,h) \partial_x \rho \Big] \\
&	&&= -&&
	\hCorli'(\rho) \Big[ 
	\rho \partial_\rho \vCorli(\rho,h)\partial_x \rho
	+
	\rho \partial_h \vCorli(\rho,h)\partial_x h \Big].
\end{alignat*}
which yields the quasilinear form~$
\partial_t \u + Q(\u) \partial_x \u=0 
$ 
for the unknowns~$\u=( \rho,h )^\T$ and the matrix function
$$
Q(\rho,h)=
\begin{pmatrix}
	\vCorli(\rho,h)
	+
	\rho \partial_\rho \vCorli(\rho,h)
	&
	\rho \partial_h \vCorli(\rho) \\
	%-
	\hCorli'(\rho) 
	\rho \partial_\rho \vCorli(\rho,h)
	&
	\hCorli'(\rho)
	\rho \partial_h \vCorli(\rho,h) 
	+\vCorli(\rho,h)
\end{pmatrix}.
$$
Hence, the characteristic speeds are
$$
\lambda_1^C(\rho,h)
=
\vCorli(\rho,h)
+
\rho\big[
\partial_\rho \vCorli(\rho,h)
+
\hCorli'(\rho)
\partial_h \vCorli(\rho,h)\big]
\quad
\text{and}
\quad
\lambda_2^C(\rho,h)
=
\vCorli(\rho,h).
$$


\noindent
While the perspective of~\cite{fan2013comparative} is more from a parameterized multiclass system, where driver dependent properties specify a given velocity curve, the approach of~\cite{Corli:2019,Corli:2023} is more related to the idea of the here proposed model, namely a closure problem. Inspired by similarly interpreting $h$  as hysteresis, we prove the following theorem. 

\medskip

\begin{theorem}\label{TheoremRelaxationCorli}
	%-
	The first-order correction to the local equilibrium approximation of the relaxed model
	\begin{equation}\label{Corli}
		\begin{cases}
			\begin{aligned}
				\partial_t \rho + \partial_x(\rho v)&=0,\\
				\partial_t v+ \Big(v-q'(h)\h'(\rho)\rho\Big)\partial_x v
				&= \frac{ \vCorli(\rho,h)-v }{\varepsilon} , \\
				\partial_t w +  \partial_x (wv
				)
				&=
				0		\end{aligned}
		\end{cases}
	\end{equation}	
	for 
	$w
	=
	\rho\big(
	h-\h(\rho) \big)
	$   
	reads as
	\begin{equation}\label{RelaxationCorli}
		\partial_t
		\begin{pmatrix}
			\rho \\ w
		\end{pmatrix}
		+\partial_x
		\begin{pmatrix}
			\vCorli(\rho,h)	\rho \\ \vCorli(\rho,h) w 
		\end{pmatrix}
		=
		-
		\varepsilon
		\partial_x 
		\left(
		\mu_C(\rho,h)
		\partial_x
		\begin{pmatrix}
			\rho \\ h
		\end{pmatrix}
		\right)
		+\mathcal{O}\big(\varepsilon^2\big)
	\end{equation}	
	with diffusion matrix
	\begin{align*}
		&\muCorli(\rho,h)
		\coloneqq
		\Big(
		\lambda_1^C(\rho,h)
		-\big(\vCorli(\rho,h)
		-q'(h)\h'(\rho)\rho
		\big)\Big)
		\begin{pmatrix}
			\rho	\partial_\rho \vCorli(\rho,h) 
			& 
			\rho	\partial_h \vCorli(\rho,h) \\
			w	\partial_\rho \vCorli(\rho,h) 
			& 
			w	\partial_h \vCorli(\rho,h) 	
		\end{pmatrix}\\
		%-
		&\text{for}\quad
		\lambda_1^C(\rho,h)
		=
		\vCorli(\rho,h)
		+
		\rho\big[
		\partial_\rho \vCorli(\rho,h)
		+
		\h'(\rho)
		\partial_h \vCorli(\rho,h)\big].
	\end{align*}
	In particular, if the relation
	$$
	q'(h)\h'(\rho)\rho
	=
	\vCorli(\rho,h)-\lambda_1^C(\rho,h)
	=
	\rho\big[
	\partial_\rho \vCorli(\rho,h)
	+
	\h'(\rho)
	\partial_h \vCorli(\rho,h)\big]
	$$
	holds, the equations~\eqref{Corli} and~\eqref{RelaxationCorli} coincide up to terms of order~$\mathcal{O}\big(\varepsilon^2\big)$.

\end{theorem}

\medskip

\begin{proof}
	We apply a Chapman-Enskog expansion
	$$
	v = \vCorli(\rho,h) + \varepsilon \v1
	+
	\mathcal{O}\big( \varepsilon^2 \big).
	$$	
	%-
	Due to~$
	\partial_t \h(\rho)+v\partial_x \h(\rho) = -\h'(\rho)\rho \partial_x v
	$, the first and third equation imply
	\begin{alignat*}{8}
		&\partial_t \rho 
		&&=-
		\partial_x \big( \rho \vCorli(\rho,h) \big)
		&&+\mathcal{O}(\varepsilon) \\
		& &&=
		-
		\vCorli(\rho,h) 
		\partial_x  \rho
		-
		\rho \Big( 
		\partial_\rho \vCorli(\rho,h)\partial_x \rho
		+
		\partial_h \vCorli(\rho,h)\partial_x h
		\Big)
		&&+\mathcal{O}(\varepsilon), \\
		%-----------------
		&\partial_t h &&= 
        -\vCorli(\rho,h) \partial_x h
        - \h'(\rho) \rho \partial_x \vCorli(\rho,h) 
		 &&+\mathcal{O}(\varepsilon)\\
		& &&=
        -\vCorli(\rho,h) \partial_x h 
        -
		\h'(\rho) \rho
		\Big(\partial_\rho \vCorli(\rho,h)\partial_x \rho
		+
		\partial_h \vCorli(\rho,h)\partial_x h
		\Big)
		&&+\mathcal{O}(\varepsilon).
	\end{alignat*}
	Hence, we have asymptotically the expression
	\begin{alignat}{8}
		&	\partial_t \vCorli(\rho,h) + \Big(\vCorli(\rho,h)-q'(h)\h'(\rho)\rho\Big) \partial_x \vCorli(\rho,h) \label{ProofRelaxationCorli1}\\
		&	
		=	
		\partial_\rho \vCorli(\rho,h) \partial_t \rho 
		+ 
		\partial_h \vCorli(\rho,h) \partial_t h \nonumber\\
	&\quad	+
		\Big(\vCorli(\rho,h)-q'(h)\h'(\rho)\rho\Big) \Big(
		\partial_\rho \vCorli(\rho,h) \partial_x \rho 
		+ 
		\partial_h \vCorli(\rho,h) \partial_x h 
		\Big)  \nonumber\\
		&
		=-	 
		\partial_\rho \vCorli(\rho,h) \vCorli(\rho,h)
		\partial_x \rho
		-
		\rho\partial_\rho \vCorli(\rho,h) \Big( 
		\partial_\rho \vCorli(\rho,h)\partial_x \rho
		+
		\partial_h \vCorli(\rho,h)\partial_x h
		\Big)  \nonumber\\
		& 
		\quad-
		\partial_h \vCorli(\rho,h)
		\h'(\rho) \rho
		\Big(\partial_\rho \vCorli(\rho,h)\partial_x \rho
		+
		\partial_h \vCorli(\rho,h)\partial_x h \Big)
		-
		\partial_h \vCorli(\rho,h)
		\vCorli(\rho,h) \partial_x h   \nonumber\\ 
		& \quad +  
		\Big(\vCorli(\rho,h)-q'(h)\h'(\rho)\rho\Big) \Big(
		\partial_\rho \vCorli(\rho,h) \partial_x \rho 
		+ 
		\partial_h \vCorli(\rho,h) \partial_x h  \Big) &&+\mathcal{O}(\varepsilon) \nonumber\\
		%%%
		& = - \Big(  \partial_\rho \vCorli(\rho,h)
		\partial_x \rho
		+
		\partial_h \vCorli(\rho,h) 
		\partial_x h
		\Big)
%		\Big(
%		\partial_\rho \vCorli(\rho,h) \rho
%		+
%		\partial_h \vCorli(\rho,h) \h'(\rho)\rho
%		+q'(h)\h'(\rho)\rho\Big)
		\Big(
		\lambda_1^C(\rho,h)
		-\big(\vCorli(\rho,h)
		-q'(h)\h'(\rho)\rho
		\big)\Big)
        && + \mathcal{O}(\varepsilon), \nonumber
	\end{alignat}
where the last equality follows from the relation
$$
		\Big(
		\partial_\rho \vCorli(\rho,h) \rho
		+
		\partial_h \vCorli(\rho,h) \h'(\rho)\rho
		+q'(h)\h'(\rho)\rho\Big)
=
		\Big(
		\lambda_1^C(\rho,h)
		-\big(\vCorli(\rho,h)
		-q'(h)\h'(\rho)\rho
		\big)\Big).
$$
	Furthermore, we have
	\begin{alignat}{8}
		&\v1 &&= 
		\frac{v-\vCorli(\rho,h)}{\varepsilon}
		&& && &&+\mathcal{O}(\varepsilon) \nonumber\\
		& &&=
		-\partial_t v &&- \Big(v&&-q'(h)\h'(\rho)\rho\Big) \partial_xv
		&&+\mathcal{O}(\varepsilon) \nonumber\\
		& &&=-
		\partial_t \vCorli(\rho,h) &&+ \Big(\vCorli(\rho,h)&&-q'(h)\h'(\rho)\rho\Big) \partial_x \vCorli(\rho,h)
		&&+\mathcal{O}(\varepsilon).
		\label{ProofRelaxationCorli2}
	\end{alignat}

	\noindent
	The equations~\eqref{ProofRelaxationCorli1}, \eqref{ProofRelaxationCorli2} and  the expressions
	\begin{alignat*}{8}
		&	\partial_t \rho &&+ \partial_x \Big(
		\vCorli(\rho,h) \rho
		\Big)
		&&=
		-\varepsilon \partial_x \Big( \rho \v1 \Big) &&+ \mathcal{O}\big(\varepsilon^2\big), \\
		%--
		&	\partial_t w &&+ \partial_x \Big(
		\vCorli(\rho,h) w
		\Big)
		&&=
		-\varepsilon \partial_x \Big( w \v1 \Big) &&+ \mathcal{O}\big(\varepsilon^2\big) 
	\end{alignat*}	
	yield the claimed diffusion matrix.

\hfill	
\end{proof}

\medskip

\noindent
Theorem~\ref{TheoremRelaxationCorli} 
states a possible choice of the functions~$
q
$ and~$\h$ such that the novel proposed model leads to results that are justified in the recent publication~\cite{Corli:2019,Corli:2023}. Namely, we have a reasonable choice  if the relation $
q'(h)\h'(\rho)\rho
\approx
\vCorli(\rho,h)-\lambda_1^C(\rho,h)
$ 
holds approximately, 
where~$\vCorli(\cdot,h)$ is the family of velocity curves from~\cite{Corli:2019} that takes hysteresis effects into account.





\section{Discussion of the Riemann problem}\label{SectionNumerics}
%- 
In this section we discuss the solution to a Riemann problem with constant left~$\u_\ell$
and right~$\u_r$
state. 
As explained in Section~\ref{SectionMacroscopicPiu}, 
the TOM model~\eqref{PiuS1}~--~\eqref{PiuS3} forms a Temple class system where the fields $k=2,3$, which correspond to the double eigenvalue~$\lambda_v(v)=v$  and which travel faster than the first wave,
form contacts. 
Since the first field is genuinely nonlinear, it can be either a rarefaction or a shock wave, which is connected by an intermediate state 
$\bar{\u}=
(
\bar{\rho},\bar{v},\bar{h}
)^\T$ 
with the contact. 

Since the velocity is a Riemann invariant of the second and third field, i.e.~${
\R_2(\u)=v}$, 
$\R_3(\u)=v$, 
it remains constant over a contact wave and hence the velocity of the intermediate state satisfies~$\bar{v}=v_r$. The third unknown~$\bar{h}$ is determined by the relation~$v_\ell+q(h_\ell)
=\R_1(\u_\ell)=\R_1(\bar{\u})=\bar{v}+q(\bar{h})
=
v_r+q(\bar{h})$.

The solution corresponding to a rarefaction waves travels according to an integral curve~$\mathcal{I}(\cdot;\u) $ of the first field, which   satisfies the ODE~$
\partial_\sigma \mathcal{I}_1(\sigma;\u)
=
r_1 \big(
\mathcal{I}(\sigma;\u)
\big)$ for $
\mathcal{I}(0;\u)
=
\u
$ 
provided that it holds~${
	\mathcal{I}( \sigma^*;\u_\ell)
    =
  ( \mathcal{I}_1,\mathcal{I}_2,\mathcal{I}_3)^\T( \sigma^*;\u_\ell)=
    \bar{\u} 
}$ for some~${\sigma^*\geq 0}$. 
Since the intermediate states~$\bar{v}$ and~$\bar{h}$ are given due to the foregoing discussion, the value~$\sigma^*$ is obtained by the equations~$\mathcal{I}_2( \sigma^*;\u_\ell) = \bar{v}$ and~$\mathcal{I}_3( \sigma^*;\u_\ell) = \bar{h}$. Finally, the density in the intermediate state is given by~$\bar{\rho}=\mathcal{I}_1( \sigma^*;\u_\ell)$. 
According to~{\cite[Sec.~5.1]{BRESSAN} and an entropy admissible weak solution is then given by



$$
\u(t,x)
\coloneqq
\begin{cases}
\u_\ell
& \text{for \ \ } x<t \lambda_1(\u_\ell), \\
\mathcal{I}(\sigma;\u_\ell)
& \text{for \ \ } x\in \big( t\lambda_1(\u_\ell),t\lambda_1(\bar{\u})  \big) 
\text{ \ \ and \ \  } \nicefrac{x}{t}   =\lambda_1\big(
\mathcal{I}(\sigma;\u_\ell)
\big), \\
\bar{\u}
& \text{for \ \ } x\in \big( t\lambda_1(\bar{\u}),tv_r  \big), \\
\u_r
& \text{for \ \ } x>t v_r.
\end{cases}
$$




