     \centering
     \begin{subfigure}{0.6\textwidth}
         \centering
         \includegraphics[width=\linewidth]{plot3recipforce.eps}
         \caption{Engine torque vs speed.}
         \label{phaseTransitionModel3}
     \end{subfigure}
     \begin{subfigure}{0.8\textwidth}
         \centering
         \includegraphics[width=\linewidth]{plot1recipforce.eps}
         \caption{A graph of force vs velocity for a variety of forces.}
         \label{phaseTransitionModel1}
     \end{subfigure}
     \begin{subfigure}{0.7\textwidth}
