\section{Functions $\lambda_\pm(x, \varepsilon)$ and kernels $A_{\pm, j}(\xi, \varepsilon)$, $B_{\pm, j}(\xi, \varepsilon)$}\label{sec:app}
The kernels $A_{\pm, j}(\xi, \varepsilon)$ and $B_{\pm, j}(\xi, \varepsilon)$ in (\ref{eq:gamma_eigen}) can be expressed as sums. This is done by using the expansion (\ref{eq:R_expans}) of the resolvent, which when substituted in definitions of $A_{\pm, j}(\xi, \varepsilon)$ and $B_{\pm, j}(\xi, \varepsilon)$ leads to
\begin{equation}\label{eq:AB_sums}
\begin{aligned}
&A_{\pm, j} (\xi, \varepsilon) = \frac{1}{2} \tanh \left(\frac{\varepsilon}{2T_c} \right) \sum_{n = 0}^\infty \frac{r_n^j(\xi) q_n^\pm(\varepsilon)}{1 - g_n}\\
&B_{\pm, j} (\xi, \varepsilon) = \frac{1}{2} \tanh \left(\frac{\varepsilon}{2T_c} \right) \sum_{n = 0}^\infty \frac{r_n^j(\xi) [q_n^\pm(\varepsilon)]^*}{1 - g_n}\\
&r_n^j(\xi) = \int\limits_0^l \psi_n(x) \lambda_j(x, \xi) dx\ \ \ q_n^\pm(\varepsilon) = \int\limits_0^l \psi_n(x) e^{\pm k(\varepsilon) x} dx.
\end{aligned}
\end{equation}
The functions $q_n^\pm(\varepsilon)$ are
\begin{equation}\label{eq:q}
q_n^\pm(\varepsilon) = \int\limits_0^l \psi_n(x) e^{\pm k(\varepsilon) x} dx = \frac{\pm k(\varepsilon) l^2}{k^2(\varepsilon) l^2 + \pi^2 n^2} \left[(-1)^n e^{\pm k(\varepsilon) l} - 1 \right].
\end{equation}
Next, 
\begin{equation}\label{eq:r}
r_n^\pm(\xi) = \int\limits_0^l \psi_n(x) \lambda_\pm(x, \xi) dx
\end{equation}
and in order to proceed we have to determine the functions $\lambda_\pm(x, \xi)$, which are entering expressions for coefficients $c_\pm(\xi)$ in (\ref{eq:cpm}). They are expressed via the Green function $H(x, x'; \xi)$:
\begin{equation}\label{eq:lambda}
\begin{aligned}
&\lambda_\pm(x', \xi) = \mu_\pm(\xi) H(0, x'; \xi) + \nu_\pm(\xi) H(l, x'; \xi).
\end{aligned}
\end{equation}
The coefficients $\mu_\pm(\xi)$ and $\nu_\pm(\xi)$ are
\begin{equation}
\begin{aligned}
&\begin{aligned}
&\mu_+(\xi) = \frac{\alpha_0}{s(\xi)} [\alpha_l + k(\xi)]& &\nu_+(\xi) = \frac{\alpha_l e^{k(\xi) l}}{s(\xi)} [\alpha_0 + k(\xi)]\\
&\mu_-(\xi) = \frac{\alpha_0 e^{2 k(\xi) l}}{s(\xi)} [\alpha_l - k(\xi)]& &\nu_-(\xi) = \frac{\alpha_l e^{2 k(\xi) l}}{s(\xi)}  [k(\xi) - \alpha_0]
\end{aligned}\\
&s(\xi) = i D e^{2 k(\xi) l} \big[\alpha_0 + k(\xi) \big] \big[\alpha_l - k(\xi) \big] + i D \big[\alpha_0 - k(\xi) \big] \big[\alpha_l + k(\xi) \big].
\end{aligned}
\end{equation}
They do not depend on $x'$, so the functions $\lambda_\pm(x', \xi)$ can also be expanded in the basis $\psi_n(x')$ given by (\ref{eq:psi}), if one substitutes
\begin{equation}
\begin{aligned}
&H(0, x'; \xi) = \sum_n \frac{\psi_n(0) \psi(x')}{h_n(\xi)} = \sum_n \frac{1}{h_n(\xi)} \cos\left(\frac{\pi n x'}{l} \right)\\ 
&H(l, x'; \xi) = \sum_n \frac{\psi_n(l) \psi(x')}{h_n(\xi)} = \sum_n \frac{(-1)^n}{h_n(\xi)} \cos\left(\frac{\pi n x'}{l} \right)
\end{aligned}
\end{equation}
in (\ref{eq:lambda}). This leads to
\begin{equation}
\lambda_\pm(x', \xi) = \sum_n \frac{\mu_\pm(\xi) + (-1)^n \nu_\pm(\xi)}{h_n (\xi)} \cos \left(\frac{\pi n x'}{l} \right).
\end{equation}
The integral in (\ref{eq:r}) is easily calculated and the sum collapses due to orthogonality of functions $\psi_n(x)$. Finally we end up with   
\begin{equation}
r_n^\pm(\xi) = \frac{\mu_\pm(\xi) + (-1)^n \nu_\pm(\xi)}{h_n (\xi)}.
\end{equation}
This together with (\ref{eq:q}) allows to write down integral kernels $A_{\pm, j}(\xi,\varepsilon)$ and $B_{\pm, j}(\xi,\varepsilon)$ as sums according to (\ref{eq:AB_sums}). 
