\title{Heterogeneous economic growth vulnerability across Euro Area countries under stressed scenarios}
\author{\normalsize Claudio Lissona\footnote{Corresponding author, e-mail: \url{claudio.lissona2@unibo.it}} \footnote{Department of Economics, University of Bologna}
