\mathbf{0} & \mathbf{0} & \ldots & \mathbf{I} & \mathbf{0}
\end{array}
} \hspace{20pt} \mathbf{A}^{(c,s)}\ =\ \parT{
\begin{array}{ccccc}
\mathbf{A}_1^{(c,s)} & \mathbf{A}_2^{(c,s)} & \multicolumn{2}{c}{\ldots}  & \mathbf{A}_{p_s}^{(c,s)} \\
\mathbf{I} & \mathbf{0} & \multicolumn{2}{c}{\ldots}  &  \mathbf{0}\\
\mathbf{0} & \mathbf{I} & \multicolumn{2}{c}{\ldots}  & \mathbf{0}\\
\vdots & \vdots & \multicolumn{2}{c}{\ddots}  & \vdots \\
\mathbf{0} & \mathbf{0} & \ldots & \mathbf{I} & \mathbf{0}
\end{array}
}
\label{sbeq::compA}
\end{equation}
\end{subequations}
\endgroup\\
are the companion form representation of the transition matrices for $s\in\mathcal{S}$ and $c\in\mathcal{C}$.

Finally, let $\bs{\Gamma}^{(s)} = (\bs{\Gamma}^{\scaleto{(\text{DE},s)}{6pt}\prime}, \bs{\Gamma}^{\scaleto{(\text{ES},s)}{6pt}\prime}, \bs{\Gamma}^{\scaleto{(\text{FR},s)}{6pt}\prime}, \bs{\Gamma}^{\scaleto{(\text{IT},s)}{6pt}\prime})' = (\bs{\gamma}_1^{(s)},\ldots, \bs{\gamma}_{n_s}^{(s)})'$ denote the loadings of the pervasive factors for sector $s\in \mathcal{S}$. 

\subsection{EM algorithm}
\label{sbapp:EM}

\subsubsection{Initialization}
\label{sbsbapp::initEM}

To estimate the model in Equations \eqref{sbeq::compobs}-\eqref{sbeq::compst}, we need to initialize all the parameters and states in the model. To do so, we employ the two step (top-down) PC approach \citep{aastveit2016world,breitung2016analyzing} to extract the estimated factors and the corresponding loadings, and we then use these estimated factors to obtain an estimate of the transition parameters in Equation \eqref{sbeq::compst}.

Specifically, let $\mathbf{X}^{(s)} = (\mathbf{x}_1^{(s)},\ldots,\mathbf{x}_T^{(s)})'$ be the $T\times N_s$ vector of data for sector $s\in\mathcal{S}$, pooling all countries. Without loss of generality, let $\mathbf{X}^{(s)}$ be standardized so to have mean zero and unit variance.
Given the data, we can estimate the global factor by means of principal components (PC) on the $N_s\times N_s$ sample variance-covariance matrix, say $\widehat{\boldsymbol{\Gamma}}^{X^s} = \frac{\mathbf{X}^{(s)\prime}\mathbf{X}^{(s)}}{T}$.

Following \citet{barigozzi2022estimation}, the least-squares estimation of the common factors within each sector, $\mathbf{f}^{(s)}$, and the corresponding loadings, $\bs{\Gamma}^{(s)}$, is given by:\\
\begin{equation}
\label{eq::LSsol}
\min_{\ubar{\mathbf{F}}^{(s)},\ubar{\bs{\Gamma}}^{(s)}}\ \frac{1}{N_s T}\sum_{t=1}^T \parT{\mathbf{X}^{(s)} - \hspace{-1.2pt}\ubar{\hspace{1.2pt}\mathbf{F}}^{(s)}\hspace{-1.2pt}\ubar{\hspace{1.2pt}\bs{\Gamma}}^{(s)\prime}}'\parT{\mathbf{X}^{(s)} - \hspace{-1.2pt}\ubar{\hspace{1.2pt}\mathbf{F}}^{(s)}\hspace{-1.2pt}\ubar{\hspace{1.2pt}\bs{\Gamma}}^{(s)\prime}}
\end{equation}\\
where $\hspace{-1.2pt}\ubar{\hspace{1.2pt}\mathbf{F}}^{(s)} = (\hspace{1pt}\ubar{\hspace{-1pt}\mathbf{f}}_1^{(s)},\ldots, \hspace{1pt}\ubar{\hspace{-1pt}\mathbf{f}}_T^{(s)})'$.
Under the identification conditions by \citet{forni2009opening}, i.e. $N_s^{-1}\hspace{-1.2pt}\ubar{\hspace{1.2pt}\bs{\Gamma}}^{(s)\prime}\hspace{-1.2pt}\ubar{\hspace{1.2pt}\bs{\Gamma}}^{(s)}$ diagonal, we solve Equation \eqref{eq::LSsol} by $\hspace{-1.2pt}\ubar{\hspace{1.2pt}\bs{\Gamma}}^{(s)}$, to obtain the PC estimator:\\
\begin{equation}
\label{eq::Ls}
\widehat{\bs{\Gamma}}^{(s),(0)}\ =\ \widehat{\mathbf{V}}^{\scaleto{\mathbf{X}^{(s)}}{5pt}}\parT{\widehat{\mathbf{M}}^{\scaleto{\mathbf{X}^{(s)}}{5pt}}}^{\frac{1}{2}}
\end{equation}\\
where $\widehat{\mathbf{V}}^{\scaleto{\mathbf{X}^{(s)}}{5pt}}$ is the matrix of eigenvectors corresponding to the $r_s-$ largest eigenvalues, $\widehat{\mathbf{M}}^{\scaleto{\mathbf{X}^{(s)}}{5pt}}$, of the sample variance-covariance matrix of the data. Given the estimated loadings, we obtain an estimate of the factor by projection onto matrix of data, that is:\\
\begin{equation}
\label{eq::Fs}
\widehat{\mathbf{F}}^{(s),(0)}\ =\ \mathbf{X}^{(s)}\widehat{\bs{\Gamma}}^{(s)}\parT{\widehat{\bs{\Gamma}}^{(s)\prime}\widehat{\bs{\Gamma}}^{(s)}}^{-1}\ =\ \mathbf{X}^{(s)}\widehat{\mathbf{V}}^{\scaleto{\mathbf{X}^{(s)}}{5pt}}\parT{\widehat{\mathbf{M}}^{\scaleto{\mathbf{X}^{(s)}}{5pt}}}^{-\frac{1}{2}} 
\end{equation}\\
Given the estimated factors in each sector, we still have to estimate the local factors within each country-sector block. Let $\overline{\mathbf{X}}^{(s)} = \mathbf{X}^{(s)} - \widehat{\mathbf{F}}^{(s),(0)}\widehat{\bs{\Gamma}}^{(s),(0)\prime}$ be the matrix of data for sector $s\in\mathcal{S}$ net of the comovements explained by the global factor (i.e., common to all countries) within the sector. We can repeat the procedure outlined above to obtain an estimate of the local factors within each country-sector subgroup.
For each country-sector pair, the estimated loadings are given by:\\
\begin{equation}
\widehat{\bs{\Phi}}^{(s),(0)}\ =\ \widehat{\mathbf{V}}^{\scaleto{\overline{\mathbf{X}}^{(s)}}{5pt}}\parT{\widehat{\mathbf{M}}^{\scaleto{\overline{\mathbf{X}}^{(s)}}{5pt}}}^{\frac{1}{2}}
\end{equation}
\subsubsection{E-step}
\label{sbsbapp:Estep}
Let $k = 1,\ldots, k_{\max}$ denote the indicator for the current iteration of the EM algorithm, and let $\widehat{\boldsymbol{\theta}}^{(k-1)}$ denote the vector of parameters estimated at iteration $k-1$, while $\mathbf{F}_{0\giv 0}^{(k-1)}$ and $\mathbf{P}_{0\giv 0}^{(k-1)}$ denote the corresponding initial estimate of factor and their conditional variance. Then, conditional on these quantities, in the E-step we run the Kalman Filter and Smoother to obtain updated estimates the factors and their variance, i.e. $\mathbf{F}_{t\giv T}^{(k)}$ and $\mathbf{P}_{t\giv T}^{(k)}$, along with the conditional covariance across states, denoted as $\mathbf{P}_{t,t-1\giv T}^{(k)}$.

\subsubsection{M-step}
\label{sbsbapp:Mstep}

In the M-step, we maximize the expected log-likelihood with respect to the parameters.\\

\begin{enumerate}
\item \textbf{Factor Loadings}:
\begin{align*}
\widehat{\bs{\gamma}}_i^{(s),(k+1)}\ &=\ \parT{\sum_{t=1}^T x_{i,t}^{(s)}\mathbf{f}_{t\giv T}^{(s),(k)}}\parT{\sum_{t=1}^T \mathbf{f}_{t\giv T}^{(s),(k)}\mathbf{f}_{t\giv T}^{(s),(k)\prime} + \mathbf{P}_{t\giv T}^{\mathbf{f}^{(s)},(k)}}^{-1} \\[5pt]
\widehat{\bs{\phi}}_i^{(c,s),(k)}\ &=\ \parT{\sum_{t=1}^T x_{i,t}^{(c,s)}\mathbf{f}_{t\giv T}^{(c,s),(k)}}\parT{\sum_{t=1}^T \mathbf{f}_{t\giv T}^{(c,s),(k)}\mathbf{f}_{t\giv T}^{(c,s),(k)\prime} + \mathbf{P}_{t\giv T}^{\mathbf{f}^{(c,s)},(k)}}^{-1} \\[5pt]
\end{align*}
stacking the loadings, we denote the estimated loadings $\widehat{\bs{\Lambda}}^{(k+1)}$.
\item \textbf{Idiosyncratic variances}:
\begin{align*}
\widehat{\sigma}^{2,(k+1)}_{\xi_i}\ =\ \frac{1}{T}\sum_{t=1}^T\parQ{\parT{x_{i,t} - \widehat{\bs{\lambda}}_i^{(k+1)'}\mathbf{F}_t^{(k)}}^2 + \widehat{\bs{\lambda}}_i^{(k+1)'}\mathbf{P}_{t\giv t-1}^{(k)}\widehat{\bs{\lambda}}_i^{(k+1)}}
\end{align*}
where $\bs{\lambda}_i$ is the $i$-th row of the matrix of stacked loadings $\bs{\Lambda} = (\bs{\lambda}_1,\ldots,\bs{\lambda}_{n})'$.
\item \textbf{Parameters of the law of motion of the common factors}:
\begingroup
\allowdisplaybreaks
\begin{align*}
\hat{\mathbf{A}}^{(s),(k+1)}\ &=\ \parT{\sum_{t=2}^T \mathbf{f}_{t\giv T}^{(s),(k)}\mathbf{f}_{t-1\giv T}^{(s),(k)^{\prime}} + \mathbf{P}_{t,t-1\giv T}^{\mathbf{f}^{(s)},(k)}}\parT{\sum_{t=2}^T \mathbf{f}_{t-1\giv T}^{(s),(k)}\mathbf{f}_{t-1\giv T}^{(s),(k)^{\prime}} + \mathbf{P}_{t-1\giv T}^{\mathbf{f}^{(s)},(k)}}^{-1}\\[5pt]
\hat{\mathbf{A}}^{(c,s),(k+1)}\ &=\ \parT{\sum_{t=2}^T \mathbf{f}_{t\giv T}^{(c,s),(k)}\mathbf{f}_{t-1\giv T}^{(c,s),(k)^{\prime}} + \mathbf{P}_{t,t-1\giv T}^{\mathbf{f}^{(c,s)},(k)}}\parT{\sum_{t=2}^T \mathbf{f}_{t-1\giv T}^{(c,s),(k)}\mathbf{f}_{t-1\giv T}^{(c,s),(k)^{\prime}} + \mathbf{P}_{t-1\giv T}^{\mathbf{f}^{(c,s)},(k)}}^{-1}\\[5pt]
\widehat{\boldsymbol{\Sigma}}_u^{(s),(k+1)}\ &=\ \frac{1}{T}\left[\sum_{t=2}^T\left(\mathbf{f}_{t \mid T}^{(s),(k)} \mathbf{f}_{t \mid T}^{(s),(k)^{\prime}}+\mathbf{P}_{t \mid T}^{\mathbf{f}^{(s)},(k)}\right)-\hat{\mathbf{A}} \sum_{t=2}^T\left(\mathbf{f}_{t \mid T}^{(s),(k)} \mathbf{f}_{t-1 \mid T}^{(s),(k)^{\prime}}+\mathbf{P}_{t, t-1 \mid T}^{\mathbf{f}^{(s)},(k)}\right)\right]\\[5pt]
\widehat{\boldsymbol{\Sigma}}_u^{(c,s),(k+1)}\ &=\ \frac{1}{T}\left[\sum_{t=2}^T\left(\mathbf{f}_{t \mid T}^{(c,s),(k)} \mathbf{f}_{t \mid T}^{(c,s),(k)^{\prime}}+\mathbf{P}_{t \mid T}^{\mathbf{f}^{(c,s)},(k)}\right)-\hat{\mathbf{A}} \sum_{t=2}^T\left(\mathbf{f}_{t \mid T}^{(c,s),(k)} \mathbf{f}_{t-1 \mid T}^{(c,s),(k)^{\prime}}+\mathbf{P}_{t, t-1 \mid T}^{\mathbf{f}^{(c,s)},(k)}\right)\right]
\end{align*}
\endgroup
\end{enumerate}

\subsubsection{Convergence}
\label{sbsbsec::EMconv}

At each iteration $k$ of the algorithm, an estimate of the log-likelihood conditional on the estimated parameters, $\ell(\mathbf{X},\widehat{\bs{\theta}}^{(k)})$, is obtained from the Kalman Filter. To assess the convergence of the EM algorithm, we then employ the likelihood-based criterion introduced by \citet{doz2012quasi}, based on the (scaled) difference between the log-likelihood across subsequent iterations of the algorithm:\\
\begin{equation*}
\Delta \ell^{(k+1)}=\frac{\left|\ell\left(\mathbf{X} ; \widehat{\boldsymbol{\theta}}^{\left(k+1\right)}\right)-\ell\left(\mathbf{X}; \widehat{\boldsymbol{\theta}}^{\left(k\right)}\right)\right|}{\frac{1}{2}\left|\ell\left(\boldsymbol{X}; \widehat{\boldsymbol{\theta}}^{\left(k+1\right)}\right)+\ell\left(\mathbf{X}; \widehat{\boldsymbol{\theta}}^{\left(k\right)}\right)\right|}
\end{equation*}\\
The algorithm is stopped when $\Delta \ell^{(k+1)} < \varepsilon$, for a predetermined threshold $\varepsilon$, which is set to $10^{-3}$.

\subsubsection{Confidence Intervals}
\label{sbsbsec::confint}
In this paper, we follow the procedure outlined in \citet{barigozzi2022estimation} to compute confidence intervals for the factors estimated via the EM algorithm, properly modified so to account for the block structure within the model. Under the assumption of cross-sectionally uncorrelated idiosyncratic components the variance-covariance matrix of the common and country-specific factors can be estimated as:
\begin{align*}
\tilde{\bs{\Gamma}}^{(s)}\ &=\ \parT{\frac{1}{N^{(s)}} \sum_{i\in N^{(s)}}\widehat{\bs{\gamma}}_{i}'(\widehat{\sigma}_{\xi_{i}}^{2})^{-1}\widehat{\bs{\gamma}}_{i}}^{-1}\\[5pt]
\tilde{\bs{\Gamma}}^{(c,s)}\ &=\ \parT{\frac{1}{N^{(c,s)}} \sum_{i\in N^{(c,s)}}\widehat{\bs{\phi}}_{i}'(\widehat{\sigma}_{\xi_{i}}^{2})^{-1}\widehat{\bs{\phi}}_{i}}^{-1} 
\end{align*}\\
where $\widehat{\sigma}_{\xi_{i}}^{2}$ is the estimated variance of the idiosyncratic component of the $i$-th variable.\footnote{We also try implementing the adaptive thresholding procedure as outlined in \citet{cai2011adaptive}, finding that only $\approx 3\%$ of outer-diagonal entries are actually shrinked to zero, yielding nearly identical results. Indeed, as shown also in Appendix \ref{app:modspec}, the block-structure is able to account for all relevant comovements in the panel, including local dynamics, which leave almost no relevant information in the idiosyncratic component} 

Although consistent, these estimates are likely to misrepresent the true uncertainty on the underlying factors. Indeed, as pointed out by \citet{maldonado2021accurate}, the estimated variance-covariance matrix of the factors depends on the loadings, which are themselves estimated. Hence, we need to account for the additional uncertainty which stems from the estimation of the loadings. This is particularly important in our setting, where we stress the factors at their 95\% significance level. Failing to account for loadings uncertainty could make our results either upward or downward biased, resulting in an over- or under-estimation of the true level of stress for the factors.

In the paper, we follow the subsampling procedure proposed by \citet{maldonado2021accurate}, properly modified to account for the block structure of our ML-DFM.   Specifically, for each country-sector subgroup, we draw randomly, without replacement, a $T\times N_{c,s}^*$ sub-matrix of data, say $X_{t}^{\scaleto{(c,s)}{6pt}^*}$. The size of the sub-matrix is selected in a data-driven way, such that $N_{c,s}^* = p^{(c,s)}\cdot N^{(c,s)}$, where $p^{(c,s)} =  1 - \frac{235}{(N^{(c,s)} + 25)^{2}} - 0.2\frac{\sqrt{N^{(c,s)}}}{T} - \frac{r^{c,s}}{N^{(c,s)}T}$. Given the sub-blocks for each country-sector pair, we then aggregate them to obtain the corresponding sub-blocks at the sectoral level, used to extract the sector-specific factors common to all countries. The reason for this \enquote{bottom-down} procedure is to avoid over- or under-representation of countries or sectors, which would be highly likely if we resampled the data being agnostic of the block-structure, especially since macroeconomic variables are sensibly more than financial ones.

Once the sub-matrix of data is selected, we extract the factors via PC, used to initialize the EM algorithm, which is run until convergence. This procedure is repeated $B$ times and, at the end of each iteration, a new estimated of the factors, denoted as $\widehat{\mathbf{F}}_t^{(b)}$ for $b=1,\ldots,B$, is stored. In the paper we set $B=199$ repetitions, as results are nearly identical using more replications, only being more computational demanding. Given the factors estimated at each iteration $b$, an estimate of the variance-covariance matrix of the factors which accounts for the uncertainty in the estimation of the loadings, can be finally computed. Specifically we define as $\widehat{\bs{\Gamma}}^{(s)}$ the estimated variance-covariance matrix for the sector-specific factors common to all countries, and with $\widehat{\bs{\Gamma}}^{(c,s)}$ the estimated variance-covariance matrix for the country-sector specific factors. Then:\\
\begin{align*}
\widehat{\bs{\Gamma}}^{(s)}\ =\ \tilde{\bs{\Gamma}}^{(s)} + \frac{N^{(s)^*}}{N^{(s)}BT}\sum_{b=1}^{B}\sum_{t=1}^{T}\parT{\widehat{\mathbf{f}}_t^{(s),(b)} - \widehat{\mathbf{f}}_t^{(s)}}\parT{\widehat{\mathbf{f}}_t^{(s),(b)} - \widehat{\mathbf{f}}_t^{(s)}}'\\[5pt]
\widehat{\bs{\Gamma}}^{(c,s)}\ =\ \tilde{\bs{\Gamma}}^{(c,s)} + \frac{N^{(c,s)^*}}{N^{(c,s)}BT}\sum_{b=1}^{B}\sum_{t=1}^{T}\parT{\widehat{\mathbf{f}}_t^{(c,s),(b)} - \widehat{\mathbf{f}}_t^{(s)}}\parT{\widehat{\mathbf{f}}_t^{(c,s),(b)} - \widehat{\mathbf{f}}_t^{(c,s)}}'
\end{align*}

\newpage 
\section{Model Specification}
\label{app:modspec}
The selection of the number of factors of the ML-DFM is carried out by analysing the structure of the sample covariance matrix of the idiosyncratic residuals obtained when estimating Model \eqref{eq::mlDFM} via the EM algorithm with the most parsimonious specification, i.e. with just one global and one country-specific factor for each country, i.e. $\widehat{\bs{\Xi}} = (\widehat{\bs{\xi}}_{1}',\ldots,\widehat{\bs{\xi}}_{N}')'$. Figure \ref{fig::idcorr_q1} is a heat-map of the corresponding pairwise cross-correlations. As we can see, although the most parsimonious model, with one country-specific factor, is able to capture the bulk of within-sector dynamics, there are still some small blocks of cross-correlated idiosyncratic components. This may be particularly relevant as the blocks are not randomly located, but they are concentrated around the same group of series for all countries (bottom-right corner). It turns out that these are mostly price series. Hence, it seems that one factor for macroeconomic variables is not able to account for some of the comovements across price series, either within or across countries (or both).

\begin{figure}[ht!]
\caption{Idiosyncratic cross-correlation: $q=1$ for each block} 
\label{fig::idcorr_q1}
\centering \footnotesize \sc
\setlength{\tabcolsep}{.01\textwidth}    
\begin{tabular}{c}
\includegraphics[width = 0.9\textwidth]{Figures/corr_xi.pdf} 
\end{tabular}    
\end{figure}

To account for the presence of cross-correlation across price series, we consider estimating an additional global macroeconomic factor and, alternatively, an country-specific additional macroeconomic factor for each country. If the price dynamics are mostly idiosyncratic within countries, then an additional macroeconomic factor for each country will incorporate this information.

\begin{figure}[ht!]
\caption{Idiosyncratic cross-correlation: alternative model specifications} 
\label{fig::idcorr_qMC}
\centering \footnotesize \sc
\setlength{\tabcolsep}{.01\textwidth}    
\begin{tabular}{cc}
\scriptsize Common macroeconomic factor & \scriptsize Country-specific macroeconomic factors\\
\includegraphics[trim={2cm 0cm 2cm 0cm},clip,width = 0.5\textwidth]{Figures/corr_xi_2M.pdf} & \includegraphics[trim={2cm 0cm 2cm 0cm},clip,width = 0.5\textwidth]{Figures/corr_xi_2MC.pdf} 
\end{tabular}    
\end{figure}

Figure \ref{fig::idcorr_qMC} plots the matrix of cross-correlations across estimated idiosyncratic components in both the cases outlined above. From the graph, it emerges that one additional factor for each country seems to be the most appropriate solution to account for the presence of local dynamics within price series.

