\section{Preliminaries}
\label{sec_preliminaries}

In this section we collect preliminaries and preparatory results from number theory, ergodic theory, and Fourier analysis which are needed for the proofs of Theorems~\ref{thm_1_tech} and~\ref{thm_2_tech}.

\subsection{Basic properties of logarithmic averages}

We use logarithmic averages in the formulations of Theorems~\ref{thm_1_tech} and~\ref{thm_2_tech} and, as we have seen in \cref{ex_1}, it is in general not possible to replace them by \Cesaro{} averages.
This naturally prompts the question: which properties of logarithmic averages are necessary for our argument? An answer is provided by the following lemma.

\begin{lemma}
\label{lem_dilation_log_averages}
For any $q,N\in\N$ and any $1$-bounded $f\colon\Z\to\C$ we have
\[
\logE_{n\in [N]} f(n) = \logE_{n\in [N]} q \1_{q\mid n} f\big(\tfrac{n}{q}\big) + \Oh\bigg(\frac{\log q}{\log N}\bigg).
\]
\end{lemma}

\begin{proof}
We have
\begin{align*}
\sum_{n\in [N]} \frac{f(n)}{n}
= \sum_{\substack{n\in [qN] \\ q\mid n}} \frac{ f\big(\tfrac{n}{q}\big)}{\tfrac{n}{q}}
= \sum_{n\in [qN]} \frac{q \1_{q\mid n} f\big(\tfrac{n}{q}\big)}{n} 
= \sum_{n\in [N]} \frac{q \1_{q\mid n} f\big(\tfrac{n}{q}\big)}{n} +\Oh(\log q).
\end{align*}
Hence,
\begin{align*}
\logE_{n\in [N]} f(n)&= \frac{1}{\big(\sum_{n\in [N]}\frac{1}{n}\big)} \Bigg(\sum_{n\in [N]} \frac{f(n)}{n} \Bigg)
\\
&= \frac{1}{\big(\sum_{n\in [N]}\frac{1}{n}\big)} \Bigg( \sum_{n\in [N]} \frac{q \1_{q\mid n} f\big(\tfrac{n}{q}\big)}{n}\Bigg) + \Oh\bigg(\frac{\log q}{\log N}\bigg)
\\
&=\logE_{n\in [N]} q \1_{q\mid n} f\big(\tfrac{n}{q}\big) + \Oh\bigg(\frac{\log q}{\log N}\bigg),
\end{align*}
as desired.
\end{proof}

\subsection{Preliminaries from multiplicative number theory}

A corollary of the \Turan{}-Kubilius inequality (cf.~\cite[Chapter~4]{Elliott79}) states that for any finite set of primes $P\subset\P\cap [N]$ one has  
\begin{equation}
\label{eqn_TK}
\sum_{n\in[N]} \left(\, \sum_{p \in P} \mathbf{1}_{p \mid n} - \sum_{p \in P} \frac{1}{p} \right)^2 \leq 3N\Bigg( \sum_{p \in P} \frac{1}{p} \Bigg),
\end{equation}
where $\mathbf{1}_{p \mid n}$ denotes the function that is $1$ if $p$ divides $n$ and $0$ otherwise.  
Dividing \eqref{eqn_TK} by $N(\sum_{p \in P} 1/p )^2$, we obtain the following equivalent version:
\begin{equation}
\label{eqn_TK_2}
\E_{n\in[N]} \Big( \logE_{p \in P} p\mathbf{1}_{p \mid n} - 1 \Big)^2 \leq 3\Bigg( \sum_{p \in P} \frac{1}{p} \Bigg)^{-1} .
\end{equation}

Note that in \eqref{eqn_TK_2}, it is not possible to replace the logarithmic average in the variable~$p$ with a \Cesaro{} average. 
Since our main results utilize logarithmic averages in all variables, we require a variant of \eqref{eqn_TK_2} that uses logarithmic averages in the variable~$n$ too.
One way to obtain such a variant would be to simply derive it from \eqref{eqn_TK_2} using partial summation. Another approach -- one we take -- is to give a short and self-contained proof.

\begin{proposition}[Logarithmically averaged \Turan{}-Kubilius inequality]
\label{prop_log_TK}
Let $N\in\N$ and $P\subset \P\cap [N]$.
Then
\[
\logE_{n\in [N]}\Big(\logE_{p\in P} \big(p\1_{p\mid n} -1\big)\Big)^2
\leq 9 \Bigg(\sum_{p\in P}\frac{1}{p} \Bigg)^{-1}.
\]
\end{proposition}

\begin{proof}
By expanding the square, we obtain
\begin{align*}
\logE_{n\in [N]}\Big(\logE_{p\in P} p\1_{p\mid n} -1\Big)^2
&=
\logE_{n\in [N]} \Big(\logE_{p\in P} p\1_{\mathrm{lcm}(p,q)\mid n}\Big)^2
-2 \logE_{n\in [N]} \Big(\logE_{p\in P} p\1_{p\mid n}\Big) +1
\\
&=
\logE_{p,q\in P} pq\Big(\logE_{n\in [N]} \1_{\mathrm{lcm}(p,q)\mid n}\Big)
-2 \logE_{p\in P} p\Big(\logE_{n\in [N]} \1_{p\mid n}\Big) +1.
\end{align*}
For the first term, we can estimate from above using
\begin{align*}
\logE_{n\in [N]} \1_{\mathrm{lcm}(p,q)\mid n}
&= \frac{1}{\big(\sum_{n\in[N]}\frac{1}{n}\big)} \sum_{n\in[N]} \frac{\1_{\mathrm{lcm}(p,q)\mid n}}{n} 
\leq \frac{1}{\mathrm{lcm}(p,q)}.
\end{align*}
For the second term, we can establish a bound from below by 
\begin{align*}
\logE_{n\in [N]} \1_{p\mid n}
&= \frac{1}{\big(\sum_{n\in[N]}\frac{1}{n}\big)} \sum_{n\in[N]} \frac{\1_{p\mid n}}{n}
\\
&= \frac{1}{\big(\sum_{n\in[N]}\frac{1}{n}\big)} \sum_{1\leq  n \leq N/p} \frac{1}{pn}
\\
&= \frac{1}{p} - \frac{1}{\big(\sum_{n\in[N]}\frac{1}{n}\big)} \sum_{N/p<  n \leq N} \frac{1}{pn}
\\
&\geq  \frac{1}{p} - \frac{\log (p)}{p\log(N)},
\end{align*}
where the last estimate is quickly derived from a standard approximation of the harmonic sum $\frac{1}{2M}-\frac{1}{8M^2}\leq (\sum_{n\in[M]}\frac{1}{n})-\log(M)-\gamma\leq \frac{1}{2M}$, where $\gamma$ is the Euler-Mascheroni constant.
It follows that
\begin{align*}
\logE_{n\in [N]}\Big(\logE_{p\in P} p\1_{p\mid n} -1\Big)^2
&=
\logE_{p,q\in P} \frac{pq}{\mathrm{lcm}(p,q)}
-1 + 2\logE_{p\in P} \frac{\log (p)}{\log(N)}.
\end{align*}
To finish the proof, note that
\[
\logE_{p,q\in P} \frac{pq}{\mathrm{lcm}(p,q)} \leq 1+ \left( \sum_{p \in P} \frac{1}{p} \right)^{-1},
\]
and that
\[
\logE_{p\in P} \frac{\log (p)}{\log(N)}=
\frac{\big(\sum_{p\in P}\frac{\log(p)}{p}\big)}{\big(\sum_{p\in P}\frac{1}{p}\big)\log(N)}.
\]
By Mertens' first theorem and since $P\subset \P\cap [N]$, we have
\[
\sum_{p\in P}\frac{\log(p)}{p}\leq \sum_{p\in \P\cap[N]}\frac{\log(p)}{p}\leq  \log(N)+ 2.
\]
Therefore, 
\[
\logE_{p\in P} \frac{\log (p)}{\log(N)}
\leq 4 \left( \sum_{p \in P} \frac{1}{p} \right)^{-1}.
\]
The claim follows by combining the above estimates.
\end{proof}

The way we employ \cref{prop_log_TK} in the subsequent proofs is via the following two corollaries.

\begin{corollary}
\label{cor_log_TK}
For $W\in\N$ and any bounded function $f\colon\Z\to\C$ we have
\[
\limsup_{M\to\infty}\limsup_{N\to\infty}\Big|\logE_{n\in[N]} f(n) - \logE_{p\in\P_W\cap [M]}\logE_{n\in[N]} f(pn)\Big|=0.
\]
\end{corollary}

\begin{proof}
Using \cref{lem_dilation_log_averages} and the Cauchy-Schwarz inequality, we obtain
\begin{align*}
\Big|\logE_{n\in[N]} f(n) - \logE_{p\in\P_W\cap [M]}\logE_{n\in[N]} f(pn)\Big|
&=
\Big|\logE_{n\in[N]} f(n) - \logE_{p\in\P_W\cap [M]}\logE_{n\in[N]} p\1_{p\mid n} f(n)\Big|
\\
&=
\Big|\logE_{n\in[N]} f(n) \Big( \logE_{p\in\P_W\cap [M]} \big(1- p\1_{p\mid n} \big)\Big)\Big|
\\
&\leq
\Big(\logE_{n\in[N]} |f(n)|^2 \Big)^{\frac{1}{2}}
\Big(\logE_{n\in[N]}\Big| \logE_{p\in\P_W\cap [M]} \big(1- p\1_{p\mid n} \big)\Big|^2\Big)^{\frac{1}{2}}.
\end{align*}
The claim now follows from \cref{prop_log_TK} together with the fact that
\[
\sum_{p\in\P_W}\frac{1}{p}=\infty,
\]
which follows from the prime number theorem in arithmetic progressions.
\end{proof}

\begin{corollary}
\label{cor_log_TK_2}
For $W\in\N$ and any bounded function $f\colon\Z\to\C$ we have for any $k\in\N$ that
\[
\limsup_{M_k\to\infty}\cdots \limsup_{M_1\to\infty}\limsup_{N\to\infty}\Big|\logE_{n\in[N]} f(n) - \logE_{p_k\in\P_W\cap [M_k]}\cdots \logE_{p_1\in\P_W\cap [M_1]}\logE_{n\in[N]} f(p_k\cdots p_1n)\Big|=0.
\]
\end{corollary}

\begin{proof}
This follows by iterating \cref{cor_log_TK}.
\end{proof}

\subsection{Preliminaries concerning exponential sums along primes}

Throughout, we use the abbreviation $e(x)=e^{2\pi i x}$ for $x\in\R$. 
It follows from the classical works of Vinogradov \cite{Vinogradov57,Vinogradov58} and Rhin \cite{Rhin73} that for any real polynomial $Q(x)=a_dx^d+\ldots+a_1x+a_0$ with the property that at least one of the coefficients $a_1,\ldots,a_d$ is an irrational number one has
\begin{equation}
\label{eqn_rhin}
\lim_{M\to\infty}\E_{p\in\P\cap[M]} e(Q(p)) =0.
\end{equation}
For the proof of our main results, we require a version of~\eqref{eqn_rhin} using logarithmic averages; we include a proof for completeness.

\begin{lemma}
\label{lem_log_vinogradov}
For any $a\in\N$, $b\in\Z$, any non-constant polynomial with rational coefficients $Q$, and any irrational real number $\alpha$ we have
\begin{equation}
\label{eqn_log_vinogradov}
\lim_{M\to\infty}\logE_{p\in\P\cap[M]} \1_{a\Z+b}(p)\, e( Q(p)\alpha) =0.
\end{equation}
\end{lemma}

\begin{proof}
We will make use of the basic identity
\[
\1_{a\Z+b}(n)=\frac{1}{a}\sum_{r=0}^{a-1} e\bigg(\frac{(b-n)r}{a}\bigg).
\]
Define $Q_r(x)=Q(x)\alpha-\frac{xr}{a}$.
We thus have
\begin{align*}
\sum_{p\in\P\cap[M]} \1_{a\Z+b}(p)\,\frac{e(Q(p)\alpha)}{p}
&=\frac{1}{a}\sum_{r=0}^{a-1} e\bigg(\frac{br}{a}\bigg) \Bigg(
\sum_{p\in\P\cap[M]}  \frac{e(Q_r(p))}{p} \Bigg).
\end{align*}
Let $\rho\in (1,2)$ and pick $J\in\N$ such that $M\in (\rho^{J},\rho^{J+1}]$.
By the prime number theorem, $|\P\cap (\rho^j,\rho^{j+1}]|\sim\frac{\rho^j}{j\log(\rho)}$.
Hence
\begin{align*}
\bigg|\sum_{p\in\P\cap[M]} & \frac{e(Q_r(p))}{p}\bigg|
\\
&\leq \sum_{j=1}^{J}\bigg| \sum_{p\in\P\cap (\rho^j,\rho^{j+1}]} \frac{e(Q_r(p))}{p}\bigg|+\Oh(1)
\\
&\leq \sum_{j=1}^{J}\bigg| \frac{1}{\rho^j} \sum_{p\in\P\cap (\rho^j,\rho^{j+1}]} e(Q_r(p))\bigg|+ \Oh\bigg(\sum_{j=1}^{J}\frac{\rho-1}{j\log(\rho)}\bigg)
\\
&= \sum_{j=1}^{J}\frac{1}{j\log(\rho)}\bigg|\frac{j\log(\rho)}{\rho^j} \sum_{p\in\P\cap (\rho^j,\rho^{j+1}]} e(Q_r(p))\bigg|+ \Oh\bigg(\sum_{j=1}^{J}\frac{\rho-1}{j\log(\rho)}\bigg).
\end{align*}
Note that by \eqref{eqn_rhin},
\begin{align*}
\lim_{j\to\infty} \frac{j\log(\rho)}{\rho^j} \sum_{p\in\P\cap (\rho^j,\rho^{j+1}]} e(Q_r(p))=\lim_{j\to\infty}
 \E_{p\in\P\cap (\rho^j,\rho^{j+1}]} e(Q_r(p))=
0,
\end{align*}
because $Q_r(x)$ is a polynomial with at least one irrational non-constant coefficient. Therefore, we are left with
\[
\sum_{j=1}^{J}\frac{1}{j\log(\rho)}\bigg|\frac{j\log(\rho)}{\rho^j} \sum_{p\in\P\cap (\rho^j,\rho^{j+1}]} e(Q_r(p))\bigg|=\oh_{J\to\infty}\bigg(\sum_{j=1}^{J}\frac{1}{j\log(\rho)}\bigg).
\]
Overall, this gives 
\begin{equation}
\label{eqn_log_vinogradov_2}
\bigg|\sum_{p\in\P\cap[M]} \1_{a\Z+b}(p)\,\frac{e(Q(p)\alpha)}{p}\bigg|=\Oh\bigg(\sum_{j=1}^{J}\frac{\rho-1}{j\log(\rho)}\bigg). 
\end{equation}
Using $M\in (\rho^{J},\rho^{J+1}]$ and the prime number theorem, we see that
\begin{equation}
\label{eqn_log_vinogradov_3}
\sum_{p\in\P\cap[M]} \frac{1}{p}\sim \sum_{j=1}^{J}\frac{1}{j\log(\rho)}.
\end{equation}
Combining \eqref{eqn_log_vinogradov_2} and \eqref{eqn_log_vinogradov_3}, we obtain
\[
\limsup_{M\to\infty}\Big|\logE_{p\in\P\cap[M]} \1_{a\Z+b}(p)\, e(Q(p)\alpha)\Big|=\Oh\big(\rho-1\big).
\]
Letting $\rho$ approach $1$ finishes the proof.
\end{proof}

Below, we offer a slight variant of \cref{lem_log_vinogradov}, which will be used in \cref{sec_proof_of_thm_rnd_component}. Recall that $\P_W=\{p\in \P: p\equiv 1\bmod W\}$. 

\begin{corollary}
\label{cor_log_vinogradov}
For any $a,W\in\N$, $b\in\Z$, any non-constant polynomial with rational coefficients $Q$, and any irrational real number $\alpha$ we have
\begin{equation}
\label{eqn_log_vinogradov_4}
\lim_{M\to\infty}\logE_{p\in\P_W\cap[M]} \1_{a\Z+b}(p)\, e( Q(p)\alpha) =0.
\end{equation}
\end{corollary}

\begin{proof}
In light of the prime number theorem in arithmetic progressions, we have for any bounded function $u\colon\N\to\C$ that
\[
\limsup_{M\to\infty}\Big|\logE_{p\in\P_W\cap[M]} u(p) -\logE_{p\in\P\cap[M]} W\1_{W\Z+1}(p)\, u(p)\Big|=0.
\]
It is then clear that \eqref{eqn_log_vinogradov_4} follows from \eqref{eqn_log_vinogradov}.
\end{proof}

\subsection{Preliminaries from ergodic theory}

For the reminder of this section, let $\Hilb$ be Hilbert space with inner product $\langle.,.\rangle$ and norm $\|.\|$. A \define{unitary operator} on $\Hilb$ is a bounded linear operator $U \colon \Hilb\to\Hilb$ which is invertible and preserves the inner product of the Hilbert space, that is, for all $f,g\in\Hilb$ we have
\[
\langle Uf,Ug\rangle=\langle f,g\rangle.
\]
We say that $\Hilb$ is the \define{orthogonal direct sum} of $\Hilb_1$ and $\Hilb_2$, and write $\Hilb = \Hilb_1 \oplus \Hilb_2$, if $\Hilb_1$ and $\Hilb_2$ are closed subspaces of $\Hilb$ satisfying:  
\begin{itemize}
    \item $\langle f_1 ,f_2\rangle=0$ whenever $f_1 \in \Hilb_1$ and $f_2 \in \Hilb_2$, and  
    \item for every $f \in \Hilb$, there exist $f_1 \in \Hilb_1$ and $f_2 \in \Hilb_2$ such that $f = f_1 + f_2$.  
\end{itemize}
Note that in this case, $f_1$ and $f_2$ are uniquely determined by $f$. In fact, $f_1$ equals the orthogonal projection of $f$ onto the subspace $\Hilb_1$, whereas $f_2$ is the orthogonal projection of $f$ onto $\Hilb_2$.

Let us now state von Neumann's mean ergodic theorem in an equivalent form.
\begin{theorem}[Mean ergodic theorem]
\label{thm_MET}
Let $U \colon \Hilb\to\Hilb$ be a unitary operator on a Hilbert space $\Hilb$. Then $\Hilb= \Hilb_{\mathrm{inv}}\oplus \Hilb_{\mathrm{erg}}$, where
\[
\Hilb_{\mathrm{inv}}=\{f\in\Hilb: Uf=f\}\qquad\text{and}\qquad
\Hilb_{\mathrm{erg}}=\Big\{f\in\Hilb: \lim_{H\to\infty}\Big\|\E_{h\in[H]}U^hf\Big\| = 0\Big\}.
\]
\end{theorem}

A proof of \cref{thm_MET} can be found in any standard book on ergodic theory, for example \cite[Theorem 1.2]{Petersen83}. We will use the following well-known corollary of \cref{thm_MET}.

\begin{corollary}[cf.~{\cite[p.~14]{Bergelson96}}]
\label{cor_rat_toterg_splitting}
Let $U \colon \Hilb\to\Hilb$ be a unitary operator on a Hilbert space $\Hilb$. Then
$\Hilb= \Hilb_{\mathrm{rat}}\oplus \Hilb_{\mathrm{tot\,erg}}$, where
\begin{align*}
\Hilb_{\mathrm{rat}}&=\overline{\big\{f\in\Hilb:~\exists q\in\N,~ U^{q}f=f\big\}},
\\
\Hilb_{\mathrm{tot\,erg}}&=\Big\{f\in\Hilb: \forall q\in \N,~\lim_{H\to\infty}\Big\|\E_{h\in[H]}U^{qh}f\Big\| = 0\Big\}.
\end{align*}
\end{corollary}

\begin{proof}
For every $q\in\N$ define
\[
\Hilb_{\mathrm{inv},q}=\{f\in\Hilb: U^qf=f\}\quad\text{and}\quad
\Hilb_{\mathrm{erg},q}=\Big\{f\in\Hilb: \lim_{H\to\infty}\Big\|\E_{h\in[H]}U^{qh}f\Big\| = 0\Big\}.
\]
By \cref{thm_MET}, we have $\Hilb= \Hilb_{\mathrm{inv},q}\oplus \Hilb_{\mathrm{erg},q}$ for all $q\in\N$. Therefore,
\[
\Hilb= \overline{\bigcup_{q\in\N} \Hilb_{\mathrm{inv},q}}\,\oplus\, \bigcap_{q\in\N} \Hilb_{\mathrm{erg},q}.
\]
It is now straightforward to verify that $\Hilb_{\mathrm{rat}}=\overline{\bigcup_{q\in\N} \Hilb_{\mathrm{inv},q}}$ and $\Hilb_{\mathrm{tot\,erg}}=\bigcap_{q\in\N} \Hilb_{\mathrm{erg},q}$, and the proof is complete.
\end{proof}

\subsection{Preliminaries from Fourier analysis}

Throughout this paper, we identify the one-dimensional torus $\T = \R/\Z$ with the interval $[0,1)$, endowed with addition modulo $1$. This allows us to treat elements of $\T$ as real numbers in $[0,1)$, which simplifies notation. As above, we use the abbreviation $e(x) = e^{2\pi i x}$ for $x \in \R$.

Let $\mu$ be a finite Borel measure on $\T$. The \define{Fourier transform} of $\mu$ on $\T$ is the function $\hat{\mu}\colon \Z\to\C$ defined as 
\[
\hat\mu(m)=\int_{\T} e(mx)\d\mu(x),\qquad\forall m\in\Z.
\]
Since $\mu$ is a finite measure, we have $|\hat{\mu}(m)|\leq \hat{\mu}(0)=\mu(\T)<\infty$ for all $m\in\Z$, and hence $\hat{\mu}$ is a bounded function.
It is natural to ask what type of bounded functions on $\Z$ correspond to the Fourier transform of a finite Borel measure on $\T$. The answer to this question is provided by a classical result in Fourier analysis known as Herglotz's theorem. 

A function $\varphi\colon\Z\to\C$ is called \define{non-negative definite} if for all $M\in\N$ and $\lambda_1,\ldots,\lambda_M\in\C$ one has
\[
\sum_{i,j=1}^M \lambda_i\overline{\lambda_j}\varphi(i-j)\geq 0.
\]
Equivalently, $\varphi$ is \define{non-negative definite} if for any $M\in\N$ the matrix $A\in\C^{M\times M}$ defined by $A_{i,j}=\varphi(i-j)$ for all $1\leq i,j\leq M$ is a non-negative definite matrix.

\begin{theorem}[Herglotz's theorem]
\label{thm_herglotz}
Let $\varphi\colon\Z\to\C$ be bounded. Then $\varphi$ is non-negative definite if and only if there exists a finite Borel measure $\mu$ on $\T=\R/\Z$ such that $\varphi=\hat{\mu}$, or in other words,
\[
\varphi(m)=\int_{\T} e(mx)\d\mu(x),\qquad\forall m\in\Z.
\]
\end{theorem}

If $\A\subset\ell^\infty(\Z)$ is a translation invariant $C^*$-subalgebra that admits logarithmic averages along an increasing sequence $\bN=(N_s)_{s\in\N}$ (see \cref{def_algebra_properties}), then it is straightforward to check that for any $f\in\A$ the function
\[
m\mapsto \logE_{n\in\bN} f(n)\overline{f(n+m)}
\]
is non-negative definite. By Herglotz's theorem, there exists a finite Borel measure $\mu_f$ on $\T$ such that
\begin{equation}
\label{eqn_spectral_measure}
\logE_{n\in\bN} f(n)\overline{f(n+m)}=\hat\mu_f(m)=\int_{\T} e(mx)\d\mu_f(x).
\end{equation}
We call $\mu_f$ the \define{spectral measure of $f$}.

\begin{lemma}
\label{lem_spectral_measure_isometry_property}
Let $N_1<N_2<\ldots\in\N$, and let $\A\subset\ell^\infty(\Z)$ be an affinely invariant $C^*$-subalgebra that admits logarithmic averages along $\bN=([N_s])_{s\in\N}$. Then for any $\ell\in\N$, $m_1,\ldots,m_\ell\in\Z$, $c_1,\ldots, c_\ell\in\C$, and $f\in\A$ we have
\[
\logE_{n\in\bN} \bigg| \sum_{i=1}^\ell c_i f(n+m_i)\bigg|^2
=
\int_\T\bigg| \sum_{i=1}^\ell c_i e(m_ix)\bigg|^2\d\mu_f(x),
\]
where $\mu_f$ denotes the spectral measure of $f$.
\end{lemma}

\begin{proof}
By expanding the square and rearranging, we can rewrite the left hand side as
\begin{align*}
\logE_{n\in\bN} \bigg| \sum_{i=1}^\ell c_i f(n+m_i)\bigg|^2
&=\sum_{i,j=1}^\ell c_i\overline{c_j}\, \logE_{n\in\bN}
f(n+m_i)\overline{f(n+m_j)}
\\
&=\sum_{i,j=1}^\ell c_i\overline{c_j}\, \logE_{n\in\bN} f(n)\overline{f(n+m_j-m_i)}.
\end{align*}
Let $\mu_f$ denote the spectral measure of $f$.
If we now use \eqref{eqn_spectral_measure}, reorder, and collapse the resulting expression back into a square, we obtain
\begin{align*}
\sum_{i,j=1}^\ell c_i\overline{c_j}\, \logE_{n\in\bN} f(n)\overline{f(n+m_j-m_i)}
&=\sum_{i,j=1}^\ell c_i\overline{c_j} \int_\T e((m_j-m_i)x)\d\mu_f(x)
\\
&=\int_\T\bigg| \sum_{i=1}^\ell c_i e(m_ix)\bigg|^2\d\mu_f(x).
\end{align*}
This completes the proof.
\end{proof}

\section{The structure theorem}

Many proofs in combinatorics depend on some type of structure theorem that allows one to decompose a given objet (such as a set, function, or graph) into two components, a ``structured'' component that is responsible for the main behavior and can be analyzed using combinatorial methods, and a ``random'' component that represents noise and can be dealt with using probabilistic techniques; see \cite{Tao07b} for a survey.
The proofs of our main theorems also follow this strategy, and the purpose of this section is to introduce the structure theorem on which our arguments rely.

\subsection{Statement of the structure theorem}

\begin{definition}
Let $\bN=(N_s)_{s\in\N}$ with $N_1<N_2<\ldots\in\N$, and let $\A\subset\ell^\infty(\Z)$ be a translation invariant $C^*$-subalgebra that admits logarithmic averages along $\bN$.
\begin{itemize}
\item 
We say $f\in\A$ is \define{locally aperiodic (with respect to logarithmic averages along~$\bN$)} if for all $q\in\Z\setminus\{0\}$ we have
\[
\lim_{H\to\infty}\logE_{n\in \bN}\Big|\E^{\phantom{\log{}}}_{h\in [H]}\, f(n+qh)\Big|^2=0.
\]   
\item 
We say $f\in\A$ is \define{locally quasiperiodic (with respect to logarithmic averages along~$\bN$)} if for all $\epsilon>0$ there exists some $q\in\N$ such that 
\[
\sup_{m\in\N}\Big(\logE_{n\in\bN}\big|f(n+qm)-f(n)\big|^2\Big)\leq \epsilon.
\]
\end{itemize}
\end{definition}

Note that the collection of all locally aperiodic elements of $\A$ forms a closed subspace of $\A$ that is invariant under complex conjugation, whereas the collection of all locally quasiperiodic elements of $\A$ forms a $C^*$-subalgebra of $\A$. Additional convenient properties of locally quasiperiodic and locally aperiodic functions are collected in \cref{lem_basic_properties_locally_periodic_locally_aperiodic} at the end of this subsection, and in \cref{sec_spectral_char_locally_periodic_locally_aperiodic}.

\begin{theorem}[Structure Theorem]
\label{thm_str}
Let $\bN=(N_s)_{s\in\N}$ with $N_1<N_2<\ldots\in\N$, and let $\A\subset\ell^\infty(\Z)$ be a separable and translation invariant $C^*$-subalgebra that admits logarithmic averages along $\bN$.
Then there exists a separable and translation invariant $C^*$-subalgebra $\A'\subset\ell^\infty(\Z)$ that admits logarithmic averages along $\bN$, contains $\A$ as a subset, and such that the following holds:
For all $f\in\A'$ there exist $f_{\str},f_{\rnd}\in \A'$ with
\[
f=f_{\str}+f_{\rnd},
\]
where $f_{\str}$ is locally quasiperiodic with respect to logarithmic averages along $\bN$ and $f_{\rnd}$ is locally aperiodic with respect to logarithmic averages along $\bN$. Moreover, if $f$ takes values in a closed interval $[a,b]\subset\R$ then the same holds for $f_{\str}$.
\end{theorem}

\cref{thm_str} can be viewed as an integer analogue of \cref{cor_rat_toterg_splitting}. Similar structure theorems in the integers were obtained in \cite{MRR19}.
The proof of \cref{thm_str} is given in \cref{sec_proof_str_thm}.

\begin{remark}
It will be clear from the construction used in the proof of \cref{thm_str} that
if $\A$ is affinely invariant then the $C^*$-supalgebra $\A'$ guaranteed by \cref{thm_str} is also affinely invariant.
Similarly, if $\bPW=(\P_W\cap[M_{t_k}])_{t\in\N}$, where $M_1<M_2<\ldots\in\N$ and $W\in\N$, and $\A$ admits iterated affine correlations along $\bPW$ (see~\cref{def_algebra_properties}), then so does $\A'$.
\end{remark}


\begin{lemma}[Basic properties of locally quasiperiodic and aperiodic functions]
\label{lem_basic_properties_locally_periodic_locally_aperiodic}
Let $\bN=(N_s)_{s\in\N}$ with $N_1<N_2<\ldots\in\N$, and let $\A\subset\ell^\infty(\Z)$ be a translation invariant $C^*$-subalgebra that admits logarithmic averages along $\bN$.
Suppose $f\in\A$ is locally quasiperiodic and $g\in\A$ is locally aperiodic. Then:
\begin{enumerate}
[label=(\roman{enumi}),ref=(\roman{enumi}),leftmargin=*]
\item
\label{itm_basic_properties_locally_periodic_locally_aperiodic_i}
$f$ and $g$ are orthogonal, i.e., $\E^{\log}_{n\in\bN} f(n)\overline{g(n)}=0$;
\item
\label{itm_basic_properties_locally_periodic_locally_aperiodic_ii}
For all $b\in\Z$, $f\circ\tau^b$ is locally quasiperiodic and $g\circ\tau^b$ is locally aperiodic;
\item
\label{itm_basic_properties_locally_periodic_locally_aperiodic_iii}
If $\A$ is affinely invariant then for all $a\in\N$, $f\circ\sigma_a$ is locally quasiperiodic and $g\circ\sigma_a$ is locally aperiodic.
\end{enumerate}
\end{lemma}

Each of the parts \ref{itm_basic_properties_locally_periodic_locally_aperiodic_i}--\ref{itm_basic_properties_locally_periodic_locally_aperiodic_iii} is straightforward to verify using the definition of locally quasiperiodic and locally aperiodic functions, and we therefore omit their proofs.

\subsection{Outlining the proofs of Theorems~\ref{thm_1_tech} and~\ref{thm_2_tech}}
\label{sec_outline_of_proof}


We now explain how the structure theorem provides a useful framework for proving both Theorems~\ref{thm_1_tech} and~\ref{thm_2_tech}.
To albeit with the hypothesis in Theorems~\ref{thm_1_tech} and~\ref{thm_2_tech}, let us assume for the reminder of this section that $N_1<N_2<\ldots\in\N$ and $M_1<M_2<\ldots\in\N$ are two increasing integer sequences, and $\A\subset\ell^\infty(\Z)$ is a separable, affinely invariant $C^*$-subalgebra that admits logarithmic averages along $\bN=([N_s])_{s\in\N}$ and iterated affine correlations along $\bPW=(\P_W\cap [M_t])_{t\in\N}$ for all $W\in\N$.

By replacing $\A$ with the $C^*$-subalgebra $\A'\subset\ell^\infty(\Z)$ guaranteed by \cref{thm_str}, we can assume without loss of generality that $\1_A\in\A$ splits into two components,
\begin{equation}
\label{eqn_splitting_of_A}
\1_A=f_{\str}+f_{\rnd},
\end{equation}
where $f_{\str}\in\A$ is locally quasiperiodic and $f_{\rnd}\in\A$ is locally aperiodic. Also, since $\1_A$ is non-negative, it follows that the function $f_{\str}$ is non-negative too, which will be important for technical reasons later on.

The next theorem lets us conclude that the structured component $f_{\rnd}$ in the decomposition $\1_A=f_{\str}+f_{\rnd}$ does not contribute to the averages in \eqref{eqn_1_tech} and \eqref{eqn_2_tech}. This will allow us to ``ignore'' $f_{\rnd}$ and focus solely on $f_{\str}$ in the proofs of Theorems~\ref{thm_1_tech} and~\ref{thm_2_tech}.

\begin{theorem}[Handling the ``random'' component]
\label{thm_rnd_component}
If $f\in\A$ is locally aperiodic with respect to logarithmic averages along $\bN$, then for all $k,W,a\in\N$ with $k\geq 2$, all $g\in\A$, and all non-constant polynomials $Q$ with integer coefficients we have
\[
\logE_{p\in\bPW^{*k}}\logE_{n\in\bN} f\big(an+Q(p)\big)g(pn)=0.
\]
\end{theorem}

A proof of \cref{thm_rnd_component} is given in \cref{sec_proof_of_thm_rnd_component}.

The next theorem can be viewed as a (somewhat technical) generalization of a
theorem of Ahlswede, Khachatrian, and \Sarkozy{} \cite{AKS99}, which in turn was a generalization of the aforementioned result of Davenport and \Erdos{} \cite{DE36,DE51}.

\begin{theorem}[Handling the ``structured'' component]
\label{thm_str_component}
Suppose $a_1,a_2,\ldots\in\N$ and $f\in\A$ with $f(n)\geq 0$ for all $n\in\N$.
Then for any $\epsilon>0$ and any $W\in\N$ there are $k\geq 2$ and an infinite set $I\subset\N$, such that for all $i,j\in I$ with $i<j$ we have
\begin{equation*}
\logE_{p\in\bPW^{*k}} \logE_{n\in \bN} f(a_in)f(a_jpn) \geq  \Big(\limsup_{j\to\infty}\logE_{n\in\bN} f(a_jn)\Big)^2-\epsilon.    
\end{equation*}
\end{theorem}

A proof of \cref{thm_str_component} can be found in \cref{sec_proof_of_thm_str_component}. 
We now explain why Theorems~\ref{thm_rnd_component} and~\ref{thm_str_component} are enough to derive Theorems~\ref{thm_1_tech} and~\ref{thm_2_tech}.

\begin{proof}[Proof of \cref{thm_1_tech} assuming Theorems~\ref{thm_rnd_component} and~\ref{thm_str_component}]
Fix $\epsilon>0$. Or goal is to find $W\geq 1$ and $k\geq 2$ such that
\begin{equation}
\label{eqn_1_tech_1}
\logE_{p\in\bPW^{*k}} \logE_{n\in \bN} \1_A(n+Q(p))\1_A(pn)\geq \Big(\logE_{n\in\bN} \1_A(n)\Big)^2-\epsilon.
\end{equation}
If $Q$ is a constant polynomial then the condition $Q(1)=0$ implies that $Q=0$. In this case, 
\eqref{eqn_1_tech_1} follows from \cref{thm_str_component} applied with $f(n)=1_A(n)$ and $a_1=a_2=\ldots=1$.

If $Q$ is non-constant then we proceed as follows. 
Using the decomposition \eqref{eqn_splitting_of_A}, we can rewrite the left hand side as
\begin{align*}
\logE_{p\in\bPW^{*k}} & \logE_{n\in \bN} \1_A(n+Q(p))\1_A(pn) 
\\ 
&=\logE_{p\in\bPW^{*k}} \logE_{n\in \bN} f_{\str}(n+Q(p))f_{\str}(pn)+\overbrace{\logE_{p\in\bPW^{*k}} \logE_{n\in \bN}f_{\str}(n+Q(p))f_{\rnd}(pn)}^{[1]}
\\
&\quad+\underbrace{\logE_{p\in\bPW^{*k}} \logE_{n\in \bN}f_{\rnd}(n+Q(p))f_{\str}(pn)}_{[2]}+\underbrace{\logE_{p\in\bPW^{*k}} \logE_{n\in \bN} f_{\rnd}(n+Q(p))f_{\rnd}(pn)}_{[3]}.
\end{align*}
By \cref{lem_basic_properties_locally_periodic_locally_aperiodic}, we have for all $p$,
\[
\logE_{n\in \bN}f_{\str}(n+Q(p))f_{\rnd}(pn)=0\qquad\text{and}
\qquad \logE_{n\in \bN}f_{\rnd}(n+Q(p))f_{\str}(pn)=0.
\]
This shows that the cross terms {\small[1]} and {\small[2]} disappear, and only the diagonal terms remain. Moreover, in light of \cref{thm_rnd_component} (applied with $f(n)=f_{\rnd}(n)$, $g(n)=f_{\rnd}(n)$, and $a=1$), the final term {\small[3]} also does not contribute to the average for any $W,k\in\N$ as long as $k\geq 2$. This proves that
\begin{align*}
\logE_{p\in\bPW^{*k}} \logE_{n\in \bN} \1_A(n+Q(p))\1_A(pn) 
=\logE_{p\in\bPW^{*k}} \logE_{n\in \bN} f_{\str}(n+Q(p))f_{\str}(pn).
\end{align*}
Since $f_{\str}$ is locally quasiperiodic, there exists $W\in\N$ such that
\[
\sup_{m'\in\N}\Big(\logE_{n\in\bN}\big|f_{\str}(n+Wm')-f_{\str}(n)\big|^2\Big)\leq \frac{\epsilon^2}{4}.
\]
Using $Q(1)=0$, we see that for every $m\in\N$ there is $m'\in\N$ such that $Q(Wm+1)=m'W$. 
Since any $p=p_1\cdots p_k$, where $p_1,\ldots,p_k\in\P_W$, can be written in the form $Wm+1$ for some $m\in\N$, it follows that
\[
\logE_{p\in\bPW^{*k}}\logE_{n\in\bN}\big|f_{\str}(n+Q(p))-f_{\str}(n)\big|^2\leq \frac{\epsilon^2}{4}.
\]
Therefore, using the Cauchy-Schwarz inequality, we get
\begin{equation}
\label{eqn_1_tech_2}
\logE_{p\in\bPW^{*k}} \logE_{n\in \bN} \1_A(n+Q(p))\1_A(pn) 
\geq \logE_{p\in\bPW^{*k}} \logE_{n\in \bN} f_{\str}(n)f_{\str}(pn)-\frac{\epsilon}{2}.
\end{equation}
Finally, note that $\E^{\log}_{n\in\bN} f_{\rnd}(n)=0$ and hence $\E^{\log}_{n\in\bN}f_{\str}(n)=\E^{\log}_{n\in\bN}\1_A(n)$.
So it follows from \cref{thm_str_component}, applied with $f(n)=f_{\str}(n)$ and $a_1=a_2=\ldots=1$, that there is some $k\geq 2$ for which we have
\begin{equation}
\label{eqn_1_tech_3}
\logE_{p\in\bPW^{*k}} \logE_{n\in \bN} f_{\str}(n)f_{\str}(pn)\geq \Big(\logE_{n\in\bN} f_{\str}(n)\Big)^2-\frac{\epsilon}{2}= \Big(\logE_{n\in\bN} \1_A(n)\Big)^2-\frac{\epsilon}{2}.
\end{equation}
Since \eqref{eqn_1_tech_2} and \eqref{eqn_1_tech_3} combined imply \eqref{eqn_1_tech_1}, the proof is finished.
\end{proof}

\begin{proof}[Proof of \cref{thm_2_tech} assuming Theorems~\ref{thm_rnd_component} and~\ref{thm_str_component}]
We use an argument that parallels the one used above to show that Theorems~\ref{thm_rnd_component} and~\ref{thm_str_component} imply \cref{thm_1_tech}.
Fix $\epsilon>0$ and let $a_1,a_2,\ldots\in\N$ be a divisible sequence. Our goal is to find $k\geq 2$ and $\{u,vu\}\subset \{a_j:j\in\N\}$ such that
\begin{equation}
\label{eqn_2_tech_1}
\logE_{p\in\bP^{*k}}\logE_{n\in\bN} \1_A(un+Q(vp))\1_A(uvpn) \geq \Big(\limsup_{j\to\infty}\logE_{n\in\bN} \1_A(a_jn)\Big)^2-\epsilon.
\end{equation}
By replacing $(a_j)_{j\in\N}$ with a subsequence of itself if necessary, we can assume without loss of generality that $a_{j+1}$ is a multiple of $a_j$ for all $j\in\N$. This can be done in a way that leaves $\limsup_{j\to\infty}\E^{\log}_{n\in\bN} \1_A(a_jn)$ unchanged.

If $Q$ is constant then $Q(0)=0$ implies $Q=0$. If this is the case then \eqref{eqn_2_tech_1} is a consequence of \cref{thm_str_component}, taking $u=a_i$ and $v=\frac{a_j}{a_i}$.
Therefore, we can assume for the remainder of this proof that $Q$ is non-constant.

Arguing as above, we can use \eqref{eqn_splitting_of_A} to split $\1_A$ into  a ``structured'' component $f_{\str}$ and a ``random'' component $f_{\rnd}$. Consequently, the left hand side of \eqref{eqn_2_tech_1} splits into four terms. The cross terms involving one ``structured'' component $f_{\str}$ and one ``random'' component $f_{\rnd}$ are $0$ due to orthogonality, see \cref{lem_basic_properties_locally_periodic_locally_aperiodic}. Moreover, the term involving twice the ``random'' component $f_{\rnd}$ is $0$ because of \cref{thm_rnd_component} (applied with $f(n)=f_{\rnd}(n)$, $g(n)=f_{\rnd}(a_jn)$, $W=1$, $a=a_i$, and $b=\frac{a_j}{a_i}$). This gives that
\begin{equation}
\label{eqn_2_tech_4}
\logE_{p\in\bP^{*k}} \logE_{n\in \bN} \1_A\big(a_in+Q\big(\tfrac{a_jp}{a_i}\big)\big)\1_A(a_jpn) 
=\logE_{p\in\bP^{*k}} \logE_{n\in \bN} f_{\str}\big(a_in+Q\big(\tfrac{a_jp}{a_i}\big)\big)f_{\str}(a_jpn).
\end{equation}
Invoking \cref{thm_str_component} (with $f(n)=f_{\str}(n)$ and $W=1$), we can find $k\geq 2$ and an infinite set $I\subset\N$, such that for all $i,j\in I$ with $i<j$ we have
\[
\logE_{p\in\bP^{*k}}\logE_{n\in\bN} f_{\str}\big(a_in\big)f_{\str}(a_jpn) \geq  \Big(\limsup_{j\to\infty}\logE_{n\in\bN} f_{\str}(a_jn)\Big)^2-\frac{\epsilon}{2}.
\]
Since $\E^{\log}_{n\in\bN}f_{\str}(bn)=\E^{\log}_{n\in\bN}\1_A(bn)$ for all $b\in\N$, this implies that
\begin{equation}
\label{eqn_2_tech_2}
\logE_{p\in\bP^{*k}}\logE_{n\in\bN} f_{\str}\big(a_in\big)f_{\str}(a_jpn) \geq  \Big(\limsup_{j\to\infty}\logE_{n\in\bN} \1_A(a_jn)\Big)^2-\frac{\epsilon}{2}.
\end{equation}

Let $i\in I$ be fixed for the remainder of this proof.
Using that $f_{\str}$ is locally quasiperiodic, there exists $q\in\N$ such that
\[
\sup_{m\in\N}\Big(\logE_{n\in\bN}\big|f_{\str}(a_in+qm)-f_{\str}(a_in)\big|^2\Big)\leq \frac{\epsilon^2}{4}.
\]
Since $(a_j)_{j\in \N}$ is divisible, there exist $j\in I$ such that $a_j$ is a multiple of $qa_i$.
Since $Q(0)=0$, for any $p$ the number $Q(\frac{a_jp}{a_i})$ is a multiple of $q$.
It follows that for all $p$ we have
\begin{equation}
\label{eqn_2_tech_5}
\logE_{n\in\bN}\big|f_{\str}\big(a_in+Q\big(\tfrac{a_jp}{a_i}\big)\big)-f_{\str}(a_in)\big|^2\leq \frac{\epsilon^2}{4}.
\end{equation}
Applying \eqref{eqn_2_tech_5} and the Cauchy-Schwarz inequality to \eqref{eqn_2_tech_4}, we can conclude that
\begin{equation}
\label{eqn_2_tech_3}
\logE_{p\in\bP^{*k}} \logE_{n\in \bN} \1_A\big(a_in+Q\big(\tfrac{a_jp}{a_i}\big)\big)\1_A(a_jpn) 
\geq \logE_{p\in\bP^{*k}} \logE_{n\in \bN} f_{\str}(a_in)f_{\str}(a_jpn)-\frac{\epsilon}{2}.
\end{equation}
Since \eqref{eqn_2_tech_2} and \eqref{eqn_2_tech_3} give \eqref{eqn_2_tech_1}, we can take $u=a_i$ and $v=\frac{a_j}{a_i}$ and the proof is complete.
\end{proof}


\section{Proof of the structure theorem}
\label{sec_proof_str_thm}

The purpose of this section is to prove \cref{thm_str}.
As noted previously, it is natural to interpret \cref{thm_str} as a discrete analogue of \cref{cor_rat_toterg_splitting}, and the main idea behind its proof is to transfer \cref{cor_rat_toterg_splitting} from the setting of unitary operators on Hilbert spaces to the setting of the translation operator acting on bounded functions over the integers.

\subsection{The Hilbert space $\mathcal{L}^2(\A, \bN)$}
Let $\bN=(N_s)_{s\in\N}$ with $N_1<N_2<\ldots\in\N$, and let $\A\subset\ell^\infty(\Z)$ be a $C^*$-subalgebra that admits logarithmic averages along $\bN$.
Consider the space
\begin{equation*}
\mathscr{L}^2(\A, \bN) = \left\{ f : \Z \to \C : \forall \epsilon > 0,~\exists g \in \A, \limsup_{s \to \infty} \logE_{n\in[N_s]}|f(n) - g(n)|^2 < \epsilon \right\}.
\end{equation*}
We can define an equivalence relation on $\mathscr{L}^2(\A, \bN)$ via
\[
f \sim g\quad\iff\quad \logE_{n \in \bN} |f(n) - g(n)|^2 = 0.
\]
For any function $f\in \mathscr{L}^2(\A,\bN)$, let $[f]_\sim$ denote the equivalence class of $f$ with respect to $\sim$, and let
\[
\mathcal{L}^2(\A,\bN)=\mathscr{L}^2(\A, \bN)/\sim
\]
denote the quotient space of $\mathscr{L}^2(\A,\bN)$ by $\sim$.
Note that pointwise addition, pointwise multiplication, scalar multiplication, and complex conjugation on $\mathscr{L}^2(\A, \bN)$ factor through to $\mathcal{L}^2(\A,\bN)$ via
\begin{align*}
[f]_\sim+[g]_\sim &=[f+g]_\sim,
\\
[f]_\sim \cdot [g]_\sim &=[f\cdot g]_\sim,
\\
c[f]_\sim&=[cf]_\sim,
\\
\overline{[f]_\sim}&=\big[\overline{f}\big]_\sim,
\end{align*}
for all $f,g\in \mathscr{L}^2(\A,\bN)$ and $c\in\C$.
This shows that $\mathcal{L}^2(\A, \bN)$ is a vector space over $\C$.
If one considers \Cesaro{} averages instead of logarithmic averages, it was shown by Farhangi in \cite[Theorem 2.1]{Farhangi24} that $\mathcal{L}^2(\A, \bN)$ is actually a Hilbert space.
It is straightforward to adapt Farhangi's argument to our situation; for completeness we include a proof below. 

\begin{theorem}
\label{thm_farhangi}
    The space $\mathcal{L}^2(\A, \bN)$ is a Hilbert space with inner product
\begin{equation*}
\langle [f]_\sim,[g]_\sim\rangle = \logE_{n \in \bN} f(n)\overline{g(n)}.
\end{equation*}
\end{theorem}

\begin{proof}
It is clear that $\mathcal{L}^2(\A,\bN)$ is an inner product space; to prove that it is a Hilbert space it therefore remains to verify that it is complete.
For the remainder of this proof we abuse notation and identify each function in $\mathcal{L}^2(\A,\bN)$  with an arbitrarily chosen representative in its equivalency class in $\mathscr{L}^2(\A, \bN)$.
Let $(f_i)_{i \in \N}$ be a Cauchy sequence in $\mathcal{L}^2(\A,\bN)$. Choose $\epsilon_i \to 0$ such that for every $i,j\in\N$,
\[
\logE_{n \in \bN}|f_j(n) - f_i(n)|^2 \leq \epsilon_{\min\{i,j\}}.
\]
This means for any $i,j\in\N$ there exists some $s_{i,j}\in\N$ such that for every $s\geq s_{i,j}$ we have
\[
\logE_{n \in [N_s]}|f_j(n) - f_i(n)|^2 \leq  2\epsilon_{\min\{i,j\}}.
\]
Now we define $s_0=0$ and $s_j=\max\{s_{1,j},s_{2,j},\ldots,s_{j,j}\}$ for $j\geq 1$.
Then for all $i,j\in\N$ with $i\leq j$ and all $s\geq s_j$ we have
\begin{equation}
\label{eqn_SF_1}
\logE_{n \in [N_s]}|f_j(n) - f_i(n)|^2 \leq  2\epsilon_{i}.
\end{equation}
By replacing $(s_j)$ with a subsequence of itself if necessary, we can assume that $s_j$ is sufficiently larger relative to $s_{j-1}$ so that
\begin{equation}
\label{eqn_SF_2}
\Big(\max_{n\in[N_{s_{j-1}}]}\max_{\ell\leq j-1}|f_\ell(n)|^2\Big)\frac{\sum_{n\in [N_{s_{j-1}}]}\frac{1}{n}}{\sum_{n\in[N_{s_j}]}\frac{1}{n}}\to 0~\text{as}~j\to\infty.
\end{equation}
Define
\[
f(n)=\sum_{i\in\N} \1_{(N_{s_{i-1}},N_{s_i}]}(n) f_i(n).
\]
Then for any $i\in\N$ and $s_{j-1}<s\leq s_{j}$ we have
\begin{align*}
 \logE_{n \in [N_s]} |f(n) - f_i(n)|^2
&=\sum_{\ell=1}^j \logE_{n \in [N_s]}\1_{(N_{s_{\ell-1}},N_{s_\ell}]}(n)|f(n) - f_i(n)|^2
\\
&=\sum_{\ell=1}^j \logE_{n \in [N_s]}\1_{(N_{s_{\ell-1}},N_{s_\ell}]}(n)|f_\ell(n) - f_i(n)|^2
\\
&= [1]+[2]+[3],
\end{align*}
where
\begin{align*}
[1]=\sum_{\ell=1}^{j-2} \logE_{n \in [N_s]}\1_{(N_{s_{\ell-1}},N_{s_\ell}]}(n)|f_\ell(n) - f_i(n)|^2,
\\
[2]=\logE_{n \in [N_s]}\1_{(N_{s_{j-2}},N_{s_{j-1}}]}(n)|f_{j-1}(n) - f_i(n)|^2,
\\
[3]=\logE_{n \in [N_s]}\1_{(N_{s_{j-1}},N_{s_j}]}(n)|f_{j}(n) - f_i(n)|^2.
\end{align*}
It follows from \eqref{eqn_SF_1} that $[2]\leq 2\epsilon_i$ as well as $[3]\leq 2\epsilon_i$. For $[1]$, we have the estimate
\begin{align*}
[1]&\leq 2\Big(\max_{n\in[N_{s_{j-2}}]}\max_{\ell\leq j-2}|f_\ell(n)|^2\Big)\logE_{n \in [N_s]}\1_{[1,N_{s_{j-2}}]}(n),
\\
&\leq 2\Big(\max_{n\in[N_{s_{j-2}}]}\max_{\ell\leq j-2}|f_\ell(n)|^2\Big)\frac{\sum_{n\in [N_{s_{j-2}}]}\frac{1}{n}}{\sum_{n\in[N_{s_{j-1}}]}\frac{1}{n}}.
\end{align*}
Therefore, \eqref{eqn_SF_2} implies that $[1]=\oh_{j\to\infty}(1)$. Combining all of the above shows
\[
\limsup_{s\to\infty}\logE_{n \in [N_s]} |f(n) - f_i(n)|^2\leq 4\epsilon_i,
\]
which implies that the Cauchy sequence $(f_i)_{i\in\N}$ converges to $f$. This proves that $\mathcal{L}^2(\A,\bN)$ is complete.
\end{proof}

\subsection{Proof of \cref{thm_str}}

\begin{proof}[Proof of \cref{thm_str}]
Let $\mathscr{L}^2(\A,\bN)$ and $\mathcal{L}^2(\A,\bN)$ be as defined above, and define $\A'=\mathscr{L}^2(\A,\bN)\cap\ell^\infty(\Z)$. Note that if $\A$ is separable (resp.~translation invariant/dilation invariant/admits iterated affine correlations along $\bPW$) then $\A'$ has the same property. Moreover, due to \cref{thm_farhangi}, $\mathcal{L}^2(\A,\bN)$ is a Hilbert space with inner product $\langle [f]_\sim, [g]_\sim\rangle=\E^{\log}_{n\in\bN} f(n)\overline{g(n)}$ and norm $\|[f]_\sim\|=(\E^{\log}_{n\in\bN}|f(n)|^2)^{1/2}$.
Define an operator $U\colon \mathcal{L}^2(\A,\bN)\to \mathcal{L}^2(\A,\bN)$ via
\[
U[f]_\sim=[f\circ \tau]_\sim,\qquad\forall [f]_\sim\in \mathcal{L}^2(\A,\bN),
\]
where $\tau(n)=n+1$ is the shift map defined in \eqref{eqn_def_dilation_translation}.
Since logarithmic averages are shift invariant, we see that $\langle U[f]_\sim,U[g]_\sim\rangle =\langle [f]_\sim,[g]_\sim\rangle$. In other words, $U$ is a unitary operator on $\mathcal{L}^2(\A,\bN)$. 
It follows from \cref{cor_rat_toterg_splitting} that 
$\mathcal{L}^2(\A,\bN)=\Hilb_{\mathrm{rat}}\oplus \Hilb_{\mathrm{tot\,erg}}$, where $\Hilb_{\mathrm{rat}}$ and $\Hilb_{\mathrm{tot\,erg}}$ are as defined in the statement of \cref{cor_rat_toterg_splitting}.
It is now easy to check that $[f]_\sim\in \Hilb_{\mathrm{rat}}$ if and only if $f$ locally quasiperiodic with respect to logarithmic averages along $\bN$, and similarily $[f]_\sim\in\Hilb_{\mathrm{tot\,erg}}$ if and only if $f$ is locally aperiodic with respect to logarithmic averages along $\bN$. It follows that for any $f\in\A'$ we can find 
$f_{\str},f_{\rnd}\colon \N\to\C$ such that 
$[f_{\str}]_{\sim}\in \Hilb_{\mathrm{rat}}$, $[f_{\rnd}]_{\sim}\in \Hilb_{\mathrm{tot\,erg}}$, and 
\[
f=f_{\str}+f_{\rnd}.
\]
It remains to show that we can take $f_{\str}$ and $f_{\rnd}$ to be bounded, or equivalently, that the equivalency classes of $f_{\str}$ and $f_{\rnd}$ contain representatives that belong to $\ell^\infty(\Z)$.

Suppose $f$ takes values in the closed interval $[a,b]$ for some $a\leq b\in\R$. If we truncate $f_{\str}$ above by $a$ and below by $b$, then the resulting function, let us call if $f_{\str}'$, also has the property that  $[f_{\str}']_\sim\in \Hilb_{\mathrm{rat}}$. Since $[f_{\str}]_\sim$ coincides with the orthogonal projection of $[f]_\sim$ onto $\Hilb_{\mathrm{rat}}$, we know that $[f_{\str}]_\sim$ is the unique element in $\Hilb_{\mathrm{rat}}$ that minimizes the distance between $[f]_\sim$ and $\Hilb_{\mathrm{rat}}$ within the Hilbert space $\mathcal{L}^2(\A,\bN)$. But the distance between $f_{\str}'$ and $f$ is no larger than the distance between $f_{\str}$ and $f$. By uniqueness, we conclude that $[f_{\str}']_\sim=[f_{\str}]_\sim$. 
This shows that with out loss of generality, we can assume that $f_{\str}$ takes values in $[a,b]$. In particular, both $f_{\str}$ and $f_{\rnd}$ are bounded and hence $f_{\str},f_{rnd}\in\A'$, completing the proof. 
\end{proof}

\section{Controlling the ``random'' component}

The goal of this section is to provide a proof of \cref{thm_rnd_component}. This proof has two main ingredients, a spectral characterization of locally aperiodic functions given in \cref{sec_spectral_char_locally_periodic_locally_aperiodic}, and a new multiplicative analogue of van der Corput's inequality proved in \cref{sec_multiplicative_vdC}.

\subsection{Spectral characterizations of locally quasiperiodic and aperiodic functions}
\label{sec_spectral_char_locally_periodic_locally_aperiodic}

Recall that we identify the torus $\T=\R/\Z$ with the interval $[0,1)$ in the natural way.
In particular, we call an element of $\T$ \define{rational} if it corresponds to a rational number in $[0,1)$, and \define{irrational} if it corresponds to an irrational number in $[0,1)$.
By abuse of language, we say that a finite Borel measure on $\T$ is supported on rational (resp.~irrational) numbers if the set of rational (resp.~irrational) numbers in $\T$ has full measure. 
\begin{theorem}
\label{thm_spectral_char_per_aper}
Let $\bN=(N_s)_{s\in\N}$ with $N_1<N_2<\ldots\in\N$, and let $\A\subset\ell^\infty(\Z)$ be a translation invariant $C^*$-subalgebra that admits logarithmic averages along $\bN$.
Let $f\in\A$. The following hold:
\begin{enumerate}
[label=(\roman{enumi}),ref=(\roman{enumi}),leftmargin=*]
\item
\label{itm_spectral_char_per_aper_i}
if $f$ is locally quasiperiodic then its spectral measure $\mu_f$ is supported on rational numbers.
\item
\label{itm_spectral_char_per_aper_ii}
if $f$ is locally aperiodic then its spectral measure $\mu_f$ is supported on irrational numbers.
\end{enumerate}
\end{theorem}

\begin{proof}
Suppose $f\in\ell^\infty(\Z)$, and let $\mu_f$ denote its spectral measure.
Using the dominated convergence theorem, we obtain for every $q\in\N$ that
\begin{align*}
\lim_{M\to\infty} \E_{m\in[M]}\hat\mu_f(qm)
&=\lim_{M\to\infty} \E_{m\in[M]}\int_{\T} e(qmx)\d\mu_f(x)  
\\
&=\int_{\T} \bigg( \lim_{M\to\infty} \E_{m\in[M]}(e(qmx)\bigg)\d\mu_f(x) 
\\
&=\int_{\T} \1_{\big\{0,\frac{1}{q},\ldots,\frac{q-1}{q}\big\}}(x)\d\mu_f(x).
\end{align*}
Therefore, we have for all $q\in\N$,
\begin{equation}
\label{eqn_spectral_char_per_aper_1}
\mu_f\big(\big\{0,\tfrac{1}{q},\ldots,\tfrac{q-1}{q}\big\}\big)= \lim_{M\to\infty} \E_{m\in[M]}\hat\mu_f(qm).
\end{equation}

We will use \eqref{eqn_spectral_char_per_aper_1} to prove both \ref{itm_spectral_char_per_aper_i} and \ref{itm_spectral_char_per_aper_ii}.
Let us first show \ref{itm_spectral_char_per_aper_i}. If $f$ is locally quasiperiodic then, by definition, for all $\epsilon>0$ there exists some $q\in\N$ such that
\[
\sup_{m\in\N}|\hat\mu_f(qm)-\hat\mu_f(0)|<\epsilon.
\]
This implies that
\[
\mu_f(\T)=\hat\mu_F(0)= \int_{\T} e(qmx)\d\mu_f(x) + \Oh(\epsilon),
\]
where the error term $\Oh(\epsilon)$ is independent of $m$. Averaging over $m$ and using \eqref{eqn_spectral_char_per_aper_1}, we obtain
\begin{align*}
\mu_f(\T)
= \mu_f\big(\big\{0,\tfrac{1}{q},\ldots,\tfrac{q-1}{q}\big\}\big)+ \Oh(\epsilon).
\end{align*}
In other words, up to an $\epsilon$-error, the measure $\mu_f$ is supported on the set $\big\{0,\frac{1}{q},\ldots,\frac{q-1}{q}\big\}$. Letting $\epsilon$ go to $0$ proves that $\mu_f$ is supported on the rationals.

To prove \ref{itm_spectral_char_per_aper_ii}, assume $f$ is locally aperiodic. From the definition, it follows that for all $q\in\N$ we have
\[
\lim_{M\to\infty} \E_{m\in[M]}\hat\mu_f(qm)=0.
\]
In light of \eqref{eqn_spectral_char_per_aper_1}, this means that $\mu_f\big(\big\{0,\frac{1}{q},\ldots,\frac{q-1}{q}\big\}\big)=0$ for all $q\in\N$. But if this holds for all $q\in\N$ then the measure $\mu_f$ must be supported on the irrationals. 
\end{proof}

\subsection{A multiplicative analogue of van der Corput's inequality}
\label{sec_multiplicative_vdC}

Van der Corput's fundamental inequality (see~\cite[Lemma 3.1]{KN74}) states that for any $1$-bounded function $f\colon\Z\to\C$ and any $N,H\in\N$ with $1\leq H\leq N$ one has
\begin{equation}
\label{eqn_vdC1}
\Big|\E_{h\in [H]} \E_{n\in[N]} f(n) \Big|^2
\leq \Re\bigg(
\E_{h\in[H]} \Big(\tfrac{H-h}{H}\Big) \E_{n\in[N]} f(n)\overline{f(n+h)} \bigg)+\Oh\bigg(\frac{1}{H}+\frac{H}{N}\bigg).
\end{equation}
It is an instrumental inequality used for proving correlation estimates, convergence theorems, and uniform distribution results in number theory, harmonic analysis, and ergodic theory.
A small refinement of the classical formulation of van der Corput's inequality, and one that is often overlooked, asserts that for any $1$-bounded functions $f,g\colon\Z\to\C$ and any $N,H\in\N$ with $1\leq H\leq N$,
\begin{equation}
\label{eqn_vdC2}
\Big|\E_{h\in [H]} \E_{n\in[N]} f(n) g(n+h) \Big|^2
\leq \Re\bigg(
\E_{h\in[H]} \Big(\tfrac{H-h}{H}\Big) \E_{n\in[N]} f(n)\overline{f(n+h)} \bigg)+\Oh\bigg(\frac{1}{H}+\frac{H}{N}\bigg).
\end{equation}
We remark that the standard proof of \eqref{eqn_vdC1} (such as the one given in \cite[Lemma 3.1]{KN74}) with minimal adjustments proves \eqref{eqn_vdC2} as well.

One can also derive a logarithmically averaged version of van der Corput's inequality: For any 
$1$-bounded functions $f,g\colon\Z\to\C$ and any $N,H\in\N$ with $1\leq H\leq N$ we have
\begin{equation}
\label{eqn_vdC3}
\Big|\logE_{h\in [H]} \logE_{n\in[N]} f(n) g(n+h) \Big|^2
\leq \Re\bigg(
\logE_{h\in[H]} \logE_{n\in[N]} f(n)\overline{f(n+h)} \bigg)+\Oh\bigg(\frac{1}{\log(H)}+\frac{\log(H)}{\log(N)}\bigg).
\end{equation}
Since we do not make use of \eqref{eqn_vdC3} in this paper, we omit its proof. It merely serves as motivation for the following novel analogue of \eqref{eqn_vdC3} that uses multiplicative instead of additive differences and plays a crucial role in our argument.

\begin{theorem}
\label{thm_mvc}
Let $y\geq 1$, $P\subset \P\cap [y]$, and suppose $f_p,g\colon \Z\to\C$ are $1$-bounded functions for all $p\in P$. Then
\[
\Big|\logE_{p\in P} \logE_{n\in[N]} f_p(n)g(pn)\Big|^2
\,\leq\, \Re\bigg(
\logE_{p,q\in P} \logE_{n\in[N]} f_p(qn)\overline{f_q(pn)} \bigg)+\Oh\Bigg(\bigg(\sum_{p\in P}\frac{1}{p} \bigg)^{-1}+ \frac{\log y}{\log N}\Bigg).
\]
\end{theorem}

\begin{remark}
If $g(n)$ is a multiplicative function (i.e.~$g(nm)=g(n)g(m)$ whenever $\gcd(n,m)=1$) and $f_p(n)=f(n)$ for some $f\colon\Z\to\C$ and all $p\in P$, then \cref{thm_mvc} is closely related to the Daboussi-Delange-\Katai{}-Bourgain-Sarnak-Ziegler orthogonality criterion \cite{DD82, Katai86, BSZ13}.
\end{remark}

\begin{proof}[Proof of \cref{thm_mvc}]
Using \cref{lem_dilation_log_averages}, we can write
\begin{align*}
\Big|\logE_{p\in P} \logE_{n\in[N]} f_p(n)g(pn)\Big|^2
&= \Big|\logE_{p\in P} \logE_{n\in[N]}p \1_{p\mid n} f_p\big(\tfrac{n}{p}\big)g(n)  \Big|^2 + \Oh\bigg(\frac{\log y}{\log N}\bigg)
\\
&\leq \logE_{n\in[N]}\Big|\logE_{p\in P}  p \1_{p\mid n} f_p\big(\tfrac{n}{p}\big)\Big|^2 + \Oh\bigg(\frac{\log y}{\log N}\bigg)
\\
&= \logE_{p,q\in P} \logE_{n\in[N]} pq \1_{\operatorname{lcm}(p,q)\mid n} f_p\big(\tfrac{n}{p}\big)\overline{f_q\big(\tfrac{n}{q}\big)} + \Oh\bigg(\frac{\log y}{\log N}\bigg)
\\
&= 
\logE_{p,q\in P} \logE_{n\in[N]} pq \1_{pq\mid n} f_p\big(\tfrac{n}{p}\big)\overline{f_q\big(\tfrac{n}{q}\big)} + [1]+ \Oh\bigg(\frac{\log y}{\log N}\bigg),
\end{align*}
where
\begin{align*}
[1]
&= \logE_{p,q\in P} \1_{p=q}\Big( \logE_{n\in[N]} p^2 \1_{p\mid n} \big|f_p\big(\tfrac{n}{p}\big)\big|^2 - \logE_{n\in[N]} p^2 \1_{p^2\mid n} \big|f_p\big(\tfrac{n}{p}\big)\big|^2\Big)
\\
&\leq
\logE_{p,q\in P} \1_{p=q}
\Big( \logE_{n\in[N]} p^2 \1_{p\mid n} \Big)
\\
&\leq \bigg(\sum_{p\in P}\frac{1}{p} \bigg)^{-2} \sum_{p\in P}\frac{1}{p^2}\Big(\logE_{n\in[N]}~p^2\1_{p\mid n}\Big)
\\
&\leq \bigg(\sum_{p\in P}\frac{1}{p} \bigg)^{-1}.
\end{align*}
Using \cref{lem_dilation_log_averages} once more, we see that
\begin{align*}
\logE_{p,q\in P} \logE_{n\in[N]} pq \1_{pq\mid n} f_p\big(\tfrac{n}{p}\big)\overline{f_q\big(\tfrac{n}{q}\big)} 
=
\Re\Big(\logE_{p,q\in P} \logE_{n\in[N]} f_p(qn)\overline{f_q(pn)}\Big) + \Oh\bigg(\frac{\log y}{\log N}\bigg).
\end{align*}
Combining all the estimates above completes the proof.
\end{proof}

\subsection{Proof of \cref{thm_rnd_component}}
\label{sec_proof_of_thm_rnd_component}

We now have all the necessary ingredients to provide a proof of \cref{thm_rnd_component}. For the convenience of the reader, let us restate the theorem here.

\begin{named}{\cref{thm_rnd_component}}{}{}
Let $N_1<N_2<\ldots\in\N$ and $M_1<M_2<\ldots\in\N$. Suppose $\A\subset\ell^\infty(\Z)$ is a separable, affinely invariant $C^*$-subalgebra that admits logarithmic averages along $\bN=([N_s])_{s\in\N}$ and iterated affine correlations along $\bPW=(\P_W\cap [M_t])_{t\in\N}$ for all $W\in\N$.
If $f\in\A$ is locally aperiodic with respect to logarithmic averages along $\bN$, then for all $k,W,a\in\N$ with $k\geq 2$, all $g\in\A$, and all non-constant polynomials $Q$ with integer coefficients we have
\[
\logE_{p\in\bPW^{*k}}\logE_{n\in\bN} f\big(an+Q(p)\big)g(pn)=0.
\]
\end{named}


\begin{proof}
It suffices to prove the case $k=2$.
Using the Cauchy-Schwarz inequality and \cref{thm_mvc}, we obtain
\begin{align*}
\Big|\logE_{p_2\in \bPW}\logE_{p_1\in \bPW} & \logE_{n\in \bN} f(an+Q(p_2p_1))g(p_2p_1n)\Big|^2
\\
&=\lim_{t\to\infty}\Big|\logE_{p_2\in \P_W\cap[M_t]} \logE_{p_1\in \bPW} \logE_{n\in \bN} f(an+Q(p_2p_1))g(p_2p_1n)\Big|^2
\\
&\leq \lim_{t\to\infty} \logE_{p_1\in \bPW} \Big|\logE_{p_2\in \P_W\cap[M_t]} \logE_{n\in \bN} f(an+Q(p_2p_1))g(p_2p_1n)\Big|^2
\\
&\leq \lim_{t\to\infty} \logE_{p_1\in \bPW} \Big(\Re\Big(\logE_{p_2,p_3\in \P_W\cap[M_t]} \logE_{n\in \bN} f(ap_3n+Q(p_2p_1))\overline{f(ap_2n+Q(p_3p_1))}\Big)\Big)
\\
&= \lim_{t\to\infty}\logE_{p_2,p_3\in \P_W\cap[M_t]}\Re\Big(  \logE_{p_1\in \bPW} \logE_{n\in \bN} f(ap_3n+Q(p_2p_1))\overline{f(ap_2n+Q(p_3p_1))}\Big).
\end{align*}
We claim that whenever $p_2\neq p_3$ then
\begin{equation}
\label{eqn_locally_aperiodic_have_no_contribution_1}
\logE_{p_1\in \bPW} \logE_{n\in \bN} f(ap_3n+Q(p_2p_1))\overline{f(ap_2n+Q(p_3p_1))}=0.
\end{equation}
Once this claim has been verified, it follows that only the diagonal terms $p_2=p_3$ contribute, which implies that
\begin{align*}
\Big|\logE_{p_2\in \bPW}\logE_{p_1\in \bPW} & \logE_{n\in \bN} f(an+Q(p_2p_1))g(p_2p_1n)\Big|^2
\leq \|f\|_\infty^2  \Big(\lim_{t\to\infty}\logE_{p_2,p_3\in \P_W\cap[M_t]} \1_{p_2=p_3}\Big)
%\\
=0.
\end{align*}

It remains to verify \eqref{eqn_locally_aperiodic_have_no_contribution_1} under the assumption $p_2\neq p_3$. By symmetry, we can assume without loss of generality that $p_3>p_2$.
Let $q=ap_2p_3$. 
First, we split the right hand side of \eqref{eqn_locally_aperiodic_have_no_contribution_1} into residue classes mod $q$.
Observe that for all $m\in\Z$,
\[
Q(p_2(qm+r))\equiv Q(p_2r)\bmod q\qquad\text{and}\qquad
Q(p_3(qm+r))\equiv Q(p_3r)\bmod q.
\]
Define
\[
Q_{2,r}(n)=\frac{Q(p_2n)-Q(p_2r)}{ap_3}\qquad\text{and}\qquad
Q_{3,r}(n)=\frac{Q(p_3n)-Q(p_3r)}{ap_2}.
\]
Therefore
\begin{align*}
&\logE_{p_1\in \bPW}  \logE_{n\in \bN} f(ap_3n+Q(p_2p_1))\overline{f(ap_2n+Q(p_3p_1))}
\\
&~=\sum_{r=0}^{q-1} \logE_{p_1\in \bPW} \logE_{n\in \bN} \1_{q\Z+r}(p_1)\, f(ap_3n+Q(p_2p_1))\overline{f(ap_2n+Q(p_3p_1))}
\\
&~=\sum_{r=0}^{q-1} \logE_{p_1\in \bPW} \logE_{n\in \bN} \1_{q\Z+r}(p_1)\, f\big(ap_3\big(n+Q_{2,r}(p_1)\big)+Q(p_2r)\big)
\\
&\hspace{19em}\overline{f\big(ap_2\big(n+Q_{3,r}(p_1)\big)+Q(p_3r)\big)}.
\end{align*}
To simplify notation, let us define, for $r\in\{0,\ldots,q-1\}$, the functions 
\[
f_{r,1}(n)=f(ap_3n+Q(p_2r))\qquad\text{and}\qquad f_{r,2}(n)=f(ap_2n+Q(p_3r)).
\]
Then we can rewrite the above as
\begin{align*}
\logE_{p_1\in \bPW} & \logE_{n\in \bN} f(ap_3n+Q(p_2p_1))\overline{f(ap_2n+Q(p_3p_1))}
\\
&~=\sum_{r=0}^{q-1} \logE_{p_1\in \bPW} \logE_{n\in \bN} \1_{q\Z+r}(p_1)\, f_{r,1}(n+Q_{2,r}(p_1))\overline{f_{r,2}(n+Q_{3,r}(p_1))}
\\
&~=\sum_{r=0}^{q-1} \logE_{p_1\in \bPW} \logE_{n\in \bN} \1_{q\Z+r}(p_1)\, f_{r,1}(n)\overline{f_{r,2}(n+Q_{3,r}(p_1)-Q_{2,r}(p_1))}.
\end{align*}
After exchanging the order of summation in the variables $n$ and $p_1$, using the Cauchy-Schwarz inequality, and finally expanding the square, we can eliminate the function $f_{r,1}$ and obtain a single correlation expression in the function $f_{r,2}$:
\begin{align*}
\Big|\logE_{p_1\in \bPW} & \logE_{n\in \bN} f(ap_3n+Q(p_2p_1))\overline{f(ap_2n+Q(p_3p_1))}\Big|
\\
&~=\bigg|\sum_{r=0}^{q-1} \Big(\lim_{t\to\infty}\logE_{p_1\in \P_W\cap [M_t]} \logE_{n\in \bN} \1_{q\Z+r}(p_1)\, f_{r,1}(n)\overline{f_{r,2}(n+Q_{3,r}(p_1)-Q_{2,r}(p_1))}\Big)\bigg|
\\
&~\leq \|f\|_\infty  \sum_{r=0}^{q-1}\lim_{t\to\infty} \bigg( \logE_{n\in \bN}  \Big|\logE_{p_1\in \P_W\cap [M_t]}\1_{q\Z+r}(p_1)\, f_{r,2}(n+Q_{3,r}(p_1)-Q_{2,r}(p_1))\Big|^2\bigg)^{\frac{1}{2}}.
\end{align*}
Let $\mu_{f_{r,2}}$ be the spectral measure associated to $f_{r,2}$, as defined in \eqref{eqn_spectral_measure}. 
In light of \cref{lem_spectral_measure_isometry_property}, it follows that
\begin{align*}
\lim_{t\to\infty} \bigg( \logE_{n\in \bN} &  \Big|\logE_{p_1\in \P_W\cap [M_t]}\1_{q\Z+r}(p_1)\, f_{r,2}(n+Q_{3,r}(p_1)-Q_{2,r}(p_1))\Big|^2\bigg)^{\frac{1}{2}}
\\
&= \lim_{t\to\infty} \bigg(\int_\T \Big|\logE_{p_1\in \P_W\cap [M_t]}\1_{q\Z+r}(p_1)\, e\big(\big(Q_{3,r}(p_1)-Q_{2,r}(p_1)\big)x\big)\Big|^2\d\mu_{f_{r,2}}(x)\bigg)^{\frac{1}{2}}.
\end{align*}
Since $Q$ is non-constant and $p_2$ and $p_3$ are distinct primes, the polynomial $x\mapsto Q_{3,r}(x)-Q_{2,r}(x)$ is non-constant with rational coefficients.
According to \cref{cor_log_vinogradov}, if $x$ is irrational then
\[
\lim_{t\to\infty} \logE_{p_1\in \P_W\cap [M_t]}\1_{q\Z+r}(p_1)\, e\big(\big(Q_{3,r}(p_1)-Q_{2,r}(p_1)\big)x\big)=0.
\]
By assumption, $f$ is locally aperiodic. Due to \cref{lem_basic_properties_locally_periodic_locally_aperiodic}, this means that $f_{r,2}$ is also locally aperiodic. In view of the spectral characterization of locally aperiodic functions given by \cref{thm_spectral_char_per_aper}, the spectral measure $\mu_{f_{r,2}}$ of $f_{r,2}$ is supported on the irrational numbers. It thus follows by the Lebesgue's dominated convergence theorem that
\[
\lim_{t\to\infty} \bigg(\int_\T \Big|\logE_{p_1\in \P_W\cap [M_t]}\1_{q\Z+r}(p_1)\, e\big(\big(Q_{3,r}(p_1)-Q_{2,r}(p_1)\big)x\big)\Big|^2\d\mu_{f_{r,2}}(x)\bigg)^{\frac{1}{2}}=0.
\]
This concludes the proof.
\end{proof}


\section{Controlling the ``structured'' component}
\label{sec_proof_of_thm_str_component}

In this section, we give a proof of \cref{thm_str_component}.
Let us restate the theorem:

\begin{named}{\cref{thm_str_component}}{}
Let $N_1<N_2<\ldots\in\N$ and $M_1<M_2<\ldots\in\N$. Suppose $\A\subset\ell^\infty(\Z)$ is a separable, affinely invariant $C^*$-subalgebra that admits logarithmic averages along $\bN=([N_s])_{s\in\N}$ and iterated affine correlations along $\bPW=(\P_W\cap [M_t])_{t\in\N}$ for all $W\in\N$.
Suppose $a_1,a_2,\ldots\in\N$ and $f\in\A$ with $f(n)\geq 0$ for all $n\in\N$.
Then for any $\epsilon>0$ and any $W\in\N$ there are $k\geq 2$ and an infinite set $I\subset\N$, such that for all $i,j\in I$ with $i<j$ we have
\begin{equation}
\label{eqn_improved_DE}
\logE_{p\in\bPW^{*k}} \logE_{n\in \bN} f(a_in)f(a_jpn) \geq  \Big(\limsup_{j\to\infty}\logE_{n\in\bN} f(a_jn)\Big)^2-\epsilon.    
\end{equation}
\end{named}


\begin{proof}
Let $\epsilon>0$ be given, and define $\delta=\limsup_{j\to\infty}\E^{\log}_{n\in\bN} f(a_jn)$.
By replacing $(a_j)_{j\in\N}$ with a subsequence of itself, we can assume without loss of generality that
\begin{equation}
\label{eqn_improved_DE_2}
\logE_{n\in\bN} f(a_jn)\geq \delta-\frac{\epsilon}{3},\qquad\forall j\in\N.
\end{equation}
Let $K\in\N$ be any natural number that satisfies $K>3\epsilon^{-1}$.
We now define a $K$ coloring of the set $\{(i,j)\in\N\times\N: i<j\}$, and 
we represent this coloring as a map $\chi\colon \{(i,j)\in\N\times\N: i<j\} \to \{1,\ldots,K\}$.
Given $i,j\in\N$ with $i<j$, define
\[
\chi(i,j)=
\begin{cases}
k,&\text{if $k$ is the smallest number in $\{2,\ldots,K\}$ for which \eqref{eqn_improved_DE} holds;}
\\
1,&\text{if \eqref{eqn_improved_DE} doesn't hold for any $k\in\{2,\ldots,K\}$}.
\end{cases}
\]
By Ramsey's theorem \cite[Theorem~A]{Ramsey30}, there exists an infinite set $I\subset \N$ such that $\chi(i,j)$ has the same color for all $i,j\in I$ with $i<j$.
If this color belongs to the set $\{2,\ldots,K\}$ then we are done.
So it remains to show that $1$ is not an admissible color.
By way of contradiction, suppose $\chi(i,j)=1$ for all $i,j\in I$ with $i<j$.
This implies that all $i,j\in I$ with $i<j$,
\[
\max_{k=2,\ldots,K}\Big(\logE_{p\in\bPW^{*k}} \logE_{n\in \bN} f(a_in)f(a_jpn)\Big) < \delta^2-\epsilon.    
\]
Let $i_2<\ldots<i_K\in I$ be arbitrary. 
Using \eqref{eqn_improved_DE_2}, \cref{cor_log_TK_2}, and the Cauchy-Schwarz inequality, we have
\begin{align*}
\Big(\delta-\frac{\epsilon}{3}\Big)^2 &\leq \Big( \E_{k\in\{2,\ldots,K\}} \logE_{n\in\bN} f(a_{i_k}n) \Big)^2
\\
&= \Big( \E_{k\in\{2,\ldots,K\}} \logE_{p\in\bPW^{*k}} \logE_{n\in\bN} f(a_{i_k}pn) \Big)^2
\\
&= \Big( \logE_{p_K\in\bPW} \cdots \logE_{p_1\in\bPW} \logE_{n\in\bN} \E_{k\in\{2,\ldots,K\}}  f(a_{i_k}p_k\cdots p_1n) \Big)^2
\\
&\leq \logE_{p_K\in\bPW} \cdots \logE_{p_1\in\bPW} \logE_{n\in\bN} \Big( \E_{k\in\{2,\ldots,K\}} f(a_{i_k}p_k\cdots p_1n) \Big)^2
\\
&= \E_{k,\ell\in\{2,\ldots,K\}} \logE_{p_K\in\bPW} \cdots \logE_{p_1\in\bPW} \logE_{n\in\bN} f(a_{i_\ell} p_\ell\cdots p_1n) f(a_{i_k}p_k\cdots p_1n)
\\
&\leq  \E_{k,\ell\in\{2,\ldots,K\}} 2\1_{\ell<k} \logE_{p_K\in\bPW} \cdots \logE_{p_1\in\bPW} \logE_{n\in\bN} f(a_{i_\ell} p_\ell\cdots p_1n) f(a_{i_k}p_k\cdots p_1n) + \frac{1}{K}
\\
&=  \E_{k,\ell\in\{2,\ldots,K\}} 2\1_{\ell<k} \logE_{p_K\in\bPW} \cdots \logE_{p_1\in\bPW} \logE_{n\in\bN} f(a_{i_\ell} n) f(a_{i_k}p_k\cdots p_{k-\ell+1}n) + \frac{1}{K-1}
\\
&=  \E_{k,\ell\in\{2,\ldots,K\}} 2\1_{\ell<k} \logE_{p\in\bPW^{*\ell}} \logE_{n\in\bN} f(a_{i_\ell} n) f(a_{i_k}pn) + \frac{1}{K-1}
\\
&< \delta^2-\epsilon+\frac{1}{K-1}.
\end{align*}
This contradicts the assumption that $K>3\epsilon^{-1}$, completing the proof.
\end{proof}

\section{Open questions}

To conclude, we formulate some open questions and conjectures connected to our results and the broader topic.

We begin by asking for a natural extension of \cref{thm_2}.

\begin{question}
Is there a multiplicatively invariant density on $\N$ (similar to $\AMdens(.)$) such that any set with positive density with respect to this density notion contains $\{x,x+y,xy\}$ for some $x,y\in\N$. 
\end{question}

The next question seeks a quantitative version of (a special case of) Moreira's theorem \cite{Moreira17}.
Given $r\in\N$, let $M(r)$ denote the smallest positive integer such that for all $N\geq M(r)$ and all $r$-colorings of $[N]$ one can find $x,y\in[N]$ such that $\{x+y,xy\}\subset[N]$ is monochromatic. 
It follows from the compactness principle (see~\cite[Section~1.5]{GRS90}) applied to Moreira's theorem that $M(r)$ is well defined for every $r\in\N$.

\begin{question}
What lower and upper bounds on $M(r)$ can be provided?
\end{question}

Finally, it is natural to inquire about sums and products in the set $\P-1$.

\begin{conjecture}
There are infinitely many $x,y\in\N$ such that 
$\{x+y,xy\}\subset \P-1$.
\end{conjecture}


