\section{Twisted graded categories}
\label{sec:twisted-graded-categories}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    Let $\cC$ be a presentably symmetric monoidal category and $M$ a commutative monoid. In this section, we study different symmetric monoidal structures on the category $\Fun(M, \cC)$ of $M$-graded $\cC$-objects. The simplest example we consider is the Day convolution, which corresponds to the constant colimit $\cC[M]$ in $\CAlg_{\cC}(\PrL)$. 
    In \cref{subsec:graded-categories-and-day}, we study this symmetric monoidal structure and compute its Picard spectrum when $M$ is discrete and $\cC$ is semiadditive and connected. 

    In \cref{subsec:Thom-cateogries}, we employ the Thom construction to construct symmetric monoidal structures on $\Fun(M,\cC)$ that agree $\EE_1$-monoidally with the Day convolution. When $M = A$ is an abelian group, we prove that these exhaust all possible structures.

    Finally, in \cref{subsec:examples}, we explore examples of twisted graded categories, reconstructing in particular the Koszul twist in any category admitting a minus one.

    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \subsection{Graded categories and Day convolution}
    \label{subsec:graded-categories-and-day}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        Let $\cC$ be an $\EE_k$-monoidal category and $M$ be an $\EE_k$-monoid for $1 \le k \le \infty$. In this subsection, we study the Picard $\EE_k$-group of the $\EE_k$-monoidal category $\Fun(M, \cC)$ equipped with the Day monoidal structure, in the case when $\cC$ is presentable and $M$ is discrete. 
        Under mild assumptions, we show it is isomorphic to $\cC\units \times M\units$.

        \begin{definition}
            Define the category of $M$-graded objects in $\cC$ as $\Gr_M \cC \coloneqq \Fun(M, \cC)$. We endow this category with the Day $\EE_k$-monoidal structure.

            Equivalently, $\Gr_M \cC$ is the Thom construction of the trivial map $M \xto{0} \Mod_{\cC}\units$ (see \cite{Antolin-Barthel-2019-Thom} or \cref{subsec:Thom-cateogries}).
        \end{definition}

        \begin{definition}\label{def:shift-and-yoneda}\ 
            \begin{enumerate}
                \item\label{item:<0>} 
                The map of commutative monoids $0 \to M$ over $\Mod_{\cC}\units$ induces an $\EE_k$-monoidal functor
                \begin{equation*}
                    (-)\shift{0} \colon \cC \to \Gr_M\cC.
                \end{equation*}
                It sends $X\in \cC$ to the graded object $X\shift{0} \colon M \to \cC$, which is $X[\Omega_0 M]$ at the connected component of $0 \in M$, and is $\emptyset$ at all other connected components.

                \item\label{item:1<->}
                The Yoneda embedding $\yo \colon M\op \to \FunDay(M, \cC) = \Gr_M \cC$ is $\EE_k$-monoidal (\cite[Corollary~4.8.1.12, Remark~4.8.1.13]{Lurie-HA}, \cite[Proposition~3.3]{Ben-Moshe-Schlank-2024-K-theory}). Denote the $\EE_k$-monoidal functor
                \begin{equation*}
                    \ounit_{\cC}\shift{-} \colon M \isoto M\op \xto{\yo} \Gr_M \cC.
                \end{equation*}
                It sends $m\in M$ to the graded object $\ounit_{\cC}\shift{m} \colon M \to \cC$, which is $\ounit_{\cC}[\Omega_m M]$ at the connected component of $m\in M$, and $\emptyset$ at all other connected components.

                \item\label{item:(-)<->}
                Taking the tensor product of the above two definitions, we define the $\EE_k$-monoidal functor
                \begin{equation*}
                    (-)\shift{-} \colon \cC \times M \xto{(-)\shift{0} \times \ounit_{\cC}\shift{-}} \Gr_M \cC \times \Gr_M \cC \xto{\otimes_{\Day}} \Gr_M \cC.
                \end{equation*}
                It sends $(X, m)$ to the graded object $X\shift{m} \colon M \to \cC$ which is $X[\Omega_m M]$ at the connected component of $m\in M$, and $\emptyset$ at all other connected components.
            \end{enumerate}
        \end{definition}

        We detour now for a quick discussion about the Picard spectrum, and more generally, the Picard $\EE_k$-group.        
        Let $\cU\in\Alg_{\EE_{k+1}}(\PrL)$. Then $\cU$ admits a unique $\EE_{k+1}$-monoidal, colimit preserving functor
        \begin{equation*}
            \ounit_{\cU}[-] \colon \spc \to \cU
        \end{equation*}
        and its right adjoint is $\Map(\ounit_{\cU}, -)$. Taking $\EE_k$-algebras we get an adjunction
        \begin{equation*}
            \ounit_{\cU}[-] \colon \Mon_{\EE_k}(\spc) \rightleftarrows \Alg_{\EE_k}(\cU) \cocolon \Map(\ounit_{\cU}, -).
        \end{equation*}
        The forgetful functor from group-like $\EE_k$-monoids admits a right adjoint $(-)\units$
        \begin{equation*}
            \fgt \colon \Grp_{\EE_k}(\spc) \rightleftarrows \Mon_{\EE_k}(\spc) \cocolon (-)\units
        \end{equation*}
        which takes a monoid to its collection of connected components spanned by invertible elements. Composing the two right adjoints we get a functor
        \begin{equation*}
            (-)\units \colon \Alg_{\EE_k}(\cU) \to \Grp_{\EE_k}(\spc).
        \end{equation*}

        When $\cU$ is symmetric monoidal we have a commutative diagram
        \begin{equation*}
            \begin{tikzcd}
                {\CAlg(\cU)} & {\Alg(\cU)} \\
                \cnSp & {\Grp(\spc).}
                \arrow["\fgt", from=1-1, to=1-2]
                \arrow["{(-)\units}", from=1-1, to=2-1]
                \arrow["{(-)\units}", from=1-2, to=2-2]
                \arrow["\fgt", from=2-1, to=2-2]
            \end{tikzcd}
        \end{equation*}

        Choosing $\cU = \Cat$, for any $\cC\in \Mon_{\EE_k}(\Cat)$ we call $\cC\units$ the Picard $\EE_k$group of $\cC$.
        The commutativity of the diagram above implies that when $\cC$ is symmetric monoidal, its Picard $\EE_1$-group agrees with the underline $\EE_1$ structure of its Picard spectrum.

        We also denote $\Pic(\cC) \coloneqq \pi_0 \cC\units$.


        We recall the following definition:
        \begin{definition}\label{def:connected}
            Let $\cC$ be an $\EE_k$-monoidal category. We say that $\cC$ is connected if it can not be decomposed as a product of $\EE_k$-monoidal categories. Equivalently, the unit $\ounit_{\cC}$ does not admit central idempotents (\cite[Proposition~6.28]{BCSY-Fourier}).   
        \end{definition}

        The goal of this section is the following:

        \begin{theorem}\label{prop:picard-of-Day}
            Let $\cC \in \Alg_{\EE_k}(\PrL)$ be semiadditive and connected.
            Let $M$ be a discrete commutative monoid. Then the functor of \cref{def:shift-and-yoneda}(\labelcref{item:(-)<->}) induces an isomorphism of $\EE_k$-groups
            \begin{equation*}
               \cC\units \times M\units \isoto (\Gr_M \cC)\units.
            \end{equation*}
        \end{theorem}

        We will need the following two simple lemmas:

        \begin{lemma}\label{lem:sum-is-zero}
            Let $\cC$ be a category. Assume there is a collection of objects $\{X_i\}_i$ such that $\bigsqcup_{i} X_i \simeq \emptyset$. Then $X_i \simeq \emptyset$ for all $i$.
        \end{lemma}
        \begin{proof}
            Let $Y \in \cC$. For any $i$ we call the following map the trivial map
            \begin{equation*}
                \emptyset \colon X_i \to \bigsqcup_j X_j \simeq \emptyset \to Y.
            \end{equation*}
            Choose an index $i_0$. The trivial maps $X_i \xto{\emptyset} Y$ for $i\neq i_0$, provide a retraction
            \begin{equation*}
                \Map(X_{i_0}, Y) \to \Map(\bigsqcup_j X_j, Y)
            \end{equation*}
            to the post-compisition map with $X_{i_0} \to \bigsqcup_j X_j$.
            Therefore $\Map(X_{i_0}, Y)$ is a retract of $\Map(\bigsqcup_j X_j, Y) \simeq \Map(\emptyset, Y) \simeq \pt$ and therefore contractible. Thus $X_{i_0} \simeq \emptyset$.
        \end{proof}

        \begin{lemma}\label{lem:sum-cannot-be-unit}
            Let $0 \neq \cC\in \Alg_{\EE_k}(\PrL)$ be semiadditive and connected. Let $E,F\in \cC$ be orthogonal, that is $E \otimes F \simeq 0$. Assume that $E \oplus F \simeq \ounit_{\cC}$. Then either $E = \ounit_{\cC}$ and $F = 0$ or $E = 0$ and $F = \ounit_{\cC}$.
        \end{lemma}
        \begin{proof}
            Consider the composition $u \colon \ounit \simeq E \oplus F \xto{\pr_E} E$. Then the map $\id_E \otimes u \colon E \to E\otimes E$ factors as
            \begin{equation*}
                \id_E \otimes u \colon E \simeq E \otimes (E \oplus F) \simeq (E \otimes E) \oplus (E\otimes F) \simeq (E\otimes E).
            \end{equation*}
            That is, $E$ is an idempotent algebra in $\cC$, in contradiction to the connectedness of $\cC$.

            % Consider the composition of $\EE_k$-monoidal left adjoints
            % \begin{equation*}
            %     \begin{tikzcd}
