            %         \arrow["\Delta", shift left, from=1-1, to=1-2]
            %         \arrow["{\times}", shift left, from=1-2, to=1-1]
            %         \arrow["{\BLoc_{E} \times \BLoc_{F}}", shift left, from=1-2, to=1-3]
            %         \arrow[shift left, hook', from=1-3, to=1-2]
