            % Since $L$ is conservative and $R$ is fully faithful, $L$ is an isomorphism of $\EE_k$-monoidal categories. Since $\cC$ is connected, without loss of generality, $\cC = \BLoc_E\cC$ and $\BLoc_F\cC = 0$. Thus $F = 0$ and so $E = \ounit_{\cC}$.
        \end{proof}


        \begin{proof}[Proof of \cref{prop:picard-of-Day}]
            Consider the $\EE_k$-monoidal map
            \begin{equation*}
                (-)\shift{-} \colon \cC \times M \to \Gr_M \cC
            \end{equation*}
            of \cref{def:shift-and-yoneda}(\labelcref{item:(-)<->}). It is fully faithful, as for each $m\in M$ the map $(-)\shift{m} \colon \cC \to \Gr_M \cC$ is fully faithful. Taking Picard $\EE_k$-groups, it induces
            \begin{equation*}
                \cC\units \times M\units \to (\Gr_M \cC)\units.
            \end{equation*}

            It is left showing it is essentially surjective.
            Let $X\in (\Gr_M \cC)\units$ and call its inverse $Y$. As $(-)\shift{0} \colon \cC \to \Gr_M \cC$ is $\EE_k$-monoidal, the unit of $\Gr_M \cC$ is $\ounit_{\cC}\shift{0}$. That is, it is $\ounit_{\cC}$ at $0\in M$ and $0\in \cC$ everywhere else. The Day convolution is given by
            \begin{equation*}
                (X \otimes_{\Day} Y)_m \simeq \bigoplus_{a+b = m} (X_a \otimes Y_b).
            \end{equation*}
            Therefore,
            \begin{equation*}
                \begin{split}
                    & \bigoplus_{a + b = 0} (X_a \otimes Y_b) \simeq \ounit_{\cC} \\
                    & \bigoplus_{a + b = m} (X_a \otimes Y_b) \simeq 0 \text{ for any $m \neq 0$}.
                \end{split}
            \end{equation*}
            By \cref{lem:sum-cannot-be-unit}, there exists a unique $m_0 \in M$ (necessarily invertible) for which $X_{m_0} \otimes Y_{-m_0} \simeq \ounit_{\cC}$, and together with \cref{lem:sum-is-zero}, for any $(a,b)\neq (m_0, -m_0)$ 
            \begin{equation*}
                X_a \otimes Y_b \simeq 0.
            \end{equation*}
            In particular, for any $a \neq m_0$, $X_a \otimes Y_{-m_0} \simeq 0$, but as $Y_{-m_0}$ is invertible, $X_a \simeq 0$. Therefore $X \simeq X_{m_0}\shift{m_0}$.
        \end{proof}

        \begin{remark}
            \cref{prop:picard-of-Day} does not hold if we replace $M$ by a non-discrete $\EE_k$-monoid. For example, if we take a connective spectrum of the form $\Sigma^2 A$ for $A\in \Ab$, and $\cC$ a strict 1-category, then any functor $\Sigma^2 A \to \cC$ is trivial and $\FunDay(\Sigma^2 A, \cC) \simeq \cC$. Therefore
            \begin{equation*}
                (\Gr_{\Sigma^2 A} \cC)\units = \cC\units \neq \cC\units \times \Sigma^2 A.
            \end{equation*}
        \end{remark}



    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \subsection{Thom categories}
    \label{subsec:Thom-cateogries}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

        \begin{definition}\label{def:twisted-Fun}
            Let $\cC \in \Alg_{\EE_{k}}(\PrL)$ for $1 \le k \le \infty$. Let $M$ be a discrete commutative monoid and $\Zchar \colon M \to \Sigma \cC\units$ be an $\EE_k$-monoidal map, equipped with an $\EE_1$-nullhomotopy. 
            Define the category $\Gr^{\Zchar}_M \cC$ of \emph{$\Zchar$-twisted $M$-graded objects} to be the Thom construction (i.e.\ the colimit in $\Mod_{\cC}$) of the map
            \begin{equation*}
                M \xto{\Zchar} \Sigma \cC\units \to \Mod_{\cC}\units.
            \end{equation*}
            It is an $\EE_k$-algebra in $\Mod_{\cC}$ (see e.g. \cite{Antolin-Barthel-2019-Thom}).
        \end{definition}


        \begin{lemma}\label{lem:twFun-Day-E1}
            The underlying $\EE_1$-algebra of $\Gr^{\Zchar}_M(\cC)$ is identified with $\Gr_M \cC \in \Alg_{\cC}(\PrL)$ via the $\EE_1$-nullhomotopy of $M\to \Sigma \cC\units$.
        \end{lemma}

        \begin{proof}
            The map of $\EE_1$-groups
            \begin{equation*}
                \Zchar \colon M \to \Sigma \cC\units
            \end{equation*}
            comes with a null homotopy by assumption. Therefore, the colimit along $\Zchar$ is identified with the trivial colimit $\cC[M] \simeq \Gr_M \cC$.
        \end{proof}

        \begin{corollary}
            Let $m_1, m_2 \in M$. Then for any  \begin{equation*}
                \Zchar \colon M \to \Sigma \cC\units
            \end{equation*}
            with an $\EE_1$-nullhomotopy we have $\ounit_{\cC}\shift{m_1} \otimes \ounit_{\cC}\shift{m_2} \simeq \ounit_{\cC}\shift{m_1 + m_2}$ in $\Gr_M^\phi(\cC)$. 
        \end{corollary}

        \begin{definition}
            Using the identification of \cref{lem:twFun-Day-E1}, we can define the $\EE_1$-map as in \cref{def:shift-and-yoneda}(\labelcref{item:(-)<->})
            \begin{equation*}
                (-)\shift{-} \colon \cC \times M \to \Gr^{\Zchar}_M(\cC).
            \end{equation*}
        \end{definition}

        We will be interested specifically in the case where $k = \infty$ and $M$ is grouplike. In this case $\EE_k$-groups are identified with connective spectra.

        \begin{definition}
            Let $X,Y \in \cnSp$. Define the space $\Map\Enull(X,Y)$ of maps $X \to Y$ that are $\EE_1$-null as the fiber
            \begin{equation*}
                \Map\Enull(X,Y) \coloneqq \fib \big( \Map_{\cnSp}(X,Y) \to \Map_{\EE_1}(X,Y) \big).
            \end{equation*}
        \end{definition}

        Using the fully faithful functor $\B \colon \Grp(\spc) \into \spc_*$ and the $\redSS[-] \dashv \fgt$ adjunction, where $\redSS[-]\colon \spc_* \to \cnSp$ is the reduced suspension spectrum functor, one can write
        \begin{equation*}
            \Map_{\EE_1}(X, Y) \simeq \Map_{\spc_*}(\B X, \B Y) \simeq \Map_{\cnSp}(\redSS[\B X], \Sigma Y) \simeq \Map_{\Sp}(\Sigma^{-1} \redSS[\B X], Y).
        \end{equation*}
        Therefore
        \begin{equation*}
            \Map\Enull(X,Y) \simeq \Map_{\Sp}(\cofib(\Sigma^{-1} \redSS[\B X] \to X), Y).
        \end{equation*}
        We moreover notice that the cofiber $\cofib(\Sigma^{-1} \redSS[\B X] \to X)$ is connected.

        \begin{definition}
            Let $X \in \cnSp$. Define
            \begin{equation*}
                X\Enull \coloneqq \Omega \cofib(\Sigma^{-1} \redSS[\B X] \to X) \in \cnSp.
            \end{equation*}
        \end{definition}

        \begin{corollary}\label{cor:E1-null}
            For any $X,Y \in \cnSp$
            \begin{equation*}
                \Map(X\Enull, \Omega Y) \simeq \Map\Enull(X,Y).
            \end{equation*}
        \end{corollary}

        \begin{definition}
            Let $\cC \in \CAlg(\PrL)$ and $\cD \in \Alg_{\cC}(\PrL)$. Define the space $\Lift(\cD)$, of $\EE_{\infty}$-lifts of $\cD$, as the pullback
            \begin{equation*}
                \begin{tikzcd}
                    {\Lift(\cD)} & {{\CAlg_{\cC}(\PrL)}\core} \\
                    {\{\cD\}} & {{\Alg_{\cC}(\PrL)}\core.}
                    \arrow[from=1-1, to=1-2]
                    \arrow[from=1-1, to=2-1]
                    \arrow["\lrcorner"{anchor=center, pos=0.125}, draw=none, from=1-1, to=2-2]
                    \arrow[from=1-2, to=2-2]
                    \arrow[from=2-1, to=2-2]
                \end{tikzcd}
            \end{equation*}
        \end{definition}



        \begin{theorem}\label{thm:twFun-are-all-lifts}
            Let $A \in \Ab$ and $\cC\in \CAlg(\PrL)$. The map 
            \begin{equation*}
                \Gr^{(-)}_A \cC \colon \Map(A\Enull, \cC\units) \simeq \Map\Enull(A, \Sigma \cC\units) \to \Lift(\Gr_A \cC)
            \end{equation*}
            is an isomorphism of spaces.
        \end{theorem}

        Before proving this theorem, we will need the following result from \cite{Antolin-Barthel-2019-Thom}:
        \begin{proposition}[\cite{Antolin-Barthel-2019-Thom}]\label{prop:universal-property-thom}
            Let $\cU \in \CAlg(\PrL)$ and $f\colon G \to \cU\units$ be a map of $\EE_k$-groups. Then for any $R\in \Alg_{\EE_k}(\cU)$ there is an isomorphism between the space $\Map_{\Alg_{\EE_k}(\cU)}(\Th(f), R)$ of algebra maps from the Thom construction of $f$ to $R$ and the space of nullhomotopies of the composition $G \to \cU\units \to \LMod_R(\cU)\units$ in $\EE_k$-groups.
        \end{proposition}

        \begin{proof}
            The proofs in \cite{Antolin-Barthel-2019-Thom} are done for $\cU$ being a category of modules over a commutative ring spectrum, but they hold generally. Now following the proof of \cite[Proposition~8.11]{Burklund-Schlank-Yuan-2022-Nullstellensatz}: By \cite[Theorem~3.5, Definition~3.12, Definition~3.14, Proposition~3.15]{Antolin-Barthel-2019-Thom} The space of maps of $\EE_k$-algebras $\Th(f) \to R$ is isomorphic to the space of lifts
            \begin{equation*}
                \begin{tikzcd}
                    & {B(R;\cU)} \\
                    G & {\cU\units,}
                    \arrow[from=1-2, to=2-2]
                    \arrow[dashed, from=2-1, to=1-2]
                    \arrow["f", from=2-1, to=2-2]
                \end{tikzcd}
            \end{equation*}
            where $B(R;\cU)$ is the space of maps $Z \to R$ where $Z\in \cU\units$ and when induced to $R$ it is an isomorphism $R\otimes Z \isoto R$. In the proof of \cite[Proposition~3.16]{Antolin-Barthel-2019-Thom} it is written as the pullback
            \begin{equation*}
                \begin{tikzcd}
                    {B(R; \cU)} & {B(\ounit_{\cU}; \cU)} \\
                    {\cU\units} & {\LMod_R(\cU)\units,}
                    \arrow[from=1-1, to=1-2]
                    \arrow[from=1-1, to=2-1]
                    \arrow["\lrcorner"{anchor=center, pos=0.125}, draw=none, from=1-1, to=2-2]
                    \arrow[from=1-2, to=2-2]
                    \arrow["{R\otimes-}", from=2-1, to=2-2]
                \end{tikzcd}
            \end{equation*}
            i.e.\ lifts to $B(R;\cU)$ are in correspondence with nullhomotopies of $G \to \cU\units \to \LMod_R(\cU)\units$.
        \end{proof}

