        \begin{lemma}\label{lem:cofiber-of-pic-Day}
            Let $\cD\in \Lift(\Gr_A \cC)$. Then there is a cofiber sequence of connective spectra
            \begin{equation*}
                \cC\units \to \cD\units \to A.
            \end{equation*}
        \end{lemma}

        \begin{proof}
            $\cD$ admits a unique $\cC$-linear symmetric monoidal functor $\cC \to \cD$ which induces a map of connective spectra $\cC\units \to \cD\units$. Denote its cofiber by $X$. 
            Since $\cC\units$ is connective, the cofiber sequence 
            \begin{equation*}
                \cC\units \to \cD\units \to X
            \end{equation*}
            is also a fiber sequence. As the underlying $\EE_1$-group commutes with limits, it is also a fiber sequence of $\EE_1$-groups. 

            As $\EE_1$-groups, $\cC\units$ and $\cD\units$ are the groups of $\otimes$-invertible elements of the $\EE_1$-monoidal categories $\cC$ and $\cD = \Gr_A \cC$. 
            The unique $\cC$-linear monoidal functor 
            \begin{equation*}
                (-)\shift{0} \colon \cC \to \Gr_A \cC
            \end{equation*}
            is the functor of \cref{def:shift-and-yoneda}(\labelcref{item:<0>}). That is, $\cC \to \Gr_A \cC$ identifies $\cC$ as a sub-monoidal category of $\Gr_A \cC$, consisting of functors that are trivial on all elements different than $0 \in A$. 
            Now, using \cref{prop:picard-of-Day}, the map $\cC\units \to \cD\units$ is identified with 
            \begin{equation*}
                \cC\units \xto{\id \times 0} \cC\units \times A \simeq (\Gr_A \cC)\units \simeq \cD\units
            \end{equation*}
            and sits in an exact sequence of $\EE_1$-groups
            \begin{equation*}
                \cC\units \to \cD\units \to A.
            \end{equation*}

            Since $A$ is the cofiber of the map $\cC\units \to \cD\units$ and the composition $\cC\units\to \cD\units \to X$ is null, we get a natural map $A \to X$ of $\EE_1$-groups. 

            Rolling both fiber sequences, both $\Omega_0 X$ and $0 = \Omega_0 A$ are the fibers of $\cC\units \to \cD\units$, therefore they identify, meaning that $X$ is a discrete abelian group.

            By the long exact sequence of homotopy groups, $X \simeq \pi_0 X \simeq \coker(\Pic(\cC) \to \Pic(\cD))$. But the map $\Pic(\cC) \to \Pic(\cD)$ identifies with
            \begin{equation*}
                \Pic(\cC) \xto{\id \times 0} \Pic(\cC) \times A,
            \end{equation*}
            thus the map $A \to X$ is an isomorphism.
        \end{proof}

        \begin{proof}[Proof of \cref{thm:twFun-are-all-lifts}]
            First we show that $\Gr^{(-)}_A \cC$ is an an isomorphism on $\pi_0$. Let \linebreak $\cD\in\Lift(\Gr_A \cC)$. By \cref{lem:cofiber-of-pic-Day}, $A$ sits in a cofiber sequence
            \begin{equation*}
                \cC\units \to \cD\units \to A.
            \end{equation*}
            Rolling the cofiber sequence, we get a natural map $\Zchar_{\cD} \colon A \to \Sigma \cC\units$. 
            The canonical nullhomotopy
            \begin{equation*}
                A \xto{\Zchar_{\cD}} \Sigma \cC\units \to \Sigma \cD\units
            \end{equation*}
            induces a null homotopy
            \begin{equation*}
                A \xto{\Zchar_{\cD}} \Sigma \cC\units \to \Mod_{\cC}\units \to \Mod_{\cD}\units.
            \end{equation*}
            By \cref{prop:universal-property-thom} this induces a map of $\cC$-linear symmetric monoidal categories $\Gr^{\Zchar_{\cD}}_A \cC \to \cD$, which is an $\EE_1$-isomorphism by assumption. Therefore it is an isomorphism in $\CAlg_{\cC}(\PrL)$. This proves that $\Gr^{(-)}_A \cC$ is surjective on $\pi_0$. To show it is injective, it is enough to verify that for any $\Zchar \in \Map\Enull(A, \Sigma \cC\units)$, the fiber of $\Zchar \colon A \to \Sigma \cC\units$ is $(\Gr^{\Zchar}_A \cC)\units$. Denote by $F_{\Zchar}$ the fiber of $\Zchar$. 
            Then there exists a symmetric monoidal map
            \begin{equation*}
                j_{\Zchar} \colon F_{\Zchar} \simeq F_{\Zchar}\op \xto{\yo} \FunDay(F_{\Zchar}, \cC) \to \Gr^{\Zchar}_A \cC,
            \end{equation*}
            where $\yo$ is the Yoneda embedding, which is symmetric monoidal by \cite[Theorem~3.2]{Glasman-2016-Day} or \cite[Corollary~4.8.1.12, Remark~4.8.1.13]{Lurie-HA}, and the last map is the one induced on Thom constructions from the commutative diagram
            \begin{equation*}
                \begin{tikzcd}
                    {F_{\Zchar}} & A \\
                    & {\Sigma\cC\units.}
                    \arrow[from=1-1, to=1-2]
                    \arrow["0"', from=1-1, to=2-2]
                    \arrow["\Zchar", from=1-2, to=2-2]
                \end{tikzcd}
            \end{equation*}
            In particular we get a map of connective spectra $F_{\Zchar} \to (\Gr^{\Zchar}_A \cC)\units$. Moreover, this map is an isomorphism as $\EE_1$-groups, as $\Zchar$ is trivial as an $\EE_1$-map. Thus it is an isomorphism of connective spectra, as needed.


            It is left now to show, that for any $\Zchar \in \Map\Enull(A, \Sigma \cC\units)$, the induced map
            \begin{equation*}\label{eqn:map-of-aut}
                \Aut_{\Map\Enull}(\Zchar) \to \Aut_{\Lift(\Gr_A \cC)}(\Gr^{\Zchar}_A \cC) \tag{$\star$}
            \end{equation*}
            is an isomorphism.
            $\Aut_{\Map\Enull}(\Zchar)$ is computed as the fiber
            \begin{equation*}
                \begin{split}
                    \Aut_{\Map\Enull}(\Zchar) 
                    & = \fib \big( \Omega_{\Zchar}\Map_{\cnSp}(A, \Sigma \cC\units)  \to \Omega_{\Zchar}\Map_{\EE_1}(A, \Sigma\cC\units) \big) \\
                    & \simeq \fib \big( \Map_{\cnSp}(A, \cC\units) \to \Map_{\EE_1}(A, \cC\units) \big) \\
                    & = \Map\Enull(A, \cC\units).
                \end{split}
            \end{equation*}
            On the other hand, $\Aut_{\Lift(\Gr_A \cC)}(\Gr^{\Zchar}_A \cC)$ is computed as the fiber
            \begin{equation*}
                \Aut_{\Lift(\Gr_A \cC)}(\Gr^{\Zchar}_A \cC) = \fib \big( \Aut_{\EE_{\infty}}(\Gr^{\Zchar}_A \cC) \to \Aut_{\EE_1}(\Gr^{\Zchar}_A \cC) \big).
            \end{equation*}
            The pullback square
            \begin{equation*}
                \begin{tikzcd}
                    {\Aut_{\EE_{\infty}}(\Gr^{\Zchar}_A \cC)} & {\Aut_{\EE_1}(\Gr^{\Zchar}_A \cC)} \\
                    {\End_{\EE_\infty}(\Gr^{\Zchar}_A \cC)} & {\End_{\EE_1}(\Gr^{\Zchar}_A \cC)}
                    \arrow[from=1-1, to=1-2]
                    \arrow[from=1-1, to=2-1]
                    \arrow["\lrcorner"{anchor=center, pos=0.125, rotate=0}, draw=none, from=1-1, to=2-2]
                    \arrow[from=1-2, to=2-2]
                    \arrow[from=2-1, to=2-2]
                \end{tikzcd}
            \end{equation*}
            implies that
            \begin{equation*}
                \Aut_{\Lift(\Gr_A \cC)}(\Gr^{\Zchar}_A \cC) = \fib \big( \End_{\EE_{\infty}}(\Gr^{\Zchar}_A \cC) \to \End_{\EE_1}(\Gr^{\Zchar}_A \cC) \big).
            \end{equation*}
            Using \cref{prop:universal-property-thom}, $\End_{\EE_k}(\Gr^{\Zchar}_A \cC)$ is identified with the space of $\EE_k$-nullhomotopies of the composition
            \begin{equation*}
                A \to \Sigma \cC\units \to \Sigma (\Gr^{\Zchar}_A \cC)\units.
            \end{equation*}
            The identity map $\Gr^{\Zchar}_A \cC \to \Gr^{\Zchar}_A \cC$ induces a specific nullhomotopy, therefore, the space of $\EE_k$-nullhomotopies is equivalent to the space of $\EE_k$-maps
            \begin{equation*}
                A \to (\Gr^{\Zchar}_A \cC)\units.
            \end{equation*}
            We get that $\Aut_{\Lift(\Gr_A \cC)}(\Gr^{\Zchar}_A \cC)$ is identified with
            \begin{equation*}
                 \fib \big( \Map_{\cnSp}(A, (\Gr^{\Zchar}_A \cC)\units) \to \Map_{\EE_1}(A, (\Gr^{\Zchar}_A \cC)\units) \big),
            \end{equation*}
            i.e.\ $\Aut_{\Lift(\Gr_A \cC)}(\Gr^{\Zchar}_A \cC) \simeq \Map\Enull(A, (\Gr^{\Zchar}_A \cC)\units)$.

            Following the above identifications, the map $\labelcref{eqn:map-of-aut}$, is identified with the map
            \begin{equation*}
                \Map\Enull(A, \cC\units) \to \Map\Enull(A, (\Gr^{\Zchar}_A \cC)\units)
            \end{equation*}
            induced by the symmetric monoidal functor $\cC \to \Gr^{\Zchar}_A \cC$.
            As this functor induces the isomorphism $\Omega \cC\units \simeq \Omega (\Gr^{\Zchar}_A \cC)\units \simeq \ounit_{\cC}\units$, the claim follows from \cref{cor:E1-null}.
        \end{proof}

