    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \subsection{Examples}
    \label{subsec:examples}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        We show some interesting examples of twisted graded categories. Our examples will be focused on the case $A = \ZZ$, in this case $\ZZ\Enull = \tau_{\ge 1} \SS$. The most famous twisted $\ZZ$-graded category is the category of graded objects with the Koszul twist. 

        We start with the trivial example.

        \begin{example}\label{exm:twFun-0-is-Day}
            Let $0 \colon A \to \Sigma \cC\units$ be the trivial map. Then $\Gr^{0}_{A} \cC \simeq \Gr_A \cC$.
        \end{example}

        When $\cC$ admits a minus one, one can reconstruct the Koszul twist. In the proof of this we will consider the universal category admitting a minus one.

        \begin{lemma}\label{lem:universal-case}
            Let $X \in \cnSp$. The universal category $\cC\in\CAlg(\PrL)$ with a morphism of connective spectra $X \to \ounit_{\cC}\units$ is 
            \begin{equation*}
                \spc[\Sigma X] \simeq \Mod_{X}(\spc) \in \CAlg(\PrL).
            \end{equation*}
            That is,
            \begin{equation*}
                \Fun_{\CAlg(\PrL)}(\Mod_X (\spc), \cC) \simeq \Map_{\cnSp}(X, \ounit_{\cC}\units).
            \end{equation*}
        \end{lemma}

        \begin{proof}
            For any $\cC\in \CAlg(\PrL)$, by Morita theory (\cite[Theorem~4.8.4.6, Corollary~4.8.5.22]{Lurie-HA}) and using the $\ounit_{\cC}[-] \dashv (-)\units$ adjunction:
            \begin{equation*}
                \begin{split}
                    \Map_{\CAlg(\PrL)}(\Mod_{X}(\spc), \cC) 
                    & \simeq \Map_{\CAlg_{\cC}(\PrL)}(\cC \otimes \Mod_{X}(\spc), \cC) \\
                    & \simeq \Map_{\CAlg_{\cC}(\PrL)}(\Mod_{\ounit_{\cC}[X]}(\cC), \Mod_{\ounit_{\cC}} (\cC)) \\
                    & \simeq \Map_{\CAlg(\cC)}(\ounit_{\cC}[X], \ounit_{\cC}) \\
                    & \simeq \Map_{\cnSp}(X, \ounit_{\cC}\units).
                \end{split}
            \end{equation*}

        \end{proof}


        \begin{definition}\label{def:Koszul}
            Let $\cC \in \CAlg(\PrL)$ and assume $\cC$ admits a minus one, i.e.\ a group homomorphism
            \begin{equation*}
                (-1) \colon \ZZ/2 \to \ounit_{\cC}\units.
            \end{equation*}
            Define $\Kos \colon \ZZ \to \Sigma \cC\units$ as the composition
            \begin{equation*}
                \Kos \colon \ZZ \onto \ZZ/2 \xto{\Sq^2} \Sigma^2 \ZZ/2 \xto{\Sigma^2 (-1)} \Sigma^2 \ounit_{\cC}\units \to \Sigma \cC\units.
            \end{equation*}
            The factorization through $\Sigma^2 \ounit_{\cC}\units$ gives a natural $\EE_1$-nullhomotopy.

            Equivalently, it is the map
            \begin{equation*}
                \ZZ\Enull = \tau_{\ge 1} \SS \to \Sigma \ZZ/2 \xto{\Sigma (-1)} \Sigma \ounit_{\cC}\units \to \cC\units.
            \end{equation*}
        \end{definition}


        \begin{proposition}\label{prop:Kos-is-Kos}
            Let $\cC\in\CAlg(\PrL)$ admitting a minus one $(-1) \colon \ZZ/2 \to \ounit_{\cC}\units$. 
            Then the braiding in $\Gr^{\Kos}_{\ZZ} \cC$ is given by a Koszul sign:
            For any $X \in \cC$, and integers $n,m\in\ZZ$, the isomorphism 
            \begin{equation*}
                X\shift{n}\otimes X\shift{m} \isoto X\shift{m} \otimes X\shift{n}
            \end{equation*}
            is given by multiplication with $(-1)^{nm} \in \ounit_{\cC}\units$.
        \end{proposition}

        \begin{proof}
            It suffices to prove the claim for the universal presentably symmetric monoidal category admitting a minus one $\spc[\Sigma \ZZ/2] \simeq \Mod_{\ZZ/2}(\spc)$ (\cref{lem:universal-case}). We first consider the non-presentable analog. The universal symmetric monoidal category admitting a minus one is $\B \ZZ/2$ and its endomorphism monoid unit is the connective spectrum $\ZZ/2 = \End(\ounit_{\B\ZZ/2})$.
            The Koszul map is the composition
            \begin{equation*}
                \ZZ \onto \ZZ/2 \xto{\Sq^2} \Sigma^2 \ZZ/2 \simeq \Sigma (\B\ZZ/2)\units,
            \end{equation*}
            which is known to have a fiber $\tau_{\le 1} \SS$ at each $n\in \ZZ$.            
            Rolling the fiber sequence further we get the fiber sequence
            \begin{equation*}
                \Sigma \ZZ/2 \to \tau_{\le 1}\SS \to \ZZ.
            \end{equation*}
            By unstraightening, $\tau_{\ge 1}\SS \simeq \colim_{\ZZ} \Sigma{\ZZ/2}$ (which is the non-presentable analog of $\Gr^{\Kos}_{\ZZ} \B\ZZ/2$). By commutation of colimits

            \begin{equation*}
                \Gr^{\Kos}_{\ZZ} \spc[\B \ZZ/2] \simeq \spc[\colim_{\ZZ} \B\ZZ/2] \simeq \spc[\tau_{\le 1}\SS].
            \end{equation*}
            Now, as it suffices to prove the claim for $X = \ounit_{\cC}$, we can prove it for $\tau_{\le 1} \SS$.
            This follows by observing that the canonical symmetric monoidal map 
            \begin{equation*}
                \bigsqcup_{\degree} \B\Sm \simeq \Fin\core \to \SS \to \tau_{\le 1} \SS
            \end{equation*}
            is the sign map on $\pi_1$.
        \end{proof}

        \begin{remark}\label{rmrk:2-structurs-on-GrVect}
            Note that for $\cC = \Vect$, symmetric monoidal structures on $\Gr_{\ZZ}\cC$ with an $\EE_1$-trivialization are the same as maps of spectra $\tau_{\ge 1} \SS \to  \Vect\units$  which are the same as maps of abelian groups $\ZZ/2 \to k\units$. So we get that there are exactly two symmetric monoidal structures on $\Gr_{\ZZ}\Vect$ with an $\EE_1$-trivialization: The usual graded and the Koszul-graded.
        \end{remark}

        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        \subsubsection*{Higher minus one}

        This example can be extended to a higher notions of minus one:
        In \cite[Definition~4.2]{CSY-cyclotomic} Carmeli, Schlank and Yanovski define higher roots of unity, and in particular one can define a higher minus one:
        \begin{definition} 
            Let $\cC\in\CAlg(\PrL)$ of height $\chrHeight$. A minus one of height $\chrHeight$ in $\cC$ is a map of connective spectra
            \begin{equation*}
                \minusone \colon \Sigma^{\chrHeight}\ZZ/2 \to \ounit_{\cC}\units.
            \end{equation*}
            We say that it is primitive if the only commutative algebra $S\in\CAlg(\cC)$ rendering the diagram of connective spectra
            \begin{equation*}
                \begin{tikzcd}
            	{\Sigma^{\chrHeight} \ZZ/2} & \ounit_{\cC}\units \\
            	0 & S\units
            	\arrow[from=1-1, to=2-1]
            	\arrow["\minusone", from=1-1, to=1-2]
            	\arrow[from=1-2, to=2-2]
            	\arrow[from=2-1, to=2-2]
                \end{tikzcd}
            \end{equation*}
            commutative is $S=0$.
        \end{definition}

        In \cite[Definition~4.7]{CSY-cyclotomic} the higher cyclotomic extension $\ounit_{\cC}[\minusone]$ is defined and in \cite[Proposition~4.8]{CSY-cyclotomic} it is proved that $\Mod_{\ounit_{\cC}[\minusone]}(\cC)$ admits a primitive (-1) of height $\chrHeight$. In the case where $\cC$ is stable and virtually $(\Fq{2}, \chrHeight)$-oriented (\cite[\S~6]{BCSY-Fourier}), $\ounit_{\cC}[\minusone]$ is a $e = (\ZZ/2)\units$-Galois extension \cite[Proposition~6.11]{BCSY-Fourier}, and thus canonically isomorphic to $\ounit_{\cC}$. In particular such $\cC$ admits a primitive higher $(-1)$.

        \begin{example}
            For any $R\in\CAlg(\SpTn)$ at $p=2$, $\Mod_R(\SpTn)$ is virtually $(\Fq{2},\chrHeight)$-orientable (\cite[Proposition~7.27, Corollary~4.21]{BCSY-Fourier}) thus admits a minus one of height $\chrHeight$.
            In particular, the categories $\SpTn$, $\SpKn=\Mod_{\SSKn}(\SpTn)$ and $\ModEn=\Mod_{\En}(\SpTn)$ admit height $\chrHeight$ minus ones.
        \end{example}

        Other examples come from categorification.
        \begin{definition}\label{def:Vectn}
            Let $\field$ be a field of characteristic 0. 
            Define $\Vectn[1] \coloneqq \Vect \in \CAlg(\PrL)$ and $\Vectnp \coloneqq \Mod_{\Vectn} \in \CAlg(\PrL)$.

            To be more formal, we choose a sequence of inaccessible cardinals $\kappa_1 \subseteq \kappa_2 \subseteq \cdots$, and consider $\Vectn[1]$ as lying in $\CAlg(\PrL_{\kappa_1})$. We then define $\Vectnp \coloneqq \Mod_{\Vectn}(\PrL_{\kappa_{\chrHeight}}) \in \CAlg(\PrL_{\kappa_{\chrHeight+1}})$. We will usually omit this careful description and always assume we work in $\PrL_{\kappa_{\chrHeight}}$ for large enough $\chrHeight$.
        \end{definition}

        One can construct by hands\footnote{It is actually possible to extend the results of Carmeli, Schlank and Yanovski to show that any (not necessarily stable) category which is virtually $(\Fq{2},\chrHeight)$-orientable has a higher minus one, as one can show that in this case as well, $\ounit_{\cC}[\omega_{p^r}^{(n)}]$ is $e$-Galois.} a higher minus one in $\Vectn$:
        \begin{example}
            For a category $\cC\in\CAlg(\PrL)$ we have a map of connective spectra 
            \begin{equation*}
                \Sigma\ounit_{\cC}\units \to \cC\units = \cC\units
            \end{equation*}
            corresponding to the connected component of the unit.
            By induction we get a map of connective spectra
            \begin{equation*}
                \Sigma^{\chrHeight} \field\units \to (\Vectn)\units.
            \end{equation*}
            $\Vectn$ is the unit of $\Vectnp$ and thus $(-1)\in \field\units$ defines a height $\chrHeight$ minus one of $\Vectnp$:
            \begin{equation*}
                \SnCt \xto{\Sigma^{\chrHeight} (-1)} \Sigma^{\chrHeight} \field\units \to (\Vectn)\units.
            \end{equation*}
        \end{example}

        The Koszul twist required a map $\ZZ \to \Sigma^2 \ZZ/2$ (of which there are exactly 2). A higher Koszul twist can be achieved by a map $\hchar \colon \ZZ \to \Sigma^{\chrHeight+2} \ZZ/2$, or equivalently an element in $\H^{\chrHeight+2}(\ZZ, \Fq{2})$.
        \begin{definition}\label{def:higher-minus-one}
            Let $\cC \in \CAlg(\PrL)$ and $\minusone \colon \Sigma^{\chrHeight} \ZZ/2 \to \ounit_{\cC}\units$ be a minus one of height $\chrHeight$. Let $\hchar \in \H^{\chrHeight+2}(\ZZ, \Fq{2})$. Then define 
            \begin{equation*}
                \Zchar_{\hchar} \colon \ZZ \xto{\hchar} \Sigma^{\chrHeight+2} \ZZ/2 \xto{\Sigma^2 \minusone} \Sigma^2 \ounit_{\cC}\units \to \Sigma \cC\units,
            \end{equation*}
            and
            \begin{equation*}
                \Gr^{\hchar}_{\ZZ} \cC \coloneqq \Gr^{\Zchar_{\hchar}}_{\ZZ} \cC.
            \end{equation*}
        \end{definition}



        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        \subsubsection*{Dual stable stems in the oriented case}  
        \label{Galois-closed}
        Assume that $\field$ is a cyclotomically-closed field. One can think of the Koszul map $\ZZ \to \Sigma^2 \ZZ/2$ as a map $\ZZ \to \Sigma^2 \mu_{\infty}$. This can be extended in the $\infty$-semiadditive case when the unit is \quotes{cycloyomically-closed}:
        In \cite{BCSY-Fourier}, the authors introduce the notion of orientability for higher semiadditive categories, which is an analog of non-primitive roots of unity. 
        First we extend the group $\mu_{\infty}$ of roots of unity.
        \begin{definition}
            Let $\chrHeight \ge 0$.
            \begin{enumerate}
                \item Let $\In \coloneqq \tau_{\ge 0} \Sigma^{\chrHeight} I_{\QQ/\ZZ}$ be the truncated and shifted Brown--Comenetz dual of the sphere.
                \item For a prime $p$, let $\Inprime \coloneqq \tau_{\ge 0} \Sigma^{\chrHeight} I_{\QQ_p/\Zp}$ be the $p$-typical truncated and shifted Brown--Comenetz dual of the sphere.
            \end{enumerate}
        \end{definition}

        \begin{remark}
            As $\QQ / \ZZ \simeq \bigsqcap_p \QQ_p / \Zp$, $\In \simeq \bigsqcap_p \Inprime$.
        \end{remark}

        \begin{remark}\label{rmrk:maps-to-In}
            Let $X$ be a connective spectrum. Then, as $\Inprime$ is $p$-local and $X$ is connective
            \begin{equation*}
                \Map_{\cnSp}(X, \Inprime) 
                \simeq \Map_{\cnSp}(X_{(p)}, \Inprime) 
                \simeq \Map_{\cnSp}(X_{(p)}, \tau_{\ge \chrHeight}\Sigma^{\chrHeight} I_{\QQ_p/\Zp})
                \simeq \Map_{\Sp}(\Sigma^{-\chrHeight} X_{(p)}, I_{\QQ_p/\Zp}).
            \end{equation*}
            Therefore,
            \begin{equation*}
                \pi_0 \Map_{\cnSp}(X, \Inprime) \simeq \widehat{\pi}_{\chrHeight}(X_{(p)}) \coloneqq \Hom_{\Ab}(\pi_{\chrHeight} X_{(p)}, \QQ_p/\Zp).
            \end{equation*}
            Similarly,
            \begin{equation*}
                \pi_0 \Map_{\cnSp}(X, \In) \simeq \widehat{\pi}_{\chrHeight}(X).
            \end{equation*}
        \end{remark}

        We work in both the integral and $p$-typical settings, and will generally write $\In$ to denote either $\In$ (in the integral case) or $\Inprime$ (in the $p$-typical case), depending on context. We trust the reader to distinguish between the two when necessary.

        The connective spectrum $\In$ defines a height $\chrHeight$ analog of the Pontryagin dual, sending $M \in \Sp$ to $\tau_{\ge 0}\hom(M,\In)$.

        \begin{definition}
            Let $\cC$ be a presentably symmetric monoidal, $\infty$-semiadditive category. Let $R \in \CAlg(\cnSp)$. An $(R,\chrHeight)$-pre-orientation of $\cC$ is a map of connective spectra
            \begin{equation*}
                \omega \colon \tau_{\ge 0} \hom(M,\In) \to \ounit_{\cC}\units.
            \end{equation*}
        \end{definition}

        \begin{definition}
            An $R$-module $M$ is $[0,\chrHeight]$-finite if it is connective, $\chrHeight$-truncated and all its homotopy groups are finite. We denote the full subcategory of $[0,\chrHeight]$-finite $R$-modules by $\Mod_R^{[0,\chrHeight]\hyphen\mrm{finite}}$
        \end{definition}

        \begin{proposition}[{\cite[Proposition~3.10]{BCSY-Fourier}}]
            The space of $(R,\chrHeight)$-pre-orientations of $\cC$ is isomorphic to the space of natural transformations 
            \begin{equation*}
                \ounit_{\cC}[-] \to \ounit_{\cC}^{\Map(-,\In)} \qin \Fun(\Mod_R^{[0,\chrHeight]\hyphen\mrm{finite}}, \CAlg(\cC)).
            \end{equation*}
        \end{proposition}
        For a pre-orientation $\omega$, we denote the corresponding natural transformation by $\mscr{F}_{\omega}$ and call it the associated Fourier transform.

        \begin{definition}
            A pre-orientation $\omega$ is an orientation if the associated Fourier transform is a natural isomorphism. If the space of $(R,\chrHeight)$-orientation of $\cC$ is non-empty we say the $\cC$ is $(R,\chrHeight)$-orientable.
        \end{definition}

        For any $R$, $\tau_{\ge 0}\hom(R,\In) \simeq \tau_{\ge 0}\hom(\tau_{\le \chrHeight} R,\In)$. Therefore an $(R,\chrHeight)$-orientation is equivalent to a $(\tau_{\le \chrHeight} R, \chrHeight)$-orientation.

        \begin{example}
            A $(\ZZ/N, 0)$-orientation of $\Vect$ is a choice of a primitive $N$-th root of unity in $\field$. $\Vect$ is $(\SS,0)$-orientable if and only if $\field$ is cyclotomically-closed.
        \end{example}

        \begin{example}
            Let $\cC$ be $\infty$-semiadditive. A $(\ZZ/p^r,\chrHeight)$-orientation of $\cC$ is equivalent to a primitive $p^r$-th root of unity of height $\chrHeight$, as in \cite{CSY-cyclotomic}.
        \end{example}

        We interpret the $(\SS, \chrHeight)$-orientability of $\cC$ as expressing that the unit $\ounit_{\cC}$ is spherically cyclotomically closed.       

        \begin{example}[{\cite[Theorem~7.8]{BCSY-Fourier}}]
            $\ModEn$ is $(\SS,\chrHeight)$-orientable.
        \end{example}


        % \begin{corollary}
        %     Let $\cC \in \CAlg(\PrL)$ be $\infty$-semiadditive. Assume that $\cC$ is $(\SS,\chrHeight)$-orientable and that $\ounit_{\cC}$ is $\chrHeight$-truncated. Then $\cC$ is of height $\le \chrHeight$ at all primes.
        % \end{corollary}
        % \begin{proof}
        %     As $\ounit_{\cC}$ is Galois-closed at $p$, $(\ounit_{\cC}\units)\pitor_{(p)} \simeq \Inprime[\chrHeight_p]$, where $\chrHeight_p$ is the height of $\cC$ at $p$. As $\ounit_{\cC}\units$ is $\chrHeight$-truncated, $\chrHeight_p \le \chrHeight$. 
        % \end{proof}

        \begin{definition}\label{def:cyc-closure}
            A cyclotomic-closure of $\ounit_{\cC}$ is an algebra $\ounit_{\cC}\cyc \in \CAlg(\cC)$ such that:
            \begin{enumerate}
                \item $\Mod_{\ounit_{\cC}\cyc}(\cC)$ is $(\SS,\chrHeight)$-orientable.
                \item $\ounit_{\cC} \to \ounit_{\cC}\cyc$ is a Galois extension in the sense of Rognes \cite{Rognes-2008-Galois}.
                \item It is the minimal such extension: For any Galois extension $\ounit \to R$ such that $\Mod_R(\cC)$ is $(\SS,\chrHeight)$-orientable, there exists a map $\ounit_{\cC}\cyc \to R$.
            \end{enumerate}
        \end{definition}
        We do not prove the existence of Galois closures in this paper but instead assume it. The general existence of cyclotomic extensions will be addressed in a forthcoming paper by the first author.

        % In this case, we have a map\footnote{Here when working in the $p$-typical case we replace $\In$ with $\Inprime$, similarly one should replace $\QQ/\ZZ$ with $\QQ_p/\Zp$.}
        % \begin{equation*}
        %     \In \simeq (\ounit_{\cC}\units)\pitor \to \ounit_{\cC}\units.
        % \end{equation*}

        \begin{example}\label{exm:higher-minus-one-for-galois-closed}
            Any $\cC$ which is $(\SS,\chrHeight)$-oriented (at the prime 2) admits a higher minus one. It is defined as the composition
            \begin{equation*}
                \Sigma^{\chrHeight} \ZZ/2 \to \Sigma^{\chrHeight} \QQ/\ZZ \to \In \to \ounit_{\cC}\units.
            \end{equation*}
        \end{example}

        \begin{remark}
            The map $\Vectn \to \cVectn$, together with the higher minus one map \linebreak$\minusone \colon \Sigma^{\chrHeight} \ZZ/2 \to (\Vectn)\units$ induces a higher minus one of $\cVectn$. It agrees with the one of \cref{exm:higher-minus-one-for-galois-closed}.
        \end{remark}


        \begin{notation}
            Denote $\pinD \coloneqq \widehat{\pi}_{\chrHeight+1}(\SS)$. When working $p$-locally we would mean $\pinD = \widehat{\pi}_{\chrHeight+1}(\SS_{(p)})$.
        \end{notation}

        \begin{definition}\label{def:dual-stable-stems}
            Let $\cC \in \CAlg(\PrL)$ be $(\SS,\chrHeight)$-orientable. Let $\pichar \in \pinD = \pi_0(\Inplus)$. Then $\pichar$ induces a map
            \begin{equation*}
                \pichar \colon \SS \to \Inplus.
            \end{equation*}
            Taking connected covers, we get a map
            \begin{equation*}
                \tau_{\ge 1} \pichar \colon \tau_{\ge 1} \SS \to \Sigma \In \to \Sigma \ounit_{\cC}\units \to \cC\units.
            \end{equation*}
            By \cref{cor:E1-null}, it is equivalent to a map
            \begin{equation*}
                \Zchar_{\pichar} \colon \ZZ \to \Sigma^2 \In \to \Sigma^2 \ounit_{\cC}\units.
            \end{equation*}
            with an $\EE_1$ null homotopy.
            We define
            \begin{equation*}
                \Gr^{\pichar}_{\ZZ} \cC \coloneqq \Gr^{\Zchar_{\pichar}}_{\ZZ} \cC.
            \end{equation*}
        \end{definition}

        \begin{example}
            Let $\field$ be a cyclotomically-closed field of characteristic 0. Then $\Vect$ is $(\SS,0)$-orientable. $\pinD[2] = \{0, \hat{\eta}\}$ has 2 elements, and
            \begin{equation*}
                \Gr^0_{\ZZ} \Vect \simeq \Gr_{\ZZ}\Vect, \qquad \Gr^{\hat{\eta}}_{\ZZ} \Vect \simeq \Gr^{\Kos}_{\ZZ} \Vect.
            \end{equation*}
        \end{example}

        \begin{remark}\label{rmrk:height-0-dual-stems}
            The same is true for any $(\SS, 0)$-orientable category (at the prime 2). The orientation $\Fq{2} \to \ounit_{\cC}\units$ is a choice of a minus one, and with respect to it $\Zchar_{\hat{\eta}} = \Kos$ (as in \cref{def:Koszul}).
        \end{remark}


