\section{Braiding and graded categories}
\label{sec:graded-braiding}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


    In \cref{sec:twisted-graded-categories}, we constructed several symmetric monoidal structures that agree $\EE_1$-monoidally. In \cref{sec:braiding}, we discussed the braiding and the braiding characters as invariants of such structures. We now specialize and study these invariants in the case of twisted graded categories.

    We start in \cref{subsec:graded-braiding} by showing that the braiding of $\ounit_\cC\shift{a}$ for $a\in A$ is a complete invariant for twisted graded categories, reproducing both the symmetric monoidal structure, and the $\EE_1$-isomorphism to the Day monoidal structure. We also identify when two such twisted graded categories are the same, forgetting the $\EE_1$-trivialization, in term of the braiding. In the special case where $\Mod_{\cC}$ is $(\chrHeight+1)$-connected and that $\ounit_{\cC}$ is truncated, we show that the braiding of $\ounit_{\cC}\shift{a}$ depends only on a map of spaces $\B\Sinfty \to \Sigma \ounit_{\cC}\units$.
    Then, in \cref{subsec:graded-braiding-character}, we study the braiding character and show that, for $\ZZ$-graded categories and a dualizable object $V\in \cC\dbl$, the braiding character of $V\shift{1}$ agrees with the image under $\THH_\cC$ of the braiding of $V\shift{1}$. 
    We also examine the behavior of this character in graded categories for dualizable objects with finite support.
    Finally, in \cref{subsec:exterior-algebras}, we analyze the levelwise orbits of the braiding, yielding a graded-commutative algebra that we call the twisted exterior algebra. Using the previous results, we derive a generating function comparing the dimensions of twisted exterior algebras for different maps $\ZZ\Enull\to \cC\units$.


    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \subsection{Braiding in graded categories}
    \label{subsec:graded-braiding}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        Let $A \in \Ab$ and $\Zchar \colon A \to \Sigma \cC\units$ with an $\EE_1$-nullhomotopy. If the braiding of $\ounit_{\cC}\shift{a}$ is given to us for all $a\in A$, it is simple to compute the braiding of any object in $\Gr^{\Zchar}_A \cC$ with finite support. 
        We now see that these braidings actually determine $\Zchar$ and in particular the whole symmetric monoidal structure.

        For any $a\in A$, we define a new map
        \begin{equation*}
            \Zchar \circ a \colon \ZZ \xto{a} A \xto{\Zchar} \Sigma \cC\units,
        \end{equation*}
        which admits a canonical $\EE_1$-nullhomotopy.

        As $\ounit_{\cC}\shift{a}$ and $\ounit_{\cC}\shift{1}$ are invertible in $\Gr^{\Zchar}_A \cC$ and $\Gr^{\Zchar \circ a}_{\ZZ} \cC$ respectively, we can think of their braiding as maps $\hchar_{\ounit_{\cC}\shift{a}}, \hchar_{\ounit_{\cC}\shift{1}} \colon \tau_{\ge 1} \SS \to \Sigma \ounit_{\cC}\units$.
        \begin{lemma}\label{lem:braiding-of-A-determined-by-Z}
            The braiding of $\ounit_{\cC}\shift{1}$ in $\Gr^{\Zchar \circ a}_\ZZ \cC$ agrees with the braiding of $\ounit_{\cC}\shift{a}$ in $\Gr^{\Zchar}_A \cC$.
        \end{lemma}

        \begin{proof}
            The map $a \colon \ZZ \to A$ is a map of spectra over $\Sigma \cC\units$ and therefore defines a symmetric monoidal map $a_! \colon \Gr^{\Zchar\circ a}_{\ZZ} \cC \to \Gr^{\Zchar}_A \cC$, sending $\ounit_{\cC}\shift{1}$ to $\ounit_{\cC}\shift{a}$. We therefore have a commutative diagram of symmetric monoidal maps
            \begin{equation*}
                \begin{tikzcd}
                    && {(\Gr^{\Zchar \circ a}_{\ZZ} \cC))\units} \\
                    \SS && {(\Gr^{\Zchar}_A \cC)\units.}
                    \arrow["{a_!}", from=1-3, to=2-3]
                    \arrow["{\T\ounit_{\cC}\shift{1}}", from=2-1, to=1-3]
                    \arrow["{\T\ounit_{\cC}\shift{a}}"', from=2-1, to=2-3]
                \end{tikzcd}
            \end{equation*}
            The claim follows by taking connected covers.
        \end{proof}

        We may therefore direct our attention to the case $A = \ZZ$.

        \begin{lemma}\label{lem:maps-from-Z-are-from-truncated-sphere}
            Let $X$ be a connective spectrum. There is a bijection
            \begin{equation*}
                \pi_0 \Map(\ZZ, \Sigma^2 X) \simeq \pi_0 \Map(\tau_{\ge 1} \SS, \Sigma X).
            \end{equation*}
        \end{lemma}

        \begin{proof}
            Consider the exact sequence of spectra
            \begin{equation*}
                \Sigma^{-1} \ZZ \to \tau_{\ge 1} \SS \to \SS
            \end{equation*}
            which induces the exact sequence of spectra
            \begin{equation*}
                 \hom(\SS, \Sigma X) \to \hom(\tau_{\ge 1} \SS, \Sigma X) \to \hom(\Sigma^{-1} \ZZ, \Sigma X).
            \end{equation*}
            The result now follows as $\pi_0$ and $\pi_{-1}$ of $\Sigma X = \hom(\SS, \Sigma X)$ vanish.
        \end{proof}

        \begin{corollary}
            Let $\cC \in \CAlg(\PrL)$. Then composing with $\Sigma^2\ounit_{\cC}\units \to \Sigma \cC\units$ defines a bijetion
            \begin{equation*}
                \pi_0 \Map_{\cnSp}(\ZZ, \Sigma^2 \ounit_{\cC}\units) \simeq \pi_0 \Map\Enull(\ZZ, \Sigma \cC\units).
            \end{equation*}
            That is, a map $\ZZ \to \Sigma \cC\units$ with an $\EE_1$-nullhomotopy is equivalent to a map $\ZZ \to \Sigma^2 \ounit_{\cC}\units$.
        \end{corollary}
        \begin{proof}
            Since $\ZZ\Enull = \tau_{\ge 1} \SS$, 
            \begin{equation*}
                \Map\Enull(\ZZ, \Sigma \cC\units) \simeq \Map(\tau_{\ge 1} \SS, \cC\units).
            \end{equation*}
            Since $\tau_{\ge 1} \SS$ is connected, $\Map(\tau_{\ge 1} \SS, \cC\units) \simeq \Map(\tau_{\ge 1} \SS, \tau_{\ge 1} \cC\units) \simeq \Map(\tau_{\ge 1} \SS, \Sigma \ounit_{\cC}\units)$.
            Finally, by \cref{lem:maps-from-Z-are-from-truncated-sphere}, 
            \begin{equation*}
                \pi_0 \Map\Enull(\ZZ, \Sigma \cC\units) \simeq \pi_0 \Map(\tau_{\ge 1} \SS, \Sigma \ounit_{\cC}\units) \simeq \pi_0\Map(\ZZ, \Sigma^2 \ounit_{\cC}\units).
            \end{equation*}
        \end{proof}

        \begin{corollary}\label{cor:E1-nullhomotopy-and-surjection}
            The map $\pi_0\Map(\ZZ, \Sigma^2 \ounit_{\cC}\units) \to \pi_0\Map(\ZZ, \Sigma \cC\units)$ is surjective.
        \end{corollary}
        \begin{proof}
            It is enough to show that any map $\ZZ \to \Sigma \cC\units$ is $\EE_1$-nullhomotopic, or equivalently that the pointed map
            \begin{equation*}
                S^1 \simeq \B\ZZ \to \B\Sigma \cC\units
            \end{equation*}
            is null. This is true as $\B\Sigma\cC\units$ is simply connected.
        \end{proof}

        \begin{remark}\label{rmrk:kernel-of-forgetting-the-E1-nullhomotopy}
            The exact sequence $\Sigma \ounit_{\cC}\units \to \cC\units \to \Pic(\cC)$ induces an exact sequence
            \begin{equation*}
                \hom(\ZZ, \Sigma^2 \ounit_{\cC}\units) \to \hom(\ZZ, \Sigma\cC\units) \to \hom(\ZZ, \Sigma \Pic(\cC)).
            \end{equation*}
            The long exact sequence of homotopy groups together with \cref{cor:E1-nullhomotopy-and-surjection} imply there is a short exact sequence
            \begin{equation*}
                0 \to \Pic(\cC)/\Pic^{\mrm{str}}(\cC) \to \pi_0\hom(\ZZ, \Sigma^2 \ounit_{\cC}\units) \to \pi_0 \hom(\ZZ, \Sigma \cC\units) \to 0,
            \end{equation*}
            where $\Pic^{\mrm{str}}(\cC) = \pi_0 \hom(\ZZ, \cC\units)$ is the group of strict Picard elements.
            The map
            \begin{equation*}
                \Pic(\cC) / \Pic^{\mrm{str}}(\cC) \to \pi_0 \hom(\ZZ, \Sigma^2 \ounit_{\cC}\units) \simeq \pi_0 \hom(\tau_{\ge 1}\SS, \Sigma \ounit_{\cC}\units)
            \end{equation*}
            sends a Picard element $Z$ to its braiding $\hchar_{Z}$.
        \end{remark}

        \begin{definition}
            Let $\Zchar \colon \ZZ \to \Sigma^2\ounit_{\cC}\units$. Then by \cref{lem:maps-from-Z-are-from-truncated-sphere}, it is equivalent to a map 
            \begin{equation*}
                \hchar_{\Zchar} \colon \tau_{\ge 1}\SS \to \Sigma\ounit_{\cC}\units
            \end{equation*}
            such that the composition $\ZZ \to \Sigma \tau_{\ge 1} \SS \xto{\hchar_{\Zchar}} \Sigma^2\ounit_{\cC}\units$ is $\Zchar$.
        \end{definition}

        \begin{corollary}\label{cor:graded-trivial-iff-picard}
            Let $\Zchar \colon \ZZ \to \Sigma^2 \ounit_{\cC}\units$ be a map of connective spectra. The symmetric monoidal category $\Gr^{\Zchar}_{\ZZ} \cC$ is isomorphic to $\Gr_{\ZZ} \cC$ if and only if there is $Z \in \cC\units$ and an isomorphism $\hchar_{Z} \simeq \hchar_{\Zchar}$.
        \end{corollary}
        \begin{proof}
            Forgetting the $\EE_1$ isomorphism to $\Gr_{\ZZ} \cC$, the symmetric monoidal structure is determined by the map $\ZZ \xto{\Zchar} \Sigma^2 \ounit_{\cC}\units \to \Sigma \cC\units$. It is the Day symmetric monoidal structure if and only if this map is null. By \cref{rmrk:kernel-of-forgetting-the-E1-nullhomotopy}, the composition is nullhomotopic if and only if $\hchar_{\Zchar} \simeq \hchar_{Z}$ for some $Z \in \cC\units$.
        \end{proof}


        \begin{proposition}\label{prop:braiding-of-1<1>-determines-the-character}
            Let $\Zchar \colon \ZZ \to \Sigma^2 \ounit_{\cC}\units$. Then $\hchar_{\Zchar}$ is the braiding of $\ounit_{\cC}\shift{1}$ in $\Gr^{\Zchar}_\ZZ \cC$.
        \end{proposition}


        \begin{proof}
            By \cref{lem:cofiber-of-pic-Day}, there is a cofiber sequence
            \begin{equation*}
                \cC\units \to (\Gr^{\Zchar}_{\ZZ}\cC)\units \to \ZZ,
            \end{equation*}
            and by the proof of \cref{thm:twFun-are-all-lifts}, the cofiber map $\ZZ \to \Sigma \cC\units$ is $\Zchar$.

            Consider also the cofiber sequence of the connected cover
            \begin{equation*}
                \Sigma \ounit_{\cC}\units \to (\Gr^{\Zchar}_{\ZZ}\cC)\units \to \Pic(\Gr^{\Zchar}_{\ZZ} \cC),
            \end{equation*}
            which admits a natural map to the previous cofiber sequence.

            The element $\ounit_{\cC}\shift{1}\in(\Gr^{\Zchar}_{\ZZ}\cC)\units$ induces a map $\T \ounit_{\cC}\shift{1} \colon \SS \to (\Gr^{\Zchar}_{\ZZ}\cC)\units$ which, by definition, its connected cover is the braiding of $\ounit_{\cC}\shift{1}$. On $\pi_0$ it is a map $\ZZ \to \Pic(\Gr^{\Zchar}_{\ZZ} \cC)$, which is a retract of the natural map $\Pic(\Gr^{\Zchar}_{\ZZ} \cC) \to \ZZ$. 

            We summarize this data as the following diagram where the columns are cofiber sequences:
            \begin{equation*}
                \begin{tikzcd}
                    {\tau_{\ge 1}\SS} & {\Sigma\ounit_{\cC}\units} & {\cC\units} \\
                    \SS & {(\Gr^{\Zchar}_{\ZZ}\cC)\units} & {(\Gr^{\Zchar}_{\ZZ}\cC)\units} \\
                    \ZZ & {\Pic(\Gr^{\Zchar}_{\ZZ}\cC)} & \ZZ \\
                    {\Sigma\tau_{\ge 1}\SS} & {\Sigma^2\ounit_{\cC}\units} & {\Sigma\cC\units.}
                    \arrow["{\hchar_{\ounit_{\cC}\shift{1}}}", from=1-1, to=1-2]
                    \arrow[from=1-1, to=2-1]
                    \arrow[from=1-2, to=1-3]
                    \arrow[from=1-2, to=2-2]
                    \arrow[from=1-3, to=2-3]
                    \arrow["{\T \ounit_{\cC}\shift{1}}", from=2-1, to=2-2]
                    \arrow[from=2-1, to=3-1]
                    \arrow[equals, from=2-2, to=2-3]
                    \arrow[from=2-2, to=3-2]
                    \arrow[from=2-3, to=3-3]
                    \arrow["{\ounit_{\cC}\shift{1}}", from=3-1, to=3-2]
                    \arrow[curve={height=12pt}, equals, from=3-1, to=3-3]
                    \arrow[from=3-1, to=4-1]
                    \arrow[from=3-2, to=3-3]
                    \arrow[from=3-2, to=4-2]
                    \arrow["\Zchar"{description}, dashed, from=3-3, to=4-2]
                    \arrow["\Zchar", from=3-3, to=4-3]
                    \arrow["{\Sigma\hchar_{\ounit_{\cC}\shift{1}}}", from=4-1, to=4-2]
                    \arrow[from=4-2, to=4-3]
                \end{tikzcd}
            \end{equation*}
            We deduce that the composition $\ZZ \to \Sigma \tau_{\ge 1} \SS \xto{\Sigma \hchar_{\ounit_{\cC}\shift{1}}} \Sigma^2 \ounit_{\cC}\units$ is isomorphic $\Zchar$. Therefore, $\hchar_{\ounit_{\cC}\shift{1}} \simeq \hchar_{\Zchar}$.
        \end{proof}

        \begin{corollary}
            The braiding of $\ounit_{\cC}\shift{1}$ determines the symmetric monoidal structure of $\Gr^{\Zchar}_\ZZ \cC$ as a $\cC$-linear symmetric monoidal category.
        \end{corollary}

        \begin{corollary}\label{cor:braiding-for-general-A-determined}
            Let $A \in \Ab$, $\Zchar \colon A\Enull \to \cC\units$ and $S\subseteq A$ a set of generators. Then the set of braidings $\hchar_{\ounit_{\cC}\shift{a}}$ for $a\in S$ determines the symmetric monoidal structure of $\Gr^{\Zchar}_A \cC$ as a $\cC$-linear symmetric monoidal category.
        \end{corollary}


