        \begin{remark}[The braiding of a higher minus one as a map of spaces]
            Assume $\cC$ admits a higher minus one $\Sigma^{\chrHeight} \ZZ/2 \to \ounit_{\cC}\units$. We can understand quite concretely the braiding, and therefore the symmetric monoidal structure, of $\ZZ$-graded categories induced by it and by a cohomology class $\hchar \in \H^{\chrHeight+2}(\ZZ, \Fq{2})$ (\cref{def:higher-minus-one}). The braiding map $\MM \to \Sigma \ounit_{\cC}\units$, choosing $\ounit_{\cC}\shift{1}$ factors through $\Sigma^{\chrHeight+1}\ZZ/2$ and defines a cohomology class $f(\hchar) \in \H^{\chrHeight+1}(\MM, \Fq{2})$, classifying the underlying map of spaces of the braiding, and which does not depend on $\cC$.

            Working with the universal category admitting a minus one of height $\chrHeight$, i.e.\ $\Mod_{\Sigma^{\chrHeight}\ZZ/2}\spc$, one can verify that $f$ commutes with Steenrod squares. That is, considering the map 
            \begin{equation*}
                \Sq^i \hchar \colon \ZZ \xto{\hchar} \Sigma^{\chrHeight+2} \ZZ/2 \xto{\Sq^i} \Sigma^{\chrHeight+i+2} \ZZ/2,
            \end{equation*}
            the corresponding cohomology class is 
            \begin{equation*}
                f(\Sq^i \hchar) \simeq \Sq^i f(\hchar) \colon \MM \xto{f(\hchar)} \Sigma^{\chrHeight+1} \ZZ/2 \xto{\Sq^i} \Sigma^{\chrHeight+i+1} \ZZ/2.
            \end{equation*}

            In particular, $f \colon \H^{*+1}(\ZZ, \Fq{2}) \to \H^*(\MM, \Fq{2})$, for $* \ge 1$, is a map of modules over the Steenrod algebra $\StAlg$. We can reduce to the case
            \begin{equation*}
                f \colon \StAlg^{\ge 2}[1] \to \H^{\ge 1}(\MM, \Fq{2}).
            \end{equation*}
            The graded module $\StAlg^{\ge 2}$ is generated by ${\Sq^{2^j}}$ for $j \ge 1$, therefore all cohomology classes appearing are Steenrod squares applied to monomials in $f(\Sq^{2^j}) \in \H^{2^j-1}(\MM, \Fq{2})$. In \cite{Giusti-Salvatore-Sinha-2022-cohomology-of-symmetric-groups}, the Hopf ring $\H^*(\MM, \Fq{2})$, is completely described. In particular they show that it is generated as a Hopf ring by classes $\gamma_{\ell, k} \in \H^{k(2^\ell - 1)}(\B \Sigma_{k 2^{\ell}})$. 
            Using \cref{prop:Kos-is-Kos}, one can show that $f(\Sq^2) = \gamma_{1,1}$, and using \cite[Theorem 8.3]{Giusti-Salvatore-Sinha-2022-cohomology-of-symmetric-groups} and the Cartan formula, $\Sq^I \gamma_{1,1} \in \{0, \gamma_{1,1}^{|I|-1}\}$. We now claim by induction on $i$ that $f(\Sq^i) \in \{0, \gamma_{1,1}^{i-1}\}$. If $i$ is not a power of 2, then by the Adem relations we can express $f(\Sq^i)$ as a linear combination of $\Sq^{i_1}f(\Sq^{i_2})$ for small values of $i_1$, therefore finishing by induction. 
            If $i$ is a power of $2$, we prove by a new induction, that $f(\Sq^j)\in \{0, \gamma_{1,1}^{j-1}\}$ for $i < j < 2i$. For this, we use the Adem relations to express $\Sq^j$ as a linear combination of products of smaller squares. Now we express $\Sq^{2i-1}$ also as $\Sq^{i-1}\Sq^i$ plus lower terms. Therefore, by induction, $f(\Sq^{i-1}\Sq^i) \in \{0,\gamma_{1,1}^{2i-2}\}$. We then get that 
            \begin{equation*}
                f(\Sq^i)^2 = \Sq^{i-1}f(\Sq^i) = f(\Sq^{i-1}\Sq^i) \in \{0, \gamma_{1,1}^{2i-2}\}.
            \end{equation*}
            As $\H^*(\MM, \Fq{2})$ is free divided powers algebra, $f(\Sq^i) \in \{0, \gamma_{1,1}^{i-1}\}$.

            This shows that there are only two families of cohomology classes coming from this construction, one is the trivial, and the second is $\{\gamma_{1,1}^{\degree}\}$. 
        \end{remark}

        \begin{remark}\label{rmrk:maps-from-symmetric-groups-and-infty}
            Inverting the map $+1 \colon \MM \to \MM$ on the free commutative monoid $\MM$, thought of as an $\MM$-module in $\spc$, is the space $\MM[-1] \simeq \ZZ \times \B\Sigma_{\infty}$ (see \cite[Appendix~C]{Bunke-Nikolaus-Tamme-2018-Belinson-regulator} for element inversions vs. localizations). Although $\MM[-1]$ is not the group completion in spaces, it is true after stabilization --- $\SS[\ZZ \times \B\Sinfty] \simeq \SS[\SS]$.
            Looking at the connected covers we get an isomorphism
            \begin{equation*}
                \redSS[\B\Sinfty] \simeq \redSS[\tau_{\ge 1} \SS] \qin \cnSp.
            \end{equation*}

            Define the map of spaces
            \begin{equation*}
                j_{\infty} \colon  \B\Sinfty \xto{u} \redSS[\B\Sinfty] \simeq \redSS[\tau_{\ge 1} \SS] \xto{c} \tau_{\ge 1} \SS,
            \end{equation*}
            where $u, c$ are the unit and counit of the $(\redSS[-] \dashv \text{forgetful})$ adjunction.
            The maps $j_m \colon \B\Sm \to \tau_{\ge 1} \SS$ of \cref{rmrk:Sm-action-from-braiding} can be written equivalently as the composition $\B\Sm \to \B\Sinfty \xto{j_{\infty}} \tau_{\ge 1} \SS$.
        \end{remark}

        \begin{definition}
            Let $\Zchar \colon \ZZ \to \Sigma^2\ounit_{\cC}\units$. Define the $\Sinfty$-representation
            \begin{equation*}
                \hchar_{\Zchar}^{\infty} \colon \B\Sinfty \xto{j_{\infty}} \tau_{\ge 1} \SS \xto{\hchar_{\Zchar}} \B\ounit_{\cC}\units.
            \end{equation*}
        \end{definition}


        \begin{remark}\label{rmrk:BSinfty-is-truncated-sphere-after-stabilization}
           The map $\hchar_{\Zchar}^{\infty}$ determines the map $\hchar_{\Zchar}$ as a map of pointed spaces. Indeed, this data is equivalent to the map of connective spectra
            \begin{equation*}
                \redSS[\B\Sinfty] \simeq \redSS[\tau_{\ge 1} \SS] \xto{c} \tau_{\ge 1} \SS \xto{\hchar_{\Zchar}} \Sigma \ounit_{\cC}\units.
            \end{equation*}
        \end{remark}

