        \subsubsection*{Braiding and truncatedness in highly connected categories}

        We can say more in the case where $\Mod_{\cC}$ is $(\chrHeight+1)$-connected, as defined in \cite{BCSY-Fourier}.
        \begin{definition}[{\cite[\textsection~6.4]{BCSY-Fourier}}]\label{def: cat connectedness}
            A symmetric monoidal category $\cC$ is said to be $d$-connected (at $p$) if for any $d$-truncated, $\pi$-finite ($p$-local) space $A$, the natural map
            \begin{equation*}
                A \to \Map_{\CAlg(\cC)}(\ounit^A, \ounit)
            \end{equation*}
            is an isomorphism.
        \end{definition}


        \begin{definition}
            A connective spectrum is $\pi$-finite if it is truncated and all its homotopy groups are finite. A spectrum is $\pi$-torsion if it is isomorphic to a (filtered) colimits of $\pi$-finite spectra. Let $\Sp\pitor\subseteq \cnSp$ be the subcategory of $\pi$-torsion connective spectra and $\plocSp\pitor \subseteq \cnSp$ be the subcategory of $\pi$-finite $p$-local connective spectra. Denote the right adjoints of the inclusions by
            \begin{equation*}
                (-)\pitor \colon \cnSp \to \Sp\pitor, \qquad (-)_{(p)}\pitor \colon \cnSp \to \plocSp\pitor.
            \end{equation*}
        \end{definition}

        \begin{theorem}[{\cite[Proposition~6.38, Corollary~6.40, Corollary~6.45, Theorem~6.58]{BCSY-Fourier}}]\label{thm:connectedness-implies-pitor}
            Let $\cC \in \CAlg(\PrL)$ be $\infty$-semiadditive and $(\Fp, \chrHeight)$-oriented at $p$. Assume that $\Mod_{\cC}$ is $(\chrHeight+1)$-connected at $p$, then
            \begin{equation*}
                (\ounit_{\cC} \units)\pitor_{(p)} \simeq \Inprime.
            \end{equation*}
        \end{theorem}

        \begin{example}[{\cite[Theorem~7.8]{BCSY-Fourier}}]
            $\ModEn$ is $(\chrHeight+1)$-connected at the prime $p$. It is $1$-connected at all primes $\ell \neq p$.
        \end{example}

        \begin{corollary}
            Let $\cC \in \CAlg(\PrL)$ be $\infty$-semiadditive. Assume that $\cC$ is $(\Fp, \chrHeight)$-oriented and $(\chrHeight+1)$-connected at all primes $p$. Then
            \begin{equation*}
                (\ounit_{\cC}\units)\pitor \simeq \In.
            \end{equation*}
        \end{corollary}

        % \begin{corollary}
        %     Let $\cC \in \CAlg(\PrL)$ be $\infty$-semiadditive. Assume that $\ounit_{\cC}$ is $\chrHeight$-truncated and Galois-closed. Then $\cC$ is of height $\le \chrHeight$ at all primes.
        % \end{corollary}
        % \begin{proof}
        %     As $\ounit_{\cC}$ is Galois-closed at $p$, $(\ounit_{\cC}\units)\pitor_{(p)} \simeq \Inprime[\chrHeight_p]$, where $\chrHeight_p$ is the height of $\cC$ at $p$. As $\ounit_{\cC}\units$ is $\chrHeight$-truncated, $\chrHeight_p \le \chrHeight$. 
        % \end{proof}

        In an announced work of Johnson-Freyd and Reuter, they construct a pro-Galois extension $\Vectn \to \overline{\catname{Vect}}_{\field}^n$, such that $\Mod_{\overline{\catname{Vect}}_{\field}^n}$ is $(\chrHeight+1)$-connected. As an example, $\overline{\catname{Vect}}_{\field} = \sVect$ (\cite{Johson-Freyd-2017-sVect}). 

        Having introduced the necessary definitions and notation, we now return to the study of braidings. We restrict to the case where the underlying space of $\ounit_{\cC}$ is truncated, so that $\Sigma \ounit_{\cC}\units$ is also truncated. In this setting, the map
        \begin{equation*}
            \hchar_{\Zchar} \colon \tau_{\ge 1} \SS \to \Sigma \ounit_{\cC}\units
        \end{equation*}
        factors through some truncation $\tau_{[1,d+1]} \SS$ which is a $\pi$-finite spectrum.

        \begin{corollary}\label{cor:truncated-unit-truncated-map}
            Assume that $\ounit_{\cC}$ is $d$-truncated. Then $\hchar_{\Zchar}$ factors uniquely as
            \begin{equation*}
                \hchar_{\Zchar} \colon \tau_{\ge 1} \SS \to \tau_{\ge [1, d+1]} \SS \xto{\hchar_{\Zchar}^{\pi}} \Sigma(\ounit_{\cC}\units)\pitor \to \Sigma \ounit_{\cC}\units.
            \end{equation*}
        \end{corollary}

        \begin{lemma}
            If $\cC$ has an $\chrHeight$-truncated unit, then $\Mod_{\cC}$ has an $(\chrHeight+1)$-truncated unit.
        \end{lemma}
        \begin{proof}
            It follows by the identity $\ounit_{\cC} \simeq \Omega \cC\core \in \spc$.
        \end{proof}

        \begin{corollary}
            The unit of $\Vectn$ is $\chrHeight$-truncated.
        \end{corollary}


        \begin{proposition}
            Let $\cC \in \CAlg(\PrL)$ be $\infty$-semiadditive. Assume that for every $p$, $\cC$ is $(\Fp,\chrHeight_p)$-orientable and $\Mod_{\cC}$ is $(\chrHeight_p+1)$-connected. 
            Assume that $\ounit_{\cC}$ is $d$-truncated.
            Let $\Zchar_1, \Zchar_2 \colon \ZZ \to \Sigma^2 \ounit_{\cC}\units$ and assume $\hchar_{\Zchar_1}^{\infty} \neq \hchar_{\Zchar_2}^{\infty}$. Then $\Zchar_1 \neq \Zchar_2$.

            That is, the $\Sinfty$-representation $\hchar_{\Zchar}^{\infty}$ determines the symmetric monoidal structure.
        \end{proposition}

        \begin{proof}
            It is enough to verify that $\hchar_{\Zchar}^{\infty}$ determines $\hchar_{\Zchar}$. By \cref{cor:truncated-unit-truncated-map} it is enough to verify that it determines $\hchar_{\Zchar}^{\pi}$. Moreover, it is enough to check it after $p$-localization at all primes $p$. Let $p$ be a prime and consider
            \begin{equation*}
                (\hchar_{\Zchar}^{\infty})_{(p)} \colon \redSS[\B\Sinfty]_{(p)} \to \Sigma(\ounit_{\cC}\units)_{(p)}.
            \end{equation*}
            As $(\Sigma\ounit_{\cC}\units)_{(p)}$ is $(d+1)$-truncated, this map is equivalent to a map
            \begin{equation*}
                (\hchar_{\Zchar}^{\infty})_{(p)} \colon \Sigma^{-1} \tau_{\le d+1} \redSS[\B\Sinfty]_{(p)} \to (\ounit_{\cC}\units)_{(p)}.
            \end{equation*}
            Note moreover, that $\Sigma^{-1} \tau_{\le d+1} \redSS[\B\Sinfty]_{(p)} \simeq \tau_{\le d} \Omega \redSS[\B\Sinfty]_{(p)}$ is a $\pi$-finite connective spectrum. Therefore, by \cref{thm:connectedness-implies-pitor}, it is equivalent to a map
            \begin{equation*}
                (\hchar_{\Zchar}^{\infty})_{(p)} \colon \tau_{\le d} \Omega \redSS[\B\Sinfty]_{(p)} \to \Inprime[\chrHeight_p].
            \end{equation*}
            By \cref{rmrk:maps-to-In} and \cref{rmrk:BSinfty-is-truncated-sphere-after-stabilization}, it is the same as an element
            \begin{equation*}
                (\hchar_{\Zchar_i}^{\infty})_{(p)} \in \widehat{\pi}_{\chrHeight_p}(\tau_{\le d} \Omega \redSS[\B\Sinfty]_{(p)}) \simeq \widehat{\pi}_{\chrHeight_p+1}(\redSS[\tau_{\ge 1} \SS]_{(p)}).
            \end{equation*}

            The map $(\hchar_{\Zchar}^{\pi})_{(p)}$ is a map of connective spectra
            \begin{equation*}
                \hchar_{\Zchar}^{\pi} \colon \tau_{[1,d+1]} \SS_{(p)} \to \Sigma\Inprime[\chrHeight_p],
            \end{equation*}
            which is equivalent to a map
            \begin{equation*}
                \hchar_{\Zchar}^{\pi} \colon \Omega \tau_{[1, d+1]} \SS_{(p)} \to \Inprime[\chrHeight_p].
            \end{equation*}
            By \cref{rmrk:maps-to-In}, this is the same as an element
            \begin{equation*}
                \hchar_{\Zchar}^{\pi} \in \widehat{\pi}_{\chrHeight_p}(\Omega \tau_{[1,d+1]} \SS_{(p)}) \simeq \widehat{\pi}_{\chrHeight_p +1}(\tau_{\ge 1} \SS_{(p)}).
            \end{equation*}

            Following \cref{rmrk:BSinfty-is-truncated-sphere-after-stabilization}, $(\hchar_{\Zchar}^{\infty})_{(p)}$ is the image of $(\hchar_{\Zchar}^{\pi})_{(p)}$ under the natural map from the unit map $\SS[\tau_{\ge 1} \SS] \to \tau_{\ge 1} \SS$. But this map has a section on the level of underlying spaces by the zig-zag identities, which in particular gives a retract on the level of $\hat{\pi}_{\chrHeight_p+1}$. That is, the map $\hchar_{\Zchar}^{\pi} \mapsto \hchar_{\Zchar}^{\infty}$ is injective.
        \end{proof}

