    \subsection{Braiding character in graded categories}
    \label{subsec:graded-braiding-character}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        In \cref{subsec:graded-braiding} we saw that the braiding is a complete invariant. Therefore, for most cases it is hard to compute. The braiding character of \cref{subsec:braiding-character} is a simpler invariant, and has an internal description in graded categories.        

        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        \subsubsection*{Characters and Thom constructions}

        We use the theory of $\cC$-atomic objects as defined in \cite{Ben-Moshe-Schlank-2024-K-theory} when $\cC$ is a mode and in \cite{Ramzi-2023-seperability} for general $\cC$. In our categories of interest, atomic objects are just dualizable objects.
        \begin{definition}
            Let $\cD \in \Mod_{\cC}$. An object $X \in \cD$ is called $\cC$-atomic (or just atomic when $\cC$ is clear from context) if $X[-] \colon \cC \to \cD$ is an internal left adjoint in $\Mod_{\cC}$.

            We denote the full subcategory consisting of $\cC$-atomic objects in $\cD$ by $\cD\cCat$ (or just $\cD\at$ when $\cC$ is clear from context).
        \end{definition}

        \begin{example}[{\cite[Lemma~6.6]{Ramzi-2023-seperability}}]
            $\cC\at \simeq \cC\dbl$.
        \end{example}

        \begin{example}[{\cite[Lemma~4.50]{Ramzi-2024-rigid}}]\label{exm:rigit-atomic-dualizable}
            Let $\cD \in \CAlg(\cC)$ be rigid over $\cC$, in the sense of \cite[Definition~9.1.2]{Gaitsgory-Rozenblyum-2019-DAG}. Then $\cD\at \simeq \cD\dbl$
        \end{example}

        Our categories of interest are Thom categories, which are all rigid:
        \begin{proposition}\label{lem:Thom-is-rigid}
             Let $X\in \cnSp$ and $f \colon X \to \Mod_{\cC}\units$ be a map of connective spectra. 
             Then $\Th(f)$ is rigid over $\cC$. In particular, $\Th(f)\at \simeq \Th(f)\dbl$.
        \end{proposition}
        \begin{proof}
            By \cite[Lemma 4.54]{Ramzi-2024-rigid} it suffices to verify that:
            \begin{enumerate}
                \item\label{cond:atomic-unit} The unit $\ounit_{\Th(f)}$ is $\cC$-atomic,
                \item\label{cond:multiplication-is-left-adjoint} the multiplication map $\Th(f)\otimes_\cC \Th(f) \to \Th(f) \in \Mod_{\Th(f)}(\cC)$ is internally left adjoint.
            \end{enumerate} 

            Let $i \colon 0 \to X$ be the zero map. Then $\ounit_{\Th(f)}[-] \colon \cC \to \Th(f)$ is the functor $i_!$ which admits a $\cC$-linear right adjoint $i^*$. Therefore $\ounit_{\Th(f))}$ is atomic.

            By the Thom isomorphism (\cite[Proposition~3.16,Corollary 3.17]{Antolin-Barthel-2019-Thom}), 
            \begin{equation*}
                \Th(F)\otimes_\cC \Th(F)\simeq \Th(F)[X].
            \end{equation*}
            Under this isomorphism, the multiplication map is $X_!$, which admits a $\Mod_{\Th(F)}(\cC)$-linear right adjoint $X^*$, proving \labelcref{cond:multiplication-is-left-adjoint}.                
            The implication is \cref{exm:rigit-atomic-dualizable}.
        \end{proof}

        The topological Hochschild homology of a Thom ring spectrum was computed in \cite{Blumberg-Cohen-Schlichtkrull-2010-THH-of-Thom}. Their results were extended to $\THH_{\cC}$ of a $\cC$-linear Thom category, for general presentably symmetric monoidal category $\cC$ in \cite{Carmeli-Cnossen-Ramzi-Yanovski-2022-characters}. We recall their results:

        \begin{definition}\label{def:character-of-a-map}
            Let $X \in \spc$, $Y \in \cnSp$ and $f \colon X \to Y$. Define the character of $f$ as the map\footnote{In the case $Y = \cC\units$, $f$ is an $X$-local system of invertible elements and therefore its character (\cref{def:character}) is defined. By \cref{lem:trace-is-eta+id}, it agrees with this definition.

            This map is also classically known as the \emph{transgression} of $f$.}
            \begin{equation*}
                \chi_f \colon \L X \xto{\L f} \L Y \simeq Y \times \Omega Y \xto{\eta + \id} \Omega Y.
            \end{equation*}
        \end{definition}
        In the case $Y = \Mod_{\cC}\units$, then $\Omega Y \simeq \cC\units$.

        \begin{remark}\label{rmrk:character-between-spectra}
            If $X \in \cnSp$ and $f \colon X \to Y$ is a map of connective spectra, then, by naturality of the decomposition of $\L$ and of $\eta + \id$, the character of $f$ is isomorphic to the map
            \begin{equation*}
                \L X \simeq X \times \Omega X \xto{\eta + \id} \Omega X \xto{\Omega f} \Omega Y.
            \end{equation*}
        \end{remark}

        \begin{theorem}[{\cite[Theorem~1]{Blumberg-Cohen-Schlichtkrull-2010-THH-of-Thom}, \cite[Corollary~7.15]{Carmeli-Cnossen-Ramzi-Yanovski-2022-characters}}]\label{thm:THH-of-Th}
            Let $X$ be a space and $f \colon X \to \Mod_{\cC}\units$. Then $\Th(f)\in \Mod_{\cC}$ is dualizable and
            \begin{equation*}
                \THH_{\cC}(\Th(f)) \simeq \Th(\chi_f).
            \end{equation*}
        \end{theorem}

         \begin{lemma}
            Let $A \in \Ab$ and $\Zchar \in \Map\Enull(A, \Sigma\cC\units)$. Then
            \begin{equation*}
                \THH_{\cC}(\Gr^{\Zchar}_A \cC) \simeq \ounit_{\cC}[A] \qin \CAlg(\Gr_A \cC),
            \end{equation*}
            and in particular does not depend on $\Zchar$.
        \end{lemma}

        \begin{proof}
            By \cref{thm:THH-of-Th} it is enough to see that the character map $\chi_{\Zchar} \colon \L A \to \cC\units$ is zero. But by \cref{rmrk:character-between-spectra} it factors through $\Omega A \simeq 0$.
        \end{proof}

