        \subsubsection*{Braiding characters}

        We start by defining a different version of the braiding character of objects in degree exactly 1 in $\ZZ$-graded categories.
        \begin{definition}
            Let $\Zchar \colon \ZZ \to \Sigma^2 \ounit_{\cC}\units$. Let $V \in \cC\dbl$. By \cref{lem:Thom-is-rigid}, the braiding of $V\shift{1} \in \Gr^{\Zchar}_{\ZZ} \cC$ 
            \begin{equation*}
                \T V\shift{1} \colon \cC[\MM] \to \Gr^{\Zchar}_{\ZZ} \cC
            \end{equation*}
            is internal left adjoint. Define
            \begin{equation*}
                \mscr{X}^{\Zchar}_{\T V\shift{1}} \colon \ounit_{\cC}[\L \MM] \to \ounit_{\cC}[\ZZ] \qin \CAlg(\cC)
            \end{equation*}
            as its image under $\THH_{\cC}$.
        \end{definition}

        We can define this variant in any graded category with an object concentrated in a single degree, as we always have a symmetric monoidal map $\Gr^{\Zchar\circ a}_{\ZZ} \cC \to \Gr^{\Zchar}_A \cC$ sending $V\shift{1}$ to $V\shift{a}$.

        \begin{definition}
            Let $A \in \Ab$ and $\Zchar \in \Map\Enull(A, \Sigma \cC\units)$. Let $V \in \cC\dbl$ and $a\in A$. Then define 
            \begin{equation*}
                \mscr{X}^{\Zchar}_{\T V\shift{a}} \coloneqq \mscr{X}^{\Zchar \circ a}_{\T V\shift{1}} \colon \L\MM \to \ounit_{\cC}[\ZZ].
            \end{equation*}
        \end{definition}

        \begin{lemma}\label{lem:braiding-characters-agree}
            Let $A\in \Ab$ and $\Zchar \in \Map\Enull(A, \Sigma \cC\units)$. Let $V \in \cC\dbl$ and $a\in A$.
            Then $\mscr{X}^{\Zchar}_{\T V\shift{a}}$ is the braiding character of $V\shift{a}$ in the sense of \cref{def:braiding-character-general}.
        \end{lemma}
        \begin{proof}
            It is enough to prove it for the universal case $A = \ZZ$, $a = 1$. Note that the composition $\L\MM \xto{\mscr{X}^{\Zchar}_{\T V\shift{1}}} \ounit_{\cC}[\ZZ] \to \ounit_{\cC}$ is the usual character of $\T V\shift{1}$. Moreover, this map sends each $\L\B\Sm$ exactly to degree $\degree$, so the claim follows from \cref{lem:map-factors-constant} and \cref{cor:braiding-character-factors-constant}.
        \end{proof}        

        \begin{notation}
            When $\Zchar$ is not clear from context, we will denote by $\chi^{\Zchar}_{\T V\shift{1}}$ the usual character of the braiding map, i.e.\ the composition $\L\MM \xto{\mscr{X}^{\Zchar}_{\T V\shift{1}}} \ounit_{\cC}[\ZZ] \to \ounit_{\cC}$.
        \end{notation}

        In the semiadditive case, we can extend this result to any object with finite support which is pointwise dualizable. Such objects are of the form $\bigoplus V_i \shift{a_i}$ for $a_i\in A$ and $V_i \in \cC\dbl$. The elements $a_i$ define a map $\vec{a} \colon \ZZ^r \to A$, sending $e_i$ to $a_i$. This, allows one to define a braiding character 
        \begin{equation*}
            \L\MM \to \ounit_{\cC}[\ZZ^r].
