        \begin{definition}
            Assume that $\cC$ is semiadditive. Let $\Zchar \in \Map\Enull(\ZZ^r, \Sigma \cC\units)$. 
            Let $W \coloneqq \bigoplus_i V_i \shift{e_i} \in \Gr^{\Zchar}_{\ZZ^r} \cC$ where $V_i \in \cC\dbl$. 
            The braiding of $W$ induces the $\cC$-linear left adjoint functor $\T W \colon \cC[\MM] \to \Gr^{\Zchar}_{\ZZ^r} \cC$. Applying $\THH_{\cC}$ we get the map
            \begin{equation*}
                \widetilde{\mscr{X}}^{\Zchar}_{\T W} \colon \L\MM \to \ounit_{\cC}[\ZZ^r].
            \end{equation*}

            We then define
            \begin{equation*}
                \mscr{X}^{\Zchar}_{\T W} \colon \L\MM \xto{\widetilde{\mscr{X}}^{\Zchar}_{\T W}} \ounit_{\cC}[\ZZ^r] \to \ounit_{\cC}[\ZZ].
