                \mscr{X}^{\Zchar}_{\T W} \coloneqq \mscr{X}^{\Zchar \circ \vec{a}}_{\T W'} \colon \L \MM \to \ounit_{\cC}[\ZZ].
            \end{equation*}
        \end{definition}

