    \subsection{Exterior algebras}
    \label{subsec:exterior-algebras}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

        Let $\cC\in \CAlg(\PrL)$ and $\Zchar \colon \ZZ \to \Sigma^2 \ounit_{\cC}\units$ be a map of connective spectra.
        Let $X \in \cC$. The free commutative algebra generated in $\Gr^{\Zchar}_{\ZZ} \cC$ by $X\shift{1}$ is a graded commutative algebra, which we think of as an analog of the exterior algebra. 
        For graded vector spaces, where there exist exactly two symmetric monoidal structures (\cref{rmrk:2-structurs-on-GrVect}), this construction recovers the classical (graded) symmetric and exterior algebras. In $\Mod_{\sVect}$, it naturally endows the exterior powers of super categories, defined in \cite{Ganter-Kapranov-2014-exterior-categories} by Ganter and Kapranov, with an algebra structure.


        \begin{definition}\label{def:exterior}
            Let $X \in \cC$. Define the $\Zchar$-twisted exterior algebra $\extAlg_{\Zchar} X \in \CAlg(\Gr_{\ZZ}^\Zchar \cC)$ of $X$ as the free commutative algebra generated by $X\shift{1}$:
            \begin{equation*}
                \extAlg_{\Zchar} X \coloneqq \mrm{Fr}_{\EE_{\infty}}(X\shift{1}) = \Sym[\bullet](X\shift{1}).
            \end{equation*}
        \end{definition}

        \begin{example}
            Assume $\Zchar \colon \ZZ \to \Sigma \cC\units$ is the trivial map. Then $\Gr^{\Zchar}_{\ZZ} \cC \simeq \Gr_{\ZZ} \cC$ and $\extAlg_{\Zchar} X \simeq \Sym[\bullet] X$ is the usual graded symmetric algebra.
        \end{example}

        \begin{example}\label{exm:exteior-Koszul}
            Assume $\cC = \Vect$. Let $(-1) \colon \ZZ/2 \to \field\units$ be the usual minus one map. Then $\Gr^{\Kos}_{\ZZ} \Vect$ is identified with the usual category of graded vector spaces with the Koszul sign (\cref{def:Koszul}) and $\extAlg_{\Kos} X$ is the usual graded exterior algebra of vector spaces.
        \end{example}

        \begin{example}
            For $\cC = \Mod_{\sVect}$, let $\widehat{\eta^2} \in \pinD[2]$ be the unique non-trivial element. Then, working in $\Gr^{\hat{\eta^2}}_{\ZZ} \cC$ as in \cref{def:dual-stable-stems}, $\alt_{\widehat{\eta^2}}$ is identified with the exterior power of super linear categories which is the main object of study of \cite{Ganter-Kapranov-2014-exterior-categories}. In particular, $\extAlg_{\widehat{\eta^2}}$ gives a natural graded symmetric monoidal structure on the collection of exterior power of super linear categories.
        \end{example}    

        \begin{corollary}
            For any $X \in \cC$, $\bigsqcup_{\degree} \alt_{\Zchar} X$ is naturally an associative algebra in $\cC$.
        \end{corollary}
        \begin{proof}
            As a monoidal category $\Gr^{\Zchar}_{\ZZ} \cC \simeq \Gr_{\ZZ} \cC$. The colimit functor, which in this case is the coproduct $\bigsqcup \colon \Gr_{\ZZ} \cC \to \cC$, is monoidal, therefore sends algebras to algebras. In particular $\extAlg_{\Zchar} X \in \Alg(\Gr_{\ZZ} \cC)$ is sent to $\bigsqcup_{\degree} \alt_{\Zchar} X \in \Alg(\cC)$.
        \end{proof}

        \begin{remark}\label{rmrk:exterior-as-alternating}
           The construction of the classical symmetric and alternating powers is through the fact that $\Sm$ admits exactly two characters --- the trivial and the sign. Given a character $\hchar \colon \Sm \to \field\units$ and $V \in \Vect$ we define
           \begin{equation*}
               \alt_{\hchar} V \coloneqq (V\om \otimes \field[\hchar])_{h\Sm}
           \end{equation*}
           where $\field[\hchar]$ is the one-dimensional representation corresponding to $\hchar$. Indeed for $\hchar = \triv$ we get the symmetric powers and for $\hchar = \sgn$ we get the exterior powers.

           For a general category $\cC$ there might be many more characters $\hchar \colon \Sm \to \ounit_{\cC}\units$. The braiding $\hchar_{\Zchar} \colon \MM \to \B\ounit_{\cC}\units$ of $\Zchar \colon \ZZ \to \Sigma^2\ounit_{\cC}\units$, defines a character $\hchar_{\Zchar}^{\degree}$ of $\B\Sm$ for each $\degree$. Moreover, for any $X\in \cC$, $\extAlg_{\Zchar} X$ at degree $\degree$ is identified with
           \begin{equation*}
               \alt_{\Zchar} X \simeq (X\om \otimes \ounit_{\cC}[\hchar_{\Zchar}^{\degree}])_{h\Sm}.
           \end{equation*}
           This is another justification for the name \quotes{exterior algebra}. 

           Note that not all characters arise in this manner, and further investigation of exterior powers associated with all characters is postponed to a separate study (\cite{Keidar-Ragimov-??-alternating}).
        \end{remark}


