        \subsubsection*{Bialgebra structure}


        The classical exterior algebra is a Hopf algebra, taking advantage of the fact that $\extAlg (V \oplus W) \simeq \extAlg V \otimes \extAlg W$. We now extend this phenomenon to our settings. The existence of the antipode map is due to the fact that any vector space is grouplike. Therefore we manage to extend the construction to that of a bialgebra, which becomes Hopf for grouplike objects. We expect that for virtually $(\Fp, \chrHeight)$-orientable categories (see \cite{BCSY-Fourier}) there should be more structure on these rings, resembling a higher version of an antipode, yet we did not study it in this paper.

        \begin{definition}
            Let $\cC$ be a category. Define the category of co-groups in $\cC$ as
            \begin{equation*}
                \coGrp(\cC) \coloneqq \coCMon\gp(\cC) = (\CMon\gp(\cC\op))\op = \Grp(\cC\op)\op.
            \end{equation*}
        \end{definition}

        \begin{remark}
            When $\cC$ is semiadditive, $\coCMon(\cC) = \cC$ and being co-grouplike is a property of objects of $\cC$.
            Moreover in this case, for any object $X$, the shearing map of $X$ as a monoid is an isomorphism if and only if the shearing map of $X$ as a comonoid is an isomorphism. Thus being co-grouplike is the same as being grouplike.
        \end{remark}


        \begin{lemma}
            Assume that $\cC$ is semiadditive. Let $X\in \cC$. Then $\extAlg_{\Zchar} X$ has a natural structure of a bialgebra. If moreover $X$ is grouplike then $\extAlg_{\Zchar} X$ has a structure of a Hopf algebra.
        \end{lemma}

        \begin{proof}
            The functor 
            \begin{equation*}
                \extAlg_{\Zchar}\colon \cC \xto{(-)\shift{1}} \Gr^{\Zchar}_{\ZZ} \cC \xto{\mrm{Fr}_{\EE_{\infty}}} \CAlg(\Gr^{\Zchar}_{\ZZ} \cC)
            \end{equation*}
            is left adjoint to the evaluation at $1$ functor $\CAlg(\Gr^{\Zchar}_{\ZZ} \cC) \to \cC$. Therefore it commutes with colimits, and in particular sends finite direct sums to tensor products. In particular it gives rise to a functor
            \begin{equation*}
                \extAlg_{\Zchar}\colon \cC \simeq \coCMon(\cC) \to \coCMon(\CAlg(\Gr_{\ZZ} \cC)) \simeq \BiCAlg(\Gr_{\ZZ} \cC)).
            \end{equation*}

            Restricting to grouplike, or equivalently, co-grouplike objects we get
            \begin{equation*}
                \extAlg_{\Zchar}\colon \coGrp(\cC) \simeq \coCMon\gp(\cC) \to \coCMon\gp(\CAlg(\Gr_{\ZZ} \cC)) = \Hopf(\Gr_{\ZZ} \cC).
            \end{equation*}
        \end{proof}

        \begin{corollary}
            Assume $\cC$ is additive. Then the exterior algebra functor extends to
            \begin{equation*}
                \extAlg_{\Zchar}\colon \cC \to \Hopf(\Gr_{\ZZ} \cC).
            \end{equation*}
        \end{corollary}

        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        \subsubsection*{Dimensions comparison}

        One can extend the construction of the exterior algebra to a lax symmetric monoidal functor $\NN \to \Gr^{\Zchar}_{\ZZ} \cC$, thinking of it as a graded algebra in $\Gr^{\Zchar}_{\ZZ} \cC$.

        \begin{definition}\label{def:exterior-functor}
            Let $\cD$ be a presentably symmetric monoidal category. Define the functor
            \begin{equation*}
                \extAlg \colon \cD \xto{\T} \cD[\MM] \xto{\deg_!} \cD[\NN].
            \end{equation*}
            As $\deg_!$ is symmetric monoidal and $\T$ factors through $\CAlg(\cD[\MM])$, the functor $\extAlg$ lands in lax symmetric monoidal functors $\NN \to \cD$.
        \end{definition}
        By \cref{rmrk:exterior-as-alternating}, when $\cD = \Gr^{\Zchar}_{\ZZ}\cC$, for $X \in \cC$, $\alt_{\Zchar} X$ as in \cref{def:exterior}, agrees with $\alt X\shift{1}$ as in \cref{def:exterior-functor}. This also allows us to define an analog of the exterior algebra for objects not concentrated only in degree 1 (which is just the free commutative algebra generated by this object).

        \begin{corollary}\label{cor:exterior-takes-sums-to-products}
            Let $\cD$ be a presentably symmetric monoidal category. Then for any $X,Y \in \cD$
            \begin{equation*}
                \extAlg (X \sqcup Y) \simeq \extAlg X \otimes_{\Day} \extAlg Y.
            \end{equation*}
        \end{corollary}
        \begin{proof}
            Since $\deg_!$ is symmetric monoidal, this follows from \cref{cor:braiding-sends-coproducts-to-tensors}.
        \end{proof}

        Written concretely, we get the known formula
        \begin{equation*}
            \alt(X \sqcup Y) \simeq \bigsqcup_{i+j = \degree} \alt[i] X \otimes \alt[j] Y.
        \end{equation*}

        Now, similarly to the braiding character, we can consider the image of this map under $\THH_{\cD}$, getting a generating function for the dimensions:
        \begin{lemma}\label{lem:extAlg-is-dbl}
             Assume $\cD$ is 1-semiadditive. Then for any $V \in \cD\dbl$, $\extAlg_{\Zchar} V$ is point-wise dualizable.
        \end{lemma}
        \begin{proof}
            The object $\extAlg V$ at degree $\degree$ is given by $(V\om)_{h\Sm}$ which is dualizable as $V\om$ is dualizable and $\B\Sm$ is 1-finite. 
        \end{proof}
        \begin{definition}
            Assume that $\cD$ is 1-semiadditive. Let $V \in \cD\dbl$. Let
            \begin{equation*}
            \extAlg V\shift{1} \coloneqq \deg_! \T V\shift{1} \colon \NN \to \Gr_{\ZZ} \cD.
            \end{equation*}
            Notice again that its image under the symmetric monoidal functor $\colim \colon \Gr_{\ZZ} \cD \to \cD$ is $\extAlg V$. Then define
            \begin{equation*}
                \dim \extAlg V \colon \ounit_{\cD}[\NN] \to \ounit_{\cD}[\ZZ] \qin \CAlg(\cD).
            \end{equation*}
            as its image under $\THH_{\cD}$ of $\extAlg V\shift{1}$.
        \end{definition}

        \begin{remark}
            Writing $\ounit_{\cD}[\ZZ] = \ounit_{\cD}[t^{\pm 1}]$, the evaluation of this map at $\degree \in \NN$ is $\dim \alt_{\Zchar} V\, t^{\degree}$. We sometimes abuse notations, and write
            \begin{equation*}
                \dim \extAlg V = \sum_{\degree} \dim \alt V\, t^{\degree},
            \end{equation*}
            as the generating function of all the dimensions.
        \end{remark}

        \begin{corollary}\label{cor:dimensions-take-sums-to-products}
            Assume $\cD$ is 1-semiadditive. Let $V, W \in \cD\dbl$. Then, as generating functions
            \begin{equation*}
                \dim \extAlg (V \oplus W) = (\dim \extAlg V) (\dim \extAlg W).
            \end{equation*}
        \end{corollary}
        \begin{proof}
            Concretely, we need to prove that
            \begin{equation*}
                \sum_{\degree} \dim \alt (V\oplus W)\, t^{\degree} = (\sum_{\degree} \dim \alt V\, t^{\degree})(\sum_{\degree} \dim \alt W\, t^{\degree}).
            \end{equation*}
            Equivalently, that
            \begin{equation*}
                \dim \alt (V\oplus W) = \sum_{i+j = \degree} (\dim \alt[i] V)(\dim\alt[j] W).
            \end{equation*}
            This follows by \cref{cor:exterior-takes-sums-to-products}. 
        \end{proof}

        \begin{remark}
            If $\cD\in \CAlg(\PrL)$ is $1$-semiadditive, then $\deg \colon \MM \to \NN$ is $\cD$-adjointable\footnote{sometimes also called $\cD$-semi-affine}, i.e.\ $\deg^* \colon \cD^{\NN} \to \cD^{\MM}$ is internal left adjoint in $\Mod_{\cD}$. This follows from \cite[Proposition~2.32]{BCSY-Fourier} since the fiber of $\deg$ at each point is 1-finite.
        \end{remark}

        \begin{lemma}\label{lem:induced-character-formula-for-dimensions}
            Assume that $\cD$ is 1-semiadditive. Then $\dim \extAlg V$ is isomorphic to the composition
            \begin{equation*}
                \ounit_{\cD}[\NN] \xto{\THH_{\cD}(\deg^*)} \ounit_{\cD}[\L\MM] \xto{\mscr{X}_{\T V}} \ounit_{\cD}[\ZZ].
            \end{equation*}
        \end{lemma}
        \begin{proof}
            This is essentially the induced character formula \cite[Theorem 5.20]{Carmeli-Cnossen-Ramzi-Yanovski-2022-characters}. The functor $\extAlg V\shift{1} = \deg_! \T V\shift{1}$ decomposes as
            \begin{equation*}
                \cD[\NN] \xto{\deg^*} \cD[\MM] \xto{\T V\shift{1}} \Gr_{\ZZ} \cD.
            \end{equation*}
            The result now follows by taking $\THH_{\cD}$.
        \end{proof} 

        \begin{corollary}\label{cor:dim-depends-only-on-dim}
            Assume that $\cD$ is 1-semiadditive. Then $\dim \extAlg V$ depends only on $\dim(V) \in (\ounit_{\cD})^{\B\vee_k \Ck}$.
        \end{corollary}
        \begin{proof}
            This follows from \cref{lem:induced-character-formula-for-dimensions,thm:braiding-depends-only-on-dim}.
        \end{proof}


        \begin{corollary}\label{cor:dim-exterior-internal}
            Assume $\cC$ is 1-semiadditive. Let $A \in \Ab$ and $\Zchar \in \Map\Enull(A, \Sigma\cC\units)$. Let $V \in \cC\dbl$ and $a\in A$. Then $\dim \extAlg V\shift{a}$ identifies with
            \begin{equation*}
                \dim \extAlg_{\Zchar} V\shift{a} \coloneqq \THH_{\cC}(\extAlg_{\Zchar \circ a}V\shift{1}) \colon \ounit_{\cC}[\NN] \to \ounit_{\cC}[\ZZ].
            \end{equation*}
        \end{corollary}
        \begin{proof}
            This follows by \cref{lem:induced-character-formula-for-dimensions,lem:braiding-characters-agree}.
        \end{proof}
        Similarly:
        \begin{corollary}\label{cor:dim-exterior-internal-multiple}
            Assume $\cC$ is 1-semiadditive. Let $A \in \Ab$ and $\Zchar \in \Map\Enull(A, \Sigma \cC\units)$. Let $V_1,\dots,V_r \in \cC\dbl$ and $a_1,\dots, a_r \in A$. Then $\dim \extAlg (\bigoplus_i V_i\shift{a_i})$ identifies with
            \begin{equation*}
                \ounit_{\cC}[\NN] \xto{\THH_{\cC}[\otimes V_i\shift{e_i}]} \ounit_{\cC}[\ZZ^r] \to \ounit_{\cC}[\ZZ].
            \end{equation*}
        \end{corollary}
        \begin{proof}
            This follows by \cref{lem:induced-character-formula-for-dimensions,lem:braiding-characters-agree-multiple}.
        \end{proof}

        \begin{notation}
            When $\Zchar \colon \ZZ \to \Sigma^2 \ounit_{\cC}\units$ is not clear from context we denote the dimension in $\Gr^{\Zchar}_{\ZZ} \cC$ by $\dim_{\Zchar}$.
        \end{notation}

        \begin{corollary}\label{cor:generating-functions-dimensions}
            Let $\Zchar_1,\dots, \Zchar_r \colon \ZZ \to \Sigma^2 \ounit_{\cC}\units$. Then the generating function
            \begin{equation*}
                (\dim \extAlg_{\Zchar_1} V) \cdots (\dim \extAlg_{\Zchar_r} V)
            \end{equation*}
            depends only on $\sum_i \dim_{\Zchar_i} (V\shift{1}) \in (\ounit_{\cC})^{\vee_k\B\Ck}$.
        \end{corollary}

        \begin{proof}
            Define $\Zchar \colon \ZZ^r \to \Sigma^2 \ounit_{\cC}\units$ as the product of $\Zchar_i$. Then the commutative diagram
            \begin{equation*}
                \begin{tikzcd}
                    \ZZ & {\ZZ^r} \\
                    & {\Sigma\cC\units}
                    \arrow["{j_i}", hook, from=1-1, to=1-2]
                    \arrow["{\Zchar_i}"', from=1-1, to=2-2]
                    \arrow["\Zchar", from=1-2, to=2-2]
                \end{tikzcd}
            \end{equation*} 
            induces a symmetric monoidal functor $(j_i)_! \colon \Gr^{\Zchar_i}_{\ZZ} \cC \to \Gr^{\Zchar}_{\ZZ^r} \cC$, sending $V\shift{1}$ to $V\shift{e_i}$. By the formulas in \cref{cor:dim-exterior-internal,cor:dim-exterior-internal-multiple}
            \begin{equation*}
                \dim \extAlg V\shift{e_i} = \dim \extAlg_{\Zchar_i} V.
            \end{equation*}
            Now, by \cref{cor:dimensions-take-sums-to-products},
            \begin{equation*}
                \dim \extAlg(\bigoplus V_i\shift{e_i}) = \bigsqcap_i \dim \extAlg V_i \shift{e_i} = \bigsqcap_i \dim \extAlg_{\Zchar_i} V.
            \end{equation*}
            By \cref{cor:dim-depends-only-on-dim}, $\dim \extAlg(\bigoplus V_i\shift{e_i})$ depends only on 
            \begin{equation*}
                \dim(\bigoplus V_i\shift{e_i}) = \sum_i \dim (V_i\shift{e_i}) \in (\ounit_{\cC})^{\vee_k \B\Ck}.
            \end{equation*}
            Again using the symmetric monoidal functor $(j_i)_! \colon \Gr^{\Zchar_i}_{\ZZ} \cC \to \Gr^{\Zchar}_{\ZZ^r} \cC$, we get that $\dim(V\shift{e_i}) = \dim_{\Zchar_i}(V\shift{1})$ as needed.
        \end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
 \section{Graded categories and orientation}
 \label{sec:Galois-closed-unit}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

    Throughout this section we fix a presentably symmetric monoidal, $\infty$-semiadditive, $(\SS, \chrHeight)$-oriented category $\cC$ (see \cref{Galois-closed}). As before, when working $p$-typically we assume that it is $(\SS_{(p)},\chrHeight)$-orientated and will write $\In$ for $\Inprime$ and $\pinD$ for $\widehat{\pi}_{\chrHeight+1}(\SS_{(p)})$ trusting the reader to infer the relevant $p$ from the context. 

    We start in \cref{subsec:graded-categories-and-orientability} by showing that there exists a universal $\cC[\omega^{(0)}_{\SS}]$ Galois extension of $\cC$, such that $\Mod_{\cC[\omega^{(0)}_{\SS}]}$ is $(\SS,\chrHeight+1)$-oriented. It is constructed as a twisted graded category. In particular, $\Mod_{\cC}$ is $(\SS,\chrHeight+1)$-oriented if and only if it is the trivial Galois extension, or equivalently, its braiding is trivial.

    This motivates us to investigate the braiding of $\cC[\omega^{(0)}_{\SS}]$, which can be analyzed independently for each $\pichar \in \pinD$. In line with the theme of this paper, we do so by examining the associated braiding characters.

    In \cref{subsec:low-heights} we show that, at height $\le 4$, the reduced $\Ck$-action on the monoidal dimension of  $\ounit_{\cC}\shift{1} \in \Gr^{\pichar}_{\ZZ} \cC$ is trivial for any $k$. We use this and the results of \cref{sec:graded-braiding} to get generating functions for the dimensions of exterior algebras under additive assumptions, and to completely compute the braiding characters in the categorical case.

    In \cref{subsec:chromatic-braiding-character} we study the case $\cC = \ModEn$ for any height, and demonstrate that the  reduced $\Cn[p^k]$-action on the dimension of any object in $\Gr^{\pichar}_\ZZ (\ModEn)\dbl$ is trivial. As a result, we compute the braiding characters for all $\pichar$ at any height, and all primes.
    This provides some support for the orientability conjecture of $\Mod_{\ModEn}$ \cite[Conjecture~7.10]{BCSY-Fourier}, which, in our language, predicts that $\Gr^{\pichar}_\ZZ \ModEn \simeq \Gr_\ZZ \ModEn$ for any $\pichar \in \pinD$.

    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \subsection{The orientable extension}
    \label{subsec:graded-categories-and-orientability}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

        In this subsection we construct a cyclotomically-closed Galois extension of $\cC$ as a graded category. 
        Recall that since $\cC$ in $(\SS,\chrHeight)$-oriented we have a map $\In \to \cC\units$ which we think of as the embedding of spherical roots of unity.

        \begin{definition}\label{def:zeta}
            Rolling the cofiber sequence 
            \begin{equation*}
                \Sigma \In \to \Inplus\to \pinD,
            \end{equation*}
            we get a map 
            \begin{equation*}
                \zeta = \zeta_{\chrHeight} \colon \pinD \to \Sigma^2 \In \to \Sigma^2\ounit_\cC\units \to \Sigma\cC\units.
            \end{equation*}

            We define $\cC[\omega^{(0)}_{\SS}] \coloneq \Gr^{\zeta}_{\pinD} \!\! (\cC)$\footnote{Or $\cC[\omega^{(0)}_{\SS_{(p)}}] \coloneqq \Gr^{\zeta}_{\pinD} \!\! (\cC)$ when working $p$-typically.}.
        \end{definition}

        Let $\pin \coloneqq \pi_{\chrHeight+1}(\SS)$ be the $(\chrHeight+1)$-st stable stem. 
        We will show that $\cC[\omega^{(0)}_{\SS}]$ is a $\B^{\chrHeight+1}\pin$-Galois extension, that $\Mod_{\cC[\omega^{(0)}_{\SS}]}$ it is $(\SS,\chrHeight+1)$-oriented, and that it is the universal such extension in an appropriate sense. See \cref{subsec:intro-galois-closed} for further justification of this notation.

        We first show it admits a natural $\B^{\chrHeight+1}\pin$-action.
        The map $\zeta \colon \pinD \to \Mod_{\cC}\units$ has a mate, which we also denote 
        \begin{equation*}
            \zeta \colon \Mod_{\cC}[\pinD] \to \Mod_{\cC}.
        \end{equation*}

        \begin{lemma}\label{lem:image-under-Fourier-and-zeta}
            The commutative algebra $\cC^{\B^{\chrHeight+1}\pin} \in \CAlg(\Mod_{\cC}^{\B^{\chrHeight+2}\pin})$ is sent to $\cC[\omega^{(0)}_{\SS}]$ under the composition of symmetric monoidal functors
            \begin{equation*}
                \Mod_{\cC}^{\B^{\chrHeight+2}\pin} \xgets[{\,\smash{\raisebox{0.9ex}{\ensuremath{\scriptstyle\sim}}}\,}]{\mscr{F}} \Mod_{\cC}[\pinD] \xto{\zeta} \Mod_{\cC},
            \end{equation*}
            where $\mscr{F}$ is the semiadditive Fourier transform (using that $\Mod_{\Mod_{\cC}}$ is $(\ZZ, \chrHeight+2)$-oriented).
        \end{lemma}

        \begin{proof}
            The map of connective spectra $\pinD \colon \pinD \to 0$, is sent under the height $(\chrHeight+2)$-Pontryagin duality (i.e.\ $\tau_{\ge 0}\hom(-,\In[\chrHeight+2])$) to the map $0 \to \B^{\chrHeight+2}\pin$. By the functoriality of the Fourier transform, we have a commutative diagram of symmetric monoidal functors
            \begin{equation*}
                \begin{tikzcd}
                    {\Mod_{\cC}[\pinD]} & {\Mod_{\cC}^{\B^{\chrHeight+2}\pin}} \\ \\
                    {\Mod_{\cC}} & {\Mod_{\cC},}
                    \arrow["{\mscr{F}}", "\sim"', from=1-1, to=1-2]
                    \arrow["{(\pinD)_!}", from=1-1, to=3-1]
                    \arrow["{0^*}", from=1-2, to=3-2]
                    \arrow["{\mscr{F}}", equals, from=3-1, to=3-2]
                \end{tikzcd}
            \end{equation*}
            and $(\pinD)_!$ is the colimit functor and $0^*$ is the functor forgetting the $\B^{\chrHeight+1}\pin$-action.
            Taking right adjoints, we see that $\mscr{F}^{-1}(0_* \cC) = \mscr{F}^{-1}(\cC^{\B^{\chrHeight+1}\pin})$ is isomorphic to $(\pinD)^* \cC$ which is the constant symmetric monoidal functor $\pinD \to \Mod_{\cC}$ with value $\cC$.

            The claim now follows by composing with $\zeta$.
        \end{proof}

        \begin{corollary}
            $\cC[\omega^{(0)}_{\SS}]$ admits a natural $\B^{\chrHeight+1}\pin$-action.
        \end{corollary}
        \begin{proof}
            The symmetric monoidal category $\cC^{\B^{\chrHeight+1}\pin}$ admits a $(\B^{\chrHeight+1}\pin \times \B^{\chrHeight+1}\pin)$-action. Therefore the symmetric monoidal functor of \cref{lem:image-under-Fourier-and-zeta}, which extends to
            \begin{equation*}
                \CAlg(\Mod_{\cC}^{\B^{\chrHeight+2}\pin})^{\B^{\chrHeight+2}\pin} \to \CAlg_{\cC}(\PrL)^{\B^{\chrHeight+2}\pin},
            \end{equation*}
            sends $\cC^{\B^{\chrHeight+1}\pin}$ to $\cC[\omega^{(0)}_{\SS}]$ equipped with a $\B^{\chrHeight+1}\pin$-action.
        \end{proof}

        \begin{proposition}\label{prop:cyc-is-Galois}
            $\cC[\omega^{(0)}_{\SS}]$ is a $\B^{\chrHeight+1}\pin$-Galois extension of $\cC$.
        \end{proposition}

        \begin{proof}
            By construction and \cite[3.12]{BMCSY-cycloshift}, it suffices to show that $\cC^{\B^{\chrHeight+1}\pin}\in \Mod_\cC^{\B^{\chrHeight+2}\pin}$ is a $\B^{\chrHeight+1}\pin$-Galois extension which is immediate as $\B^{\chrHeight+1}\pin$ is dualizable in $\Mod_\cC$. 
        \end{proof}

        \begin{remark}
            Note that by \cite[Theorem 5.15]{BCSY-Fourier} we have that $\Mod_\cC$ is $(\SS,\chrHeight+1)$-oriented if and only if there exists a lifting
            \begin{equation*}
                \begin{tikzcd}
                   {\Sigma \In } & {\Sigma \ounit_\cC\units} & {\cC\units} \\
                   {\Inplus}
                   \arrow[from=1-1, to=1-2]
                   \arrow[from=1-1, to=2-1]
                   \arrow[from=1-2, to=1-3]
                   \arrow[dashed, from=2-1, to=1-3]
                \end{tikzcd}
            \end{equation*}
            where the map $\In  \to \ounit_{\cC}\units$ is the orientation and $\Sigma \In \to \Inplus$ is the connected cover map.   
        \end{remark}


        \begin{lemma}\label{lem:cyc_is_cyc_closed}
            The category $\Mod_{\cC[\omega^{(0)}_{\SS}]}$ is $(\SS,\chrHeight+1)$-oriented.
        \end{lemma}

        \begin{proof}
            Recall from \cref{prop:picard-of-Day} and from the proof of \cref{thm:twFun-are-all-lifts} that there exists a cofiber sequence
            \begin{equation*}
                \cC\units \to (\cC[\omega^{(0)}_{\SS}])\units \to \pinD,
            \end{equation*}
            and the induced map $\pinD \to \Sigma \cC\units$ is $\zeta$.
            Consider the following commutative square
            \begin{equation*}
                \begin{tikzcd}
                    \pinD & {\Sigma^2 \In} \\
                    \pinD & {\Sigma \cC\units.}
                    \arrow["{\zeta}", from=1-1, to=1-2]
                    \arrow[equals, from=1-1, to=2-1]
                    \arrow[from=1-2, to=2-2]
                    \arrow["{\zeta}", from=2-1, to=2-2]
                \end{tikzcd}
            \end{equation*}
            Taking fibers, we get a map
            \begin{equation*}
                i_{\chrHeight+1} \colon \Inplus \to (\cC[\omega^{(0)}_{\SS}])\units.
            \end{equation*}
            and by construction we have that.
            \begin{equation*}
                \Omega i_{\chrHeight+1} \colon \In \simeq \Omega \Inplus \to \Omega (\cC[\omega^{(0)}_{\SS}])\units \simeq \ounit_{\cC}\units
            \end{equation*}
            is identified with the canonical map $(\ounit_{\cC}\units)\pitor \to \ounit_{\cC}\units$, as required.
        \end{proof}


        The following proposition allows us to view $\cC[\omega^{(0)}_\infty]$ as the universal $(\SS,\chrHeight+1)$-oriented extension of $\cC$:

        \begin{proposition}\label{prop:C-cyclotoimcally-closed-iff-gradedpi-is-trivial}
               The following are equivalent:
               \begin{enumerate}
                   \item\label{item:cyc-closed} The category $\Mod_\cC$ is $(\SS,\chrHeight+1)$-orientable.
                   \item\label{item:trivial-Galois} $\cC[\omega^{(0)}_{\SS}]$ is a trivial Galois extension, i.e.\ $\cC[\omega^{(0)}_{\SS}] \simeq \cC^{\B^{\chrHeight+1} \pin}$.
                   \item\label{item:trivial-braiding} $\cC[\omega^{(0)}_{\SS}] \simeq \Gr_{\pinD} (\cC)$, i.e.\ the braiding of $\cC[\omega^{(0)}_{\SS}]$ is trivial.
               \end{enumerate}
        \end{proposition}


        \begin{proof}
            The equivalence of (\labelcref{item:trivial-Galois}) and (\labelcref{item:trivial-braiding}) follows by the semiaddtive Fourier transform.

            We show now that (\labelcref{item:cyc-closed}) is equivalent to (\labelcref{item:trivial-braiding}).  
            By the universal property of the Thom construction, $\cC[\omega^{(0)}_{\SS}] = \Gr^{\zeta}_{\pinD}\!\!(\cC)$ is isomorphic to $\Gr_{\pinD} (\cC)$ if and only if the map $\zeta \colon \pinD \to \Sigma \cC\units$ is null as an $\EE_{\infty}$-map. 
            Using the cofiber sequence 
            \begin{equation*}
                \pinD \to \Sigma^2 \In \to \Sigma \Inplus,
            \end{equation*}
            $\zeta$ is null if and only if there exists a lift
            \begin{equation*}
                \begin{tikzcd}
                    \pinD \\
                    {\Sigma^2 \In} & {\Sigma\cC\units.} \\
                    {\Sigma \Inplus}
                    \arrow[from=1-1, to=2-1]
                    \arrow[from=1-1, to=2-2]
                    \arrow[from=2-1, to=2-2]
                    \arrow[from=2-1, to=3-1]
                    \arrow[dashed, from=3-1, to=2-2]
                \end{tikzcd}
            \end{equation*}
        \end{proof}

       \begin{remark}
           One can use \cref{prop:C-cyclotoimcally-closed-iff-gradedpi-is-trivial} in order to construct the cyclotomic closure of $\cC$ as in \cref{def:cyc-closure}. More generally by adding homotopy groups of $\Inplus$ inductively one can construct the the cyclotomic closure of $\cC$ for any $\infty$-semi-additive category which is virtually $(\Fp,\chrHeight)$-orientable.
       \end{remark}


    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \subsection{Braiding characters of oriented categories in low heights}
    \label{subsec:low-heights}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

        Thinking of $\SS$ as a symmetric monoidal category, the element $1 \in \SS$ is invertible. Therefore it has a dimension
        \begin{equation*}
            \dim(1) \in \End_{\SS}(1)^{\B\TT} = (\Omega \SS)^{\B\TT}.
        \end{equation*}
        By \cite[Proposition~3.20]{CSY-cyclotomic}, $\dim(1)$ is identified with $\eta$ in $\Omega \SS$. 
        \begin{definition}
            We denote by $\eta \in (\Omega\SS)^{\B\TT}$ the dimension of $1\in \SS$ with the corresponding $\TT$-action.
        \end{definition}

        Let $\cC \in \CAlg(\PrL)$ and $\Zchar \colon \ZZ \to \Sigma \cC\units$. By \cref{lem:cofiber-of-pic-Day} and the proof of \cref{thm:twFun-are-all-lifts}, the fiber of this map is $(\Gr^{\Zchar}_{\ZZ}\cC)\units$.
        As $(\Gr^{\Zchar}_{\ZZ}\cC)\units$ is a spectrum, the dimension of $\ounit_{\cC}\shift{1}$ is given by the action of $\eta \in (\Omega \SS)^{\B\TT}$
        \begin{equation*}
            \dim(\ounit_{\cC}\shift{1}) = \eta \cdot \ounit_{\cC}\shift{1} \qin \End_{(\Gr^{\Zchar}_{\ZZ}\cC)\units}(\ounit_{\cC}\shift{1})^{\B\TT} = (\Omega(\Gr^{\Zchar}_{\ZZ}\cC)\units)^{\B\TT} \simeq (\ounit_{\cC}\units)^{\B\TT}.
        \end{equation*}

        \begin{notation}
            Let $\pichar \in \pinD$. Then $\pichar \in \Inplus$ is invertible. Denote its dimension by
            \begin{equation*}
                \eta_{\pichar} \coloneqq \dim(\pichar) \qin \End_{\Inplus}(1)^{\B\TT} = (\Omega \Inplus)^{\B\TT} \simeq (\In)^{\B\TT}.
            \end{equation*}
            Equivalently it is $\eta \cdot \pichar$, for $\eta \in (\Omega \SS)^{\B\TT}$ and $\pichar \in \Inplus$.
        \end{notation}

        \begin{lemma}
            Let $\pichar \in \pinD$ and $\cC \in \CAlg(\PrL)$ be $\infty$-semiadditive, $(\SS,\chrHeight)$-orientable. Then, under the inclusion map $\In \to \ounit_{\cC}\units$, the dimension of $\ounit_{\cC}\shift{1} \in \Gr^{\pichar}_{\ZZ} \cC$ is
            \begin{equation*}
                \dim(\ounit_{\cC}\shift{1}) = \eta_{\pichar} \qin (\ounit_{\cC}\units)^{\B\TT}.
            \end{equation*}
        \end{lemma}
        \begin{proof}
            Let $\Inpi \in \cnSp$ be the pullback
            \begin{equation*}
                \begin{tikzcd}
                    \Inpi & \Inplus \\
                    \ZZ & \pinD.
                    \arrow[from=1-1, to=1-2]
                    \arrow[from=1-1, to=2-1]
                    \arrow["\lrcorner"{anchor=center, pos=0.125}, draw=none, from=1-1, to=2-2]
                    \arrow[from=1-2, to=2-2]
                    \arrow["\pichar", from=2-1, to=2-2]
                \end{tikzcd}
            \end{equation*}
            Equivalently, it is the fiber of the map
            \begin{equation*}
                \ZZ \xto{\pichar} \pinD \to \Sigma^2 \In.
            \end{equation*}
            The map of connective spectra $\Inpi \to \Inplus$ sends $1$ to $\pichar$. Taking fibers of the commutative diagram
            \begin{equation*}
                \begin{tikzcd}
                    \ZZ & {\Sigma^2 \In} \\
                    \ZZ & {\Sigma \cC\units,}
                    \arrow["{\Zchar_{\pichar}}", from=1-1, to=1-2]
                    \arrow[equals, from=1-1, to=2-1]
                    \arrow[hook, from=1-2, to=2-2]
                    \arrow["{\Zchar_{\pichar}}", from=2-1, to=2-2]
                \end{tikzcd}
            \end{equation*}
            we get a symmetric monoidal map $\Inpi \to \Gr^{\pichar}_{\ZZ}\cC$ sending $1\in \Inpi$ to $\ounit_{\cC}\shift{1}$. Therefore, both the dimension of $\pichar \in \Inplus$ and the dimension of $\ounit_{\cC}\shift{1}\in \Gr^{\pichar}_{\ZZ} \cC$, agree with the dimension of $1 \in \Inpi$.
        \end{proof}

        \begin{corollary}\label{cor:dim-of-shift-in-cyc-closed}
            Let $\pichar \in \pinD$ and $\cC \in \CAlg(\PrL)$ be $\infty$-semiadditive, $(\SS,\chrHeight)$-orientable. Then, working in $\Gr^{\pichar}_{\ZZ} \cC$, for any $V \in \cC\dbl$
            \begin{equation*}
                \dim(V\shift{1}) \simeq \eta_{\pichar} \cdot \dim(V) \qin \End(\ounit_{\cC})^{\B\TT}.
            \end{equation*}
        \end{corollary}

        Moreover, using \cref{prop:dim-is-transfer}, we can understand the $\TT$-action on $\eta_{\pichar} \in \In$ --- it is just (the loops of) the composition
        \begin{equation*}
            \Sigma \SS[\B\TT] \xto{\Tr} \SS \xto{\pichar} \Inplus.
        \end{equation*}

        In low heights, everything is much simpler: Choose $\pichar \in \pinD$ and consider $\Gr^{\pichar}_{\ZZ} \cC$ as in \cref{def:dual-stable-stems}.
        \begin{lemma}\label{lem:trivial-T-action-0-1}
            Assume $\chrHeight \le 1$. Let $V \in \cC\dbl$ and assume that the $\TT$-action on $\dim(V)$ is trivial. Then the $\TT$-action on $\dim(V\shift{1})$ is trivial.     
        \end{lemma}
        \begin{proof}
            It suffices to show that the $\TT$-action on $\eta_{\pichar} \in \In$ is trivial. This follows as there are no non-trivial maps $\B\TT \to \In$ for $\chrHeight \le 1$. 
        \end{proof}

        \begin{lemma}\label{lem:trivial-T-action-2}
            Assume $\chrHeight = 2$. Let $V \in \cC\dbl$ and assume that the $\TT$-action on $\dim(V)$ is trivial. Then the restricted $\Ck$-action on $\dim(V\shift{1})$ is trivial for any $k$.
        \end{lemma}
        \begin{proof}
            It suffices to show that the $\Ck$-action on $\eta_{\pichar} \in \In[2]$ is trivial. 
            As $\B\TT$ is simply connected, the map $\B\TT \to \In[2]$ factors through $\tau_{\ge 2} \In[2] = \B^2 \QQ/\ZZ$. Therefore the $\Ck$-action maps factors as maps
            \begin{equation*}
                \B\Ck \to \B^2 \QQ/\ZZ,
            \end{equation*}
            or equivalently,
            \begin{equation*}
                \B\Ck \to \B^3 \ZZ.
            \end{equation*}
            As there is no 3-rd cohomology to $\B\Ck$, these maps are null.
        \end{proof}

        Combining both lemmas and \cref{thm:braiding-depends-only-on-dim} we conclude.
        \begin{corollary}
            Assume $\chrHeight \le 4$. Let $V \in \cC\dbl$ and assume that the $\TT$-action on $\dim(V)$ is trivial. Then $\mscr{X}^{\Zchar}_{\T V}$ depends only on $\eta_{\pichar} \cdot \dim(V) \in \ounit_{\cC}$.
        \end{corollary}

        \begin{proof}
            For $\chrHeight \le 2$ it follows from \cref{lem:trivial-T-action-0-1,lem:trivial-T-action-2,thm:braiding-depends-only-on-dim}. For $\chrHeight = 3,4$ it follows since $\pinD[4] = \pinD[5] = 0$.
        \end{proof}



        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        \subsubsection*{Dimensions of exterior algebras}
        We can use the triviality of the $\Ck$-actions to compare, in nice cases, dimensions of exterior algebras coming from different elements in $\pinD$. 

        In height 0 everything works, and we get a generalization of a well known generating function (in the case $\cC = \Vect$) for the dimensions of symmetric and exterior powers:
        \begin{proposition}\label{prop:generating-function-ht-0}
            Let $\cC$ be $\infty$-semiadditive, $(\SS,0)$-oriented\footnote{It is enough to assume we are working 2-typically.} category.
            Let $V \in \cC\dbl$ such that the $\TT$-action on $\dim(V)$ is trivial. Then,
            \begin{equation*}
                (\sum_{\degree} \dim(\Sym V)\, t^{\degree}) (\sum_{\degree} \dim(\alt_{\Kos} V)\, (-t)^{\degree}) = 1.
            \end{equation*}
        \end{proposition}

        \begin{proof}
            Let $\hat{\eta}\in\pinD[1]$ be the unique non-trivial element. By \cref{cor:dim-of-shift-in-cyc-closed,lem:trivial-T-action-0-1}, $\dim_0 (V\shift{1}) = \dim(V) \in \Gr_{\ZZ} \cC$ and $\dim_{\hat{\eta}}(V\shift{1}) = \eta_{\hat{\eta}} \cdot \dim(V) \in \Gr^{\Kos}_{\ZZ} \cC$.\footnote{We sincerely apologize for the notation $\eta_{\hat{\eta}}$. It is a good opportunity to apologize for the excessive use of footnotes in this paper.}
            As an element in $\In[0] = \QQ/\ZZ$, $\eta_{\hat{\eta}}$ is just the action of $\eta \in \Omega \SS$ on $\hat{\eta} \in \In[1]$, which is $(-1) \in \QQ/\ZZ$. 
            Summarizing: $\dim_0(V\shift{1}) + \dim_{\hat{\eta}}(V\shift{1}) = 0$, where $0$ is equipped with the trivial $\TT$-action.
            By \cref{rmrk:height-0-dual-stems}, $\Gr^{\hat{\eta}}_{\ZZ} \cC = \Gr^{\Kos}_{\ZZ} \cC$. Finally, by \cref{cor:generating-functions-dimensions},
            \begin{equation*}
                (\dim \Sym[\bullet] V) \cdot (\dim \extAlg_{\Kos} V) = \dim \extAlg_{0,\Kos} 0 = 1,
            \end{equation*}
            where $\extAlg_{0,\Kos}$ is the exterior algebra functor in $\Gr^{0,\Kos}_{\ZZ^2} \cC$, proving the statement.
        \end{proof}

        \begin{remark}
            The same proof shows that, working in $\Gr^{0,\hat{\eta}}_{\ZZ^2} \cC$,
            \begin{equation*}
                \mscr{X}_{\T (V\shift{e_1} \oplus V\shift{e_2})} = \mscr{X}_{0} = 1.
            \end{equation*}
            Using that $\T (V \shift{e_1} \oplus V\shift{e_2}) = \T V\shift{e_1} \otimes_{\Day} \T V\shift{e_2}$, and the symmetric monoidal functors $\Gr^0_{\ZZ} \cC \to \Gr^{0,\hat{\eta}}_{\ZZ^2} \cC$, $\Gr^{\Kos}_{\ZZ} \cC \to \Gr^{0,\hat{\eta}}_{\ZZ^2} \cC$, we get a relation between $\chi^{0}_{\Tm V}$ and $\chi^{\Kos}_{\Tm V}$.
            This relation is, unfortunately, much less comprehensible.
        \end{remark}

        In higher heights, the orientation does not provide us with minus one. Therefore we can not hope generally that the sum of the dimensions will be 0. E.g. for $\cC = \Mod_{\sVect}$, the dimension $\dim_{\hat{\eta^2}}(\sVect\shift{1})$ is the  $(0|1) $-dimensional super vector space, and $\dim_0(\sVect \shift{1}) \oplus \dim_{\hat{\eta^2}}(\sVect \shift{1})$ is the $(1|1)$-dimensional super vector space, which is non-zero. 

        We can try to overcome this by forcing additivity, but even that does not guarantee that the dimension would be sent to -1. Thus, we will force both:

        \begin{notation}
            Denote the generators of the cyclic groups $\pinD[2]$ and $\pinD[3]$ by $\hat{\eta^2}$ and $\hat{\nu}$ respectively.
        \end{notation}

        The proof of the following is exactly as \cref{prop:generating-function-ht-0}, using that $\dim(\hat{\eta^2}) = \hat{\eta} \in \In[1]$ and $\dim(\hat{\nu}) = \hat{\eta^2} \in \In[2]$:
        \begin{lemma}\label{lem:generating-function-ht-1-additive}
            Let $\cC$ be $\infty$-semiadditive, $(\SS,1)$-oriented category. Assume that $\cC$ is additive and that the map $\In[1] \to \ounit_{\cC}\units$ sends $\hat{\eta}$ to $(-1)\in \ounit_{\cC}\units$.
            Let $V \in \cC\dbl$ such that the $\TT$-action on $\dim(V)$ is trivial. Then,
            \begin{equation*}
                (\sum_{\degree} \dim(\Sym V)\, t^{\degree}) (\sum_{\degree} \dim(\alt_{\hat{\eta^2}} V)\, (-t)^{\degree}) = 1.
            \end{equation*}
        \end{lemma}
        \begin{lemma}\label{lem:generating-function-ht-2-additive}
            Let $\cC$ be $\infty$-semiadditive, $(\SS,2)$-oriented category. Assume that $\cC$ is additive and that the map $\In[2] \to \ounit_{\cC}\units$ sends $\hat{\eta^2}$ to $(-1)\in \ounit_{\cC}\units$.
            Let $V \in \cC\dbl$ such that the $\TT$-action on $\dim(V)$ is trivial. Then,
            \begin{equation*}
                (\sum_{\degree} \dim(\Sym V)\, t^{\degree}) (\sum_{\degree} \dim(\alt_{\hat{\nu}} V)\, (-t)^{\degree}) = 1.
            \end{equation*}
        \end{lemma}

        \begin{example}
            In the prime $p=2$, at heights $\chrHeight = 1,2$, $\ModEn$ satisfies the above conditions (see \cref{prop:truncated-units}).
        \end{example}

        \begin{remark}\label{rmrk:iterated-dimension}
            A way to bypass this problem in categorical examples such as $\cVectn$, which are never additive, is to consider the iterated dimension. For example, for $\cC = \Mod_{\sVect}$, in both graded categories, corresponding to $0$ and $\hat{\eta^2}$, the object $\sVect \shift{1}$ is 2-dualizable and 
            \begin{equation*}
                \dim^2_0(\sVect\shift{1}) = 1, \qquad \dim^2_\Kos(\sVect\shift{1}) = -1.
            \end{equation*}
            Therefore, one can get a generating function for the iterated dimensions. This is similar in flavor to \cite[Example~4.1.3]{Ganter-Kapranov-2014-exterior-categories}.
            % We will give such formulas in \todo{add cite}.
        \end{remark}

        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        \subsubsection*{Examples of braiding characters}

        Using \cref{lem:character-of-Tm} we can compute by hand the braiding characters in low heights.

        \begin{example}[Day convolution]
            Let $\cC$ be an $\infty$-semiadditive, presentably symmetric monoidal category and $(\SS,\chrHeight)$-oriented for height $\chrHeight \le 2$. Let $V \in \cC\dbl$ and assume that $\TT$ acts trivially on $\dim(V)$. Then, in $\Gr_{\ZZ} \cC$, for $\sigma \in \L\B\Sm\subseteq \L\MM$
            \begin{equation*}
                \chi_{\T V}(\sigma) = (\dim(V))^{\numcyc}\, t^{\degree}.
            \end{equation*}
        \end{example}

        In height 0, we know that the dimension of $\hat{\eta}$ is $(-1)$, so $\dim_{\hat{\eta}}(V\shift{1}) = -\dim(V)$. In particular,
        \begin{example}[Height 0]
            Let $\cC$ be an $\infty$-semiadditive, presentably symmetric monoidal category which is $(\SS,0)$-oriented. Let $V \in \cC\dbl$ and assume that $\TT$ acts trivially on $\dim(V)$. Then, in $\Gr^{\Kos}_{\ZZ} \cC$, for $\sigma \in \L\B\Sm\subseteq \L\MM$
            \begin{equation*}
                \chi^{\Kos}_{\T V}(\sigma) = (-\dim(V))^{\numcyc}\, t^{\degree} = \begin{cases}
                    \dim(V)^{\numcyc}\, t^{\degree}, & \text{$\numcyc$ is even}, \\
                    -\dim(V)^{\numcyc}\, t^{\degree}, & \text{$\numcyc$ is odd}.
                \end{cases}.
            \end{equation*}
        \end{example}

        \begin{remark}
            The same can be said for the braiding character in $\Gr^{\hat{\eta^2}}_{\ZZ} \cC$ and $\Gr^{\hat{\nu}}_{\ZZ} \cC$, under the assumptions of \cref{lem:generating-function-ht-1-additive} and \cref{lem:generating-function-ht-2-additive}, respectively. 

            In particular, this allows us to compute the braiding character in $\ModEn$ for $\chrHeight \le 4$.
        \end{remark}

        \begin{example}[Height 1]
            In $\Mod_{\sVect}$, which is $(\SS,1)$-oriented, $\dim_{\hat{\eta^2}}(\ounit_{\cC}\shift{1}) = \Pi \field$ is the $(0|1)$-dimensional super vector space. For any $\mcal{V} \in \Mod_{\sVect}\dbl$
            \begin{equation*}
                \chi_{\T \mcal{V}}(\sigma) = (\Pi \dim(\mcal{V}))^{\otimes \numcyc}\, t^{\degree} = \begin{cases}
                    \dim(\mcal{V})^{\otimes \numcyc}\, t^{\degree}, & \text{$\numcyc$ is even}, \\
                    \Pi \dim(\mcal{V})^{\otimes \numcyc}\ t^{\degree}, & \text{$\numcyc$ is odd}
                \end{cases}
                \qin \sVect.
            \end{equation*}
        \end{example}

        \begin{remark}
           One can write similar results in height $2$ in terms of $\dim_{\hat{\nu}}(\cVectn[2]\shift{1})$.
        \end{remark}

        \begin{remark}
            Similarly to \cref{rmrk:iterated-dimension}, working in categorical examples, one can consider the iterated character. These behave more like the characters in the additive case. We postpone the study of these to a future paper (\cite{Keidar-Ragimov-??-alternating}).
            % \todo{add cite}.
        \end{remark}       



    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \subsection{The chromatic braiding character}
    \label{subsec:chromatic-braiding-character}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

        In the categorical setting, for example in $\Vectn[\chrHeight+1] = \Mod_{\Vectn}$, the monoidal character map is a categorical operation that decreases the height at the cost of adding a free loops:
        \begin{equation*}
            \chi \colon ((\Vectn[\chrHeight+1])\dbl)^A = (\Mod_{\Vectn}\dbl)^A \to (\Vectn)^{\L A}
        \end{equation*}
        for any space $A$.

        In the chromatic setting, we have an analogous story, using the transchromatic character theory developed by Hopkins--Kuhn--Ravenel, Stapleton and Lurie (\cite{Hopkins-Kuhn-Ravanel-2000-HKR,Stapleton-2013-HKR,Lurie-2019-Elliptic3}). There exists a $\Kn$-local algebra, called the ($\Kn$-local) splitting algebra at height $\chrHeight$,
        \begin{equation*}
            \LKn \Enp \to C^{\chrHeight+1}_{\chrHeight},
        \end{equation*}
        and a transchromatic character map
        \begin{equation*}
            \chi^{\HKR} \colon \Enp^A \to (C^{\chrHeight+1}_{\chrHeight})^{\L A}
        \end{equation*}
        for any $p$-finite space $A$. Since $C^{\chrHeight+1}_{\chrHeight}$ is a nonzero $\Kn$-local algebra, we can relate it to a Morava $E$-theory via the chromatic Nullstellensatz \cite{Burklund-Schlank-Yuan-2022-Nullstellensatz}.

        \begin{notation}
            A map $R \to \En(L)$ in $\CAlg(\SpTn)$, for $L$ algebraically closed, is called a \emph{geometric point of $R$}.
        \end{notation}

        Thus, we obtain a refined transchromatic character map
        \begin{equation*}
            \chi^{\HKR} \colon \Enp^A \to (C^{\chrHeight+1}_{\chrHeight})^{\L A} \to \En(K)^{\L A},
        \end{equation*}
        where $K$ is an algebraically closed field, and the second map arises from a chosen geometric point.

        This connects with the monoidal character, by using again the chromatic Nullstellensatz, which allows us to relate $(\ModEn)\dbl$ with $\Enp$.

        \begin{notation}
            Let $\KTnp \coloneqq \LTnp \K$ denote the $\Tnp$-localized $\K$-theory functor. We also write $\KTnp(\En) \coloneqq \KTnp((\ModEn)\dbl)$.
        \end{notation}

        There is a canonical map of commutative monoids
        \begin{equation*}
            (\ModEn)\dblspace \to \KTnp(\En).
        \end{equation*}
        By chromatic redshift for $\En$ \cite{Yuan-2024-redshift-En}, we know that $\KTnp(\En)$ is nontrivial, so we fix a geometric point
        \begin{equation*}
            \KTnp(\En) \to \Enp(L),
        \end{equation*}
        for some algebraically closed field $L$.
        \begin{definition}
            Using this geometric point, we define the \emph{decategorification map}
            \begin{equation*}
                \de \colon (\ModEn)\dblspace \to \KTnp(\En) \to \Enp(L).
            \end{equation*}
        \end{definition}

        Let $\LKn \Enp(L) \to C^{\chrHeight+1}_{\chrHeight}(L)$ be the associated $\Kn$-local splitting algebra at height $\chrHeight$.

        \begin{construction}\label{cons:character-diagram}
            Choose a geometric point $C^{\chrHeight+1}_{\chrHeight}(L) \to \En(K')$. By \cite[Lemma 7.14, Theorem 7.2(2)]{Burklund-Schlank-Yuan-2022-Nullstellensatz}, we obtain geometric points $\En \to \En(K)$ and $\En(K') \to \En(K)$. For $A \in \pspcpi$, this gives rise to a (not necessarily commutative) diagram:
            \begin{equation*}
                \begin{tikzcd}
                    {((\ModEn)\dblspace)^A} && {\Enp(L)^A} \\
                    && {C^{\chrHeight+1}_{\chrHeight}(L)^{\L A}} \\
                    {\En^{\L A}} && {\En(K)^{\L A}}
                    \arrow["\de", from=1-1, to=1-3]
                    \arrow["\chi", from=1-1, to=3-1]
                    \arrow["\chi^{\HKR}", from=1-3, to=2-3]
                    \arrow[from=2-3, to=3-3]
                    \arrow[from=3-1, to=3-3]
                \end{tikzcd}
            \end{equation*}
            We refer to this as the \emph{character diagram}.
        \end{construction}


        While we expect this diagram to commute in general (up to an isomorphism of $\En(K)$), thereby providing an interpretation of transchromatic character theory as a form of monoidal character theory, we do not know how to prove this in full generality. However, we verify that the two paths agree in special cases (\cref{cor:commutativity-of-character-diagram-suspension-In}, \cref{lem:commutativity-of-character-diagram-En}). These cases serve as the main tool in our analysis of the chromatic braiding character.

        By \cref{lem:character-of-Tm,thm:braiding-depends-only-on-dim}, the study of the braiding character reduces to understanding the character of the restricted action of $\ZZ/p^k \subseteq \Sm[p^k]$ for $p^k$-permutation representations for all $k$. Let $\pichar \in \pinD$. The permutation representation
        \begin{equation*}
            \Tm[p^k] \En\shift{1} \qin (\Gr^{\pichar}_\ZZ \ModEn)^{\B\ZZ/p^k}
        \end{equation*}
        is concentrated in a single degree $p^k$, and thus corresponds to a $\ZZ/p^k$-action on $\En$ in $\ModEn$. We show that the decategorification of this representation is given by
        \begin{equation*}
            \Tm[p^k](\omega(\pichar)) = \omega(\pichar)^{p^k} \qin \Enp(L)^{\B\ZZ/p^k},
        \end{equation*}
        where
        \begin{equation*}
            \omega \colon \pinD = \pi_0(\Inplus) \to \pi_0 \Enp(L)\units
        \end{equation*}
        is the $\pi_0$ of the orientation map.

        The image of $\omega$ lies in $\{\pm 1\}$ (\cref{def:truncated-units}), therefore $\omega(\pichar)$ admits a categorification (i.e.\ a preimage under $\de$):
        \begin{equation*}
            \de(\En) = 1, \qquad \de(\Sigma \En) = -1.
        \end{equation*}
        Using the commutativity of the character diagram in these cases, together with \cref{cor:no-action-on-dim-En}, we conclude that the character of $\Tm \En\shift{1}$ agrees with the character of one of the following:
        \begin{equation*}
            \Tm \En \qor \Tm (\Sigma \En).
        \end{equation*}

        We begin in \cref{subsubsec:character-diagram} by showing that the character diagram commutes in these specific cases. Then in \cref{subsubsec:truncated-units} we study the image of the orientation map $\omega$, classifying when it takes the values $1$ and $-1$ (\cref{prop:truncated-units}). Finally, in \cref{subsubsec:T-action-chromatic}, we deduce a formula for the braiding character in the chromatic setting (\cref{thm:chromatic-braiding-character}).


        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        \subsubsection{Compatibility between monoidal and transchromatic characters}
        \label{subsubsec:character-diagram}

        We investigate certain relations between transchromatic character theory and monoidal character theory, expressed through the commutativity of the character diagram \cref{cons:character-diagram}. Some of the results in this subsection likely hold in greater generality than we state. However, since the special cases presented here suffice for our purposes, we do not pursue the general case further.

        This subsubsection is relatively technical. We begin with a few notations that will help us keep track:

        \begin{notation}
            When working in an $\infty$-commutative monoid $M$ (e.g.\ a $\Tn$-local spectrum), we denote the operation of semiadditive integration in $M$ by $\int^M$.
        \end{notation}

        \begin{notation}
            We work with Morava $E$-theories over various algebraically closed fields. When stating a claim that holds for all such theories, we typically write $\En$ to mean $\En(L)$ for some algebraically closed field $L$.
        \end{notation}

        \begin{notation}
            Let $L$ be an algebraically closed field and $0 \le t \le \chrHeight$. We denote by
            \begin{equation*}
                \LKn[t]\En(L) \to C^{\chrHeight}_t(L)
            \end{equation*}
            the $\Kn[t]$-local splitting algebra for $\En(L)$ at height $t$ 
            (\cite[\textsection~3.10]{Stapleton-2013-HKR}, 
            \cite{Barthel-Stapleton-2016-centralizers-good-groups}, 
            \cite{Barthel-Stapleton-2018-rings-transchromatic}, \cite[Definition~2.7.12]{Lurie-2019-Elliptic3}).

            For any $p$-local $\pi$-finite space $A$, we denote the transchromatic character map by
            \begin{equation*}
                \chi^{\chrHeight - t, \HKR} \colon \En(L)^A \to C^{\chrHeight}_t(L)^{\L^{\chrHeight - t} A},
            \end{equation*}
            and write specifically $\chi^{\HKR} = \chi^{1, \HKR}$.
            We write the evaluation of the character at a specific map $\rho \colon A \to \En(L)$ as
            \begin{equation*}
                \chi^{\chrHeight - t, \HKR}_{\rho} \colon \L^{\chrHeight - t} A \to C^{\chrHeight}_t(L).
            \end{equation*}

            When there is no need to distinguish between different $E$-theories, we omit the field $L$ from the notation.
        \end{notation}

        Recall the following claim from \cite{BMCSY-cardinality}:
        \begin{proposition}[{\cite[Proposition~11]{BMCSY-cardinality}}]\label{prop:KTnp-is-infty-semiadditive}
            The functor $\KTnp \colon \Cat_{\Lnf, \mfin[p]} \to \SpTnp$ is $p$-typically $\infty$-semiadditive.
        \end{proposition}

        \begin{corollary}\label{cor:integral-in-K-is-colim}
            Let $A\in \pspcpi$ and let $V \in ((\ModEn)\dbl)^A$ be an $A$-local system of dualizable objects. Then 
            \begin{equation*}
                \int_A^{\KTnp(\En)} [V] = [\colim_A V] \qin \KTnp(\En).
            \end{equation*}
        \end{corollary}

        \begin{proof}
            As $\KTnp$ is $p$-typically $\infty$-semiadditive, it respects $p$-typical semiadditive integrals. Therefore it sends
            \begin{equation*}
                \colim_A V = \int^{\ModEn}_A V \qin \ModEn
            \end{equation*}
            to 
            \begin{equation*}
                [\colim_A V ] = \int_A^{\KTnp(\En)} [V] \qin \KTnp(\En)
            \end{equation*}
            as claimed.
        \end{proof}

        \begin{lemma}\label{lem:integral-Enp-to-En}
            Let $A \in \pspcpi$, $V \in ((\ModEn)\dbl)^A$. Then the following three semiadditive integrals
            \begin{equation*}
                \int_{\L_p A}^{\En} \chi_V \in \pi_0 \En, \qquad
                \int_{A}^{\Enp(L)} \de(V) \in \pi_0 \Enp(L), \qquad
                \int_{\L_p A}^{C^{\chrHeight+1}_{\chrHeight}(L)} \chi^{\HKR}_{\de(V)} \in \pi_0 C^{\chrHeight+1}_{\chrHeight}(L)
            \end{equation*}
            land in $\ZZ$, and they are all identified.
        \end{lemma}

        \begin{proof}
            By \cref{cor:no-action-on-dim-En}, for each $a \in A$, the value $\de(V)(a) \in \pi_0 \Enp(L)$ is an integer and agrees with $\dim(V_a) \in \ZZ \subseteq \pi_0 \En$.

            As $A$ is $p$-typically $\pi$-finite, $\Lp A \simeq \L A$. Thus, by the induced character formula \cite[Theorem 5.20]{Carmeli-Cnossen-Ramzi-Yanovski-2022-characters},
            \begin{equation*}
                \int_{\Lp A}^{\En} \chi_V \simeq \int_{\L A}^{\En}\chi_V \simeq \dim(\colim_A V).
            \end{equation*}
            By \cite[Proposition~13]{BMCSY-cardinality}, the dimension map
            \begin{equation*}
                \dim \colon \K(\En) \to \ZZ \subseteq \pi_0 \En
            \end{equation*}
            is an isomorphism on $\pi_0$. Under this identification, we identify $\dim(\colim_A V)$ with $[\colim_A V] \in \pi_0 \K(\En)$. The $\Tnp$-localization map gives an identification of $\ZZ\subseteq \K(\En)$ with $\ZZ \subseteq \KTnp(\En)$, so we identify $\dim(\colim_A V)$ with $[\colim_A V] \in \pi_0 \KTnp(\En)$. Now, using \cref{cor:integral-in-K-is-colim},
            \begin{equation*}
                [\colim_A V] = \int_A^{\KTnp(\En)} [V] \qin \pi_0 \KTnp(\En).
            \end{equation*}
            Using the geometric point $\KTnp(\En)\to \Enp(L)$ and \cite[Proposition~2.1.14(1)]{CSY-teleambi}, we get
            \begin{equation*}
                \int_A^{\KTnp(\En)} [V] = \int_A^{\Enp(L)} \de(V),
            \end{equation*}
            which together implies the first equality. The second equality follows by \cite[Remark~7.4.8, Remark~7.4.9]{Lurie-2019-Elliptic3}, see also \cite[Theorem~A]{Ben-Moshe-2024-shifted-semiadditive}.
        \end{proof}

        \begin{definition}\label{def:iterated-character-of-a-map}
            Let $A$ be a $\pi$-finite $p$-space and let $\rho \colon A \to \Sigma\In$ be a map of spaces.  
            For $k \ge 1$, we define the \emph{$k$-fold character} of $\rho$ to be the composition
            \begin{equation*}
                \chi^k_\rho \colon \L^kA \xto{\L^k \rho} \L^k \Sigma\In \xrightarrow{(1+\eta)^k} \Omega^k \Sigma \In \simeq \In[\chrHeight+1-k].
            \end{equation*}
            This is the $k$-fold iterated character of the map $\rho$, as in \cref{def:character-of-a-map}.
        \end{definition}

        \begin{notation}\label{not:higher-character}
            By an abuse of notation, we will usually think of $\rho \colon A \to \Sigma \In$ as the composition (of maps of spaces)
            \begin{equation*}
                A \xto{\rho} \Sigma \In \to \Enp\units \to \Enp.
            \end{equation*}
            Similarly, we consider the the $k$-fold character of $\rho$ as a map to $\En[\chrHeight+1-k]$:
            \begin{equation*}
                \chi^k_{\rho} \colon \L^k A \to \In[\chrHeight+1-k] \to \En[\chrHeight+1-k]\units \to \En[\chrHeight+1-k].
            \end{equation*}
        \end{notation}

        \begin{definition}
            Let $\alpha \in \pinD = \pi_0 (\Inplus)$. The composition
            \begin{equation*}
                \B\ZZ/p^k \to \B\Sm[p^k] \into \MM \xto{\T \alpha} \Inplus \xto{\alpha^{-p^k} \cdot (-)} \Inplus
            \end{equation*}
            is a pointed map. We denote its factorization through the connected cover by
            \begin{equation*}
                \rho_{\alpha,k} \colon \B\ZZ/p^k \to \Sigma\In.
            \end{equation*}
        \end{definition}

         \begin{definition}
            Let $A$ be a $\pi$-finite $p$-space and $\rho \colon A \to \Sigma\In$ be a map of spaces. We denote by $\En{}[\rho]\in (\ModEn)^{A}$ the local system
            \begin{equation*}
                A \xto{\rho} \Sigma\In \to \Sigma \En\units \to \ModEn
            \end{equation*}

            In particular, for $\alpha \in \pinD$, we denote by $\En{}[\rho_{\alpha,k}]$ the local system 
            \begin{equation*}
                \B\ZZ/p^k \xto{\rho_{\alpha,k}} \Sigma \In \to \B\En\units \to \ModEn.
            \end{equation*}
        \end{definition}

        \begin{remark}
            Let $A$ be $\pi$-finite $p$-space and $\rho \colon A \to \Sigma\In$ be a map of spaces. Then $\chi_{\rho}$ as in \cref{not:higher-character} agrees with the character $\chi_{\En{}[\rho]}$.
        \end{remark}

        \begin{lemma}
            Let $\pichar \in\pinD$. We identify the automorphism group of $\En\shift{p^k} \in \Gr^{\pichar}_{\ZZ} \cC$ with $\Aut(\En)$, via the $(-p^k)$ shift map. Then $(\En\shift{1})^{\otimes p^k} \in \B\Aut(\En\shift{p^k})^{\B\ZZ/p^k}$ identifies with $\En{}[\rho_{\pichar, k}] \in \B\Aut(\En)^{\B\ZZ/p^k}$. 
        \end{lemma}

        \begin{proof}
            This is a reformulation of \cref{prop:braiding-of-1<1>-determines-the-character}. 
        \end{proof}

        \begin{lemma}\label{lem:HKR-factors-through-a-map-of-spectra}
            Let $X$ be an $\Ind$-$\pi$-finite $p$-local connective spectrum and $f \colon X \to \En\units$ be a map of spectra. Let $0\le t\le \chrHeight-1$. Then the transchromatic character 
            \begin{equation*}
                \chi^{\chrHeight-t,\HKR}_f \colon \L^{\chrHeight-t}X \to C^{\chrHeight}_t \qin \spc
            \end{equation*}
            factors through a map of connective spectra $\L^{\chrHeight-t} X \to (C^{\chrHeight}_t)\units$.
        \end{lemma}

         \begin{proof}
            For a commutative ring spectrum $R$, we denote by $\spc_{/R}$ the category of spaces over $\Omega^{\infty} R$. It is equipped with the symmetric monoidal structure given by the cartesian product of spaces, using the commutative monoid structure on $\Omega^{\infty} R$ induced by the multiplication on $R$.

            Let $k \in \NN$. Then the map $\En^{(-)}\to \LKn[t]\En^{(\B\ZZ/p^k)^{\chrHeight-t} \times\Map((\B \ZZ/p^k)^{\chrHeight-t},(-))}$, induces a symmetric monoidal map
            \begin{equation*}
                \Map((\B\ZZ/p^k)^{\chrHeight-t},(-)) \colon \spc_{/\En} \to \spc_{/\LKn[t]\En^{(\B\ZZ/k)^{\chrHeight-t}}}.
            \end{equation*}
            Composing with the natural map $\LKn[t]\En^{(\B\ZZ/p^k)^{\chrHeight-t}}\to C^{\chrHeight}_t$ and using the compatibility of these maps, we get a symmetric monoidal map
            \begin{equation*}
                \colim_k\Map((\B\ZZ/p^k)^{\chrHeight-t},(-)) \colon \spc_{/\En} \to \spc_{/C^{\chrHeight}_t}.
            \end{equation*}
            Restricting to $(\pspcpi)_{/\En}$ and using \cite[Proposition 3.4.7]{Lurie-2019-Elliptic3} we get a symmetric monoidal map 
            \begin{equation*}
                \L^{\chrHeight-t} \colon (\pspcpi)_{/\En} \to (\pspcpi)_{/C^{\chrHeight}_t}.
            \end{equation*}
            Using that the free loops functor $\L$ commutes with filtered colimits since $\TT$ is compact, we may take $\Ind$ to both sides. As the functor is symmetric monoidal it induces a map on commutative algebras
            \begin{equation*}
                \L^{\chrHeight-t} \colon \CAlg(\Ind(\pspcpi)_{/\En}) \to \CAlg(\Ind(\pspcpi)_{/C^{\chrHeight}_t}),
            \end{equation*}
            sending $f \colon X \to \En$ to $\chi^{\chrHeight-t, \HKR}_f \colon \L^{\chrHeight-t} X \to C^{\chrHeight}_t$. In particular, if $X$ is a spectrum and $f$ is a map of commutative monoids, then $\chi^{\chrHeight-t,\HKR}_f$ factors through $(C^{\chrHeight}_t)\units$.
          \end{proof}   

        \begin{remark} 
            By the proof of \cref{lem:HKR-factors-through-a-map-of-spectra}, for any $\pi$-finite $p$-space $X$ and 
            \begin{equation*}
                \rho \colon X\to \In \to \En,
            \end{equation*}
            the transchromatic character map $\chi^{\chrHeight-t, \HKR}_{\rho}\colon \L^{\chrHeight-t}X \to C^{\chrHeight}_t$ factors through a map of spectra $\L^{\chrHeight-t}\In \to (C^{\chrHeight}_t)\units$.  
        \end{remark}

        \begin{lemma}\label{lem:orbits-of-free-loops-is-loops}
            Let $X$ be a spectrum. Then $(\Lnc^k\, X)_{h\TT^k} \simeq \Sigma^{-k} X$, where $\Lnc$ is the non-connective free loops spectrum. Under the isomorphism
            \begin{equation*}
                \Lnc^k \, X \simeq (\Sigma^{-1} \oplus \id_{\cnSp})^k\, X \simeq \bigoplus_{i=0}^k \bigoplus_{k \choose i} (\Sigma^{-i} X),
            \end{equation*} 
            the canonical map to the orbit is $(1+\eta)^k \simeq \bigoplus_{i=0}^k \bigoplus_{k \choose i} \eta^i$.  
        \end{lemma}

        \begin{proof}
            It is enough to prove it for the case $k=1$. As $\Lnc\, X = \hom(\SS[\TT], X)$ with the $\TT$-action only coming from $\SS[\TT]$, and as $\SS[\TT]$ is dualizable, it is enough to prove it for $X = \SS$, in which case it is of the dual decomposition in \cref{prop:trace-is-counit}.
        \end{proof}

        \begin{lemma}\label{lem:HKR-vs-twice-HKR}
             Let $A \in \pspcpi$ and $0 \le s \le t \le \chrHeight$. Then for every geometric point $C^{\chrHeight}_t(K) \to \En[t](K_t)$ there exists a map of $\Kn[s]$-local commutative algebras $C^{\chrHeight}_s(K) \to C^t_s(K_t)$ rendering the following diagram commutative
             \begin{equation*}
                \begin{tikzcd}
                    {\En(K)^{A}} & {C^{\chrHeight}_t(K)^{\L^{\chrHeight-t}A}} & {\En[t](K_t)^{\L^{\chrHeight-t}A}} \\ \\
                    {C^{\chrHeight}_s(K)^{\L^{\chrHeight-s}A}} && {C^t_s(K_t)^{\L^{\chrHeight-s}A}.}
                    \arrow["{\chi^{\chrHeight-t,\HKR}}", from=1-1, to=1-2]
                    \arrow["{\chi^{\chrHeight-s,\HKR}}", from=1-1, to=3-1]
                    \arrow[from=1-2, to=1-3]
                    \arrow["{\chi^{t-s,\HKR}}", from=1-3, to=3-3]
                    \arrow[from=3-1, to=3-3]
                \end{tikzcd}
            \end{equation*}
         \end{lemma}

        \begin{proof}
         Consider the composition
            \begin{equation*}
                \LKn[s] \En(K) \to \LKn[s] \LKn[t] \En(K) \to \LKn[s] C^{\chrHeight}_t(K) \to \LKn[s] \En[t](K_t) \to C^t_s(K_t).
            \end{equation*}
            Let $\mbf{G}_{\LKn[t]\En(K)}$ be the pullback of the Quillen $p$-divisible $\mbf{G}^{\mcal{Q}}_{\En(K)}$ on $\En(K)$ to $\LKn[t]\En(K)$. By \cite[Corollary~2.5.7]{Lurie-2018-Elliptic2}, the canonical orientation of $\mbf{G}^{\mcal{Q}}_{\En(K)}$ induces an injective pre-orientation $\mbf{G}^{\mcal{Q}}_{\LKn[t]\En(K)} \to \mbf{G}_{\LKn[t]\En(K)}$. By the proof of \cite[Proposition~2.5.6]{Lurie-2018-Elliptic2}, it is identified with the connected component at the unit so sits in a cofiber sequence
            \begin{equation*}
                0 \to \mbf{G}^{\mcal{Q}}_{\LKn[t](\En)} \to \mbf{G}_{\LKn[t](\En)} \to \mbf{G}^{\mrm{\'et}}_{\LKn[t](\En)} \to 0.
            \end{equation*}
            By \cite[Corollary~2.18]{Stapleton-2013-HKR},\cite[Definition~2.7.12]{Lurie-2019-Elliptic3} the pullback of $\mbf{G}_{\LKn[t]}(\En)$ to $C^{\chrHeight}_t(K)$ splits and has a trivial \'etale part 
            \begin{equation*}
                \mbf{G}_{C^{\chrHeight}_t(K)} \simeq \underline{(\QQ_p/\Zp)}^{\chrHeight-t} \oplus \mbf{G}^{\mcal{Q}}_{C^{\chrHeight}_t(K)}.
            \end{equation*}
            This in turn, by \cite[Remark~4.3.6, Proposition~4.3.21, Proposition~4.3.23]{Lurie-2018-Elliptic2}, is pulled to the $p$-divisible group
            \begin{equation*}
                \underline{(\QQ_p/\Zp)}^{\chrHeight-t} \oplus \mbf{G}^{\mcal{Q}}_{\En[t](K_t)}
            \end{equation*}
            on $\En[t](K_t)$. 
            Finally, repeating the above arguments, this is pulled to the $p$-divisible group 
            \begin{equation*}
                \underline{(\QQ_p/\Zp)}^{\chrHeight-s} \oplus \mbf{G}^{\mcal{Q}}_{C^t_s(K_t)}
            \end{equation*}
            on $C^t_s(K_t)$. 
            As $C^{\chrHeight}_s(K)$ is initial with respect to this property (\cite[Corollary~2.18]{Stapleton-2013-HKR}, \cite[Definition~2.7.12, Proposition 2.7.15]{Lurie-2019-Elliptic3}), this composition factors through $C^{\chrHeight}_s(K)$. As those are maps of tempered $\EE_\infty$-rings (\cite[Notation~4.0.1]{Lurie-2019-Elliptic3}), applying \cite[Theorem~4.3.2]{Lurie-2019-Elliptic3} we get the commutativity of the desired diagram.
        \end{proof}


        \begin{proposition}\label{prop:HKR-factors-through-trace}
            Let $A\in \pspcpi$ and $\rho \colon A \to \Inplus$ be a map of spaces. Using the notations of \cref{cons:character-diagram}, the map
            \begin{equation*}
                \L A \xto{\chi^\HKR_\rho} C^{\chrHeight+1}_{\chrHeight}(L)\to \En(K)
            \end{equation*}
            we get by the right vertical composition of \cref{cons:character-diagram} factors as 
            \begin{equation*}
                \L A \xto{\L \rho} \L\Inplus \xto{1+\eta} \In \to \En(K)\units \to \En(K).
            \end{equation*}
        \end{proposition}

        \begin{proof}
            Since $\Inplus$ is $\Ind$-$\pi$-finite, by \cref{lem:HKR-factors-through-a-map-of-spectra} we have that $\chi_\rho^\HKR$ factors through a map of spectra 
            \begin{equation*}
                f \colon \L \Inplus \to  C^{\chrHeight+1}_{\chrHeight}(L)\units.
            \end{equation*}
            As $\Mod_{\En(K)}$ is $(\chrHeight+1)$-connected (\cref{def: cat connectedness}), using that $\L\Inplus$ is $\Ind$-$\pi$-finite, the composition 
            \begin{equation*}
                \L\Inplus \xto{f} C^{\chrHeight+1}_{\chrHeight}(L)\units \to \En(K)\units,
            \end{equation*}
            factors, as a map of spectra, through $\In = (\En(K)\units)\pitor$. 
            % \begin{equation*}
            %     \L A\to \L \In \simeq \In \oplus \In[\chrHeight-1] \xto{1+\eta}  \In[\chrHeight-1] \to \En[\chrHeight-1](L)\units \to \En[\chrHeight-1](L)
            % \end{equation*}
            % where all the maps apart from the last and the first are maps of spectra.
            It is left to show that the map 
            \begin{equation*}
                f \colon \Inplus \times \In \simeq \L\Inplus \to \In
            \end{equation*}
            is the trace map, i.e.\ $1+\eta$. 
            Using the universal property of $\In$ (\cref{rmrk:maps-to-In}), this is equivalent to the map being classified by:
            \begin{itemize}
                \item  $1 \in \ZZ_2 = \widehat{\pi}_{\chrHeight}(\In)$ and $\eta \in \{1,\eta\} = \widehat{\pi}_{\chrHeight}(\Inplus)$ when $p=2$, or
                \item $1 \in \Zp = \widehat{\pi}_{\chrHeight}(\In)$ (and $\widehat{\pi}_{\chrHeight}(\Inplus) = 0$) when $p \neq 2$. 
            \end{itemize}

            We first show that for any $p$, the restriction to $\In$ is classified by an invertible element in $\Zp$.
            Let $\tau \colon \Sigma^{\chrHeight+1}\ZZ/p \to \Sigma^{\chrHeight+1}\QQ_p/\Zp \to \Inplus$ be the natural map. Then, the composition of maps of connective spectra
            \begin{equation*}
                \Sigma^{\chrHeight+1} \ZZ/p \xto{\tau} \Inplus \to \En\units
            \end{equation*}
            chooses the higher $p$-th root of unity $\omega^{(\chrHeight)}_p$ (see \cite{CSY-cyclotomic}) and therefore is not nullhomotopic. 
            By \cite[Corollary 8.12]{Burklund-Schlank-Yuan-2022-Nullstellensatz} and \cref{lem:integral-Enp-to-En}, we see that 
            \begin{equation*}
                0=\dim(\colim_{\B^{\chrHeight+1}\ZZ/p} \En[\chrHeight][\tau])=\int_{\B^{\chrHeight+1}\ZZ/p}^{\En[\chrHeight+1](L)} \tau=\int_{\L\B^{\chrHeight+1}\ZZ/p}^{C^{\chrHeight+1}_{\chrHeight}(L)}\chi_\tau^\HKR.
            \end{equation*}
            Therefore, the image of the element that classifies our map, under the modulo $p$ map
            \begin{equation*}
                \Zp = \Hom_{\Ab}(\QQ_p/\Zp, \QQ_p/\Zp) \to \Hom_{\Ab}(\ZZ/p,\QQ_p/\Zp) \simeq \ZZ/p,
            \end{equation*}
            is non zero. That is, it is an invertible element in $\Zp$. Thus, up to a choice of a different orientation $\In\to \En\units$, the restriction to $\In$ is the identity.

            We are now left with the case $p=2$. We will show that the restriction to $\Inplus$ is classified by $\eta \in  \pi_{\chrHeight}(\Inplus)$. Assume otherwise, i.e.\ that it is the trivial map. Let 
            $I \coloneqq \hom(\tau_{\le 1}\SS/2, \Inplus)$ and consider the map 
            \begin{equation*}
                g \colon I \to \Inplus,
            \end{equation*}
            dual to the natural modulo 2 and truncation map $\SS \to \tau_{\le 1}\SS/2$. 
            By assumption, the composition
            \begin{equation*}
                I \xto{g} \Inplus \to \L\Inplus \xto{f} \In
            \end{equation*}
            is trivial, or equivalently,
            \begin{equation*}
                I \to \L I \xto{\L g} \L\Inplus \xto{f} \In
            \end{equation*}
            is trivial.
            By \cref{lem:HKR-vs-twice-HKR}, we have a commutative diagram 
            % \begin{equation*}
            %     \begin{tikzcd}
            %         {C^{\chrHeight+1}_{\chrHeight}(L)^{\L I}} & {\En[\chrHeight](K)^{\L I}} \\
            %         {C^{\chrHeight+1}_{0}(L)^{\L^{\chrHeight+1} I}} & {C^{\chrHeight}_0(K)^{\L^{\chrHeight+1}I}\ ,}
            %         \arrow[from=1-1, to=1-2]
            %         \arrow[from=1-1, to=2-1]
            %         \arrow[from=1-2, to=2-2]
            %         \arrow[from=2-1, to=2-2]
            %     \end{tikzcd}
            % \end{equation*}
            \begin{equation*}
                \begin{tikzcd}
                    {\Enp^{I}} & {(C^{\chrHeight+1}_{\chrHeight})^{\L I}} & {\En(K)^{\L I}} \\ \\
                    {(C^{\chrHeight+1}_0)^{\L^{\chrHeight+1}I}} && {C^{\chrHeight}_0(K)^{\L^{\chrHeight+1}I}.}
                    \arrow["{\chi^{\HKR}}", from=1-1, to=1-2]
                    \arrow["{\chi^{\chrHeight+1,\HKR}}", from=1-1, to=3-1]
                    \arrow[from=1-2, to=1-3]
                    \arrow["{\chi^{\chrHeight,\HKR}}", from=1-3, to=3-3]
                    \arrow[from=3-1, to=3-3]
                \end{tikzcd}
            \end{equation*}
            As $C^{\chrHeight}_0(K)$ is rational and $\L^{\chrHeight+1} I$ is $\pi$-finite, the map of spaces 
            \begin{equation*}
                \chi^{\chrHeight+1, \HKR}_g \colon \L^{\chrHeight+1} I \to C^{\chrHeight}_0(K)
            \end{equation*}
            factors through $\pi_0 \L^{\chrHeight+1} I \simeq \ZZ/2^{\oplus(\chrHeight+2)}$. By \cref{lem:HKR-factors-through-a-map-of-spectra}, this map factors through a map of spectra $\ZZ/2^{\oplus(\chrHeight+2)} \to C^{\chrHeight}_0(K)\units$. 
            The space of maps $\ZZ/2^{\oplus (\chrHeight+2)} \to C^{\chrHeight}_0(K)\units$ is discrete, therefore the map
            \begin{equation*}
                \L^{\chrHeight+1} I \to C^{\chrHeight}_0(K)\units
            \end{equation*}
            is $\TT^{\chrHeight+1}$-invariant, and induces a map of connective spectra
            \begin{equation*}
                (\L^{\chrHeight+1} I)_{h\TT^{\chrHeight+1}} \to C^{\chrHeight}_0(K)\units.
            \end{equation*}

            Consider the $(\chrHeight+1)$-connective cover map
            \begin{equation*}
                \Sigma^{\chrHeight+1} \ZZ/2 \to I
            \end{equation*}
            and the commutative diagram
            \begin{equation*}
                \begin{tikzcd}
                    {\L^{\chrHeight+1}\Sigma^{\chrHeight+1}\ZZ/2} & {\L^{\chrHeight+1}I} & {\Lnc^{\chrHeight+1}I} \\
                    {(\L^{\chrHeight+1}\Sigma^{\chrHeight+1}\ZZ/2)_{h\TT^{\chrHeight+1}}} & {(\L^{\chrHeight+1}I)_{h\TT^{\chrHeight+1}}} & {(\Lnc^{\chrHeight+1}I)_{h\TT^{\chrHeight+1}}.}
                    \arrow[from=1-1, to=1-2]
                    \arrow[from=1-1, to=2-1]
                    \arrow[from=1-2, to=1-3]
                    \arrow[from=1-2, to=2-2]
                    \arrow[from=1-3, to=2-3]
                    \arrow[from=2-1, to=2-2]
                    \arrow[from=2-2, to=2-3]
                \end{tikzcd}            
            \end{equation*}
            Using \cref{lem:orbits-of-free-loops-is-loops}, and that $\L^{\chrHeight+1}\Sigma^{\chrHeight+1} \ZZ/2 = \Lnc^{\chrHeight+1} \Sigma^{\chrHeight+1}\ZZ/2$, we write it equivalently as
            \begin{equation*}
                \begin{tikzcd}
                    {\L^{\chrHeight+1}\Sigma^{\chrHeight+1}\ZZ/2} & {\L^{\chrHeight+1}I} & {\Lnc^{\chrHeight+1}I} \\
                    {\ZZ/2} & {(\L^{\chrHeight+1}I)_{h\TT^{\chrHeight+1}}} & {\Sigma^{-(n+1)}I.}
                    \arrow[from=1-1, to=1-2]
                    \arrow["{(\eta+\id)^{\chrHeight+1}}", from=1-1, to=2-1]
                    \arrow[from=1-2, to=1-3]
                    \arrow[from=1-2, to=2-2]
                    \arrow["{(\eta+\id)^{\chrHeight+1}}", from=1-3, to=2-3]
                    \arrow[from=2-1, to=2-2]
                    \arrow[from=2-2, to=2-3]
                \end{tikzcd}
            \end{equation*}
            Note that the vertical left map and the bottom horizontal composition are isomorphisms on $\pi_0$. In particular, there is a $\ZZ/2$-summand in $\pi_0((\L^{\chrHeight+1} I)_{h\TT^{\chrHeight+1}})$ such that
            \begin{enumerate}
                \item\label{item:onto} the map $\pi_0 (\L^{\chrHeight+1} I) \to \pi_0((\L^{\chrHeight+1} I)_{h\TT^{\chrHeight+1}}) \onto \ZZ/2$ is given by $\pi_0 (\eta + \id)^{\chrHeight+1}$, and
                \item\label{item:into} the composition 
                \begin{equation*}
                    \ZZ/2 \into \pi_0((\L^{\chrHeight+1} I)_{h\TT^{\chrHeight+1}}) \to \pi_0 C^{\chrHeight}_0(K) \units
                \end{equation*}
                agrees with
                \begin{equation*}
                    \ZZ/2 \xto{\pi_0 \chi^{\chrHeight+1, \HKR}_{\tau}} \pi_0 C^{\chrHeight+1}_0 \to \pi_0 C^{\chrHeight}_0(K).
                \end{equation*}
                where $\tau \colon \Sigma^{\chrHeight+1} \ZZ/2 \to \Inplus$ is the natural map.
            \end{enumerate}

            By our assumption, the composition
            \begin{equation*}
                \pi_0 \L^{\chrHeight} I \to \pi_0 \L^{\chrHeight+1} I  \to \pi_0 C^{\chrHeight}_0(K)\units
            \end{equation*}
            is zero, therefore so is the composition with the projection to the $\ZZ/2$-summand
            \begin{equation*}
                \pi_0 \L^{\chrHeight} I \to \pi_0 \L^{\chrHeight+1} I  \onto \ZZ/2 \into \pi_0 \L^{\chrHeight+1} I \to \pi_0 C^{\chrHeight}_0(K)\units.
            \end{equation*}
            By (\labelcref{item:onto}), the composition
            \begin{equation*}
               \ZZ/2 = \pi_0 \L^{\chrHeight} I \to \pi_0 \L^{\chrHeight+1} I \onto \ZZ/2
            \end{equation*}
            is an isomorphism, therefore the restriction
            \begin{equation*}
                \ZZ/2 \into \pi_0 \L^{\chrHeight+1} I \to \pi_0 C^{\chrHeight}_0(K)\units
            \end{equation*}
            is zero.            
            But by (\labelcref{item:into}), this composition is not zero, in contradiction.
        \end{proof} 

       % We now relate the transchromatic character theory, and categorical character theory, for maps factoring through $\In$, via the chromatic Nullstellensatz and decent.



        \begin{lemma}\label{lem:spherical-roots-of-unity-Nullstellensatz-shift}
            Following the notations of \cref{cons:character-diagram}, the orientation map, composed with the geometric point
            \begin{equation*}
                \Sigma \In \to \Sigma \En\units \to (\ModEn)\units \to \KTnp(\En)\units \to \Enp(L)\units,
            \end{equation*}
            is a $(\tau_{\le \chrHeight} \SS, \chrHeight+1)$-orientation. In particular, we can assume it is the connected cover of the $(\SS,\chrHeight+1)$-orientation map of $\Enp(L)$.
        \end{lemma}

        \begin{proof}
            Let $\Sigma^{\chrHeight+1} \QQ_p / \Zp \to \Sigma \In$ denote the $(\chrHeight+1)$-connective cover. Since the induced map
            \begin{equation*}
                \pi_0 \Map(\Sigma \In, \Inplus) \to \pi_0 \Map(\Sigma^{\chrHeight+1} \QQ_p / \Zp, \Inplus)
            \end{equation*}
            is an isomorphism, it suffices to verify the claim after precomposing with it.  
            By \cite[Theorem~5.15]{BCSY-Fourier}, the map
            \begin{equation*}
                \Sigma^{\chrHeight+1} \QQ_p / \Zp \to \Sigma \En\units \to (\ModEn)\units
            \end{equation*}
            is an orientation of $\ModEn$, exhibiting it as having primitive roots of unity of height $\chrHeight+1$.

            By \cite[Theorem~B]{BMCSY-cycloshift}, primitive roots of unity of height $\chrHeight+1$ in $\ModEn$ map to the corresponding height $\chrHeight+1$ primitive roots of unity in $\KTn(\En)$, which in turn are sent to the primitive roots of unity of $\Enp(L)$.    
        \end{proof}


         \begin{corollary}\label{cor:commutativity-of-character-diagram-suspension-In}
            Let $A$ be a $\pi$-finite $p$-local space and $\rho \colon A\to \Sigma \In$ be a map of spaces. 
            Then the image of $\En{}[\rho] \in ((\ModEn)\dbl)^A$, under both compositions in the character diagram \cref{cons:character-diagram}, is the same, up to multiplication by an invertible $p$-adic integer.\footnote{I.e.\ up to a change of $(\SS,\chrHeight)$-orientation of $\En(K)$.}

            Written differently, $\chi_{\rho}$ in the sense of \cref{def:iterated-character-of-a-map} agrees with $\chi^{\HKR}_{\rho}$ (after mapping both to $\En(K)$).
         \end{corollary}

         \begin{proof}
             This follows from \cref{prop:HKR-factors-through-trace} and \cref{lem:spherical-roots-of-unity-Nullstellensatz-shift}.
         \end{proof}  

         \begin{lemma}\label{lem:commutativity-of-character-diagram-En}
            Let $P \subseteq \Sm$ be a $p$-subgroup. Assume that $P$ is an $\En$-good group in the sense of \cite{Barthel-Stapleton-2016-centralizers-good-groups} (which is implied by \cite[Definition~7.1]{Hopkins-Kuhn-Ravanel-2000-HKR}). Let $V \in (\ModEn)\dbl$. Then the image of $\Tm V \in ((\ModEn)\dbl)^{\B P}$ under the two composition in the character diagram \cref{cons:character-diagram} is the same.
         \end{lemma}

        \begin{proof}
            Since $P$ is an $\En$-good group, by \cite[Corollary 7.1]{Barthel-Stapleton-2016-centralizers-good-groups}, so are its centralizers, and therefore the transchromatic character map 
            \begin{equation*}
                \chi^{\chrHeight,\HKR} \colon \En(K)^{\L \BP}\to C^{\chrHeight}_0(K)^{\L^{\chrHeight+1}\BP}
            \end{equation*}
            is injective on $\pi_0$. Therefore it suffices to check commutativity after composing to $C^{\chrHeight}_0(K)^{\L^{\chrHeight+1} \BP}$. 

            We now show that both compositions arise as instances of the \emph{character of the total power operation}, as constructed in \cite[Theorem 9.1]{Barthel-Stapleton-2017-power-operations}. More precisely, they both coincide with the character applied to $d \coloneqq \dim(V)$ with $G = e$, and restricted along $\L^{\chrHeight+1} \BP \to \Lp^{\chrHeight+1} \B \Sm$.

            First, by \cite[Corollary 10.2]{Barthel-Stapleton-2017-power-operations}, the character of the total power operation evaluated on $d$ is independent of the choice of $\phi$. By \cref{lem:HKR-vs-twice-HKR} $\Tm V$ is sent under the composition 
            \begin{equation*}
                ((\ModEn)\dbl)^{\BP} \xto{\de} \En[n+1](\L)^{\BP} \xto{\chi^{\HKR}} \En(K)^{\L\BP} \xto{\chi^{\chrHeight,\HKR}} C^{\chrHeight}_0(K)^{\L^{\chrHeight+1}\BP}
            \end{equation*}
            to the character of the total power operation applied to $d$. 

            To see that the other composition agrees with this character, we use the formula for the character of the total power operation given just before \cite[Proposition 5.5]{Barthel-Stapleton-2017-power-operations}. Let $[\degree]$ be a set of cardinality $\degree$. An element of
            \begin{equation*}
                \pi_0 \Lp^{\chrHeight+1} \B \Sm = \Hom(\Zp^{\chrHeight+1}, \Sm) / \mrm{conj}
            \end{equation*}
            can be viewed as a $\Zp^{\chrHeight+1}$-action on $[\degree]$. 
            The formula then evaluates the character of the total power operation applied to $d =\dim(V)$ at this $\Zp^{\chrHeight+1}$-set, as $d^r$, where $r$ is the number of $\Zp^{\chrHeight+1}$-orbits in $[\degree]$.

            The claim now follows from \cref{lem:character-of-Tm}, which asserts that the value of $\chi_{\Tm V}$ on a $\Zp$-set of size $m$ is $d^\ell$, where $\ell$ is the number of $\Zp$-orbits in its decomposition. In this case, the stabilizer of the corresponding conjugacy class acts by permuting isomorphic orbits.
        \end{proof}

        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        \subsubsection{Truncated units}
        \label{subsubsec:truncated-units}

        By \cref{subsubsec:character-diagram}, since the character diagram commutes for both permutation representations and characters factoring through~$\In$, it follows that the character of $\Tm\En\shift{1} \in \Gr^{\pichar}_{\ZZ} \ModEn$ agrees with the transchromatic character of the image of $\pichar$ under $\pi_0$ of the orientation map (\cref{lem:character-of-rho-is-character-of-Tm}).

        We are thus led to study the image of the orientation map $\In \to \En\units$ on~$\pi_0$. We call elements in this image truncated units, and immediately show that almost always there are no such units.


        \begin{definition}\label{def:truncated-units}
            Denote the $\pi_0$ of the orientation map by
            \begin{equation*}
                \omega \colon \pinD[\chrHeight] = \pi_0 \In \to \pi_0 \En\units.
            \end{equation*}
            We call an element in $\pi_0 \En\units$ a truncated unit if it is in the image of $\omega$.
        \end{definition}

        Note that a truncated unit must lie in the $p$-power torsion group
        \begin{equation*}
            \pi_0 \En\units[p^{\infty}] = \Witt(\Fpbar)[\![u_1,\dots,u_{\chrHeight-1}]\!]\units[p^{\infty}] = \begin{cases}
                \{1\}, & p \neq 2 \\
                \{\pm 1\}, & p = 2.
            \end{cases}
        \end{equation*}
        Therefore, when $p \neq 2$ there are no non-trivial truncated units. When $p=2$, only $-1$ can be a non-trivial truncated unit. 
        Our goal is therefore to understand when $-1\in \pi_0 \En\units$ is truncated in the case $p=2$. Until the end of this part we assume $p=2$. We will use the following notation:
        \begin{notation}
             Let $\pichar \in \pinD[\chrHeight]$. Define
             \begin{equation*}
                 \Sigma^{\pichar} \Enm \coloneqq \begin{cases}
                     \Sigma \Enm, & \omega(\pichar) = -1, \\
                     \Enm, & \omega(\pichar) = 1
                 \end{cases}
                 \qin \ModEnm.
             \end{equation*}
        \end{notation}

        \begin{definition}
            Let $\pichar \in \pinD[\chrHeight]$. Define
            \begin{equation*}
                \rho_{\pichar,k} \colon \B\ZZ/2^k \to \B\Sm[2^k] \into \MM \xto{\pichar} \In.
            \end{equation*}
            As before, we will abuse notation and sometimes identify it with the map of spaces
            \begin{equation*}
                \rho_{\pichar,k} \colon \B\ZZ/2^k \to \In \to \En\units \to \En.
            \end{equation*}
        \end{definition}

        \begin{lemma}\label{lem:character-of-rho-is-character-of-Tm}
             Let $\pichar \in\pinD[\chrHeight]$. Then 
            \begin{equation*}
                \chi_{\Tm[p^k](\Sigma^\pichar \Enm)} \simeq \chi_{\Enm{}[\rho_{\pichar,k}]},
            \end{equation*}
            where $\Tm[p^k](\Sigma^{\pichar} \Enm) \in (\ModEnm)^{\B\ZZ/p^k}$ is equipped with the restricted action of $\ZZ/p^k \subseteq \Sm[p^k]$.
        \end{lemma}

        \begin{proof}
            By \cref{lem:spherical-roots-of-unity-Nullstellensatz-shift}, the image of ${\Enm{}[\rho_{\pichar,k}]}$ and $\Tm[p^k](\Sigma^\pichar \Enm)$ is the same under the decatgorification map
            \begin{equation*}
                \de \colon (\ModEnm)^{\B\ZZ/p^k} \to \En(L)^{\B\ZZ/p^k}.
            \end{equation*}
            Consider the character diagram \cref{cons:character-diagram} for height $\chrHeight-1$. Since the bottom horizontal map $\Enm^{\L \B \ZZ/p^k} \to \Enm(K)^{\L\B\ZZ/p^k} $ is injective on $\pi_0$, the claim follows from \cref{cor:commutativity-of-character-diagram-suspension-In} and \cref{lem:commutativity-of-character-diagram-En}.
        \end{proof}


        \begin{corollary}\label{cor:character-of-alpha}
            Let $0 \le t \le \chrHeight$. Choose a geometric point $C^{\chrHeight}_{t} \to \En[t](K_t)$ for some algebraically-closed field $K_t$. 
            Let $\pichar \in \pinD[\chrHeight]$. Define $\pichar_{t} \coloneqq \eta^{\chrHeight-t}\cdot \pichar \in \pi_{\chrHeight-t} (\In) = \pinD[t]$, where $\eta \in \pi_1 \SS$ acts by the $\SS$-module structure. Let $\omega_t \in \pi_0 \En[t](K_t)\units$ be the image of $\pichar_t$ under the orientation map. Then 
            \begin{equation*}
                \chi^{\chrHeight-t,\HKR}_{\rho_{\pichar,k}} \colon \L^{\chrHeight-t} \B \ZZ/2^k \simeq \bigsqcup_{(\ZZ/2^k)^{\chrHeight-t}} \B\ZZ/2^k \to C^{\chrHeight}_{t} \to \En[t](K_t)
            \end{equation*}
            can be computed inductively on $k$, as follows:
            \begin{enumerate}
                \item If $k = 0$, it is $\omega_t \in \En[t](K_t)\units$.
                \item On a connected component $(x_1,\dots,x_{\chrHeight-t})$ which is not 2-divisible, it is $\omega_t \in \En[t](K_t)\units$ with the trivial $\ZZ/2^k$-action.
                \item On a connected component of the form 
                \begin{equation*}
                    2(x_1,\dots, x_{\chrHeight-t}) \in (\ZZ/2^k)^{\chrHeight-t}, \qquad \text{for} \qquad (x_1,\dots, x_{\chrHeight-t}) \in (\ZZ/2^{k-1})^{\chrHeight-t},
                \end{equation*}
                it is $(\chi^{\chrHeight-t, \HKR}_{\rho_{\pichar,k-1}}(x_1,\dots,x_{\chrHeight-t}))^2$ computed as the induction (i.e.\ the 0-semiadditive integral) from $\ZZ/2^{k-1}$ to $\ZZ/2^k$, in $\En[t](K_t)\units$:
                \begin{equation*}
                    \begin{split}
                        \chi^{\chrHeight-t, \HKR}_{\rho_{\pichar,k-1}}(2x_1,\dots,2x_{\chrHeight-t}) 
                        & = \int^{\En[t](K_t)\units}_{\B\ZZ/2^{k-1} \to \B\ZZ/2^k} \chi^{\chrHeight-t, \HKR}_{\rho_{\pichar,k-1}}(x_1,\dots,x_{\chrHeight-t}) \\
                        & \simeq (\chi^{\chrHeight-t, \HKR}_{\rho_{\pichar,k}}(x_1,\dots,x_{\chrHeight-t}))^2 \qin (\En[t](K_t)\units)^{\B\ZZ/2^k}.
                    \end{split}
                \end{equation*}                
            \end{enumerate}
        \end{corollary}

        \begin{proof}
            This follows from \cref{cor:commutativity-of-character-diagram-suspension-In}, \cref{lem:character-of-rho-is-character-of-Tm}, \cref{lem:character-of-Tm} and \cref{cor:no-action-on-dim-En}.
        \end{proof}

        \begin{remark}
            Note that as we write the addition rule in $\In[t]$ and $\En[t](K_t)\units$ as multiplication, $\omega_t^2$ is the image of $\pichar_t^2$ which is the action of $2 \in \SS$ on $\pichar_t$. In particular,
            \begin{equation*}
                \pichar_t^2 = 2\eta^{\chrHeight-t} \cdot \pichar = 0 \cdot \pichar = \pichar^0 = 1
            \end{equation*}
            whenever $t < \chrHeight$, and therefore $\chi^{\chrHeight-t,\HKR}_{\rho_{\pichar,k}}$ sends any 2-divisible connected component to the connected component of $1 \in \En[t](\K_t)\units$. It can still admit a non-trivial $\ZZ/2^k$-action.
        \end{remark}

        \begin{remark}
            In particular, for $k=1$, 
            \begin{equation*}
                \chi^{\chrHeight-t,\HKR}_{\rho_{\pichar,1}} \colon \bigsqcup_{(\ZZ/2)^{\chrHeight-t}} \B\ZZ/2 \to \En[t](K_t)
            \end{equation*}
            is the map that 
            \begin{enumerate}
                \item on a connected component $(x_1,\dots, x_{\chrHeight-t}) \neq (0,\dots,0) \in (\ZZ/2)^{\chrHeight-t}$ is $\omega_t$ with the trivial $\ZZ/2$-action.
                \item on the connected component $(0,\dots,0)$ is $1 \simeq \omega_t^2$ in $\En[t](K_t)\units$, with the cyclic $\ZZ/2$-action.
            \end{enumerate}
        \end{remark}

        \begin{lemma}\label{lem:representation-is-trivial-iff-character}
            Let $\pichar \in \pinD[\chrHeight]$. Then $\rho_{\pichar,k} \colon \B\ZZ/2^k \to \En(K)\units$ is nullhomotopic if and only if there exists $0 \le t \le \chrHeight$ such that 
            \begin{equation*}
                \chi^{\chrHeight-t,\HKR}_{\rho_{\pichar,k}} \colon \L^{\chrHeight-t}\B\ZZ/2^k \to (C^{\chrHeight}_t)\units \to \En[t](K_t)\units
            \end{equation*}
            is null, where $C^{\chrHeight}_t \to \En[t](K_t)$ is a geometric point.
        \end{lemma}

        \begin{proof}
            The \quotes{only if} part is obvious. 
            Assume that $\chi^{\chrHeight-t, \HKR}_{\rho_{\pichar,k}}$ is null. Therefore, the $t$-fold character
            \begin{equation*}
                \chi^{t, \HKR}_{\chi^{\chrHeight-t, \HKR}_{\rho_{\pichar,k}}} \colon \L^{\chrHeight}\B\ZZ/2^k \to C^t_0(K_t)
            \end{equation*}
            is the constant map choosing $1 \in C^t_0(K_t)$.
            By \cref{lem:HKR-vs-twice-HKR} the following diagram is commutative
            \begin{equation*}
                \begin{tikzcd}
                    {\En(K)^{\B\ZZ/2^k}} & {C^{\chrHeight}_t(K)^{\L^{\chrHeight-t}\B\ZZ/2^k}} & {\En[t](K_t)^{\L^{\chrHeight-t}\B\ZZ/2^k}} \\
                    {C^{\chrHeight}_0(K)^{\L^{\chrHeight}\B\ZZ/2^k}} && {C^t_0(K_t)^{\L^{\chrHeight}\B\ZZ/2^k}.}
                    \arrow["{\chi^{\chrHeight-t,\HKR}}", from=1-1, to=1-2]
                    \arrow["{\chi^{\chrHeight,\HKR}}", from=1-1, to=2-1]
                    \arrow[from=1-2, to=1-3]
                    \arrow["{\chi^{t,\HKR}}", from=1-3, to=2-3]
                    \arrow[from=2-1, to=2-3]
                \end{tikzcd}
            \end{equation*}

            Combining with previous part, the composition
            \begin{equation*}
                \L^{\chrHeight}\B\ZZ/2^k \xto{\chi^{\chrHeight,\HKR}_{\rho_{\pichar,k}}} C^{\chrHeight}_0(K) \to C^t_0(K_t)
            \end{equation*}
            is the constant map choosing $1$.

            The character $\chi^{\chrHeight, \HKR}_{\rho_{\pichar,k}} \in C^{\chrHeight}_0(K)^{\L^{\chrHeight}\B\ZZ/2^k}$ is the character of the $\ZZ/2^k$-power operation for $G = e$, applied to $\omega(\pichar)$, as in \cite[Theorem 9.1]{Barthel-Stapleton-2017-power-operations}. Therefore, by the formula for the total power operation (appearing right before \cite[Proposition 5.5]{Barthel-Stapleton-2017-power-operations}), it lands in $\ZZ^{\L^{\chrHeight}\B\ZZ/2^k}$. In particular, as it is constant after pre-composition with $C^{\chrHeight}_0(K) \to C^t_0(K_t)$, it is the constant map choosing $1$.

            As $\ZZ/2^k$ is an $\En$-good group (\cite[Proposition~7.2]{Hopkins-Kuhn-Ravanel-2000-HKR}), the character map
            \begin{equation*}
                \chi^{\chrHeight,\HKR} \colon \En(K)^{\B\ZZ/2^k} \to C^{\chrHeight}_0(K)^{\L^{\chrHeight}\B\ZZ/2^k}
            \end{equation*}
            is injective on $\pi_0$, therefore $\rho_{\pichar,k}$ is the constant map choosing $1 \in \En(K)$ as needed.
        \end{proof}


