        \begin{corollary}\label{cor:representation-is-null-for-n>=4}
            Let $\chrHeight \ge 4$ and $\pichar \in \pinD[\chrHeight]$. Then for any $k$, $\rho_{\pichar,k}$ is nullhomotopic.
        \end{corollary}

        \begin{proof}
            We use the criterion of \cref{lem:representation-is-trivial-iff-character} with $t = \chrHeight-4$. This now follows by \cref{cor:character-of-alpha}, since $\pichar_{t} = \eta^{4} \cdot \pichar = 1$.
        \end{proof}

        Recall the following fact from \cite{CSY-teleambi}:
        \begin{lemma}[{\cite[Lemma 5.3.3]{CSY-teleambi}}]\label{lem:cardinality-of-BZ/2}
            In $\ModEn$ at $p=2$, the cardinality of $\B\ZZ/2$ is
            \begin{equation*}
                |\B \ZZ/2| = 2^{\chrHeight-1}.
            \end{equation*}
        \end{lemma}

        We also need the following simple computation:

        \begin{lemma}\label{lem:integral-of-(-1)^2}
            Let $\chrHeight \ge 0$. Then, in $\ModEn$
            \begin{equation*}
                \int_{\B\ZZ/2} (-1)^2 = -2^{\chrHeight-1}+1.
            \end{equation*}
        \end{lemma}
        \begin{proof}
            The map 
            \begin{equation*}
                \begin{split}
                    \pi_0 \En & \to \pi_0 \En \\
                    x & \mapsto 2\int_{\B\Cn[2]}x^2-x^2
                \end{split}
            \end{equation*}
            is simply seen to be additive, and at $1$ it is equal to $2|\B\ZZ/2|-1 = 2^\chrHeight-1$. Therefore 
            \begin{equation*}
                \int_{\B\ZZ/2}(-1)^2 = \frac{1}{2}(2\int_{\B\ZZ/2}(-1)^2 - (-1)^2) + \frac{(-1)^2}{2} = -2^{\chrHeight-1}+1.
            \end{equation*}
        \end{proof}

        \begin{corollary}\label{cor:no-truncated-units-for-n>=4}
            Let $\chrHeight \ge 4$. Then $-1\in \pi_0 \En\units$ is not a truncated unit.  
        \end{corollary}

        \begin{proof}
            Assume otherwise, then there exists $\chrHeight \ge 4$ and $\pichar \in \pinD[\chrHeight]$ that maps to $-1\in \pi_0 \En\units$ under $\omega$. Therefore the map 
            \begin{equation*}
                \rho_{\pichar,1} \colon \B\ZZ/2 \into \MM \xto{\pichar} \In \to \En\units \to \En
            \end{equation*}
            is the map that chooses $(-1)^2$. By \cref{cor:representation-is-null-for-n>=4} this map is nullhomotopic, and therefore, by \cref{lem:cardinality-of-BZ/2} 
            \begin{equation*}
                \int_{\B\ZZ/2}(-1)^2 = |\B\ZZ/2| = 2^{\chrHeight-1}.
            \end{equation*}
            On the other hand, by \cref{lem:integral-of-(-1)^2},
            \begin{equation*}
                \int_{\B\ZZ/2}(-1)^2 = -2^{\chrHeight-1} + 1,
            \end{equation*}
            in contradiction.
        \end{proof}

        Finally, we show:

        \begin{lemma}\label{lem:-1-truncated-unit-for-n<=3}
            Let $\chrHeight \le 3$. Then $-1\in \pi_0 \En \units$ is a truncated unit. 
        \end{lemma}

        \begin{proof}
            For $\chrHeight=0$ the claim is trivial. 

            Note that for $1 \le \chrHeight \le 3$, the group $\pinD[\chrHeight]$ is cyclic and $2$-power torsion. Therefore, the claim is equivalent to saying that the generator of $\pinD[\chrHeight]$ is sent to $(-1)\in \pi_0 \En\units$.

            We prove the claim by induction on $\chrHeight$.
            Assume the claim is true for $\chrHeight$ and that $\chrHeight+1 \le 3$. 
            Let $\pichar \in \pinD$ be the generator (i.e.\ $\hat{\eta}$, $\hat{\eta^2}$, $\hat{\nu}$ for $\chrHeight=0,1,2$ respectively). Note that, $\eta \cdot \pichar$ is $(-1)\in \pinD[0] = \QQ/\ZZ$, when $\chrHeight = 0$, and is the generator of $\pinD[\chrHeight]$ when $\chrHeight > 0$.
            In both cases, by it being $-1$ or by the induction hypothesis, $\eta \cdot \pichar$ is sent to $(-1) \in \pi_0 \En\units$.

            Consider the decategorification map
            \begin{equation*}
                \de \colon ((\ModEn)\dblspace)^{\B\ZZ/2} \to \KTnp(\En)^{\B\ZZ/2}\to \Enp(L)^{\B\ZZ/2}.
            \end{equation*}
            Then, by \cref{lem:spherical-roots-of-unity-Nullstellensatz-shift}, it sends the representation $\En{}[\rho_{\pichar,1}]$ to 
            \begin{equation*}
                \rho_{\pichar,1} \simeq \de(\En{}[\rho_{\pichar,1}]) \colon \B\ZZ/2 \into \MM \xto{\pichar} \Inplus \to \Enp(L)\units \to \Enp(L).
            \end{equation*}
            By \cref{lem:integral-Enp-to-En} we get 
            \begin{equation*}
                \int_{\L\B\ZZ/2}^{\En}\chi_{\En{}[\rho_{\pichar,1}]}=\dim(\colim_{\B\ZZ/2} \En{}[\rho_{\pichar,1}])=\int_{\B\ZZ/2}^{\Enp} \rho_{\pichar,1}.
            \end{equation*}
            By our assumption, \cref{cor:character-of-alpha} and \cref{lem:integral-of-(-1)^2}:
            \begin{equation*}
                \int_{\L\B\ZZ/2}^{\En}\chi_{\rho_{\pichar,1}}= \int_{\B\ZZ/2}^{\En}(-1)^2-|\B\ZZ/2|_{\En}= -2^{\chrHeight-1}+1-2^{\chrHeight-1}=-2^{n}+1,
            \end{equation*}
            which by \cref{lem:integral-of-(-1)^2} and \cref{lem:cardinality-of-BZ/2}, is euqal to $\int_{\B\ZZ/2}^{\Enp} (-1)^2$ and not to $\int_{\B\ZZ/2}^{\Enp} 1^2=|\B\ZZ/2|_{\Enp}$.
        \end{proof}

        We summarize the discussion about truncated units, specifically \cref{cor:no-truncated-units-for-n>=4} and \cref{lem:-1-truncated-unit-for-n<=3}:
        \begin{proposition}\label{prop:truncated-units}
            Let $p$ be a prime and $\chrHeight \ge 0$. Then
            \begin{enumerate}
                \item If $p > 2$ or $\chrHeight \ge 4$ then there are no non-trivial truncated units in $\En\units$.
                \item If $p=2$ and $\chrHeight \le 3$ then $\pm 1$ are exactly the truncated units in $\En\units$.
            \end{enumerate}
        \end{proposition}


        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        \subsubsection{The $\TT$-action and the braiding character}
        \label{subsubsec:T-action-chromatic}

        We now combine the previous results to show that the reduced $\B\ZZ/p^k$-action on the monoidal dimensions is trivial in our cases of interest. We then leverage this to compute the braiding character at all primes and heights.

        \begin{proposition}\label{prop:chromatic-T-action-trivial}
            Let $\pichar \in \pinD$. Then the action of $\ZZ/p^k \subseteq\TT$ on the dimension of $\En\shift{1} \in \Gr^{\pichar}_\ZZ\ModEn$ is trivial.  
        \end{proposition}

        \begin{proof}
            Assume first that $p$ is odd or $\chrHeight \ge 4$. By \cref{prop:truncated-units}(1), the map 
            \begin{equation*}
                \rho_{\pichar,k} \colon \B\ZZ/p^k \to \SS \xto{\pichar} \Inplus \to \Enp\units
            \end{equation*}
            is nullhomtopic, and therefore $\En{}[\rho_{\pichar,k}]$ is mapped, under the decategorification map,
            \begin{equation*}
                \de \colon ((\ModEn)\dblspace)^{\B\ZZ/2^k} \to \Enp(L)^{\B\ZZ/2^k}
            \end{equation*}
           to a constant map choosing $1$. 
           By \cref{cor:commutativity-of-character-diagram-suspension-In}, using that the map $\En^{\L\B\ZZ/2^k}\to \En(K)^{\L\B\ZZ/2^k}$ is injective on $\pi_0$, the character of $\En{}[\rho_{\pichar,k}]$ is the constant map choosing 1. 
           But by \cref{lem:character-of-Tm}, this character, on a connected component of an element different than $0$, is the $\B\ZZ/p^k$ action on $\dim(\En\shift{1})$ coming from the $\TT$ action.

           Assume now that $p = 2$ and $\chrHeight \le 3$. Then the same argument, shows that the character of $\En{}[\rho_{\pichar,k}]$ agrees with the character of $(\Sigma \En)^{\otimes 2^k} \in (\ModEn)^{\B\ZZ/2^k}\textit{}$. The claim now follows from \cref{cor:no-action-on-dim-En}.   
        \end{proof}

        \begin{corollary}\label{cor:chromatic-T-action-zeta-trivial}
            Let 
            \begin{equation*}
                \zeta \colon \pinD \to\Sigma^2\In\to  \Mod_{\ModEn}
            \end{equation*}
            as in \cref{def:zeta}. Then the restricted $\ZZ/p^k$-action on the dimension of $\En\shift{\pichar} \in \ModEn{}[\omega^{(0)}_{\SS}]$ is trivial for all $\pichar \in\pinD$.
        \end{corollary}

        \begin{proof}
            There is a symmetric monoidal functor $\Gr^{\pichar}_{\ZZ} \ModEn \to \ModEn{}[\omega^{(0)}_{\SS}]$, sending $\En\shift{1}$ to $\En\shift{\pichar}$.
        \end{proof}


        \begin{corollary}\label{cor:T-action-trivial-in-zeta}
            Let $V\in (\ModEn{}[\omega^{(0)}_{\SS}])\dbl$. Then the restricted $\ZZ/p^k$-action on $\dim(V)$ is trivial. 
        \end{corollary}

        \begin{proof}        
            Write $V$ as $V = \bigoplus_{\pichar \in \pinD} V_{\pichar}\shift{\pichar}$. 
            The $\ZZ/p^k$-action on $V$ can be understood degree-wise, i.e.\ in $\THH(\ModEn{}[\omega^{(0)}_{\SS}])^{\B\ZZ/p^k} = \ounit[\pinD]^{\B\ZZ/p^k}$. Therefore, it suffices to show that the $\ZZ/p^k$-action on $\dim(V_{\pichar}\shift{\pichar}) = \dim(V_{\pichar}) \cdot \dim(\En\shift{\pichar})$ is trivial. This follows by \cref{cor:no-action-on-dim-En} and \cref{cor:chromatic-T-action-zeta-trivial}.
        \end{proof}

        \begin{corollary}\label{cor:T-action-is-trivial-in-Z-graded}
            Let $V\in \Gr^{\pichar}_{\ZZ}(\ModEn)\dbl$. Then the restricted $\ZZ/p^k$-action on $\dim(V)$ is trivial. 
        \end{corollary}
        \begin{proof}
            The symmetric monoidal map $\Gr^{\pichar}_{\ZZ} \ModEn \to \ModEn{}[\omega^{(0)}_{\SS}]$ sends $V$ to a dualizable object, and the dimension to the dimension. As both categories share unit, this follows from \cref{cor:T-action-trivial-in-zeta}.
        \end{proof}

        Putting everything together, from \cref{thm:braiding-depends-only-on-dim}, \cref{cor:T-action-is-trivial-in-Z-graded} and \cref{prop:truncated-units},  we get 

        \begin{theorem}\label{thm:chromatic-braiding-character}
            Let $\pichar \in \pinD$. Then
            \begin{enumerate}
                \item If $p$ is odd, or $n\ge 3$, or $p = n = 2$ and $\pichar$ is 2-divisible, then the braiding character of $\Gr^{\pichar}_{\ZZ} \ModEn$ is the braiding character of $\En \in \ModEn$.
                \item If $p=2$, $n \le 2$ and $\pichar$ is not 2-divisible, then the the braiding character of $\Gr^{\pichar}_{\ZZ} \ModEn$ is the braiding character of $\Sigma\En\in\ModEn$.
            \end{enumerate}
        \end{theorem}        

        % \begin{remark}
        %      Opening up some definition one can see that a variant of the braiding character of the form $\L\SS_p^{\B\Zp} \to \ounit[t^\pm]$ which comes from taking free loop after the group completion determines the symmetric monoidal structure of $\Gr_\ZZ(\ModEn)$. We call this the spherical braiding character. By \cref{cor:graded-trivial-iff-picard} it does so in the following way: the symmetric monoidal structure on $\Gr^{\pichar}_{\ZZ} \ModEn$ is equivalent to the day convolution if and only if there exists $V\in \ModEn$ such that $V\shift{1}\in \Gr_\ZZ(\ModEn)$ has the same spherical braiding character as $\En$ or as $\Sigma\En$. We see that \cref{thm:chromatic-braiding-character} says that after pre-composing to $\L_p(\MM_p) \to \L\SS_p^{\B\Zp}$ this is indeed the case. One can also identify the above map and show it is equivalent to $\colim_k \SS^{\B\ZZ/p^k} \to \SS^{\B\Zp}$.  
